P.entries["quest:2159"] = {n="多兰纳尔的货物",s="旅人们离开幽影谷时，带着一包要送往多兰纳尔的草药。伯萨努斯正忙于德鲁伊的事务，便请他们将草药带往南方，这也成了他们首次走出这片安宁林地的旅程。",h="旅人们离开幽影谷时，带着一包要送往多兰纳尔的草药。伯萨努斯正忙于德鲁伊的事务，便请他们将草药带往南方，这也成了他们首次走出这片安宁林地的旅程。",kw={"送货","多兰纳尔","多兰纳尔的货物","草药","旅店老板凯达米尔","暗夜精灵","伯萨努斯","幽影谷","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你知道伯萨努斯正与幽影谷的德鲁伊一起忙碌，处理泰达希尔枝干间那些塞纳里奥议会所关切的精神职责与自然失衡问题。",["profession:Herbalism"]="身为草药师，你知道幽影谷土壤中生长的未经加工的草药，对多兰纳尔的治疗者、厨师和看护者有多么重要。",["race:NightElf"]="身为暗夜精灵，这次送货标志着你离开奥达希尔庇护下的摇篮，开始肩负起守护泰达希尔的更广泛责任。"},sec={{t="幽影谷的信使",b="伯萨努斯请从幽影谷南下的旅人沿着林间小径，捎上一捆刚采集的草药。他正与照料这片林地的德鲁伊一起处理紧急事务，无法亲自离开去跑这一趟。年轻的冒险者准备离开训练场，前往泰达希尔更广阔的天地时，也将这捆草药带向了南方。"},{t="通往多兰纳尔的路",b="从幽影谷向南延伸的道路通往多兰纳尔，那是泰达希尔巨大枝干上的一处主要暗夜精灵聚居地。旅店老板凯达米尔负责接待漫游者、哨兵和德鲁伊，为他们提供休息之所和补给。他收到伯萨努斯托人送来的草药后，便劝年轻的冒险者先让心灵与精神得到休憩，再去面对世界之树上蔓延的腐化。"}},faq={{q="伯萨努斯是谁？",a="伯萨努斯是一名暗夜精灵，住在泰达希尔的新手林地幽影谷。他与当地的德鲁伊共事，并请离开林地的旅人替他将物资带往南方。",al={"伯萨努斯","谁提供多兰纳尔的货物任务","任务给予者伯萨努斯"}},{q="伯萨努斯为什么不能亲自送草药？",a="伯萨努斯忙于和幽影谷的德鲁伊处理紧急事务，只能留在这片安宁的山谷中，因此要靠路过的冒险者将草药带往南方。",al={"伯萨努斯为什么需要帮助","伯萨努斯为什么不能去"}},{q="包裹里装着什么？",a="包裹里装着在幽影谷采集的草药，供多兰纳尔的旅店使用。",al={"多兰纳尔的货物包裹内容","草药是什么"}},{q="旅店老板凯达米尔是谁？",a="旅店老板凯达米尔经营着多兰纳尔的旅店，接待旅人，为他们提供住宿和炉石。他还负责协调与泰达希尔各地其他聚居地之间的贸易及物资交换。",al={"凯达米尔","多兰纳尔旅店老板","谁接收草药"}},{q="多兰纳尔位于哪里？",a="多兰纳尔位于幽影谷南方。从林地出口出发，沿着大路就能直达镇中心。",al={"多兰纳尔在哪里","多兰纳尔位置","前往多兰纳尔的路线"}},{q="这次送货为什么对年轻的冒险者很重要？",a="这次送货让年轻的冒险者接触到幽影谷之外的世界，并鼓励他们踏上旅途，找到多兰纳尔的旅店、训练师和提供各类服务的人。",al={"送货的意义","为什么送草药"}}},fp="17,164,26.324.0,20.373.0,19.181.0,48.153.0,27.78.0,26.190.0,26.115.0,53.126.0"}
P.entries["quest:2160"] = {n="塔诺克的补给品",s="汉兹·跳链有一批要交给塔诺克·霜锤的旅店补给品，但穴居人让山间小径变得危机四伏。他请你把箱子从寒脊山谷送到卡拉诺斯的雷酒酿制厂。",h="汉兹·跳链有一批要交给塔诺克·霜锤的旅店补给品，但穴居人让山间小径变得危机四伏。他请你把箱子从寒脊山谷送到卡拉诺斯的雷酒酿制厂。",kw={"安威玛尔","寒脊山小径","汉兹·跳链","卡拉诺斯","塔诺克的补给品","塔诺克·霜锤","雷酒","穴居人"},ang={["faction:Alliance"]="身为联盟的一员，恢复偏远哨站之间的贸易，有助于让铁炉堡的内陆补给线在穴居人的侵扰下继续运转。",["race:Dwarf"]="身为矮人，将补给品从安威玛尔送往卡拉诺斯，会让你走出受到庇护的山谷，为铁炉堡效力。",["race:Gnome"]="身为侏儒，帮助汉兹·跳链，展现了诺莫瑞根流亡者与丹莫罗收留他们的矮人之间的合作。"},sec={{t="遭到封锁的山谷",b="穴居人占据了寒脊山小径，让离开寒脊山谷的道路变得危险。巡山人忙于守卫定居点和防御工事，人手不足，护送补给的任务可能因此耽搁数日。这箱旅店补给品无法安全运出去。"},{t="双手与旅店老板的助手",b="汉兹·跳链是一位在小径入口等候的侏儒工匠，但他无法独自安全地运送这箱物资。你可以把补给品送给塔诺克·霜锤，他是卡拉诺斯雷酒旅店的助手。"},{t="卡拉诺斯温暖的炉火",b="塔诺克·霜锤在卡拉诺斯接收了补给品。他说，自从穴居人阻断交通，安威玛尔就很少有消息传来。如果没有这次运送，这两个与外界隔绝的矮人聚居地之间的通信和贸易仍难以维系。"}},faq={{q="汉兹·跳链是谁？",a="汉兹·跳链是一位侏儒工匠，在寒脊山谷的寒脊山小径入口等候。他请旅人把货物送到卡拉诺斯，因为他无法独自安全地穿过小径。",al={"汉兹·跳链","任务给予者","谁给予塔诺克的补给品任务"}},{q="塔诺克·霜锤是谁？",a="塔诺克·霜锤是卡拉诺斯雷酒酿制厂的助手。他负责接收从安威玛尔等地送来的补给品。",al={"塔诺克","塔诺克·霜锤","卡拉诺斯旅店老板助手"}},{q="为什么汉兹不能亲自运送补给品？",a="穴居人占据了寒脊山谷与卡拉诺斯之间的小径，让旅途变得危险。巡山人也因分散守卫各处定居点和防御工事而人手不足，护送任务因此延误。",al={"汉兹为什么不能亲自运送","为什么需要冒险者","小径为什么危险"}},{q="卡拉诺斯的旅店在哪里？",a="雷酒酿制厂位于卡拉诺斯中央，就在向东通往铁炉堡的大路旁。塔诺克·霜锤就在里面。",al={"塔诺克在哪里","雷酒酿制厂位置","卡拉诺斯旅店位置"}},{q="一箱旅店补给品里装着什么？",a="箱子里装着在安威玛尔筹集的酒馆用品和给养，要送往卡拉诺斯的雷酒旅店。",al={"箱子里有什么","一箱旅店补给品"}},{q="安威玛尔与卡拉诺斯之间的通信为什么中断了？",a="来自地下隧道的穴居人占据了寒脊山小径。它们阻碍了寒脊山谷与丹莫罗其他地区之间的步行往来和定期通信。",al={"安威玛尔为什么消息稀少","小径穴居人问题"}}},fx={["6d15a4f4"]={q="汉兹·跳链为什么想把补给送到卡拉诺斯？",a="汉兹·跳链答应为卡拉诺斯旅店的助手塔诺克·霜锤送去急需的补给，但穴居人的袭击阻断了寒脊山谷出口处的山道。常规货运被困在途中，巡山人的护送队还要几天才能赶到，塔诺克只能一边等待，一边为日渐短缺的物资发愁。汉兹想兑现送货的承诺，确保生意兴隆的雷酒酿制厂和旅店有充足的存货，招待旅途劳顿的客人。",al={"为什么给塔诺克送补给","汉兹·跳链动机","为什么运送一箱旅店补给品"}}},fp="18,195,18.238.0,35.206.0,30.232.0,28.192.0,26.136.0,45.193.0,37.129.0,41.104.0,59.178.0"}
P.entries["quest:2161"] = {n="苦工的重担",s="乌克尔等在试炼谷外的小路上，带着一批自己无力运回家的货物。红色峡谷中的新兵拒收他的补给，如今他只好请过路的旅人将它们送回剃刀岭。",h="乌克尔等在试炼谷外的小路上，带着一批自己无力运回家的货物。红色峡谷中的新兵拒收他的补给，如今他只好请过路的旅人将它们送回剃刀岭。",kw={"杜隆塔尔","食物","旅店老板格罗斯克","苦工","剃刀岭","补给","乌克尔","试炼谷"},ang={["faction:Horde"]="你离开试炼场，前往剃刀岭，那里是部落在杜隆塔尔南部的防御与后勤枢纽。",["race:Orc"]="兽人文化崇尚力量与勇气，因此像乌克尔这样的苦工处于社会最底层。帮他运送补给，便能看出卑微的劳作如何维系着杜隆塔尔这个新生国度的运转。"},sec={{t="送错的补给",b="乌克尔从剃刀岭出发，为在红色峡谷中受训的新兵运送补给。他以为他们需要这些食物，却被监工赶了回来。监工严格限制补给，因为他们相信，微薄的口粮能让年轻的部落战士学会纪律，磨炼耐力。旅店老板格罗斯克后来解释说，这种艰苦也是训练的一部分。"},{t="赤红荒野的危机",b="乌克尔抵达了山口，却害怕踏上穿越杜隆塔尔的归途。蝎子、毒蜘蛛和四处游荡的野猪出没在岩石遍布的小路上。他没有武器和护甲，也缺少兽人步兵应有的斗志。他等在路旁，请离开试炼场的旅人将沉重的补给送回剃刀岭的旅店。"}},faq={{q="乌克尔是谁？",a="乌克尔是个好心却胆小的兽人苦工，正等在离开试炼谷的路旁。他从剃刀岭出发送补给，随后才发现，自己太害怕当地的野兽，不敢独自踏上归途。",al={"乌克尔","路上的苦工是谁","试炼谷附近的苦工"}},{q="试炼谷的教官为什么不要这些食物？",a="监工认为，初来乍到的新兵必须学会纪律。旅店老板格罗斯克解释说，教官让受训者饿着肚子，以此考验他们的毅力，磨炼他们的意志，所以乌克尔送来的补给并不受欢迎。",al={"为什么拒收食物","乌克尔为什么运送食物","旅店老板格罗斯克 挨饿"}},{q="这批补给要送到哪里？",a="沿杜隆塔尔的大路向北，将补给运到剃刀岭，再交给镇上酒馆里的旅店老板格罗斯克。",al={"剃刀岭在哪里","食物交给谁","乌克尔的货物送到哪里"}},{q="这段旅程对苦工来说有什么危险？",a="领地意识极强的蝎子、有毒的爬行蜘蛛和野猪在杜隆塔尔遍布岩石的荒野上游荡。乌克尔只是个没有护甲、未经训练的劳工，而训练有素的新兵能够对付这些害兽。",al={"乌克尔为什么害怕","杜隆塔尔道路的危险"}},{q="苦工在部落中承担什么职责？",a="苦工处于兽人社会的最底层，负责搬运补给、砍伐木材和修筑防御工事等杂役。步兵和勇士赢得赞誉与荣耀，而苦工虽然维持着聚居地的粮食供应和日常运转，却常常被忽视。",al={"兽人苦工的背景故事","苦工的地位","苦工是什么"}},{q="旅店老板格罗斯克是谁？",a="旅店老板格罗斯克经营着剃刀岭的旅店，负责镇上的住宿和补给。他为往来的战士提供食物、饮品和温暖的炉火，也提醒新兵在踏入更广阔的世界之前先好好休息。",al={"旅店老板格罗斯克","格罗斯克 剃刀岭","剃刀岭旅店老板"}}},fp="15,178,20.329.0,23.361.0,12.189.0,62.212.0,36.136.0,44.168.0,39.264.0,23.197.0"}
P.entries["quest:217"] = {n="保卫国王的领土",s="“保卫国王领地”的任务最终将演变成对洛克莫丹穴居人入侵者首领的直接打击。矮人侦察兵追踪到了这起暴力入侵事件的源头，发现碎石怪之谷深处盘踞着格拉姆格酋长及其残暴的保镖。拉格弗斯上尉委派勇敢的联盟冒险者去击杀这位酋长，以粉碎穴居人的士气并收复王国的南部边境。",h="“保卫国王领地”的任务最终将演变成对洛克莫丹穴居人入侵者首领的直接打击。矮人侦察兵追踪到了这起暴力入侵事件的源头，发现碎石怪之谷深处盘踞着格拉姆格酋长及其残暴的保镖。拉格弗斯上尉委派勇敢的联盟冒险者去击杀这位酋长，以粉碎...",kw={"布劳勒","格纳舍","格拉姆格","国王领地","洛克莫丹","拉格弗斯","碎石怪","穴居人"},ang={["faction:Alliance"]="保卫洛克莫丹可以维护铁炉堡与东部边境之间至关重要的陆路连接，确保所有联盟部队的补给线安全。",["race:Dwarf"]="对于矮人而言，将穴居人从卡兹莫丹古老的土地上赶走是保卫家园与荣誉的问题，确保山堡不被地下灾祸所玷污。"},sec={{t="斩首虫群",b="在洛克莫丹南部肆虐的穴居人威胁已经不仅仅是随机的地下爬行生物骚扰了。拉格弗斯上尉的侦察兵发现，碎石怪穴居人在一个名叫格拉姆格的酋长的粗暴指挥下行动。与通常四散的掠夺者不同，这群穴居人展现出了协同一致的侵略性，如果不加以遏制，它们可能会践踏国王的领地。通过深入它们的巢穴，将格拉姆格及其私人打手一并处决，矮人守卫希望能够瓦解这群怪物的凝聚力并扭转局势。"},{t="深入碎石怪巢穴",b="格拉姆格盘踞在碎石怪之谷东南部悬崖内的一个阴暗洞穴中。在它最信任的打手——格纳舍和布劳勒——的簇拥下，这位酋长对孤身冒险者构成了巨大的挑战。击杀这个核心集团将迫使剩余的穴居人陷入混乱，从而为处境艰难的登山者们争取到宝贵的机会，以便他们能够加固道路并将这些野兽赶回黑暗的深渊。"}},faq={{q="谁是格拉姆格？",a="格拉姆格是那名邪恶的穴居人酋长，他正集结洛克莫丹南部的碎石怪穴居人发动攻击。矮人侦察兵确认他就是骚扰山谷的组织化袭击背后的主谋，他的身边时刻带着两名强大的保镖：格纳舍和布劳勒。",al={"格拉姆格背景故事","穴居人首领是谁","格拉姆格酋长"}},{q="格拉姆格和他的守卫在哪里？",a="格拉姆格、格纳舍和布劳勒都在洛克莫丹碎石怪之谷东南边缘的一个洞穴中安营扎寨。他们共同居住在洞穴深处。",al={"格拉姆格位置","格拉姆格在哪里","格拉姆格怎么找"}},{q="谁是拉格弗斯上尉？",a="拉格弗斯上尉是驻扎在洛克莫丹南部岗哨的矮人军官。他负责监督针对穴居人入侵的防御行动，并发布保护国王领地领土完整的命令。",al={"拉格弗斯","拉格弗斯上尉职责","谁发布保卫国王领地的任务"}},{q="为什么格拉姆格的保镖也必须被击杀？",a="格纳舍和布劳勒是格拉姆格的私人打手，从不离他左右。要消灭这位酋长并彻底粉碎穴居人攻势的领导核心，必须将这两名强大的守卫与他们的头领一起击败。",al={"为什么击杀格纳舍和布劳勒","格纳舍和布劳勒","格拉姆格保镖"}},{q="格拉姆格被消灭后会发生什么？",a="击杀格拉姆格将为洛克莫丹带来至关重要的缓解。失去了指挥突袭的酋长，碎石怪穴居人将失去组织性，这将使当地的矮人民兵有机会守住边境，并将这些野兽赶回地下。",al={"击杀格拉姆格的结果","格拉姆格死后穴居人会怎样","洛克莫丹安全了吗"}},{q="为什么穴居人会入侵洛克莫丹？",a="穴居人长期以来一直在卡兹莫丹地下的地穴中滋生。挖掘工作和未封闭的洞穴让它们能够涌上地表，肆意驱逐定居点并攻击国王道路上的旅客。",al={"为什么这里有穴居人","洛克莫丹穴居人入侵","碎石怪穴居人起源"}}},fx={["440a3b53"]={q="拉格弗斯上尉为什么想杀死格劳姆格？",a="拉格弗斯上尉认为，格劳姆格是策动穴居人入侵、威胁洛克莫丹的幕后主使。矮人驻军一直在艰难抵挡从地下蜂拥而来的敌人，拉格弗斯相信，铲除它们的首领，也就是消灭格劳姆格及其精锐护卫，就能挫败它们的攻势，让矮人有机会将它们赶回地下。",al={"拉格弗斯动机","为什么杀格劳姆格","保卫国王的领土目的"}}},fp="30,250,22.286.0,23.351.0,15.197.0,41.112.0,25.194.0,43.148.0,41.255.1,35.209.0"}
P.entries["quest:2178"] = {n="炖陆行鸟",s="在奥伯丁，奥兰达利亚·夜歌愿意与那些为她带来森林陆行鸟肉的猎手分享她的炖陆行鸟食谱。",h="在奥伯丁，奥兰达利亚·夜歌愿意与那些为她带来森林陆行鸟肉的猎手分享她的炖陆行鸟食谱。",kw={"奥兰达利亚·夜歌","奥伯丁","烹饪","黑海岸","炖陆行鸟","森林陆行鸟","陆行鸟肉"},ang={["class:Hunter"]="身为猎人，你可以沿着黑海岸雾气弥漫的小径，练习追踪和猎捕敏捷的foreststriders。",["profession:Cooking"]="身为途经黑海岸的厨师，你可以学习用当地的野生动物烹制炖陆行鸟。",["race:NightElf"]="身为卡利姆多的暗夜精灵，你深知依靠大地生活的价值。炖陆行鸟是奥伯丁沿海居民的日常食物。"},sec={{t="荒野的滋味",b="奥伯丁的沿海居民善于利用周围的野生动物。奥兰达利亚·夜歌有一道独家的炖陆行鸟食谱，用漫步于黑海岸林间的高大森林陆行鸟烹制，丰盛又暖胃。她请你先猎杀这些鸟，带回它们的肉，然后才会传授烹饪方法。"},{t="猎捕森林陆行鸟",b="森林陆行鸟遍布奥伯丁南北两侧的林地与海滩。它们尖喙锋利，脾气暴躁，被激怒时十分危险，但它们的肉能炖出浓郁的美味。把新鲜的肉带给奥兰达利亚，她就会分享自己的食谱。"}},faq={{q="奥兰达利亚·夜歌是谁？",a="奥兰达利亚·夜歌住在黑海岸的奥伯丁。她愿意将自己的炖陆行鸟食谱传授给那些证明了狩猎本领的旅人。",al={"奥兰达利亚","奥兰达利亚·夜歌是谁","奥伯丁炖肉厨师"}},{q="在哪里能找到陆行鸟肉？",a="在黑海岸各处猎杀森林陆行鸟，获取它们的肉。这些不会飞的大鸟在奥伯丁外的海岸和树林间游荡。",al={"陆行鸟肉位置","森林陆行鸟在哪里","如何获取陆行鸟肉"}},{q="这个任务的目的是什么？",a="你要猎杀森林陆行鸟，将五块肉带给奥兰达利亚·夜歌。作为回报，她会教你烹制炖陆行鸟。",al={"为什么要做炖陆行鸟","任务目的","炖陆行鸟任务目标"}},{q="猎捕森林陆行鸟危险吗？",a="森林陆行鸟有锋利的喙和敏捷的双腿，有人靠近时就会变得好斗。狩猎时务必小心。",al={"陆行鸟难杀吗","森林陆行鸟危险程度"}},{q="这个任务会解锁烹饪食谱吗？",a="会。把奥兰达利亚要的肉带给她，她就会传授炖陆行鸟的食谱。",al={"能获得食谱吗","炖陆行鸟食谱","烹饪奖励"}},{q="这个任务在哪里进行？",a="你在奥伯丁接取并交还任务，在黑海岸的荒野中狩猎。",al={"任务区域","炖陆行鸟在哪里"}}},fp="19,120,19.288.0,26.253.0,29.143.0,33.152.0,34.129.0,41.105.0,40.94.0,33.72.0"}
P.entries["quest:218"] = {n="被窃取的日记",s="格瑞林·白须需要找回被盗的日记，才能完成对寒脊山谷巨魔威胁的评估。霜鬃的首领冷酷的格瑞克尼尔将日记带进了巨魔洞穴，让格瑞林失去了大部分侦察记录。",h="格瑞林·白须需要找回被盗的日记，才能完成对寒脊山谷巨魔威胁的评估。霜鬃的首领冷酷的格瑞克尼尔将日记带进了巨魔洞穴，让格瑞林失去了大部分侦察记录。",kw={"寒脊山谷","丹莫罗","霜鬃巨魔要塞","霜鬃巨魔","格瑞林·白须","冷酷的格瑞克尼尔","森内尔·白须","被盗的日记"},ang={["faction:Alliance"]="作为联盟的一员，你协助保卫丹莫罗的新兵山谷，使其免受侵扰。为此，你压制了咄咄逼人的霜鬃部族。",["race:Dwarf"]="作为矮人，你协助保护那些刚刚迈出安威玛尔的年轻新兵。你瓦解了寒脊山谷中霜鬃的指挥力量。",["race:Gnome"]="作为侏儒，你依赖寒脊山谷各处隘口的安全。侏儒难民在安威玛尔避难，并在矮人的领地上重新集结。"},sec={{t="学者遗失的笔记",b="霜鬃巨魔已侵入寒脊山谷，格瑞林·白须的笔记记录着他们的动向。笔记记载了巨魔的习性，以及他们突然变得咄咄逼人的情形。动乱期间，一个高大的巨魔偷走了格瑞林的私人日记，逃进了巢穴深处。日记中有他大部分的侦察记录，因此在找回日记之前，格瑞林无法完成评估。"},{t="迎战冷酷的格瑞克尼尔",b="冷酷的格瑞克尼尔坐镇山谷中巨魔洞穴的深处。他的身上和脸上绘有醒目的图案。击败这个强大的霜鬃巨魔，就能瓦解洞内巨魔眼前的指挥力量，并夺回格瑞林的日记。日记归还后，格瑞林就能完成调查，判定当地的巨魔局势尚可控制，并将报告送给他的兄弟森内尔。"}},faq={{q="谁偷走了格瑞林·白须的日记？",a="冷酷的格瑞克尼尔偷走了格瑞林·白须的日记。这个高大的霜鬃巨魔身上和脸上带有奇怪的图案，潜伏在巨魔洞穴深处。",al={"谁偷了日记","格瑞林的日记在谁手里","偷日记的贼"}},{q="在哪里能找到冷酷的格瑞克尼尔？",a="冷酷的格瑞克尼尔就在寒脊山谷南部的巨魔洞穴中。",al={"格瑞克尼尔在哪里","格瑞克尼尔位置","如何找到格瑞克尼尔"}},{q="日记为什么对格瑞林如此重要？",a="格瑞林的日记记载了他对寒脊山谷巨魔活动的观察和调查结果。他需要找回日记，才能完成给兄弟森内尔的报告。",al={"格瑞林为什么要找回日记","格瑞林的日记里有什么"}},{q="归还日记后会发生什么？",a="你找回日记后，格瑞林便完成了关于寒脊山谷巨魔局势的报告。他请你将调查结果送给卡拉诺斯的兄弟森内尔·白须。",al={"被窃取的日记之后做什么","被窃取的日记后续任务"}},{q="此后，霜鬃巨魔就被赶出寒脊山谷了吗？",a="格瑞林认为，格瑞克尼尔被击败后，寒脊山谷的巨魔局势已得到控制。在丹莫罗更广阔的山间隘口，霜鬃仍然是个威胁。",al={"寒脊山谷的巨魔被击败了吗","寒脊山谷是否已免受巨魔威胁"}},{q="森内尔·白须是谁？",a="森内尔·白须是格瑞林的兄弟，也是一名联盟斥候，驻扎在寒脊山谷之外、卡拉诺斯附近。他收集有关王国所面临威胁的情报。",al={"森内尔是谁","格瑞林的兄弟森内尔"}}},fx={["78f0c4e3"]={q="格瑞林·白须为什么想让你做这件事？",a="格瑞林正在为他的兄弟森内尔编写一份正式报告，说明寒脊山谷面临的霜鬃威胁。没有日记，他就无法完成记录，也无法评估山谷是否安全，当地首领也就得不到有关巨魔活动的重要情报。",al={"格瑞林为什么要日记","格瑞林·白须动机","为什么找回格瑞林的日记"}},beb6a987={q="格瑞林为什么需要你找回他的日记？",a="格瑞林是个观察者，并非前线战士，而他的日记被一个强悍的巨魔蛮兵带进了寒脊山谷的巨魔洞穴深处。他已经见识过你击退山谷中巨魔的本领，因此请你深入洞穴，应对其中的危险。",al={"格瑞林为什么需要我","为什么派冒险者找日记","格瑞林为什么不能自己取日记"}}},fp="18,225,22.372.0,29.364.0,37.154.0,37.87.0,39.145.0,42.180.1,67.172.0,24.160.0"}
P.entries["quest:219"] = {n="失踪人员",s="在赤脊山，基沙恩下士所属的步兵团遭到击溃，他也随之失踪。黑石兽人将他打昏，拖进了一座洞穴要塞。如今，他需要有人护送他返回湖畔镇，让驻军得知那些失踪士兵的下落。",h="在赤脊山，基沙恩下士所属的步兵团遭到击溃，他也随之失踪。黑石兽人将他打昏，拖进了一座洞穴要塞。如今，他需要有人护送他返回湖畔镇，让驻军得知那些失踪士兵的下落。",kw={"黑石兽人","基沙恩下士","护送","基沙恩","湖畔镇","治安官马瑞斯","失踪人员","赤脊山"},ang={["class:Warrior"]="作为一名战士，你在前线抵挡一波又一波黑石袭击者，保护患有脑震荡的基沙恩逃离他们戒备森严的营地。",["faction:Alliance"]="作为一名联盟士兵，每救回一名战士，都对兵力吃紧的湖畔镇驻军至关重要，他们正守卫王国，抵御黑石氏族。"},sec={{t="步兵团覆灭",b="黑石兽人从北方的群峰涌下，让赤脊山愈发危险。镇上的卫兵巡逻队时常遭到伏击，而基沙恩下士的部队损失最为惨重。步兵团寡不敌众，遭到击溃，大多数士兵在袭击中阵亡。基沙恩挨了一记重击，在兽人来得及处决他之前就昏了过去，因此活了下来。他们把他拖进洞穴，关押起来。"},{t="逃离洞穴",b="基沙恩遍体鳞伤，还受了脑震荡，被关押在敌境深处，无法独自跋涉下山。你护送他前往湖畔镇，穿过兽人战帮占据的山脊。治安官马瑞斯一直在追查失踪步兵团的遭遇，同时让湖畔镇做好准备，抵御接下来的袭击。基沙恩平安归来，让他终于松了一口气。"}},faq={{q="基沙恩下士是谁？",a="基沙恩下士是一名驻守赤脊山的联盟步兵。他所属的步兵团在岩石遍布的山丘间巡逻时，被黑石兽人击溃，他随后被拖走。他是目前唯一已知的幸存者。",al={"基沙恩下士","基沙恩是谁","基沙恩的故事"}},{q="基沙恩下士在哪里被俘？",a="基沙恩下士被关押在赤脊山北部丘陵的一处洞穴深处，那里遍布兽人，四周都是敌对的黑石战士。",al={"基沙恩在哪里","基沙恩位置","基沙恩洞穴"}},{q="基沙恩部队里的其他人怎么样了？",a="黑石兽人伏击并击溃了基沙恩所属的步兵团。几乎所有士兵都在最初的交战中丧生。",al={"基沙恩小队","步兵团遭遇了什么","基沙恩的士兵"}},{q="谁派玩家去营救基沙恩？",a="联盟冒险者在囚禁基沙恩下士的洞穴中发现了他，他请求你将他救出去。",al={"谁给予失踪人员任务","任务给予者","在哪里接取失踪人员"}},{q="基沙恩获救后会去哪里？",a="你救出基沙恩后，还需要护送他沿山坡下行，前往湖畔镇。他会在镇上的桥边向治安官马瑞斯报到。",al={"交付失踪人员","基沙恩跑向哪里","基沙恩目的地"}},{q="黑石兽人为什么会出现在赤脊山？",a="黑石氏族从燃烧平原的据点向南推进，进入赤脊山。这个氏族威胁着援军不足的湖畔镇，还伏击王国的巡逻队。",al={"黑石兽人赤脊山","湖畔镇为什么有兽人","黑石入侵"}}},fp="17,238,18.386.0,21.379.0,24.208.0,36.129.0,44.106.0,36.101.0,40.132.0,39.178.0"}
P.entries["quest:22"] = {n="猪肝馅饼",s="血牙野猪的肝馅饼是为西部荒野萨丁农场的萨尔玛·萨丁完成的一项烹饪差事。随着王国的粮仓被强盗洗劫一空，当地农户只能依靠捕猎凶猛的本地野猪来为餐桌增添一道丰盛的佳肴。帮助萨尔玛能在这片凄凉的边境之地，带来一丝难得的舒适和家常般的款待。",h="血牙野猪的肝馅饼是为西部荒野萨丁农场的萨尔玛·萨丁完成的一项烹饪差事。随着王国的粮仓被强盗洗劫一空，当地农户只能依靠捕猎凶猛的本地野猪来为餐桌增添一道丰盛的佳肴。帮助萨尔玛能在这片凄凉的边境之地，带来一丝难得的舒适和家常...",kw={"野猪","烹饪","血牙野猪","肝馅饼","萨丁农场","萨尔玛·萨丁","西部荒野"},ang={["faction:Alliance"]="帮助像萨丁一家这样的农村农户，能直接支持那些在暴风城军队缺席的情况下，仍努力守护王国边境的忠诚人类家庭。",["profession:Cooking"]="萨尔玛的这道菜展现了传统的人类乡村烹饪技艺，使用大蒜、迷迭香和莳萝等园艺香料，将野味内脏提升为一道主食。"},sec={{t="边境的款待",b="西部荒野曾是暴风城肥沃的粮仓，但近年来境况不佳。由于基础设施缺乏维护、强盗横行以及农田荒废，仅存的定居者们生活日益艰难。在萨丁农场，萨尔玛·萨丁不辞辛劳，努力在日益逼近的威胁中守护着家的温馨。制作一份传统的肉馅饼，是那些试图保全生活方式的农户们所能享受到的为数不多的简单奢侈之一。"},{t="西部荒野的野兽",b="西部荒野的平原上到处都是血牙野猪，这种凶猛的野猪以皮糙肉厚和獠牙锋利而闻名。虽然它们对落单的农场工人来说很危险，但对那些与正常贸易隔绝的家庭来说，它们也是重要的肉食来源。萨尔玛的食谱需要仔细处理——加入碎迷迭香、蒜末、莳萝碎和炖肉汁——才能将这些强壮野兽的浓腥内脏变成一道香气四溢的盛宴。"}},faq={{q="谁是萨尔玛·萨丁？",a="萨尔玛·萨丁是一位坚韧的农妇，她和丈夫农夫萨丁住在位于西部荒野中部的农场里。她以擅长家常料理而闻名，尽管面临强盗和野兽的威胁，她依然竭尽全力保持乐观的精神。",al={"萨尔玛·萨丁","谁是萨尔玛","萨丁的妻子"}},{q="萨尔玛为什么需要血牙野猪的肝？",a="萨尔玛正在准备她那著名的鲜美肉馅饼，准备和丈夫一起享用。馅饼皮已经烤好了，调料也准备就绪，只需要当地血牙野猪的肝脏来完成馅料的炖煮。",al={"为什么需要血牙野猪的肝","馅饼的原料","肝馅饼的用途"}},{q="血牙野猪在西部荒野通常出现在哪里？",a="血牙野猪在西部荒野的金色平原和休耕的农田上四处游荡，它们在荒废的田地里翻找食物，并在土路上漫步。",al={"血牙野猪的位置","哪里能找到野猪","血牙野猪肝狩猎"}},{q="血牙野猪对当地农民有危险吗？",a="是的。血牙野猪是一种凶猛的领地型野猪，长有尖锐的獠牙。它们对平原上的牲畜和毫无防备的旅行者构成了重大威胁。",al={"血牙野猪是否具有敌意","西部荒野的野猪危险"}},{q="为什么西部荒野现在的食物如此短缺？",a="由于暴风城缺乏王室支持，加上有组织的强盗频繁劫掠，许多农民被迫背井离乡，使曾经的王国粮仓变成了贫困挣扎的边境之地。",al={"西部荒野饥荒","为什么西部荒野缺乏食物","西部荒野的艰难时期"}},{q="完成这项任务能帮助萨丁农场生存下去吗？",a="虽然这不能解决西部荒野面临的更广泛的危机，但收集新鲜肉类可以直接维持萨丁一家的生计，并为旅行者提供旅途所需的丰盛口粮。",al={"馅饼是否重要","萨丁农场的食物供应"}}},fx={["3baa4b09"]={q="血牙野猪的肝有什么用？",a="萨尔玛·萨丁需要新鲜的血牙野猪的肝，这是她那道拿手的西部荒野肉馅饼最后一份关键食材。她已经备好了调过味的饼皮、切碎的莳萝、大蒜、迷迭香，以及正在慢炖的肉汁，只差肉就能做好这顿家常饭。",al={"血牙野猪的肝有什么用","为什么要血牙野猪的肝","猪肝馅饼食谱"}},ad043644={q="萨尔玛为什么请冒险者帮忙，而不亲自猎杀血牙野猪？",a="萨丁一家正艰难应对西部荒野的困境，萨尔玛忙着操持农庄和厨房。围栏外的野猪四处游荡，凶猛好斗，当地民兵又人手不足，她只能依靠有本事的旅人帮忙弄到鲜肉。",al={"血牙野猪的肝为什么找我","萨尔玛为什么需要我","萨尔玛为什么不狩猎"}}},fp="18,193,20.355.0,23.358.0,21.204.0,36.226.0,48.136.0,45.169.0,44.207.0,56.147.0"}
P.entries["quest:220"] = {n="水之召唤",s="布瑞恩准备的水被送到贫瘠之地东部海岸的水之先知伊斯伦手中，萨满祭司试炼的下一阶段将在那里开始。瓶中装着布瑞恩准备并祝福过的水，用它调制的sapta能让学徒看见银松森林的水之灵。",h="布瑞恩准备的水被送到贫瘠之地东部海岸的水之先知伊斯伦手中，萨满祭司试炼的下一阶段将在那里开始。瓶中装着布瑞恩准备并祝福过的水，用它调制的sapta能让学徒看见银松森林的水之灵。",kw={"布瑞恩","水之召唤","水之先知伊斯伦","灵契","银松森林","贫瘠之地","一瓶最纯净的水","水之灵契","水之图腾"},ang={["class:Shaman"]="身为部落的萨满祭司，你要完成水之召唤仪式，与元素之灵沟通，获得掌管治疗与恢复的水之图腾。",["faction:Horde"]="身为部落的一员，你从卡利姆多的贫瘠之地前往洛丹伦的银松森林，在试炼途中穿越被遗忘者控制的土地。"},sec={{t="重返海岸",b="完成贫瘠之地南部的试炼后，布瑞恩交给萨满祭司学徒一瓶最纯净的水。这些水取自纯净的泉水，并经过布瑞恩的仪式祝圣。学徒带着它返回东部海岸，水之先知伊斯伦在那里守望。这些水将布瑞恩的教导与图腾仪式联系起来。"},{t="sapta的用途",b="水之先知伊斯伦解释说，凡人的双眼很难看见水之灵。要与它们相见，学徒需要饮下一种名为sapta的药剂。布瑞恩的水将作为这种药剂的基底，开启萨满祭司的感知，让其察觉寻常目光无法发现的存在。看见元素之灵只是这段旅程的一部分；它们还将考验学徒。"},{t="渡海前往洛丹伦",b="水之先知伊斯伦派萨满祭司离开卡利姆多，跨海前往幽暗城以南的银松森林。在一座偏僻的神殿旁，学徒必须饮下sapta，直面元素生物。只有这样，萨满祭司才能获得召唤水之图腾的资格。"}},faq={{q="一瓶最纯净的水里装着什么？",a="一瓶最纯净的水里装着取自纯净泉源、经过布瑞恩仪式祝圣的水。它是调制灵契不可或缺的基底，能让萨满祭司与水之灵沟通。",al={"一瓶最纯净的水","布瑞恩的水","布瑞恩给了什么"}},{q="水之先知伊斯伦是谁？",a="水之先知伊斯伦是一位年长的萨满祭司，住在棘齿城以南、贫瘠之地僻静的东南海岸。她指引部落的萨满祭司与水沟通，并寻求获得水之图腾。",al={"水之先知伊斯伦","水之先知伊斯伦是谁","水之先知伊斯伦的故事"}},{q="什么是灵契？",a="灵契是萨满祭司导师调制的一种仪式饮剂。它能改变萨满祭司的感知，使其看见并接触凡人目光无法察觉的元素之灵。",al={"灵契的含义","水之灵契","灵契的作用"}},{q="为什么接下来必须去银松森林？",a="举行这次沟通仪式的神殿位于东部王国幽暗城以南、银松森林的近海水域。那里的元素之灵要求萨满祭司与它们相见，并接受最后的试炼，才能掌握水的力量。",al={"为什么去银松森林","银松森林水之图腾","银松森林的神殿"}},{q="布瑞恩住在哪里？",a="布瑞恩住在贫瘠之地南部一间偏僻的小屋里，位于通往升降梯和千针石林的道路西侧的高处山丘上。",al={"布瑞恩的位置","布瑞恩在哪里","寻找布瑞恩"}},{q="萨满祭司能跳过调制灵契这一步吗？",a="不能。沟通仪式要求萨满祭司的灵魂与不可见的世界相协调。没有灵契开启这条通路，就无法见到神殿中的水之灵，也无法接受它们的挑战。",al={"跳过灵契","是否必须使用灵契","萨满祭司幻视试炼"}}},fp="13,231,19.287.0,24.282.0,23.236.1,40.185.0,23.183.0,16.167.0,46.222.0,22.133.0,39.174.0"}
P.entries["quest:2205"] = {n="军情七处",s="科瑞恩·塞尔留斯从闪金镇派遣新入行的潜行者，带着密封包裹前往暴风城。这趟递送让他们得以面见马迪亚斯·肖尔，他掌管着王室的秘密情报网。",h="科瑞恩·塞尔留斯从闪金镇派遣新入行的潜行者，带着密封包裹前往暴风城。这趟递送让他们得以面见马迪亚斯·肖尔，他掌管着王室的秘密情报网。",kw={"闪金镇","科瑞恩·塞尔留斯","马迪亚斯·肖尔","旧城区","潜行者","寻找军情七处","si:7","暴风城"},ang={["class:Rogue"]="身为潜行者，你加入了暴风城最重要的间谍机构，从街头巷尾的小把戏转向为王室执行侦察任务。",["faction:Alliance"]="身为联盟的一员，在瓦里安·乌瑞恩国王仍然下落不明之时，你依靠SI: 7抵御境内外的威胁，守护王国。"},sec={{t="信使的考验",b="潜行者训练师科瑞恩·塞尔留斯觉得，这些新人看起来不像秘密特工。她交给他们一件送往王都的密封包裹，考验他们作为信使是否可靠。在此过程中，她也在暗中判断，他们是否有潜力成为为王国效力的斥候。"},{t="旧城区紧闭的门后",b="军情七处，全称暴风城的情报机构, 第7处，在暴风城旧城区的东南部开展行动。在这片破旧的城区，马迪亚斯·肖尔统管着王国的秘密行动。他接过包裹，冷淡中带着几分怀疑，随后判断你是否有胆识从事真正的间谍工作。"}},faq={{q="SI:7是什么？",a="军情七处意为暴风城的情报机构, 第7科。马迪亚斯·肖尔在旧城区的总部，领导这个组织为暴风城王国搜集秘密情报、执行秘密行动。",al={"si 7是什么意思","si7是什么","si:7背景故事"}},{q="科瑞恩·塞尔留斯是谁？",a="科瑞恩·塞尔留斯在闪金镇的狮王之傲旅店训练潜行者。她与SI: 7合作，考察当地的新兵，并将有潜力的斥候派往暴风城，去见马迪亚斯·肖尔。",al={"科瑞恩·塞尔留斯","闪金镇潜行者训练师"}},{q="马迪亚斯·肖尔在暴风城的什么地方？",a="马迪亚斯·肖尔位于暴风城旧城区东南部的SI: 7总部楼上，经过城里的潜行者训练师后便能找到。",al={"肖尔在哪里","寻找马迪亚斯·肖尔","马迪亚斯·肖尔位置"}},{q="把包裹交给肖尔后会发生什么？",a="向马迪亚斯·肖尔报到后，他会考验你的潜行者技艺。他派你前往杰罗德码头，从一名迪菲亚码头管理员那里偷取一份货运时间表。",al={"寻找军情七处的后续任务","肖尔想要什么"}},{q="为什么科瑞恩在交付包裹前要嘲讽玩家？",a="军情七处的特工重视能力与敏锐的直觉。科瑞恩·塞尔留斯对新人态度严厉，是为了判断他们的性情，看看他们是否有决心去面见大师 肖尔。",al={"凯瑞恩为什么侮辱我","送奶酪的侮辱"}}},fx={["5aa3ad9f"]={q="科瑞恩·塞尔留斯为什么想把这个包裹送给马迪亚斯·肖尔？",a="科瑞恩正式承诺过，要把这个包裹交给马迪亚斯·肖尔，这是她公务的一部分。她显然不屑于亲自跑这种寻常的送信差事，但派你前去有两个目的：既能履行她对机构的承诺，也能让暴风城的上级检验你初露头角的潜行者本领。",al={"为什么送给马迪亚斯","科瑞恩·塞尔留斯动机","为什么送包裹给si7"}},["6bd14f9c"]={q="科瑞恩为什么派一个未经考验的潜行者去，而不亲自送包裹？",a="科瑞恩驻守在闪金镇，负责物色和指导新人，没什么兴趣为了一点小小的送货差事走回旧城区。把任务交给你这样跃跃欲试的新手，既能省去她奔波的工夫，也能实际考察你是否足够机敏，能够找到暴风城情报机关的总部。",al={"科瑞恩为什么派我","寻找军情七处为什么找我","为什么不亲自送去"}}},fp="14,191,16.247.0,31.284.0,13.180.0,21.181.0,43.140.0,50.148.1,64.186.0"}
P.entries["quest:2206"] = {n="连偷带抢",s="“抓捕与夺取”是军情七处首领马迪亚斯·肖尔派给有潜力的潜行者的卧底任务。任务要求特工潜入杰罗德码头，从迪菲亚潜行者手中窃取船运情报。",h="“抓捕与夺取”是军情七处首领马迪亚斯·肖尔派给有潜力的潜行者的卧底任务。任务要求特工潜入杰罗德码头，从迪菲亚潜行者手中窃取船运情报。",kw={"水晶湖","迪菲亚","码头管理员","闪金镇","杰罗德码头","马迪亚斯·肖尔","船运时间表","军情七处","抓捕与夺取"},ang={["class:Rogue"]="这项任务标志着潜行者正式加入军情七处，通过考验潜行和扒窃本能来赢得认可，并从马迪亚斯·肖尔那里获得一把标志性的匕首。",["faction:Alliance"]="在杰罗德码头拦截迪菲亚的补给链不仅保护了艾尔文森林，还削弱了威胁暴风城周边领土的犯罪集团。"},sec={{t="技艺的考验",b="对于暴风城中一位胸怀大志的特工来说，站在马迪亚斯·肖尔面前便是进入王国秘密情报机构的真正考验。肖尔要求的不是单纯的蛮力，而是精妙的技巧和潜行能力。在不引起王国公开丑闻的情况下悄无声息地解决关键人物并取回重要文件，这是军情七处的核心准则，而这项任务就是新人的试炼场。"},{t="河上的走私者",b="杰罗德码头坐落在艾尔文森林南部的河边，位于闪金镇以南，马科伦农场正东方。这里曾是一个安静的地方码头，但迪菲亚潜行者夺取了该地的控制权，并将其建立为一条非法的运输走廊。通过在水中转运走私的武器、补给品和违禁品，将它们从赤脊山运往西部荒野，这些盗贼完全绕过了王国的道路巡逻队。"},{t="合理的推诿",b="在派遣特工进入现场之前，肖尔明确传达了军情七处不成文的准则：如果特工被捕、身份暴露或被杀，王国及其情报首脑将否认对此人的任何知情权。找回迪菲亚码头管理员的时间表，既能获取迪菲亚潜行者补给线的关键证据，又能让暴风城的官方介入保持在阴影之中。"}},faq={{q="是谁发布了“抓捕与夺取”任务？",a="暴风城情报机构军情七处的首领马迪亚斯·肖尔在旧城区的军情七处总部内发布该任务。",al={"谁发布抓捕与夺取任务","抓捕与夺取任务发布者"}},{q="杰罗德码头在哪里？",a="杰罗德码头是位于艾尔文森林南部河流上的一个码头，在闪金镇以南，马科伦农场正东方。迪菲亚潜行者已经征用了那里的码头和码头房屋。",al={"杰罗德码头位置","杰罗德码头在哪里","码头管理员位置"}},{q="迪菲亚潜行者通过杰罗德码头走私什么？",a="迪菲亚潜行者利用杰罗德码头在赤脊山和西部荒野之间的水域运送大量的违禁品和补给品，从而绕过王国的岗哨和道路检查站。",al={"他们走私什么","迪菲亚违禁品"}},{q="谁携带着迪菲亚船运时间表？",a="船运时间表由迪菲亚码头管理员携带，他就在杰罗德码头的码头房屋旁守卫。",al={"船运时间表在哪里","谁掉落时间表","迪菲亚码头管理员"}},{q="如果特工在任务中被俘会发生什么？",a="正如马迪亚斯·肖尔所警告的那样，军情七处奉行严格的“合理推诿”原则。如果特工身份暴露或被捕，军情七处将否认与他们有任何联系。",al={"如果我失败了会怎样","被军情七处否认"}},{q="为什么军情七处需要这份船运时间表？",a="这份文件详细说明了迪菲亚潜行者如何在赤脊山和西部荒野之间运输违禁品。获取它能让暴风城的情报网络在不惊动该组织的情况下绘制出敌人的后勤地图。",al={"为什么需要时间表","军情七处船运时间表"}}},fx={["170a7301"]={q="迪菲亚船运时间表是什么？",a="这份时间表详细记录了非法货物在艾尔文森林水道上的运输情况。迪菲亚潜行者占据了杰罗德码头，在王国眼皮底下往来于赤脊山和西部荒野之间，运送大量违禁品。取回这些时间表，就能为SI:7提供有关迪菲亚通行走廊和后勤路线的确切情报。",al={"迪菲亚船运时间表","船运时间表是什么","船运时间表用途"}},["5dd0ffd3"]={q="迪菲亚码头主管是谁？",a="码头管理员负责监督兄弟会在杰罗德码头的秘密行动，那是闪金镇南面河边的一处码头货栈。他以此为据点，协调走私补给、武器和赃物在赤脊山与西部荒野之间的运输，并随身携带违禁货物清单，以便指挥迪菲亚的河道运输人员。",al={"迪菲亚码头主管","码头主管是谁","杰罗德码头码头主管"}},a07026c6={q="马迪亚斯·肖尔为什么派你去，而不派SI:7的资深特工？",a="你是科瑞恩·塞尔留斯发掘的一名颇有潜力的潜行者新人，因此被派来见马迪亚斯·肖尔。潜入杰罗德码头，既是对你潜行和偷窃本领的实战考验，也是一项可以撇清关系的外勤任务。因为SI:7打算在你被捕后否认知道你的一切，派出一名新手特工，就能让暴风城最重要的情报网络免于公开暴露。",al={"为什么派我","为什么为si7招募新人","马迪亚斯·肖尔为什么需要我"}}},fp="15,158,20.313.0,22.321.0,21.312.0,38.121.0,25.175.0,54.135.0,41.97.0,61.104.0,48.197.0"}
P.entries["quest:221"] = {n="森林里的狼人",s="随着夜祸狼人族群进一步向夜色镇逼近，卡洛尔派遣冒险者去击杀该族群的主要基层潜行者。这些凶猛的暗影奔行者已经占领了附近的烂果园，威胁着要将这座被围困的城镇完全包围。",h="随着夜祸狼人族群进一步向夜色镇逼近，卡洛尔派遣冒险者去击杀该族群的主要基层潜行者。这些凶猛的暗影奔行者已经占领了附近的烂果园，威胁着要将这座被围困的城镇完全包围。",kw={"卡洛尔","卡尔文","暗影奔行者","夜色镇","暮色森林","守夜人","夜祸","烂果园","狼人"},ang={["class:Hunter"]="在烂果园迅速蔓延的非自然双足狼怪，给猎人们上了一堂严峻的课，教导他们如何应对那些违背艾泽拉斯自然生态、来自异界的野兽。",["faction:Alliance"]="暮色森林几乎没有得到来自暴风城王国的任何增援，这迫使守夜人等当地志愿民兵组织不得不完全依赖路过的联盟英雄来削减这些入侵的掠食者族群。"},sec={{t="收紧的防线",b="起初，侦察兵在森林边缘发现了独自编织暗影魔法的狼人，但卡洛尔的巡逻揭示了一个更为紧迫的战术威胁。更大型、更迅捷的野兽——被称为夜祸暗影奔行者——已经在夜色镇西南方的烂果园集结。这些掠食者并没有仅仅潜伏在树冠之下，它们构成了狼人族群的主力，并在距离镇门仅一步之遥的地方建立了前哨阵地。"},{t="无穷无尽的潮水",b="虽然消灭暗影奔行者可以暂时削弱狼人的攻势，但这并不能让守夜人感到安心。卡洛尔怀着日益增长的恐惧注意到，每一只被击倒的野兽仿佛都会被迷雾中徘徊的另一只立刻取代。夜祸狼人超自然的韧性和极高的补充速度让城镇的守卫者们感到困惑，迫使他们求助于像乔纳森·卡尔文大师这样的资深怪物猎人，去查明究竟是什么邪恶的媒介将这些异界的恐怖之物召唤到了暮色森林。"}},faq={{q="什么是夜祸暗影奔行者？",a="夜祸暗影奔行者是体型更大、更具威慑力的狼人，构成了徘徊在暮色森林的狼人族群的主要前线部队。与神秘的暗影织法者不同，暗影奔行者依靠纯粹的速度、利爪和捕食者的凶猛。",al={"暗影奔行者","什么是暗影奔行者","夜祸暗影奔行者"}},{q="烂果园在哪里？",a="烂果园位于夜色镇的西南方。它曾是一片肥沃的农田，如今已经沦为一片被腐化和侵蚀的空地，并被夜祸狼人族群当作靠近城镇的前进落脚点占据。",al={"烂果园位置","烂果园在哪里"}},{q="卡洛尔是谁？",a="卡洛尔是夜色镇的一名游侠，服务于乔纳森·卡尔文大师。他负责侦察定居点的边缘地带，追踪威胁着城镇生存的狼人族群的侵略性动向。",al={"卡洛尔是谁","卡洛尔暮色森林","卡洛尔任务发布者"}},{q="为什么守卫者觉得狼人的数量无穷无尽？",a="守卫者们还不了解狼人存在的超自然本质。他们认为有一股邪恶的力量正在积极地召唤或将这些野兽吸引到暮色森林，导致新的浪潮在旧的被杀死的瞬间就会出现。",al={"为什么狼人这么多","无穷无尽的狼人","狼人从哪里来"}},{q="卡尔文大师是谁？",a="乔纳森·卡尔文大师在夜色镇领导着卡尔文家族对抗亡灵和暮色森林其他邪恶势力的斗争。卡洛尔非常信任他的专业知识，希望他能查出困扰该地区的怪物滋生的根本原因。",al={"卡尔文大师","乔纳森·卡尔文","谁是卡尔文"}},{q="这项任务如何融入夜色镇的防御之中？",a="夜色镇是一个孤立的定居点，补给匮乏，且得不到暴风城的援助。清理烂果园可以防止夜祸狼人族群对城镇的西南防线发起直接且势不可挡的伏击。",al={"为什么要杀暗影奔行者","夜色镇防御"}}},fp="19,158,22.351.0,21.333.1,32.192.0,37.164.0,13.164.0,56.200.0,22.208.0,53.204.0"}
P.entries["quest:222"] = {n="森林里的狼人",s="随着夜行狼人部族不断收紧对暮色森林的控制，卡洛尔指引冒险者去打击他们最致命的军团。通过直接前往他们南方的巢穴和矿洞展开战斗，守卫者们击退了对夜色镇步步紧逼的野蛮威胁。",h="随着夜行狼人部族不断收紧对暮色森林的控制，卡洛尔指引冒险者去打击他们最致命的军团。通过直接前往他们南方的巢穴和矿洞展开战斗，守卫者们击退了对夜色镇步步紧逼的野蛮威胁。",kw={"卡洛尔","卡尔文","夜色镇","暮色森林","夜行狼人","污浊者","邪恶之牙","狼人"},ang={["class:Hunter"]="夜行狼人表现出的狡诈使它们成为了不同寻常的猎物，这要求在它们昏暗巢穴附近活动的追踪者必须时刻保持警惕。",["faction:Alliance"]="夜色镇孤零零地坐落在王国的阴郁南方；清理南方的洞穴有助于保护暮色森林脆弱的补给线和仅存的家园。"},sec={{t="野兽的立足点",b="困扰暮色森林的狼人瘟疫远非无脑的混乱。这些被称为“夜行”的野兽在夜色镇南部的黑暗旷野中开辟了领地，并开始建立坚固的营地。卡洛尔怀着日益增长的恐惧，注视着远方闪烁的篝火，他注意到这些生物已经占据了深处的洞穴和废弃的矿井。在它们之中，邪恶之牙和污浊者代表了最凶残的品种，它们展现出的野蛮残暴和顽强令人担忧，甚至可能威胁到小镇的周边防线。"},{t="卡洛尔的推荐",b="卡洛尔担任着夜色镇防御的前线征兵官，时刻保持警惕，尽管他对这些狼人入侵者可怕的本性并无幻想。击溃邪恶之牙和污浊者的主力是对任何英雄勇气的考验。那些成功铲除这些顽固狼群的人获得的不仅仅是金钱，还能赢得卡洛尔的尊重，并获得他写给卡尔文大师的亲笔推荐信。卡尔文大师是一位深居简出的重要人物，负责协调针对狼人天灾的更大规模攻势。"}},faq={{q="邪恶之牙和污浊者位于何处？",a="这些危险的夜行狼人品种聚集在暮色森林南部的洞穴和矿井周围，通常会聚集在显眼的篝火旁。",al={"污浊者位置","邪恶之牙位置","暮色森林狼人位置"}},{q="卡洛尔是谁？",a="卡洛尔是夜色镇的一名忠诚居民，他密切关注着森林中的狼人威胁，并招募有能力的冒险者来阻止这些生物的推进。",al={"卡洛尔 夜色镇","谁发布了“森林中的狼人”3"}},{q="卡尔文大师是谁？",a="卡尔文大师就是夜色镇的乔纳森·卡尔文，他的家族致力于对抗该地区的邪恶势力，并负责协调从周边地区根除狼人威胁的行动。",al={"卡尔文大师","卡尔文 暮色森林"}},{q="为什么狼人会生篝火？",a="尽管拥有可怕的狼人外表，但夜行狼人表现出了令人不安的智慧，它们聚集在有组织的营地中，使用火种，并占据着像矿井这样坚固的阵地。",al={"为什么狼人生火","夜行狼人篝火"}},{q="完成这次狩猎后会发生什么？",a="让卡洛尔刮目相看就能为你赢得一封推荐信，你可以直接去找卡尔文大师，协助他进行下一阶段的狩猎。",al={"“森林中的狼人”3后的后续任务","“森林中的狼人”后续"}},{q="为什么夜色镇如此担心这些特定的狼人？",a="邪恶之牙和污浊者是该部族中最致命、最具攻击性的成员。如果不加限制地任由它们在南方矿井附近活动，这些野兽可能会彻底淹没周边道路。",al={"为什么会有夜行狼人邪恶之牙","邪恶之牙的危险"}}},fp="19,131,16.308.0,19.276.1,50.107.0,13.122.0,22.147.0,32.194.0,40.125.0,58.175.0"}
P.entries["quest:223"] = {n="森林里的狼人",s="在你猎杀暮色森林的狼人之后，卡洛尔派你前往夜色镇，给乔纳森·卡尔文送去一封信。卡尔文面对的危险不止这些野兽，卡洛尔相信你的身手能助他一臂之力。",h="在你猎杀暮色森林的狼人之后，卡洛尔派你前往夜色镇，给乔纳森·卡尔文送去一封信。卡尔文面对的危险不止这些野兽，卡洛尔相信你的身手能助他一臂之力。",kw={"卡洛尔","卡洛尔的便笺","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","森林里的狼人"},ang={["class:Paladin"]="身为圣骑士，卡尔文以圣光之言欢迎那些已证明自己实力的盟友，并寻求神圣的勇士，对抗暮色森林亵渎的邪恶。",["class:Priest"]="作为牧师，你会听到卡尔文临别时的祝福：“荣耀归于圣光。”这展现了守卫者在夜色镇无尽腐化之中依然坚守的信仰。",["faction:Alliance"]="暴风城王国无力抽调士兵支援暮色森林的边境，因此，独立行动的联盟冒险者和卡尔文这样的民间守卫者，成了镇子仅有的防线。"},sec={{t="难得的举荐",b="你将夜行狼群逐出了罗兰之墓和幽暗的林间空地，赢得了卡洛尔的敬重。他驻守在森林幽暗的边陲，很少赞许别人，也很少正式举荐他人。卡洛尔交给你一张褪色的羊皮纸，请你将他的推荐信送到夜色镇的乔纳森·卡尔文手中。他说，要是多几个像你这样的战士，他的小队或许就能胜过镇上疲于应付的守夜人。"},{t="卡尔文的守望",b="乔纳森·卡尔文在夜色镇忙于应对重重压力，对外来者心存戒备，也无暇多言。镇子面临着狼人、躁动不安的亡灵、恶魔势力，以及从内部助长腐化的邪教徒。卡洛尔的举荐让你赢得了卡尔文的信任，在他眼中，你是一名可靠的战士，已准备好对抗暮色森林的恐怖威胁，捍卫圣光。"}},faq={{q="是谁派我执行这项任务？",a="卡洛尔派你将一封褪色的推荐信送给乔纳森·卡尔文。你在暮色森林各处猎杀狼人的战绩，赢得了卡洛尔的敬重。",al={"任务给予者","谁开启任务","卡洛尔"}},{q="乔纳森·卡尔文是谁？",a="乔纳森·卡尔文是夜色镇一位专心尽责的居民，负责协调镇子抵御超自然威胁的防务。他虽然对陌生人心存戒备，却会与卡洛尔等值得信赖的盟友合作，对抗亡灵、恶魔及其帮凶。",al={"卡尔文","卡尔文是谁","卡尔文大师"}},{q="卡洛尔为什么如此轻视守夜人？",a="卡洛尔认为，守夜人难以应付暮色森林的众多危险。他觉得，几名能干的战士就能比镇上的这支小队取得更大的战果。",al={"卡洛尔 守夜人","人数超过守夜人","为何与守夜人竞争"}},{q="送信时，卡尔文会提醒我提防哪些威胁？",a="卡尔文面对着狼人、躁动不安的亡灵、恶魔势力，以及从内部助长腐化的邪教徒。来自四面八方的威胁让镇子承受着重重压力。",al={"卡尔文的敌人","卡尔文说什么","对抗什么敌人"}},{q="这项任务需要战斗吗？",a="不需要。你只需将卡洛尔的信送到夜色镇的卡尔文手中。先前猎杀夜行狼人的行动已经结束。",al={"是否需要战斗","是否需要击杀","只需送信"}},{q="在哪里可以找到乔纳森·卡尔文？",a="乔纳森·卡尔文就在夜色镇，负责照料镇上的防务。",al={"卡尔文位置","卡尔文在哪里","在哪里交任务"}}},fp="19,197,21.382.0,15.339.0,29.158.0,24.210.0,46.153.0,51.150.0,35.137.0,34.66.0"}
P.entries["quest:224"] = {n="保卫国王的领土",s="碎石穴居人正向国王谷逼近，南部哨塔的巡山人库伯弗林特为此呼吁援助。铁炉堡的部队正在遥远的前线作战。",h="碎石穴居人正向国王谷逼近，南部哨塔的巡山人库伯弗林特为此呼吁援助。铁炉堡的部队正在遥远的前线作战。",kw={"库伯弗林特","格拉维戈","铁炉堡","洛克莫丹","巡山人","碎石","穴居人","国王谷"},ang={["class:Hunter"]="身为猎人，你可以利用碎石怪之谷的峭壁和突出的岩石，从高处攻击穴居人哨兵和斥候。",["faction:Alliance"]="身为联盟冒险者，在矮人部队远赴盟军前线作战时，协助守卫国王谷便是响应铁炉堡的号召。",["race:Dwarf"]="身为矮人，在军队远赴他处作战时，响应库伯弗林特的号召，有助于保卫麦格尼国王祖传的山谷，抵御地下害物的侵扰。"},sec={{t="国王谷的薄弱防线",b="库伯弗林特和守卫们兵力不足，无法阻止宏伟矮人纪念碑下日益猛烈的穴居人入侵。国王麦格尼·铜须已将大部分正规军派往海外，支援联盟。当地巡逻队和受雇的佣兵必须守住这片领地，防止它沦陷。"},{t="碎石的入侵",b="碎石怪之谷穿过洛克莫丹南部的群山，穴居人从地下深处掘洞而出。它们的斥候侦察道路，战士则在谷底扎营。如果不加以遏制，它们的队伍就会威胁通往南部隘口的道路。巡山人必须不停地与它们作战。"}},faq={{q="洛克莫丹的驻军为什么如此缺乏人手？",a="国王麦格尼·铜须已将铁炉堡的大部分军队派往遥远的联盟战场，以及遍布艾泽拉斯的前哨。洛克莫丹和其他本土领地主要依靠兵力单薄的巡山人巡逻队，他们会召集旅人，协助抵御当地的入侵。",al={"守卫为何这么少","铁炉堡士兵在哪","为何人手不足"}},{q="巡山人库伯弗林特是谁？",a="巡山人库伯弗林特是驻守国王谷南部哨塔的一名矮人哨兵。他负责协调洛克莫丹南部边界的防务，并指挥对穴居人部族的进攻。",al={"库伯弗林特","谁发布任务","任务发布者"}},{q="碎石怪之谷在哪里？",a="碎石怪之谷位于塞尔萨玛以南。入口靠近大路，就在国王谷巨大的矮人雕像前，穴居人在岩石遍布的谷底设有数处营地。",al={"碎石位置","穴居人在哪","寻找碎石怪之谷"}},{q="穴居人为什么会对矮人构成如此严重的威胁？",a="穴居人能在坚硬的岩石中挖掘隧道，绕过地表的城墙和防御工事。它们可能从道路、定居点和矿井下方突然钻出，危及铁炉堡的安全。",al={"穴居人的威胁","为何对抗穴居人","穴居人危险吗"}},{q="帮助库伯弗林特之后，我该找谁交谈？",a="你削减碎石穴居人及其斥候的数量后，库伯弗林特会派你去找巡山人格拉维戈。他就在旁边的哨塔内，负责山谷前线下一段的巡逻。",al={"下一个任务","之后去哪","格拉维戈"}},{q="碎石穴居人有组织吗？",a="碎石氏族派出专门的斥候侦察道路，步兵则驻守在峡谷各处的防御营地。",al={"穴居人斥候","穴居人聪明吗","碎石组织结构"}}},fx={abec66b9={q="巡山人库伯弗林特为什么要削减穴居人的数量？",a="巡山人库伯弗林特认为，穴居人的泛滥是洛克莫丹乃至铁炉堡面临的最大威胁。这些生物从每一道裂隙中挖洞涌出，威胁着国王谷及周边地区。由于矮人正规军都被派往遥远的战场，库伯弗林特只能依靠勇敢的志愿者，在当地哨塔和聚落彻底沦陷之前削减这些成群而来的敌人。",al={"为什么杀死穴居人","库伯弗林特的动机","库伯弗林特为什么要杀死穴居人"}},["515fdd78"]={q="碎石穴居人在洛克莫丹做什么？",a="碎石穴居人是一群凶残的地下变异生物，它们挖掘地道，来到洛克湖南部，并在碎石怪之谷各处建立营地。它们的斥候不断试探矮人的领地，寻找山谷道路沿线和南部哨塔附近的薄弱之处。如果不加以遏制，它们的大量涌现将切断交通路线，并席卷整个地区。",al={"穴居人是什么","碎石穴居人为什么在这里","碎石穴居人目标"}}},fp="30,170,34.273.0,27.321.0,49.266.0,31.204.0,38.197.0,54.178.0,44.193.0,39.136.0"}
P.entries["quest:2242"] = {n="命运的召唤",s="塞尤娜派你去查明远古的塞希尔对泰达希尔的腐化知道些什么。这个萨特盘踞在神谕林地附近，试图以武力或外交手段接近他的人都未能如愿。",h="塞尤娜派你去查明远古的塞希尔对泰达希尔的腐化知道些什么。这个萨特盘踞在神谕林地附近，试图以武力或外交手段接近他的人都未能如愿。",kw={"黑海岸","达纳苏斯","命运的召唤","日记","神谕林地","萨特","远古的塞希尔","塞尤娜","泰达希尔"},ang={["class:Rogue"]="身为盗贼，你在达纳苏斯潜行训练师的指引下，检验自己能否从一个危险萨特的眼皮底下窃取机密情报。",["faction:Alliance"]="身为联盟的保卫者，你得知泰达希尔林地中的腐化已经超出这座岛屿，蔓延到了卡利姆多的北方大地。",["race:NightElf"]="身为kaldorei的保卫者，你得知黑海岸的古老诅咒已经跨海侵入泰达希尔，威胁着你神圣的庇护之地。"},sec={{t="无声的侦察",b="泰达希尔日益严重的病变令达纳苏斯的暗夜精灵领袖忧心忡忡。盗贼训练师塞尤娜需要一个行事隐秘的人；武装巡逻队曾试图接近远古的塞希尔，却为此丧命。这个萨特盘踞在神谕林地附近一根偏僻的树枝上，武力和外交手段都没能奏效。要查明他知道些什么，你需要潜入他的巢穴，取走他的私人物品。"},{t="黑海岸逼近的阴影",b="远古的塞希尔的日记将泰达希尔的污秽与迷雾之海对岸的腐朽和腐化联系起来，后者正吞噬着黑海岸的森林与水道。这种病变并不局限于世界之树脚下的土壤。它波及的范围表明，一股蓄意为恶的力量正威胁着卡多雷的腹地。"}},faq={{q="远古的塞希尔是谁？",a="远古的塞希尔是一个萨特，藏身于泰达希尔神谕林地北缘附近的树枝上。想要探知他对岛上腐化了解多少的人，无论是武装进攻还是和平问询，都遭到了他的击败或拒绝。",al={"塞希尔","塞希尔是谁","神谕林地的萨特"}},{q="塞尤娜为什么想要塞希尔的日记？",a="塞尤娜相信，塞希尔的日记中藏着线索，能揭示泰达希尔蔓延的反常病变。日记记述了他的活动和那股黑暗的污秽。",al={"为何需要塞希尔的日记","塞尤娜的目标","日记里有什么"}},{q="任务完成时，日记揭示了什么？",a="塞希尔的日记将泰达希尔枝干中的病变，与海峡对岸侵蚀黑海岸古老森林和海岸的恶魔瘟疫联系起来。",al={"日记背景故事","塞希尔发现了什么","与黑海岸的关联"}},{q="在哪里接取这个任务？",a="达纳苏斯的盗贼训练师塞尤娜会在初步考察你的能力后，将这项工作交给你。",al={"哪里接取命运的召唤","命运的召唤任务给予者","谁给予命运的召唤"}},{q="完成这项任务后，冒险者该去哪里？",a="塞尤娜说，对于此事，在这里已经无能为力了。她会奖励你一把利刃，以酬谢你为泰达希尔效力。",al={"接下来做什么","命运的召唤之后的下一步","塞希尔之后"}},{q="为什么处理森林腐化的是盗贼训练师，而不是德鲁伊？",a="面对塞希尔，武力和德鲁伊的外交手段都以失败告终，还付出了生命的代价。公开的尝试以流血收场后，塞尤娜转而求助于潜行与渗透。",al={"为何是盗贼任务","为何是塞尤娜","为何不是塞纳里奥议会"}}},fp="13,158,23.375.0,31.268.1,26.231.0,38.154.0,45.152.1,29.106.0,58.120.1,68.159.0"}
P.entries["quest:2258"] = {n="荒芜之地的试剂",s="卡加斯哨站的加卡尔是一位颇有名气的炼金师，他需要荒芜之地的材料来补充库存。他许诺支付钱币，但只有交来材料的人才能拿到报酬。",h="卡加斯哨站的加卡尔是一位颇有名气的炼金师，他需要荒芜之地的材料来补充库存。他许诺支付钱币，但只有交来材料的人才能拿到报酬。",kw={"炼金术","荒芜之地","秃鹫的砂囊","峭壁郊狼的牙齿","加卡尔","卡加斯","岩石元素的碎片","奥达曼"},sec={{t="补充库存",b="加卡尔缺少材料：五只秃鹫的砂囊、十只峭壁郊狼的牙齿，以及五个岩石元素的碎片。这三种材料都可以从那些生物身上取得。不擅长战斗的人会被告知，去找擅长战斗的朋友帮忙。加卡尔会支付钱币，但必须等材料到手才会付款。"},{t="满载而归之后",b="加卡尔对收来的材料很满意，说这些应该够用一阵子了。这位炼金师还有更多材料要收集，但它们只能在奥达曼挖掘场的深处找到，而且并不容易取得。加卡尔暗示，报酬或许比闪亮的钱币更有价值。"}},faq={{q="是谁在收集这些材料？",a="加卡尔，他是荒芜之地卡加斯哨站一位颇有名气的炼金师，想要补充库存。",al={"荒芜之地的材料由谁提供","加卡尔","加卡尔是谁"}},{q="加卡尔需要哪些材料？",a="五只秃鹫的砂囊、十只峭壁郊狼的牙齿，以及五个岩石元素的碎片。这些材料都来自那些生物本身。",al={"需要哪些物品","荒芜之地材料清单","所需材料"}},{q="加卡尔在哪里？",a="加卡尔在荒芜之地的卡加斯哨站。",al={"加卡尔位置","卡加斯炼金师在哪里","荒芜之地的材料在哪里交付"}},{q="加卡尔会用什么来交换这些材料？",a="钱币，把材料送到卡加斯的加卡尔手中后才会支付。在那之前不会支付任何报酬。",al={"荒芜之地的材料奖励","能获得什么"}}},fp="20,116,20.253.0,14.243.1,33.94.0,34.149.0,33.62.0,55.94.0"}
P.entries["quest:2259"] = {n="艾瑞安·影语",s="艾瑞安·影语是一个简单的召唤任务，旨在引导初出茅庐的联盟潜行者前往达纳苏斯。该信息由詹诺克·柔歌传达，指引旅行者前往塞纳里奥区，艾瑞安·影语正等在那里，准备将他们的行动范围扩展到当地以外的区域。",h="艾瑞安·影语是一个简单的召唤任务，旨在引导初出茅庐的联盟潜行者前往达纳苏斯。该信息由詹诺克·柔歌传达，指引旅行者前往塞纳里奥区，艾瑞安·影语正等在那里，准备将他们的行动范围扩展到当地以外的区域。",kw={"塞纳里奥区","达纳苏斯","艾瑞安·影语","艾瑞安的命令","詹诺克·柔歌","潜行者引导任务","塞尤娜"},ang={["class:Rogue"]="这个引导任务标志着你从泰达希尔的新手工作中毕业，直接将你引向艾瑞安·影语，去执行那些需要超越起始森林范畴的精湛技巧的任务。",["faction:Alliance"]="该任务引导卡利姆多北部的联盟特工在进入争夺领土之前，先与达纳苏斯的联络人进行协调。",["race:NightElf"]="对于暗夜精灵影行者来说，向达纳苏斯的艾瑞安·影语报到是必经的成人礼，标志着他们从本地守卫工作转向更广泛的大陆职责。"},sec={{t="塞纳里奥区的召唤",b="当一名潜行者在泰达希尔周边地区小有名气时，詹诺克·柔歌会介入，确保他们的才华不被浪费。为了缓解他们被派去接受严厉的训练师塞尤娜教导的焦虑，詹诺克转而指引这些特工直接前往达纳苏斯的中心。在那里，在塞纳里奥区葱郁的枝叶深处，艾瑞安·影语负责处理那些需要更安静、更微妙手段的事务。"},{t="展望地平线",b="对于任何在暗夜精灵领地活动的潜行者来说，找到艾瑞安·影语是一个重要的转折点。他的问候清楚地表明，泰达希尔的庇护森林已不再能束缚一名特工的职责。艾瑞安·影语的角色是引导有能力的潜行者走向更广阔、更危险的世界，并作为通往跨海任务的跳板。"}},faq={{q="是谁让你去找艾瑞安·影语的？",a="詹诺克·柔歌发布了召唤，让你立即前往达纳苏斯，在塞纳里奥区与艾瑞安·影语交谈。",al={"任务发布者","谁开启了艾瑞安·影语任务","詹诺克·柔歌任务"}},{q="艾瑞安·影语在哪里？",a="艾瑞安·影语位于达纳苏斯的塞纳里奥区，就在该区域上层的树木掩映之中。",al={"艾瑞安·影语位置","艾瑞安·影语在哪里","如何找到艾瑞安·影语"}},{q="为什么詹诺克提到了塞尤娜？",a="塞尤娜是达纳苏斯一位著名的潜行者训练师，以严厉和高要求著称。詹诺克开了一个轻松的玩笑，让你放心，你并没有惹上麻烦，也不会被拖去接受她那严苛的课程。",al={"谁是塞尤娜","为什么不是塞尤娜","詹诺克关于塞尤娜的台词"}},{q="向艾瑞安·影语报到后会发生什么？",a="在你完成汇报后，艾瑞安·影语会交给你他的下一个任务“艾瑞安的命令”，指引你离开泰达希尔，以扩大你在卡利姆多的行动范围。",al={"接下来做什么","艾瑞安·影语后续","艾瑞安·影语之后的任务"}},{q="艾瑞安·影语负责什么样的工作？",a="艾瑞安·影语负责协调达纳苏斯内部的行动并指导初出茅庐的潜行者，作为一名联络人，将当地特工与联盟网络中更广泛的任务连接起来。",al={"艾瑞安·影语是潜行者训练师吗","艾瑞安·影语的角色","艾瑞安·影语做什么"}},{q="为什么一个潜行者联络人会驻扎在塞纳里奥区？",a="虽然塞纳里奥区主要以德鲁伊和自然崇拜而闻名，但其蔓延、阴影笼罩的树木为潜行特工提供了充足的隐蔽场所，使他们能够避开月神殿，聚集并开展业务。",al={"塞纳里奥区潜行者","为什么德鲁伊区域会有潜行者"}}},fp="18,159,24.243.0,19.194.0,41.114.0,36.105.0,31.197.0,38.131.0,37.95.0,57.175.0"}
P.entries["quest:226"] = {n="恶狼成群",s="“狼群逼近”是一项联盟任务，由位于暮色森林西部斯温营地的拉尔斯提供。任务要求狩猎潜伏在周围树林中、患有狂犬病且饥饿的恐狼。旅行者们将清除这些迫在眉睫的荒野威胁，让斯温和拉尔斯能够专注于他们针对死灵法师摩本特·费尔的复仇行动。",h="“狼群逼近”是一项联盟任务，由位于暮色森林西部斯温营地的拉尔斯提供。任务要求狩猎潜伏在周围树林中、患有狂犬病且饥饿的恐狼。旅行者们将清除这些迫在眉睫的荒野威胁，让斯温和拉尔斯能够专注于他们针对死灵法师摩本特·费尔的复仇行...",kw={"恐狼","暮色森林","闪光束","拉尔斯","摩本特·费尔","患狂犬病的恐狼","饥饿的恐狼","斯温","斯温营地"},ang={["class:Hunter"]="驯服或扑杀暮色森林中扭曲的野生动物需要极高的警惕；这些恐狼远比普通的森林野兽更加绝望和凶残。",["faction:Alliance"]="帮助拉尔斯可以稳定斯温偏远的营地，从而稳固一个对抗困扰暮色森林西部亡灵势力的盟军补给据点。"},sec={{t="岌岌可危的营地",b="斯温·约根和他的同伴拉尔斯在暮色森林西部、靠近西部荒野边界的群山中维护着一个与世隔绝的前哨站。远离夜色镇的生活使他们完全依赖自己的采集和狩猎来维持生存。然而，在这些黑暗的树林中携带新鲜猎物，使拉尔斯成为了潜伏在阴影河岸和灌木丛中的饥饿掠食者们无法抗拒的目标。"},{t="清理树林",b="当地的饥饿且患有狂犬病的恐狼群主要在营地的北部和东部，向河流方向游荡。通过猎杀这些疯狂的野兽，旅行者们解除了拉尔斯狩猎工作所面临的紧迫困境。减少狼群的数量使两人不必再为每日的面包而不断战斗，让他们能够将全部注意力转向潜伏在更东面的死灵法师摩本特·费尔身上。"}},faq={{q="拉尔斯是谁？",a="拉尔斯是一位坚韧的生存专家，在暮色森林西部山丘中的一个小营地里协助斯温·约根。他负责营地日常的狩猎和采集，而斯温则执着于向威胁该地区的黑暗势力复仇。",al={"拉尔斯","狼群逼近任务发布者","任务发布者拉尔斯"}},{q="狼群在何处游荡？",a="恐狼游荡在斯温营地正北和正东的森林中，特别是在将暮色森林与北部地区隔开的河岸沿线。",al={"恐狼位置","患狂犬病的恐狼在哪里","饥饿的恐狼在哪里"}},{q="为什么恐狼如此具有攻击性？",a="在阴影的侵蚀下，暮色森林的荒野环境日益恶化。猎物稀缺，导致恐狼濒临饿死；疾病或黑暗腐蚀也使得它们中的许多患上了狂犬病，并对任何携带新鲜肉类的人表现出鲁莽的暴力倾向。",al={"狼群为何攻击","暮色森林的疯狼"}},{q="摩本特·费尔是谁？",a="摩本特·费尔是一位强大的死灵法师，在东部的墓地和土丘中研习黑暗艺术。斯温和拉尔斯对他怀有深仇大恨，并准备在满足了基本生存需求后就去打倒他。",al={"摩本特·费尔","死灵法师","东面的死灵法师是谁"}},{q="拉尔斯作为奖励给予的闪光束是什么？",a="闪光束是由夜色镇居民制造的致盲闪光装置。同情的居民们将它们捐赠给了斯温的营地，以帮助他对抗在这片树林中出没的亡灵和野兽。",al={"闪光束","拉尔斯的奖励","什么是闪光束"}},{q="为什么斯温和拉尔斯不住在夜色镇？",a="斯温的家庭遭遇了一场悲剧，使他变成了一个痛苦、执着的义务警员。斯温和拉尔斯没有躲在夜色镇的守夜人背后，而是驻扎在荒野中，亲身追踪困扰这片树林的邪恶力量。",al={"为什么要住在营地","斯温营地位置","为什么不住在镇里"}}},fp="19,185,17.272.0,18.254.0,12.199.0,30.140.0,38.228.0,19.203.0,50.188.0,42.229.0"}
P.entries["quest:2260"] = {n="艾瑞安的命令",s="“埃里奥的嘱托”是一份发给在达纳苏斯行动、前途无量的暗夜精灵潜行者的传唤。潜行者导师埃里奥·影语（艾瑞安·影语）认可了他们初露锋芒的潜行技巧，于是派遣他们跨越海洋前往暴风城，直接向暴风城军情七处报到。",h="“埃里奥的嘱托”是一份发给在达纳苏斯行动、前途无量的暗夜精灵潜行者的传唤。潜行者导师埃里奥·影语（艾瑞安·影语）认可了他们初露锋芒的潜行技巧，于是派遣他们跨越海洋前往暴风城，直接向暴风城军情七处报到。",kw={"达纳苏斯","埃里奥·影语","埃里奥的嘱托","旧城区","“剃刀”雷吉克","潜行者","军情七处","暴风城"},ang={["class:Rogue"]="这份传唤标志着你已从卡利姆多的地方小打小闹，毕业并进入了更广阔的洲际间谍活动领域，并将在军情七处接受致命的训练。",["faction:Alliance"]="军情七处负责统筹联盟的秘密行动，确保来自各个成员种族的优秀侦察兵能够被部署到王权最需要他们的地方。",["race:NightElf"]="离开达纳苏斯和泰达希尔的庇护，去暴风城的石板巷弄里为人类情报网络效力，对于卡多雷潜行者来说，往往是一种强烈的文化冲击。"},sec={{t="跨海的传唤",b="在泰达希尔阴影下行动的暗夜精灵潜行者通常会在埃里奥·影语这样的导师静默的注视下磨练自己的技能。然而，当一名特工展现出非凡的天赋时，消息便会传遍世界之树的枝桠。通过埃里奥，暴风城军情七处（即大名鼎鼎的军情七处）向其发出直接邀请，要求其跨越无尽之海前往人类首都。"},{t="加入军情七处",b="旅途十分艰辛，特工需要从卡利姆多的北部边境出发，穿过黑海岸的码头或湿地，进入暴风城熙熙攘攘的街道。一旦到达首都，特工必须潜入旧城区，并向军情七处总部报到。在那里，“剃刀”雷吉克正等着考核新人，为他们开启通往高级间谍活动、毒药精通以及代表联盟执行隐秘行动的大门。"}},faq={{q="是谁派遣我执行这个任务的？",a="埃里奥·影语，达纳苏斯的潜行者训练师。在你早期的事迹引起了海对岸情报网络的注意后，他便指派了这项任务给你。",al={"任务发布者","埃里奥·影语","谁给了我这个任务"}},{q="为什么军情七处会联系一名暗夜精灵？",a="虽然暗夜精灵有自己传统的潜行方式，但联盟非常依赖军情七处来协调秘密情报和破坏活动。军情七处会定期发掘任何联盟种族中的优秀潜行者，以充实他们的作战队伍。",al={"为什么是军情七处","为什么是暴风城","人类为何关注我"}},{q="我在哪里可以找到“剃刀”雷吉克？",a="“剃刀”雷吉克驻扎在军情七处总部内，该总部位于暴风城的旧城区区一隅。",al={"雷吉克的位置","剃刀在哪里","寻找雷吉克"}},{q="这个任务只有潜行者能接吗？",a="是的。这是一个联盟潜行者职业任务，旨在引导位于卡利姆多的特工前往暴风城的联盟情报训练中心。",al={"仅限潜行者","其他职业能做这个吗","这是潜行者任务吗"}},{q="见到雷吉克之后会发生什么？",a="向雷吉克报到后，你将加入军情七处在东部王国的训练行动，从而为接受专门训练和在人类领地执行隐秘任务做好准备。",al={"后续任务","我能得到什么","雷吉克之后"}},{q="现阶段暗夜精灵该如何前往暴风城？",a="旅客可以从黑海岸的奥伯丁乘坐船只，直航跨越海洋抵达暴风城港口。",al={"如何前往暴风城","前往暴风城","前往暴风城的路径"}}},fp="14,198,24.270.0,28.321.0,29.144.0,53.208.0,34.75.0,30.117.0,34.165.0,57.85.0"}
P.entries["quest:2281"] = {n="赤脊山的联络员",s="“赤脊山会面”是暴风城情报指挥部派发的一项联盟潜行者任务。由于SI:7意识到未经雕琢的新兵缺乏执行危险实地行动所需的技巧，他们会将有潜力的特工送往湖畔镇，以便在经验丰富的特工指导下磨练他们的职业技能。",h="“赤脊山会面”是暴风城情报指挥部派发的一项联盟潜行者任务。由于SI:7意识到未经雕琢的新兵缺乏执行危险实地行动所需的技巧，他们会将有潜力的特工送往湖畔镇，以便在经验丰富的特工指导下磨练他们的职业技能。",kw={"湖畔镇","卢修斯","赤脊山会面","伦兹克·“快刀”","潜行者任务","si:7","暴风城"},ang={["class:Rogue"]="这项任务标志着潜行者正式开始SI:7的实地工作，将其训练内容从街头小偷小摸转变为经过计算的国家间谍活动。",["faction:Alliance"]="这项指派揭示了暴风城秘密部门的影响力，他们在像湖畔镇这样的外部定居点中也驻扎有隐秘的特工。"},sec={{t="生存的考量",b="在暴风城SI:7的秘密大厅内，副指挥官伦兹克·“快刀”对新兵的预期寿命直言不讳。将未经磨练的特工直接投入敌对行动只会造成人员伤亡，而非搜集情报。为了防止不必要的损失，SI:7会将展现出潜力的招募人员派往东方，进入赤脊山，并在驻扎于湖畔镇码头的特工卢修斯手下接受训练。"},{t="湖畔镇的监视者",b="湖畔镇是进行秘密训练的理想中转站。这座边境城镇四周环绕着豺狼人和黑石兽人，提供了充足的现实威胁；而繁忙的码头又为卢修斯这样的特工提供了绝佳的掩护，使他能在不引起当地镇民或城镇守卫注意的情况下，评估潜行者的潜行、反应和开锁能力。"}},faq={{q="谁发布了“赤脊山会面”任务？",a="伦兹克·“快刀”，这位在暴风城旧城区的SI:7总部内活动的哥布林情报主管，会将该任务发布给向情报指挥部报到的潜行者。",al={"谁发布赤脊山会面","赤脊山会面任务发布人","谁发布任务"}},{q="卢修斯在哪里？",a="卢修斯位于赤脊山的湖畔镇木质码头上，混在水边的当地闲人和渔民中。",al={"卢修斯在哪里","卢修斯位置","寻找卢修斯"}},{q="SI:7为什么要派潜行者去赤脊山？",a="伦兹克认为新手潜行者不适合执行高风险的情报实地任务。卢修斯的职责是打磨他们的生疏技巧，在边境环境下测试他们的扒窃和开锁等实际能力。",al={"为什么选择湖畔镇","赤脊山会面的目的","为什么去赤脊山"}},{q="完成“赤脊山会面”后有什么后续任务？",a="向卢修斯报到后会直接进入训练练习，首先是“奥瑟尔伐木场”，特工将在那里被要求测试自己的潜行能力和手工灵巧度。",al={"下一个任务","赤脊山会面后续","赤脊山会面之后"}},{q="除了潜行者以外的职业可以接取此任务吗？",a="不可以。“赤脊山会面”是专门针对SI:7实地训练的联盟潜行者职业任务。",al={"战士可以做赤脊山会面吗","是潜行者专属吗","职业要求"}},{q="为什么伦兹克会为暴风城情报部门工作？",a="尽管伦兹克·“快刀”是个哥布林，但他却是情报主管马迪亚斯·肖尔高度信任的副手，负责在SI:7要塞深处进行特工招募和培训。",al={"为什么si:7里有哥布林","伦兹克背景故事","暴风城的哥布林"}}},fx={da1ebf68={q="雷吉克为什么需要我执行这项任务？",a="SI:7需要能够承担危险秘密工作的新特工，但雷吉克知道，把一个尚未磨炼成熟的潜行者直接投入实地行动，几乎等于判他死刑。他不愿白白浪费有潜力的人才，因此特意派你前去，让你先在卢修斯的指导下磨炼谍报技巧，再去执行那些可能让你丧命的任务。",al={"雷吉克为什么选我","赤脊山为什么选我","为什么派我去见卢修斯"}}},fp="19,183,21.327.0,17.237.0,40.154.0,24.120.0,38.206.0,48.117.0,53.85.0,48.160.0"}
P.entries["quest:2282"] = {n="奥瑟尔伐木场",s="在奥瑟尔伐木场，卢修斯用一个上锁的箱子和盗贼工具考验联盟潜行者。伐木场位于湖畔镇东北方向的道路沿线，黑石兽人如今已逼近此地。",h="在奥瑟尔伐木场，卢修斯用一个上锁的箱子和盗贼工具考验联盟潜行者。伐木场位于湖畔镇东北方向的道路沿线，黑石兽人如今已逼近此地。",kw={"奥瑟尔伐木场","黑石兽人","湖畔镇","开锁","卢修斯","赤脊山","si:7","盗贼工具","偷窃技能证明物"},ang={["class:Rogue"]="身为潜行者，你会获得开锁工具和野外行动资质，同时在黑石兽人附近磨炼耐心与潜行本领。",["faction:Alliance"]="身为联盟的一员，你会协助在湖畔镇附近训练盗贼和渗透者，同时监视黑石的动向。"},sec={{t="优雅与灵巧的考验",b="卢修斯让你带上自己的第一套盗贼工具，沿着湖畔镇的道路向东北前往奥瑟尔伐木场。在那里，等待你的是一个上锁的箱子和一场技艺考验。打开卢修斯的私人箱子，带回里面的信物，就能获得偷窃技能认证书。"},{t="锯刃周围的阴影",b="奥瑟尔伐木场曾是一处伐木前哨，但黑石兽人如今正侵入赤脊山，已逼近此地。卢修斯将他们的存在视为一项额外的考验。SI:7要求特工在敌占区域行动时，能够不被察觉地开锁。"}},faq={{q="前往奥瑟尔伐木场的任务有何目的？",a="卢修斯要在野外考验你的开锁本领。他给你盗贼工具，让你从一个上锁的箱子里取回信物，以此证明你的技艺。",al={"为何前往奥瑟尔伐木场","任务目的","这项任务有何作用"}},{q="卢修斯是谁？",a="卢修斯在赤脊山的湖畔镇训练潜行者。他教导由联盟各地的联络人派来的新兵，考验他们的潜行本领和手上功夫。",al={"卢修斯是谁","卢修斯 湖畔镇","任务由谁发布"}},{q="奥瑟尔伐木场在哪里？",a="奥瑟尔伐木场位于湖畔镇东北及以东方向的路旁，紧靠通往更高山口之前的山麓。",al={"伐木场在哪里","奥瑟尔伐木场位置","如何找到奥瑟尔伐木场"}},{q="为什么奥瑟尔伐木场周围有兽人？",a="黑石氏族的兽人从石堡及其上方燃烧的山脊下来。他们袭击人类定居点，在赤脊山各处建立前沿据点，这座废弃伐木场周围也不例外。",al={"这里为何有兽人","黑石兽人 赤脊山","谁控制着奥瑟尔伐木场"}},{q="完成任务后，卢修斯会给予什么奖励？",a="卢修斯会授予你偷窃技能认证书，认可你对锁簧和开锁器的掌握，证明你已准备好作为一名获得认证的潜行者执行野外任务。",al={"奖励是什么","偷窃技能认证书","任务完成奖励"}},{q="这项任务在联盟的潜行者训练中有何作用？",a="联盟各地的潜行者会在联络人的指引下，前往湖畔镇与卢修斯会面，其中就包括暴风城中马迪亚斯·肖尔麾下负责联络的SI:7人员。奥瑟尔伐木场的考验，是他们基础野外训练中的最后一场实操试炼。",al={"潜行者任务链","与si7的联系","赤脊山的联络员后续"}}},fp="13,151,27.269.0,23.241.0,52.148.0,14.159.0,31.126.0,40.198.0,55.153.0,64.218.0"}
P.entries["quest:23"] = {n="乌萨苟斯的爪子",s="这个任务证明了你已经击杀了乌萨诺斯，它是灰谷中最凶猛、最富传奇色彩的掠食者之一。将这头野兽的断爪带给碎木岗哨的塞娜尼·雷心，将为你赢得部落追踪者们的荣耀。",h="这个任务证明了你已经击杀了乌萨诺斯，它是灰谷中最凶猛、最富传奇色彩的掠食者之一。将这头野兽的断爪带给碎木岗哨的塞娜尼·雷心，将为你赢得部落追踪者们的荣耀。",kw={"灰谷","灰谷狩猎","熊","新月纹章","爪子","塞娜尼·雷心","碎木岗哨","乌萨诺斯"},ang={["class:Hunter"]="追踪并击败灰谷最古老、最致命的掠食者之一，是对野外生存能力、求生技巧和战斗技能的终极考验。",["faction:Horde"]="部落猎手视乌萨诺斯为危险的猎物，击败它能在碎木岗哨赢得荣耀。",["race:Tauren"]="对于牛头人猎手来说，夺取乌萨诺斯的爪子是一件神圣的事情，既是为了向野兽表示敬意，也是为了展示战斗的决心以及对狩猎之灵的尊重。"},sec={{t="伟大狩猎的战利品",b="作为灰谷狩猎的一部分，驻扎在碎木岗哨的追踪者们负责追捕那些盘踞在茂密森林树冠下的远古野兽。乌萨诺斯是这些顶级掠食者中最凶猛的一员，因为它杀死了无数过往的旅人和战士。击败这样的野兽绝非易事，取回它的爪子是这头强大生物最终落败的铁证。"},{t="暗夜精灵的联系",b="仔细检查乌萨诺斯的爪子时，可以看到上面刻有一个小的四分之一新月纹章。当你把它交给塞娜尼·雷心时，她会指出这个标志是暗夜精灵介入的明确迹象。暗夜精灵经常驯养和结盟森林中强大的野兽来保卫他们神圣的边境，这意味着乌萨诺斯不仅仅是一头野生掠食者——它还是联盟不自知的守护者或武器。"}},faq={{q="什么是乌萨诺斯？",a="乌萨诺斯是一头漫游在灰谷森林中，体型巨大且致命的熊。它让猎人和路人闻风丧胆，在倒在部落的猎杀之下前，它已经夺去了无数的生命。",al={"乌萨诺斯是谁","乌萨诺斯之熊","乌萨诺斯背景故事"}},{q="爪子上的新月纹章意味着什么？",a="当你检查战利品时，这个四分之一新月纹章是一个谜。当你送交这只爪子时，塞娜尼·雷心可以帮你鉴定它。",al={"爪子上的新月印记","爪子纹章","为什么会有新月标志"}},{q="我该把乌萨诺斯的爪子交给谁？",a="这只爪子必须交给位于灰谷东部碎木岗哨的牛头人女猎手塞娜尼·雷心。",al={"在哪里上交爪子","谁想要乌萨诺斯的爪子","塞娜尼·雷心位置"}},{q="这与灰谷狩猎有什么关系？",a="乌萨诺斯是灰谷狩猎中被标记的三头巨兽之一，另外两头是沙德拉和尖爪。击败这三头巨兽并上交它们的战利品是完成整个试炼的必要条件。",al={"灰谷狩猎系列任务","什么是狩猎","狩猎任务线"}},{q="部落为什么要猎杀灰谷的巨兽？",a="部落的猎手，尤其是碎木岗哨的牛头人和兽人，猎杀这些顶级生物既是为了测试他们的战斗能力，也是为了遏制潜伏在他们脆弱补给线和营地附近的致命威胁。",al={"为什么要猎熊","碎木岗哨狩猎背景"}},{q="上交爪子后会发生什么？",a="一旦你收集了乌萨诺斯和其他指定猎物的战利品，塞娜尼·雷心就会在最终试炼“狩猎的终结”中认可你的功绩。",al={"爪子之后的下一个任务","乌萨诺斯之后是什么"}}},fp="15,147,26.230.0,24.306.1,18.173.0,46.149.0,34.108.0,42.161.0,55.188.0,38.173.0"}
P.entries["quest:230"] = {n="斯温的营地",s="在暮色森林，斯温·约根仍被悲痛驱使，追查家人惨遭屠戮的真相。埋在农场废墟中的一本日记，或许能揭示谁目睹了这一切。",h="在暮色森林，斯温·约根仍被悲痛驱使，追查家人惨遭屠戮的真相。埋在农场废墟中的一本日记，或许能揭示谁目睹了这一切。",kw={"黑暗强盗","暮色森林","一堆松软的泥土","模糊的人影","斯温·约根","约根农场"},ang={["faction:Alliance"]="身为联盟的一员，你可以协助调查 Yorgen 一家的惨案，而联盟也正努力查明侵入暮色森林的黑暗势力。"},sec={{t="泥土中的线索",b="斯温·约根归来时，发现家人已死，农场也成了废墟，黑暗强盗 趁他外出时发动了袭击。悲痛与复仇之心驱使他派盟友搜查家园的残骸。一堆新翻的泥土下，埋着一本沾满泥污的小册子，是一个鬼祟的身影匆忙藏下的。"},{t="沉默的目击者",b="在西部群山中的营地里，斯温得知了书中的内容。这本日记证实，一个鬼祟的身影目睹了他家人惨遭屠戮的经过。它没有带来安宁，反而让斯温决心找到那个身份不明的旁观者，追问真相。"}},faq={{q="土堆里发现的是什么书？",a="这是一本没有标题、沾满泥污的小日记，埋在 约根农场。日记中的记录证实，一个身份不明的旁观者目睹了斯温·约根一家惨遭屠戮的经过。",al={"这是什么书","斯温 农场的书","挖出了什么"}},{q="这个任务接下来通向哪里？",a="将书交给斯温·约根后，便会开始寻找那位神秘的目击者，并接到 模糊的人影。",al={"接下来做什么","斯温的营地 后续任务","模糊的人影 是谁"}},{q="斯温·约根在哪里？",a="斯温在暮色森林西北部群山中的一处营地避难，哀悼家人的命运，谋划复仇。",al={"斯温 在哪里","斯温·约根位置","交任务地点"}},{q="为什么这本书被埋在农场里？",a="这本书藏在家园废墟间的松土中。它可能是那个在袭击现场逗留的旁观者匆忙丢弃或藏起来的。",al={"为什么埋起来","谁藏了书","松软的泥土"}},{q="谁杀害了斯温的家人？",a="来自逆风小径的 黑暗强盗 趁斯温不在农场时，屠杀了他的家人。",al={"谁袭击了农场","谁杀了 斯温 的家人","杀害 斯温 家人的凶手"}},{q="哪个阵营可以完成这个任务？",a="只有联盟玩家可以完成这个任务；斯温·约根向暮色森林的守卫者和联盟寻求援助。",al={"是否仅限联盟","部落 能否做 斯温的营地"}}},fp="11,161,18.288.0,16.220.1,44.171.0,32.112.0,29.114.0,36.131.0,25.89.0,37.101.0"}
P.entries["quest:2300"] = {n="军情七处",s="这项指令旨在将艾尔文森林中前途无量的年轻潜行者直接召集到暴风城秘密情报网络的核心。在闪金镇的科瑞恩·塞尔留斯指导下，特工们被命令立即向旧城区的“剃刀”雷吉克报到。响应此召唤将使一名特工直接进入马迪亚斯·肖尔大师麾下效力。",h="这项指令旨在将艾尔文森林中前途无量的年轻潜行者直接召集到暴风城秘密情报网络的核心。在闪金镇的科瑞恩·塞尔留斯指导下，特工们被命令立即向旧城区的“剃刀”雷吉克报到。响应此召唤将使一名特工直接进入马迪亚斯·肖尔大师麾下效力。",kw={"科瑞恩·塞尔留斯","马迪亚斯·肖尔","旧城区","“剃刀”雷吉克","潜行者","哨兵岭","si:7","暴风城"},ang={["class:Rogue"]="这次召唤标志着你从一名从事当地杂活的流氓，转变为暴风城官方情报部门认可的特工。",["faction:Alliance"]="SI:7作为联盟的秘密盾牌，负责处理那些常规元帅和步兵无法公开执行的危险间谍行动。"},sec={{t="前往旧城区的召唤",b="潜行者训练师科瑞恩·塞尔留斯在闪金镇的狮王之傲旅店开展工作，密切关注当地的新兵。当一名潜行者在应对聚集的迪菲亚威胁时展现出足够的狡黠和能力，塞尔留斯就会传达来自总部的消息。召唤简短而不拘礼节：立即向“剃刀”雷吉克报到。特工将离开艾尔文森林的田野，直接被指派前往首都的秘密核心。"},{t="暴风城的隐形之眼",b="在旧城区一座毫不起眼的军营外表下，隐藏着暴风城首席情报机构——SI:7的总部。在马迪亚斯·肖尔大师的指挥下，SI:7负责管理整个王国及其周边的秘密行动、侦察和暗杀任务。“剃刀”雷吉克是肖尔言辞犀利的副官，他会亲自审核有前途的外勤特工，然后再将他们派遣去执行那些王国正规军无法触及的高风险行动。"}},faq={{q="是谁派我向SI:7报到的？",a="闪金镇狮王之傲旅店的潜行者训练师科瑞恩·塞尔留斯会给你这项指令。一旦你在外勤中证明了自己的能力，塞尔留斯就会传达命令，指示你前往暴风城的总部报到。",al={"谁发布任务","任务发布者","科瑞恩·塞尔留斯"}},{q="“剃刀”雷吉克是谁？",a="“剃刀”雷吉克是一位地精特工，担任SI:7的副官，直接在马迪亚斯·肖尔大师手下工作。他负责评估外勤特工，并从位于旧城区的SI:7总部协调秘密情报任务。",al={"“剃刀”雷吉克","谁是雷吉克","雷吉克"}},{q="什么是SI:7？",a="SI:7——即暴风城情报局——是暴风城王国的秘密间谍、侦察和暗杀部门。在马迪亚斯·肖尔的领导下，其特工负责收集针对王权威胁的情报，这些威胁是常规卫兵和士兵无法处理的。",al={"什么是si:7","si:7是做什么的","暴风城情报局"}},{q="SI:7总部位于哪里？",a="SI:7总部位于暴风城的旧城区东部。它在一座隐藏于主干道之外的坚固行会大厅和训练营中运作。",al={"si:7在哪里","si:7位置","雷吉克在哪里"}},{q="向雷吉克报到后会发生什么？",a="一旦你向雷吉克报到，他会测试你的准备情况，然后才会分配给你一项城墙之外的外勤任务，派遣你去见一位驻扎在赤脊山的特工。",al={"下一个任务","接下来要做什么","赤脊山会合"}},{q="为什么科瑞恩·塞尔留斯叫我“菜鸟”？",a="这是指未受考验的新手或新兵的俚语。该机构内部的特工会使用生动且刺耳的昵称，以让新兵在通过真实任务证明自己之前保持谦逊。",al={"为什么叫我菜鸟","菜鸟的含义"}}},fx={d2c94cb8={q="科瑞恩·塞尔留斯为什么派我去SI:7？",a="科瑞恩·塞尔留斯是在执行高层的命令。“剃刀”雷吉克特意传来消息，说他正在找你，而科瑞恩很清楚，马迪亚斯·肖尔的副手发来的召令绝不能置之不理。在暴风城情报机构的秘密指挥体系中，只要雷吉克召见一名特工，科瑞恩这样的中间人就会立刻传达命令，不让总部久等。",al={"科瑞恩为什么派我","科瑞恩·塞尔留斯的动机","为什么向si7报到"}},fe886311={q="SI:7为什么需要我，而不派自己的特工？",a="“剃刀”雷吉克指名要你前去。作为联盟网络中一名崭露头角的潜行者，你是尚未进入当地敌人视线的新生力量。肖尔大师和雷吉克经常依靠能干且刚刚证明过自己的外勤特工，在王国各地执行秘密任务，因为那些经验丰富的熟面孔可能会招来不必要的注意。",al={"si7为什么选我","雷吉克为什么找我","为什么召见我"}}},fp="4,166,21.292.0,23.413.0,31.202.0,25.204.0,13.239.0,39.159.0,39.136.1,38.183.0"}
P.entries["quest:233"] = {n="寒脊山谷的送信任务",s="在安威玛尔，斯登·粗臂派你向西出发，为冰湖另一边的斥候送信。积雪和附近的穴居人可能切断山谷守卫与外界的联系，让重要消息无法送达。",h="在安威玛尔，斯登·粗臂派你向西出发，为冰湖另一边的斥候送信。积雪和附近的穴居人可能切断山谷守卫与外界的联系，让重要消息无法送达。",kw={"安威玛尔","寒脊山谷","丹莫罗","格瑞林·白须","送信","斯登·粗臂","塔林·锐眼"},ang={["faction:Alliance"]="身为联盟的一员，你帮助寒脊山谷的各处哨站保持联系，这对协调丹莫罗的防御至关重要。",["race:Dwarf"]="身为矮人，你在哨站之间传递消息，帮助铁炉堡驻扎在偏远山谷中的斥候与各自的氏族保持联系。",["race:Gnome"]="身为诺莫瑞根陷落后与盟友一同生活在丹莫罗的侏儒，传递消息有助于你赢得当地矮人守卫的信任。"},sec={{t="雪中信使",b="来自丹莫罗各地的信件经由山口送抵安威玛尔，冬日里的信使将信件留在这里，逐渐积攒起来。斯登·粗臂负责补给和警戒，因此由新兵沿西边的道路运送这些成捆的信件。没有你的帮助，重要的信件就只能留在大厅里。"},{t="边境哨站",b="塔林·锐眼在安威玛尔以西的冰湖边监视穴居人的动向和危险的野兽。即使身处寒冷的哨站，铁炉堡和周边营地的消息也同样重要。山区环境恶劣，分拣邮件并不容易，因此寄给不同斥候的信件可能会混在同一捆里。"}},faq={{q="送信任务由谁发起？",a="斯登·粗臂在安威玛尔外将送信任务交给你。信件刚刚经由山口送来，但他职责在身，无法亲自送信。",al={"任务给予者","寒脊山谷送信任务由谁给予","斯登·粗臂任务"}},{q="塔林·锐眼在哪里？",a="塔林·锐眼在安威玛尔以西扎营，就在寒脊山谷冰湖附近的路边。",al={"塔林·锐眼在哪里","塔林·锐眼位置","寻找塔林·锐眼"}},{q="这摞信真的全是寄给塔林的吗？",a="不是。塔林发现其中有一封信是寄给格瑞林·白须的，他就驻守在山谷中附近的地方。",al={"信件全是寄给塔林的吗","格瑞林·白须的信","送错的信件"}},{q="为什么斯登需要冒险者帮忙送信？",a="穴居人的入侵和当地的威胁让斯登与其他矮人守卫忙于补给和警戒。旅人和新兵可以帮忙把信件送到偏远的哨站。",al={"为什么要送信","斯登为什么不亲自送信","送信职责"}},{q="这个任务会引出其他任务吗？",a="会。送达信件后，塔林会请你把那封送错的信转交给格瑞林·白须，继续送信。",al={"下一个任务","送信任务链","送信后续任务"}},{q="这些信件最初来自哪里？",a="这些信件来自丹莫罗各地和铁炉堡，经由山口进入寒脊山谷。",al={"信件来自哪里","信件来源"}}},fx={bf556c8e={q="斯登·粗臂为什么要把信送出去？",a="一捆新信件刚刚经过山口送达，但斯登在安威玛尔有自己的职责要忙，无法抽身亲自送信。他不愿让重要消息和公文堆着积灰，让野外的巡山人苦等音讯，因此要依靠一位热心的旅人，沿路将信件安全送达。",al={"为什么送信","斯登·粗臂的动机","为什么投递邮件"}}},fp="30,181,21.258.0,17.299.0,29.159.0,31.99.0,52.86.1,49.173.0,36.124.1,43.108.0"}
P.entries["quest:234"] = {n="寒脊山谷的送信任务",s="在寒脊山谷，一封公函从塔林·锐眼的哨所送往格瑞林·白须的营地。你沿着东南方的道路送信，让巡山人与铁炉堡保持联系。",h="在寒脊山谷，一封公函从塔林·锐眼的哨所送往格瑞林·白须的营地。你沿着东南方的道路送信，让巡山人与铁炉堡保持联系。",kw={"寒脊山谷","信使","丹莫罗","格瑞林·白须","铁炉堡","送信","塔林·锐眼"},ang={["faction:Alliance"]="身为联盟的一员，你依靠穿过积雪隘道的信使路线，将命令和重要情报送到偏远地区的斥候手中。",["race:Dwarf"]="身为矮人，你依靠King Magni在铁炉堡的王座传来的公函，协调丹莫罗的防务。"},sec={{t="通往山中的纽带",b="安威玛尔是寒脊山谷的行政中心。野外的斥候和哨兵从那里出发，沿着山间小径，在高处的隘口与铁炉堡之间传递公函。"},{t="捎给白须的消息",b="格瑞林·白须驻守着塔林·锐眼哨所东南方的一处小营地。这些偏远哨所里的老练巡山人，既要面对冰冷的积雪，也要应付穴居人持续不断的骚扰。定期送来的信件让他们了解丹莫罗各地以及王国其他地方的近况。"}},faq={{q="格瑞林·白须是谁？",a="格瑞林·白须是一位矮人老兵，驻守在寒脊山谷东南方道路旁的一处哨站。他监视道路，防范穴居人和野兽。",al={"格瑞林","格瑞林·白须的信息","格瑞林是谁"}},{q="这封信从哪里寄来？",a="这封信来自矮人的首都铁炉堡。当地的信使和哨兵带着它穿过寒脊山谷，沿山间隘道下行，将它送到收信人手中。",al={"信从哪里来","铁炉堡的信","寄信人"}},{q="这里为什么靠步行送信？",a="寒脊山谷四周的山峰阻隔了通往丹莫罗主要道路的交通，因此信使只能步行送信。值得信赖的旅人和巡山人亲手将公函送到野外营地。",al={"为什么步行送信","为什么跑着送信","寒脊山谷没有邮箱"}},{q="格瑞林·白须的营地在哪里？",a="格瑞林·白须的营地位于穿过寒脊山谷的东南方道路更深处，要先经过上方隘口的狩猎和侦察区域。",al={"格瑞林的营地在哪","格瑞林·白须的位置","寻找格瑞林"}},{q="是谁把送给格瑞林的信交给你的？",a="驻守在隘道沿线的猎人兼斥候塔林·锐眼把信交给了你。这封信是从安威玛尔附近的集结地送来的。",al={"谁给的信","塔林·锐眼的职责","谁提供任务"}},{q="格瑞林收到信后会做什么？",a="格瑞林收到铁炉堡的消息后，便着手应对山谷中的危险。他经常指派新兵对付霜鬃巨魔和穴居人。",al={"送信后做什么","格瑞林的下一个任务","送信之后"}}},fx={c573251b={q="塔林·锐眼为什么想让人办这件事？",a="塔林·锐眼驻守在寒冷的路边，知道格瑞林·白须一直在营地等候，却迟迟没有消息。塔林接过从安威玛尔送来的信件后，希望确保这位矮人同胞终于能收到铁炉堡的来信，不再困在山谷里，对外面的消息一无所知。",al={"塔林为何需要送信","塔林·锐眼的动机","为何给格瑞林送信"}},d47c3713={q="塔林·锐眼为什么请你送信，而不亲自去？",a="塔林·锐眼在寒脊山谷的道路旁站岗，监视着小径和当地的野生动物。如果他擅离职守，一路走到格瑞林·白须的营地，山口就会无人看守，因此，像你这样路过的旅人自然就成了送完这段路的合适人选。",al={"塔林为何需要我","塔林为何不能亲自送信","塔林为何选我"}}},fp="30,185,22.157.0,19.257.0,25.155.0,32.162.0,35.200.0,42.147.0,47.130.0,44.144.0"}
P.entries["quest:235"] = {n="灰谷狩猎",s="公告员高拉克派遣部落成员北上灰谷，加入狩猎。前往碎木岗哨向塞娜尼·雷心报到，部落正从那里将疆界推进这片古老的森林。",h="公告员高拉克派遣部落成员北上灰谷，加入狩猎。前往碎木岗哨向塞娜尼·雷心报到，部落正从那里将疆界推进这片古老的森林。",kw={"灰谷","贫瘠之地","高拉克","狩猎","奥格瑞玛","塞娜尼","碎木","雷心"},ang={["class:Hunter"]="作为猎人，当你响应塞娜尼·雷心的召唤时，灰谷茂密的林冠和危险的野兽将成为磨炼身手的试炼场。",["faction:Horde"]="作为部落的一员，你将部落的势力从杜隆塔尔向外延伸，深入资源丰富却充满敌意的异域。",["race:Tauren"]="作为牛头人，你可以在塞娜尼·雷心的指引下，怀着对伟大狩猎的深切敬意，踏入这片未经驯服的森林。"},sec={{t="荒野的召唤",b="奥格瑞玛需要木材、肉食和安全的商路，才能继续发展。公告员高拉克传达部落最高指挥部的命令，派遣老练的游历者和初出茅庐的冒险者奔赴各处战场。对于在杜隆塔尔和贫瘠之地成长起来的人来说，灰谷是下一场考验身手与生存本领的试炼。"},{t="危机四伏的边疆",b="在贫瘠之地以北，部落在灰谷拥有两处据点。碎木岗哨位于东部林地，佐拉姆加前哨站则坐落在西部海岸。塞娜尼·雷心在碎木岗哨协调行动，组织追踪者和猎人，应对林冠下的野兽，以及不肯承认部落领土主张的暗夜精灵哨兵。"}},faq={{q="谁给予这个任务，在哪里能找到？",a="公告员高拉克在部落首都奥格瑞玛下达命令。他召集有能力的冒险者，前往杜隆塔尔以外的地方参与战事。",al={"任务给予者","高拉克在哪里","谁给予灰谷狩猎任务"}},{q="碎木岗哨在哪里？",a="碎木岗哨位于贫瘠之地以北、灰谷东部，就在穿过森林、向东通往艾萨拉的主路旁。",al={"碎木位置","碎木岗哨在哪里","怎么去碎木"}},{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是驻守碎木岗哨的一位经验丰富的牛头人追踪者。她指挥灰谷各地的狩猎，并考核那些希望参加当地试炼的冒险者。",al={"塞娜尼是谁","塞娜尼·雷心位置","交任务的非玩家角色"}},{q="在灰谷狩猎有什么目的？",a="狩猎可以获取野味和珍贵的兽皮，还能清除威胁碎木岗哨附近巡逻队及周边伐木作业的顶级掠食者。",al={"为什么在灰谷狩猎","灰谷狩猎故事","部落在灰谷的目标"}},{q="部落在灰谷还拥有哪些前哨站？",a="部落还拥有佐拉姆加前哨站，它位于灰谷最西端的佐拉姆海岸。",al={"部落在灰谷的据点","佐拉姆海岸岗哨","灰谷前哨站"}},{q="这个任务涉及战斗吗？",a="不涉及。你从奥格瑞玛出发，穿过贫瘠之地，向塞娜尼·雷心报到；这段旅程本身不要求战斗。",al={"这个任务有战斗吗","需要战斗吗","只需交任务"}}},fp="18,185,17.300.0,22.367.0,48.124.0,27.113.0,27.165.0,42.163.0,53.95.0,35.123.0"}
P.entries["quest:2359"] = {n="克拉文之塔",s="密探吉尔妮在西部荒野的一处营地监视着克拉文之塔。诡异的货物与变异的守卫，表明迪菲亚潜行者内部暗藏危险。",h="密探吉尔妮在西部荒野的一处营地监视着克拉文之塔。诡异的货物与变异的守卫，表明迪菲亚潜行者内部暗藏危险。",kw={"密探吉尔妮","迪菲亚潜行者","暮色森林的箱子","克拉文·摩特维克","克拉文之塔","马迪亚斯·肖尔","毒药","si:7","西部荒野","赞吉尔"},ang={["class:Rogue"]="身为联盟潜行者，你将执行一次秘密潜入行动，需要运用潜行、偷窃和开锁技巧，并找出敌人身体上的弱点。",["faction:Alliance"]="克拉文之塔的迪菲亚与丛林巨魔联手，借助邪恶的炼金术威胁王国。他们早已不只是心怀不满的石匠。",["race:Human"]="身为守卫暴风城的人类，你若发现昔日的同胞在西部荒野被变成了没有思想的亡灵奴仆，或许会感到惊骇。"},sec={{t="西部荒野的监视行动",b="在西部荒野的东南边缘，河流从克拉文之塔下方流过，塔楼位于匕首岭以北。迪菲亚潜行者占据着这座石塔，而他们手下的人类盗贼和强盗则遍布平原。密探吉尔妮已独自监视这座塔数周。最近，她发现了怪事：一批诡异的货物直接从暮色森林阴暗的林地运来，护送货物的哨兵畸形可怖，与寻常拦路强盗截然不同。"},{t="高塔与尖刺守卫",b="克拉文·摩特维克掌管着这座塔，塔内变异的哨兵呼吸粗重，艰难地喘着气。在步履蹒跚的守卫中，一具魁梧的僵尸带着迪菲亚塔楼钥匙。要拿到钥匙，必须悄无声息，手法娴熟。有了钥匙，特工就能绕过地面的防御，抵达据点上层，打开挂着锁的暮色森林的箱子。"},{t="赞吉尔的药剂",b="克拉文·摩特维克的私人日记揭示了迪菲亚、荆棘谷地精与荆棘谷丛林巨魔之间的联系。日记记载，巫医赞吉尔发现了一种炼金毒药，能制造出没有思想、唯命是从的亡灵奴仆。对马迪亚斯·肖尔和SI:7而言，这一发现揭露了迪菲亚日益膨胀的野心。他们的特工必须充分掌握毒药知识。"}},faq={{q="克拉文之塔位于何处？",a="克拉文之塔耸立在西部荒野东南边缘的河流附近，位于匕首岭以北。迪菲亚潜行者占据着这座防守严密的高塔。",al={"克拉文之塔位置","克拉文之塔在哪里","西部荒野迪菲亚塔楼位置"}},{q="密探吉尔妮是谁？",a="密探吉尔妮效力于暴风城的情报机构SI:7。数周以来，她一直从附近的营地秘密监视克拉文之塔，追踪诡异的货物，并策划潜入行动。",al={"密探吉尔妮","谁提供克拉文之塔任务","西部荒野的潜行者是谁"}},{q="克拉文之塔的守卫有何异常？",a="塔楼的哨兵是经过改造的亡灵，与迪菲亚惯用的人类强盗不同。一种运入西部荒野的奇异炼金药剂将他们变成了没有思想的劳工。",al={"守卫为何是僵尸","克拉文塔楼守卫","塔楼守卫是什么"}},{q="迪菲亚为何拥有亡灵仆从？",a="迪菲亚从荆棘谷的丛林巨魔巫医赞吉尔那里获得了一种特制的毒性药剂。这种毒药通过与荆棘谷地精的交易流入他们手中，能将活生生的受试者变成唯命是从的奴仆。",al={"迪菲亚如何获得僵尸","迪菲亚为何拥有亡灵","赞吉尔与迪菲亚的联系"}},{q="克拉文·摩特维克是谁？",a="克拉文·摩特维克是驻守塔楼的一名迪菲亚高阶监工。他监督来自暮色森林的邪恶货物运输，并在私人日记中记下了他们阴险的炼金术。",al={"克拉文·摩特维克背景故事","克拉文·摩特维克是谁","克拉文"}},{q="马迪亚斯·肖尔为何关心找回的日记？",a="马迪亚斯·肖尔需要掌握有关迪菲亚盟友及危险外来特工的有用情报。赞吉尔的巨魔能用毒药制造亡灵，这一消息让SI:7意识到暴风城正面临严重威胁。因此，这个机构必须训练特工掌握制毒技艺。",al={"马迪亚斯·肖尔为何要日记","军情七处 赞吉尔毒药","马迪亚斯·肖尔 克拉文"}}},fx={af44437f={q="密探吉尔妮为什么想让人办这件事？",a="密探吉尔妮已经在克拉文之塔外监视了数周，追踪迪菲亚的动向。当一批诡异的货物在非人怪物的护送下从暮色森林运来时，她就知道这个兄弟会藏着危险的东西。她在SI:7的职责是监视和收集情报；查明那个上锁的箱子里究竟藏着什么，就能揭露迪菲亚在暴风城眼皮底下策划的阴险勾当。",al={"吉尔妮的动机","密探吉尔妮为何需要这个","吉尔妮的理由"}},["043ff283"]={q="迪菲亚塔楼钥匙有什么用？",a="迪菲亚塔楼钥匙能让你进入防守严密的据点，并打开里面受到看守的暮色森林货箱。钥匙由一只在外围巡逻、浑身尖刺的畸形怪物携带，是你打开迪菲亚的锁、调查那些古怪盟友究竟向西部荒野偷运了什么的唯一途径。",al={"迪菲亚塔楼钥匙","用什么打开克拉文之塔","塔楼钥匙的用途"}},d5d17d25={q="克拉文·摩特维克的日记是什么？",a="这本日记锁在塔顶的暮色森林货箱里，记载着克拉文·摩特维克的记录与秘密。它详细描述了迪菲亚潜行者如何与外部势力合作，调制邪恶的药剂，并揭露赞吉尔手下巨魔提供的奇异药水能使人陷入活死人的状态，成为唯命是从的傀儡。",al={"克拉文·摩特维克的日记","克拉文的日记","日记里有什么"}},["738a266c"]={q="密探吉尔妮为什么派你去，而不亲自行动？",a="密探吉尔妮是SI:7的斥候，主要任务是长期侦察。如果她暴露身份，强闯一处遍布非自然守卫的坚固据点，就会危及自己的监视哨，并在SI:7查明迪菲亚的计划之前惊动他们。她需要一名能干的特工潜过哨兵，取得情报，并直接交给马迪亚斯·肖尔。",al={"克拉文之塔为何选我","吉尔妮为何不亲自潜入","为何派我去"}}},fp="14,146,22.434.0,30.342.1,19.366.2,32.145.0,21.189.0,48.164.1,41.214.1,23.160.0,55.252.1"}
P.entries["quest:2360"] = {n="Mathias and the Defias",s="军情七处报告称，西部荒野的迪菲亚活动异常猖獗。你奉命前往一座废弃的联盟瞭望塔附近，接受密探吉尔妮的汇报。",h="军情七处报告称，西部荒野的迪菲亚活动异常猖獗。你奉命前往一座废弃的联盟瞭望塔附近，接受密探吉尔妮的汇报。",kw={"密探吉尔妮","迪菲亚","马西亚斯","赤脊山","哨兵岭","军情七处","瞭望塔","西部荒野"},ang={["faction:Alliance"]="迪菲亚占据了西部荒野一座废弃的联盟瞭望塔，并将其用作走私据点。"},sec={{t="瞭望塔",b="迪菲亚占据了哨兵岭东南方一座废弃的联盟瞭望塔。军情七处报告称，他们正以此为据点，走私来自赤脊山补给线的货物。你奉命前往西部荒野，找到藏身在塔附近的密探吉尔妮，听取她的汇报。"}},faq={{q="西部荒野发生了什么？",a="军情七处报告称，西部荒野的迪菲亚活动异常猖獗。迪菲亚占据了一座废弃的联盟瞭望塔，并利用它走私来自赤脊山补给线的货物。",al={"西部荒野的迪菲亚","西部荒野迪菲亚活动"}},{q="迪菲亚的据点在哪里？",a="迪菲亚占据了哨兵岭东南方一座废弃的联盟瞭望塔。",al={"迪菲亚瞭望塔","他们的据点在哪里"}},{q="密探吉尔妮是谁？",a="密探吉尔妮是军情七处派驻此地的密探，你奉命前往塔附近找到她，听取汇报。",al={"吉尔妮","吉尔妮是谁"}},{q="军情七处要我做什么？",a="军情七处派你前往西部荒野，找到藏身在塔附近的密探吉尔妮，听取汇报。",al={"军情七处任务","寻找吉尔妮"}},{q="迪菲亚在走私什么？",a="迪菲亚正在走私来自赤脊山补给线的货物。",al={"迪菲亚货物","赤脊山补给"}}},fp="22,143,15.264.0,30.173.0,25.80.0,21.85.0,29.98.0,30.62.0"}
P.entries["quest:237"] = {n="保卫国王的领土",s="在洛克莫丹南部，巡山人格拉维戈正寻求援助，对抗碎石穴居人。矮人部队已投入联盟前线，当地哨站只能依靠志愿者坚守防线。",h="在洛克莫丹南部，巡山人格拉维戈正寻求援助，对抗碎石穴居人。矮人部队已投入联盟前线，当地哨站只能依靠志愿者坚守防线。",kw={"碎石怪","铁炉堡","洛克莫丹","巡山人","先知","头骨重锤","碎石","穴居人","国王谷"},ang={["faction:Alliance"]="这项任务展现了联盟各处战事所付出的代价。当联盟的部队在遥远的土地上巩固控制时，其成员自己的家园却无力抵御当地的威胁。",["race:Dwarf"]="身为矮人，保卫国王谷与你息息相关。这里纪念着铁炉堡最伟大的统治者，而当你的同胞在遥远的战场上流血时，穴居人却在亵渎这片土地。这实在令人难以接受。"},sec={{t="薄弱的防线",b="守卫通往丹莫罗南部隘口的巡山人兵力捉襟见肘。国王麦格尼·铜须已将铁炉堡的大批兵力派往联盟各处前线，导致国王谷的哨塔缺少正规步兵。因此，巡山人格拉维戈号召志愿者进攻碎石怪之谷，遏制穴居人的攻势。援军也许永远不会到来。"},{t="碎石的萨满祭司与斗士",b="碎石穴居人既非没有头脑，也非漫无目的。他们的战团以蛮力和粗浅的元素魔法作战。格拉维高 希望将他们久经沙场的 头骨重锤，以及凭借神秘力量统领族人的 先知 逐出战斗。失去这些首领，部族南部的营地就会陷入混乱，无法集结兵力进攻通往铁炉堡的道路。"},{t="前线噩耗",b="当你回来复命时，格拉维高 带来了一个坏消息。先前承诺的矮人援军不会来了。联盟遥远前线的惨重损失耗尽了铁炉堡的后备兵力，保卫洛克莫丹的重任落在了当地巡山人和过路的佣兵肩上。"}},faq={{q="巡山人格拉维戈在哪里？",a="巡山人格拉维戈位于穿过国王谷的道路旁，在南边的哨塔驻守。他守卫着洛克莫丹与丹莫罗之间的隘口。",al={"格拉维戈 位置","格拉维戈 在哪里","向 格拉维戈 交任务"}},{q="矮人巡山人为何如此缺乏人手？",a="国王麦格尼·铜须已将铁炉堡的大部分常备军派往联盟各处前线。随着前线伤亡不断增加，洛克莫丹的边境哨站只剩下维持运转的少量人手，必须依靠过路的志愿者。",al={"为何没有矮人守卫","援军在哪里","铁炉堡军队 洛克莫丹"}},{q="在哪里能找到 碎石头骨重锤 和 先知？",a="碎石头骨重锤 和 先知 主要聚集在国王谷以东、碎石怪之谷南部的营地中。还有一些出没于洛克湖最北端的岛屿上。",al={"碎石击颅者位置","碎石先知 位置","穴居人在哪里"}},{q="为何专门针对 头骨重锤 和 先知？",a="头骨重锤 是碎石部族的突击部队，而 先知 使用粗浅的魔法，指挥地位较低的穴居人。击败这两者，就能削弱部族的战力，瓦解他们的协同作战能力。",al={"为何击杀 先知","为何针对 头骨重锤","穴居人目标"}},{q="格拉维戈 接下来会派你去哪里？",a="格拉维戈 会派你前往国王谷南部的哨塔，寻找巡山人沃尔班，协助保卫山谷。",al={"格拉维戈 后续任务","沃尔班 是谁","保卫国王的领土 之后"}}},fx={c78d8208={q="巡山人格拉维戈为什么希望你做这件事？",a="巡山人格拉维戈正试图为洛克莫丹的守军争取宝贵时间。碎石穴居人不断向南部山谷推进，而矮人士兵在联盟远方的战场上也同样急缺。通过削弱入侵者的兵力，他希望守住南部隘道，直到铁炉堡的援军赶到。",al={"为什么要杀穴居人","格拉维戈的动机","保卫国王领地的动机"}}},fp="30,199,14.366.0,34.347.0,27.248.1,39.150.0,48.213.0,61.184.0,48.179.0,35.130.1"}
P.entries["quest:2378"] = {n="寻找碎手氏族",s="在奥格瑞玛，碎手氏族正等待一名来自提瑞斯法林地、前途可期的被遗忘者盗贼。亡灵哨兵派这名新人渡海前往杜隆塔尔，向这个氏族学习专门的技艺。",h="在奥格瑞玛，碎手氏族正等待一名来自提瑞斯法林地、前途可期的被遗忘者盗贼。亡灵哨兵派这名新人渡海前往杜隆塔尔，向这个氏族学习专门的技艺。",kw={"暗影裂口","亡灵哨兵","米奈特·卡加德","奥格瑞玛","盗贼任务","碎手氏族","申苏尔"},ang={["class:Rogue"]="身为盗贼，你从本地训练迈入部落更广阔的犯罪与秘密活动网络，结识卡利姆多地下世界的训练师。",["faction:Horde"]="身为部落的一员，你见证了奥格瑞玛与幽暗城秘密机构之间的合作，这份合作延伸到了前线步兵与萨满祭司之外。",["race:Undead"]="身为一名初出茅庐的被遗忘者盗贼，你告别了洛丹伦当地的Scourge残余势力，来到杜隆塔尔，融入部落的腹地。"},sec={{t="暗影同盟",b="米奈特·卡加德见证了一名盗贼在提瑞斯法林地证明自己的实力。被遗忘者培养着自己的秘密组织亡灵哨兵，而他们与部落的联盟为学习更黑暗的技艺开辟了道路。他指引有潜力的盗贼前往奥格瑞玛寻找碎手氏族，将洛丹伦的亡灵特工与卡利姆多的兽人刺客联系起来。"},{t="深入暗影裂口",b="旅程的终点是奥格瑞玛地下的暗影裂口，术士、盗贼和恶魔束缚者在这里隐秘行事。碎手氏族的训练师申苏尔正在那里等候。这名粗鲁的巨魔以苛刻而怀疑的目光审视着初来乍到的亡灵特工。单凭名声无法让他满意；他想看看这名使者是否真有过人的狡黠，还是白白横渡了无尽之海。"}},faq={{q="谁提供寻找碎手氏族任务？",a="米奈特·卡加德是幽暗城潜行者区的一名亡灵哨兵训练师，待你在提瑞斯法林地证明自己掌握了基本技巧后，他便会派你出发。",al={"谁提供寻找碎手氏族","米奈特 卡加德任务","谁派往奥格瑞玛"}},{q="申苏尔在哪里？",a="申苏尔位于暗影裂口，那是奥格瑞玛中央道路下方的幽暗裂谷。",al={"寻找申苏尔","申苏尔位置","申苏尔在奥格瑞玛哪里"}},{q="亡灵哨兵与碎手氏族是什么关系？",a="亡灵哨兵是被遗忘者的情报网络和刺客公会，而碎手氏族在奥格瑞玛为部落承担着类似的职责。双方是正式盟友，在整个部落内部共享进阶训练和秘密委托。",al={"亡灵哨兵与碎手氏族","被遗忘者盗贼与兽人盗贼","为何被派往奥格瑞玛"}},{q="申苏尔为什么说我平庸无奇？",a="申苏尔说你平庸无奇，是因为碎手氏族看重强韧的体魄和冷酷的狡黠。他用侮辱打击新人的傲气，试探他们能否承受严苛的刺客训练。",al={"申苏尔对话","申苏尔为何刻薄","申苏尔任务完成文本"}},{q="找到申苏尔后会发生什么？",a="申苏尔先让你与赞杜沙共事，随后派你南下前往棘齿城，在贫瘠之地执行实地任务。",al={"寻找碎手氏族后续任务","申苏尔之后的任务","碎手氏族任务链"}},{q="非被遗忘者盗贼能接到这个任务吗？",a="不能。亡灵哨兵将这个版本的任务交给被遗忘者盗贼。杜隆塔尔的兽人和巨魔盗贼会接到一个作用相同的过渡任务，名为“去奥格瑞玛!”。",al={"兽人盗贼寻找碎手氏族","巨魔版本","去奥格瑞玛替代任务"}}},fp="23,206,19.336.0,24.387.0,44.142.0,26.88.0,74.255.0,38.209.0,37.114.0,39.148.0"}
P.entries["quest:2379"] = {n="赞杜沙",s="在奥格瑞玛的暗影裂口，有潜力的潜行者开始接受碎手氏族的训练。导师申苏尔派他选中的新兵去见赞杜沙，加入部落的秘密队伍。",h="在奥格瑞玛的暗影裂口，有潜力的潜行者开始接受碎手氏族的训练。导师申苏尔派他选中的新兵去见赞杜沙，加入部落的秘密队伍。",kw={"暗影裂口","开锁","奥格瑞玛","潜行者","碎手氏族","申苏尔","潜行","维尼克斯","赞杜沙"},ang={["class:Rogue"]="身为潜行者，你加入了碎手氏族的秘密队伍，从未经训练的持刀斗士成长为得到认可的部落特工。",["faction:Horde"]="碎手氏族负责部落的谍报与秘密行动，即便大酋长高谈荣誉与正面进攻，他们仍在防范那些潜藏的威胁，守护部落。"},sec={{t="步入暗影",b="奥格瑞玛的统治者深知，蛮力无法赢得每一场战争。在城市下方，暗影裂口是碎手氏族的据点，这个秘密公会为部落执行间谍、破坏和盗窃任务。潜行者导师申苏尔发现有潜力的新兵时，就会派他们向赞杜沙报到，接受专门的特工训练。"},{t="证明自己的价值",b="赞杜沙并不会对每个走进洞穴、缺乏经验的潜行者都另眼相看。与他见面，标志着正式开始研习更精深的秘密技艺，首先要学习潜行、诡计和偷窃。他的训练让粗野的街头扒手逐步成为有组织的情报特工，为潜行者走出都城红色峡谷壁垒的庇护、执行实地任务做好准备。"}},faq={{q="赞杜沙是谁？",a="赞杜沙是奥格瑞玛暗影裂口的一名潜行者导师，也是碎手氏族的特工负责人。他评估新兵，传授实用的潜行、入室盗窃和特工行动技巧。",al={"赞杜沙","赞杜沙是谁","赞道赞 暗影裂口"}},{q="申苏尔为什么派潜行者去见赞杜沙？",a="有潜力的潜行者需要接受碎手氏族特工的专门训练时，申苏尔就会派他们去见赞杜沙。赞杜沙负责指导入室盗窃和开锁课程，为秘密实地行动做准备。",al={"为什么要与赞杜沙交谈","申苏尔 赞杜沙","任务目的"}},{q="奥格瑞玛的碎手氏族是什么组织？",a="碎手氏族最初是来自德拉诺的一个残暴兽人氏族，以仪式性的自残闻名，后来演变为部落的秘密情报与暗杀机构。其成员在奥格瑞玛的暗影中活动，负责谍报、用毒和侦察。",al={"碎手氏族是什么","碎手氏族 奥格瑞玛","部落潜行者 碎手氏族"}},{q="这条训练任务线接下来通向哪里？",a="你向赞杜沙报到后，他会派你前往贫瘠之地海岸的棘齿城，与地精接头人维尼克斯会面，开始实地练习开锁。",al={"下一个任务","赞杜沙之后的任务","棘齿城的维尼克斯"}},{q="在哪里可以找到赞杜沙？",a="赞杜沙在暗影裂口活动，那是奥格瑞玛中心下方一片幽深的洞穴群。术士、暗影牧师和潜行者特工聚集在那里，避开日光。",al={"赞杜沙位置","赞杜沙在哪里","如何找到赞杜沙"}},{q="赞杜沙为什么一见面就向我道歉？",a="在你到来之前，赞杜沙或许曾怀疑你的胆量。看到你已准备好接受训练，他认可了你的决心，并收回最初的怀疑。",al={"赞杜沙为什么道歉","赞杜沙任务完成对话"}}},fp="9,145,23.316.0,19.351.0,17.182.0,47.156.0,40.245.0,41.164.1,27.176.0,45.149.0"}
P.entries["quest:2380"] = {n="向奥格瑞玛进发！",s="卡普拉克派一名年轻的潜行者从剃刀岭前往奥格瑞玛。在那里，你要在暗影裂口找到申苏尔，加入碎手氏族的情报网。",h="卡普拉克派一名年轻的潜行者从剃刀岭前往奥格瑞玛。在那里，你要在暗影裂口找到申苏尔，加入碎手氏族的情报网。",kw={"暗影裂口","卡普拉克","剃刀岭","潜行者","碎手氏族","申苏尔","前往奥格瑞玛"},ang={["class:Rogue"]="身为潜行者，你正进入申苏尔监管下的主城秘密网络。你的工作将从边境的小规模战斗，转向毒药、偷窃和欺骗。",["faction:Horde"]="身为部落的一员，你听闻了萨尔奉行荣誉的新道路与奥格瑞玛地下依然存续的旧氏族组织之间的摩擦。"},sec={{t="暗影的召唤",b="卡普拉克派你从剃刀岭北上，前往奥格瑞玛。你的身手虽初露锋芒、尚显生涩，却已引起更高层联络人的注意。你将杜隆塔尔的赤红山岩抛在身后，向主城进发。"},{t="萨尔的注视之下",b="申苏尔在奥格瑞玛地下的暗影裂口接见你。他不安地关注着大酋长萨尔的政治改革。碎手氏族无法仅凭蛮力或公开反抗来保护自身利益；它必须依靠耐心、诡计和欺骗，才能生存下去并保住影响力。"}},faq={{q="谁派我执行这个任务？",a="剃刀岭的潜行者训练师卡普拉克派你出发，因为你的身手引起了奥格瑞玛上级的注意。",al={"任务给予者","谁给予去奥格瑞玛任务","卡普拉克任务"}},{q="在哪里能找到申苏尔？",a="你可以在暗影裂口找到申苏尔，那是奥格瑞玛下方的一处地下城区，潜行者、术士和其他被放逐者聚集于此。",al={"申苏尔位置","申苏尔在哪里","暗影裂口申苏尔"}},{q="碎手氏族在奥格瑞玛有何图谋？",a="碎手氏族是部落内部从事情报与暗杀的公会。申苏尔对萨尔奉行荣誉的改革心存戒备，公会则依靠隐秘行动保住影响力并维持生存。",al={"碎手氏族动机","碎手氏族为何在奥格瑞玛","碎手氏族萨尔"}},{q="为什么偏偏在这个阶段派我前去？",a="你在基础侦察和小规模战斗中证明了自己的能力，因此开始承担更正式的公会职责。这些职责从主城中的开锁训练和秘密外勤开始。",al={"十六级潜行者任务","为何现在前往奥格瑞玛","潜行者训练召唤"}},{q="这个任务与“寻找碎手氏族”有何不同？",a="这两个任务都会引导潜行者前往奥格瑞玛寻找申苏尔。你接到哪一个，取决于你在哪里接受训练或听候差遣，两者推进的都是同一条训练任务线。",al={"寻找碎手氏族与去奥格瑞玛的区别","替代引导任务"}},{q="向申苏尔报到后会发生什么？",a="申苏尔会考验你的能力，并让你继续推进任务线。你会与赞杜沙等联络人见面，随后执行涉及棘齿城地精联络人的秘密任务。",al={"去奥格瑞玛后续任务","申苏尔给予什么任务"}}},fp="13,150,24.224.0,27.282.1,27.128.0,25.134.0,49.207.0,47.179.0,54.156.0,41.164.0"}
P.entries["quest:2381"] = {n="抢劫海盗",s="卑鄙的维尼克斯派遣新加入碎手氏族的潜行者，去对付棘齿城附近的南海海盗。在海浪剃刀号上，他们必须应付海盗、上锁的坚固箱和危险的守卫，才能取得南海宝藏。",h="卑鄙的维尼克斯派遣新加入碎手氏族的潜行者，去对付棘齿城附近的南海海盗。在海浪剃刀号上，他们必须应付海盗、上锁的坚固箱和危险的守卫，才能取得南海宝藏。",kw={"大饼干","开锁","抢劫海盗","波利","棘齿城","南海海盗","南海宝藏","蓟叶茶","海浪剃刀号","卑鄙的维尼克斯"},ang={["class:Rogue"]="作为潜行者，你会学着在压力下开锁，并获得蓟叶茶，这种珍贵的饮品深受效力于部落的特工青睐。",["faction:Horde"]="碎手氏族通过棘齿城的地精联络人，让有望加入的特工对付威胁贫瘠之地海岸的南海海盗，以此考验他们。",["profession:Cooking"]="作为对烹饪感兴趣的潜行者，你可以获得蓟叶茶，这种草药饮品因能恢复能量而备受重视。"},sec={{t="潜行与刀锋的考验",b="卑鄙的维尼克斯是棘齿城的一名地精联络人，负责考验有志加入碎手氏族的特工。他派潜行者沿贫瘠之地海岸南下，前往一处海湾，海浪剃刀号就停泊在那里，船员都是南海海盗。他们必须悄悄登船，进入扒手受训的海盗巢穴，撬开船舱里的坚固箱，再把赃物带回来。"},{t="波利与小装置",b="维尼克斯警告说，先前派去的盗贼都被切成碎块送了回来。一只名叫波利的凶猛鹦鹉守着船上最底层的船舱。为了帮助潜行者对付这只鸟，维尼克斯提供了一个实验性的大饼干。撬开海盗的坚固箱后，把它扔向波利；这个装置会让它晕头转向，削弱它的力量，让潜行者有机会赢得战斗。"}},faq={{q="卑鄙的维尼克斯是谁？",a="卑鄙的维尼克斯是棘齿城的一名地精潜行者联络人。他与奥格瑞玛的碎手氏族麾下的特工合作，派新手盗贼进入海盗领地，练习开锁并夺回被抢走的财物。",al={"维尼克斯","维尼克斯是谁","棘齿城地精潜行者任务"}},{q="海浪剃刀号在哪里？",a="海浪剃刀号停泊在棘齿城以南、贫瘠之地东海岸的一处南海海盗海湾。这艘船是海盗的据点，也是他们的训练场所。",al={"海浪剃刀号位置","海盗船在哪里","南海海盗在哪里"}},{q="大饼干是什么，该如何使用？",a="大饼干是一种实验性的地精装置，由维尼克斯的机械设备发放。用它对付波利，这只巨型鹦鹉在海浪剃刀号的船舱里守着南海宝藏；装置会削弱它，让你能够将其击败。",al={"大饼干","大饼干是什么","如何击败波利"}},{q="船上的开锁区域为何重要？",a="海浪剃刀号的第二层甲板是南海海盗的训练室。潜行者可以先用这里的锁箱实地练习开锁，再尝试打开下层的坚固箱。",al={"开锁练习","扒手训练船","贫瘠之地开箱练习"}},{q="这项任务为何对潜行者如此重要？",a="完成这次劫掠，就能向碎手氏族的联络网证明一名潜行者的价值。维尼克斯会给你蓟叶茶作为你应得的一份，这种饮品能迅速恢复潜行者在战斗中消耗的能量。",al={"潜行者蓟叶茶任务","为什么要做抢劫海盗","潜行者任务奖励"}},{q="波利是谁？",a="波利是一只凶恶的鹦鹉，替南海海盗守卫海浪剃刀号的下层船舱。如果没有地精技术削弱它，经验不足的潜入者就会命丧它的利爪。",al={"波利","巨型鹦鹉","海浪剃刀号首领"}}},fp="25,225,27.350.0,19.321.1,27.216.0,32.160.0,40.233.0,52.168.0,40.165.0,13.187.0"}
P.entries["quest:2382"] = {n="棘齿城的维尼克斯",s="在奥格瑞玛，棘齿城的维尼克斯将部落潜行者引向遥远南方的一座地精港口。赞杜沙派他们去帮助卑鄙的维尼克斯，那是一个住在棘齿城、声名狼藉的地精。",h="在奥格瑞玛，棘齿城的维尼克斯将部落潜行者引向遥远南方的一座地精港口。赞杜沙派他们去帮助卑鄙的维尼克斯，那是一个住在棘齿城、声名狼藉的地精。",kw={"棘齿城","潜行者","碎手氏族","贫瘠之地","萨尔","维尼克斯","赞杜沙"},ang={["class:Rogue"]="身为部落潜行者，你离开安全的奥格瑞玛，踏入中立的海盗领地，这是训练中必不可少的一步。",["faction:Horde"]="身为部落的一员，你知道碎手氏族的耳目遍布杜隆塔尔边境之外。它经常依靠棘齿城这样的中立港口处理机密委托。"},sec={{t="暗影中的先知",b="在奥格瑞玛的暗影裂口，潜行者公会在曲折的岩隙中活动，鲜有人察觉。赞杜沙是个说话颠三倒四的巨魔，他用不祥的预兆迎接前来的密探。在他的幻象中，大酋长萨尔倒在毒药与利刃之下。他没有解释这则预言，便匆匆将密探派往南方，前往贫瘠之地的港口小镇棘齿城。"},{t="棘齿城的解难人",b="棘齿城位于贫瘠之地的海岸，在十字路口以东。无赖、雇佣兵和工匠聚集在这座中立港口，卑鄙的维尼克斯也住在这里。维尼克斯对赞杜沙古怪的行事方式没什么耐心。他说，那个巨魔先前招募的人都在海湾里惨遭厄运，葬身于饥饿的掠食者腹中。"}},faq={{q="是谁派你去棘齿城的？",a="赞杜沙是奥格瑞玛暗影裂口中的一名碎手氏族巨魔，他脱口说出一些奇怪的幻象后，便派你南下。",al={"谁发布任务","任务给予者","赞杜沙"}},{q="卑鄙的维尼克斯是谁？",a="卑鄙的维尼克斯是棘齿城的一名地精联络人。他为贫瘠之地各处的潜行者处理秘密事务，并提供机械物资。",al={"维尼克斯是谁","维尼克斯 棘齿城","维尼克斯身份"}},{q="在我之前派去的密探怎么样了？",a="维尼克斯说，赞杜沙在你之前派去的五名密探都没能完成任务，成了棘齿城近海鲨鱼的食物。",al={"先前的潜行者","鲨鱼的食物","其他新兵"}},{q="赞杜沙说的那些关于萨尔的话是什么意思？",a="赞杜沙说，他看见萨尔被一把淬毒的匕首从背后刺倒，随后便突然打住，转移了话题。",al={"萨尔预言","萨尔中毒","赞杜沙 萨尔幻象"}},{q="棘齿城在哪里？",a="棘齿城坐落在贫瘠之地的东海岸，就在十字路口正东面。从怒水河向南延伸的道路将这里与杜隆塔尔相连。",al={"棘齿城在哪里","寻找棘齿城","棘齿城位置"}},{q="见过维尼克斯之后，接下来要做什么？",a="你向维尼克斯问候时，他会交给你“抢劫海盗”：潜入棘齿城以南沿岸的南海海盗之中。",al={"下一个任务","见过维尼克斯之后","棘齿城后续任务"}}},fp="17,171,24.337.0,24.316.0,25.123.0,27.129.0,47.121.0,50.124.0,25.150.0,37.153.1"}
P.entries["quest:2383"] = {n="简易羊皮纸",s="试炼谷有一封在你离开期间寄来的信，正等着你。你的职业训练师弗朗恩就在大兽穴外。",h="试炼谷有一封在你离开期间寄来的信，正等着你。你的职业训练师弗朗恩就在大兽穴外。",kw={"职业训练师","大兽穴","弗朗恩","羊皮纸","简易羊皮纸","试炼谷"},sec={{t="弗朗恩的来信",b="羊皮纸上的文字让你读完后去和弗朗恩谈谈。你的职业训练师正在试炼谷的大兽穴外等候。"}},faq={{q="谁寄来了这张羊皮纸？",a="这张羊皮纸似乎是你的职业训练师弗朗恩寄来的。",al={"羊皮纸寄件人","谁写的"}},{q="在哪里可以找到弗朗恩？",a="弗朗恩正在试炼谷的大兽穴外等候。",al={"弗朗恩在哪","弗朗恩位置"}},{q="弗朗恩有什么事？",a="等你准备好了，弗朗恩有话要对你说。",al={"弗朗恩找我何事","羊皮纸上的信息"}},{q="我该怎么处理这张羊皮纸？",a="读完羊皮纸，然后去试炼谷和弗朗恩谈谈。",al={"阅读羊皮纸","简易羊皮纸"}}},fp="16,121,20.128.0,23.66.0,23.52.0,21.43.0,36.66.0"}
P.entries["quest:239"] = {n="西泉要塞",s="在西泉要塞，瑞尼尔副队长和他的卫兵面临着越来越大的压力，却几乎没有多余的兵力。治安官杜汉将有空的冒险者派往西边，前往艾尔文森林与西部荒野交界处的哨所。暴风城的军队分散在王国各地，兵力捉襟见肘，要塞只能在没有定期增援的情况下应付河爪豺狼人和四处游荡的盗贼。",h="在西泉要塞，瑞尼尔副队长和他的卫兵面临着越来越大的压力，却几乎没有多余的兵力。治安官杜汉将有空的冒险者派往西边，前往艾尔文森林与西部荒野交界处的哨所。暴风城的军队分散在王国各地，兵力捉襟见肘，要塞只能在没有定期增援的情况...",kw={"瑞尼尔副队长","艾尔文森林","豺狼人","闪金镇","治安官杜汉","河爪","西泉要塞"},ang={["faction:Alliance"]="作为联盟的志愿者，你接过正规军的职责，帮助核心领地免于彻底陷入混乱。",["race:Human"]="作为暴风城的人类，你看到了王国疏于照管的令人不安的迹象。自国王失踪以来，王室的防御力量日渐薄弱。"},sec={{t="兵力吃紧的边境",b="西泉要塞守卫着艾尔文森林的西部边缘，这里是有人定居的林地与西部荒野动荡平原的交界处。沿着水道和西部道路活动的豺狼人战团与强盗日益猖獗，因此这座小要塞请求增派人手。治安官杜汉和闪金镇的行政官员没有多余的暴风城士兵可以调派。当地指挥官只能雇用过路的佣兵和四处游历的冒险者。"},{t="溪流对岸的威胁",b="瑞尼尔副队长和他的部下面对着不断骚扰旅人及附近农庄的河爪豺狼人。这群豺狼人出没于艾尔文和西部荒野之间的边境地带。暴风城被政治和军事上的麻烦牵制，豺狼人便进一步侵入有人居住的土地。西泉要塞阻挡着它们，以免它们长驱直入森林腹地。"}},faq={{q="暴风城为什么无法向西泉要塞派遣正规军？",a="暴风城的常备军分散在数处边境，兵力捉襟见肘。国王瓦里安·乌瑞恩失踪，王国内部纷争不断，最高统帅部拒绝或无力向乡间哨所派遣正规军。像杜汉这样的城镇治安官只能依靠自愿效力的自由冒险者。",al={"为什么没有暴风城部队","为什么派遣冒险者","暴风城军队在哪里"}},{q="西泉要塞位于哪里？",a="西泉要塞坐落在艾尔文森林的西部边缘。从闪金镇沿大路向西走，越过小溪。就在西部荒野边界之前，右手边便是那座设有防御工事的哨塔。",al={"西泉要塞位置","如何前往西泉要塞","瑞尼尔副队长在哪里"}},{q="哪些威胁正在困扰要塞？",a="瑞尼尔副队长不仅要应对河爪豺狼人的反复袭击，还要应付西部荒野与艾尔文森林交界地带日益猖獗的盗贼和强盗。",al={"什么在袭击西泉要塞","瑞尼尔为什么需要帮助","谁在袭击西泉要塞"}},{q="瑞尼尔副队长是谁？",a="瑞尼尔副队长是负责指挥西泉要塞的暴风城军官。他必须守住西部边境，而由于正规军的增援稀缺，只能依靠平民志愿者和佣兵。",al={"瑞尼尔背景故事","瑞尼尔副队长","瑞尼尔是谁"}},{q="向瑞尼尔副队长报到后会发生什么？",a="瑞尼尔副队长会请你协助对付当地的河爪豺狼人。他悬赏收集它们的项圈，以削减它们的数量，保护边境道路。",al={"接下来做什么","西泉要塞任务链","瑞尼尔任务"}},{q="豺狼人为什么向艾尔文森林进逼？",a="河爪豺狼人沿着分隔艾尔文和西部荒野的河流设有营地。边境驻军减少后，它们越发大胆，开始袭击商路，并向艾尔文腹地的农场进逼。",al={"河爪豺狼人 艾尔文","豺狼人为什么在这里","豺狼人问题"}}},fx={["76645dec"]={q="治安官杜汉为什么要你去西泉要塞？",a="治安官杜汉坐镇闪金镇，负责维护整个艾尔文森林的秩序与安全，但他手中的资源已经捉襟见肘。西泉要塞守卫着王国的西部边界，而瑞尼尔副队长已经发来急报，称匪患日益猖獗，豺狼人也在步步进逼。杜汉无正规军可派去增援，只能依靠独立行动的冒险者，在西部边境彻底失守之前，回应哨所的求援。",al={"为何派往西泉要塞","治安官杜汉的动机","西泉要塞为何需要帮助"}}},fp="30,367,25.395.0,27.357.0,64.289.0,36.195.0,40.157.0,21.205.0,46.153.0,46.211.0"}
P.entries["quest:2399"] = {n="发芽的树叶",s="在奥拉密斯湖畔德纳兰的花园里，种下的树叶已经生根发芽。旅人们可以在花圃间看到新长出的嫩叶。",h="在奥拉密斯湖畔德纳兰的花园里，种下的树叶已经生根发芽。旅人们可以在花圃间看到新长出的嫩叶。",kw={"德纳兰","草药学","花盆","种子","发光的树叶","发芽的树叶","泰达希尔","涌泉湖"},ang={["class:Druid"]="身为德鲁伊，你能从德纳兰的花盆中看到，悉心照料如何让生命蓬勃生长，即使泰达希尔正面临日益严峻的危机。",["profession:Herbalism"]="德纳兰的研究展现了采集和研究泰达希尔植物的实际工作，也展示了当地种子能多快适应经过照料的土壤。",["race:NightElf"]="身为一名kaldorei，你协助守护和培育那些在你们年轻的世界之树各处扎根的生命。"},sec={{t="奥拉密斯湖畔的花园",b="你在奥拉密斯湖附近找到了德纳兰的花园，这位植物学家在这里研究泰达希尔的奇异植物。种下一片发光的树叶后，新的树叶从他的花盆土壤中长出，等待采集和研究。"},{t="世界之树的奇异植物",b="泰达希尔年轻而庞大，树上的植物生长迅速。暗夜精灵草药师既为这种生长速度着迷，也为之担忧。发光的树叶及其新芽表明，生命能在世界之树的枝干上迅速扎根，但这股生命力有时难以预测。"}},faq={{q="发芽的树叶是什么？",a="德纳兰在奥拉密斯湖畔的营地种下一片发光的树叶，这些植物便从中萌发。这些奇异的树叶从中长出，到了可以采集的时候便会颤动。",al={"发芽的树叶","这些植物是什么","德纳兰的树叶"}},{q="德纳兰的花园在哪里？",a="德纳兰的花园和研究营地位于泰达希尔的奥拉密斯湖东岸，在多兰纳尔东南方。",al={"德纳兰位置","德纳兰在哪里","涌泉湖花园"}},{q="德纳兰为什么要种植这些树叶？",a="德纳兰研究泰达希尔植物奇特而迅速的生长现象。他将种子种进备好的土壤，借此了解这些植物，并检验它们是否具有实用的恢复功效或草药价值。",al={"为什么种植树叶","德纳兰的实验","树叶的用途"}},{q="发芽的树叶有危险吗？",a="没有。这些发芽的树叶是等待采摘的无害植物，与泰达希尔枝干上其他地方受到腐化或具有敌意的某些植物不同。",al={"树叶有危险吗","树叶会攻击吗","这种植物有害吗"}},{q="这个任务之前要做什么？",a="冒险者先在泰达希尔的荒野中找到一片发光的树叶，再将它带给德纳兰。他把它种在花园的花盆里，希望它能生根。",al={"发芽的树叶前置任务","先做哪个任务"}},{q="这些树叶为什么会颤动？",a="这些树叶在等待采摘时会颤动。颤动的原因尚不清楚。",al={"颤动的树叶","为什么会颤动"}}},fp="19,132,25.216.0,35.263.0,29.168.0,34.120.0,36.172.0,34.141.0,29.150.0,26.78.0"}
P.entries["quest:24"] = {n="萨杜布拉的头颅",s="这个任务证明了你已经击败了影爪，这只臭名昭著且凶猛的夜刃豹一直在灰谷的西部小径上徘徊。将这头野兽的断头带回给碎木岗哨的塞娜尼·雷心，不仅完成了灰谷狩猎的关键考验，还保障了通往佐拉姆海岸的旅行路线安全。",h="这个任务证明了你已经击败了影爪，这只臭名昭著且凶猛的夜刃豹一直在灰谷的西部小径上徘徊。将这头野兽的断头带回给碎木岗哨的塞娜尼·雷心，不仅完成了灰谷狩猎的关键考验，还保障了通往佐拉姆海岸的旅行路线安全。",kw={"灰谷狩猎","夜刃豹","塞娜尼·雷心","影爪","碎木岗哨","战利品","佐拉姆海岸"},ang={["class:Hunter"]="追踪并征服像影爪这样难以捉摸的夜刃豹，是对在茂密林地中进行射击、耐心和生存能力的终极考验。",["faction:Horde"]="碎木岗哨仍然是一个孤立的部落据点；消除像影爪这样的当地威胁，对于保持通往佐拉姆海岸的重要补给线畅通至关重要。",["race:Tauren"]="对于牛头人来说，猎杀影爪这种级别的野兽，既是通过挑战顶级掠食者来磨练技巧，又是在保护路上的族人，这符合大地母亲的自然法则。"},sec={{t="西部大道的威胁",b="影爪在灰谷的参天巨树间绝非普通的掠食者。这只强大的夜刃豹一直徘徊在碎木岗哨以西的荒野中，猎杀那些试图前往佐拉姆海岸的部落斥候和信使。它的速度、隐蔽性和纯粹的凶残使得步行旅行变得危机四伏，导致碎木岗哨的守军在巡逻队向西移动时总是提心吊胆。"},{t="狩猎的证明",b="作为灰谷狩猎的一部分，牛头人女猎手塞娜尼·雷心向部落的勇士们发起挑战，要求他们追踪并猎杀森林中的顶级野兽。上交影爪的头颅不仅仅是一种炫耀实力的冷酷展示，更证明了道路已经变得更加安全，且猎人已经征服了卡利姆多最致命的土生掠食者之一。"}},faq={{q="影爪是谁？",a="影爪是一只极其凶残的夜刃豹，它在那片碎木岗哨以西的森林中出没。由于它经常伏击那些前往海岸长途跋涉的旅人，它被认为是灰谷当地最危险的野兽之一。",al={"影爪是什么","影爪背景故事","那只猫是谁"}},{q="为什么塞娜尼·雷心想要这个头颅？",a="塞娜尼·雷心在碎木岗哨负责监管灰谷狩猎。要求得到这个头颅，既是将其作为一场出色狩猎的传统战利品，也是确认对前往西部旅人的威胁已被消除。",al={"为什么要带回头颅","塞娜尼·雷心战利品","灰谷狩猎证明"}},{q="这在灰谷狩猎中处于什么位置？",a="这是接受灰谷狩猎后启动的首要考验之一。击杀影爪，连同森林中的其他巨兽如乌萨诺斯和尖爪，将最终获得认可，并开启任务“狩猎完成”。",al={"什么是灰谷狩猎","狩猎任务线","下一个狩猎任务"}},{q="清除这头野兽对部落为什么很重要？",a="碎木岗哨依赖斥候和信使向西前往位于佐拉姆海岸的部落营地——佐拉姆加前哨站。影爪的掠食本性对通过这片荒野的部落步行交通构成了持续的威胁。",al={"部落为什么关心","佐拉姆海岸道路危险","碎木岗哨安全"}},{q="在哪里可以找到影爪？",a="影爪徘徊在碎木岗哨以西的林地中，在道路和散布于灰谷中西部地区的暗夜精灵古代遗迹之间的树林里游荡。",al={"影爪位置","影爪在哪里","寻找影爪"}},{q="影爪与暗夜精灵结盟了吗？",a="没有。虽然夜刃豹经常被暗夜精灵驯化和崇拜，但影爪是一头野性难驯、只凭原始掠食本能行事的恐怖森林野兽，威胁着任何进入它领地的生物。",al={"影爪是宠物吗","哨兵宠物","影爪暗夜精灵"}}},fp="16,210,28.231.0,17.250.0,18.190.0,43.175.0,44.180.0,50.182.0,29.181.0,41.175.0"}
P.entries["quest:240"] = {n="基特斯的美餐",s="你将厨师格鲁奥做的饭食带到乌鸦岭，交给基特斯。这些蛋糕终于让这位饥肠辘辘的隐士填饱了肚子。",h="你将厨师格鲁奥做的饭食带到乌鸦岭，交给基特斯。这些蛋糕终于让这位饥肠辘辘的隐士填饱了肚子。",kw={"厨师格鲁奥","夜色镇","暮色森林","黑蟹蛋糕","肚子咕咕叫","基特斯","血鸦旅店"},ang={["faction:Alliance"]="夜色镇匮乏而古怪的食物，反映出镇子与暴风城的补给几乎断绝。当地人只能依靠那些在阴影中爬行的东西维生。",["profession:Cooking"]="厨师格鲁奥将黏糊糊的毒网蜘蛛腿做成可口的蛋糕，展现了在边地做饭所需的应变本领。"},sec={{t="可疑的美味",b="厨师格鲁奥在血鸦旅店掌勺，暮色森林缺少牲畜和水产，他只能就地取材，利用这片凋敝森林中的食材。他的拿手菜黑蟹蛋糕里没有蟹肉。格鲁奥用的是林间毒网蜘蛛黏糊糊的腿。他称之为善用食材；肠胃娇弱的人恐怕不敢苟同。"},{t="安抚基特斯",b="在乌鸦岭，基特斯因恐惧而蜷缩着，无力面对那些将他逼出树林的可怕事物。恐惧让他不敢狩猎或采集食物，饥饿又加重了他的痛苦。温热的蛋糕让这个浑身颤抖的流浪汉得到了片刻难得的慰藉。他急于填饱肚子，没问格鲁奥用的是什么蟹就吃了下去。"}},faq={{q="黑蟹蛋糕里有什么？",a="黑蟹蛋糕里没有蟹肉。厨师格鲁奥用当地毒网蜘蛛黏糊糊的腿作食材，再用调味料调出传统海鲜蛋糕的风味。",al={"蟹肉蛋糕食材","黑蟹蛋糕用什么做的","用的是真蟹吗"}},{q="基特斯知道蛋糕是用蜘蛛黏液做的吗？",a="厨师格鲁奥对配方守口如瓶。基特斯又饿又怕，迫不及待地吃下蛋糕，根本没问里面有什么。",al={"基特斯知道吗","基特斯知道蜘蛛的事吗"}},{q="基特斯为什么无法自己寻找食物？",a="基特斯在暮色森林的荒林中遭遇了可怕的事物，从此被恐惧笼罩。他惊恐不安，不敢远离乌鸦岭，只能依靠好心的旅人为他提供食物。",al={"基特斯为什么挨饿","基特斯为什么不狩猎"}},{q="厨师格鲁奥是谁？",a="厨师格鲁奥在夜色镇的血鸦旅店掌勺。阴影与野兽使镇子与外界隔绝，他便用搜寻物资的人带来的非常规食材，为酒馆的客人做饭。",al={"厨师格鲁奥的职责","夜色镇的厨师"}},{q="这条任务线从哪里开始？",a="任务线始于饥肠辘辘，基特斯在乌鸦岭请求你帮他填饱肚子。随后，你要为厨师格鲁奥猎杀毒网蜘蛛，再把做好的饭食带回去。",al={"基特斯食物任务如何开始","基特斯任务线起点"}},{q="基特斯吃过东西后恢复了吗？",a="这顿饭让基特斯填饱了肚子，他由衷地向你道谢。食物无法缓解他内心深处的恐惧；他依然焦虑不安，被森林中的黑暗秘密所困扰。",al={"基特斯治好了吗","食物对基特斯有帮助吗"}}},fp="17,118,18.340.0,24.300.0,32.142.0,51.125.0,38.167.0,18.189.0,34.156.0,34.172.0"}
P.entries["quest:243"] = {n="进入沙漠",s="药剂师金格派你带着野外测试工具前往塔纳利斯沙漠，测试石化蜥蜴、蝎子和土狼的组织。改装过的工具还需要一种加基森地精手中的能源，因此药剂师金格指引你去找当地的首席工程师沙克斯·比格维兹。",h="药剂师金格派你带着野外测试工具前往塔纳利斯沙漠，测试石化蜥蜴、蝎子和土狼的组织。改装过的工具还需要一种加基森地精手中的能源，因此药剂师金格指引你去找当地的首席工程师沙克斯·比格维兹。",kw={"药剂师","石化蜥蜴","首席工程师沙克斯·比格维兹","加基森","土狼","能源","蝎子","塔纳利斯","测试工具","药剂师金格"},sec={{t="沙漠中的组织",b="药剂师金格想要测试沙漠中石化蜥蜴、蝎子和土狼的组织稠度。你收集样本，用随身携带的测试工具进行检测，不过相当一部分样本会不合格。每种生物都需要八份合格样本，药剂师金格要求你成功收集齐后再回来。"},{t="加基森的能源",b="改装过的工具必须配合一种加基森地精手中的能源使用。药剂师金格派你去加基森找首席工程师沙克斯·比格维兹，弄到一个。"},{t="没有免费的东西",b="首席工程师沙克斯·比格维兹很熟悉4711-FTZ型能源；它们通常用于驱动水井，而且拜那些可恶的游牧民所赐，眼下这类能源多得很。不管你想隐瞒什么邪恶实验，首席工程师沙克斯·比格维兹都会替你安排一个，但要收钱，因为加基森没有免费的东西。"}},faq={{q="是谁派你前往塔纳利斯进行这项研究？",a="药剂师金格，她交给你一套野外测试工具，希望你测试沙漠生物的组织。",al={"谁开启进入沙漠","谁给予进入沙漠","进入沙漠任务给予者"}},{q="为什么需要去见首席工程师沙克斯·比格维兹？",a="改装过的测试工具需要一种加基森地精手中的能源，要弄到一个，就得找首席工程师沙克斯·比格维兹。",al={"首席工程师沙克斯·比格维兹的作用","为何拜访首席工程师沙克斯·比格维兹","测试工具能源"}},{q="需要测试哪些野兽？",a="塔纳利斯沙漠中的石化蜥蜴、蝎子和土狼，每种都需要八份合格样本。",al={"待测试的野兽","进入沙漠生物种类","塔纳利斯组织样本"}}},fp="14,188,20.267.0,27.151.0,15.282.1,43.119.0,51.132.0,38.94.0"}
P.entries["quest:2438"] = {n="翡翠摄梦符",s="多兰纳尔的塔隆凯·捷根请求冒险者从他在星风村的废弃住所里取回一件珍贵的传家宝。翡翠摄梦符是他从德鲁伊守望者盖洛拉斯·塔文斯伦那里获得的礼物，当受到腐蚀的棘齿熊怪占领了这座宁静的定居点时，他被迫将其遗落。取回这件护身符可以防止它那温和的自然魔法落入邪恶之手。",h="多兰纳尔的塔隆凯·捷根请求冒险者从他在星风村的废弃住所里取回一件珍贵的传家宝。翡翠摄梦符是他从德鲁伊守望者盖洛拉斯·塔文斯伦那里获得的礼物，当受到腐蚀的棘齿熊怪占领了这座宁静的定居点时，他被迫将其遗落。取回这件护身符可以...",kw={"班奈希尔兽穴","多兰纳尔","翡翠梦境","翡翠摄梦符","熊怪","盖洛拉斯·塔文斯伦","棘齿熊怪","星风村","塔隆凯·捷根","泰达希尔"},ang={["class:Druid"]="这件护身符是盖洛拉斯·塔文斯伦的直接作品，他是照料你在班奈希尔兽穴中沉睡族人的守望者，因此找回此物关乎德鲁伊的荣誉。",["faction:Alliance"]="帮助多兰纳尔的流离失所的卡多雷能巩固当地局势，因为泰达希尔正饱受熊怪部落日益严重的腐蚀之苦。",["race:NightElf"]="星风村曾是你族人宁静的避风港。帮助塔隆凯找回他的遗产，是对席卷泰达希尔野生生物的疯狂行径的一次小小的反击。"},sec={{t="德鲁伊的护身符",b="翡翠摄梦符绝不仅仅是一件装饰性的饰品。它是盖洛拉斯·塔文斯伦赠予的礼物，此人是班奈希尔兽穴内沉睡德鲁伊的尊贵守望者。这件护身符旨在引导翡翠梦境中平静的流光。通过汲取这种纯净的精神能量，摄梦符能为佩戴者带来安宁与好运。这类信物极为罕见，只授予少数几位与森林守护事业息息相关的受托者。"},{t="逃离星风村",b="不久之前，星风村还是一座坐落在泰达希尔枝干间的宁静定居点。随着当地的棘齿熊怪陷入疯狂，暗夜精灵被迫逃离他们的家园，那种平静的生活便戛然而止。在撤离时的恐惧与混乱中，塔隆凯被迫将他最珍贵的财产留在了村庄东南角的梳妆台里，无力独自取回。"},{t="腐蚀的威胁",b="将一个翡翠梦境魔法的聚焦点留在一座被占领的村庄中心，有着极大的风险。棘齿熊怪已被证明容易受到黑暗力量的影响，而一件脉动着梦境能量的文物很容易被玷污或武器化。在熊怪或其他邪恶生物玷污其残留的魔法之前，将其安全取回，能把星风村的一部分遗产带回给塔隆凯。"}},faq={{q="什么是翡翠摄梦符？",a="这是一款罕见的护身符，由班奈希尔兽穴的德鲁伊守望者盖洛拉斯·塔文斯伦赠予塔隆凯。摄梦符能从翡翠梦境汲取能量，为佩戴者带来好运与精神上的和谐。",al={"什么是翡翠摄梦符","摄梦符背景故事","翡翠摄梦符"}},{q="为什么摄梦符会被留在星风村？",a="当当地的棘齿熊怪陷入疯狂且受到腐蚀的狂乱状态时，星风村迅速失陷。塔隆凯·捷根被迫逃亡多兰纳尔以求生，只能将那件珍贵的传家宝遗落在他的卧室梳妆台里。",al={"为什么把它留在那","星风村梳妆台","塔隆凯的梳妆台"}},{q="塔隆凯·捷根是谁？",a="塔隆凯是一位目前居住在多兰纳尔的暗夜精灵难民。在星风村沦陷后逃脱的他，正寻求勇敢的旅人前往被占领的废墟，找回他的传家宝并守护德鲁伊圣物。",al={"谁是塔隆凯","塔隆凯·捷根"}},{q="是谁制作了摄梦符？",a="塔隆凯只提到这是盖洛拉斯·塔文斯伦赠予的礼物，他是班奈希尔兽穴内监护沉睡德鲁伊的守望者；至于此物究竟由谁所制，从未提及。",al={"谁制造的","盖洛拉斯·塔文斯伦 摄梦符","盖洛拉斯"}},{q="摄梦符在星风村的什么位置？",a="它位于星风村最东南侧房屋内塔隆凯的私人梳妆台里，该区域现在正有大批敌对的棘齿熊怪游荡。",al={"梳妆台在哪里","星风村梳妆台位置","寻找摄梦符"}},{q="归还摄梦符后会发生什么？",a="当塔隆凯检查找回的护身符时，他发现上面的翡翠不见了，那是被棘齿熊怪首领“梦境吞噬者”费罗塞塔斯窃走的，这也直接引发了对他的追捕。",al={"任务后续","摄梦符之后的下一个任务"}}},fp="24,289,18.312.0,26.299.0,24.312.1,33.219.0,59.160.0,27.187.0,26.165.0,56.146.0,48.167.1"}
P.entries["quest:244"] = {n="豺狼人的入侵",s="“逼近的豺狼人”是一项联盟任务，旨在向湖畔镇的城镇卫兵发出警报，告知他们有豺狼人正在艾尔文森林边境附近危险地徘徊。卫兵帕克在边境通道沿线发现了聚集的营地，于是派遣路人前往提醒菲尔顿副队长。这个消息证实了湖畔镇日益增长的担忧：这些兽人正威胁着要将赤脊山彻底与外界隔绝。",h="“逼近的豺狼人”是一项联盟任务，旨在向湖畔镇的城镇卫兵发出警报，告知他们有豺狼人正在艾尔文森林边境附近危险地徘徊。卫兵帕克在边境通道沿线发现了聚集的营地，于是派遣路人前往提醒菲尔顿副队长。这个消息证实了湖畔镇日益增长的担...",kw={"评估威胁","菲尔顿副队长","艾尔文森林边境","逼近的豺狼人","卫兵帕克","湖畔镇","赤脊山"},ang={["faction:Alliance"]="湖畔镇的孤立威胁到了联盟的东部前线，这使得边境情报对于旅行者和补给车队至关重要。",["race:Human"]="兽人在艾尔文森林视线范围内的蚕食，突显了在国王缺席的情况下，王国核心领土变得多么脆弱。"},sec={{t="边境视线",b="连接艾尔文森林和赤脊山的道路本应是王国中最安全的交通路线之一，但暴风城稀薄的兵力使其几乎处于无人防守的状态。卫兵帕克驻扎在西部边境小径上负责监视动向。虽然他勉强维持了碎石路供补给车队通行，但他向北和向东的侦察却显示，豺狼人战团已经从山崖中推进，并在离道路惊人近的地方建立了营地。"},{t="受困的城镇",b="在湖畔镇大桥附近收到警报后，菲尔顿副队长意识到情况比预想的还要糟糕。赤脊山的豺狼人不仅仅是在袭击城镇周边；他们在艾尔文森林边境附近的靠前部署意味着他们可以包围湖畔镇并向王国的腹地推进。由于暴风城无视增援的请求，湖畔镇的守卫根本无法应对两线作战的威胁。"}},faq={{q="谁发放这个任务？",a="卫兵帕克在赤脊山西部、靠近艾尔文森林边境路口处的道路旁发放该任务。",al={"任务发放者","从哪里开始","卫兵帕克位置"}},{q="我在哪里能找到菲尔顿副队长？",a="菲尔顿副队长驻扎在湖畔镇，在城镇大石桥以南的地面巡逻。",al={"菲尔顿位置","菲尔顿副队长是谁","交付地点"}},{q="为什么道路上的豺狼人是个问题？",a="通往艾尔文森林的道路是湖畔镇与王国其他地区联系的唯一陆路生命线。如果豺狼人占领了西侧山坡，该镇将实际上被切断补给和逃生路径。",al={"豺狼人的重要性","赤脊山豺狼人问题","道路危险"}},{q="为什么暴风城不向湖畔镇派遣援助？",a="由于瓦里安·乌瑞恩国王失踪，王国局势紧张，伯瓦尔公爵和王庭拒绝向赤脊山派遣皇家部队，导致湖畔镇的防务完全留给了当地的副官和志愿者。",al={"暴风城卫兵在哪里","没有增援","湖畔镇防务"}},{q="报告豺狼人后的后续内容是什么？",a="菲尔顿副队长会让你在后续任务“评估威胁”中更近距离地侦察豺狼人营地，以确定它们数量的真实实力。",al={"下一个任务","任务链后续"}},{q="哪些豺狼人部族正在侵入这里？",a="赤脊山的豺狼人正聚集在山丘中形成赤脊山豺狼人部族，随着人类对该地区控制力的减弱，它们变得越来越大胆且协作紧密。",al={"哪些豺狼人","赤脊山豺狼人部族"}}},fp="18,234,18.369.0,18.363.0,22.120.0,31.94.0,40.176.0,45.206.0,40.125.0,39.148.0"}
P.entries["quest:245"] = {n="蜘蛛的威胁",s="暮色森林的西部边界挤满了毒网蜘蛛。守夜人道茨呼吁旅人削减它们的数量，以免更多守夜人守卫落入蛛网。",h="暮色森林的西部边界挤满了毒网蜘蛛。守夜人道茨呼吁旅人削减它们的数量，以免更多守夜人守卫落入蛛网。",kw={"夜色镇","暮色森林","八只脚的威胁","守夜人","幼小的毒网蜘蛛","蜘蛛","守夜人道茨"},ang={["class:Hunter"]="身为猎人，你将在暮色森林面对凶猛的毒网蜘蛛；谨慎走位并备好抗毒药剂，有助于你猎杀它们。",["faction:Alliance"]="守夜人得不到贵族的援助，因此，联盟旅人的支援有助于维持道路畅通。"},sec={{t="危机四伏的边界",b="幼小的毒网蜘蛛成群盘踞在从西部荒野通往暮色森林的西部道路旁的灌木中。茂密树冠下的灌木丛被蛛网塞满，威胁着旅人的安全，也危及守夜人薄弱的防线。"},{t="守夜人的重担",b="守夜人道茨驻守在远离夜色镇的一处小营地，手下的兵力不足以守住边界。亡灵和狼人正不断逼近镇子，指挥官阿尔泰娅·埃伯洛克无法派出援军。道茨已有同伴死于蜘蛛之手，他找到他们时，他们倒吊在树冠间，毒液麻痹了他们的身体，也将他们的血肉化为液体。"}},faq={{q="谁提供这个任务？",a="守夜人道茨是守夜人的一员，驻扎在暮色森林的一处小营地，请求旅人清除蜘蛛。",al={"任务给予者","谁提供八足的威胁","守夜人道茨"}},{q="守夜人为什么无法自行对付蜘蛛？",a="指挥官阿尔泰娅·埃伯洛克将为数不多的守军留在夜色镇附近，抵御亡灵接连不断的进攻。道茨兵力不足，无法在进攻边界蜘蛛巢穴的同时守住哨所。",al={"为何需要帮助","为何召集冒险者","夜色镇民兵短缺"}},{q="这些蜘蛛在哪里？",a="幼小的毒网蜘蛛成群出没在暮色森林西部的林地中，就在从西部荒野通来的大路旁的灌木里。",al={"蜘蛛位置","幼小毒网蜘蛛在哪","蜘蛛林地"}},{q="这些蜘蛛为何对守卫如此危险？",a="这些蜘蛛数量众多，毒液能麻痹身体、溶解血肉。落入蛛网的守夜人守卫无助地吊在枝头，沦为唾手可得的猎物。",al={"蜘蛛毒素","蜘蛛毒液","蜘蛛受害者"}},{q="暮色森林里只有这些蜘蛛吗？",a="不。幼小的毒网蜘蛛只是体型较小的幼蛛。森林深处还栖息着体型大得多、也更加致命的蜘蛛，威胁着过往旅人。",al={"暮色森林其他蜘蛛","蜘蛛种类","毒网蜘蛛"}},{q="昆虫和蜘蛛的数量为何增长得如此迅猛？",a="魔法腐化笼罩着暮色森林，扭曲了当地的野生动物，使它们更具攻击性、体型更大，也更加致命。",al={"为何蜘蛛这么多","暮色森林自然腐化","蜘蛛起源"}}},fp="20,182,20.221.0,29.325.0,22.106.0,56.174.0,32.106.0,51.148.0,39.145.0,63.137.0"}
P.entries["quest:2458"] = {n="卧底密探",s="申苏尔派一名有潜力的部落盗贼前往淤泥沼泽，联络潜伏在荆棘谷地精内部的密探。碎手氏族花了一年时间，将工头费苏勒安插进这家公司的钻探场，监视他们的计划。",h="申苏尔派一名有潜力的部落盗贼前往淤泥沼泽，联络潜伏在荆棘谷地精内部的密探。碎手氏族花了一年时间，将工头费苏勒安插进这家公司的钻探场，监视他们的计划。",kw={"贫瘠之地盗贼","深入敌后","信号枪","碎手氏族","申苏尔","淤泥沼泽","工头费苏勒","荆棘谷地精"},ang={["class:Rogue"]="身为部落盗贼，你正从街头侦察迈向受人信任的实地任务，在暗中与同伴配合。",["faction:Horde"]="身为部落的一员，你目睹荆棘谷地精的伐木和钻探活动威胁着部落在贫瘠之地的土地与资源。"},sec={{t="奸商中的密探",b="碎手氏族通过秘密情报活动和暗杀来维护奥格瑞玛的利益。一年来，其成员一直设法将一名密探安插进荆棘谷地精的队伍。工头费苏勒在淤泥沼泽以北的钻探哨站站稳了脚跟，混入了这家公司的雇佣兵之中。"},{t="暗号与信号",b="费苏勒 必须维持冷酷强硬的名声，才能让荆棘谷地精的监工满意。不速之客可能招来攻击。抵达他所在高塔的盗贼必须在他的视野内用信号枪发射两枚信号弹，悄悄靠近，再行碎手氏族的秘密敬礼。随后，费苏勒 才能透露他所掌握的情报，揭示这家公司日益扩大的阴谋。"}},faq={{q="工头费苏勒是谁？",a="工头费苏勒是碎手氏族安插在淤泥沼泽以北的荆棘谷地精内部的密探。他花了一年时间在这家公司的雇佣兵中树立威信，同时监视他们的行动，并向奥格瑞玛传递情报。",al={"费苏勒","费苏勒 是谁","工头费苏勒的身份"}},{q="为什么没有正确发出信号，费苏勒 就会攻击？",a="费苏勒 保持着荆棘谷地精工头应有的严厉作风。没有两枚信号弹和碎手氏族的敬礼，他就会把靠近的陌生人视为敌对入侵者或对手的密探，为了维持伪装而发动攻击。",al={"费苏勒 为什么攻击","费苏勒 敌对","费苏勒 杀了我"}},{q="荆棘谷地精的高塔在哪里？",a="荆棘谷地精的高塔位于贫瘠之地北部，俯瞰着淤泥沼泽以北的钻探场。",al={"费苏勒 的位置","高塔位置","淤泥沼泽高塔在哪"}},{q="部落为什么要刺探荆棘谷地精？",a="碎手氏族刺探荆棘谷地精，是因为这家公司肆无忌惮的开采、剥削和暴力威胁着卡利姆多。最近的情报指向贫瘠之地的一项重大阴谋，因此申苏尔找上了他的线人。",al={"为什么刺探荆棘谷地精","荆棘谷地精的威胁"}},{q="与 费苏勒 接头后会发生什么？",a="接头后，费苏勒 指示盗贼进入附近的荆棘谷地精高塔，杀死里面的所有人，包括大工头普兹克·加里维克斯，并取走赞吉尔的改良药剂，向公会证明自己的价值。",al={"卧底密探 之后做什么","费苏勒 之后"}},{q="碎手氏族是什么？",a="碎手氏族是一个由盗贼、间谍和刺客组成的情报网，以奥格瑞玛的暗影裂口为据点。它曾是德拉诺上一个臭名昭著的氏族，如今则在暗中为部落搜集情报。",al={"碎手氏族","碎手氏族 是谁"}}},fp="10,218,22.282.0,17.353.0,26.220.0,58.236.0,43.102.0,47.223.0,47.216.1,27.190.0"}
P.entries["quest:2459"] = {n="噬梦者菲罗斯塔",s="“食梦者”费罗塞塔斯是一项由多兰纳尔的塔隆凯·捷根提供的联盟任务。在找回他受损的传家宝翡翠摄梦符后，塔隆凯发现其强力的翡翠核心被星风村北部的蓟皮熊怪撬走了。冒险者们受命去杀死那些腐化的秘法师，并从它们的首领，费罗塞塔斯那里取回被盗的宝石。",h="“食梦者”费罗塞塔斯是一项由多兰纳尔的塔隆凯·捷根提供的联盟任务。在找回他受损的传家宝翡翠摄梦符后，塔隆凯发现其强力的翡翠核心被星风村北部的蓟皮熊怪撬走了。冒险者们受命去杀死那些腐化的秘法师，并从它们的首领，费罗塞塔斯那...",kw={"多兰纳尔","食梦者","翡翠摄梦符","费罗塞塔斯","蓟皮秘法师","星风村","塔隆凯·捷根","塔隆凯的珠宝","泰达希尔"},ang={["class:Druid"]="翡翠摄梦符是与翡翠梦境相连的强力法器；看到它被腐化的熊怪玷污，需要迅速进行自然的惩戒。",["race:NightElf"]="蓟皮熊怪曾经是卡多雷的盟友，这使得它们的秘法师被腐化以及它们窃取神圣护身符的行为，对于任何保卫泰达希尔的暗夜精灵来说，都是一出令人心酸的悲剧。"},sec={{t="污秽的传家宝",b="当塔隆凯·捷根检查从腐化的荒野中找回的翡翠摄梦符时，他的欣慰很快变成了沮丧。这件神圣的文物遭到了破坏，其充满活力的翡翠中心被从编织的框架中撬了出来。暗夜精灵中流传着一个消息，星风村北部的一群蓟皮秘法师受到了一位被称为“食梦者”费罗塞塔斯的熊怪首领的影响，他肆无忌惮地将那颗闪亮的绿色宝石挂在脖子上。深知这颗神圣的宝石在那个生物手中毫无用处且显得亵渎，塔隆凯派遣防御者去夺回它。"},{t="清除秘法师",b="居住在泰达希尔北部的蓟皮熊怪曾经是和平的邻居，但渗透进世界之树的日益严重的腐化驱使它们陷入了狂乱和疯狂。曾经实行和谐自然仪式的秘法师们，开始利用扭曲的魔法能量。通过追踪费罗塞塔斯并杀出重围，击败守卫其林地领地的秘法师随从，旅行者们恢复了林地的平衡，并找回了塔隆凯的珠宝，使翡翠摄梦符终于得以复原。"}},faq={{q="我在哪里可以找到“食梦者”费罗塞塔斯？",a="“食梦者”费罗塞塔斯位于泰达希尔星风村北部的森林中，周围环绕着腐化的蓟皮秘法师和其他林地危险。",al={"费罗塞塔斯位置","费罗塞塔斯在哪里","找到食梦者"}},{q="费罗塞塔斯是谁？",a="费罗塞塔斯是一位蓟皮熊怪首领，他指挥着星风村北部的一群腐化的蓟皮秘法师。他从塔隆凯·捷根的翡翠摄梦符上取下了那块翡翠，并将它做成了一条简陋的项链。",al={"费罗塞塔斯是谁","费罗塞塔斯背景故事","什么是食梦者"}},{q="为什么塔隆凯·捷根想要回这颗珠宝？",a="失踪的翡翠是塔隆凯的翡翠摄梦符的核心动力源。没有它，这件护身符就无法修复，也无法引导翡翠梦境的保护能量。",al={"为什么塔隆凯想要珠宝","塔隆凯珠宝的作用"}},{q="蓟皮熊怪真的能使用翡翠的魔法吗？",a="不能。根据塔隆凯·捷根的说法，翡翠的魔法属性对于费罗塞塔斯和蓟皮秘法师这类生物来说毫无用处，他们仅仅把它当作一个发光的装饰品来觊觎。",al={"蓟皮熊怪能用翡翠摄梦符吗","费罗塞塔斯会使用翡翠吗"}},{q="这个任务之后会发生什么？",a="这个任务是始于“翡翠摄梦符”这一两部分任务链的最终章。一旦你将珠宝交给多兰纳尔的塔隆凯，他终于可以修复他的传家宝了。",al={"费罗塞塔斯任务后续","翡翠摄梦符后续任务"}},{q="为什么蓟皮秘法师会充满敌意？",a="和泰达希尔各地的许多野生动物和熊怪部落一样，蓟皮熊怪屈服于一种奇怪的腐化，这种腐化扭曲了新种植的世界之树的枝干，使它们心智扭曲，变得具有攻击性。",al={"为什么熊怪会发狂","蓟皮熊怪腐化"}}},fp="25,167,18.501.0,19.429.0,42.150.0,17.193.0,49.195.0,51.141.0,30.163.0,38.188.0"}
P.entries["quest:246"] = {n="审时度势",s="菲尔顿副队长需要摸清湖畔镇附近豺狼人的威胁。驻军兵力捉襟见肘，暴风城又不肯派出援军，他只好雇用旅人，削减豺狼人的数量，探明它们的实力。",h="菲尔顿副队长需要摸清湖畔镇附近豺狼人的威胁。驻军兵力捉襟见肘，暴风城又不肯派出援军，他只好雇用旅人，削减豺狼人的数量，探明它们的实力。",kw={"评估","菲尔顿","豺狼人","湖畔镇","混血种","偷猎者","侦察","赤脊山","威胁"},ang={["class:Warrior"]="菲尔顿副队长要求开展武装侦察。身为战士，你冲入设防的营地，击溃豺狼人的先头部队。",["faction:Alliance"]="赤脊山显露出联盟腹地承受的压力：被忽视的边境聚落雇用勇士以求生存，而首都却对此视而不见。",["race:Human"]="身为人类守卫者，保卫湖畔镇与你息息相关。边境的家庭正为暴风要塞的政局僵持付出代价。"},sec={{t="吃紧的边防",b="湖畔镇既要面对从高地袭来的黑石兽人战帮，也要抵挡山谷中凶悍的豺狼人群。镇上的守军太少，连日常的侦察巡逻都难以维持。报告证实豺狼人正向边境逼近后，菲尔顿副队长便向旅人寻求帮助。他付钱请勇士到野外试探敌人，因为镇上已抽不出卫兵。"},{t="武装侦察",b="你沿着赤脊山南部的道路侦察，袭击赤脊山混血豺狼人和偷猎者的营地。每场战斗都能削减豺狼人的前哨斥候，扰乱它们的补给线。这也能查明，这些豺狼人究竟是四处游荡的食腐者，还是威胁湖畔镇的有组织部队。战斗为菲尔顿提供了可用的兵力数据，帮助他筹划镇上吃紧的防务。"}},faq={{q="菲尔顿副队长为什么派冒险者，而不是镇上的卫兵？",a="湖畔镇的驻军严重缺员。暴风城没有派来援军，敌对势力又从几个方向步步紧逼，卫兵无力抽调士兵沿南部道路进行长途巡逻。",al={"为何雇用冒险者","卫兵在哪里","湖畔镇卫兵短缺"}},{q="这次任务要对付的豺狼人在哪里？",a="赤脊山 杂种豺狼人和偷猎者在南部道路沿线及赤脊山的低矮山麓扎营，位于湖畔镇以南，靠近边境隘口。",al={"赤脊山 混血豺狼人在哪里","赤脊山豺狼人位置","南部道路豺狼人"}},{q="削减这些豺狼人的数量，有什么战略目的？",a="战斗能击退逼近道路的豺狼人，扰乱它们的补给线，并为菲尔顿提供有关它们数量、武器和纪律的第一手情报。",al={"为何击杀豺狼人","威胁评估目标","湖畔镇防御"}},{q="暴风城会帮助应对豺狼人的威胁吗？",a="不会。暴风城的贵族和摄政议会不肯向赤脊山这样的边远地区提供常规军事支援。所罗门镇长和菲尔顿副队长等地方领袖只能依靠花钱雇来的佣兵。",al={"暴风城援军","暴风城为何不援助","暴风城军队湖畔镇"}},{q="菲尔顿副队长会如何处理你的报告？",a="菲尔顿副队长评估了这些豺狼人的实力和顽强程度，确认南方的豺狼人构成了严重的军事威胁，而非零散的野兽。他指引你去帮助镇上其他领袖巩固防御。",al={"菲尔顿的反应","评估威胁之后","提交报告"}},{q="这项任务与前一个任务有什么联系？",a="这项任务接续豺狼人的入侵。你向驻军报告豺狼人的动向后，菲尔顿便派你进行战斗巡逻，查明这次入侵究竟有多严重。",al={"任务线关联","豺狼人的入侵后续","前置任务"}}},fp="20,219,19.344.0,23.347.0,63.207.0,46.158.0,54.175.0,47.214.0,44.228.0,46.160.0"}
P.entries["quest:2460"] = {n="碎手军礼",s="碎手礼是一种由申苏尔在奥格瑞玛的暗影裂口监督的入门仪式。通过学习这种独特的识别标志，初出茅庐的潜行者们可以学会如何在野外安全地识别碎手氏族的同僚。",h="碎手礼是一种由申苏尔在奥格瑞玛的暗影裂口监督的入门仪式。通过学习这种独特的识别标志，初出茅庐的潜行者们可以学会如何在野外安全地识别碎手氏族的同僚。",kw={"暗影裂口","隐蔽","深度潜伏","奥格瑞玛","潜行者","碎手氏族","碎手礼","申苏尔"},ang={["class:Rogue"]="对于一名部落潜行者来说，掌握碎手氏族的秘密信号代表着从一名普通的小偷向奥格瑞玛情报网络值得信赖的特工的转变。",["faction:Horde"]="尽管大酋长萨尔以荣誉领导部落，但部落在很大程度上依赖碎手氏族的秘密手段来在威胁浮出水面之前将其化解。"},sec={{t="标志与阴影",b="在暗影裂口的黑暗隧道中，碎手氏族作为萨尔领导的部落的秘密情报和暗杀机构开展行动。考虑到他们任务的危险性和隐秘性，特工们不能依赖显眼的横幅或标准的军事纹章。申苏尔指导新入行的潜行者学习碎手礼，这是一种旨在作为盟友之间明确无误的无声信号的特定手势。"},{t="野外准备",b="掌握这种礼节不仅是一种仪式性的练习，更是至关重要的贸易技巧。潜行者特工被派往危险地区或负责渗透敌对派系时，必须在不惊动旁观者或目标的情况下验证联络人。申苏尔坚持要求特工在将秘密的野外任务托付给他们之前，必须能够熟练地识别并模仿这一手势。"}},faq={{q="碎手礼的目的是什么？",a="碎手礼是碎手氏族成员之间的一种秘密识别信号。它允许特工在深入潜伏或处于敌对领土时识别彼此，而不会向外人暴露他们的真实身份。",al={"为什么需要学习碎手礼","碎手礼的目的","碎手礼的作用"}},{q="谁传授碎手礼？",a="这种礼节由申苏尔传授，他是一位驻扎在奥格瑞玛下方暗影裂口深处的潜行者训练师。",al={"谁发布任务","谁是申苏尔","在哪里学习碎手礼"}},{q="什么组织使用这种手势？",a="它由碎手氏族使用，这是一个由兽人潜行者、间谍和刺客组成的组织，在奥格瑞玛的阴影中为现代部落服务。",al={"碎手氏族","碎手氏族是谁","哪个组织使用这种手势"}},{q="为什么在进入野外之前必须学习这种礼节？",a="被派去执行渗透任务（例如与卧底特工联络）的特工依靠这种礼节来避免暴露身份或将敌人误认为盟友。",al={"为什么要练习碎手礼","碎手礼是必须的吗"}},{q="这项训练在哪里进行？",a="训练在暗影裂口进行，这是奥格瑞玛下方的地下区域，潜行者、术士和其他禁忌之术的修行者聚集在这里，远离公众的视线。",al={"碎手礼位置","申苏尔在哪里"}},{q="掌握这种礼节后会进行什么任务？",a="一旦申苏尔对特工掌握礼节的情况感到满意，他就会指派他们执行深度潜伏任务，测试他们使用该信号联系野外特工的能力。",al={"接下来做什么","碎手礼之后的下一个任务","深度潜伏任务"}}},fp="20,157,17.315.0,25.325.0,44.147.0,33.101.0,36.132.0,65.138.0,36.186.0,51.179.0"}
P.entries["quest:247"] = {n="完成狩猎",s="在灰谷，这场狩猎让一位部落勇士接受三头传奇猛兽的考验。击杀乌萨苟斯、萨杜布拉和沙普塔隆，便能在这片战火纷争的森林中证明自己的力量、坚韧与野性本领。",h="在灰谷，这场狩猎让一位部落勇士接受三头传奇猛兽的考验。击杀乌萨苟斯、萨杜布拉和沙普塔隆，便能在这片战火纷争的森林中证明自己的力量、坚韧与野性本领。",kw={"灰谷","野兽","狩猎","捕食者","塞娜尼","萨杜布拉","沙普塔隆","桑德哈特","战利品","乌萨苟斯"},ang={["class:Hunter"]="身为猎人，你要以灰谷最强大的三头猛兽证明自己的追踪本领与射术。你的本能必须足以与这些野兽匹敌。",["faction:Horde"]="身为部落的一员，你帮助族人巩固在灰谷的据点，这片危险的林地中遍布猛兽与联盟哨兵。",["race:Tauren"]="身为牛头人，你通过猎杀乌萨苟斯、萨杜布拉和沙普塔隆，践行一项传承已久的试炼，彰显敬意、平衡与先祖的荣耀。"},sec={{t="猎人的证明",b="塞娜尼·雷心在灰谷的部落军中考验旅人。她的狩猎考验的不只是对大酋长的忠诚，还要看猎人是否懂得在荒野中生存。猎物是三头传奇猛兽：巨熊乌萨苟斯、豹类猛兽萨杜布拉，以及凶猛的角鹰兽沙普塔隆。将它们全部击杀并取得战利品，便能证明猎人血脉纯正。"},{t="向先祖致敬",b="对牛头人而言，狩猎是体现平衡与敬意的神圣之举，即便身处交战前线也不例外。战胜灰谷最可怕的猛兽，既能向大地之灵致敬，也能让猎人获得雷心的先祖祝福。正式的嘉奖与嘉许的信物标志着狩猎的结束，勇士的名声也随之传遍森林。"}},faq={{q="谁提供这个任务，位于何处？",a="牛头人猎人塞娜尼·雷心在灰谷的部落军中提供这项狩猎任务。",al={"任务给予者","交任务地点","塞娜尼·雷心位置"}},{q="完成狩猎需要满足什么条件？",a="你必须击杀三头强大的猛兽，并带回它们死亡的证明：乌萨苟斯的爪子、萨杜布拉的头颅和沙普塔隆的利爪。",al={"要杀哪些野兽","前置条件","哪些动物"}},{q="塞娜尼·雷心为何要猎杀这些野兽？",a="这场狩猎考验力量与坚韧。击杀如此强大的野兽，便能证明旅人拥有捕食者的心志与本能，足以在灰谷危机四伏的荒野中生存。",al={"为何猎杀它们","塞娜尼的动机","狩猎目的"}},{q="这场狩猎对部落有何文化意义？",a="对塞娜尼·雷心这样的牛头人来说，与强大野兽较量、考验自身勇气，是向自然之灵与先祖致敬的光荣传统。这展现了驾驭荒野的本领，同时避免鲁莽之举有损荣誉。",al={"牛头人狩猎背景","文化意义","牛头人为何猎杀野兽"}},{q="整个部落都认可这项试炼吗？",a="是的。完成狩猎后，灰谷的部落军便会认可你是一名经受过考验的猎人。你会获得先祖的祝福与战友的尊重。",al={"部落认可","是否正式认可","部落嘉奖"}},{q="灰谷狩猎的目标是哪三头野兽？",a="三个目标分别是巨熊乌萨苟斯、夜刃豹萨杜布拉和角鹰兽沙普塔隆。",al={"三头野兽","狩猎目标","有名字的动物"}}},fp="18,159,16.377.0,22.343.0,49.90.0,47.126.0,53.178.0,59.204.0,45.153.0,54.104.0"}
P.entries["quest:2478"] = {n="基本不可能的任务",s="在贫瘠之地北部，部落潜行者面对着一座荆棘谷地精哨站，潜行、偷窃和战斗技巧都将在此经受考验。他们潜入一座采油塔，杀死大工头普兹克·加里维克斯，并为碎手氏族夺取一种强效化学药剂。",h="在贫瘠之地北部，部落潜行者面对着一座荆棘谷地精哨站，潜行、偷窃和战斗技巧都将在此经受考验。他们潜入一座采油塔，杀死大工头普兹克·加里维克斯，并为碎手氏族夺取一种强效化学药剂。",kw={"贫瘠之地","费苏勒","开锁","毒药","普兹克·加里维克斯","碎手氏族","申苏尔","希里克斯","淤泥沼泽","赞吉尔"},ang={["class:Rogue"]="身为潜行者，你会在实地行动中学会开锁、偷窃和利用弱点。这些技巧将引领你掌握碎手氏族致命的技艺与毒药。",["faction:Horde"]="碎手氏族在奥格瑞玛的阴影中活动，监视着荆棘谷地精这类危险的公司入侵者，看着他们掠夺贫瘠之地的资源。"},sec={{t="潜入荆棘谷地精",b="在淤泥沼泽的采油平台北面，荆棘谷地精设有一座孤立的钻探塔。工头费苏勒是碎手氏族的一名特工，伪装成荆棘谷地精的主管，他命令潜行者运用地下世界的伎俩，而非正面强攻。他要求他们从工头希里克斯身上偷走钥匙，替他保管。随后，他们向塔上攀登，绕过那些被塔内实验改变的工人和哨兵。"},{t="化学灾祸",b="一种名为赞吉尔的改良药剂的实验物质改变了塔内的居民。这种毒液削弱了守卫，使他们难以抵挡迅猛的打击、造成流血的攻击和突如其来的伏击。它还让整座设施变得极不稳定。在塔顶，大工头普兹克·加里维克斯守卫着一个装有药剂的锁箱。"},{t="职责的代价",b="潜行者打开加里维克斯的锁箱时，变异药剂的蒸气逸散出来。它们打破潜行，消耗生命力，并留下持续很久的虚弱症状。回到奥格瑞玛后，碎手氏族的导师申苏尔收下了加里维克斯的头颅和化学样本。他为费苏勒身份暴露而痛惜，并让这名濒死的特工去寻求解药。"}},faq={{q="荆棘谷地精的高塔在哪里？",a="荆棘谷地精的高塔坐落于贫瘠之地北部，就在淤泥沼泽钻探场的北面。敌对的荆棘谷地精工人围在塔的四周，工头费苏勒则藏在东边不远处的一棵树旁。",al={"荆棘谷地精高塔位置","加里维克斯的高塔在哪","淤泥沼泽高塔"}},{q="如何取得高塔的钥匙？",a="工头希里克斯带着高塔的钥匙，在塔底外面的场地上游荡。潜行时对他使用偷窃便可取得钥匙；杀死他无法获得钥匙。",al={"希里克斯高塔钥匙","如何取得高塔钥匙","钥匙在哪"}},{q="赞吉尔的改良药剂是什么？",a="赞吉尔的改良药剂是一种炼金药剂，源自臭名昭著的巨魔巫医赞吉尔的配方。荆棘谷地精得到了它，而它不稳定的烟雾毒害了塔内的工人，使他们病弱、变异，也更容易受到潜行者战斗技艺的伤害。",al={"赞吉尔药剂","是什么毒药","变异药剂"}},{q="为什么打开锁箱后无法潜行？",a="打开加里维克斯的锁箱会释放出变异药剂的浓烈烟雾。这种中毒症状会持续数日，削弱你的属性，并使你无法潜行，直到一位经验丰富的药剂师将其治愈。",al={"赞吉尔之触","开箱后中毒","潜行者任务无法潜行","七天中毒"}},{q="工头费苏勒是谁？",a="工头费苏勒是部落潜行者公会碎手氏族的一名深度潜伏特工。这名黑铁矮人在贫瘠之地伪装成一位冷酷无情的荆棘谷地精工头，指挥新兵破坏公司的资产，同时避免暴露自己。",al={"费苏勒","谁给的任务","费苏勒的故事"}},{q="大工头普兹克·加里维克斯是谁？",a="大工头普兹克·加里维克斯是一名地精监工，掌管着淤泥沼泽附近的荆棘谷地精高塔。他守着那批盗来的赞吉尔药剂，直到碎手氏族的特工将他杀死。",al={"普兹克·加里维克斯","加里维克斯在贫瘠之地吗","工头加里维克斯"}}},fp="34,166,31.391.0,22.298.1,17.370.2,39.210.0,39.156.0,33.280.0,53.210.1,26.259.0,36.199.0"}
P.entries["quest:2479"] = {n="希诺特的帮助",s="“希诺特的帮助”是一次迫切的旅程，旨在拯救身中致命热带毒素的部落潜行者。在贫瘠之地的渗透任务中，这些潜行者中了毒，需要塔伦米尔的瑟尔格·希诺特提供专业诊疗。寻找他的帮助不仅能带来救命的解药，还能习得调制致命毒药的艺术。",h="“希诺特的帮助”是一次迫切的旅程，旨在拯救身中致命热带毒素的部落潜行者。在贫瘠之地的渗透任务中，这些潜行者中了毒，需要塔伦米尔的瑟尔格·希诺特提供专业诊疗。寻找他的帮助不仅能带来救命的解药，还能习得调制致命毒药的艺术。",kw={"希尔斯布莱德丘陵","希诺特的帮助","潜行者毒药任务","瑟尔格·希诺特","申苏尔","塔伦米尔","幽暗城飞艇","赞吉尔","赞吉尔的药剂"},ang={["class:Rogue"]="这个成人仪式架起了潜行技能与炼金艺术之间的桥梁，在考验潜行者耐力的同时，也为你开启了自制毒药的大门。",["faction:Horde"]="这次任务展示了卡利姆多的兽人和巨魔潜行者与洛丹伦被遗忘者的邪恶炼金知识之间紧密的实践合作。"},sec={{t="中毒危机",b="在大胆潜入淤泥沼泽北部的荆棘谷地精塔楼之后，潜行者们中了赞吉尔调制的混合毒剂。这种毒药对身体造成了极大的破坏，迟钝了反应能力，甚至危及生命。奥格瑞玛的潜行者训练师申苏尔认识到这种毒素的严重性，承认当地的治疗手段无法应对，于是指引这名中毒的特工跨海前往东部王国。"},{t="前往塔伦米尔",b="寻找解药的旅程将引导你穿过洛丹伦大陆南部，前往希尔斯布莱德丘陵的塔伦米尔村。那里住着药剂师瑟尔格·希诺特，他对剧毒药剂的痴迷使他成为分析这些异域样本的最佳人选。当普通的治疗者对赞吉尔的毒液退避三舍时，希诺特却怀着专业的兴奋感对待这种致命化合物，渴望剖析这种邪恶的混合剂，并指导有前途的潜行者调配他们自己的毒药。"}},faq={{q="为什么我需要去见瑟尔格·希诺特？",a="瑟尔格·希诺特是一位居住在塔伦米尔的专家级药剂师，专门研究稀有毒素及其解毒剂。普通的治疗者无法清除赞吉尔的混合毒剂，因此希诺特是唯一有能力分析这种化合物、拯救你的生命并教授毒药学艺术的联络人。",al={"为什么找希诺特","谁能解毒","瑟尔格·希诺特的作用"}},{q="塔伦米尔在哪里？",a="塔伦米尔是希尔斯布莱德丘陵北部的一处被遗忘者定居点。从奥格瑞玛出发，乘坐飞艇前往提瑞斯法林地的幽暗城，然后穿过银松森林向南行进，沿路向东转入希尔斯布莱德。",al={"塔伦米尔的位置","如何前往塔伦米尔","希诺特在哪里"}},{q="我最初是怎么中毒的？",a="你是在贫瘠之地淤泥沼泽北部的荆棘谷地精塔楼执行隐秘任务“任务：可能的，但不现实的”时感染的。打开高安全级别的箱子使你接触到了赞吉尔的混合毒剂，留下了挥之不去的衰弱性毒素。",al={"我怎么中的赞吉尔毒药","任务：可能的，但不现实的毒药","我为什么中毒"}},{q="瑟尔格·希诺特收到样本后会发生什么？",a="一旦希诺特收到样本，他会检查其属性并准备解药来净化你的系统。在治愈毒素后，他会分享他的专业知识，使潜行者能够掌握毒药的调配和使用方法。",al={"希诺特任务后续","我会被治愈吗","希诺特的帮助之后"}},{q="申苏尔是谁？他为什么要让我离开？",a="申苏尔是位于奥格瑞玛大断崖的碎手氏族潜行者训练师。他监督了你在贫瘠之地的技能测试，并认识到赞吉尔的药剂已经远远超出了奥格瑞玛的医疗知识水平，需要希尔斯布莱德的专家来处理。",al={"申苏尔是谁","申苏尔 奥格瑞玛","训练师为什么让我离开"}},{q="其他职业能完成这个任务吗？",a="不能。这个任务是潜行者专属训练任务链的一部分，旨在解锁调配毒药和解药的基础学科。",al={"潜行者专属任务","战士能做希诺特的帮助吗"}}},fp="19,214,19.312.0,22.372.0,34.221.0,29.226.0,42.256.0,52.221.1,44.250.0,40.108.0"}
P.entries["quest:248"] = {n="监视",s="塞欧克瑞图斯通过一条附魔通道，从艾尔文监视赤脊山东部。他想查明莫甘斯与石堡要塞的黑石兽人发生冲突的原因，并派你把阿祖拉的铭文饰品放进附近的哨塔。",h="塞欧克瑞图斯通过一条附魔通道，从艾尔文监视赤脊山东部。他想查明莫甘斯与石堡要塞的黑石兽人发生冲突的原因，并派你把阿祖拉的铭文饰品放进附近的哨塔。",kw={"空罐子","阿祖拉的铭文饰品","进一步调查","莫甘斯","古老的狮子雕像","石堡","石堡要塞","塞欧克瑞图斯","伊尔加拉之塔"},ang={["class:Mage"]="塞欧克瑞图斯使用阿祖拉的铭文饰品进行远程窥视，展现了这位Mage of Azora如何通过魔法监视敌方领地。",["faction:Alliance"]="石堡要塞仍是黑石氏族在赤脊山的主要据点。了解他们与莫甘斯之间的冲突，对保卫湖畔镇至关重要。"},sec={{t="赤脊山的裂痕",b="塞欧克瑞图斯在艾尔文森林的密室中，用占卜魔法监视赤脊山东部。他观察伊尔加拉之塔时，察觉到叛离的人类术士莫甘斯与盘踞在石堡要塞的黑石兽人发生了冲突。这两个敌对势力本该联合起来对抗暴风城王国，却在争夺某种不为人知的东西。塞欧克瑞图斯赶在这场冲突改变力量对比之前介入。"},{t="监视石堡的眼睛",b="塞欧克瑞图斯需要第二个魔法锚点，才能穿透石堡要塞的防御。因此，他派你爬上残破堡垒旁那座完好的哨塔。驻军的杂物堆中，有一个兽人哨兵丢弃的空罐子，是个不起眼的藏匿之处。把阿祖拉的铭文饰品固定在里面，塞欧克瑞图斯就能通过心灵感应探查石堡内的思想，查明莫甘斯与黑石兽人反目的原因。"}},faq={{q="是谁派我执行这项任务？",a="完成塞欧克瑞图斯先前交给你的任务后，这位阿祖拉法师会通过赤脊山的古老的狮子雕像与你交谈。",al={"谁发布任务","任务发布者","古老的狮子雕像"}},{q="塞欧克瑞图斯为什么要窥探石堡要塞？",a="塞欧克瑞图斯察觉到，伊尔加拉之塔中离经叛道的黑暗巫师莫甘斯与占据石堡要塞的黑石兽人正在交战。他想查明这场冲突的起因。",al={"为何窥探兽人","塞欧克瑞图斯的目的","为何选择石堡"}},{q="容器在哪里？",a="空罐子放在石堡要塞正门旁那座完好哨塔顶部的桶上。",al={"空罐子位置","铭文饰品放在哪里","哨塔在哪里"}},{q="阿祖拉的铭文饰品有什么作用？",a="阿祖拉的铭文饰品是一件用于窥视和占卜的魔法媒介。它能让塞欧克瑞图斯远程监视周围区域，并深入探查要塞内黑石兽人的思想。",al={"阿祖拉的铭文饰品的用途","铭文饰品有什么作用"}},{q="放置铭文饰品之后会发生什么？",a="塞欧克瑞图斯占卜出冲突的根源后，会派你前往伊尔加拉之塔猎杀莫甘斯，取回他的暗影坠饰。",al={"下一个任务","接下来会发生什么","深入调查后续"}},{q="为什么要用空罐子？",a="用于窥探的魔法符文需要藏在不起眼的容器里，才不会被守卫发现或摧毁。那个被遗弃在桶上、散发着恶臭的酒罐，正是理想的藏匿之处。",al={"为何使用罐子","空罐子的背景故事"}}},fx={["3912e7be"]={q="我在石堡要塞监视谁？",a="你要监视占据石堡要塞的黑石兽人。法师塞欧克瑞图斯从观察点发现，这些敌对兽人与伊尔加拉之塔的黑暗法师摩根斯之间正酝酿着冲突。放置雕文能让法师探查石堡要塞内众人的思想，找出这场摩擦的真正原因。",al={"石堡要塞里有什么人","石堡要塞目标","深入探查任务目标"}},["6347ef38"]={q="为什么塞欧克瑞图斯需要冒险者去放置雕文？",a="塞欧克瑞图斯驻守在阿祖拉之塔，借助古老的狮子雕像等附魔遗物施展法术，监视赤脊山各处的威胁。石堡要塞里到处都是危险的黑石兽人，要潜入这座据点，就需要有人能一路战斗而不被发现地进入塔中；独自一人的脆弱法师不能轻易离开岗位。",al={"为什么派我深入探查","塞欧克瑞图斯为什么不自己做","为什么派我去石堡"}}},fp="15,241,18.418.0,21.425.1,29.133.0,44.201.0,31.114.0,32.182.0,38.141.1,21.170.0"}
P.entries["quest:2480"] = {n="希诺特的帮助",s="在塔伦米尔，一名部落潜行者向瑟尔格·希诺特求助，以解除赞吉尔的毒药。这位被遗忘者化学家研究毒素，配制解药。",h="在塔伦米尔，一名部落潜行者向瑟尔格·希诺特求助，以解除赞吉尔的毒药。这位被遗忘者化学家研究毒素，配制解药。",kw={"抗毒药剂","解药","希尔斯布莱德","希诺特","毒药","潜行者任务","瑟尔格·希诺特","塔伦米尔","赞吉尔"},ang={["class:Rogue"]="身为潜行者，你治愈了入门试炼留下的病症，并学会了配制战术毒药的知识。",["faction:Horde"]="身为部落的一员，你可以从被遗忘者炼金术中学习，见证丛林巨魔的毒素如何转化为实战知识。",["race:Undead"]="身为Undead，你能看到药剂师希诺特对精心配制的毒药怀有冷静而超然的欣赏，无论它来自何处。"},sec={{t="毒药杰作",b="在贫瘠之地执行任务后，你身中一种扰乱心智的毒素，被派往北方的塔伦米尔。被遗忘者化学家瑟尔格·希诺特研究了这种毒药，它出自被放逐的丛林巨魔赞吉尔之手。希诺特并不在意这个巨魔的身份或族人。他欣赏这剂毒药的狠毒效果，想先弄清它的作用原理，再配制解药。"},{t="解药与技艺",b="希诺特需要时间分离毒药中的活性成分。他配好的解药遏止了逐渐侵蚀心智的疯狂，不过他说，那股挥之不去的恶臭依然存在。毒药不再使你虚弱后，希诺特便将他从赞吉尔的作品中学到的知识传授给你。你可以运用这些知识，配制自己的战术毒药。"}},faq={{q="希诺特的帮助的任务过程是什么？",a="在塔伦米尔稍候片刻，等待瑟尔格·希诺特配制解药。解药备好后，与他交谈并服下解药，解除赞吉尔的毒药。",al={"这里要做什么","希诺特的帮助攻略","如何完成任务"}},{q="瑟尔格·希诺特是谁？",a="瑟尔格·希诺特是一位被遗忘者炼金师和毒药专家，居住在希尔斯布莱德丘陵的塔伦米尔。他帮助部落潜行者治愈异常病症，并学习配制毒药。",al={"瑟尔格·希诺特的故事","希诺特是谁","塔伦米尔药剂师"}},{q="瑟尔格·希诺特为何对这种毒药赞叹不已？",a="希诺特欣赏赞吉尔配方中的精湛技艺，这种毒药既会逐渐使人陷入疯狂，也会令身体虚弱。尽管他在设法消除药效，却仍对这剂毁灭性毒药背后的技艺赞不绝口。",al={"赞吉尔毒药反应","希诺特为何喜欢这种毒药"}},{q="希诺特提到的残留气味是什么？",a="赞吉尔的药剂会留下一股刺鼻、令人作呕的气味，久久滞留在受害者的毛孔中。希诺特的解药能遏止毒性，让心智恢复清明，但恶臭还会持续一段时间。",al={"身上为何有臭味","疯狂与臭味","任务臭味"}},{q="完成这个任务有什么奖励？",a="解药会消除潜行者训练留下的持续性病症，并让你能够学习盗贼毒药，从而配制使敌人衰弱的涂抹毒药。",al={"潜行者获得什么","希诺特的帮助奖励"}},{q="在哪里交付这个任务？",a="你会在希尔斯布莱德丘陵北部的塔伦米尔见到瑟尔格·希诺特，他在那里开始并完成解毒工作。",al={"希诺特在哪里","任务交付地点"}}},fp="19,100,19.369.0,26.295.1,40.154.0,20.172.0,44.181.0,44.166.0,45.147.0,30.113.0"}
P.entries["quest:249"] = {n="莫甘斯",s="塞欧克瑞图斯监视着莫甘斯在赤脊山搜寻一件古老圣物。",h="塞欧克瑞图斯监视着莫甘斯在赤脊山搜寻一件古老圣物。",kw={"艾尔文","莫甘斯","暗影坠饰","赤脊山","月神镰刀","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="身为法师，你看到了塞欧克瑞图斯勤勉治学的传统：人类法师在高塔中守望，保护王国免受叛离施法者的侵害。",["class:Warlock"]="身为术士，你看到了对邪能与暗影的野心不受约束时会有多么危险。觊觎月神镰刀这样的圣物，会迅速招致毁灭。",["faction:Alliance"]="身为联盟的一员，你协助保卫暴风城防御薄弱的东部边境。击败莫甘斯，就能让赤脊山免于落入黑暗巫术的掌控。",["race:NightElf"]="身为暗夜精灵，听到月神镰刀落入人类之手的传闻，你理应警觉。对kaldorei而言，它的名字牵涉着神圣而不稳定的奥秘。"},sec={{t="边界彼端的守望者",b="塞欧克瑞图斯在艾尔文森林东部的阿祖拉之塔中，借助占卜法术监视赤脊山的峭壁。他看到伊尔加拉之塔中的术士莫甘斯正在寻找月神镰刀。塞欧克瑞图斯担心莫甘斯即将得到它，便请联盟勇士在暴风城受到威胁之前阻止他。"},{t="强攻高塔",b="伊尔加拉之塔耸立在赤脊山盆地上方，塔内遍布豺狼人和扭曲的奥术能量。莫甘斯在塔顶等候，操纵着暗影魔法，守护着自己的研究。要抵达他所在的地方，你必须穿过敌人盘踞的区域，直面这名术士。你可以带回他的暗影坠饰，证明高塔已被攻陷，威胁已被消除。"},{t="镰刀的余影",b="莫甘斯的败亡消除了暴风城眼前的威胁，但他对月神镰刀的追寻，也表明这件神器的黑暗传说流传之广。塞欧克瑞图斯收到暗影坠饰后，终于松了一口气。这把古老镰刀的下落，以及它可能给周边各地带来的浩劫，仍然无人知晓。"}},faq={{q="莫甘斯是谁？",a="莫甘斯是一名强大的叛离术士，住在赤脊山的伊尔加拉之塔顶层。他钻研黑暗法术，并寻找月神镰刀，一件能够施展灾难性魔法的神器。",al={"莫甘斯身份","莫甘斯是谁","莫甘斯背景故事"}},{q="伊尔加拉之塔在哪里？",a="伊尔加拉之塔位于赤脊山东部，在石堡要塞更远处，暗皮豺狼人就在塔脚周围扎营。",al={"伊尔加拉之塔位置","莫甘斯的塔在哪里","赤脊山高塔"}},{q="塞欧克瑞图斯为什么想要莫甘斯死？",a="塞欧克瑞图斯通过占卜法术得知，莫甘斯正在寻找月神镰刀，并担心他很快就会找到它。莫甘斯追求的力量威胁着赤脊山和邻近的暴风城王国。",al={"塞欧克瑞图斯的动机","为什么杀死莫甘斯","塞欧克瑞图斯任务缘由"}},{q="月神镰刀是什么？",a="月神镰刀是一件笼罩在谜团中的神器。塞欧克瑞图斯没有解释它的力量，但他担心，一旦莫甘斯找到它，赤脊山和暴风城就会领教这名术士的黑暗力量。",al={"月神镰刀传说","镰刀是什么","镰刀为什么危险"}},{q="暗影坠饰是什么？",a="暗影坠饰是莫甘斯的魔法护符。它能汇聚他的黑暗法术之力，将它带给阿祖拉之塔的塞欧克瑞图斯，就能证明莫甘斯已被击败。",al={"暗影坠饰","莫甘斯坠饰","莫甘斯死亡证明"}},{q="此前有哪些系列任务？",a="这一系列任务始于艾尔文森林的“塞欧克瑞图斯的坠饰”，随后是“监视”和“继续观察”。这些步骤会取回工具，并布置占卜法术，以监视莫甘斯的高塔。这是该系列任务的最后一环。",al={"莫甘斯系列任务","莫甘斯前置条件","如何解锁莫甘斯"}}},fp="8,87,27.327.0,18.335.0,29.330.1,16.217.0,30.126.0,39.210.0,28.191.0,30.166.0,34.214.0"}
P.entries["quest:2498"] = {n="向德纳兰回报",s="“回到德纳兰身边”是一个联盟任务，连接了正在调查泰达希尔内部腐蚀现象的植物学家们。在研究了折磨当地树苗怪的苔藓肿瘤后，雷利亚·绿树把你派回南边的奥拉密斯湖，去协助德纳兰处理一项令人震惊的新发现。",h="“回到德纳兰身边”是一个联盟任务，连接了正在调查泰达希尔内部腐蚀现象的植物学家们。在研究了折磨当地树苗怪的苔藓肿瘤后，雷利亚·绿树把你派回南边的奥拉密斯湖，去协助德纳兰处理一项令人震惊的新发现。",kw={"德纳兰","多兰纳尔","奥拉密斯湖","奥肯斯古尔","雷利亚·绿树","泰达希尔","树苗怪","肿瘤"},ang={["class:Druid"]="调查林地灵体身上不自然的肿瘤，触及了塞纳里奥议会维护自然平衡和净化阴险枯萎病这一使命的核心。",["race:NightElf"]="树苗怪是泰达希尔生命力的活体体现；协助德纳兰是治愈威胁到你族人新家园的日益严重的腐蚀这一神圣职责的一部分。"},sec={{t="枝叶间的讯息",b="在检查泰达希尔树苗怪身上奇异的苔藓肿瘤时，雷利亚·绿树收到了同事德纳兰的紧急消息。德纳兰驻扎在平静的奥拉密斯湖畔，他认为自己终于查明了是什么导致了这些森林自然之灵身上出现的不自然生长。意识到局势的严重性，雷利亚立即把你派回南边去伸出援手。"},{t="湖畔的威胁",b="德纳兰在奥拉密斯湖的研究对于了解蔓延在这棵年轻世界之树上的病症至关重要。最初对受腐蚀植物和患病树苗怪的调查，很快升级为与毒害树枝的枯萎实体之间的直接对抗，而这一切始于那只受到腐蚀的树苗怪奥肯斯古尔。"}},faq={{q="德纳兰是谁？",a="德纳兰是一位暗夜精灵研究员兼博物学家，驻扎在泰达希尔南部的奥拉密斯湖。他致力于研究岛上的植物群、奇异的幼苗变异，以及在当地树苗怪中蔓延的不自然病症。",al={"德纳兰背景故事","德纳兰是谁","德纳兰 奥拉密斯湖"}},{q="为什么雷利亚·绿树要让你回到奥拉密斯湖？",a="雷利亚收到消息称，德纳兰已经发现了导致树苗怪身上肿瘤的可能根源。由于局势发展迅速，且对森林构成了日益严重的威胁，雷利亚派你前去提供及时的实地援助。",al={"为什么要去德纳兰那里","雷利亚·绿树的任务"}},{q="困扰树苗怪的肿瘤是什么？",a="树苗怪是诞生于岛上植物群的宁静自然之灵，但泰达希尔内部滋生的一种弥漫性腐蚀导致它们长出了奇异的苔藓状赘生物。这些肿瘤使这些生物变得充满敌意且疯狂。",al={"树苗怪肿瘤","为什么树苗怪会长肿瘤","苔藓肿瘤"}},{q="我在哪里可以找到德纳兰？",a="德纳兰在奥拉密斯湖岸边扎营，就在泰达希尔南部林地多兰纳尔的南边。",al={"德纳兰位置","德纳兰在哪里"}},{q="到达德纳兰那里后会发生什么？",a="德纳兰欢迎你的帮助，并说他发现了一些令人不安的事情。当你到达他的营地时，他会向你解释接下来的任务。",al={"接下来做什么","奥肯斯古尔后续任务"}},{q="这个差事是如何联系起雷利亚和德纳兰的？",a="这项差事将雷利亚·绿树在达纳苏斯的树苗怪研究与德纳兰在奥拉密斯湖的营地联系了起来，将雷利亚对肿瘤的研究带到了德纳兰关于其病因的新发现之中。",al={"为什么雷利亚要派我去找德纳兰","回到德纳兰的目的"}}},fp="17,222,27.349.0,22.223.1,15.214.0,59.211.0,47.214.0,25.109.0,37.129.1,49.198.0"}
P.entries["quest:2499"] = {n="奥肯斯古尔",s="奥拉密斯湖沿岸的枯萎病源自一只名叫奥肯斯古尔的堕落树精。德纳兰请你消除这个威胁。这只发狂的生物栖身于湖南岸的一处洞穴。",h="奥拉密斯湖沿岸的枯萎病源自一只名叫奥肯斯古尔的堕落树精。德纳兰请你消除这个威胁。这只发狂的生物栖身于湖南岸的一处洞穴。",kw={"腐化","德纳兰","巨大的瘤","奥拉密斯湖","长满苔藓的肿瘤","奥肯斯古尔","泰达希尔","树精"},ang={["class:Druid"]="身为德鲁伊，看到一只守护森林的树精被怪异瘤体扭曲，你便能明白泰达希尔年轻的生态系统已病得多么严重。",["profession:Herbalism"]="身为草药师，你在帮助德纳兰时，可以看到无形的腐烂如何将植物扭曲成长满苔藓的恶性病体。",["race:NightElf"]="身为暗夜精灵，奥肯斯古尔的堕落威胁着奥拉密斯湖，而这片湖就在多兰纳尔以南，紧邻你族人的腹地。"},sec={{t="堕落的守护者",b="树精照料着泰达希尔的枝干，奥肯斯古尔曾是它们的首领。如今，腐化蔓延于世界之树，寻常的野生动物与古老的守护者都未能幸免。一颗巨大的瘤体在奥肯斯古尔的树皮上不断膨胀，令这只树精陷入疯狂。它曾守护的森林，如今正遭受枯萎病的侵蚀。"},{t="净化奥拉密斯湖",b="奥肯斯古尔藏身于奥拉密斯湖南岸的一处洞穴。它的存在毒害着附近的湖水和林间野兽。德纳兰无法独自对抗这只生物，因此寻求将其消灭，以切断腐化的源头，并研究那些折磨着湖畔精魂的怪异瘤体。"}},faq={{q="奥肯斯古尔是什么？",a="奥肯斯古尔是一只体型庞大的树精，是与泰达希尔的植物息息相关的森林精魂。在恶性瘤体侵袭之前，这只树精曾统领同类。",al={"奥肯斯古尔是谁","奥肯斯古尔背景故事","奥肯斯古尔是什么生物"}},{q="为什么必须消灭奥肯斯古尔？",a="奥肯斯古尔身上的巨大瘤体扭曲了它的心智，使它变得狂暴而极具攻击性。它从奥拉密斯湖畔的洞穴中，将枯萎病传播给附近的树精和野兽。",al={"为什么要杀死奥肯斯古尔","奥肯斯古尔敌对"}},{q="奥肯斯古尔住在哪里？",a="奥肯斯古尔栖身于泰达希尔南部、奥拉密斯湖南岸的一处洞穴。",al={"奥肯斯古尔位置","奥肯斯古尔的洞穴在哪里"}},{q="德纳兰是谁，他为什么研究这颗肿瘤？",a="德纳兰是一位草药师兼博物学家，住在奥拉密斯湖东岸。他研究世界之树的动植物，试图了解并治愈感染当地树精的怪异腐烂病症。",al={"谁发布奥肯斯古尔任务","德纳兰 奥肯斯古尔"}},{q="是什么导致奥肯斯古尔长出肿瘤？",a="这颗肿瘤表明，一种更深层的病症正在泰达希尔的土壤和根系中蔓延，从内部腐化自然之灵。",al={"树精为什么长肿瘤","腐化源头"}},{q="奥肯斯古尔已经无药可救了吗？",a="冒险者找到奥肯斯古尔时，它的病情已经发展到了无法挽回的地步。瘤体已彻底扭曲了这只树精，德纳兰只能请求以死亡结束它的痛苦。",al={"奥肯斯古尔能治愈吗","治愈奥肯斯古尔"}}},fp="10,186,17.294.0,21.284.0,19.142.0,33.168.0,29.92.0,48.206.0,36.133.0,28.158.0"}
P.entries["quest:25"] = {n="石爪山的困境",s="密斯特拉湖中受到污染的水之灵阻断了部落通往石爪山的补给运输。碎木岗哨的马斯托克·维尔西斯派你清除这些敌对的元素生物，并侦察一座能俯瞰银风避难所的暗夜精灵凉亭。",h="密斯特拉湖中受到污染的水之灵阻断了部落通往石爪山的补给运输。碎木岗哨的马斯托克·维尔西斯派你清除这些敌对的元素生物，并侦察一座能俯瞰银风避难所的暗夜精灵凉亭。",kw={"受污染的水元素","凉亭","马斯托克·维尔西斯","密斯特拉湖","碎木岗哨","石爪山的困境","石爪小径","泰德雷斯"},ang={["class:Shaman"]="身为萨满祭司，你能看出水元素扭曲的状态，意味着灰谷古老森林中的元素已严重失衡。",["faction:Horde"]="身为部落的一员，你知道碎木岗哨依赖畅通的补给路线。保持石爪小径畅通，才能维系与石爪山的通信和贸易。",["race:Orc"]="身为兽人，你知道部落依靠灰谷的木材和道路，为各处定居点提供补给。绝不能任由山间补给线遭到阻断。"},sec={{t="受阻的补给线",b="部落需要在灰谷和石爪山脉之间运送木材、补给并派遣信使。石爪小径是他们的必经之路，途经密斯特拉湖西岸。敌对的水元素阻断了通行，还袭击了补给商队。马斯托克·维尔西斯要求采取行动，在部落的补给线崩溃前重新打通这条路线。"},{t="被污染的湖水",b="密斯特拉湖中的水元素受到了污染，变得凶暴而难以捉摸。它们会攻击行经附近小径的人。你受命削减它们的数量，并击败强大的水之灵泰德雷斯，让这一带变得更安全。在灰谷神圣林地的动荡中，究竟是什么污染了湖中的水之灵，仍然无人知晓。"},{t="隔水窥敌",b="密斯特拉湖的湖心岛上有一座暗夜精灵凉亭，从那里可以清楚地望见对岸的银风避难所。部落派出斥候，评估它能否用作前沿观察哨。这样，碎木的指挥官就能在不被发现的情况下监视附近联盟的动向。"}},faq={{q="是什么导致石爪山附近的运输停滞？",a="密斯特拉湖中受到污染的水元素变得狂暴，袭击附近石爪小径上的行人。它们的袭击使灰谷与石爪山脉之间的补给运输陷入停滞。",al={"运输为何停滞","石爪小径受阻","什么阻断了补给线"}},{q="是谁下令清除元素生物？",a="马斯托克·维尔西斯是驻扎在灰谷东部碎木岗哨的一名兽人，他命令你清除元素生物，并侦察联盟的据点。",al={"谁提供石爪山的困境任务","马斯托克·维尔西斯任务","马斯托克是谁"}},{q="为什么要侦察密斯特拉湖中央的凉亭？",a="从密斯特拉湖湖心岛上的凉亭，可以隔水望见附近的暗夜精灵定居点银风避难所。马斯托克想评估那里能否用作隐蔽的观察哨，以监视敌人的动向。",al={"为何侦察凉亭","密斯特拉湖凉亭用途","凉亭观察哨"}},{q="石爪小径是什么？",a="石爪小径是连接灰谷西南部与石爪山脉的山间小路。它途经密斯特拉湖西岸。",al={"石爪小径位置","通往石爪山的小径","石爪山道路"}},{q="密斯特拉湖中的水元素为什么会受到污染？",a="水元素受到腐化的原因尚不清楚。灰谷的动荡扰乱了这片湖泊，使湖中的水之灵开始敌视外来者。",al={"元素为何受到腐化","密斯特拉湖水受到污染","受污染元素的来源"}},{q="从凉亭监视的是哪个联盟前哨？",a="凉亭可以俯瞰银风避难所，那是湖泊北面不远处的一座暗夜精灵定居点。驻守那里的哨兵保卫着灰谷，抵御部落的伐木行动。",al={"密斯特拉湖附近的联盟基地","灰谷联盟前哨"}}},fp="21,237,21.322.0,20.296.0,21.289.0,47.204.0,34.135.0,51.221.0,27.148.0,54.146.0,56.171.0"}
P.entries["quest:250"] = {n="水坝危机",s="主工程师辛德维尔七世担心，继在湿地发生袭击事件后，巨石水坝会成为黑铁矮人侵略的下一个目标。由于大坝的大部分防御守军已被调往别处，冒险者们被派去调查潜伏在东侧坡道附近的黑铁工兵。",h="主工程师辛德维尔七世担心，继在湿地发生袭击事件后，巨石水坝会成为黑铁矮人侵略的下一个目标。由于大坝的大部分防御守军已被调往别处，冒险者们被派去调查潜伏在东侧坡道附近的黑铁工兵。",kw={"黑铁矮人","丹莫德","辛德维尔","洛克莫丹","工兵","巨石水坝","可疑木桶","萨多尔大桥"},ang={["faction:Alliance"]="随着大陆各处前线军队兵力吃紧，联盟新兵必须挺身而出，保护重要的后方补给中心和区域基础设施。",["profession:Engineering"]="工程师们既能领略大坝那令人叹为观止的规模，也能意识到工兵在承重地基上部署挥发性化学炸药所带来的阴险威胁。",["race:Dwarf"]="巨石水坝是矮人工艺与荣耀的杰作；眼见它受到阴险的黑铁同族的威胁，使得这项调查成了关乎国家防御的大事。"},sec={{t="脆弱的奇迹",b="巨石水坝是铁炉堡最伟大的工程杰作之一，它拦截了洛克莫丹的浩瀚水域。然而，随着卡兹莫丹及其他地区冲突的持续，大坝的大部分安全守卫已被调往联盟前线。由于兵力短缺，当敌人活动逐渐逼近这座庞大的建筑时，主工程师辛德维尔七世和他留守的精简人手在面对协同攻击时几乎毫无防备。"},{t="来自北方的回响",b="辛德维尔的焦虑源于最近北部边境遭受的破坏。黑铁矮人在湿地发动了致命的协同攻击，破坏了具有战略意义的萨多尔大桥，并洗劫了要塞城镇丹莫德。观察到臭名昭著的黑铁工兵潜伏在大坝东侧坡道附近，辛德维尔意识到其中的规律：这个邪恶氏族已经将目标转向了摧毁洛克湖的生命线。"},{t="可疑的木桶",b="对下层城墙的侦察证实了这位工程师最担心的事。在工兵聚集处的岩石中，藏着一个无人看管、装满了不稳定且散发着奇怪气味的火药的可疑木桶。这充分证明黑铁矮人正在积极筹划爆破，意图摧毁巨石水坝的地基。"}},faq={{q="为什么主工程师辛德维尔会担心大坝的安全？",a="黑铁部队最近破坏了萨多尔大桥并洗劫了丹莫德，摧毁了北方的防线。看到黑铁工兵潜伏在巨石水坝的东侧坡道上，这让辛德维尔确信大坝就是他们的下一个目标。",al={"辛德维尔为何担忧","对巨石水坝的威胁","为什么要攻击水坝"}},{q="大坝的守军去哪了？",a="驻扎在巨石水坝的大部分安全部队，包括辛德维尔手下的高级督察，都被调往支援更广阔的联盟前线，导致这座关键设施防守薄弱。",al={"为什么水坝没有守卫","大坝安保","士兵去哪了"}},{q="你在东侧坡道发现了什么？",a="在发现黑铁工兵踪迹的东侧坡道附近，调查人员发现了一个装有散发奇怪气味火药的可疑木桶，证实黑铁矮人正在安放炸药企图破坏该建筑。",al={"线索是什么","可疑木桶线索","工兵在做什么"}},{q="巨石水坝有什么战略意义？",a="巨石水坝控制着洛克莫丹的水库。如果水坝决堤，洪水将对下游的湿地造成巨大的破坏，同时会排干矮人领地的核心区域。",al={"为什么要摧毁水坝","水坝决堤会发生什么","水坝背景资料"}},{q="辛德维尔提到的针对丹莫德的袭击是什么？",a="丹莫德是位于北部湿地、靠近萨多尔大桥的一座坚固矮人前哨站。黑铁渗透者攻陷了该城镇并袭击了附近的萨多尔大桥，切断了关键的陆路补给线。",al={"丹莫德袭击","丹莫德发生了什么","萨多尔大桥被毁"}},{q="针对洛克莫丹的黑铁矮人是什么人？",a="自三锤之战以来，黑铁氏族长期以来一直是铜须矮人的死敌。他们以黑石山和灼热峡谷为据点，经常破坏铜须矮人的基础设施和边境防御。",al={"黑铁矮人是谁","黑铁工兵的动机","黑铁矮人为何仇恨铁炉堡"}}},fx={f99be494={q="Dark Iron工兵为什么会出现在巨石水坝？",a="在袭击北方的萨多尔大桥和丹莫德之后，Dark Iron矮人悄悄南下，潜入了洛克莫丹。总工程师Hinderweir发现他们的工兵在巨石水坝东侧坡道附近鬼鬼祟祟，怀疑他们接下来打算破坏这座宏伟的建筑。",al={"dark iron工兵水坝","dark iron为什么在水坝","dark iron工兵洛克莫丹"}}},fp="19,188,19.259.0,21.221.0,19.194.1,55.196.0,32.161.0,37.160.1,59.148.0,56.196.0,51.230.0"}
P.entries["quest:251"] = {n="翻译亚伯克隆比的信",s="在夜色镇，翻译亚伯克隆比的信将一封奇怪的信带到了镇上领袖的面前。艾尔罗·埃伯洛克镇长向希拉·沃宁迪求助，这位学者精通晦涩的文字。",h="在夜色镇，翻译亚伯克隆比的信将一封奇怪的信带到了镇上领袖的面前。艾尔罗·埃伯洛克镇长向希拉·沃宁迪求助，这位学者精通晦涩的文字。",kw={"亚伯克隆比","密码","夜色镇","暮色森林","艾尔罗·埃伯洛克","隐士","希拉·沃宁迪","翻译"},ang={["class:Mage"]="身为法师，你或许能看懂希拉·沃宁迪研究夜色镇晦涩文字时所做的工作。",["faction:Alliance"]="作为援助暮色森林的联盟勇士，你能看出，夜色镇的领袖在四周的黑暗中感到何等脆弱与孤立无援。"},sec={{t="无法辨读的信件",b="亚伯克隆比从住处寄给艾尔罗·埃伯洛克镇长一封密封的信。埃伯洛克原以为，这位墓地隐士又在提出古怪的请求，或是满怀怨恨地胡言乱语，但羊皮纸上的奇异文字却无法用寻常的通用语解读。镇长不懂古老或晦涩的语言，却也不愿置之不理。在暮色森林，即便是一个疯癫的隐士，也可能带来危险。"},{t="夜色镇的学者",b="埃伯洛克让你穿过广场，去找夜色镇研究秘学的学者希拉·沃宁迪。希拉通晓古老的技艺与失传的语言。他嘲讽亚伯克隆比神志不清，说任何住在闹鬼墓地旁的人，脑子肯定都烂掉了。尽管如此，他还是认真对待这张羊皮纸，开始了缓慢的誊译工作。"},{t="窥探隐士的内心",b="亚伯克隆比这封加密的信表明，他的心思远比那个索要补给、请求保护以免遭食尸鬼袭击的虚弱孤僻老人所显露的更深。信中的话语警告，一场清算即将到来，而夜色镇对此毫无准备。"}},faq={{q="为什么埃伯洛克镇长不能亲自读懂这张便笺？",a="便笺上的奇异文字让艾尔罗·埃伯洛克镇长无法辨读，因此他将其交给夜色镇精通晦涩文字的学者希拉·沃宁迪。",al={"艾尔罗为何读不懂便笺","埃伯洛克信件翻译","为何需要译者"}},{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是夜色镇的学者，以通晓晦涩的语言、历史和古老技艺而闻名。他研究来自周围树林的神秘文献与遗物。",al={"希拉·沃宁迪是谁","译者是谁","夜色镇学者"}},{q="亚伯克隆比住在哪里？",a="亚伯克隆比住在暮色森林西部、乌鸦岭墓地东北方不远处的一间破旧小屋里，周围尽是不安的亡灵和凶猛的野兽。",al={"亚伯克隆比在哪里","隐士位置","亚伯克隆比暮色森林"}},{q="希拉对亚伯克隆比的便笺有何反应？",a="希拉怀疑亚伯克隆比神志不清，说任何住在墓地旁的人，脑子肯定都烂掉了。尽管如此，他还是仔细查看了这封信，并开始翻译其中晦涩的文字。",al={"希拉如何看待亚伯克隆比","希拉·沃宁迪对话"}},{q="把便笺交给希拉后会发生什么？",a="希拉·沃宁迪让你稍候，等他誊译这封信。他完成后，你将译文带回给艾尔罗·埃伯洛克公爵。",al={"翻译便笺后的任务","翻译亚伯克隆比的便笺之后"}},{q="亚伯克隆比为什么给埃伯洛克镇长写信？",a="亚伯克隆比的便笺使用了艾尔罗无法辨读的文字。希拉·沃宁迪的译文揭示了这位隐士写下的内容。",al={"亚伯克隆比为何寄信","隐士便笺的目的"}}},fp="28,164,25.356.0,24.337.0,32.205.1,48.134.0,22.179.0,28.142.0,47.176.0,44.137.1,45.126.1"}
P.entries["quest:2518"] = {n="月神的泪水",s="“月之泪”是女祭司艾茉拉在月神殿指派的一项庄严任务。伟大的蜘蛛萨丝拉女士曾深受艾露恩女神的眷顾，如今却陷入了疯狂，这迫使The Sisterhood of Elune不得不痛下杀手，以求终结她的苦难，并取回她神圣的丝囊。",h="“月之泪”是女祭司艾茉拉在月神殿指派的一项庄严任务。伟大的蜘蛛萨丝拉女士曾深受艾露恩女神的眷顾，如今却陷入了疯狂，这迫使The Sisterhood of Elune不得不痛下杀手，以求终结她的苦难，并取回她神圣的丝囊。",kw={"达纳苏斯","艾露恩","萨丝拉女士","女祭司艾茉拉","银色丝囊","月之泪","泰达希尔","月神殿","涌泉湖"},ang={["class:Druid"]="德鲁伊们将萨丝拉突如其来的凶猛和折磨视为泰达希尔失衡的又一个令人不安的症状，这使得恢复她灵魂的纯净成为了一种生态上的必要。",["class:Priest"]="侍奉The Sisterhood of Elune的牧师们明白，慈悲有时需要通过痛苦的打击来达成，最终通过一场仪式性的祭献，将一个被腐化的灵魂归还给女神的怀抱。",["race:NightElf"]="对于卡多雷而言，除掉萨丝拉是一个痛苦的提醒，即侵蚀泰达希尔荒野的腐化既不放过卑微的野兽，也不放过艾露恩的神圣伙伴。"},sec={{t="挚爱生物的陨落",b="在达纳苏斯的月神殿宁静的殿堂中，女祭司艾茉拉为萨丝拉女士的悲惨命运感到哀痛。过去，萨丝拉曾被视为艾露恩的眷属。她在夜空下编织出精致的银色蛛网，捕捉泰达希尔枝叶间凝聚的夜雾。她的蛛网所收集的闪烁露水具有神奇的治疗功效，The Sisterhood of Elune会精心收集并保存这些露水，用于她们神圣的祭祀活动。"},{t="对萨丝拉的慈悲",b="正如年轻的世界之树上的许多野生生物一样，萨丝拉女士最近也沦为了某种压倒性疯狂的牺牲品。她的腐化不仅威胁到了路人，也威胁到了她位于涌泉湖附近北部区域尚未孵化的后代。由于她此刻狂暴且躁动不安，已无法将其净化，The Sisterhood of Elune认定终结她的苦难是唯一剩下的慈悲之举。通过取回她的银色丝囊，女祭司们打算将她的遗骸奉献在艾露恩的祭坛上，祈祷月亮女神能赐予她安宁，使她获得纯净的重生。"}},faq={{q="萨丝拉女士是谁？",a="萨丝拉女士是一只泰达希尔本土的雄伟古老蜘蛛。传统上，她被尊为艾露恩的眷属，以编织能捕捉蕴含自然治疗力量的夜雾的银色蛛网而闻名。",al={"萨丝拉女士背景故事","萨丝拉女士是谁","萨丝拉背景","萨丝拉蜘蛛"}},{q="为什么必须杀死萨丝拉女士？",a="她屈服于一种已经感染了泰达希尔野生生物的蔓延疯狂。因为她变得极具攻击性，且对她的后代和其他生物构成了威胁，女祭司们决定将其击杀是一种慈悲的行为。",al={"为什么杀死萨丝拉","萨丝拉可以被拯救吗","为什么萨丝拉会攻击人"}},{q="萨丝拉女士在哪里？",a="萨丝拉女士在泰达希尔的北部荒野，涌泉湖的岸边筑巢。",al={"萨丝拉女士位置","萨丝拉在哪里","寻找萨丝拉"}},{q="萨丝拉女士的蛛网有什么用途？",a="她的蛛网捕捉夜雾，形成了被称为具有深厚治疗力量的强效银色露水，艾露恩姐妹会将这些露水保存在月神殿中。",al={"月之泪含义","萨丝拉蛛网用途","银色露水背景"}},{q="谁给予了“月之泪”这个任务？",a="达纳苏斯月神殿内的一位侍从，女祭司艾茉拉，将此任务给予了值得信赖的联盟冒险者。",al={"谁发布月之泪任务","月之泪任务发布者","女祭司艾茉拉"}},{q="女祭司们将如何处理萨丝拉的丝囊？",a="它们会被作为一种祝圣祭品奉献给神殿祭坛上的艾露恩，祈求女神接纳萨丝拉的灵魂，祝福她，并让她在宁静祥和中重生。",al={"丝囊怎么处理","丝囊用途","献祭给艾露恩"}}},fp="17,205,25.317.0,17.497.1,20.148.0,40.199.0,28.81.0,39.144.0,38.105.0,55.174.0"}
P.entries["quest:2519"] = {n="月神殿",s="月神殿是达纳苏斯的一个入门任务，艾奎恩妮会在任务中指引冒险者寻找女祭司艾茉拉。The Sisterhood of Elune 需要有人协助泰达希尔枝叶中遭受痛苦的古老生物。这是通往庄严慈悲仪式的开端。",h="月神殿是达纳苏斯的一个入门任务，艾奎恩妮会在任务中指引冒险者寻找女祭司艾茉拉。The Sisterhood of Elune 需要有人协助泰达希尔枝叶中遭受痛苦的古老生物。这是通往庄严慈悲仪式的开端。",kw={"达纳苏斯","艾露恩","女祭司艾茉拉","萨丝拉","艾奎恩妮","艾露恩姐妹会","神殿花园","月神殿"},ang={["class:Druid"]="德鲁伊非常关心任何处于困境中的大型野生生物，这使得来自神殿花园的呼唤成为了事关自然和谐的紧急事项。",["class:Priest"]="在达纳苏斯行走的祭司们会被姐妹会的工作自然而然地吸引，协助神职同僚进行治疗和慈悲的仪式。",["race:NightElf"]="对于暗夜精灵来说，响应艾奎恩妮的号召是他们保护泰达希尔神圣生态系统、维护艾露恩祭司教导这一职责的延伸。"},sec={{t="花园的恳求",b="当旅行者漫步在神殿花园的水域和林荫间时，会遇到艾奎恩妮，一位艾露恩的虔诚仆人。她感受到冒险者是有能力的人，便代表她的组织寻求帮助。一只古老的森林生物正在受苦，而姐妹会无法独自处理此事。"},{t="进入月神殿",b="艾奎恩妮指引候选者前往东南方宏伟的月神殿。在那里，女祭司艾茉拉负责协调仪式和实际工作，以处理泰达希尔受困的野生生物，并让富有同情心的盟友准备好执行一项令人悲伤的慈悲任务。"}},faq={{q="谁发布了月神殿任务？",a="艾奎恩妮发布该任务。她站在达纳苏斯神殿花园区域外。",al={"月神殿 任务发布者","在哪里接取 月神殿 任务","谁发布 月神殿"}},{q="女祭司艾茉拉在哪里？",a="女祭司艾茉拉位于宏伟的月神殿内，就在达纳苏斯神殿花园的东南方。",al={"女祭司艾茉拉在哪里","寻找艾茉拉","女祭司艾茉拉位置"}},{q="需要帮助的生物是什么？",a="该生物是萨丝拉，一只泰达希尔受人尊敬的蜘蛛，她的困境引发了一场由祭司主持的慈悲仪式。",al={"什么生物需要帮助","森林生物是谁","任务链的内容是什么"}},{q="这个任务是继续任务链所必需的吗？",a="不是。月神殿只是一个可选的指引任务。你可以直接与神殿内的女祭司艾茉拉交谈，无需先拜访艾奎恩妮即可进行仪式任务。",al={"月神殿 是必须的吗","我可以跳过 月神殿 吗","月神殿 指引任务"}},{q="这个任务之后接什么任务？",a="女祭司艾茉拉会提供月神的泪水任务，指引你结束萨丝拉的痛苦并带回她的银色丝囊。",al={"月神殿 之后的任务","月神殿 后续任务","接下来做什么"}},{q="为什么 艾露恩姐妹会 要向外人寻求帮助？",a="泰达希尔动植物体内挥之不去的腐蚀让姐妹会人手紧缺，迫使女祭司们招募那些尊重自然和女神的有能力的旅行者。",al={"为什么寻求外人帮助","为什么祭司需要帮助","艾奎恩妮的动机"}}},fp="22,184,21.189.0,20.213.0,44.81.0,35.102.0,37.122.0,46.186.0,34.127.0,57.158.0"}
P.entries["quest:252"] = {n="翻译好的信件",s="在暮色森林，你将希拉·沃宁迪翻译好的信件送往夜色镇，交给艾尔罗·埃伯洛克公爵。这是亚伯克隆比故事中的一环，信中带来了有关这位隐士所写内容的消息。",h="在暮色森林，你将希拉·沃宁迪翻译好的信件送往夜色镇，交给艾尔罗·埃伯洛克公爵。这是亚伯克隆比故事中的一环，信中带来了有关这位隐士所写内容的消息。",kw={"亚伯克隆比","夜色镇","埃伯洛克","乌鸦岭","希拉·沃宁迪","把译文交给艾尔罗"},ang={["faction:Alliance"]="身为联盟的勇士，你将在暮色森林的诡诈中得到一次惨痛的教训：在这片森林里信错了人，就可能危及整个聚居地的无辜居民。"},sec={{t="迟来的醒悟",b="连日来，亚伯克隆比的种种请求让旅者们奔波于暮色森林各处。这位年迈的隐士索要丝线、保存好的试剂和私人物品，声称自己需要这些东西才能活下去。希拉·沃宁迪终于破译了他的私人羊皮纸，揭露了真相：这位和善的老人竟是个丧心病狂的防腐师。收集来的材料被用来制造一件可怕的复仇兵器，目标正是夜色镇。"},{t="通往夜色镇的道路",b="翻译好的信件送到艾尔罗·埃伯洛克公爵手中时，这位镇长的脸上顿时失去了血色。无论你当初出于多么高尚的动机伸出援手，送去最后那批物资的举动，都让亚伯克隆比完成了他制造的怪物——缝合怪。信件送达后，这头巨兽便从乌鸦岭墓地出发，沿着道路向东行进。沿途遇到的任何守夜人巡逻队都会惨遭屠戮。"}},faq={{q="翻译好的信件里写了什么？",a="西拉担心亚伯克隆比做了什么难以启齿的恶行。立刻将翻译好的信件送给艾尔罗·埃伯洛克公爵，他能判断夜色镇面临的危险。",al={"信里写了什么","亚伯克隆比的信件内容","翻译了什么"}},{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是一位住在夜色镇的学者。他精通语言，善于分析，能在旁人看不懂字迹时，破译亚伯克隆比晦涩难懂的笔记和信件。",al={"希拉是谁","希拉·沃宁迪的故事"}},{q="艾尔罗为什么责怪玩家？",a="艾尔罗读过翻译好的信件后，才会作出这样的反应。尽快将警告送到他手中。",al={"艾尔罗为什么生气","是我导致缝合怪出现的吗","艾尔罗的反应"}},{q="完成这个任务后会立刻发生什么？",a="将翻译好的信件送给夜色镇的艾尔罗·埃伯洛克公爵。等他读过信，你就会看到他的反应，并知晓信中提到的危险。",al={"什么会触发缝合怪","缝合怪会出现吗","缝合怪事件"}},{q="缝合怪接下来会去哪里？",a="缝合怪与乌鸦岭墓地和夜色镇之间的道路有关。他在亚伯克隆比阴谋中扮演的角色，会随着调查逐渐揭晓。",al={"缝合怪的路线","缝合怪正往哪里走"}},{q="下一个任务是什么？",a="你送达信件后，艾尔罗便会派冒险者继续执行藏尸者的妻子。",al={"下一个任务","翻译好的信之后"}}},fx={["203575b3"]={q="为什么希拉·沃宁迪要把信送给艾尔罗？",a="解读信件后，希拉意识到亚伯克隆比犯下了不可饶恕的罪行，释放出一场可怕的灾祸，而灾祸正蹒跚着逼近夜色镇。他派你立刻警告艾尔罗·埃伯洛克公爵，好让镇上的领袖在灾难袭击城门前做好准备。",al={"为什么要把信送给艾尔罗","希拉·沃宁迪的动机","为什么要送翻译后的信"}},["4e225af8"]={q="为什么希拉派你去警告艾尔罗公爵，而不是亲自前往？",a="最初奉艾尔罗公爵之命解读亚伯克隆比可疑文字的人是你，后来也是你把那封奇怪的信带给了希拉。怪物已经出动，每一秒都至关重要；把警告交给眼前这位能干的冒险者，是最快让镇长收到消息的办法。",al={"为什么让我去找艾尔罗","希拉为什么不自己去找艾尔罗","为什么派玩家去找艾尔罗"}}},fp="19,177,21.388.1,21.368.1,41.154.0,22.179.0,36.109.0,53.137.1,34.137.2,22.90.1"}
P.entries["quest:2520"] = {n="萨丝拉的祭品",s="“萨丝拉的祭品”是达纳苏斯月神殿内举行的一场肃穆仪式的终结。玩家受托带着萨丝拉女士的遗骸，将这只已故生物的丝囊献入艾露恩的神圣之水中，以洗净她灵魂所受的腐化，并让她安息。",h="“萨丝拉的祭品”是达纳苏斯月神殿内举行的一场肃穆仪式的终结。玩家受托带着萨丝拉女士的遗骸，将这只已故生物的丝囊献入艾露恩的神圣之水中，以洗净她灵魂所受的腐化，并让她安息。",kw={"女祭司艾茉拉","达纳苏斯","艾露恩","喷泉","萨丝拉女士","净化","萨丝拉","丝囊","泰达希尔","月神殿"},ang={["class:Druid"]="哀悼泰达希尔瘟疫的德鲁伊们在得知堕落的野兽可以通过净化回归自然循环时，感到了一丝慰藉。",["class:Priest"]="走在月神殿的祭司们亲眼目睹了艾露恩的神圣之光和圣水如何治愈那些因疯狂和腐化而破碎的灵魂。",["race:NightElf"]="对于暗夜精灵来说，这种仪式反映了他们对卡利姆多动植物群所负有的庄严职责：即便生物必须被击杀，它们的灵魂也能通过艾露恩的恩典得到尊崇与净化。"},sec={{t="神圣之水中的净化",b="在萨丝拉女士被悲剧性地击杀后，女祭司艾茉拉交给初学者们一项最终的精神使命。这只巨型蜘蛛沦为了蔓延在泰达希尔的黑暗疯狂的牺牲品，这种疯狂扭曲了她曾经温顺的天性，使她陷入了盲目的攻击性。与其将她的死亡视为简单的捕杀，艾露恩的祭司们寻求救赎她堕落的本质。通过将她的银色丝囊放入月神殿中央的喷泉中，圣水洗去了玷污她的腐化，使她得到了解脱。"},{t="萨丝拉的重生",b="将祭品献给艾露恩会带来即时的精神共鸣。当丝囊触碰到月光下的水池时，萨丝拉女士虚灵的形态从深处升起，平静且洗净了那折磨她陷入疯狂的病痛。The Sisterhood of Elune视此仪式为必要的救赎；尽管痛失这只巨型生物令人悲伤，但暗夜精灵的神学教导说，通过这种神圣的净化，她终有一天能带着纯洁的灵魂重生。"}},faq={{q="萨丝拉女士是谁？",a="萨丝拉女士是一只居住在泰达希尔的巨型蜘蛛，她屈服于折磨世界之树野生动物的蔓延腐化。她因受腐化而陷入疯狂，必须被击杀以使她的遗骸能够得到净化。",al={"萨丝拉女士","萨丝拉是谁","萨丝拉是什么"}},{q="祭品是在哪里献出的？",a="祭品被放入位于月神殿中央的神圣喷泉中，该神殿是达纳苏斯艾露恩姐妹会的中心圣殿。",al={"我该把祭品放在哪里","喷泉位置","神殿喷泉"}},{q="当你把丝囊放入喷泉时会发生什么？",a="在将银色丝囊放入祝福之水中后，萨丝拉那净化的灵魂会短暂地显现在水池中，自由且平静地漫步，象征着艾露恩的接纳。",al={"喷泉处发生了什么","萨丝拉之魂喷泉"}},{q="为什么萨丝拉女士必须死？",a="毒害她心智的腐化太过深重，以至于她在活着的时候无法治愈。女祭司艾茉拉和艾露恩姐妹会认为，拯救她灵魂的唯一方法就是结束她的痛苦，并在艾露恩的神圣之水中洗净她的遗骸。",al={"为什么要杀死萨丝拉","萨丝拉能被拯救吗","萨丝拉的疯狂"}},{q="是谁发布了“萨丝拉的祭品”任务？",a="该任务由在达纳苏斯月神殿内、俯瞰中央大厅的女祭司艾茉拉发布并终结。",al={"任务发布者","在哪里交任务","艾茉拉的位置"}},{q="暗夜精灵的这种仪式背后蕴含着什么信仰？",a="暗夜精灵相信，经由月之母净化的灵魂可以重生于自然世界，他们的精神得到洗涤与更新，不再带有残留的腐化污点。",al={"暗夜精灵转世","艾露恩的净化","重生传说"}}},fp="19,193,28.462.0,22.335.1,21.212.0,31.143.0,59.180.1,33.225.0,40.130.0,54.123.0"}
P.entries["quest:253"] = {n="藏尸者的妻子",s="在夜色镇，艾尔罗·埃伯洛克公爵派你去寻找伊莉莎的坟墓。镇上的人已经得知，藏尸者确实存在，而你要从她受诅咒的遗骸中取出他那颗仍在跳动的心脏，剥夺他的力量。",h="在夜色镇，艾尔罗·埃伯洛克公爵派你去寻找伊莉莎的坟墓。镇上的人已经得知，藏尸者确实存在，而你要从她受诅咒的遗骸中取出他那颗仍在跳动的心脏，剥夺他的力量。",kw={"炼金术师","藏尸者的新娘","夜色镇","暮色森林","伊莉莎","埃伯洛克","藏尸者的心脏","坟墓","藏尸者"},ang={["class:Paladin"]="身为圣骑士，你可以将伊莉莎邪恶的复生视为对Light和自然法则的亵渎。你可以净化这头食人的恐怖怪物，斩断这名通灵师亵渎生命的命脉。",["class:Priest"]="身为牧师，你可以理解这位鳏夫痛失爱妻的悲剧，同时也明白，伊莉莎这个嗜食血肉、嘲弄生命的存在必须在神圣的力量下彻底安息。",["faction:Alliance"]="守夜人在对抗暮色森林的凶残怪物时已捉襟见肘，你必须以联盟勇士的身份挺身而出，保卫夜色镇，抵御这股古老而悄然蔓延的疯狂。"},sec={{t="成真的睡前故事",b="暮色森林的孩子们从小就听着藏尸者的故事长大。据说，他原本是一位善良的炼金术师，却在爱妻伊莉莎死后陷入了疯狂。为了逃脱死亡，他不顾一切地求助于巫术，剖出自己仍在跳动的心脏，放进她的胸膛。艾尔罗·埃伯洛克公爵曾把这个故事当作乡间传说，不以为意。近来的发现却表明，藏尸者正行走于活人之间，而他的造物正在墓地的泥土下腐烂。"},{t="复生的新娘",b="伊莉莎的复生付出了可怕的代价。那夺来的生命火花将她变成了一头饥肠辘辘的怪物，永无止境地渴求着活人的血肉。藏尸者对自己的造物感到恐惧，却又不愿毁掉她，于是将新娘藏进了一座孤坟。他一边秘密探望她，一边谋划更多恶行。如今，埃伯洛克公爵派你去找到伊莉莎的坟墓，杀死这嗜食血肉的恐怖怪物，取走那颗仍在跳动、维系着藏尸者黑暗法术的心脏。"},{t="夜色镇的护盾",b="当你把伊莉莎仍在跳动的心脏带回夜色镇时，埃伯洛克公爵松了一口气。镇长并不打算毁掉它。他打算用这位炼金术师的技艺反过来对付他，利用心脏中的诡异魔法，为夜色镇设下护符与护盾。他希望它能保护这座饱受侵扰的城镇，抵挡衰弱的藏尸者为复仇而施展的任何怒火。"}},faq={{q="藏尸者是谁？",a="藏尸者曾是暮色森林的一名炼金术师，在妻子伊莉莎死后陷入疯狂。他转而钻研通灵术，剖出自己鲜活的心脏，放进她的尸体使她复生，自己也成了一个行踪诡秘的怪物。",al={"藏尸者背景故事","藏尸者是谁","藏尸者的过往"}},{q="伊莉莎既然已经复生，为什么还被埋了起来？",a="炼金术师用自己的心脏复活了伊莉莎，但黑暗魔法使她对活人的血肉产生了无法满足的饥渴。他既无法让她安全地回到人群之中，也无法满足她野兽般的饥饿，只好将她藏在墓地里。",al={"伊莉莎为何被埋葬","伊莉莎的坟墓","为何把伊莉莎藏在坟墓里"}},{q="埃伯洛克公爵为什么想要藏尸者的心脏？",a="艾尔罗相信，藏尸者的心脏就是他的力量之源。他让你趁心脏仍在跳动时，从伊莉莎的坟墓中取走它，相信这样就能摧毁这位炼金术师的力量。",al={"为何取走心脏","藏尸者的心脏用途"}},{q="这条任务线从哪里开始？",a="这条任务线紧接着“翻译好的信件”展开。送到艾尔罗·埃伯洛克公爵手中的旧信件和研究资料证明，当地童谣里的藏尸者仍在活动，而且十分危险。",al={"任务前置条件","如何接取藏尸者的妻子","藏尸者前置任务"}},{q="取回心脏就能彻底击败藏尸者吗？",a="艾尔罗相信，取走心脏就能摧毁藏尸者的力量。接下来会发生什么，等你回到夜色镇便会明白。",al={"藏尸者死了吗","这会杀死藏尸者吗"}},{q="谁发布这个任务？",a="夜色镇的镇长兼领袖艾尔罗·埃伯洛克公爵得知镇上传说背后的真相后，在夜色镇大厅向你交付了这项使命。",al={"任务发布者","谁发布藏尸者的妻子"}}},fp="21,196,26.429.0,21.461.1,17.361.2,20.207.0,53.198.0,50.165.0,34.190.0,58.120.1,21.153.0"}
P.entries["quest:254"] = {n="掘墓",s="你在暮色森林的乌鸦岭墓地寻找藏尸者遗失的心脏。一座标有伊莉莎之名的坟冢下，埋着不肯安息的恐怖之物。",h="你在暮色森林的乌鸦岭墓地寻找藏尸者遗失的心脏。一座标有伊莉莎之名的坟冢下，埋着不肯安息的恐怖之物。",kw={"亚伯克隆比","藏尸者 的新娘","棺材","掘地三尺","暮色森林","伊莉莎","伊莉莎 的坟土","藏尸者 的心脏","乌鸦岭墓地"},ang={["class:Paladin"]="惊扰新坟有违圣光的丧葬仪式。释放并消灭坟中违背自然的恶物，则是一种净化之举。",["class:Priest"]="圣化的泥土下，利爪抓挠，牙齿咬得咯咯作响，亵渎了 Light 向暮色森林死者许诺的安息。",["faction:Alliance"]="守夜人艰难地抵御着从乌鸦岭涌出的恐怖威胁。找出藏尸者埋下的恐怖之物，对夜色镇的安全至关重要。"},sec={{t="惊扰坟墓",b="在乌鸦岭墓地，一片刚翻过的松软泥土上标着伊莉莎的名字。暮色森林的其他坟墓敞露着，任由食腐动物或狂野的食尸鬼出入，但这里的泥土却被人仔细堆放过。挖开表土，便会露出碎裂的棺木板。棺木封存着藏尸者想要藏在日光之外的残存之物。"},{t="棺内的抓挠声",b="伊莉莎躺在碎裂的棺木板下，但她绝非一具安息的尸体。利爪般的手指刮擦着棺盖，腐烂的上下颌咯咯作响，棺盖随之震颤。亚伯克隆比的实验造物正在她的松木棺材里蠢蠢欲动。藏尸者遗失的心脏在她胸中跳动，她正等着毫无戒心的人伸手掘开坟墓。"}},faq={{q="伊莉莎的坟墓里埋着什么？",a="泥土下埋着一口棺材，里面躺着伊莉莎，一个由藏尸者制造的亡灵生物。他的心脏就在她的胸中。",al={"坟墓里有什么","伊莉莎 是谁","伊莉莎 墓中之物"}},{q="这座坟墓在哪里？",a="伊莉莎的坟墓位于暮色森林西部的乌鸦岭墓地，周围是闹鬼的墓穴和游荡的亡灵。",al={"伊莉莎 的坟墓在哪","伊莉莎 坟墓位置","坟土位置"}},{q="为什么必须挖到棺材？",a="你挖开坟墓，是为了面对伊莉莎，取回藏尸者的心脏，结束对他邪恶阴谋的追查。",al={"为什么挖坟","挖掘目的","为什么打开棺材"}},{q="打开棺材后会发生什么？",a="当你打开棺材时，伊莉莎便会挣脱而出。你必须消灭这只挥舞利爪的食尸鬼，才能取回与她一同封在棺内的心脏。",al={"接下来会发生什么","棺材打开后","打开 伊莉莎 的棺材"}},{q="是谁将伊莉莎埋入地下的？",a="藏尸者将伊莉莎埋在乌鸦岭墓地，把他的造物和珍视的心脏藏在那里的坟墓之间。",al={"谁埋葬了 伊莉莎","谁把她放在那里"}},{q="伊莉莎是普通的食尸鬼吗？",a="伊莉莎生前是藏尸者的妻子，他用黑暗魔法将她复活，并将自己的心脏放在她胸中。比起暮色森林道路上游荡的无脑食尸鬼，她更强韧，行动也更有目的。",al={"伊莉莎 是什么怪物","伊莉莎 是食尸鬼吗"}}},fp="24,137,17.297.0,21.292.1,32.118.1,28.105.0,39.115.1,39.124.1,28.104.1,27.175.1"}
P.entries["quest:2541"] = {n="沉睡的德鲁伊",s="奥本·怒爪沉睡在班奈希尔兽穴中，但他的灵魂却被困在翡翠梦境里。瘤背萨满祭司将他的灵魂抽离肉体，并操纵他的躯体在兽穴中游荡。",h="奥本·怒爪沉睡在班奈希尔兽穴中，但他的灵魂却被困在翡翠梦境里。瘤背萨满祭司将他的灵魂抽离肉体，并操纵他的躯体在兽穴中游荡。",kw={"班奈希尔兽穴","兽穴","翡翠梦境","瘤背","奥本·怒爪","萨满巫毒符咒","泰达希尔","沉睡的德鲁伊"},ang={["class:Druid"]="身为德鲁伊，你能体会奥本的困境如同一场清醒的噩梦：在翡翠梦境中沟通时，肉体却遭人夺取，这践踏了德鲁伊沉眠的根本。",["race:NightElf"]="身为暗夜精灵，你知道瘤背熊怪亵渎班奈希尔兽穴的行径，表明他们与Kaldorei之间古老的情谊已衰败到何种地步。"},sec={{t="被扰乱的沉眠",b="暗夜精灵德鲁伊在卡利姆多各地的兽穴中沉睡，灵魂则漫游于翡翠梦境。他们的肉体安卧在石壁的凹室中，平安度过数百年的沉眠。泰达希尔的腐化让瘤背熊怪陷入了绝望的狂暴。在班奈希尔兽穴中，瘤背萨满祭司找到了破坏奥本·怒爪神圣沉眠的方法，将他鲜活的灵魂从沉睡的肉体中抽离。"},{t="巫毒与腐化",b="萨满巫毒符咒是一种护符，能让瘤背萨满祭司操纵奥本失去灵魂的躯体。他的灵魂被困在翡翠梦境中，眼看着自己的肉体在兽穴的通道里徘徊，盲目攻击每一个进入者。奥本的灵魂请你取回一枚瘤背的符咒，好让他加以研究，寻找解除魔法、恢复肉体的方法。"}},faq={{q="奥本·怒爪是谁？",a="奥本·怒爪是一名暗夜精灵德鲁伊，他在班奈希尔兽穴中进入神圣的沉眠，与翡翠梦境沟通。充满敌意的瘤背熊怪控制了他的肉体，使他的灵魂流离在外。",al={"奥本·怒爪","沉睡的德鲁伊是谁","兽穴中沉睡的暗夜精灵"}},{q="奥本的肉体为什么会攻击别人？",a="瘤背萨满祭司将奥本的灵魂与肉体分离，并用黑暗魔法驱动他空无灵魂的躯体。如今，这具躯体守卫着班奈希尔兽穴深处。",al={"奥本为何充满敌意","奥本为何发动攻击","奥本·怒爪的肉体攻击"}},{q="萨满巫毒符咒是什么？",a="萨满巫毒符咒是班奈希尔兽穴中的瘤背萨满祭司携带的一种附魔法器。他们利用其中的黑暗力量，将沉睡的德鲁伊的灵魂抽离肉体，并驱动留下的躯壳。",al={"萨满符咒","巫毒咒符 泰达希尔","萨满巫毒符咒是什么"}},{q="任务期间，奥本真正的灵魂在哪里？",a="奥本的灵魂被困在翡翠梦境中，无法回到自己的肉体。他能在安眠之地附近以微光闪烁的灵体形态，与清醒世界沟通。",al={"奥本在哪里","奥本灵魂的位置","翡翠梦境 奥本"}},{q="班奈希尔兽穴中的熊怪为什么充满敌意？",a="泰达希尔日益加深的污染与疯狂，让瘤背部族与昔日的暗夜精灵盟友反目成仇。瘤背熊怪亵渎了德鲁伊的神圣之地。",al={"瘤背为何疯狂","熊怪腐化 泰达希尔","熊怪为何有攻击性"}},{q="能在不杀死奥本肉体的情况下挽救它吗？",a="研究萨满巫毒符咒，是奥本打破仪式的最初希望。他希望通过检查束缚肉体的魔法，了解其中的奥秘，找到化解危机的方法。",al={"拯救奥本·怒爪","奥本能获救吗","治愈奥本"}}},fp="18,187,19.382.0,21.336.1,21.205.0,36.151.0,32.208.0,45.162.0,53.169.0,44.162.0"}
P.entries["quest:255"] = {n="雇佣兵",s="莫格罗什食人魔正向洛克莫丹东北部推进，塞尔萨玛的镇长埃罗恩·钝鼻雇用了途经此地的战士。铁炉堡已承诺派兵保卫山谷，但援军还要几个月才能抵达。当地的定居点、挖掘场和巨石水坝仍无力抵御威胁。",h="莫格罗什食人魔正向洛克莫丹东北部推进，塞尔萨玛的镇长埃罗恩·钝鼻雇用了途经此地的战士。铁炉堡已承诺派兵保卫山谷，但援军还要几个月才能抵达。当地的定居点、挖掘场和巨石水坝仍无力抵御威胁。",kw={"洛克莫丹","镇长埃罗恩·钝鼻","佣兵","莫格罗什","食人魔","巨石水坝","塞尔萨玛"},ang={["faction:Alliance"]="身为联盟的旅人，你知道洛克莫丹是连接卡兹莫丹与北方诸国的重要通道。食人魔的袭击一旦令这里陷入混乱，就会威胁联盟在东部王国各地的补给线。",["race:Dwarf"]="对身为矮人的你来说，巨石水坝是矮人工程学的无上瑰宝。看到它因铁炉堡的繁文缛节而无人防守，无论你是巡山人，还是来自首都的旅人，Bluntnose的征召都与你切身相关。"},sec={{t="铁炉堡的迟缓运转",b="铁炉堡花了两个月，才答应派出少量士兵保卫洛克莫丹。还要再等两个月，他们才能抵达。敌对势力在山谷外集结，塞尔萨玛的卫兵已捉襟见肘。镇长埃罗恩·钝鼻无法再等援军了。"},{t="群山中的威胁",b="莫格罗什食人魔在洛克湖东北方的山丘中加固了一处营地。他们的势力日益壮大，威胁着塞尔萨玛、铁环挖掘场和巨石水坝。如果水坝遭到攻击或损坏，下游将遭受毁灭性的灾难。\n\n没有正规巡山人分队支援，钝鼻便雇用独立作战的战士，削减食人魔的兵力。他希望为山谷争取时间，抵御食人魔和穴居人的威胁。"}},faq={{q="镇长埃罗恩·钝鼻为什么雇用佣兵，而不动用卫兵？",a="铁炉堡迟迟没有回应洛克莫丹的求援。两个月过去，参议院才批准派出少量士兵保卫山谷，而他们还要再过两个月才能抵达。塞尔萨玛、水坝和当地挖掘场都面临迫在眉睫的威胁，因此布伦特诺斯雇用了独立作战的战士。",al={"为何雇用佣兵","塞尔萨玛卫兵","铁炉堡援助"}},{q="莫格罗什食人魔在哪里？",a="莫格罗什食人魔盘踞在莫格罗什要塞，那里位于洛克莫丹大湖东北方崎岖的峭壁与山丘之间。",al={"食人魔位置","莫格罗什在哪里","莫格罗什营地"}},{q="为什么说巨石水坝正面临危险？",a="巨石水坝调节着整座湖泊的水位，是矮人建筑艺术的瑰宝。它几乎没有驻军防守，附近却有一处莫格罗什营地。布伦特诺斯担心，一场有组织的进攻可能损坏或破坏水坝，引发灾难性的洪水。",al={"为何保护水坝","食人魔与水坝"}},{q="除了食人魔，塞尔萨玛还面临哪些威胁？",a="穴居人从地下遗迹和挖掘场中涌出，遍布洛克湖一带。布伦特诺斯认为它们是巨大的威胁，但附近的食人魔要塞迫使他雇用战士，击退莫格罗什。这样，当地卫兵就能集中力量应对穴居人的入侵。",al={"洛克莫丹的其他威胁","穴居人威胁"}}},fx={bfea2c9c={q="镇长埃罗恩·钝鼻为什么要杀死莫格罗什食人魔？",a="镇长埃罗恩·钝鼻担忧塞尔萨玛及周边地区的存亡。莫格罗什食人魔已在湖泊东北方建立了一座坚固的营地，而铁炉堡迟迟没有派兵防守，使镇子、当地的挖掘场和巨石水坝随时可能遭受毁灭性的袭击。他希望击退食人魔，消除迫在眉睫的威胁，让当地人腾出精力，应对肆虐的穴居人。",al={"镇长埃罗恩·钝鼻的动机","为何杀死莫格罗什食人魔","钝鼻为何雇佣兵"}},["5f9f9ec0"]={q="威胁洛克莫丹的莫格罗什食人魔是谁？",a="莫格罗什是一个野蛮的食人魔氏族，已经侵入洛克莫丹东北部，占据了湖泊另一侧崎岖的丘陵。他们的执行者和蛮兵就在防备薄弱的矮人领地旁，炫示着可怕的蛮力。他们趁当地防线捉襟见肘之际不断壮大，直接威胁着旅人、巨石水坝和附近矮人定居点的安全。",al={"莫格罗什是谁","洛克莫丹的莫格罗什食人魔","莫格罗什食人魔是什么"}}},fp="11,262,23.274.0,23.420.0,71.330.0,37.118.0,49.268.0,59.258.0"}
P.entries["quest:256"] = {n="通缉令：卓克苏尔",s="在洛克莫丹东北部，卓克苏尔麾下的食人魔威胁着当地的定居点和维系山谷生计的设施。镇长埃罗恩·钝鼻希望在更多人丧命之前除掉这名军阀。",h="在洛克莫丹东北部，卓克苏尔麾下的食人魔威胁着当地的定居点和维系山谷生计的设施。镇长埃罗恩·钝鼻希望在更多人丧命之前除掉这名军阀。",kw={"钝鼻","悬赏","卓克苏尔","洛克莫丹","食人魔","巨石水坝","塞尔萨玛"},ang={["faction:Alliance"]="身为联盟的一员，你依靠洛克莫丹的农业资源，以及这里通往丹莫罗的补给路线。塞尔萨玛的安全关系到联盟的军事行动。",["profession:Engineering"]="身为工程师，你知道巨石水坝是矮人土木工程最伟大的杰作之一。任由食人魔破坏它，简直不可想象。",["race:Dwarf"]="身为矮人，你明白，对巨石水坝和附近考古挖掘场的袭击，威胁着族人的骄傲、传承，以及铁炉堡领土的安全。"},sec={{t="洛克湖的威胁",b="如今，食人魔威胁着洛克莫丹东北部，而穴居人和野兽早已在这一带不断侵扰山谷的边界。他们在崎岖的丘陵间扎下营地，行径也不再局限于搜刮拾荒。据当地斥候和镇上官员报告，这些袭击目标明确、接连不断，十分危险。"},{t="卓克苏尔的头颅悬赏",b="镇长埃罗恩·钝鼻认为，卓克苏尔正在指挥对塞尔萨玛、附近一处矮人挖掘场以及巨石水坝的袭击。他担心平民的性命和山谷中这项宏伟工程的安危，因此悬赏征求这名食人魔酋长的性命，无论采用何种手段。必须以卓克苏尔被砍下的头颅作为凭证。"}},faq={{q="是谁悬赏征求卓克苏尔的性命？",a="塞尔萨玛的最高行政长官镇长埃罗恩·钝鼻代表镇子发布了悬赏，以保护这一地区免遭有组织的袭击。",al={"谁想要卓克苏尔死","谁发布了卓克苏尔的悬赏","塞尔萨玛通缉告示"}},{q="为什么铲除卓克苏尔如此紧迫？",a="人们认为，卓克苏尔指挥食人魔袭击塞尔萨玛、铁炉堡的考古挖掘场和巨石水坝，危及矮人的性命和王国的重要工程。",al={"为什么要杀卓克苏尔","卓克苏尔做了什么","卓克苏尔的威胁"}},{q="在哪里能找到卓克苏尔？",a="在洛克莫丹东北角崎岖丘陵间的一处食人魔营地里，可以找到卓克苏尔。",al={"卓克苏尔的位置","卓克苏尔在哪里","洛克莫丹食人魔营地"}},{q="镇长埃罗恩·钝鼻要求提供什么凭证？",a="镇长埃罗恩·钝鼻要求以卓克苏尔被砍下的头颅作为凭证，凭此领取赏金并获得铁炉堡的感激。将头颅直接交给塞尔萨玛的他。",al={"卓克苏尔的头颅","悬赏凭证","交付卓克苏尔悬赏"}},{q="食人魔为什么要袭击巨石水坝？",a="巨石水坝拦蓄着洛克莫丹浩瀚的湖水，是矮人工程技术的伟大杰作。破坏水坝可能导致洪水淹没湿地，并重创矮人的补给线，因此它成了敌对势力眼中极具价值的目标。",al={"为什么袭击水坝","巨石水坝遭袭"}},{q="还有其他食人魔与卓克苏尔一起行动吗？",a="有。卓克苏尔统领着东北部丘陵中的一处食人魔营地，并指挥他们袭击周边地区。",al={"卓克苏尔的氏族","洛克莫丹食人魔","卓克苏尔的追随者"}}},fx={["761222eb"]={q="卓克苏尔是谁？",a="卓克苏尔是一名食人魔蛮兵，掌控着洛克莫丹东北部的食人魔营地。人们认为，针对塞尔萨玛、巨石水坝和当地矮人挖掘场的协同袭击，都是由他在幕后狡诈地策划协调的，因此他是威胁这片山谷安全的最大有组织力量。",al={"卓克苏尔是谁","卓克苏尔目标","关于卓克苏尔"}}},fp="16,180,20.280.0,28.306.0,34.138.0,55.180.0,28.103.0,45.143.0,44.216.0,44.123.0"}
P.entries["quest:2561"] = {n="利爪德鲁伊",s="奥本·怒爪的灵魂在泰达希尔地下的兽穴中等待，无法安息。瘤背熊怪用黑暗魔法束缚了他的身体，而你可以摧毁他失去灵魂的躯壳，打破这道束缚。",h="奥本·怒爪的灵魂在泰达希尔地下的兽穴中等待，无法安息。瘤背熊怪用黑暗魔法束缚了他的身体，而你可以摧毁他失去灵魂的躯壳，打破这道束缚。",kw={"班奈希尔","利爪德鲁伊","翡翠梦境","瘤背","奥本·怒爪","泰达希尔","沉睡的德鲁伊","巫毒咒符"},ang={["class:Druid"]="身为德鲁伊，你明白，当一名沉睡的利爪德鲁伊的灵魂与翡翠梦境交流、肉身留在尘世时，堕落的熊怪亵渎其肉身会带来怎样的危险。",["race:NightElf"]="身为暗夜精灵，你知道泰达希尔本应是你的庇护之所。如今，瘤背熊怪的堕落甚至威胁到了神圣的兽穴。"},sec={{t="分离的灵魂",b="奥本·怒爪在泰达希尔地下的兽穴中沉睡时，堕落的瘤背熊怪对他沉睡的身体施加了巫毒法术。这道魔法将他的灵魂从血肉之躯中撕裂出来，困在了翡翠梦境之中。如今，他的灵魂在附近徘徊，既无法安息，也无法夺回自己的身体。"},{t="赐予肉身的仁慈",b="奥本·怒爪的肉身受到了熊怪的控制。进入附近的洞室，摧毁那具毫无心智、充满敌意的躯壳。然后对他的遗骸使用熊怪的咒符，破除束缚他灵魂的魔法。"}},faq={{q="为什么我必须杀死奥本·怒爪？",a="瘤背熊怪在奥本沉睡时对他施法，将他的身体变成了没有灵魂的傀儡。他的肉身仍在它们的控制之下，因此只有摧毁它，才能破除法术，解放他的灵魂。",al={"为什么杀死奥本","杀死沉睡的德鲁伊","奥本·怒爪的身体"}},{q="巫毒咒符有什么用途？",a="这枚咒符可以破除控制奥本的法术。摧毁他失去灵魂的身体后，对他的遗骸使用咒符，解除束缚他灵魂的魔法。",al={"巫毒咒符用途","如何使用巫毒咒符","瘤背咒符奥本"}},{q="这个任务结束后，奥本会去哪里？",a="奥本·怒爪的身体被摧毁、法术被驱散后，他的灵魂就能离开凡世，前往翡翠梦境安息。",al={"奥本的命运","奥本·怒爪的结局","奥本会活下来吗"}},{q="瘤背为什么使用巫毒魔法？",a="瘤背熊怪已经陷入堕落与疯狂。它们背弃了祖先传承的和谐之道，转而使用邪恶的巫术和黑暗魔法，奴役附近的生物与沉睡的德鲁伊。",al={"熊怪巫毒","瘤背巫毒魔法","熊怪为什么有咒符"}},{q="奥本·怒爪曾是什么人？",a="奥本是一名暗夜精灵利爪德鲁伊，他在泰达希尔的兽穴中进入神圣的沉睡，与翡翠梦境交流。瘤背熊怪打扰了他的安眠，并奴役了他的身体。",al={"奥本是谁","奥本的故事","奥本·怒爪的背景"}},{q="奥本的身体还活着时，他的灵魂仍在和我说话吗？",a="是的。那道法术将奥本的灵魂从肉身中撕裂了出来。他的幽魂出现在洞室入口附近，无法控制或重新进入里面那具受法术控制的空壳。",al={"奥本的幽魂和身体","两个奥本","奥本为什么在两个地方"}}},fp="17,189,16.290.0,19.213.1,36.214.0,34.159.0,36.153.1,41.201.0,22.193.0,61.168.0"}
P.entries["quest:257"] = {n="自豪的猎人",s="“猎人的夸耀”是由洛克莫丹旅行者营地的年轻的达瑞尔发布的一项限时狩猎挑战。这名傲慢的年轻人类急于炫耀他所谓的精湛技艺，竟敢向冒险者挑衅，要求他们在十五分钟的限时内追踪并击杀六只山地秃鹫。",h="“猎人的夸耀”是由洛克莫丹旅行者营地的年轻的达瑞尔发布的一项限时狩猎挑战。这名傲慢的年轻人类急于炫耀他所谓的精湛技艺，竟敢向冒险者挑衅，要求他们在十五分钟的限时内追踪并击杀六只山地秃鹫。",kw={"猎人的夸耀","大胆的达瑞尔","年轻的达瑞尔","旅行者营地","狩猎挑战","洛克莫丹","山地秃鹫","限时任务"},ang={["class:Hunter"]="对于射手和追踪者来说，达瑞尔的比赛是一个有趣的契机，可以在他的主场胜过这个夸夸其谈的新手，并获得一把可靠的弓或枪。",["faction:Alliance"]="旅行者营地是洛克莫丹东南部道路上一个重要的联盟哨所，为崎岖山谷中的狩猎活动提供庇护和补给。",["race:Dwarf"]="习惯了营地老练猎人的矮人们会看出这个人类年轻人的姿态不过是空洞的虚张声势，最好的回应便是默默展现实力。"},sec={{t="年轻射手的傲慢",b="旅行者营地是卡兹莫丹一些最优秀的追踪者和射手的聚集地，但并非屋檐下的每一个人都拥有老兵的谦逊。年轻的达瑞尔——自诩为“大胆的达瑞尔”——总是喜欢轻视路过的冒险者。他坚信这些初出茅庐的外乡人根本无法与他的狩猎本领相提并论，于是他下了一个鲁莽的赌注：在十五分钟内猎杀六只当地的山地秃鹫，否则就承认失败。"},{t="清理食腐动物",b="山地秃鹫在洛克莫丹的悬崖和山坡上盘旋，它们以残羹剩饭为食，并捕食较小的野生动物。虽然成群结队时十分危险，但它们主要被当作测试猎人速度、耐心和准头的基准目标。那些在严格时限内完成任务的人会迅速挫败达瑞尔那膨胀的自尊心，迫使他极不情愿地交出一件远程武器，也为后续的狩猎挑战奠定了基础。"}},faq={{q="这项狩猎挑战是在哪里进行的？",a="该任务起始于位于洛克莫丹东南部荒野的旅行者营地。你需要狩猎的山地秃鹫在附近区域的岩架和开阔的山脊上游荡。",al={"任务地点","达瑞尔在哪里","秃鹫在哪里"}},{q="年轻的达瑞尔是谁？",a="年轻的达瑞尔是一名雄心勃勃、喜欢吹嘘的年轻人类，目前待在旅行者营地。他自称“大胆的达瑞尔”，喜欢挑衅旅行者进行限时狩猎试验，以证明他那自以为是的优越感。",al={"达瑞尔是谁","大胆的达瑞尔背景故事","达瑞尔与旅行者营地"}},{q="为什么狩猎有时间限制？",a="十五分钟的限制是达瑞尔赌注的一部分。他认为在压力下猎杀野生秃鹫是一项远超普通冒险者能力的壮举。",al={"为什么是15分钟","任务计时器","限时挑战"}},{q="完成达瑞尔的挑战后会发生什么？",a="虽然对你的成功感到震惊，但达瑞尔拒绝承认真正的失败。他信守诺言提供了一件武器，然后立即提出了另一个狩猎任务——“猎人的挑战”，目标是体型更大的猎物。",al={"接下来是什么","夸耀后续任务","猎人任务链"}},{q="为什么专门狩猎山地秃鹫？",a="成群的山地秃鹫在洛克莫丹的岩石斜坡上筑巢。它们是一种敏捷的飞行目标，非常适合测试弓箭手或火枪手是否具备真正的实战纪律。",al={"为什么要狩猎秃鹫","秃鹫的作用","洛克莫丹的秃鹫"}},{q="这个任务与旅行者营地的其他任务有关联吗？",a="是的。达瑞尔的测试直接引出了营地的一系列更广泛的狩猎任务，最终目标是追踪那头曾在达瑞尔身上留下伤疤的“老烟鬼”，这也是维琳·迅风为了教训这个狂妄的年轻人而制定的计划的一部分。",al={"与维琳的关系","营地故事","旅行者营地剧情"}}},fx={["4c8cb4f1"]={q="年轻的达瑞尔为什么要向你挑战猎杀秃鹫？",a="达瑞尔对自己的本领极为自负，想要炫耀一番。他自称“胆大的达瑞尔”，瞧不起途经旅行者营地的旅人，认定你会失败。他拿自己的狩猎武器作赌注，定下了苛刻的十五分钟时限，只为证明外来者无法与他的本领相比。",al={"达瑞尔为何要做这件事","达瑞尔的动机","达瑞尔为何发起狩猎挑战"}},["3b45bb0a"]={q="达瑞尔为什么不亲自猎杀秃鹫？",a="达瑞尔并非在寻求帮助，也不是为了安全而减少秃鹫的数量；他提出的是一场夸耀本领的狩猎赌局。他认为这项任务不值得自己出手，并认定一个尚未证明实力的冒险者无法在十五分钟内猎杀六只秃鹫，等你如他所料地失败后，他便又能吹嘘一番。",al={"达瑞尔为何选我","达瑞尔为何不猎杀秃鹫","达瑞尔为何找我"}}},fp="16,134,28.214.0,23.220.0,45.141.0,27.179.0,38.131.0,45.163.1,40.127.0,62.171.1"}
P.entries["quest:258"] = {n="猎人的挑战",s="在旅行者营地，年轻的达瑞尔向你发起挑战，要你在十二分钟内杀死五头年老的山地野猪。他认定洛克莫丹崎岖的高地和危险的野兽会让你失败。",h="在旅行者营地，年轻的达瑞尔向你发起挑战，要你在十二分钟内杀死五头年老的山地野猪。他认定洛克莫丹崎岖的高地和危险的野兽会让你失败。",kw={"野猪","寒脊","达瑞尔","年老的山地野猪","旅行者营地","狩猎","洛克莫丹","年轻人"},ang={["class:Hunter"]="身为猎人，在高地的灌木丛中追踪五头年老的山地野猪，并在严格的时限内将它们杀死，考验着你对付猎物的本领。",["faction:Alliance"]="身为联盟的一员，你可以将旅行者营地视为林地守卫的集结地，他们守护着洛克莫丹的东部边境，抵御野兽和高地上的威胁。",["race:Dwarf"]="身为从寒脊山谷一路历练而来的矮人，你会明白达瑞尔所作的比较，尽管他那居高临下的态度或许更令人难以忍受。"},sec={{t="少年的夸口",b="年轻的达瑞尔与旅行者营地经验老到的猎手们生活在一起，却没有他们那份沉稳与耐心。他用大话和冗长的狩猎故事掩饰自己的稚嫩，其中就包括他如何获得那道“著名”伤疤的絮叨讲述。他不肯承认别人也有本事。他还总是叫错其他猎人的名字，并给初来乍到的人设下严苛的考验，希望挫一挫他们的锐气，挽回自己在营地居民心目中的地位。"},{t="高地狩猎",b="年老的山地野猪在洛克莫丹的峭壁和山坡间游荡。它们体型庞大，皮糙肉厚，被激怒时十分危险。达瑞尔给你十二分钟，要你找到并杀死五头。如果你及时完成，这个大言不惭的年轻人就会尴尬地退缩，假装对自己随口许下的豪赌一无所知。"}},faq={{q="年轻的达瑞尔是谁？",a="达瑞尔是一名年轻又爱吹嘘的人类猎手，住在洛克莫丹东南部的旅行者营地。他急于显得像身边那些年长的老猎人一样厉害，于是吹嘘自己的本领，编造夸张的故事，还向路过的冒险者发起艰难的狩猎挑战。",al={"达瑞尔 是谁","年轻的达瑞尔背景故事","旅行者营地 达瑞尔"}},{q="年老的山地野猪在哪里？",a="年老的山地野猪在旅行者营地周围的山麓、草地和山脊间游荡，也遍布洛克莫丹的南部和东部。它们在营地与中央湖泊之间的高地上觅食。",al={"年老的山地野猪位置","哪里能找到野猪","野猪狩猎区域"}},{q="这场狩猎为什么要限时？",a="达瑞尔只给你十二分钟，因为他认定你会失败。时间十分紧迫，他希望借此让你难堪，证明你之前狩猎成功只是新手的运气。",al={"为什么是十二分钟","为什么限时","猎人挑战时限"}},{q="达瑞尔打了什么赌？",a="达瑞尔拿自己身上穿的衬衣打赌，赌你无法及时杀死五头年老的山地野猪。等你凯旋归来，他立刻装作不记得打过这个赌。",al={"达瑞尔 的赌约","身上穿的衬衣","达瑞尔 拿什么打赌"}},{q="这与猎杀寒脊山谷的野猪相比如何？",a="洛克莫丹年老的山地野猪，比矮人新手在寒脊山谷猎杀的小野猪更强壮，也更凶猛。它们的皮更厚，獠牙在高地的花岗岩上磨得锋利，十分危险。",al={"寒脊 野猪与山地野猪对比","寒脊 对比"}},{q="这条狩猎任务线接下来会通向哪里？",a="当你完成达瑞尔的挑战，让他不再吹嘘后，营地的注意力便转向更严肃的事情：在 维林的报复 中对付危险的老熊奥尔苏迪。",al={"下一个任务是什么","猎人的挑战 之后","狩猎任务线"}}},fx={["4ae04a68"]={q="老山猪是什么？",a="老山猪是洛克莫丹周边峭壁与丘陵地带土生土长的野兽，久经生存磨炼，十分强壮。与寒脊山谷等地游荡的小野猪相比，这些野兽要顽强得多，将它们逼入绝境也更加危险。达瑞尔特意选中它们，想将你的追踪与战斗本领逼到极限，认定你会在紧迫的时限下失败。",al={"洛克莫丹老山猪","为何选择老山猪","这些野猪是什么"}},["33153764"]={q="达瑞尔为什么派你去狩猎，而不亲自出马？",a="年轻的达瑞尔更喜欢待在旅行者营地，受人簇拥，夸大其词地讲述自己那道著名伤疤的来历，而不愿再跋涉到荒野中去。他坚信自己的本领高人一等，不断提出更难的考验，纯粹是为了挫败你的锐气，维护自己在猎人中自封的威望。",al={"达瑞尔为何不狩猎","达瑞尔为何需要我","达瑞尔为何不去狩猎"}}},fp="20,188,15.446.0,17.327.0,27.255.0,43.198.0,23.188.0,24.165.0,48.217.0,40.191.1"}
P.entries["quest:26"] = {n="必修的课程",s="玛斯雷·驭熊者将年轻的德鲁伊从达纳苏斯派往月光林地，学习水之道。在那里，他们会见塞纳里奥议会的一位长者，开始修习水栖形态。",h="玛斯雷·驭熊者将年轻的德鲁伊从达纳苏斯派往月光林地，学习水之道。在那里，他们会见塞纳里奥议会的一位长者，开始修习水栖形态。",kw={"必修的课程","水栖形态","达纳苏斯","德迪利特·星焰","德鲁伊任务","玛斯雷·驭熊者","月光林地","永夜港"},ang={["class:Druid"]="身为德鲁伊，这标志着你修行中的一个里程碑，也为你开启了在波涛之下感悟塞纳留斯恩赐的道路。",["race:NightElf"]="身为达纳苏斯的kaldorei，在月光林地响应塞纳里奥议会的召唤，既是对传统的尊崇，也让你与你古老的导师们建立联系。"},sec={{t="荒野的召唤",b="玛斯雷·驭熊者指引着年轻的暗夜精灵德鲁伊，让他们在达纳苏斯的枝桠间修行。当一名学徒展现出与自然的牢固联系，并准备好承担更大的责任时，玛斯雷便会引导其踏上掌握水之道的旅途。塞纳留斯的恩赐需要专注，而要学会穿越深水而不溺亡，则需要塞纳里奥议会长者的指引。"},{t="前往永夜港",b="学徒离开达纳苏斯，前往海加尔山下的古老圣地月光林地。在永夜港，塞纳里奥议会的资深导师德迪利特·星焰正等待着他们。星焰会判断年轻的变形者是否已准备好接受通往水栖形态的试炼。掌握水之道，既需要强健的体魄，也需要坚定的意志。"}},faq={{q="谁会派我执行这项任务？",a="当你的德鲁伊初期训练取得足够进展后，达纳苏斯塞纳里奥区的德鲁伊训练师玛斯雷·驭熊者就会派你执行这项任务。",al={"任务给予者","谁给予必修的课程","谁开启这项任务"}},{q="这项任务的目的是什么？",a="这是德鲁伊学习水栖形态的起点。你将前往月光林地，接受长者德迪利特·星焰的指导与试炼。",al={"为何做这项任务","水栖形态入门","能获得什么"}},{q="德迪利特·星焰在哪里？",a="德迪利特·星焰住在月光林地月神湖北岸的永夜港。",al={"德迪利特的位置","德迪利特·星焰在哪里","寻找德迪利特"}},{q="德鲁伊如何前往月光林地执行这项任务？",a="德鲁伊可以凭借与自然的精神共鸣，使用传送：月光林地直接前往这片神圣的林地。",al={"如何前往月光林地","前往永夜港"}},{q="与德迪利特·星焰交谈后会发生什么？",a="与德迪利特·星焰交谈后，他会派你参加湖中试炼，考验你在水下的耐力以及保持头脑清明的能力。",al={"后续任务","接下来做什么","必修的课程之后"}}},fp="17,180,20.365.0,21.318.0,27.137.0,34.126.0,36.94.0,45.108.0,48.147.0"}
P.entries["quest:2605"] = {n="口渴的地精",s="加基森的马林·诺格弗格饱受口渴的折磨。传闻西南方仙人掌园里的露水收集者会用特殊的腺体储水，马林希望用其中一个腺体制成饮料，终于解了这难耐的口渴。",h="加基森的马林·诺格弗格饱受口渴的折磨。传闻西南方仙人掌园里的露水收集者会用特殊的腺体储水，马林希望用其中一个腺体制成饮料，终于解了这难耐的口渴。",kw={"仙人掌园","露水收集者","露水腺体","加基森","马林·诺格弗格","塔纳利斯","灌木谷"},sec={{t="能制成饮料的腺体",b="马林听说，加基森西南方生活着一种叫作露水收集者的奇怪生物，会用特殊的腺体储水。马林觉得，一个储满水的腺体或许能用来调制饮料，彻底解决口渴的问题。你受托找到它们栖息的仙人掌园，带回一个这样的腺体。"}},faq={{q="是谁派你去寻找露水腺体的？",a="加基森镇的马林·诺格弗格请你寻找一个饱含露水的腺体，缓解他难耐的口渴。",al={"口渴的地精任务给予者","谁提供口渴的地精任务","马林·诺格弗格"}},{q="露水收集者在哪里？",a="它们生活在塔纳利斯加基森西南方，灌木谷的仙人掌园里。",al={"露水收集者位置","哪里能找到露水腺体","仙人掌园位置"}},{q="哪种生物身上有饱含露水的腺体？",a="这些腺体来自灌木露水收集者，据说这种生物会用特殊的腺体储水。",al={"什么掉落饱含露水的腺体","露水收集者怪物"}},{q="任务链的下一步是什么？",a="任务链的下一步是好味道。",al={"口渴的地精后续任务","口渴的地精之后的任务"}}},fp="18,232,22.259.0,40.107.0,37.103.0,42.76.0,29.39.0"}
P.entries["quest:2606"] = {n="好味道",s="马林·诺格弗格觉得灌木露水的味道糟透了，但他决定不放弃。你带着灌木露水被派去找加基森的斯普林克，她是马林的一位朋友。",h="马林·诺格弗格觉得灌木露水的味道糟透了，但他决定不放弃。你带着灌木露水被派去找加基森的斯普林克，她是马林的一位朋友。",kw={"加基森","好品味","马林·诺格弗格","斯普林克","塔纳利斯","灌木露水"},sec={{t="糟糕的饮料，蹩脚的厨师",b="马林尝了尝灌木露水，觉得味道很可怕，但他最终决定不放弃这个想法。相反，他把灌木露水交给你，让你去找加基森的一位朋友斯普林克，马林称赞她是一位出色的厨师。你要告诉她发生了什么事，并说明这种饮料需要更容易入口。马林还希望它能有点劲儿。"}},faq={{q="这一步在任务链中处于什么位置？",a="它紧接在“口渴的地精”之后，之后是“斯普林克的秘密配料”。",al={"前置任务","任务链后续","任务进度"}},{q="为什么马林·诺格弗格想把灌木露水带给斯普林克？",a="马林觉得灌木露水很难喝。他称赞斯普林克是一位出色的厨师，希望她能让饮料更容易入口，并且更有劲儿。",al={"为什么找斯普林克","马林对斯普林克的要求","斯普林克是谁"}},{q="在哪里可以找到斯普林克？",a="斯普林克在加基森，和马林·诺格弗格在同一个城镇。",al={"斯普林克位置","斯普林克在哪","寻找斯普林克"}}},fp="13,143,21.278.0,38.75.0,59.155.0,28.62.0"}
P.entries["quest:261"] = {n="血色之路",s="位于尼耶尔前哨站的血色十字军安东兄弟说，他的组织正在与天灾军团作战，这是一种腐蚀人民并感染大地的邪恶力量。他要求你消灭白骨之谷中的三十个亡灵劫掠者来证明你的忠诚。",h="位于尼耶尔前哨站的血色十字军安东兄弟说，他的组织正在与天灾军团作战，这是一种腐蚀人民并感染大地的邪恶力量。他要求你消灭白骨之谷中的三十个亡灵劫掠者来证明你的忠诚。",kw={"安东兄弟","凄凉之地","血色之路","尼耶尔前哨站","血色十字军","天灾军团","亡灵劫掠者","白骨之谷"},sec={{t="证明忠诚",b="安东兄弟说话很直接。他说必须在天灾军团吞噬这片土地并将世界拖入黑暗之前阻止它们，而血色十字军已经发誓要进行这场战斗。如果你与他们站在一边，他希望你能通过消灭三十个亡灵劫掠者来展示你的勇气和忠诚。它们就在安东南部的白骨之谷。成功的话，十字军会欢迎你。"}},faq={{q="谁要求你消灭亡灵劫掠者？",a="位于尼耶尔前哨站的血色十字军安东兄弟。",al={"谁给予血色之路任务","安东兄弟任务","凄凉之地血色十字军非玩家角色"}},{q="在哪里可以找到亡灵劫掠者？",a="在凄凉之地的白骨之谷，位于尼耶尔前哨站的南面。",al={"亡灵劫掠者位置","白骨之谷在哪里","凄凉之地的劫掠者"}},{q="安东兄弟为什么要消灭这些劫掠者？",a="他说十字军正在与天灾军团作战，这是一种腐蚀人民并感染大地的邪恶力量，他希望以此让你证明你的忠诚。",al={"为什么要杀死亡灵劫掠者","安东兄弟动机","血色十字军原因"}},{q="需要消灭多少个劫掠者？",a="三十个。",al={"需要多少个劫掠者","劫掠者数量"}},{q="在此之前需要做什么？",a="首先是与安东兄弟会面。",al={"前置任务","血色之路的前置条件"}}},fp="21,93,19.315.0,44.63.0,36.83.0,51.132.0,36.33.0,23.29.0"}
P.entries["quest:262"] = {n="模糊的人影",s="在自家农场的废墟附近，斯温·约根寻找着那个目睹他家人惨死的陌生人。他把一本从废墟中找到的古怪书籍交给你，请你查明是谁留下了它。",h="在自家农场的废墟附近，斯温·约根寻找着那个目睹他家人惨死的陌生人。他把一本从废墟中找到的古怪书籍交给你，请你查明是谁留下了它。",kw={"书","夜色镇","暮色森林","伊瓦夫人","神秘人影","斯温·约根","斯温的营地"},ang={["class:Priest"]="身为牧师，你能看出灵性洞察、暗影魔法与普通物品上残留的精神印记之间有着多么紧密的联系。",["faction:Alliance"]="夜色镇几乎得不到暴风城的支援，因此，饱受创伤的边民和当地先知只能完全依靠四处游历的联盟勇士，调查暮色森林中那些夺人性命的暴行。"},sec={{t="惨案的回响",b="斯温·约根藏身于暮色森林西部的山丘中，家人惨遭杀害的阴影至今仍挥之不去。他曾将惨案归咎于那些在林中散播恐惧的黑衣骑手，但另一段记忆令他不安：惨案发生的那一夜，附近有一个神秘人影。斯温把那本在遭到洗劫的农场里找到的古怪书籍交给你，这是废墟中留下的唯一实物线索。"},{t="赴镇求占",b="危险的荒野中没有明确的线索可循，于是你向东前往夜色镇。斯温希望那些迷信的镇民中有人能认出这本奇特的书。伊瓦夫人便是其中之一，她的神秘感知能让她看见常人目力之外的事物。她的占卜或许能揭示神秘遗物上残留的印记。"},{t="外来的线索",b="伊瓦夫人从书中读出了微弱的印记。斯温近来的复仇渴望已在书页上留下印记，但在其下还潜藏着另一股气息。艾瓦感知到，最初的主人来自夜色镇和暮色森林以外的地方，而且在血案发生前就已到访过农场。"}},faq={{q="斯温·约根是谁？",a="斯温·约根是一个悲痛欲绝的农夫，流落在暮色森林西部的山丘中。黑衣骑手在他的家园杀害了他的家人，悲痛驱使他遁入荒野，寻求向凶手复仇。",al={"斯温是谁","斯温的身世","斯温·约根"}},{q="在斯温的农场找到的是什么书？",a="这本书是从斯温被毁家园的泥土和瓦砾中找回的一件实物。在斯温的家人遭袭时，一个行踪隐秘的旁观者潜伏在阴影中，随后留下了这本书。",al={"这是什么书","斯温农场的书","神秘的书"}},{q="为什么要把书带给伊瓦夫人？",a="伊瓦夫人是夜色镇的先知和占卜师。普通镇民无法从一本没有标记的书中看出多少端倪，但她的灵视能读出先前拥有或携带过这本书的人所留下的精神印记。",al={"为何找伊瓦夫人","谁来解读这本书","夜色镇的秘术师"}},{q="伊瓦夫人从书中得知了什么？",a="伊瓦夫人感知到，斯温近日接触这本书时留下了强烈的复仇印记。在这层印记之下，她察觉到了微弱的痕迹，表明最初的主人来自夜色镇以外的地方。",al={"艾瓦说了什么","书主人的身份","占卜结果"}},{q="接下来要去哪里调查？",a="伊瓦夫人得知，这本书的主人来自夜色镇以外的地方。她让你查阅镇上的记录，并到熟悉的地方寻找，看是否有人记得与那个人影相符的陌生旅人。",al={"接下来做什么","书之后的任务","神秘人影是谁"}}},fp="18,172,21.313.0,26.302.0,15.275.1,19.232.0,38.201.0,32.213.0,41.191.1,40.199.1"}
P.entries["quest:2622"] = {n="丢失的命令",s="一问起失踪的命令，分队指挥官鲁尔格就怒气冲冲，坚称命令已经传达。鲁尔格说，携带命令的士兵遭到了鱼人的伏击，只有一人活了下来，并让你去找本戈尔谈谈。",h="一问起失踪的命令，分队指挥官鲁尔格就怒气冲冲，坚称命令已经传达。鲁尔格说，携带命令的士兵遭到了鱼人的伏击，只有一人活了下来，并让你去找本戈尔谈谈。",kw={"伏击","本戈尔","分队指挥官鲁尔格","失踪的命令","鱼人","悲伤沼泽"},sec={{t="鲁尔格的说法",b="鲁尔格觉得这个问题冒犯了他，坚称命令已经传达。据鲁尔格所说，奉命送信的士兵遭到了鱼人的伏击和毒打，只有一人活了下来，如果那还算活着的话。幸存者几乎说不出话，无法行走，只能靠管子进食。鲁尔格说，要想知道命令的下落，就去问本戈尔，他就在这附近的某个地方。鲁尔格还警告你，少把鼻子伸进不该管的事里，小心被咬掉。"},{t="本戈尔断断续续的话语",b="你找到本戈尔时，他只能断断续续地吐出一些零碎的话语，其中你听到了 沼泽空谈者 这几个字。"}},faq={{q="是谁派人送出那份失踪的命令？",a="分队指挥官鲁尔格说，命令已经交由派出的士兵传达，但一被问起命令的下落，他就满心戒备。",al={"谁下达了失踪的命令","谁弄丢了命令"}},{q="携带命令的士兵遭遇了什么？",a="据分队指挥官鲁尔格所说，他们遭到了鱼人的伏击和毒打，只有一人活了下来。",al={"信使遭遇了什么","命令是怎么丢失的"}},{q="本戈尔是谁？",a="本戈尔是那场伏击中唯一的幸存者。他几乎说不出话，无法行走，只能靠管子进食。",al={"幸存者是谁","本戈尔的故事"}},{q="在哪里能找到本戈尔？",a="分队指挥官鲁尔格只说，本戈尔就在这附近的某个地方。",al={"本戈尔的位置","本戈尔在哪里"}}},fp="18,77,14.352.0,22.93.1,38.125.0,50.116.0,14.103.0,26.56.0"}
P.entries["quest:2623"] = {n="沼泽空谈者",s="本戈尔几乎说不出话，但还是勉强讲清了命令的下落。调度指挥官交给了他们命令，而他们在前往诅咒之地的途中遭到大批鱼人伏击。其中一个名叫沼泽空谈者的鱼人从他手中夺走了命令。必须夺回命令，交给部落英雄的灵魂。",h="本戈尔几乎说不出话，但还是勉强讲清了命令的下落。调度指挥官交给了他们命令，而他们在前往诅咒之地的途中遭到大批鱼人伏击。其中一个名叫沼泽空谈者的鱼人从他手中夺走了命令。必须夺回命令，交给部落英雄的灵魂。",kw={"本戈尔","诅咒之地","部落英雄的灵魂","鱼人","悲伤沼泽","沼泽空谈者","酋长的命令"},sec={{t="本戈尔断断续续的讲述",b="本戈尔说，调度指挥官下达了命令，他的小队在前往诅咒之地的途中遭到大批鱼人伏击。就在一支长矛刺入他的头颅时，一个名叫沼泽空谈者的鱼人从他手中夺走了命令。本戈尔勉强提到东边的一个洞穴，随后便昏了过去。必须夺回命令，交给部落英雄的灵魂。"},{t="陨落英雄的悔悟",b="部落英雄的灵魂发现，情况比想象中更糟。倘若当初没有如此鲁莽行事，英雄麾下的十九名部下本可以免受苦难。英雄无力采取行动，只能催促你去帮助那些人。"}},faq={{q="谁偷走了酋长的命令？",a="伏击期间，一个名叫沼泽空谈者的鱼人从本戈尔手中夺走了命令。",al={"谁拿走了命令","沼泽空谈者是谁","谁偷走了命令"}},{q="沼泽空谈者去了哪里？",a="本戈尔逐渐微弱的话语中提到了东边的一个洞穴。",al={"沼泽空谈者在哪里","沼泽空谈者位置","鱼人洞穴在哪里"}},{q="本戈尔和他的小队原本要去哪里？",a="他们带着调度指挥官的命令前往诅咒之地，途中遭到了鱼人的伏击。",al={"本戈尔的目的地","本戈尔原本要去哪里","本戈尔小队的目标"}},{q="应该把命令交还给谁？",a="必须把命令交给部落英雄的灵魂。",al={"酋长的命令交给谁","在哪里交还命令","交付沼泽空谈者任务"}}},fp="16,123,23.342.0,27.223.1,32.83.0,30.49.0,39.117.0,38.48.0"}
P.entries["quest:263"] = {n="保卫国王的领土",s="此任务代表了铁炉堡的巡山人为了对抗洛克莫丹南部的穴居人入侵而进行的不断升级的斗争。巡山人沃尔班在南部哨塔指挥着经验丰富的招募兵进入碎石怪之谷，以清除危险的穴居人萨满和前线碎骨者。完成此试炼将赢得沃尔班的充分信任，并获得与该哨所指挥官拉格弗斯上尉面谈的机会。",h="此任务代表了铁炉堡的巡山人为了对抗洛克莫丹南部的穴居人入侵而进行的不断升级的斗争。巡山人沃尔班在南部哨塔指挥着经验丰富的招募兵进入碎石怪之谷，以清除危险的穴居人萨满和前线碎骨者。完成此试炼将赢得沃尔班的充分信任，并获得与...",kw={"碎骨者","铁炉堡","洛克莫丹","麦格尼","巡山人","萨满","碎石怪","穴居人","沃尔班"},ang={["class:Shaman"]="直面碎石怪穴居人粗陋的施法者，可以让你以一种原始、野蛮的角度审视被野性本能扭曲的大地魔法。",["faction:Alliance"]="援助南部哨塔能够巩固连接丹莫罗、东部湿地以及暴风城王国的重要贸易和旅行路线。",["race:Dwarf"]="响应沃尔班的号召对于任何矮人来说都是保家卫国之事，在同族正规军被调往海外时，站出来保护洛克莫丹的家园。"},sec={{t="单薄的矮人防线",b="洛克莫丹的防御已捉襟见肘。随着矮人正规预备役被征调至艾泽拉斯各地的遥远前线，像南部哨塔这样的地方哨所人手严重不足。巡山人沃尔班和他的几位同袍面临着碎石怪部族的持续压力，这迫使他们不得不极度依赖到访的联盟旅者来守住南部的关口。"},{t="目标：碎石怪先锋",b="与其猎杀零星的斥候，此项行动将更深入地打击碎石怪的层级结构。穴居人碎骨者为部族提供了残酷的蛮力，而他们原始的萨满则编织大地魔法来集结同族。消灭二十个此类高价值目标将削弱他们对低地的入侵，直接服务于国王麦格尼·铜须对王国的保卫工作。"}},faq={{q="巡山人沃尔班是谁？",a="巡山人沃尔班是一位驻扎在洛克莫丹南部哨塔的铁炉堡矮人。他的任务是监控从山脉中蔓延出来的穴居人活动，并协调民兵力量以确保南部主干道的安全。",al={"沃尔班","沃尔班是谁","巡山人沃尔班背景故事"}},{q="为什么巡山人要向旅者寻求帮助？",a="铁炉堡的军事预备役已被征调至王国境内及海外更优先的战线。这种重新部署使得像洛克莫丹南部岗哨这样的边境哨所面对当地威胁时，人手严重短缺。",al={"为什么矮人需要帮助","铁炉堡卫兵在哪里","为什么没有预备役"}},{q="这些穴居人位于何处？",a="它们主要聚集在碎石怪之谷，隐藏在洛克湖西南方崎岖的丘陵中。这些萨满和碎骨者的小股部队也会出没于湖面上北部的岛屿。",al={"碎石怪穴居人在哪里","碎石怪萨满位置","碎石怪之谷在哪里"}},{q="碎石怪部族为何构成威胁？",a="穴居人繁殖迅速，并通过纯粹的地下虫群淹没定居区域。碎石怪部族通过其萨满施展粗糙的元素魔法，并依靠凶猛的碎骨者撕裂矮人斥候，威胁着附近的定居点和贸易路线。",al={"为什么穴居人很危险","碎石怪威胁"}},{q="在这项任务之后巡山人沃尔班会做什么？",a="在确认你是效忠于麦格尼国王的可靠战士后，沃尔班会指引你去向拉格弗斯上尉报到，以获取更多关于保卫洛克莫丹的战略指令。",al={"沃尔班任务之后做什么","上尉是谁"}},{q="在这场危机中，谁统治着铁炉堡？",a="国王麦格尼·铜须在铁炉堡的王座厅统治着矮人王国。为保卫洛克莫丹所做的每一份努力都是以他的名义进行的，旨在捍卫他的主权领土。",al={"矮人国王是谁","铁炉堡国王"}}},fx={["20cd043f"]={q="巡山人沃尔班为什么要杀死这些穴居人？",a="洛克莫丹各地的穴居人之患日益严重，威胁着铁炉堡领土的安全。巡山人预备队被调往遥远的前线后，沃尔班和驻守南部哨塔的同伴便陷入了孤立无援的境地。他需要削减穴居人的数量，保护山谷，以国王之名守住防线。",al={"为何杀死碎石穴居人","沃尔班的动机","沃尔班为何要杀死穴居人"}},c0ccff20={q="碎石萨满祭司和断骨者是什么？",a="他们是侵入洛克莫丹的碎石穴居人氏族中各有所长的先锋。断骨者是氏族中残暴而强悍的执行者，萨满则驾驭着原始而狂野的魔法。他们共同构成了穴居人涌出地底、侵入矮人领土的核心力量。",al={"碎石萨满祭司","碎石断骨者","穴居人目标是谁"}}},fp="30,305,19.346.0,36.308.0,28.214.0,51.201.0,31.186.0,43.218.0,50.174.0,39.159.0"}
P.entries["quest:264"] = {n="至死方休",s="“直到死亡将我们分离”是一个充满苦涩的个人任务，它将玩家引向银松森林的瑟伯切尔。克拉莉斯·弗斯特，一位居住在雷霆崖下方预见之池的被遗忘者，派遣冒险者将她的坠饰丢弃在她已故丈夫尤里夫的墓碑上。这项任务揭示了当瘟疫席卷洛丹伦时，狂热与战争所造成的人性破碎。",h="“直到死亡将我们分离”是一个充满苦涩的个人任务，它将玩家引向银松森林的瑟伯切尔。克拉莉斯·弗斯特，一位居住在雷霆崖下方预见之池的被遗忘者，派遣冒险者将她的坠饰丢弃在她已故丈夫尤里夫的墓碑上。这项任务揭示了当瘟疫席卷洛丹伦...",kw={"克拉莉斯·弗斯特","十字军东征","被遗忘者","坠饰","瑟伯切尔","银松森林","坟墓","尤里夫"},ang={["class:Priest"]="这个任务描绘了一幅关于信仰的残酷画面，突显了对圣光的狂热是如何拆散家庭，并给幸存者心中留下持久的苦涩。",["faction:Horde"]="帮助克拉莉斯可以让部落的勇士们深入了解将银松森林的被遗忘者们凝聚在一起的个人悲剧与持久怨恨。",["race:Undead"]="对于被遗忘者来说，克拉莉斯的困境体现了生者的虚伪：圣战战士们为了狂热的信仰离开了家人，任由他们毁灭，留下的只有那些被转化后的幸存者来承受记忆的重负。"},sec={{t="苦涩的纪念品",b="克拉莉斯·弗斯特对她凡人婚姻的回忆毫无留恋。当洛丹伦分崩离析时，她的丈夫尤里夫抛弃了她和孩子们，去参加一场针对日益壮大的亡灵威胁的十字军东征，并声称侍奉圣光高于一切。最终，他的虔诚既没能拯救他的家庭，也没能拯救他自己。如今，克拉莉斯已复生成为亡灵，而尤里夫则在破损的墓碑下腐烂，她只想抛弃这最后一件关于他那破碎诺言的有形信物。"},{t="被遗弃的坟墓",b="尤里夫的墓位于瑟伯切尔周围的墓地中，墓碑上伤痕累累，散落着垃圾，并长满了杂草。将克拉莉斯的坠饰放在他双手雕像的浮雕上，并没有引发什么伟大的魔法或精神上的解脱，只是让宝石变得暗淡，并有一阵冰冷、静默的风吹过坟墓。这无声地见证了洛丹伦亡者心中挥之不去的怨恨。"}},faq={{q="尤里夫是谁？",a="尤里夫是克拉莉斯·弗斯特身为凡人时的丈夫。生前，他为了以圣光之名对抗天灾军团，抛下了她和孩子们，将十字军东征置于家庭之上。",al={"尤里夫是谁","尤里夫背景故事","克拉莉斯的丈夫"}},{q="为什么克拉莉斯如此痛恨她已故的丈夫？",a="克拉莉斯曾无数次在夜晚等待尤里夫归来，而他却将宗教职责放在首位。最终，他的十字军东征没能保护她们，他死在了一座荒废的坟墓里，而她却被诅咒复生，变成了他生前极力对抗的那种亡灵怪物。",al={"克拉莉斯为何愤怒","克拉莉斯·弗斯特背景"}},{q="归还坠饰后会发生什么？",a="当坠饰被放置在尤里夫雕像的双手上时，宝石明显变暗了。一阵寒冷、僵硬的微风吹过瑟伯切尔，留下了那座被损毁的坟墓，在寒冷与寂静中被遗弃。",al={"坟墓上的坠饰","直到死亡将我们分离结局"}},{q="尤里夫的墓在哪里？",a="尤里夫的墓碑位于瑟伯切尔的墓地区域，那是被遗忘者在银松森林北部设立的据点。",al={"尤里夫的墓在哪里","尤里夫墓地位置"}},{q="为什么尤里夫的坟墓损毁得如此严重？",a="坟墓被利刃划破，堆满了垃圾，并长满了杂草。生活在瑟伯切尔的被遗忘者对一个死于对抗他们同类的十字军战士毫无同情或敬意。",al={"为什么坟墓被损毁","坟墓遭破坏"}},{q="克拉莉斯的孩子们幸存了吗？",a="克拉莉斯提到尤里夫在抛弃她的同时，也抛弃了他们的孩子，但他们的最终命运并未提及。考虑到洛丹伦所遭受的彻底毁灭，他们很可能遭遇了悲惨的结局。",al={"孩子们发生了什么","克拉莉斯的孩子"}}},fp="22,220,17.409.0,19.328.0,14.166.0,47.191.0,41.178.1,30.104.0,32.174.0,31.149.0"}
P.entries["quest:2641"] = {n="斯普琳科的秘密佐料",s="马林·诺格弗格调制的药剂味道糟糕，加基森的斯普琳科提出用她的秘密配料，一种叫紫色水生菇的蘑菇，来改善它的味道。它生长在辛特兰一座小湖的水下。",h="马林·诺格弗格调制的药剂味道糟糕，加基森的斯普琳科提出用她的秘密配料，一种叫紫色水生菇的蘑菇，来改善它的味道。它生长在辛特兰一座小湖的水下。",kw={"加基森","辛特兰","蘑菇","诺格弗格","斯普琳科","塔纳利斯","紫色水生菇"},sec={{t="厨师的秘密",b="斯普琳科说起了自己的童年，那时饭菜全由姐姐来做，味道实在难以下咽。后来，她找到了一种蘑菇，也就是紫色水生菇，成了她的“秘密”配料，让每一道菜都变得美味可口。她打算用它来帮忙，让马林那难喝的药剂变得可以入口。"},{t="水面之下",b="这种蘑菇生长在辛特兰的一座小湖里。瓦罗温湖就在横贯这片地区的道路南侧。紫色水生菇只生长在水下，所以你得潜入水中采集，然后返回加基森，去找斯普琳科。"}},faq={{q="斯普琳科是谁？",a="斯普琳科是加基森的一名厨师，也是马林·诺格弗格的朋友，是他让你带着难喝的药剂来找她的。",al={"斯普琳科是谁","斯普琳科 加基森","斯普琳科的秘密配料 任务给予者"}},{q="紫色水生菇是什么？",a="它是斯普琳科小时候发现的一种蘑菇，被她称为秘密配料。她说，它能让任何东西都变得美味可口。",al={"紫色水生菇","紫色水生菇是什么","秘密配料 蘑菇"}},{q="在哪里能找到紫色水生菇？",a="只在辛特兰一座小湖的水下生长。瓦罗温湖就在横贯这片地区的道路南侧。",al={"紫色水生菇在哪里","哪里能找到秘密配料","紫色水生菇位置"}},{q="这和马林·诺格弗格有什么关系？",a="马林调制的药剂味道糟糕，所以斯普琳科想用紫色水生菇让它变得可以入口。",al={"斯普琳科为什么需要这个","马林·诺格弗格的关联","诺格弗格任务线"}}},fp="28,172,15.274.0,15.223.0,16.114.0,26.130.0,37.130.0,44.87.0"}
P.entries["quest:265"] = {n="继续搜寻",s="在暮色森林，追查日记来历的线索从伊瓦夫人那里引向了夜色镇的书记员达尔塔。这本日记来自斯温·约根遭到洗劫的农庄废墟。",h="在暮色森林，追查日记来历的线索从伊瓦夫人那里引向了夜色镇的书记员达尔塔。这本日记来自斯温·约根遭到洗劫的农庄废墟。",kw={"书","书记员达尔塔","夜色镇","暮色森林","日记","伊瓦夫人","神秘身影","斯温·约根"},ang={["class:Rogue"]="身为潜行者，你知道如何借助购买记录和商人的记忆，追踪一个在镇上活动、神色紧张的目标。",["faction:Alliance"]="对联盟而言，追查是谁为暮色森林的死灵法师提供物资和援助，关系到夜色镇的安全，也关系到能否为惨遭屠戮的边境农户伸张正义。"},sec={{t="追查装帧",b="伊瓦夫人察觉，日记的作者是个外来者，但日记的装帧却出自夜色镇。书记员达尔塔经常向游历至此的学者、施法者和记录员出售空白账簿与书册。调查沿着这些本地交易展开，寻找那个闯入暮色森林林地的邪恶之徒的线索。"},{t="紧张的买家",b="尽管夜色镇的城镇大厅经手的文书众多，书记员达尔塔仍记得这笔买卖。大约一个月前，一名神色紧张的旅人买下了那本空白书册，没有留下姓名。这个鬼鬼祟祟的买家不断回头张望，给书记员留下了鲜明的印象。斯温瞥见的那个神秘身影，曾公然行走在夜色镇的居民之间。"}},faq={{q="那本神秘的书从何而来？",a="伊瓦夫人说，作者对夜色镇而言是个陌生人，但书是在镇上买的。书记员达尔塔出售空白书册，或许还记得是谁买下了它。",al={"书的来历","谁卖的书","书的来源"}},{q="伊瓦夫人为什么让你去找书记员达尔塔？",a="伊瓦夫人察觉，这本书的装帧和用料表明它是在本地购得的。书记员达尔塔向当地居民和游历至此的学者出售空白账簿与日记本。",al={"为什么找达尔塔","艾瓦与达尔塔的联系","谁制作了这本书"}},{q="书记员达尔塔还记得买家的哪些情况？",a="达尔特里记得，大约一个月前，一名神色紧张、没有留下姓名的旅人买下了那本空白书册。",al={"谁买了书","买家描述","神秘身影的外貌"}},{q="这与斯温的农场有什么联系？",a="这本书是从斯温·约根位于暮色森林南部、已被摧毁的农场中找回的，那场杀害他全家的血腥袭击过后，它被留在了那里。",al={"与斯温的联系","为什么要调查","斯温·约根"}},{q="调查接下来指向哪里？",a="调查将在夜色镇的血鸦旅店继续，那里或许有人见过那个神色紧张的陌生人住在哪里，或是与谁交谈过。",al={"接下来做什么","找过达尔塔之后","下一条线索"}},{q="书记员达尔塔有危险吗？",a="达尔特里正在协助辨认一名从他日常售书生意中买过书的顾客。交谈中没有任何迹象表明他本人受到了威胁。",al={"书记员达尔塔的危险","达尔塔是否安全"}}},fp="28,143,19.295.0,15.332.1,40.144.0,45.164.0,48.90.0,37.143.0,39.139.1,26.126.0"}
P.entries["quest:266"] = {n="调查旅店",s="在夜色镇，书记员达尔塔让你带着从斯温·约根的破败农场找到的日记，前往血鸦旅店。他希望那里有人能认出日记的主人。",h="在夜色镇，书记员达尔塔让你带着从斯温·约根的破败农场找到的日记，前往血鸦旅店。他希望那里有人能认出日记的主人。",kw={"书记员达尔塔","夜色镇","暮色森林","旅店里的线索","乌鸦岭","血鸦旅店","神秘人","斯温·约根","旅店老板斯密茨"},ang={["class:Rogue"]="身为潜行者，你可以通过仔细调查，从酒馆里的闲谈中找到线索，一路追踪逃亡者，直到荒凉的废墟。",["faction:Alliance"]="身为联盟冒险者，你调查镇内的威胁，帮助守护夜色镇这座位于东部王国南部、孤立的边境城镇。"},sec={{t="血鸦旅店的线索",b="书记员达尔塔已经检查完从斯温·约根的农场找到的破旧书册。他认为，任何到访夜色镇的陌生人都会在镇上的酒馆停留。血鸦旅店在镇子的另一头，是夜色镇唯一供人聚会和住宿的地方。在那里，你或许能打听到谁曾来过，以及他们去了哪里。"},{t="疑神疑鬼的客人",b="你把日记拿给旅店老板斯密茨看，他认出了这本日记。日记的主人租了几天房间，每晚都在吧台边埋头写个不停。后来，这位客人惊恐地逃离了夜色镇，坚信有个看不见的追踪者正在追捕他。他沿着道路向西，朝乌鸦岭去了。"}},faq={{q="谁让你去旅店？",a="夜色镇负责保管镇上档案的书记员达尔塔检查日记后，让你前往血鸦旅店。他希望那里有人能认出日记的主人。",al={"谁提供这个任务","任务给予者","旅店里的线索在哪里开始"}},{q="你带着的是什么书？",a="这本破旧的日记来自暮色森林南部斯温·约根的破败农庄。人们认为，它属于那个曾在附近徘徊的神秘人。",al={"这是什么书","斯温农场的书","日记"}},{q="谁经营血鸦旅店？",a="旅店老板斯密茨经营着血鸦旅店，为冒险进入暮色森林的旅人提供酒水和客房。",al={"酒馆老板是谁","夜色镇旅店老板","斯密茨是谁"}},{q="旅店老板斯密茨透露了那位客人的什么情况？",a="日记的主人租了几天房间，每晚都在吧台边写东西。后来，他惊恐地逃离了夜色镇，坚信有个看不见的追踪者正在追捕他。",al={"斯密茨说了什么","神秘人发生了什么事","旅店老板知道什么"}},{q="那个神秘人逃到了哪里？",a="那个陌生人从夜色镇沿路向西逃去，朝乌鸦岭去了。",al={"他去了哪里","神秘人在哪里","接下来去哪里"}},{q="旅店里的线索之后是什么任务？",a="在寻找暗影任务中，旅店老板斯密茨指引你向西追寻那个陌生人的踪迹。",al={"下一个任务","旅店里的线索之后是什么","后续任务"}}},fp="18,155,27.320.0,18.289.1,25.161.0,34.148.0,34.121.0,51.172.0,34.71.0,38.95.0"}
P.entries["quest:2661"] = {n="给马林的粉末",s="加基森的斯普林克交给你一包紫色粉末，让你带给马林·诺格弗格，并提醒你转告马林，他欠她一个人情。",h="加基森的斯普林克交给你一包紫色粉末，让你带给马林·诺格弗格，并提醒你转告马林，他欠她一个人情。",kw={"加基森","马林·诺格弗格","诺格弗格药剂","斯普林克","塔纳利斯","紫色粉末"},sec={{t="城镇快递",b="在拿到紫色水生菇后，斯普林克把紫色粉末交给你，让你送到同样位于加基森的马林·诺格弗格那里。你要告诉马林，他欠她一个人情。"}},faq={{q="谁派你去找马林·诺格弗格的？",a="在你把紫色水生菇交给加基森的斯普林克之后，她会给你紫色粉末。",al={"谁给马林的快递任务","马林的快递任务发布者","斯普林克的快递"}},{q="你要递送什么物品？",a="紫色粉末，斯普林克让你带给马林·诺格弗格的东西。",al={"带给马林什么","马林的快递物品","什么粉末"}},{q="马林·诺格弗格在哪里？",a="在加基森，和斯普林克在同一个城镇。",al={"马林·诺格弗格位置","马林在哪里","寻找马林·诺格弗格"}},{q="斯普林克想要传达给马林什么消息？",a="她想让马林知道，他欠她一个人情。",al={"斯普林克的消息","斯普林克对马林说了什么","斯普林克的人情"}}},fp="18,105,15.186.0,36.98.0,29.66.0,36.62.0,48.73.0"}
P.entries["quest:2662"] = {n="诺格弗格药剂",s="马林·诺格弗格在加基森将紫色粉末混合进露水中，并让你稍后再回来找他，届时他的神奇药剂就完成了。",h="马林·诺格弗格在加基森将紫色粉末混合进露水中，并让你稍后再回来找他，届时他的神奇药剂就完成了。",kw={"露水","加基森","哥布林","马林·诺格弗格","诺格弗格药剂","粉末","斯普琳科","塔纳利斯"},sec={{t="混合药剂",b="马林拿到了露水和粉末，开始将两者混合在一起。你需要稍等片刻，然后再次与马林交谈，此时诺格弗格药剂应该已经准备好了。"},{t="马林的结论",b="当马林完成后，他会递给你一杯饮料，并声称其效果绝妙。马林吹嘘说这瓶药剂将为他带来数百万的收入，他让你站到一边以免妨碍生意，并对斯普琳科声称的人情嗤之以鼻，认为那只是个玩笑。"}},faq={{q="谁提供这个任务？",a="马林·诺格弗格，位于加基森。",al={"诺格弗格任务给予者","谁提供诺格弗格药剂","马林·诺格弗格任务"}},{q="在这一步之前发生了什么？",a="此任务紧接“给马林的货物”。在此之前是“口渴的哥布林”、“好的口味”和“斯普琳科的秘密配料”。",al={"诺格弗格药剂前置任务","马林的上一个任务","诺格弗格药剂的前置任务是什么"}},{q="马林在这里混合了什么原料？",a="马林将从斯普琳科那里得到的紫色粉末混合进了露水中。",al={"诺格弗格配方原料","马林正在混合什么","药剂里有什么"}}},fp="19,143,17.145.0,15.244.1,22.42.0,27.117.0,41.50.0"}
P.entries["quest:267"] = {n="穴居人的威胁",s="“穴居人威胁”是一项联盟任务，由洛克莫丹南门岗哨的拉格弗斯上尉发布。由于当地的铁炉堡预备队已被调往支援联盟的其他战线，剩余的守军在对抗山丘中充满敌意的穴居人部落时显得捉襟见肘。冒险者们受命去消灭这些穴居人，并带回它们的石牙，以减轻山口所面临的防守压力。",h="“穴居人威胁”是一项联盟任务，由洛克莫丹南门岗哨的拉格弗斯上尉发布。由于当地的铁炉堡预备队已被调往支援联盟的其他战线，剩余的守军在对抗山丘中充满敌意的穴居人部落时显得捉襟见肘。冒险者们受命去消灭这些穴居人，并带回它们的石...",kw={"拉格弗斯上尉","铁炉堡预备队","卡兹莫丹","洛克莫丹","麦格尼·铜须","南门","穴居人","穴居人的石牙"},ang={["faction:Alliance"]="该任务凸显了联盟在遥远地区的作战承诺如何掏空了像洛克莫丹这类地区的防卫储备。",["race:Dwarf"]="对于矮人来说，清除南门附近的穴居人是履行对卡兹莫丹的直接职责，并将获得国王麦格尼·铜须本人的赞许。"},sec={{t="日渐空虚的边境",b="守卫洛克莫丹南入口的防线如今岌岌可危。常规的矮人山地巡逻队和铁炉堡预备役军团已被派遣去增援更广阔的联盟战争前线，只留下拉格弗斯上尉和一支残缺的卫戍部队驻扎在南岗哨。由于受到不得擅离职守的严格军令限制，拉格弗斯无法对高地发动主动进攻，这使得附近的定居者和旅人极易遭受伏击。"},{t="遏制浪潮",b="盘踞在周边峭壁上的穴居人对卡兹莫丹构成了日益严重的威胁。若不加以遏制，它们的数量会迅速膨胀，进而威胁到矮人的前哨站。为了争取时间并削弱这一威胁，拉格弗斯号召流浪的冒险者直接突袭穴居人在山坡上的巢穴，并上交割下的石牙作为完成任务的实质证据。"}},faq={{q="拉格弗斯上尉是谁？",a="拉格弗斯上尉是驻扎在洛克莫丹南门岗哨的一名矮人军官。他的职责是守卫山口，防止入侵，同时还要应对驻军严重不足的窘境。",al={"拉格弗斯上尉","谁发布了穴居人威胁","拉格弗斯"}},{q="为什么南门的驻军不足？",a="铁炉堡预备队已被征召并重新部署，前往国外的更大型联盟前线作战。仅有一小支军团留守岗哨，他们受限于防守职责，无法发起反击。",al={"为什么没有卫兵","铁炉堡预备队缺席","矮人士兵在哪里"}},{q="什么是穴居人石牙？",a="穴居人有着天生石化、状如岩石的牙齿特征，这反映了它们源自地底的土灵血统。拉格弗斯上尉要求冒险者带回这些牙齿，作为它们已被击杀的无可辩驳的实质证据。",al={"穴居人的石牙","石牙","为什么需要穴居人牙齿"}},{q="穴居人在哪里？",a="这些穴居人栖息在洛克莫丹南门附近的岩石山丘、峡谷以及道路两旁的挖掘场中。",al={"哪里可以找到穴居人","洛克莫丹的穴居人位置","这个任务的穴居人在哪里"}},{q="为什么穴居人现在构成了如此大的威胁？",a="穴居人繁殖迅速，具有极强的领地侵略性，一旦军方撤离，它们就会涌入定居区。若不主动进行清理，它们将会堵塞连接洛克莫丹与周边地区的通道。",al={"为什么穴居人很危险","穴居人问题","穴居人想要什么"}},{q="完成这个任务对国王麦格尼·铜须有什么帮助？",a="国王麦格尼·铜须肩负着保卫整个卡兹莫丹安全的重任。在铁炉堡的军队远征在外时，冒险者们通过减少穴居人的数量，保护了王国内部的补给线和脆弱的边境定居点。",al={"与麦格尼·铜须的联系","麦格尼会在意吗","为什么要帮助铁炉堡"}}},fx={["5b5ee45d"]={q="拉格弗斯上尉为什么想要完成这件事？",a="铁炉堡的预备部队被部署到联盟前线后，拉格弗斯上尉便没有足够的人手保障当地安全。他的部队被牵制在南部哨塔，抵御可能发生的入侵。如果放任附近丘陵中聚集的穴居人不管，它们就可能轻易攻陷这座哨站，进而席卷洛克莫丹。",al={"拉格弗斯的动机","为何对抗穴居人","拉格弗斯上尉的目的"}},ba878bae={q="为什么穴居人会盘踞在南门附近的山丘？",a="穴居人在矮人的领地各处涌出地面，大肆侵占定居点和交通要道。周围的峭壁适合入侵，它们便在南门附近的山脊游荡，伺机攻击那些因持续兵力短缺而空虚的防线。",al={"穴居人是什么","穴居人的目标","穴居人为何在这里"}}},fp="16,241,19.279.0,17.283.0,25.170.0,38.173.0,27.184.0,29.111.0,43.196.0,58.204.0"}
P.entries["quest:268"] = {n="回复斯温",s="你带着基特斯写完的日记，返回斯温·约根在西部荒野附近的营地。自家人遇害以来，那些问题一直困扰着他，而日记中的记述或许能给出答案。",h="你带着基特斯写完的日记，返回斯温·约根在西部荒野附近的营地。自家人遇害以来，那些问题一直困扰着他，而日记中的记述或许能给出答案。",kw={"黑暗强盗","暮色森林","荒弃鬼屋","基特斯","基特斯的日记","摩本特·费尔","斯温·约根","约根农场"},ang={["class:Paladin"]="身为圣骑士，帮助斯温查明杀害他家人的幕后势力，正是在履行保护无辜、伸张正义的神圣职责。",["faction:Alliance"]="约根农场的毁灭，表明暴风城未能保护暮色森林的边境聚落，使其免遭步步逼近的暗影侵袭。"},sec={{t="懦夫的忏悔",b="斯温·约根的农场遭到袭击时，基特斯逃进了树林，留下一本尚未写完的日记。基特斯害怕面对斯温的怒火，又始终无法摆脱亲眼所见的惨状，于是躲进了暮色森林深处。你找到他时，他自愿将写完的日记交给你。他希望这份关于袭击的完整记录能让他免于亲自面对斯温。"},{t="揭开黑暗强盗的面目",b="基特斯写完的记录，将斯温一家遇害的线索串联起来。杀害他们的是寻找一件神器的黑暗强盗，而非偶然涌来的亡灵或发动袭击的野兽。斯温还记得，自己曾在荒弃鬼屋附近，看见这些戴着兜帽的身影与死灵法师摩本特·费尔秘密会面。这本日记让斯温不再沉溺于茫然的悲痛，而是将复仇的目标锁定为摩本特·费尔。"}},faq={{q="基特斯为什么如此惧怕斯温·约根？",a="基特斯逃离了斯温的农场，害怕面对这位悲痛农夫的怒火。他请你把日记交给斯温，让他读到其中的记述。",al={"基特斯为什么害怕","基特斯害怕斯温","基特斯做了什么"}},{q="基特斯写完的日记里记载了什么？",a="基特斯写完的日记完整记述了斯温农场发生的事情。斯温需要读过日记，才能明白家人究竟遭遇了什么。",al={"日记写了什么","基特斯的日记背景故事"}},{q="斯温提到的黑暗强盗是谁？",a="黑暗强盗是一群戴着兜帽、游荡在暮色森林中的神秘身影。他们搜寻强大的魔法遗物，所到之处只留下死亡与毁灭。",al={"黑暗强盗是谁","暮色森林中的骑手","黑暗强盗"}},{q="摩本特·费尔与斯温农场遭袭有什么关联？",a="摩本特·费尔是暮色森林西部一名强大的死灵法师。斯温的调查和基特斯的日记揭示了他与这次袭击的关联。",al={"摩本特·费尔的关联","为什么是摩本特·费尔","摩本特·费尔是谁"}},{q="在哪里能找到斯温·约根？",a="斯温已经离开了被毁的农场，如今住在暮色森林西北部丘陵的一处小营地，靠近通往西部荒野的边界通道。",al={"斯温在哪里","斯温·约根的位置","斯温的营地"}},{q="把日记交给斯温之后会发生什么？",a="斯温读完基特斯的记述后，会要求你在证明你的实力中证明自己的战斗能力。",al={"回复斯温之后的任务","斯温任务线的后续"}}},fp="14,156,21.321.0,25.373.1,43.139.0,38.146.1,42.137.0,58.137.1,31.125.0,43.99.1"}
P.entries["quest:269"] = {n="寻求指引",s="在暴风城，斯温·约根向主教法席恩寻求有关暮色森林的神圣指引。他送去基特斯的日记，希望主教能揭示如何破除摩本特·费尔的护盾。",h="在暴风城，斯温·约根向主教法席恩寻求有关暮色森林的神圣指引。他送去基特斯的日记，希望主教能揭示如何破除摩本特·费尔的护盾。",kw={"主教法席恩","光明大教堂","夜色镇","暮色森林","基特斯","摩本特·费尔","寻求智慧","暴风城","斯温·约根"},ang={["class:Paladin"]="作为一名圣骑士，你将被遗弃的边境地区寻求神圣援助的恳求带往光明大教堂，这考验着白银之手保护被遗忘者、净除死灵法术的职责。",["class:Priest"]="作为一名牧师，你能从主教法席恩那里得到指引，了解黑暗结界如何腐蚀肉体与灵魂。对抗暗影巫术，既需要刀剑，也需要专注的神圣净化。",["faction:Alliance"]="作为一名联盟旅人，这段旅程让你看清了暴风城戒备森严的大理石殿堂与暮色森林遭遗弃的城镇之间的鸿沟。那些城镇得不到驻军支援。"},sec={{t="阴影中的恳求",b="暮色森林饱受古老诅咒和饥渴亡灵的折磨。暴风城的王廷已变得冷漠，斯温·约根也明白，寻常力量无法穿透摩本特·费尔的结界。他心灰意冷，栖身于边境附近的一处营地，请你将基特斯整理好的日记带到教会。向北的道路通往光明大教堂。"},{t="大教堂中的指引",b="在暴风城的光明大教堂，主教法席恩倾听暮色森林的恳求。基特斯的记述证实了摩本特·费尔的力量：邪恶的巫术保护着这名死灵法师，使他免受寻常攻击的伤害。仅凭勇气无法突破这些结界。要击败他，就必须找到一件经过附魔的神圣器具。"}},faq={{q="斯温为何派你去找主教法席恩，而不是安度因国王？",a="斯温信任主教法席恩，他是一位仁慈而博学的圣光信徒，深谙邪恶魔法。政局陷入僵局，暴风城的贵族和军队大多已任由夜色镇及周边地区自生自灭，因此斯温不指望能通过官方途径获得援兵。",al={"为何找法席恩","为何不找暴风城贵族","暴风城无视暮色森林"}},{q="基特斯的日记是什么，主教为何需要它？",a="基特斯记录了斯温的农场遇袭前后发生的事情。斯温将这份完整的记述送给主教法席恩，以便主教在你准备面对摩本特·费尔时给予指引。",al={"基特斯的日记是什么","为何需要基特斯的日记","基特斯的日记"}},{q="摩本特·费尔是谁？",a="摩本特·费尔是一名强大的死灵法师，曾现身于暮色森林的荒弃鬼屋。他统率着成群的骷髅爪牙，并以强大的结界护身，抵挡普通武器的攻击。",al={"摩本特·费尔是谁","摩本特·费尔的故事"}},{q="主教法席恩在哪里？",a="主教法席恩居住在光明大教堂，那是暴风城教堂广场区内宏伟的人类大教堂。",al={"法席恩在哪里","法席恩的位置","主教法席恩地图"}},{q="主教法席恩读完日记后会发生什么？",a="主教法席恩解释说，寻常攻击无法伤害摩本特·费尔。他指引你寻找一件能驱散这名死灵法师结界的圣物，由此开始了对被诅咒的舰队的搜寻。",al={"寻求指引之后做什么","寻求指引后续","寻求指引之后"}},{q="斯温·约根住在暮色森林的哪里？",a="斯温·约根栖身于暮色森林西北部的一处小营地，靠近以河流为界的边境。营地位于艾尔文森林以南、闹鬼的乌鸦岭墓地以西。",al={"斯温在哪里","斯温·约根的位置","斯温的营地"}}},fx={["12ed4f38"]={q="为什么斯温·约根需要你去送日记？",a="斯温独自在暮色森林坚守，满心复仇的怒火与悲痛，在恐怖之物环伺的营地中求生。暴风城已经放弃了夜色镇及其周边地区，任由它们自生自灭，没有留下任何皇家卫兵帮助他。斯温不能离开，让暮色森林无人守护，也无力独自破解摩本特·费尔的黑暗巫术。你已经在对抗当地威胁时证明了自己的实力，如今你是他唯一可靠的希望，能将基特斯揭露的真相带给拥有智慧和神圣力量、能够提供帮助的人。",al={"斯温为何选我","为何派玩家去找主教法席恩","斯温为何不去暴风城"}}},fp="14,177,23.345.0,24.281.1,65.291.0,57.173.0,19.184.0,33.123.0,53.193.1,40.161.0"}
P.entries["quest:27"] = {n="必修的课程",s="在雷霆崖，图拉克·符文图腾派遣年轻的牛头人德鲁伊北上，研习水中之道。他们的旅途通往月光林地的永夜港，塞纳里奥议会在那里指导他们修行。",h="在雷霆崖，图拉克·符文图腾派遣年轻的牛头人德鲁伊北上，研习水中之道。他们的旅途通往月光林地的永夜港，塞纳里奥议会在那里指导他们修行。",kw={"水栖形态","塞纳里奥议会","德迪利特·星焰","长者高地","必修的课程","月光林地","永夜港","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="身为德鲁伊，你不再局限于陆地上的生存之道，开始学习在水下呼吸和行动。",["faction:Horde"]="身为部落的一员，你尊重月光林地神圣的中立地位，在塞纳留斯共同庇护的林冠下与暗夜精灵并肩而行。",["race:Tauren"]="身为牛头人，你与雷霆崖的德鲁伊一道，加入月光林地更广大的塞纳里奥同道。"},sec={{t="驾驭深水",b="你已经学会了熊形态，掌握了它的力量。现在，图拉克·符文图腾开始教导学生适应不同的环境。艾泽拉斯的水域危机四伏，让只能在陆地上活动的旅人难以应对。因此，他派遣献身自然的德鲁伊北上，学习水栖形态。"},{t="通往永夜港之路",b="图拉克·符文图腾派你走出莫高雷，学习如何改变形态以适应水中环境。你前往海加尔山下的庇护之地月光林地，抵达永夜港。在那里，塞纳里奥议会的暗夜精灵导师迎接牛头人学生。他们将阵营纷争搁置一旁，守护共同传承的塞纳留斯教诲。"},{t="两重试炼",b="德迪利特·星焰在永夜港等候，你的修行将在那里开始。这位暗夜精灵长者说，唯有通过考验，才能掌握水中之道。两场试炼正等待着你。一场考验你在水下的耐力与沉着。另一场则要求你从灵魂深处领悟水栖形态的本质。"}},faq={{q="谁会给予必修的课程任务？",a="图拉克·符文图腾在雷霆崖的长者高地给予这个任务，他在那里训练德鲁伊。当你积累了足够的经验，他就会派你接受进阶训练。",al={"必修的课程起始任务人","必修的课程领取地点","图拉克·符文图腾任务"}},{q="完成这个任务需要去哪里？",a="你需要前往月光林地的永夜港，与塞纳里奥议会的德迪利特·星焰交谈。",al={"必修的课程交付地点","德迪利特·星焰位置","永夜港位置"}},{q="这条任务线最终会让人学会什么技能？",a="这条道路最终通向水栖形态。它让你能在水下迅速游动，并能无限期地在水下呼吸。",al={"获得什么形态","水栖形态任务","做这个任务的原因"}},{q="为什么牛头人德鲁伊要向暗夜精灵学习？",a="塞纳里奥议会是一个信奉塞纳留斯、致力于保护自然的中立团体。在月光林地，暗夜精灵与牛头人放下部落和联盟之间的紧张关系，共同研习神圣的技艺。",al={"前往月光林地的原因","找德迪利特·星焰的原因","塞纳里奥议会牛头人"}},{q="德迪利特·星焰提到的是什么试炼？",a="德迪利特·星焰告诉你，有两场试炼。一场考验你在水下承受压力时能否保持沉着。另一场考验你领悟水栖形态本质的精神意志。",al={"两场试炼是什么","德迪利特的考验","水栖试炼"}},{q="这个阶段的德鲁伊如何抵达月光林地？",a="德鲁伊可以使用源自精神纽带的法术传送: 月光林地，从艾泽拉斯的任何地方直接前往永夜港。",al={"如何前往月光林地","传送到月光林地","前往永夜港"}}},fp="17,180,21.253.0,22.320.0,15.288.0,38.155.0,39.95.0,43.113.0,52.206.0,45.168.0,47.132.0"}
P.entries["quest:270"] = {n="被诅咒的舰队",s="“注定的舰队”是一段向北的旅程，由暴风城光明大教堂的主教法席恩派遣。为了寻找击败强大的死灵法师摩尔本·菲尔的方法，英雄们被派往卡兹莫丹，前往湿地海岸边那些沉没的残骸。",h="“注定的舰队”是一段向北的旅程，由暴风城光明大教堂的主教法席恩派遣。为了寻找击败强大的死灵法师摩尔本·菲尔的方法，英雄们被派往卡兹莫丹，前往湿地海岸边那些沉没的残骸。",kw={"主教法席恩","注定的舰队","戈罗林·钢眉","库尔提拉斯","圣光锻铁","米奈希尔港","摩尔本·菲尔","第三舰队","湿地"},ang={["class:Paladin"]="寻找圣洁金属来打击邪恶的死灵法师，体现了圣骑士使用圣光祝圣武器净化黑暗的使命。",["class:Priest"]="在主教法席恩的指引下行动，将牧师们直接与教会关于受祝福遗物和祝圣矿石的古老知识联系了起来。",["faction:Alliance"]="这个任务突显了联盟的后勤跨度，将南方孤立的人类城镇与矮人港口和古老的航海路线连接起来。",["profession:Blacksmithing"]="铁匠们会欣赏圣光锻铁这种罕见的传说，这是一种注入了信仰的金属，需要大师级的工艺才能塑造。"},sec={{t="神圣真理之武器",b="事实证明，普通钢铁无法对摩尔本·菲尔在荒弃鬼屋隐居处所施加的黑暗结界产生效果。为了穿透这种死灵防御，主教法席恩指示冒险者们必须打造一把与圣光相连的武器。关键材料是圣光锻铁，这是一种稀有且神圣的金属，它的打击蕴含神圣真理，能够切开那些弹开普通刀剑的魔法防护。"},{t="第三舰队的残骸",b="不幸的是，圣光锻铁在被围困的暮色森林中并没有现成的储备。法席恩回忆起多年前，库尔提拉斯岛国的第三舰队在铁炉堡以北湿地那险恶的海岸线上遭遇了灾难。在那些沉没的帆船中，有一艘载着珍贵的矿石。冒险者们必须一路前往米奈希尔港，咨询戈罗林·钢眉，他是一位熟知沼泽及其沉船的矮人联络人。"}},faq={{q="为什么我必须一路前往湿地？",a="摩尔本·菲尔的黑暗魔法保护他免受普通攻击。主教法席恩知道，只有用神圣的圣光锻铁打造的武器才能剥离那些结界，而唯一已知的矿藏就位于米奈希尔港外库尔提拉斯第三舰队的失事船只中。",al={"为什么要去湿地","为什么去米奈希尔港","湿地之行"}},{q="摩尔本·菲尔是谁？",a="摩尔本·菲尔是一位居住在暮色森林荒弃鬼屋的邪恶死灵法师。他的法术助长了困扰该地区的亡灵起义，因此击败他对于夜色镇的生存至关重要。",al={"摩尔本·菲尔身份","死灵法师是谁","暮色森林死灵法师"}},{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位驻扎在湿地米奈希尔港的矮人。他是圣光教会的盟友，对沼泽的海岸线、沉船和打捞行动有着深刻的了解。",al={"钢眉是谁","钢眉的作用"}},{q="什么是圣光锻铁？",a="圣光锻铁是一种被牧师们珍视的、经过特殊祝圣的金属。用它打造的武器在打击时带有神圣的力量，能够驱散或穿透普通钢铁无法撼动的黑暗护盾和死灵诅咒。",al={"圣光锻铁的作用","圣光金属","圣化钢铁"}},{q="库尔提拉斯第三舰队发生了什么事？",a="多年前，库尔提拉斯的第三舰队在湿地崎岖沼泽的海岸线上遇难并沉没。它们的船体残骸至今仍淹没在岸边，里面留有遗失的货物，并由溺毙的水手和水生掠食者守护着。",al={"第三舰队的命运","湿地的库尔提拉斯船只","船只如何沉没"}},{q="这个任务一开始就需要战斗吗？",a="这一阶段完全是一个跑腿任务。它需要从暮色森林出发，经过暴风城王国和卡兹莫丹，长途跋涉前往米奈希尔港与戈罗林·钢眉接头。",al={"有战斗吗","只是跑腿任务"}}},fp="16,186,22.267.0,28.330.0,52.242.0,19.194.0,24.176.0,24.197.0,46.191.0,48.142.0"}
P.entries["quest:272"] = {n="海狮试炼",s="海狮试炼是德鲁伊在月光林地进行的一项神圣仪式，旨在踏上掌握水栖形态的旅程。受训者需要找回两块散落的坠饰碎片，它们分别象征着海狮的敏捷与耐力，然后将它们在雷姆洛斯神殿合而为一。通过锻造出完整的海狮坠饰，德鲁伊证明了自己与水元素的和谐统一，并为引导该生物的灵魂做好了准备。",h="海狮试炼是德鲁伊在月光林地进行的一项神圣仪式，旨在踏上掌握水栖形态的旅程。受训者需要找回两块散落的坠饰碎片，它们分别象征着海狮的敏捷与耐力，然后将它们在雷姆洛斯神殿合而为一。通过锻造出完整的海狮坠饰，德鲁伊证明了自己与水...",kw={"水栖形态","德迪利特·星焰","水兽敏捷坠饰","水兽耐力坠饰","月光林地","永夜港","海狮坠饰","雷姆洛斯神殿","海狮试炼"},ang={["class:Druid"]="这项试炼是德鲁伊独有的成年仪式，在他们被允许与水元素灵魂交流并采用海狮形态之前，考验他们的精神成熟度和平衡性。",["race:NightElf"]="作为月光林地和塞纳里奥议会的长期守护者，暗夜精灵德鲁伊崇敬德迪利特·星焰的教诲以及雷姆洛斯神殿周围的神圣土地。",["race:Tauren"]="对于新加入塞纳里奥议会的牛头人德鲁伊来说，在月光林地进行试炼可以加强他们与自然灵魂的交流，并加深他们与暗夜精灵导师之间的联系。"},sec={{t="水栖形态之路",b="为了获得在艾泽拉斯深水中航行的能力，德鲁伊受训者必须在月光林地的神圣林地中进行协调测试。海狮试炼是这些重要仪式中的第二项，此前他们已经进行了精神训练方面的准备。在永夜港的德迪利特·星焰的指导下，这项试炼挑战德鲁伊去理解两种截然不同的特质——优雅的速度与坚韧的耐力——是如何达到平衡的。如果不掌握海狮天性的这两个维度，受训者就无法驾驭其形态，也无法抵御深海的危险。"},{t="敏捷与耐力",b="试炼的物质与精神核心在于从两块断裂的碎片中重新组装海狮坠饰。其中一块坠饰引导着海狮形态的敏捷，反映了其在湍急水流中优雅穿梭的能力。另一块坠饰则汲取了该生物无穷的耐力，代表了在冰冷的水中长时间潜行而不动摇所需的坚韧。受训者必须向月光林地的居民寻求线索，以发现这些散落在世界各地的圣物，这既展示了他们的足智多谋，也体现了他们在神圣庇护所内寻求指导的意愿。"},{t="雷姆洛斯神殿",b="一旦两件圣物都到手，受训者必须将碎片带到雷姆洛斯神殿附近，将它们重新结合成一枚单一的护身符。守护者的圣所提供了将敏捷与耐力的不同力量和谐融合所需的宁静而强大的能量。将修复后的海狮坠饰呈现给永夜港的德迪利特·星焰，即可完成试炼。手持这一信物，德鲁伊表明了他们已准备好拥抱海狮形态，并最终唤醒他们的水栖形态。"}},faq={{q="什么是海狮试炼？",a="海狮试炼是月光林地一项关键的德鲁伊任务，考验受训者对水生生物的理解。它要求德鲁伊找回代表敏捷和耐力的两块坠饰碎片，在雷姆洛斯神殿将它们组装起来，并将完成的护身符交给德迪利特·星焰。通过这项试炼是解锁德鲁伊水栖形态的必要里程碑。",al={"海狮试炼任务","什么是海狮试炼","海狮试炼"}},{q="谁发布海狮试炼任务？",a="月光林地雷姆洛斯神殿的守望者塔加里会发布这项试炼。受训者向当地居民寻求指导，在神殿附近将两块碎片结合，然后将制成的海狮坠饰带给位于永夜港的暗夜精灵德鲁伊德迪利特·星焰。",al={"谁给予海狮试炼","如何开始海狮试炼","海狮试炼任务发布者"}},{q="这两块坠饰碎片分别代表什么？",a="这两块坠饰碎片代表了界定海狮形态的双重特质：敏捷和耐力。一块体现了在深水中平稳滑行所需的优雅与迅捷，另一块则体现了在漫长的水下旅程中生存所需的耐力与韧性。德鲁伊必须同等尊重并体现这两种特质，才能掌握他们的变形艺术。",al={"什么是坠饰碎片","坠饰碎片的含义","敏捷与耐力碎片"}},{q="坠饰碎片位于何处？",a="要发现水兽敏捷坠饰和水兽耐力坠饰隐藏在哪里，受训者必须与月光林地的居民交谈。当地的德鲁伊和村民会提供关于每块碎片遗失或隐藏的遥远水域的关键线索。",al={"如何找到坠饰碎片","去哪里找坠饰碎片","海狮坠饰碎片位置"}},{q="在哪里组装海狮坠饰？",a="这两块碎片不能随处组合；它们必须在月光林地雷姆洛斯神殿的附近结合。雷姆洛斯守护者神殿的神圣光环提供了将敏捷与耐力的力量结合成单一功能性护身符所需的精神共鸣。",al={"如何组合坠饰碎片","在哪里融合坠饰碎片","雷姆洛斯神殿坠饰在哪里"}},{q="为什么德鲁伊必须平衡敏捷和耐力？",a="根据德迪利特·星焰的说法，在水下，敏捷和耐力单凭任何一种都无法有效发挥作用。没有耐力的快速移动会导致迅速精疲力竭，而没有迅捷的耐力则会使游泳者在强大的水流面前束手无策。对于任何试图完全体现海狮灵魂的德鲁伊来说，调和这两种特质至关重要。",al={"为什么需要敏捷与耐力","德鲁伊海狮特质","海狮试炼的意义"}},{q="完成试炼能获得什么？",a="完成海狮试炼可获得修复后的海狮坠饰，并完成获得水栖形态所需的主要试炼。通过证明对敏捷与耐力课程的掌握，受训者建立了变形为能够在水下呼吸和快速游动的生物所需的精神基础。",al={"完成海狮试炼能得到什么","海狮试炼奖励","这能给予水栖形态吗"}}},fp="21,210,24.398.0,21.373.0,21.372.0,34.228.0,42.224.0,41.281.0,37.254.0,50.144.0,46.274.0,39.259.0"}
P.entries["quest:273"] = {n="挖掘场的补给品",s="吉恩·角盔让你从塞尔萨玛出发，追赶一辆缓缓驶向铁环挖掘场、运送爆破火药的货车。三名矮人运输者沿洛克湖岸向南行进。",h="吉恩·角盔让你从塞尔萨玛出发，追赶一辆缓缓驶向铁环挖掘场、运送爆破火药的货车。三名矮人运输者沿洛克湖岸向南行进。",kw={"爆破火药","胡达尔","铁环","吉恩·角盔","洛克莫丹","米兰","挖掘场的补给品","赛恩","塞尔萨玛"},ang={["profession:Mining"]="你知道在崎岖的地面上运送易爆火药有多危险。这批货物对南方的挖掘者至关重要。",["race:Dwarf"]="身为铜须矮人，你在洛克莫丹危险的道路上保护爆破火药的运输，帮助维持铁环挖掘工作的补给。"},sec={{t="湖岸边的沉重货物",b="洛克莫丹南部的铁环挖掘场需要爆破火药来炸开坚硬的岩石。火药先运到塞尔萨玛，再由吉恩·角盔安排胡达尔、米兰和赛恩将三桶易爆的火药运往南方。沉重的货物拖慢了驮畜队伍沿湖边道路行进的速度，让你有时间追上他们，在途中提供帮助。"},{t="暗影中的背叛",b="胡达尔的货车在南边的道路上遭到了伏击。黑铁矮人发动袭击，意图破坏铜须探险队的考古工作。赛恩曾与胡达尔共事近一年，却因支持黑铁而参与策划了这场伏击。"}},faq={{q="任务挖掘场的补给品由谁发起？",a="你把爆破火药交给吉恩·角盔后，他便让你从塞尔萨玛出发。他请你沿洛克湖边的道路向南走，追上补给队。",al={"谁提供挖掘场的补给品","挖掘场的补给品任务发起者","在哪里接挖掘场的补给品"}},{q="在哪里可以找到胡达尔和货车？",a="胡达尔和货车位于塞尔萨玛以南，在沿洛克湖西岸和南岸通往铁环挖掘场的道路上。",al={"寻找胡达尔","胡达尔位置","洛克莫丹货车在哪里"}},{q="为什么要给铁环运送爆破火药？",a="勘察员基恩萨·铁环和他的队伍在南部的挖掘场发掘古代遗物。他们需要爆破火药来炸碎厚重的岩石，炸穿地下岩层。",al={"铁环为什么需要火药","铁环爆破火药","为什么给挖掘场运送爆破火药"}},{q="谁伏击了胡达尔的货车？",a="杰恩预计胡达尔的队伍会走塞尔萨玛以南沿洛克湖延伸的那条惯常道路。等你找到胡达尔，就会得知是谁袭击了货车。",al={"谁袭击了货车","洛克莫丹货车伏击","谁袭击了胡达尔"}},{q="赛恩在袭击中扮演了什么角色？",a="赛恩与胡达尔和米兰同行，运送沉重的爆破火药桶。等你追上队伍，就会得知他在袭击中扮演的角色。",al={"赛恩是谁","赛恩的背叛","赛恩做了什么"}},{q="找到胡达尔之后，下一个任务是什么？",a="与胡达尔交谈后，这一段旅程便告完成。他对这批货物遭遇的讲述，会指引你接下来的行动。",al={"挖掘场的补给品后续任务","胡达尔之后的任务"}}},fx={["72005fbc"]={q="为什么吉恩·角盔派你去追赶胡达尔？",a="吉恩·角盔发现，你送来爆破火药时，胡达尔和他的队伍刚刚带着沉重的货车，动身前往铁环挖掘场。车上装满了桶，十分沉重，因此吉恩知道，他们沿着洛克湖南侧道路行进的速度会很慢。他派你赶上他们，协助运送这批至关重要的物资。",al={"吉恩·角盔的动机","为何追赶胡达尔","吉恩为何派人前往"}}},fp="26,172,29.342.0,24.247.1,48.162.0,40.143.0,42.169.0,28.140.1,39.141.1,43.119.1"}
P.entries["quest:274"] = {n="水坝危机",s="在巨石水坝发现可疑粉末后，位于丹莫德的阿什兰·暗石确认该物质为不稳定的瑟银。如果接触到水，它会引发灾难性的破坏，这种粉末对该地区及附近的矮人领地构成了直接威胁。阿什兰·暗石调制出了一种拆弹胶质，并派人传信给主工程师辛德维尔七世，以便化解这场灾难。",h="在巨石水坝发现可疑粉末后，位于丹莫德的阿什兰·暗石确认该物质为不稳定的瑟银。如果接触到水，它会引发灾难性的破坏，这种粉末对该地区及附近的矮人领地构成了直接威胁。阿什兰·暗石调制出了一种拆弹胶质，并派人传信给主工程师辛德维...",kw={"阿什兰·暗石","爆炸粉末","主工程师辛德维尔七世","黑暗威胁逼近","拆弹胶质","铁炉堡","瑟银","湿地"},ang={["faction:Alliance"]="联盟的防御者必须迅速行动，协助主工程师辛德维尔七世并保护低地，以免敌方破坏者摧毁战略基础设施。",["profession:Engineering"]="工程学专家们会认出瑟银是一种极具威力的挥发性化合物，需要小心处理并采取精确的化学对策，以避免产生巨大的冲击波。",["race:Dwarf"]="对于卡兹莫丹的矮人来说，想到有破坏者在通往丹莫罗和铁炉堡的门口使用这种极不稳定的瑟银，简直是一种生存威胁。"},sec={{t="危险的发现",b="通过检查从巨石水坝带回的样本，阿什兰·暗石立刻辨认出那是瑟银特有的银色结晶，并闻到了它独特的气味。虽然在干燥条件下处于惰性状态，但瑟银一旦受潮就会发生剧烈反应——对于一座拦截着洛克莫丹水域的巨石水坝来说，这简直是噩梦。阿什兰警告说，这种化合物一旦发生失控爆炸，足以将铁炉堡从山中震飞。"},{t="与时间赛跑",b="为了对抗这种不稳定的爆炸物，阿什兰·暗石调制出了一种专门的拆弹胶质。中和这种反应需要一种特定的化学混合物：将这种胶质与潜伏者的毒液、研磨后的莫格罗什水晶以及鳄鱼的眼泪混合。时间紧迫，必须立刻警告主工程师辛德维尔七世，以免湿气引发灾难。"}},faq={{q="在水坝发现了什么种类的爆炸物？",a="阿什兰·暗石确认这种神秘物质是瑟银粉，其特征是明显的银色结晶和刺鼻的化学气味。",al={"这是什么粉末","这种粉末是什么","瑟银粉"}},{q="为什么瑟银在这里如此危险？",a="瑟银在保持干燥时相对无害，但一旦接触到水就会引发灾难性的爆炸。考虑到巨石水坝拦截着洛克莫丹的水域，这使其成为极度危险的地方。",al={"为什么瑟银很危险","什么会导致瑟银爆炸"}},{q="阿什兰·暗石是谁？",a="阿什兰·暗石是一位居住在湿地的联盟矮人专家，拥有分析神秘粉末和制作中和剂所需的工程学与化学专业知识。",al={"阿什兰是谁","阿什兰·暗石的身份"}},{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世负责该地区的工程和防御事务，他在洛克莫丹的巨石水坝工作，负责维护和保卫矮人的基础设施。",al={"辛德维尔是谁","主工程师辛德维尔"}},{q="如何中和瑟银？",a="中和这种化学反应需要将阿什兰的拆弹胶质与三种稀有的当地材料混合：潜伏者的毒液、一颗研磨后的莫格罗什水晶和鳄鱼的眼泪。",al={"如何拆除瑟银","瑟银拆除配方","拆弹胶质配方"}},{q="对铁炉堡有什么危险？",a="阿什兰警告说，如果在周围的山脉系统中发生失控的爆炸，可能会导致灾难性的地震，足以将铁炉堡从山中震飞。",al={"铁炉堡有危险吗","铁炉堡受到什么威胁"}}},fp="19,182,20.262.0,16.280.1,44.120.0,35.189.0,25.175.0,37.161.0,37.142.0,32.148.0"}
P.entries["quest:2741"] = {n="超级测蛋器",s="克格尔·曲藤的最新发明是一台令人印象深刻的机器，当你靠近它的控制面板时，它疯狂地喷着火花。角鹰兽蛋会被放进里面。",h="克格尔·曲藤的最新发明是一台令人印象深刻的机器，当你靠近它的控制面板时，它疯狂地喷着火花。角鹰兽蛋会被放进里面。",kw={"克格尔·曲藤","蛋蛋机","测蛋仪","菲拉斯","角鹰兽蛋","塔纳利斯"},sec={{t="克格尔·曲藤的机器",b="克格尔·曲藤的最新发明看起来令人印象深刻。当你走到它的控制面板前时，它会疯狂地喷着火花。它是用来处理角鹰兽蛋的，这种蛋可以在菲拉斯南部的群山中，也就是伊斯迪尔废墟附近找到。"},{t="机器的作用",b="把一颗角鹰兽蛋放进去，机器就会发出一连串的蜂鸣声和奇怪的机械噪音。它的测蛋仪会称量并测量这颗蛋，然后迅速地将其打包。出来的东西是一个蛋箱，里面装着各种各样的蛋。"}},faq={{q="谁制造了超级蛋蛋机？",a="克格尔·曲藤，这是他的最新发明。",al={"谁制造了蛋蛋机","蛋蛋机的制造者","克格尔·曲藤的发明"}},{q="机器需要什么才能运行？",a="一颗角鹰兽蛋，你需要把它放进机器里。",al={"我应该给蛋蛋机什么","蛋蛋机所需的物品","角鹰兽蛋机器"}},{q="在哪里可以找到角鹰兽蛋？",a="在菲拉斯南部的群山中，也就是伊斯迪尔废墟附近。",al={"角鹰兽蛋位置","去哪里找角鹰兽蛋","菲拉斯的蛋在哪里"}}},fp="21,114,30.175.0,21.210.1,32.70.0,38.49.0,34.92.0"}
P.entries["quest:2742"] = {n="林吉被困住了！",s="林吉，一个巨魔，丢失了一把斧头并被困在奎尔丹尼小屋中，他恳求别人帮助他逃脱。林吉知道其他人可能不喜欢他这个种族，但他承诺会给予回报，并提到了隐藏在眺望台悬崖上的一个秘密。",h="林吉，一个巨魔，丢失了一把斧头并被困在奎尔丹尼小屋中，他恳求别人帮助他逃脱。林吉知道其他人可能不喜欢他这个种族，但他承诺会给予回报，并提到了隐藏在眺望台悬崖上的一个秘密。",kw={"俘虏","护送","辛特兰","眺望台悬崖","奎尔丹尼","林吉","石板"},sec={{t="逃脱的请求",b="林吉被囚禁在奎尔丹尼小屋中，惊恐万分。斧头不见了，林吉恳求路人帮助他逃离这里。林吉知道很多人不喜欢他这一族，但他愿意为帮助他的善良灵魂提供回报，并声称眺望台悬崖上隐藏着一个秘密。"},{t="逃脱的终点",b="等待着的是一块刻满奇怪符号的巨魔石板。上面的文字无法辨认。"}},faq={{q="谁是林吉？",a="林吉是一个巨魔，他丢失了一把斧头，并被俘虏在辛特兰的奎尔丹尼小屋中。林吉说话时喜欢用第三人称指代自己，并恳求他人帮助他逃脱。",al={"林吉","奎尔丹尼的巨魔是谁","谁是林吉"}},{q="林吉被关在哪里？",a="林吉被关押在辛特兰的奎尔丹尼小屋中。",al={"林吉在哪里","林吉的位置","奎尔丹尼牢笼"}},{q="林吉用什么作为帮助他的回报？",a="林吉为那些帮助他的人准备了回报，并声称眺望台悬崖上隐藏着一个秘密。",al={"林吉的秘密是什么","林吉的奖励","眺望台悬崖有什么"}}},fp="18,182,17.257.0,24.81.1,14.176.0,29.62.0,32.93.0"}
P.entries["quest:2745"] = {n="潜入城堡",s="在暴风要塞，埃林·提亚斯派你去见他的特工同伴泰里恩。泰里恩已在皇家花园监视葛瑞格·莱斯科瓦勋爵数周。",h="在暴风要塞，埃林·提亚斯派你去见他的特工同伴泰里恩。泰里恩已在皇家花园监视葛瑞格·莱斯科瓦勋爵数周。",kw={"奶酪店","迪菲亚潜行者","埃林·提亚斯","潜入城堡","莱斯科瓦","暴风要塞","泰里恩"},ang={["class:Rogue"]="身为潜行者，你协助两名经验丰富的秘密特工，潜入人类贵族的权力中心。他们的行动展现了保护暴风城免受宫廷内部威胁所需的隐秘而致命的技艺。",["faction:Alliance"]="瓦里安国王失踪后，王国已承受不起城堡最高议事厅中的背叛。身为联盟的一员，你协助铲除阴谋者，维护王国的稳定。",["race:Gnome"]="身为侏儒，你见证泰里恩在暴风要塞内进行长期的秘密监视。他的行动表明，侏儒的聪明才智既能用于机械，也能用于谍报。"},sec={{t="法律之外的行动",b="在贸易区的奶酪店里，埃林·提亚斯看出迪菲亚潜行者的威胁已渗入王国的统治阶层。葛瑞格·莱斯科瓦勋爵根基深厚，受到重重庇护，寻常法律无法揭露或惩治这样的贵族。于是，埃林·提亚斯提出了一条险路：在暴风要塞内，以法律之外的手段伸张正义，彻底斩断这场阴谋。"},{t="灌木丛中的眼睛",b="埃林·提亚斯在宫廷里安插了一名特工：泰里恩，一个机敏而善于隐蔽的侏儒。数周来，泰里恩一直监视着城堡的庭院和皇家花园。他追踪莱斯科瓦的行踪，留意谁进入他的房间，以及这个叛徒何时与迪菲亚潜行者的秘密联络人会面。你需要找到泰里恩，同时避免引起皇家卫兵的怀疑。"},{t="宫廷中的叛国阴谋",b="莱斯科瓦勋爵与迪菲亚潜行者刺客沉默之刃马尔松的勾结，表明瓦里安·乌瑞恩国王不在期间，暴风城宫廷已腐败至深。宫廷贵族在王国内部密谋，境外的匪徒则从西部荒野和赤脊山向边境步步紧逼。对莱斯科瓦下手，是为了赶在王国崩溃之前铲除腐败。"}},faq={{q="埃林·提亚斯为什么要在法律之外处理这件事？",a="莱斯科瓦勋爵在贵族中拥有巨大的影响力和财富。没有确凿的证据，指控一位地位显赫的勋爵可能引发政治灾难，导致证据被压下，揭发者遭到处决。埃林·提亚斯认为，秘密采取直接行动，是阻止这一威胁的唯一可靠办法。",al={"为何在法律之外行动","埃林·提亚斯法外正义","为何私自执法"}},{q="泰里恩藏在哪里？",a="泰里恩藏在暴风要塞的皇家花园里，穿过正门后，就在庭院左侧。他躲在灌木丛中监视莱斯科瓦勋爵的住处，不让守卫察觉。",al={"泰里恩在哪里","寻找泰里恩","泰里恩位置"}},{q="泰里恩是谁？",a="泰里恩是一名秘密特工，也是埃林·提亚斯信任的伙伴。数周以来，他一直监视暴风要塞，追踪葛瑞格·莱斯科瓦勋爵，查清他与迪菲亚潜行者之间的秘密联系。",al={"泰里恩是谁","泰里恩侏儒","埃林·提亚斯的朋友"}},{q="莱斯科瓦勋爵是谁？",a="葛瑞格·莱斯科瓦勋爵是暴风城一位显赫的贵族，暗中与迪菲亚潜行者合作，充当他们在宫廷中的内应。他帮助他们从内部破坏王国。",al={"莱斯科瓦勋爵","莱斯科瓦是谁","莱斯科瓦迪菲亚潜行者"}},{q="马尔松是谁？",a="马尔松，人称沉默之刃，是迪菲亚潜行者的一名精锐刺客。他直接与莱斯科瓦勋爵合作，为迪菲亚潜行者协调袭击和暗杀行动。",al={"马尔松","沉默之刃马尔松","沉默之刃"}},{q="泰里恩为什么担心自己的名声？",a="泰里恩担心你会在秘密监视期间暴露他的身份。他还抱怨，全副武装的冒险者在城堡守卫眼皮底下，徘徊在他身旁的皇家灌木丛中，既惹人怀疑，也有失体面。",al={"泰里恩藏在灌木丛","灌木丛中的名声"}}},fx={ae2213ef={q="你在暴风城城堡要去对付谁？",a="埃林·提亚斯派你去处理葛瑞格·莱斯科瓦大人和他的同伙马尔松。莱斯科瓦是个贵族，在暴风城的暴风要塞内部活动，涉嫌叛国；马尔松则代表着城墙之外危险的阴谋集团。提亚斯和他的联络人泰里恩希望在两人的密谋威胁王国之前将他们一并铲除。",al={"我们要对付谁","潜入城堡的目标是谁","莱斯科瓦和马尔松是谁"}},["7d59c2b3"]={q="为什么埃林·提亚斯派你去，而不是动用暴风城卫兵？",a="莱斯科瓦勋爵是暴风要塞里的高级贵族，没有确凿证据，官方指控在政治上根本行不通。城卫军听命于宫廷，而贵族在宫廷中势力强大；若通知官方渠道，很可能会惊动莱斯科瓦，或让此事陷入繁琐程序。提亚斯依靠一位独立的冒险者潜入其中、与泰里恩会合，并果断地伸张正义，不让阴谋者察觉。",al={"为什么派我去","为什么不告诉卫兵","为什么不找暴风城卫兵"}}},fp="23,152,24.337.0,21.349.0,20.354.1,56.312.0,23.203.0,14.185.0,21.183.0,14.162.1,43.223.0"}
P.entries["quest:2746"] = {n="必备物品",s="为了将他的机械间谍潜入暴风要塞并窃听莱斯科瓦勋爵，秘密行动人员泰里恩需要一些非常特定的伪装材料。你必须提供精良的丝绸和清脆的果园苹果，以组装一个古怪的伪装身份，从而在不被察觉的情况下绕过皇家卫兵。",h="为了将他的机械间谍潜入暴风要塞并窃听莱斯科瓦勋爵，秘密行动人员泰里恩需要一些非常特定的伪装材料。你必须提供精良的丝绸和清脆的果园苹果，以组装一个古怪的伪装身份，从而在不被察觉的情况下绕过皇家卫兵。",kw={"克拉拉","埃林·提亚斯","潜入城堡","莱斯科瓦勋爵","丝绸布匹","间谍机器人","暴风要塞","伏击","泰里恩"},ang={["class:Rogue"]="与泰里恩和埃林·提亚斯这样的行动人员并肩工作，突显了军情七处非传统的监视手段，并展示了国内情报部门是如何在贵族眼皮底下运作的。",["faction:Alliance"]="保护年轻的安度因国王和伯瓦尔·弗塔根公爵，需要铲除那些在暴风要塞内与法外之徒勾结的腐败贵族。",["profession:Tailoring"]="泰里恩的临时计划需要真正的丝绸布匹，这提醒裁缝们，精美的纺织品对于秘密阴谋来说，就像对于正式礼服一样至关重要。"},sec={{t="紧迫的日程",b="奶酪商人埃林·提亚斯传来的消息加快了针对葛瑞格·莱斯科瓦勋爵的行动。由于怀疑这位贵族在暴风要塞内的阴谋对王国构成了直接威胁，提亚斯坚持要求提前行动时间表。躲藏在暴风要塞花园里的泰里恩同意推进这一行动，但他坚持认为收集适当的渗透物资需要精心的准备。"},{t="伪装的艺术",b="泰里恩的计划依赖于一种非传统的资产：Spybot，一个小型的机械装置，旨在溜过警惕的城堡卫兵，到达Keep内的莱斯科瓦身边。泰里恩没有依赖简单的潜行，而是构建了一个奇异的女性伪装来转移怀疑。为了完成这种伪装，他派遣行动人员前往城墙外Clara的果园寻找大小合适的苹果，同时要求用丝绸布匹来为这个傀儡剪裁服装。"},{t="揭露叛国罪",b="泰里恩透露，他最初对莱斯科瓦勋爵的监视与迪菲亚潜行者根本没有联系，而是因为有可疑的线索将这位贵族与暮光之锤邪教联系在了一起。发现莱斯科瓦正在积极与迪菲亚潜行者的阴谋家勾结，使得他继续留在皇家法庭已变得站不住脚，将一项常规的监视任务变成了王国心脏地带的一次高风险诱捕行动。"}},faq={{q="泰里恩为什么需要苹果和丝绸布匹？",a="泰里恩正在为他的机械侦察兵间谍机器人制作一种奇特的女性伪装，以便在不引起警报的情况下溜过暴风要塞的皇家卫兵。丝绸被剪裁成临时服装，而来自克拉拉农场的苹果则提供了完成这种幻象所需的确切形状。",al={"为什么需要苹果","苹果的用途","泰里恩的伪装材料","间谍机器人伪装"}},{q="泰里恩为谁工作？",a="泰里恩与贸易区的奶酪商人埃林·提亚斯协同工作，后者在暴风城经营着自己的朋友网络；提亚斯承认，这次行动只是间接地帮了马迪亚斯·肖尔和军情七处一个忙。",al={"泰里恩向谁汇报","泰里恩的效忠对象","埃林·提亚斯与泰里恩"}},{q="我在哪里可以找到克拉拉的苹果？",a="克拉拉的农场位于艾尔文森林北部，就在暴风城的城门外。新鲜的苹果可以直接在她的简朴果园周围采集。",al={"克拉拉的农场位置","克拉拉的苹果在哪里","暴风城的新鲜苹果"}},{q="泰里恩最初怀疑莱斯科瓦勋爵在做什么？",a="泰里恩和提亚斯最初追踪的线索表明，莱斯科瓦勋爵与邪恶的暮光之锤邪教有联系。发现他与迪菲亚潜行者的合作证明，他的叛国罪行要深重得多，并且对王权构成了迫在眉睫的威胁。",al={"莱斯科瓦与暮光之锤","为什么要调查莱斯科瓦","泰里恩与莱斯科瓦的历史"}},{q="交付这些物品后的下一步是什么？",a="一旦间谍机器人装备齐全并被送入要塞，你将接到任务，在后续任务“伏击!”中直接对抗并消灭这些阴谋家。",al={"接下来发生什么","完成“必备物品”之后","“必备物品”之后的后续任务"}},{q="为什么要使用机械间谍机器人而不是亲自潜入？",a="暴风要塞由皇家哨兵严密把守，他们会仔细盘查每一个进入王座大厅和私人庭院的人。间谍机器人伪装成一位女祭司，可以走过卫兵并直接与莱斯科瓦交谈，把他引诱到花园里去见马尔松，而那里是任何已知特工都无法接近的地方。",al={"为什么要使用间谍机器人","为什么不亲自潜入","暴风要塞的安保"}}},fx={["7ec9a91a"]={q="为什么泰里恩想扳倒莱斯科瓦公爵？",a="泰里恩和他的同僚埃林·提亚斯怀疑莱斯科瓦公爵与颠覆势力有关，已经追踪了他数周。他们最初调查的是他是否与暮光之锤的邪教徒有牵连，却发现莱斯科瓦正在与迪菲亚潜行者密谋，这让他立刻成为暴风城面临的严重威胁。泰里恩打算在他的叛国行径撕裂这座城市之前，揭露并铲除他。",al={"为何阻止莱斯科瓦","泰里恩的动机","为何调查莱斯科瓦"}},["73f45f0b"]={q="为什么泰里恩需要外来者帮忙，而不找城里的卫兵？",a="莱斯科瓦公爵是身处暴风要塞的贵族，没有确凿证据，就无法公开指控他，也无法让卫兵直接介入。暴风城的当权者不能仅凭猜测，就对一位地位显赫的贵族采取行动。泰里恩奉提亚斯大师之命在暗中行事，需要一名独立行动的人，愿意秘密收集物资，并最终亲自应对那场危险的秘密交锋。",al={"为何不找城里的卫兵","泰里恩为何需要我","为何依靠冒险者"}}},fp="25,175,21.275.0,23.313.0,18.324.1,43.180.0,26.195.0,31.126.0,58.208.1,51.132.1,62.252.0"}
P.entries["quest:2747"] = {n="特别的蛋",s="克格尔·曲藤很少见到来自菲拉斯、品相特别好的蛋。这种蛋是所有蛋中最稀有的。",h="克格尔·曲藤很少见到来自菲拉斯、品相特别好的蛋。这种蛋是所有蛋中最稀有的。",kw={"克格尔·曲藤","特别的蛋","菲拉斯","超级蛋蛋机","塔纳利斯"},sec={{t="来自菲拉斯的珍品",b="克格尔·曲藤说，来自菲拉斯的蛋中，品相特别好的寥寥无几，而这种蛋是所有蛋中最稀有的。克格尔要找的就是这样的蛋。"}},faq={{q="谁在寻找特别的蛋？",a="克格尔·曲藤，他是超级测蛋器的发明者。",al={"特别的蛋起始任务人","特别的蛋任务给予者","克格尔·曲藤的蛋"}},{q="这些特别的蛋来自哪里？",a="它们是从菲拉斯取回来的，但送到时品相特别好的寥寥无几。",al={"特别的蛋位置","哪里能找到特别的蛋","来自菲拉斯的蛋"}},{q="这项请求的前置任务是什么？",a="它的前置任务是超级测蛋器。",al={"特别的蛋前置任务","特别的蛋任务链","特别的蛋上一个任务"}}},fp="20,70,21.134.0,40.81.0,44.85.0,31.43.0"}
P.entries["quest:2748"] = {n="优良的蛋",s="克格尔·曲藤提到，优良的蛋有机会在不受戈杜尼食人魔邪恶咒语影响的情况下孵化。",h="克格尔·曲藤提到，优良的蛋有机会在不受戈杜尼食人魔邪恶咒语影响的情况下孵化。",kw={"克格尔·曲藤","达纳苏斯","优良的蛋","戈杜尼","食人魔咒语","超级蛋蛋机","塔纳利斯"},sec={{t="何以称为优良",b="克格尔·曲藤说，优良的蛋在理想条件下，很有可能在不受戈杜尼食人魔邪恶吟唱影响的情况下孵化。"},{t="克格尔·曲藤接下来要做的事",b="克格尔·曲藤收下了蛋，打算将它送往达纳苏斯，希望它能很快在那里孵化。"}},faq={{q="什么样的蛋才算优良的蛋？",a="在理想条件下，它能在不受戈杜尼食人魔咒语带来的邪恶影响的情况下孵化。",al={"什么是优良的蛋","优良的蛋背景故事","为何称为优良的蛋"}},{q="这一步之前是什么？",a="这一步接在超级测蛋器之后。",al={"优良的蛋前置任务","优良的蛋上一个任务"}}},fp="10,98,18.136.0,21.89.1,40.96.0,27.44.0"}
P.entries["quest:2749"] = {n="普通的蛋",s="克格尔·曲藤照料普通的角鹰兽蛋，这些蛋能否孵化就像抛硬币一样：大约只有一半能孵化。克格尔悉心照料它们，盼着好运降临。",h="克格尔·曲藤照料普通的角鹰兽蛋，这些蛋能否孵化就像抛硬币一样：大约只有一半能孵化。克格尔悉心照料它们，盼着好运降临。",kw={"克格尔·曲藤","菲拉斯","角鹰兽","普通的蛋","塔纳利斯","超级蛋蛋机"},sec={{t="一半的机会",b="一枚普通的角鹰兽蛋只有大约一半的几率能够孵化。克格尔·曲藤尽心照料每一枚蛋，运气好的话，蛋就会孵化。"}},faq={{q="克格尔·曲藤是谁？",a="克格尔·曲藤是超级测蛋器的发明者，负责处理在菲拉斯发现的角鹰兽蛋。",al={"克格尔是谁","克格尔·曲藤"}},{q="普通的角鹰兽蛋会怎么样？",a="克格尔照料着它，盼着好运降临，因为这类蛋大约只有一半能孵化。",al={"克格尔如何处理蛋","蛋的孵化几率"}},{q="这些蛋来自哪里？",a="来自菲拉斯。",al={"哪里能找到蛋","普通的蛋位置"}},{q="这一步之前是什么？",a="这一步接在超级测蛋器之后。",al={"前置任务","上一个任务是什么"}}},fp="15,79,13.136.0,25.93.0,44.96.0,30.27.0,27.50.0"}
P.entries["quest:275"] = {n="大地上的脓疱",s="“土地上的脓疱”是绿色守卫者雷希耶尔在湿地东部山脊提供的一个联盟任务。这位孤独的沼泽兽守望者察觉到沼泽中正在酝酿一种非自然的疾病，于是委托旅行者清除潜伏在水道中的染病沼泽爬行者。平息这些蹒跚的植物怪物是雷希耶尔为了消除沼泽日益严重的“热病”所做的努力。",h="“土地上的脓疱”是绿色守卫者雷希耶尔在湿地东部山脊提供的一个联盟任务。这位孤独的沼泽兽守望者察觉到沼泽中正在酝酿一种非自然的疾病，于是委托旅行者清除潜伏在水道中的染病沼泽爬行者。平息这些蹒跚的植物怪物是雷希耶尔为了消除沼...",kw={"土地上的脓疱","沼泽爬行者","绿色守卫者","沼泽","雷希耶尔","湿地沼泽","湿地"},ang={["class:Druid"]="雷希耶尔的任务直接反映了德鲁伊治愈自然世界的职责，清除不安的元素疫病，使大地回归平衡。",["class:Shaman"]="沼泽爬行者代表了大地与水元素的扭曲表现，摧毁它们是一种平息不和谐元素之灵的行为。",["race:NightElf"]="在东部王国发现一头与暴风城结盟的孤独沼泽兽守望者，这表明即使是土地本身的灵魂也会寻求帮助，以呵护受创的土地。"},sec={{t="溃烂的沼泽",b="绿色守卫者雷希耶尔在沼泽中的树林里守护着湿地那片潮湿的广袤土地。这里的沼泽从来都不安宁，但最近一种非自然的疾病开始在泥沼中蔓延。雷希耶尔认为这种折磨是大地本身产生的一种日益严重的“热病”，导致野外的自然力量扭曲成了无意识的、蹒跚而行的怪物。"},{t="净化沼泽",b="这种腐烂的主要症状就是沼泽爬行者的出现——它们是沿着水道蹒跚而行的沼泽植被构成的腐烂元素聚合物。雷希耶尔将其描述为大地上肿胀的病态脓疱。由于它们被折磨的存在只会加剧沼泽的混乱，这位绿色守卫者要求过往的盟军将它们消灭，以便它们那纠结的残骸能重新无害地沉入泥土之中。"}},faq={{q="绿色守卫者雷希耶尔是谁？",a="绿色守卫者雷希耶尔是一头居住在湿地东部绿色守卫者之林的沼泽兽。它致力于照料沼泽地的自然平衡，寻求平复这片土地的苦难，并抑制腐化的元素生长。",al={"谁是雷希耶尔","绿色守卫者雷希耶尔背景故事","谁发布了土地上的脓疱任务"}},{q="什么是沼泽爬行者？",a="沼泽爬行者是徘徊在湿地水道中的敌对植物与沼泽元素生物。它们表现为由藤蔓、泥土和腐烂的沼泽植物构成的笨重、蹒跚的聚合体。",al={"沼泽爬行者","什么是沼泽爬行者","湿地爬行者"}},{q="为什么雷希耶尔想要消灭沼泽爬行者？",a="雷希耶尔将沼泽爬行者视为沼泽日益严重的疾病所产生的发热、病态的体现。它相信消灭它们可以让它们的形态消散并重新沉入大地，从而平复这片焦躁不安的土地。",al={"为什么要消灭沼泽爬行者","为什么会有土地上的脓疱任务"}},{q="是什么导致了湿地的溃烂？",a="雷希耶尔承认它并不完全了解是什么导致了湿地的溃烂在不断加剧。它只是感受到了这片土地悲伤的痛苦，并通过在元素骚动涌现的任何地方安抚它们来治疗这些症状。",al={"为什么湿地会生病","湿地疾病的原因"}},{q="沼泽爬行者在湿地的什么地方？",a="沼泽爬行者游荡在湿地纵横交错的潮湿水道、泥泞岸边和中央河道中，尤其是在绿色守卫者之林以西的深层沼泽附近。",al={"沼泽爬行者位置","去哪里找沼泽爬行者"}},{q="这个任务与雷希耶尔的其他任务有关联吗？",a="是的。“土地上的脓疱”延续了雷希耶尔对苔藓皮豺狼人在“火之禁忌”任务中焚烧湿地树木的担忧，这是它为保护沼泽平衡所做努力的一部分。",al={"绿色守卫者任务线","雷希耶尔任务"}}},fp="20,184,19.253.0,17.279.0,31.211.0,22.169.0,49.184.0,42.149.0,45.143.0,51.148.0"}
P.entries["quest:2750"] = {n="坏掉的蛋",s="克格尔·曲藤谈到了那些无法挽救、永远不会孵化的蛋。",h="克格尔·曲藤谈到了那些无法挽救、永远不会孵化的蛋。",kw={"坏掉的蛋","克格尔·曲藤","菲拉斯","超级蛋蛋机","塔纳利斯"},sec={{t="无法挽救的蛋",b="有些角鹰兽的蛋无法挽救，而坏掉的蛋永远不会孵化。这类蛋由克格尔·曲藤处理。"},{t="蛋的去向",b="克格尔收下这枚蛋，以便妥善处理。克格尔说，并非每枚蛋都能挽救，你不该灰心，而应再找一枚来自菲拉斯的蛋试试。"}},faq={{q="谁会收下坏掉的蛋？",a="克格尔·曲藤。",al={"坏掉的蛋交给谁","克格尔·曲藤的蛋","谁收坏掉的蛋"}},{q="这枚蛋还能挽救吗？",a="不能。坏掉的蛋无法挽救，也永远不会孵化。",al={"坏掉的蛋能孵化吗","坏掉的蛋会孵化吗","挽救坏掉的蛋"}},{q="之前是什么任务？",a="它的前一个任务是超级测蛋器。",al={"前一个任务","前置条件","坏掉的蛋前置条件"}}},fp="9,69,20.92.0,18.136.1,24.38.0,21.51.0,22.33.0"}
P.entries["quest:2751"] = {n="野人装甲",s="在奥格瑞玛，奥罗克·沃姆什正在寻找能传承家族锻造技艺的人。他没有子嗣，因此要求一位有志于锻造的铁匠先用青铜证明自己的手艺，才肯传授知识。",h="在奥格瑞玛，奥罗克·沃姆什正在寻找能传承家族锻造技艺的人。他没有子嗣，因此要求一位有志于锻造的铁匠先用青铜证明自己的手艺，才肯传授知识。",kw={"野人装甲","锻造","青铜","传承","沃姆什","奥格瑞玛","奥罗克·沃姆什"},ang={["faction:Horde"]="身为部落的一员，你认同沃姆什的信念：锻造之物应当经受战斗的考验，染上敌人的鲜血。",["profession:Blacksmithing"]="身为部落铁匠，你在从基础的青铜与铜器锻造迈向更高深的护甲制作传统的道路上，达成了一个重要里程碑。"},sec={{t="沃姆什一脉的终点",b="奥罗克·沃姆什在奥格瑞玛的铁砧前劳作，肩负着家族历史的重担。二十代以来，沃姆什一脉将矿石锻造成武器和护甲，供部落使用。奥罗克没有亲人，也无法生育，因此觉得自己辜负了家族。眼看家族技艺面临失传，他放下了对血脉的执念，寻找一位学徒来延续家族的锻造传统。"},{t="金属与利爪的考验",b="奥罗克不会向未经考验的铁匠传授秘技。他要求交来两副带花纹的青铜护腕、两把青铜巨剑和两只锋利的野兽爪子，以此证明基本的锻造本领。在他看来，锻造绝非供人享乐的闲技：护甲与钢刃染上敌人的鲜血，才是这门技艺至高的荣耀。满足他的要求，或许能让这位老铁匠相信，沃姆什的传承可以通过学徒延续下去，并赢得进一步学习锻造技艺的机会。"}},faq={{q="奥罗克·沃姆什是谁？",a="奥罗克·沃姆什是奥格瑞玛的一位锻造大师，也是沃姆什一脉的第二十代传人。他没有亲人和子嗣，因此希望找一位家族之外的人，让氏族的锻造知识得以延续。",al={"奥罗克·沃姆什","奥罗克是谁","沃姆什铁匠"}},{q="奥罗克为什么需要另找传人？",a="奥罗克已无在世的亲人，也无法生育。他需要一位学徒来继承工坊的图纸与技艺，否则二十代积累的锻造知识就会随他一同消逝。",al={"为何收徒","奥罗克的继承人","沃姆什传承为何濒临断绝"}},{q="需要哪些物品才能向奥罗克证明自己的本领？",a="奥罗克要求交来两副带花纹的青铜护腕、两把青铜巨剑，以及从凶猛的掠食野兽身上取得的两只锋利爪子。",al={"野人装甲需要什么","野人装甲所需物品","野人装甲交任务"}},{q="完成野人装甲后是什么任务？",a="证明自己掌握了青铜锻造的基本技艺后，奥罗克会通过铁肩铠继续训练你，让你学习更厚重的铁器锻造与复杂的板甲制作。",al={"后续任务","野人装甲后续任务链","接下来是什么"}}},fp="20,185,25.390.0,25.413.0,19.183.0,42.191.0,53.124.0,49.167.0"}
P.entries["quest:2753"] = {n="踩在脚下",s="在奥格瑞玛的荣誉谷，奥罗克·沃姆什让铁匠接受一项高阶锻造试炼。锻造绿铁护甲既考验他们的耐力，也教会他们制作厚重的铁靴，而能否学到沃姆什血脉传承的秘技，就取决于这场试炼。",h="在奥格瑞玛的荣誉谷，奥罗克·沃姆什让铁匠接受一项高阶锻造试炼。锻造绿铁护甲既考验他们的耐力，也教会他们制作厚重的铁靴，而能否学到沃姆什血脉传承的秘技，就取决于这场试炼。",kw={"护甲锻造","锻造","戈罗克","绿铁","奥格瑞玛","奥罗克·沃姆什","踩在脚下","荣誉谷"},ang={["faction:Horde"]="奥罗克的课程传授坚固耐用的铁甲图样，专为部落各条战线上惯用的残酷战斗方式而设计。",["profession:Blacksmithing"]="对于部落的护甲锻造师来说，这项试炼是重要的一步。要获得独有的靴子设计图，就需要大量熔炼铁锭并准备绿色染料。"},sec={{t="沃姆什的试炼",b="奥罗克·沃姆什在奥格瑞玛通过艰苦的体能试炼训练护甲锻造师。在他看来，金属加工不只是加热矿石、锤打成形；这项工作既是对祖辈氏族的致敬，也考验着铁匠的耐力。这是他这一系列试炼中的第三项，反复打造经过淬炼的绿铁护甲，旨在锻炼体魄与自律。"},{t="戈洛克酋长的传承",b="将所需绿铁装备交给奥罗克的铁匠，会得到这位粗豪的护甲锻造师难得的赞许。他将经受住这番劳作的工匠，比作自己的祖父——沃姆什的戈洛克酋长。作为护甲的回报，奥罗克会传授祖传的坚固铁靴图样，让部落勇士能将敌人碾碎在脚下。"}},faq={{q="谁提供踩在脚下任务？",a="这项试炼由奥罗克·沃姆什提供，他是奥格瑞玛荣誉谷的一名兽人护甲锻造师。",al={"任务提供者","谁提供踩在脚下","奥罗克·沃姆什位置"}},{q="奥罗克·沃姆什的这项试炼需要什么？",a="奥罗克需要四顶绿铁头盔、四副绿铁护腕和两条绿铁护腿。这些装备考验并证明铁匠对绿铁锻造技艺的掌握。",al={"踩在脚下交任务","所需物品","所需材料"}},{q="沃姆什训练任务线背后有什么故事？",a="奥罗克·沃姆什让年轻铁匠承受严酷的体力劳作，以延续祖先的尚武传统。他相信，艰苦的护甲锻造能练就力量，打造出经得起残酷战火考验的装备。",al={"奥罗克要求打造护甲的原因","沃姆什氏族故事"}},{q="沃姆什的戈罗克酋长是谁？",a="沃姆什的戈罗克酋长是奥罗克·沃姆什的祖父。奥罗克推崇祖父的武勇，并将那些经受住繁重铁器锻造试炼的铁匠比作这位酋长。",al={"戈罗克酋长","奥罗克的祖父"}},{q="踩在脚下的前置任务是什么？",a="在奥罗克的一系列护甲锻造挑战中，铁肩铠是这项试炼的前置任务。",al={"前置任务","任务线的上一个任务"}},{q="完成踩在脚下之后的下一个任务是什么？",a="这项试炼之后，奥罗克·沃姆什会提供疯狂之角。接下来还剩两课，整个系列以沃姆什的喜悦收尾。",al={"下一个任务","踩在脚下的后续任务"}}},fp="19,226,19.322.0,22.324.0,41.80.0,45.164.0,49.208.0,29.173.0,40.88.0,60.116.0"}
P.entries["quest:2755"] = {n="沃姆什的喜悦",s="得到一位冒险者的大力相助后，奥罗克·沃姆什在奥格瑞玛分享了家族的传统。这位老练的铁匠把眼泪推说成烟灰作祟，随后跳起沃姆什欢乐之舞，传承这份不同寻常的家族遗产。",h="得到一位冒险者的大力相助后，奥罗克·沃姆什在奥格瑞玛分享了家族的传统。这位老练的铁匠把眼泪推说成烟灰作祟，随后跳起沃姆什欢乐之舞，传承这份不同寻常的家族遗产。",kw={"铁匠","欢乐之舞","沃姆什的喜悦","奥格瑞玛","奥罗克·沃姆什","烟灰入眼","荣誉谷"},ang={["faction:Horde"]="在奥格瑞玛的荣誉谷，钢铁碰撞声中，尚武的自豪与奥罗克喜悦的泪水和充满活力的舞蹈交织在一起。",["profession:Blacksmithing"]="身为铁匠，奥罗克那支饱含深情的家族舞蹈，让人得以一窥这位老工匠在熔炉之外幽默而温情的生活。"},sec={{t="沾染烟灰的泪水",b="在奥格瑞玛灼热的熔炉旁，奥罗克·沃姆什以沉重的锤击闻名，而非眼泪。这位魁梧的铁匠得到了你的鼎力相助，你的善意让他感动不已。他固执地说是眼里进了烟灰，不肯承认自己在流泪。"},{t="沃姆什的传统",b="临别前，奥罗克说，他还有一个沃姆什家族的秘密必须分享。他为学徒跳起了动作有力、十分耗费体力的沃姆什欢乐之舞，然后教导学徒如何挥出铁拳。"}},faq={{q="奥罗克·沃姆什是谁？",a="奥罗克·沃姆什是奥格瑞玛荣誉谷的一名兽人铁匠。他对家族的手艺和血脉深感自豪，在打铁之余，也传承着充满活力的传统。",al={"奥罗克是谁","奥罗克·沃姆什的背景故事","铁匠奥罗克"}},{q="奥罗克为什么哭了？",a="奥罗克说是熔炉的烟灰进了眼睛，但其实是你的帮助深深打动了他。他找到了一位值得分享家族传统的人。",al={"奥罗克为什么哭","奥罗克伤心吗","烟灰入眼"}},{q="什么是沃姆什欢乐之舞？",a="沃姆什欢乐之舞是奥罗克家族代代相传的一套舞蹈，动作有力。这支舞让他疲惫不堪，而他已经很久没有练习了。",al={"沃姆什舞蹈","欢乐之舞","这是什么舞蹈"}},{q="这个任务发生在哪里？",a="任务发生在奥格瑞玛，地点就在荣誉谷的锻造熔炉附近，奥罗克·沃姆什在那里锻打金属。",al={"任务地点","沃姆什的喜悦在哪里","奥格瑞玛熔炉"}},{q="奥罗克会教你什么？",a="奥罗克会教你沃姆什欢乐之舞，并承诺传授铁拳的知识，让铁匠与冒险者结下纽带。",al={"沃姆什奖励","能学到什么","铁拳"}},{q="联盟玩家能参与这个任务吗？",a="不能。奥罗克·沃姆什效忠部落，住在奥格瑞玛坚固的城墙之内，因此只有部落冒险者能在那里见到他。",al={"联盟沃姆什的喜悦","是否仅限部落"}}},fp="13,195,19.219.0,19.207.0,19.170.0,20.154.0,31.163.0,33.91.0,26.135.0,47.132.0"}
P.entries["quest:276"] = {n="践踏之爪",s="“践踏之爪”是一项由绿色守卫者雷希耶尔在湿地的绿色守卫者树林发放的联盟任务。沼泽兽守护者被奥加兹之门附近激增的苔藓沼泽豺狼人数量所困扰，他委托冒险者在这些豺狼人的营火和践踏之爪摧毁沼泽之前，将它们清理干净。",h="“践踏之爪”是一项由绿色守卫者雷希耶尔在湿地的绿色守卫者树林发放的联盟任务。沼泽兽守护者被奥加兹之门附近激增的苔藓沼泽豺狼人数量所困扰，他委托冒险者在这些豺狼人的营火和践踏之爪摧毁沼泽之前，将它们清理干净。",kw={"奥加兹","豺狼人","绿色守卫者","杂种狗头人","苔藓沼泽","雷希耶尔","践踏之爪","湿地"},ang={["class:Druid"]="雷希耶尔的使命直接反映了塞纳里奥议会维持生态平衡的宗旨，即剔除不自然的种群高峰，以确保沼泽不会崩溃。",["race:Dwarf"]="随着豺狼人在奥加兹之门外直接肆虐，清理它们不仅保护了沼泽，还确保了连接铁炉堡和米奈希尔港的重要道路的安全。",["race:NightElf"]="暗夜精灵与荒野的自然之灵有着祖传的联系，这使得雷希耶尔提出的治愈沼泽的请求成为一项令人熟悉且倍感荣幸的职责。"},sec={{t="膨胀的沼泽威胁",b="多年来，苔藓沼泽豺狼人一直栖息在湿地，并没有彻底破坏其自然秩序。然而最近，它们的族群数量却向南爆发式增长，直逼丹奥加兹山口。它们沉重的靴子和爪印践踏了稀有的沼泽植物，粗糙的伐木行为剥去了维持营地火堆所需的关键树林。如果任其发展，这些不断壮大的族群将威胁到脆弱的沼泽生态系统，使其退化。"},{t="绿色守卫者的审判",b="绿色守卫者雷希耶尔以平衡而非文明的视角审视着这片沼泽。对于绿色守卫者来说，问题不在于豺狼人的存在，而在于它们失控的种群数量超出了湿地的承载能力。通过将苔藓沼泽豺狼人和杂种狗头人驱赶回可控的数量，冒险者有助于保护湿地，并赢得这位古老荒野守护者勉强的认可。"}},faq={{q="绿色守卫者雷希耶尔是谁？",a="雷希耶尔是一头居住在铁炉堡边境与阿拉希之间湿地道路上的沼泽兽。它致力于保护沼泽，监控着这片土地的健康状况，并委托旅行者控制破坏性的种群数量。",al={"雷希耶尔背景故事","谁发放践踏之爪","绿色守卫者湿地"}},{q="为什么苔藓沼泽豺狼人现在成了问题？",a="虽然苔藓沼泽部族曾经与沼泽共存且未造成长期损害，但它们最近的人口激增导致了大量的森林砍伐以获取木柴，以及对脆弱沼泽植物的大规模践踏。",al={"为什么要在湿地击杀豺狼人","苔藓沼泽豺狼人威胁"}},{q="豺狼人在哪里造成了这种破坏？",a="苔藓沼泽豺狼人和杂种狗头人在湿地南部大量聚集，尤其是在矮人的丹奥加兹山口附近。",al={"苔藓沼泽豺狼人在哪里","践踏之爪位置"}},{q="清理豺狼人之后会发生什么？",a="一旦族群数量减少，雷希耶尔会深入调查它们异常活动和燃料消耗的根源，并派遣冒险者去完成后续任务“禁火”。",al={"践踏之爪后续任务","践踏之爪后续"}},{q="为什么雷希耶尔提到它的信仰受到了考验？",a="雷希耶尔告诉你，它对你们种族的信仰在过去曾受到考验，它对凡人及其快速扩张持谨慎态度。帮助它保护荒野沼泽证明了凡人冒险者可以成为自然的管家，而不是掠夺者。",al={"雷希耶尔对话","过去的信仰考验"}}},fp="13,193,21.318.0,26.286.0,31.233.0,42.194.0,41.125.0,36.135.1,49.215.0"}
P.entries["quest:2766"] = {n="寻找OOX-22/FE！",s="你发现了一个奇怪的蛋形金属装置。里面传来一个声音，自称是奥格索普·奥布诺提斯，说他的自动导航机器人坠毁了。他请你把信标带到机器人那里，它就在深痕谷附近的一个洞穴里。",h="你发现了一个奇怪的蛋形金属装置。里面传来一个声音，自称是奥格索普·奥布诺提斯，说他的自动导航机器人坠毁了。他请你把信标带到机器人那里，它就在深痕谷附近的一个洞穴里。",kw={"求救信标","深痕谷","菲拉斯","自动导航机器人","机械小鸡","奥格索普·奥布诺提斯","22型机械小鸡"},sec={{t="蛋中的声音",b="你拨弄了一下旋钮，金属蛋随即弹开，展开成一个侏儒机械装置，里面传来一个夹杂着杂音的声音。奥格索普·奥布诺提斯说，自动导航机器人坠毁了，并承诺只要你找回它，就会付给你报酬。你需要把信标带到机器人那里，而奥格索普已经计算出了它的位置：深痕谷附近的一个洞穴。"},{t="洞中之物",b="你在洞穴里发现了一堆残骸，看起来像一只机械小鸡。奥格索普的声音确认，这就是他的自动导航机器人，并说它必须先重新启动，才能飞往藏宝海湾接受修理。你把信标放进去，机器人便嗡嗡作响地启动了，随后奥格索普的声音从机器人身上传了出来。"}},faq={{q="是谁在通过求救信标说话？",a="奥格索普·奥布诺提斯。他的自动导航机器人坠毁了，他请你把信标带到机器人那里。",al={"谁制作了信标","谁在说话","奥格索普是谁"}},{q="信标指引你去哪里？",a="奥格索普已经计算出了机器人的坐标，它就在菲拉斯深痕谷旁的一个洞穴里。",al={"机器人在哪里","自动导航机器人位置","信标送到哪里"}},{q="信标是什么？",a="一个奇怪的蛋形金属装置。你拨弄一下旋钮，它就会展开成一个侏儒机械装置，里面还会传出一个声音。",al={"蛋是什么","菲拉斯22号机械小鸡是什么","求救信标"}},{q="这一步之后是什么？",a="后续任务是拯救机械小鸡22号！。",al={"下一个任务","寻找失踪的机械小鸡的后续任务","洞穴之后"}}},fp="15,156,18.282.0,19.270.1,44.120.0,38.111.0,19.124.0,27.26.0"}
P.entries["quest:2767"] = {n="拯救OOX-22/FE！",s="在深痕谷发现归航机器人OOX-22/FE之后，你再次听到了那个侏儒从机器人里传出的噼啪声。这个机器人需要被护送到被遗忘的海岸码头，之后奥格索普·奥布诺提斯想在藏宝海湾与你谈谈。",h="在深痕谷发现归航机器人OOX-22/FE之后，你再次听到了那个侏儒从机器人里传出的噼啪声。这个机器人需要被护送到被遗忘的海岸码头，之后奥格索普·奥布诺提斯想在藏宝海湾与你谈谈。",kw={"藏宝海湾","深痕谷","菲拉斯","被遗忘的海岸","归航机器人","奥格索普·奥布诺提斯","22型机械小鸡","机器鸡"},sec={{t="一个安全的起飞地点",b="那个侏儒的声音说，OOX-22/FE需要一个开阔且安全的地方，以便开始漫长的起飞过程。机器人内置了隐形装置，但奥格索普·奥布诺提斯需要时间让它重新工作。奥格索普建议使用被遗忘的海岸码头，那里足够长，可以完成所有启动工作，因此需要将机器人从它所在的位置护送到那里。"},{t="事后，前往藏宝海湾",b="一旦机器人安全到达码头，奥格索普·奥布诺提斯希望你去藏宝海湾找他谈谈。"}},faq={{q="机械小鸡22号需要去哪里？",a="被遗忘的海岸码头。它需要从你发现它的深痕谷被护送到那里。",al={"我该把这只鸡带到哪里","菲拉斯22号机械小鸡的目的地","菲拉斯护送小鸡路线"}},{q="奥格索普·奥布诺提斯是谁？",a="一位发明大师，他的归航机器人系列包括机械小鸡22号。奥格索普通过机器人进行交流，你可以在藏宝海湾找到他。",al={"是谁制造了机器鸡","奥格索普·奥布诺提斯是谁","小鸡发明者"}},{q="为什么机器人需要到达码头？",a="漫长的起飞过程需要一个开阔、安全的地方，奥格索普说码头足够长，可以完成启动工作。机器人的内置隐形功能需要时间才能重新工作。",al={"为什么要护送22号机械小鸡","为什么要走去码头"}},{q="事后我该去哪里报告？",a="一旦机器人安全到达码头，就去藏宝海湾找奥格索普·奥布诺提斯谈话。",al={"奥格索普在哪里","交任务地点","之后我该和谁谈话"}}},fp="17,166,24.363.0,21.102.0,32.116.0,28.146.0,42.192.0,29.83.0"}
P.entries["quest:277"] = {n="火焰管制",s="“火的禁忌”是绿色守卫者雷希耶尔在湿地泥泞道路上布置的一项任务。这只沼泽兽深受当地森林痛苦的折磨，因此派遣旅行者去剥夺苔皮豺狼人手中的粗制打火石，这些豺狼人利用它们来点燃并焚烧活木。通过让豺狼人无法取火，雷希耶尔希望保护沼泽中那些古老的枝干免遭吞噬。",h="“火的禁忌”是绿色守卫者雷希耶尔在湿地泥泞道路上布置的一项任务。这只沼泽兽深受当地森林痛苦的折磨，因此派遣旅行者去剥夺苔皮豺狼人手中的粗制打火石，这些豺狼人利用它们来点燃并焚烧活木。通过让豺狼人无法取火，雷希耶尔希望保护...",kw={"粗制打火石","火的禁忌","豺狼人","绿色守卫者","活木","苔皮部族","雷希耶尔","湿地"},ang={["class:Druid"]="作为荒野的守护者，德鲁伊与雷希耶尔有着同样的对树木的敬畏之心，也理解活木被豺狼人的火坑折磨时那种非自然痛苦。",["faction:Alliance"]="苔皮豺狼人威胁着经过湿地的旅行者；帮助当地的灵魂有助于确保连接丹莫罗和阿拉希的贸易路线安全。",["race:NightElf"]="暗夜精灵可能会在雷希耶尔这只感同身受湿地苦难的沼泽兽身上，认出一位活木的同道守护者。"},sec={{t="绿色守卫者的痛苦",b="绿色守卫者雷希耶尔守护着湿地的荒野，与沼泽的树木保持着深厚的精神羁绊。虽然腐烂与新生的自然循环是沼泽的一部分，但这种蓄意的伐木行为深深刺痛了雷希耶尔的灵魂。对于一个活着的沼泽之灵来说，听到活生生的枝干被砍倒并投入炉火中发出的呻吟，是雷希耶尔无法再默默承受的折磨。"},{t="扑灭苔皮豺狼人的火种",b="苔皮部落为了取暖和争夺领地，在湿地横行霸道，他们砍伐的是青翠的活树，而不是收集枯木。为了在不陷入持久消耗战的情况下遏制他们的扩张，雷希耶尔将目标对准了他们破坏的核心工具：那些强壮的豺狼人所使用的粗制打火石。通过剥夺部落的生火工具，雷希耶尔使他们无法再焚烧砍下的木材。雷希耶尔会亲自粉碎收集到的每一块石头，并将粉末撒入海中，确保这些火星永远不会再次点燃森林。"}},faq={{q="谁是绿色守卫者雷希耶尔？",a="绿色守卫者雷希耶尔是一只居住在湿地的沼泽兽。雷希耶尔与当地树木和植物的生命力紧密相连，寻求保护受伤的沼泽免受苔皮豺狼人的蹂躏。",al={"谁是雷希耶尔","绿色守卫者雷希耶尔背景故事","谁发布火的禁忌"}},{q="为什么雷希耶尔想要粗制打火石而不是杀死豺狼人首领？",a="雷希耶尔认为焚烧活木是不可原谅的亵渎。通过夺走打火石，雷希耶尔直接阻止了豺狼人点火烧毁湿地的树木，从而瘫痪了他们的营地，终结了对活木的破坏。",al={"为什么需要打火石","为什么要夺走打火石","粗制打火石的用途"}},{q="打火石上交后会发生什么？",a="雷希耶尔会将粗制打火石砸得粉碎，并将残渣撒入海中，这样它们就再也不能被用来敲击产生火星去对付活木了。",al={"她如何处理打火石","毁掉打火石"}},{q="哪些豺狼人携带打火石？",a="苔皮部落中更强壮的成员携带粗制打火石。较小的苔皮豺狼人和较弱的杂种由于不被信任而没有生火工具，因此也不会携带它们。",al={"谁掉落打火石","哪些豺狼人持有粗制打火石"}},{q="为什么苔皮豺狼人要砍伐树木？",a="苔皮豺狼人砍伐活树是为了供给篝火，在潮湿的沼泽中取暖，而不是依赖干燥的枯木。",al={"为什么豺狼人砍伐树木","苔皮部族伐木"}},{q="收集打火石后的下一步是什么？",a="在你剥夺了豺狼人的火种后，雷希耶尔会派你去处理困扰沼泽的另一种枯萎病，相关后续任务为“土地上的脓包”。",al={"火的禁忌后的任务","交完打火石后的下一步任务"}}},fp="10,198,23.280.0,27.389.0,31.177.0,72.191.0,51.120.0,30.149.0,41.144.0,43.162.1"}
P.entries["quest:278"] = {n="水坝危机",s="黑铁的炸药威胁着巨石水坝，主工程师辛德维尔七世需要你的帮助。他请你从洛克莫丹收集稀有试剂，以便配制混合剂，使这些炸药失效。",h="黑铁的炸药威胁着巨石水坝，主工程师辛德维尔七世需要你的帮助。他请你从洛克莫丹收集稀有试剂，以便配制混合剂，使这些炸药失效。",kw={"鳄鱼的眼泪","黑铁","辛德维尔七世","洛克莫丹","潜伏者的毒液","莫格罗什水晶","巨石水坝"},ang={["faction:Alliance"]="身为联盟的旅人，你知道水坝一旦被毁，铁炉堡与北方诸王国之间至关重要的陆上补给路线就会中断。",["profession:Engineering"]="身为工程师，你能领会辛德维尔七世的巧思：配制一种化学中和剂，在野外使不稳定的爆破炸药恢复稳定。",["race:Dwarf"]="身为卡兹莫丹的矮人，你肩负着重大职责，必须阻止黑铁破坏巨石水坝，保护祖先的土地及其宏伟的工程。"},sec={{t="不稳定的配方",b="主工程师辛德维尔七世需要三种原料来配制混合剂。森林潜伏者的毒液、洛克湖中鳄鱼的眼泪，以及莫格罗什水晶，各自都能引发不同的反应。它们混合后，能使矮人的炸药失效。"},{t="险地采集",b="这些原料分布在洛克莫丹的危险地带。森林潜伏者蜘蛛和鳄鱼威胁着旅人，而莫格罗什食人魔则在东北方的一座要塞中守卫着他们开采的水晶。想要取得水晶，就得深入营地，面对那些食人魔。"}},faq={{q="工程师辛德维尔七世为何需要这些特定的试剂？",a="主工程师辛德维尔七世需要这些试剂来配制一种化合物，用于解除黑铁炸药的威胁。潜伏者的毒液、鳄鱼的分泌物和莫格罗什水晶能引发所需的反应，使破坏者安放的炸药失效。",al={"为何需要蜘蛛毒液","为何需要鳄鱼的眼泪","解除炸药的混合剂试剂"}},{q="莫格罗什水晶来自哪里？",a="莫格罗什食人魔在洛克莫丹东北部的群山中开采并囤积这些水晶。想要取得一块水晶，就得进入他们戒备森严的领地。",al={"水晶在哪里","莫格罗什水晶位置","谁持有水晶"}},{q="威胁洛克莫丹的黑暗势力是什么？",a="潜入此地的黑铁矮人企图摧毁巨石水坝。一旦水坝被毁，洪水就会淹没下方的湿地，切断联盟的补给线，并重创整个地区。",al={"什么黑暗威胁","谁在攻击水坝","水坝危机的故事"}},{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世是一位矮人工程师，负责监督巨石水坝的运作，确保坝体完好。他指挥水坝的维护工作，并组织当地防御，防范蓄意破坏。",al={"辛德维尔七世是谁","主工程师辛德维尔七世"}},{q="在哪里能找到当地的生物？",a="森林潜伏者蜘蛛在山谷周围林木丛生的荒野中出没。鳄鱼栖息在洛克湖岸边及附近水域。",al={"潜伏者在哪里","鳄鱼位置","哪里能找到蜘蛛"}},{q="铁炉堡的卫兵为何不亲自收集这些物品？",a="巡山人和当地卫兵既要保卫塞尔萨玛等城镇，又要警戒黑铁斥候，早已人手不足。搜寻特殊物品和深入食人魔领地的任务，只能交给有能力的旅人。",al={"为何帮助辛德维尔七世","铁炉堡卫兵在哪里"}}},fx={["0370975a"]={q="主工程师辛德维尔七世为什么要收集这些物品？",a="主工程师辛德维尔七世担心黑铁矮人即将袭击巨石水坝。为了应对任何爆破行动，他需要你收集性质不稳定的特殊材料——潜伏者的毒液、鳄鱼的眼泪和稀有的莫格罗什水晶——以便配制中和药剂，在洛克莫丹遭到毁灭前拆除敌人的炸药。",al={"辛德维尔七世为什么要做这件事","为什么为辛德维尔七世收集材料","辛德维尔七世 动机 黑暗威胁"}}},fp="19,207,17.245.0,18.259.0,58.232.0,37.145.0,44.167.0,37.179.0,44.116.0,61.193.0"}
P.entries["quest:2781"] = {n="通缉：卡利夫·斯科比斯汀",s="加基森水业公司为卡利夫·斯科比德悬赏，此人是沙漠流浪者不法之徒的首领。击杀证明需呈交给加基森的首席工程师沙克斯·比格维兹。",h="加基森水业公司为卡利夫·斯科比德悬赏，此人是沙漠流浪者不法之徒的首领。击杀证明需呈交给加基森的首席工程师沙克斯·比格维兹。",kw={"悬赏","卡利夫·斯科比德","首席工程师沙克斯·比格维兹","加基森","加基森水业公司","热砂港","塔纳利斯","沙漠流浪者"},sec={{t="公司的指控",b="在加基森和热砂港的布告栏上张贴着加基森水业公司发布的高额悬赏，目标是沙漠流浪者不法之徒的首领卡利夫·斯科比德。针对他的指控包括谋杀公司员工、盗窃公司资源以及侵占公司财产。击杀证明需呈交给加基森的首席工程师沙克斯·比格维兹。"},{t="水业公司的期冀",b="首席工程师沙克斯·比格维兹称斯科比德的死是正义的伸张，也是对沙漠流浪者的一记重击，这位工程师称他们为卑劣的游牧民和非法侵占者。公司希望此举能最终将他们从加基森的水井旁赶走，赏金将代表公司支付。"}},faq={{q="谁是卡利夫·斯科比德？",a="他是沙漠流浪者不法之徒的首领，也是加基森水业公司的通缉目标。",al={"卡利夫·斯科比德背景故事","谁领导沙漠流浪者","斯科比德"}},{q="为什么加基森水业公司想要他死？",a="公司指控他谋杀其员工、盗窃其资源并侵占其财产。",al={"为何悬赏斯科比德","卡利夫·斯科比德罪行","加基森水业公司敌人"}},{q="谁支付了卡利夫·斯科比德的赏金？",a="加基森的加基森水业公司首席工程师沙克斯·比格维兹负责接收斯科比德的击杀证明。",al={"谁负责接收斯科比德悬赏","卡利夫的头颅在哪上交","比格维兹悬赏"}},{q="通缉令张贴在哪里？",a="在加基森和热砂港。",al={"卡利夫通缉令位置","哪里领取卡利夫悬赏","斯科比德公告"}}},fp="27,179,21.282.0,32.254.1,27.95.0,51.100.0,44.122.0,37.61.0"}
P.entries["quest:2782"] = {n="林吉的秘密",s="帮助林吉后，你带着林吉的秘密，这块石板上刻着无人读懂的枯木文字。奥兰·斯内克威瑟研究枯木，或许能将其破译。据说他住在幽暗城的魔法区。",h="帮助林吉后，你带着林吉的秘密，这块石板上刻着无人读懂的枯木文字。奥兰·斯内克威瑟研究枯木，或许能将其破译。据说他住在幽暗城的魔法区。",kw={"辛特兰","魔法区","奥兰·斯内克威瑟","林吉","石板","幽暗城","枯木"},sec={{t="无人能读懂的石板",b="石板上刻满了枯木巨魔的文字，但林吉的秘密究竟是什么，仍是个谜。它可能价值连城，也可能一文不值。陷入困境的枯木巨魔为了脱身，可能什么办法都愿意尝试。"},{t="幽暗城的学者",b="奥兰·斯内克威瑟是一位研究枯木巨魔的知名学者。据说他住在幽暗城的魔法区，或许能读懂这块石板。"}},faq={{q="这块石板从何而来？",a="这块石板就是林吉藏在望海崖的秘密。你帮助林吉逃出奎尔丹尼小屋后，找到了它。",al={"林吉石板来源","如何获得石板"}},{q="谁能读懂石板上的文字？",a="奥兰·斯内克威瑟对枯木巨魔十分了解，或许能破译这些文字。",al={"谁能破译石板","谁能读懂枯木文字"}},{q="奥兰·斯内克威瑟在哪里？",a="据说奥兰·斯内克威瑟住在幽暗城的魔法区。",al={"奥兰·斯内克威瑟位置","奥兰在哪里"}},{q="这块石板值钱吗？",a="谁也说不准。这块石板可能价值连城，也可能一文不值，因为陷入困境的枯木巨魔为了摆脱麻烦，可能什么办法都愿意尝试。",al={"林吉的秘密是什么","石板含义"}}},fp="15,227,24.201.0,26.160.0,32.123.0,40.91.0,34.72.0,23.146.0"}
P.entries["quest:280"] = {n="水坝危机",s="这是一个由主工程师辛德维尔七世发布的紧急任务，目的在于阻止巨石水坝被毁。黑铁破坏者们在水面之下深处安置了一枚瑟福瑞姆炸药，威胁要摧毁这座矮人王国最伟大的工程奇迹之一。",h="这是一个由主工程师辛德维尔七世发布的紧急任务，目的在于阻止巨石水坝被毁。黑铁破坏者们在水面之下深处安置了一枚瑟福瑞姆炸药，威胁要摧毁这座矮人王国最伟大的工程奇迹之一。",kw={"水坝","黑铁","拆除","爆炸物","辛德维尔","暴乱分子","桶","瑟福瑞姆","巨石"},ang={["faction:Alliance"]="巨石水坝的毁灭将摧毁连接卡兹莫丹与北方联盟领地的关键交通路线。",["profession:Engineering"]="直接使用瑟福瑞姆和专业的拆弹化学制剂，突显了爆破与反爆炸化学应用在极端情况下的高风险性。",["race:Dwarf"]="巨石水坝是矮人建筑和荣耀的永恒丰碑；保护它免受黑铁矮人的背叛，对铁炉堡的每一位儿女来说都至关重要。",["race:Gnome"]="侏儒的头脑不仅能理解辛德维尔中和剂背后的复杂化学原理，也能预见到瑟福瑞姆爆炸对矮人工程学造成的恐怖破坏。"},sec={{t="水面下的破坏",b="主工程师辛德维尔七世发现了黑铁暴乱分子正游向巨石水坝的底部，他们携带这一大桶名为瑟福瑞姆的烈性炸药。由于附近没有山地探险队员可以干预，这些渗透者直接将武器安装在了水坝的水下基座上。一旦水坝决堤，洛克湖中全部的蓄水就会倾泻到下方的低地，引发灾难性的洪水，并将瘫痪整个地区的矮人贸易与交通。"},{t="不稳定的中和剂",b="辛德维尔迅速将活性成分配制成了一种拆弹剂，并派出一名勇敢的潜水员径直前往水下的炸弹处。想要中和瑟福瑞姆，就需要旋开水下的炸药桶，并将这种化学溶液直接搅拌进炸药粉末中。混合物发出轻柔的水下嘶嘶声，从而让倒计时停止，在爆炸撕裂砖石之前稳住了炸药。"}},faq={{q="这个任务的目标是什么？",a="你必须潜入洛克湖的水下，到达巨石水坝的基座，找到安置好的瑟福瑞姆炸药桶，并倒入主工程师辛德维尔的拆弹剂来中和爆炸。",al={"任务目标","我在这里该做什么","黑暗威胁临近任务目标"}},{q="是谁安置了爆炸桶？",a="黑铁暴乱分子在当天早些时候渗透进了洛克湖，利用当地山地探险队员不在场的机会，将一枚瑟福瑞姆炸药直接安放在了水坝的水下那一侧。",al={"谁放的炸弹","谁安置了瑟福瑞姆","黑暗威胁临近肇事者"}},{q="如果水坝被毁会发生什么？",a="巨石水坝拦截了巨大的洛克湖。如果水坝破碎，数百万加仑的水将会冲入湿地和周围的峡谷，冲毁道路、城镇和生命。",al={"为什么要保护水坝","炸弹爆炸会发生什么","水坝爆炸风险"}},{q="是谁配置了拆弹剂？",a="主工程师辛德维尔七世使用收集到的试剂配制了这种化学中和剂，制造出了一种可以在不引发意外爆炸的情况下中和瑟福瑞姆炸药的混合物。",al={"谁制作了混合物","辛德维尔的角色","谁制作了化学药剂"}},{q="爆炸桶在哪里？",a="炸药桶位于水下，紧靠着巨石水坝南部面向湖泊一侧深处的水下基座。",al={"炸弹在哪里","炸药桶位置","水下火药桶"}},{q="使用了什么样的爆炸物？",a="黑铁破坏者使用的是瑟福瑞姆，这是一种强力且挥发性极强的爆破化合物，被装在密封的防水桶中。",al={"炸弹由什么制成","炸弹类型","什么炸药"}}},fx={["8859d649"]={q="主工程师辛德维尔七世为什么要做这件事？",a="作为负责巨石水坝的主工程师，Hinderweir将确保水坝结构完好视为自己的责任。Dark Iron叛乱者已在坝基安放了威力强大的Seaforium炸药。一旦水坝决口，洛克湖倾泻而出的滔天洪水就会淹没下方的山谷，摧毁矮人最伟大的建筑奇迹之一。",al={"hinderweir为什么在意","hinderweir的动机","为什么要阻止爆炸"}},["34eba16d"]={q="主工程师辛德维尔七世为什么需要你，而不是巡山人？",a="Dark Iron破坏者接近时，附近没有巡山人能够拦截他们，而眼下时间已经极为紧迫。炸药随时可能引爆，Hinderweir又必须留下，赶紧用原料配制拆弹剂。你是在场唯一有能力潜入水下、立即拆除炸药的人。",al={"守卫为什么不能做这件事","hinderweir为什么选我","巡山人在哪里"}}},fp="19,157,28.331.0,22.322.1,31.185.0,30.196.0,37.151.0,36.155.0,35.103.0,32.98.0"}
P.entries["quest:282"] = {n="森内尔的观察站",s="在收集了关于寒脊山谷当地威胁的重要情报后，格瑞林·白须委托你将他的发现带给远在卡拉诺斯的兄弟，森内尔·白须。然而，想要离开这片受保护的山谷，你需要穿过一条最近被敌对穴居人占领的隧道，那里有巡山人萨鲁斯把守。",h="在收集了关于寒脊山谷当地威胁的重要情报后，格瑞林·白须委托你将他的发现带给远在卡拉诺斯的兄弟，森内尔·白须。然而，想要离开这片受保护的山谷，你需要穿过一条最近被敌对穴居人占领的隧道，那里有巡山人萨鲁斯把守。",kw={"安威玛尔","寒脊山谷","格瑞林·白须","格瑞林的报告","卡拉诺斯","巡山人萨鲁斯","森内尔·白须","穴居人","隧道"},ang={["faction:Alliance"]="维持矮人山谷之间通道的安全对于铁炉堡的防御和联盟信使的安全至关重要。",["race:Dwarf"]="对于矮人巡山人和新兵来说，穿过东部隧道标志着他们第一次离开寒脊山谷的训练场，正式执行任务。",["race:Gnome"]="作为生活在铜须部族中的侏儒难民，这份公文提供了一条走出最初避难所的路径，去面对困扰丹莫罗的更广泛的问题。"},sec={{t="白须家族的信使",b="格瑞林·白须花费了巨大的精力来记录寒脊山谷周围蠢蠢欲动的巨魔活动。当他的日志被偷走又被找回后，他意识到收集到的情报太过关键，绝不能交给缺乏经验的学徒。为了绕过中间环节，格瑞林挑选了一位经验丰富的冒险者，直接将他的报告送到他在卡拉诺斯负责山谷外行动的兄弟——森内尔·白须手中。"},{t="通往卡拉诺斯的封锁通道",b="离开寒脊山谷已不再是一段简单的路程。连接山谷与丹莫罗广阔雪原的东部隧道已经被掘地的穴居人暴力占据。为了防止毫无防备的平民误入陷阱，铁炉堡卫队在隧道外驻扎了巡山人萨鲁斯。只有携带紧急公务的旅行者才被允许通过哨所，穿越这条地下险道。"}},faq={{q="格瑞林要把报告送给谁？",a="这份报告是写给格瑞林·白须的兄弟——森内尔·白须的。他目前驻扎在群山之外的卡拉诺斯，负责评估该地区的局势。",al={"谁收到报告","森内尔·白须","报告接收者"}},{q="为什么格瑞林的学徒不能递送报告？",a="格瑞林最初打算派他的学徒去，但在最近发生了冰鬃巨魔偷走他日志的事件后，他认为这些信息太重要了，不能交给缺乏经验的人。",al={"为什么不用学徒","格瑞林的学徒"}},{q="为什么出寒脊山谷的隧道有人把守？",a="连接寒脊山谷与丹莫罗其他地区的隧道已经被穴居人完全占领。巡山人萨鲁斯被部署在洞口，在道路被清理干净之前，负责保障平民的安全。",al={"为什么萨鲁斯在守卫","隧道被封锁","为什么隧道关闭"}},{q="巡山人萨鲁斯在哪里？",a="萨鲁斯驻扎在安威玛尔以东，正守在通往卡拉诺斯的寒脊山谷隧道的入口附近。",al={"萨鲁斯的位置","萨鲁斯在哪里","寻找巡山人萨鲁斯"}},{q="是什么让你能够通过穴居人出没的隧道？",a="巡山人萨鲁斯不会让普通的旅行者进入隧道，但携带格瑞林·白须发出的紧急公文证明了你的任务极其重要，值得去冒这个险。",al={"穿过隧道","隧道通行许可"}},{q="与巡山人萨鲁斯交谈后会发生什么？",a="萨鲁斯会提供穿越这条危险地下路线的警告和指导，然后准许你继续向东前往卡拉诺斯。",al={"下一步","见到萨鲁斯之后"}}},fx={ba85e128={q="格瑞林·白须为什么要送出这份报告？",a="格瑞林·白须一直在记录寒脊山谷中日益频繁的霜鬃巨魔活动及其带来的威胁。他的兄弟森内尔·白须驻扎在卡拉诺斯，收集丹莫罗各地其他事端的情报。将报告安全送到森内尔手中，对协调这一地区的防御至关重要，尤其是如今霜鬃正不断逼近矮人的定居点。",al={"为什么要送格瑞林的报告","格瑞林·白须的动机","为什么要送森内尔的观察报告"}}},fp="20,178,29.308.0,28.232.0,37.123.0,49.145.0,50.153.0,36.108.0,58.90.0,52.120.0"}
P.entries["quest:2821"] = {n="质量的保证",s="在羽月要塞，制皮师普拉特·马克格鲁比对品质绝不妥协。普拉特发现了一种厚实的雪人皮，想要收集一叠，共十张。",h="在羽月要塞，制皮师普拉特·马克格鲁比对品质绝不妥协。普拉特发现了一种厚实的雪人皮，想要收集一叠，共十张。",kw={"羽月要塞","深痕谷","菲拉斯","被遗忘的海岸","普拉特·马克格鲁比","质量的保证","厚实的雪人皮","雪人"},sec={{t="普拉特的理念",b="普拉特·马克格鲁比对皮革制品绝不妥协：只接受最好的品质。在寻找上等材料时，普拉特发现了一种厚实的雪人皮。雪人原生于菲拉斯，许多就栖息在被遗忘的海岸稍往内陆的深痕谷一带。"},{t="报酬",b="只要交来一叠十张雪人皮，普拉特就会让你从他制作的皮革制品中挑选一件。把这些皮带回羽月要塞。"},{t="普拉特对雪人皮的看法",b="普拉特问你是否曾停下来，摸一摸这些皮的质地。经过妥善处理，它们可能比铁还要坚韧，而知道这种皮的人寥寥无几。普拉特精通各种处理皮革的药剂，希望能制作出真正体现卓越品质的物品。"}},faq={{q="谁在收集雪人皮？",a="普拉特·马克格鲁比，羽月要塞的一名制皮师。",al={"任务给予者","普拉特·马克格鲁比","谁提供质量的保证任务"}},{q="在哪里能找到雪人？",a="雪人原生于菲拉斯，许多就栖息在被遗忘的海岸稍往内陆的深痕谷一带。",al={"雪人位置","雪人在哪里","深痕谷"}},{q="普拉特需要多少张皮？",a="十张，叠成一叠。",al={"需要多少张雪人皮","皮的数量"}},{q="交出这些皮能得到什么？",a="交出这一叠皮，就可以从普拉特制作的皮革制品中挑选一件。",al={"普拉特给什么","质量的保证报酬"}}},fp="19,107,18.246.0,9.126.0,29.253.1,28.81.0,29.102.0,31.35.0,28.94.0"}
P.entries["quest:2822"] = {n="质量的保证",s="在莫沙彻营地，制皮师杉多尔·迅蹄坚信，品质绝不能打折扣。杉多尔发现了厚实的雪人毛皮，想要收集一叠十张。",h="在莫沙彻营地，制皮师杉多尔·迅蹄坚信，品质绝不能打折扣。杉多尔发现了厚实的雪人毛皮，想要收集一叠十张。",kw={"莫沙彻营地","深痕谷","菲拉斯","被遗忘的海岸","杉多尔·迅蹄","制皮","厚实的雪人毛皮","雪人"},sec={{t="关乎自豪",b="杉多尔·迅蹄以自己的制皮手艺为傲，认为品质绝不能打折扣。最近，杉多尔发现了厚实的雪人毛皮。雪人栖息在菲拉斯，常出没于莫沙彻营地以西的深痕谷，就在被遗忘的海岸往内陆不远处。"},{t="报酬",b="只要交来一叠十张毛皮，杉多尔就会让你从他制作的皮革制品中挑选一件。把毛皮带回莫沙彻营地。"},{t="杉多尔对毛皮的看法",b="杉多尔声称，经过特殊处理后，这些毛皮能像铁一样坚韧。要找到合适的鞣制配方，还得反复尝试，但杉多尔确信，这些毛皮将把品质标准提升到前所未有的高度。"}},faq={{q="谁需要这些毛皮？",a="杉多尔·迅蹄，菲拉斯莫沙彻营地的一位制皮师。",al={"谁提供任务","质量的保证任务给予者","杉多尔在哪里"}},{q="哪里能找到雪人？",a="雪人是菲拉斯的原生生物。莫沙彻营地以西的深痕谷有许多雪人，就在被遗忘的海岸往内陆不远处。",al={"雪人在哪里","雪人毛皮位置","深痕谷在哪里"}},{q="需要多少张毛皮？",a="十张，叠成一叠。",al={"需要多少张雪人毛皮","雪人毛皮数量","质量的保证任务要求"}},{q="交出毛皮能得到什么？",a="交出这叠毛皮后，杉多尔会让你从他制作的皮革制品中挑选一件。",al={"杉多尔给什么","质量的保证报酬"}}},fp="19,100,17.215.0,9.123.0,31.203.1,28.92.0,29.120.0,28.32.0,28.87.0"}
P.entries["quest:283"] = {n="水坝危机",s="主工程师辛德维尔七世需要你赶往巨石水坝，黑铁破坏者在那里安放了炸药。在下方的山谷陷入危险之前，解除炸药。",h="主工程师辛德维尔七世需要你赶往巨石水坝，黑铁破坏者在那里安放了炸药。在下方的山谷陷入危险之前，解除炸药。",kw={"黑铁","拆弹剂","炸药","辛德维尔七世","洛克莫丹","破坏","巨石水坝"},ang={["faction:Alliance"]="作为联盟的一员，你帮助守住了铁炉堡与北方阿拉希和洛丹伦之间的重要陆路通道。",["profession:Engineering"]="作为一名工程师，你知道，在宏大的土木工程内部解除不稳定的爆破装置时，应对措施和爆破理论有多么重要。",["race:Dwarf"]="作为一名矮人，你可以为巨石水坝这项矮人石工技艺的杰作感到自豪。保护它，就是在黑铁的恶意面前捍卫铁炉堡的骄傲。"},sec={{t="水坝中的炸药",b="巨石水坝拦住洛克湖的湖水，下方便是湿地的低地。如今，坝内藏着一桶黑铁矮人留下的不稳定炸药。一旦引爆，下方的山谷和下游的生灵都将遭殃。你必须在那之前使用拆弹剂，然后向主工程师辛德维尔七世报信。"},{t="辛德维尔七世如释重负",b="你使用了拆弹剂，那桶不稳定的炸药嘶嘶作响，随后便失去了威胁。水坝和下游生灵面临的燃眉之急已经解除。听到你的报告，主工程师辛德维尔七世松了一口气。他称你的行动为铁炉堡王国和联盟赢得了一场胜利。黑铁渗透者已经深入卡兹莫丹，而这些心怀怨恨的同族仍执意要毁掉铁炉堡的成就。"}},faq={{q="这条任务线的目标是什么？",a="这条任务线旨在揭露并阻止黑铁矮人引爆炸药、摧毁巨石水坝的阴谋。",al={"水坝危机概要","巨石水坝任务目标","为何拆除炸弹"}},{q="是谁安放了炸药？",a="黑铁矮人破坏者在巨石水坝内部安放了炸药桶，企图将其摧毁。",al={"谁在这里安放了炸弹","谁袭击了水坝","黑铁水坝"}},{q="主工程师辛德维尔七世是谁？",a="主工程师辛德维尔七世是一位矮人主管，负责洛克莫丹巨石水坝的维护、运行和防御。",al={"辛德维尔七世是谁","辛德维尔七世背景故事","水坝的工程师"}},{q="如果水坝决堤，会发生什么？",a="如果巨石水坝决堤，洛克莫丹水库的蓄水就会汹涌而出，淹没下游的湿地，冲毁道路、定居点和重要的交通要道。",al={"水坝被毁会怎样","水坝决堤的后果","水坝爆炸"}},{q="炸药是如何被解除的？",a="你将专门调配的拆弹剂倒在炸药上，火药桶嘶嘶作响，在引爆之前安全地熄灭了。",al={"如何阻止炸弹爆炸","拆弹剂","如何解除炸药"}},{q="巨石水坝现在安全了吗？",a="眼前的爆炸危机已经解除，水坝得以保全。辛德维尔七世说，水坝的防御只是暂时稳固，因为黑铁密探仍在威胁这片地区。",al={"水坝是否安全","黑铁是否已经离开","水坝是否永远安全"}}},fp="19,157,21.377.0,19.433.1,38.115.0,33.96.0,37.143.0,42.169.0,31.137.1,33.176.1"}
P.entries["quest:284"] = {n="继续搜寻",s="你继续在附近的鱼人棚屋中寻找米奈希尔雕像。这些棚屋里没有雕像的踪迹，于是你转向另外两间。",h="你继续在附近的鱼人棚屋中寻找米奈希尔雕像。这些棚屋里没有雕像的踪迹，于是你转向另外两间。",kw={"桶","奶酪","棚屋","米奈希尔雕像","鱼人","搜寻"},sec={{t="空荡的棚屋",b="你搜查了这片鱼人棚屋，却没有发现米奈希尔雕像的踪迹。附近北面和东北面的两间棚屋里或许有线索。"}},faq={{q="我在寻找什么？",a="你在寻找米奈希尔雕像。",al={"寻找雕像","米奈希尔雕像","什么雕像"}},{q="这些棚屋里有什么发现？",a="你在这片鱼人棚屋中没有发现米奈希尔雕像的踪迹。",al={"鱼人棚屋","空荡的棚屋","这里有什么"}},{q="接下来该去哪里找？",a="去附近北面和东北面的棚屋里寻找更多线索。",al={"接下来搜查的棚屋","去哪里找","北面的棚屋"}},{q="桶里有什么？",a="桶里装着潮湿、气味刺鼻的奶酪，吃起来依然美味。",al={"桶里的东西","奶酪桶","桶里有什么"}}},fp="20,135,12.149.0,24.45.0,31.77.0,25.68.0,22.58.0"}
P.entries["quest:2844"] = {n="大保姆",s="巨人罗克比特本该照看他的小朋友——暗夜精灵女孩沙恩，可不知怎么，她竟然走丢了。他忧心忡忡，不知如何是好，于是请你去找她。",h="巨人罗克比特本该照看他的小朋友——暗夜精灵女孩沙恩，可不知怎么，她竟然走丢了。他忧心忡忡，不知如何是好，于是请你去找她。",kw={"菲拉斯","巨人守护者","迷路的女孩","罗克比特","废墟","沙恩","沙恩·飘叶"},sec={{t="一转身就不见了",b="罗克比特本该照看沙恩。他最后一次见到她时，两人正走在他所在位置北边不远的废墟中。本来一切都好好的，可他一转身，就发现她不见了。他不知道该怎么办，但他知道你的双腿跑得比他快得多，于是请你去寻找她。"},{t="找到她时",b="沙恩很高兴有人找到了她。她承认自己有点迷路了，却还是忍不住赞叹这里的美景。"}},faq={{q="罗克比特在找谁？",a="一个名叫沙恩的暗夜精灵小女孩，她是他的朋友，本该由他照看。",al={"沙恩是谁","失踪的女孩是谁","谁迷路了"}},{q="最后一次有人见到沙恩是在哪里？",a="罗克比特说，她失踪时，两人正走在他所在位置北边不远的废墟中。",al={"沙恩去哪了","最后出现的位置","废墟在哪里"}},{q="罗克比特为什么请别人去找她？",a="他很担心，不知道该怎么办，而且他觉得你的双腿跑得比他快得多。",al={"罗克比特为什么不能去找","为什么派冒险者去"}}},fp="18,113,30.241.0,17.109.1,29.102.0,25.87.0,46.99.0"}
P.entries["quest:2845"] = {n="迷路的沙恩",s="找到沙恩·飘叶后，她请你帮她回到朋友罗克比特身边。她承认，只要有东西可看，她就会走开，但她有一只铃铛，一听到铃声就会跑回来。",h="找到沙恩·飘叶后，她请你帮她回到朋友罗克比特身边。她承认，只要有东西可看，她就会走开，但她有一只铃铛，一听到铃声就会跑回来。",kw={"护送","菲拉斯","巨人卫士","罗克比特","沙恩·飘叶","沙恩的铃铛"},sec={{t="容易分心的女孩",b="沙恩想回到罗克比特身边，他本该照看着她。她承认自己时不时就会走开，因为可看的东西太多，她总会分心。"},{t="箱中的铃铛",b="沙恩说，有一样东西总能引起她的注意。她身旁的箱子里放着一只她珍爱的铃铛，她很喜欢它的声音。她保证，如果自己走开了，只要摇响铃铛，她就会跑回来。铃铛由你携带，她希望你把她带到罗克比特的营地。"}},faq={{q="沙恩·飘叶想回到谁的身边？",a="她的朋友罗克比特身边，他本该照看着她。你要把她带到他的营地。",al={"罗克比特是谁","沙恩的朋友","沙恩去哪里"}},{q="沙恩为什么会走开？",a="她说可看的东西太多，所以总会分心。",al={"沙恩为什么迷路","沙恩怎么迷路的","沙恩为什么走开"}},{q="怎样才能让沙恩不乱跑？",a="沙恩的铃铛放在她身旁的箱子里。她喜欢铃铛的声音，并保证如果自己走开了，只要摇响铃铛，她就会跑回来。",al={"如何管住沙恩","沙恩的铃铛","铃铛有什么用"}},{q="前一个任务是什么？",a="前一个任务是巨人看护者，罗克比特在那个任务中派你去寻找沙恩。",al={"前置任务","巨人监护者","迷路的沙恩的前置任务"}}},fp="14,106,24.136.0,21.231.0,45.109.0,25.57.0,33.143.0,23.81.0"}
P.entries["quest:285"] = {n="搜寻雕像",s="你在鱼人的棚屋中没有找到米奈希尔雕像的踪迹。于是你继续向北，寻找下一条线索。",h="你在鱼人的棚屋中没有找到米奈希尔雕像的踪迹。于是你继续向北，寻找下一条线索。",kw={"桶","米奈希尔雕像","鱼人棚屋","北边的棚屋","搜查更多棚屋"},sec={{t="向北搜寻",b="你相信米奈希尔雕像就在北边的某间棚屋里。于是你继续在鱼人的住处搜寻。"}},faq={{q="我在寻找什么？",a="你正在鱼人的棚屋中寻找米奈希尔雕像。",al={"搜寻雕像","米奈希尔雕像","在寻找什么"}},{q="这些棚屋里有雕像吗？",a="你仔细搜查了这一带的棚屋，却一无所获。",al={"空棚屋","这里有何发现","棚屋里有何发现"}},{q="雕像可能在哪里？",a="你相信更北边的某间鱼人棚屋里可能藏着米奈希尔雕像。",al={"雕像在哪里","北边的棚屋","雕像位置"}}},fp="18,125,16.130.0,24.63.0,36.58.0,29.83.0"}
P.entries["quest:286"] = {n="归还雕像",s="米奈希尔港的卡尔·波兰需要有人把米奈希尔雕像带回来。它是在一只从淤泥中捞出的木桶里发现的，归还它能让Blind Princess的船长松一口气。",h="米奈希尔港的卡尔·波兰需要有人把米奈希尔雕像带回来。它是在一只从淤泥中捞出的木桶里发现的，归还它能让Blind Princess的船长松一口气。",kw={"木桶","盲眼公主","卡尔·波兰","米奈希尔港","米奈希尔雕像","圣骑士","小雕像"},sec={{t="小雕像",b="小雕像放在木桶里，周围填着细软的稻草。它刻画的是一位留着长发、举起战锤的年轻圣骑士。米奈希尔港的卡尔·波兰正等着它。得知货物安然无恙，Blind Princess的船长就能松一口气了。"}},faq={{q="米奈希尔雕像是什么？",a="米奈希尔雕像是一尊银色的小雕像，刻画的是一位留着长发、高举战锤的年轻圣骑士。",al={"小雕像","米奈希尔 小雕像","木桶里有什么"}},{q="小雕像是在哪里发现的？",a="小雕像放在一只从淤泥中捞出的木桶里，周围填着细软的稻草。",al={"木桶小雕像","在哪里发现的","稻草木桶"}},{q="谁在等着小雕像？",a="米奈希尔港的卡尔·波兰正等着米奈希尔雕像。",al={"小雕像交给谁","归还小雕像","卡尔·波兰"}},{q="小雕像归还后，谁会松一口气？",a="得知珍贵的货物已经找回，盲眼公主号的船长就能松一口气了。",al={"船长松一口气","盲眼公主号 货物","货物是谁的"}},{q="小雕像刻画的是什么？",a="小雕像刻画的是一位留着长发、高举战锤的年轻圣骑士。",al={"小雕像上是谁","圣骑士小雕像","战锤小雕像"}}},fp="20,178,12.235.0,31.103.0,30.76.0,33.68.0,41.94.0,31.72.0"}
P.entries["quest:2862"] = {n="与豺狼人开战",s="在莫沙彻营地，哈杜肯·迅蹄称豺狼人对营地本身构成了长久的威胁，而且近来它们的袭击变得愈发狂暴。哈杜肯要求你带回十个木爪豺狼人鬃毛，以削减它们的数量。",h="在莫沙彻营地，哈杜肯·迅蹄称豺狼人对营地本身构成了长久的威胁，而且近来它们的袭击变得愈发狂暴。哈杜肯要求你带回十个木爪豺狼人鬃毛，以削减它们的数量。",kw={"先发制人","莫沙彻营地","菲拉斯","豺狼人","哈杜肯·迅蹄","鬃毛","木爪"},sec={{t="对营地的威胁",b="对哈杜肯而言，这些豺狼人是否属于菲拉斯并不重要。他警告说，如果营地不能坚定决心，他们就会被彻底赶出这一地区。随着对营地的袭击变得愈发频繁，他想要削减它们的数量，并承诺为十个木爪豺狼人鬃毛提供丰厚的报酬。"},{t="哈杜肯的回应",b="哈杜肯称这些鬃毛是一个好的开始。他曾向其他人提出过同样的要求；许多人以前也与豺狼人战斗过，过去的努力确实遏制了它们。最近，豺狼人更频繁地向北推进至营地控制的区域，它们的袭击变得野蛮且近乎绝望。哈杜肯说他有一个计划，或许能解决这个问题。"}},faq={{q="在菲拉斯是谁提供了这份悬赏？",a="莫沙彻营地的哈杜肯·迅蹄。",al={"谁发布了针对木爪的战争","在哪里交还针对木爪的战争任务","针对木爪的战争任务发布者"}},{q="为什么莫沙彻营地要针对木爪豺狼人？",a="哈杜肯认为它们对营地构成了持续的威胁，且袭击愈发狂暴。他担心如果营地不坚守阵地，就会被彻底赶出这一地区。",al={"为什么要与木爪战斗","木爪问题","为什么豺狼人在袭击"}},{q="哈杜肯·迅蹄需要什么证明？",a="十个木爪豺狼人鬃毛。",al={"针对木爪的战争需要什么物品","木爪任务物品","我应该带什么给哈杜肯"}}},fp="18,182,20.314.0,18.368.1,34.55.0,49.193.0,45.54.0"}
P.entries["quest:2863"] = {n="突然袭击",s="哈杜肯·迅蹄打算打破与木爪豺狼人之间的僵局：在短时间内连续击杀几名自称为“阿尔法”的豺狼人领袖。哈杜肯希望由你来执行这个计划。",h="哈杜肯·迅蹄打算打破与木爪豺狼人之间的僵局：在短时间内连续击杀几名自称为“阿尔法”的豺狼人领袖。哈杜肯希望由你来执行这个计划。",kw={"阿尔法突袭","菲拉斯","豺狼人","哈杜肯·迅蹄","木爪","木爪阿尔法"},sec={{t="一小时内击杀五个阿尔法",b="哈杜肯推断，如果这些自称为“阿尔法”的豺狼人领袖一个接一个地倒下，它们的队伍就会陷入混乱。这也将传达出一个信息：部落有能力也有决心消灭它们。你必须执行哈杜肯的意志：在一小时内击杀五个阿尔法，否则僵局将无法打破。"},{t="后续",b="哈杜肯认为，削减兵力和击杀领袖会让豺狼人在突袭营地前产生犹豫。但麻烦还没有结束。哈杜肯想在豺狼人重新集结之前，查清到底是什么让它们变得如此疯狂。"}},faq={{q="谁发布了这个任务？",a="哈杜肯·迅蹄，他正在为部落处理与木爪豺狼人之间的僵局。",al={"谁发布阿尔法突袭任务","哈杜肯·迅蹄","任务发布者"}},{q="为什么要设定一小时的限制？",a="这个计划只有在阿尔法们快速接连倒下时才会奏效，因为这样才能让豺狼人的队伍陷入混乱。必须在一小时内击杀五个。",al={"为什么限制一小时","为什么连续击杀","阿尔法突袭时间限制"}},{q="什么是阿尔法？",a="它们是木爪豺狼人中的领袖，自称为阿尔法。",al={"木爪阿尔法","豺狼人阿尔法","目标是谁"}},{q="我需要击杀多少个阿尔法？",a="五个，必须在一小时内全部完成，然后回到哈杜肯·迅蹄那里。",al={"需要多少阿尔法","阿尔法计数"}}},fp="12,179,22.277.0,10.225.1,21.102.0,23.127.0,20.76.0,28.79.0"}
P.entries["quest:2866"] = {n="索兰萨尔废墟",s="珊蒂斯·羽月告诉你，南边的索兰萨尔废墟如今挤满了憎世娜迦。你受命前往废墟巡视，留意任何异常之处。",h="珊蒂斯·羽月告诉你，南边的索兰萨尔废墟如今挤满了憎世娜迦。你受命前往废墟巡视，留意任何异常之处。",kw={"羽月要塞","菲拉斯","凉亭","符文","憎世","娜迦","珊蒂斯·羽月","索兰萨尔"},sec={{t="古老石墙间的娜迦",b="索兰萨尔废墟的历史远早于现代。珊蒂斯说，他们起初探索过那里，没有发现什么值得注意的东西，便不再过问。然而就在最近，憎世娜迦占据了那里，数量之多令人不安。起初，这看起来像是进攻的前兆，这种威胁至今仍未消除，但珊蒂斯认为，背后或许另有缘由。你要前往废墟巡视，留意任何异常之处。"},{t="异样之处",b="仔细察看凉亭时，你发现它与周围的石砌建筑截然不同。它显然是后来新建的。凉亭四周刻着细小的符文，排列成反复出现的图案，没有人知道它们的来历或含义。石头本身摸起来是温热的。"}},faq={{q="索兰萨尔废墟在哪里？",a="就在珊蒂斯·羽月所在位置的南边。",al={"索兰萨尔废墟位置","索兰萨尔在哪","哪里能找到索兰萨尔"}},{q="珊蒂斯·羽月为什么担忧这片废墟？",a="憎世娜迦最近占据了废墟，数量之多令人不安。起初，这看起来像是在为进攻做准备，如今这种可能性依然存在，但珊蒂斯认为，背后或许另有缘由。",al={"为何派我去索兰萨尔","珊蒂斯·羽月索兰萨尔缘由","为何调查索兰萨尔"}},{q="娜迦到来之前，索兰萨尔废墟是什么样的？",a="这片废墟的历史远早于现代。珊蒂斯说，起初有人探索过那里，没有发现什么值得注意的东西，此后便不再打扰那里。",al={"索兰萨尔历史","索兰萨尔是什么"}},{q="废墟里有哪些娜迦？",a="憎世娜迦。",al={"谁在索兰萨尔","索兰萨尔敌人","索兰萨尔的娜迦部族"}}},fp="21,151,22.386.0,15.198.1,32.44.0,54.197.0,56.131.0,28.32.0"}
P.entries["quest:2867"] = {n="返回羽月要塞",s="你在索兰萨尔废墟的中心发现了一座奇怪的凉亭。现在该返回羽月要塞，将此事报告给珊蒂斯·羽月将军了。",h="你在索兰萨尔废墟的中心发现了一座奇怪的凉亭。现在该返回羽月要塞，将此事报告给珊蒂斯·羽月将军了。",kw={"羽月要塞","菲拉斯","憎世","纳迦","索兰萨尔废墟","珊蒂斯·羽月","索兰萨尔 凉亭"},sec={{t="带回报告",b="珊蒂斯·羽月将军正在羽月要塞，等你报告在废墟深处发现的那座奇怪凉亭。带着你的发现返回要塞。"},{t="归来之后",b="珊蒂斯 认为你关于凉亭的报告令人不安。即使纳迦从未打算发动进攻，他们继续盘踞于此，对向菲拉斯推进的行动而言也是个不祥之兆。要塞急需更多援手来对抗憎世纳迦，如果你愿意，珊蒂斯 还有更多任务交给你。"}},faq={{q="探索废墟后该向谁报告？",a="羽月要塞的珊蒂斯·羽月将军。",al={"向谁交任务","谁要这份报告","返回羽月要塞 在哪里交"}},{q="该报告什么？",a="索兰萨尔废墟中心矗立着的那座奇怪凉亭。",al={"向 珊蒂斯 报告什么","在 索兰萨尔 发现了什么"}},{q="前一个任务是什么？",a="前一个任务是《索兰萨尔废墟》，珊蒂斯 在那个任务中派你探索废墟，调查那里的纳迦。",al={"前置任务","前置任务是什么"}}},fp="32,154,24.182.0,14.281.1,35.65.0,21.98.0,23.118.0"}
P.entries["quest:2869"] = {n="憎世纳迦之战",s="羽月要塞的拉托尼库斯·月矛想要正面迎击仇恨之峰纳迦，而不是坐以待毙。他要求你收集十片完好的仇恨之峰鳞片。",h="羽月要塞的拉托尼库斯·月矛想要正面迎击仇恨之峰纳迦，而不是坐以待毙。他要求你收集十片完好的仇恨之峰鳞片。",kw={"未雨绸缪","羽月要塞","菲拉斯","仇恨之峰","仇恨之峰纳迦鳞片","拉托尼库斯·月矛","纳迦","萨尔多岛"},sec={{t="未雨绸缪",b="无论纳迦在图谋什么，拉托尼库斯·月矛都认为他们迟早会试图占领这座岛屿，因此必须在为时已晚之前采取强硬的手段。他需要十片完好的仇恨之峰鳞片，并希望你自己想办法弄到手。他指望通过这种方式削弱萨尔多岛上的纳迦势力，这也将是你第一次与纳迦交手。"},{t="和平与职责",b="拉托尼库斯明确表示，暗夜精灵并非好战之徒，而是致力于追求和平与和谐。但他同时也表示，这并不意味着他们会放弃守护自己的利益，而守护这些利益正是他对羽月将军和这座要塞应尽的职责。"},{t="事后",b="拉托尼库斯表示这些鳞片非常完美，打算把它们送给普拉特，看看能不能从中制作出有用的东西。他还有其他任务要交给你。"}},faq={{q="是谁发布了这个任务，在哪里领取？",a="拉托尼库斯·月矛，在羽月要塞，既负责发布收集鳞片的任务，也负责接收任务物品。",al={"谁发布了未雨绸缪","拉托尼库斯·月矛的位置","去哪里交未雨绸缪任务"}},{q="拉托尼库斯·月矛为什么要仇恨之峰鳞片？",a="他推测纳迦迟早会采取行动控制萨尔多岛，因此想要先发制人采取强硬措施。收集鳞片意味着削弱他们在岛上的势力。",al={"为什么要杀仇恨之峰","仇恨之峰鳞片的用途","为什么要收集纳迦鳞片"}},{q="需要多少鳞片？",a="十片完好的仇恨之峰鳞片。",al={"需要多少鳞片","鳞片数量"}},{q="在哪里可以找到仇恨之峰纳迦？",a="拉托尼库斯提到了萨尔多岛上有纳迦的驻军。",al={"仇恨之峰的位置","去哪里找仇恨之峰","萨尔多岛纳迦"}}},fp="21,174,28.344.0,14.186.0,10.166.1,31.85.0,52.141.0,27.48.0,35.52.0"}
P.entries["quest:287"] = {n="霜鬃巨魔要塞",s="在涌冰湖上方，霜鬃巨魔守卫着西部群峰中的一座洞穴要塞。森内尔·白须是卡拉诺斯的一名巡山人兼斥候，他派你深入洞穴侦察，带回撰写报告所需的情报。",h="在涌冰湖上方，霜鬃巨魔守卫着西部群峰中的一座洞穴要塞。森内尔·白须是卡拉诺斯的一名巡山人兼斥候，他派你深入洞穴侦察，带回撰写报告所需的情报。",kw={"烈酒村","丹莫罗","霜鬃猎头者","霜鬃巨魔要塞","冰霜巨魔","涌冰湖","卡拉诺斯","森内尔·白须","报告"},ang={["faction:Alliance"]="作为联盟的一员，你协助保卫丹莫罗，确保连接铁炉堡与邻近王国的山路免遭敌对部族伏击。",["race:Dwarf"]="身为矮人，你知道霜鬃巨魔正在挑战铁炉堡对丹莫罗雪峰的控制。侦察他们的主要洞穴要塞有助于保卫王国。",["race:Gnome"]="身为侏儒，你知道诺莫瑞根沦陷后，侏儒们在丹莫罗各地和卡拉诺斯安顿下来。遏制霜鬃的袭击有助于保障难民补给通道的安全。"},sec={{t="误了期限的斥候",b="森内尔追踪那些凶悍的部族，找到了位于烈酒村西南方的主要洞穴。入口处挤满了全副武装的巨魔。森内尔的正式报告已经逾期，又不愿独自进入，于是雇你代他侦察这座冰冷的洞穴。"},{t="攻入洞穴",b="这座要塞位于涌冰湖上方，开凿于西部群峰之中，里面挤满了充满敌意的冰霜巨魔。你一路杀穿地下通道，消灭驻守在岩台上的霜鬃猎头者，并绘出内部地形。你带回的发现为森内尔提供了所需的情报，让他能完成呈交铁炉堡军事指挥官的报告。"}},faq={{q="霜鬃巨魔要塞在哪里？",a="霜鬃巨魔要塞位于烈酒村西南方，坐落在丹莫罗最西端的一处洞穴中。从卡拉诺斯沿路向北走到桥边，再沿结冰的河流向西，经过涌冰湖抵达烈酒村，然后向西南方登山。",al={"寻找霜鬃巨魔要塞","洞穴在哪","霜鬃巨魔要塞位置"}},{q="森内尔·白须是谁？",a="森内尔·白须是一名矮人斥候，驻扎在卡拉诺斯的雷酒酿制厂外。他追踪丹莫罗各地的威胁，并撰写有关凶悍的霜鬃巨魔的报告。",al={"森内尔·白须","谁发布任务","卡拉诺斯任务发布者"}},{q="森内尔为什么不亲自探索要塞？",a="森内尔侦察了入口，发现那个部族聚集在那里，但洞里满是全副武装的巨魔，他不敢独自进入。他担心自己的安全，侦察工作又已超过期限，于是把这项危险的任务交给有能力的冒险者。",al={"森内尔为何害怕","森内尔为何没去"}},{q="霜鬃巨魔是什么部族？",a="霜鬃是一个冰霜巨魔部族，世代生活在丹莫罗白雪覆盖的峭壁间。他们是铁炉堡矮人和侏儒的死敌，经常从遍布这片地区的隐蔽营地出击，袭击商路、营地和定居点。",al={"霜鬃","巨魔 丹莫罗","丹莫罗巨魔"}},{q="完成要塞侦察后会发生什么？",a="当你带回洞穴内部布局和猎头者已被消灭的消息后，森内尔便完成了报告。他请你把这些紧急文件送交他在丹莫罗的上级。",al={"后续任务","霜鬃巨魔要塞之后","森内尔的观察报告任务"}},{q="需要深入洞穴多远？",a="越过入口，侦察内部洞室，并杀死五名霜鬃猎头者。他们的死亡证实洞穴深处已经得到彻底调查。",al={"彻底探索霜鬃巨魔要塞","洞穴探索触发条件"}}},fx={["889a57f0"]={q="森内尔·白须为什么要探索霜鬃巨魔要塞？",a="森内尔·白须是一名情报人员，负责撰写有关丹莫罗日益严峻的威胁的报告。他的侦察工作落下了进度，需要霜鬃巨魔营地的第一手情报，好赶在上级察觉之前完成交给铁炉堡指挥部的评估。",al={"森内尔为什么要做这件事","森内尔·白须的动机","为什么要侦察霜鬃巨魔要塞"}},["860fac70"]={q="为什么派你去对付霜鬃猎头者？",a="霜鬃猎头者是霜鬃巨魔要塞的武装守卫，这片位于烈酒村西南的深邃洞穴聚集了大批流离失所的巨魔。杀死这些守卫可以削弱巡逻力量，清出一条道路，以便深入洞穴展开侦察。",al={"霜鬃 猎头者是什么来头","为什么要杀猎头者","霜鬃 猎头者的作用"}}},fp="14,214,23.234.0,20.334.0,32.263.0,24.184.0,42.249.0,29.225.0,52.176.1,41.175.0"}
P.entries["quest:2870"] = {n="击败沙尔扎鲁",s="羽月要塞的拉托尼库斯·月矛告诉你，斥候已经确认了一名尤为残忍的娜迦王族，沙尔扎鲁。他请你除掉沙尔扎鲁，并带回这位娜迦领主挖出的遗物。",h="羽月要塞的拉托尼库斯·月矛告诉你，斥候已经确认了一名尤为残忍的娜迦王族，沙尔扎鲁。他请你除掉沙尔扎鲁，并带回这位娜迦领主挖出的遗物。",kw={"羽月要塞","菲拉斯","憎世","恐怖之岛","拉托尼库斯·月矛","沙尔扎鲁","神秘遗物","娜迦"},sec={{t="娜迦的指挥体系",b="新的侦察报告让拉托尼库斯·月矛清楚地了解了娜迦的指挥体系。娜迦的队伍中有王族，命令正是由他们下达的。沙尔扎鲁就是其中尤为残忍的一位。"},{t="奇异的遗物",b="据斥候报告，娜迦在恐怖之岛的一处洞穴中挖掘时，沙尔扎鲁亲自挖出了一件奇异的遗物，那里与此地隔水相望，位于主要废墟的南面。拉托尼库斯希望你除掉沙尔扎鲁，终止挖掘，并将神秘遗物带到羽月要塞交给他，以便研究。"},{t="事成之后",b="拉托尼库斯相信，沙尔扎鲁的覆灭会让娜迦陷入一段时间的混乱，甚至可能永远如此，而如今的威胁也比以往任何时候都更可控。随后，他还有一件事要请你帮忙。"}},faq={{q="沙尔扎鲁是谁？",a="斥候确认的一名尤为残忍的娜迦王族。娜迦的队伍中有王族，由他们发号施令。",al={"沙尔扎鲁","沙尔扎鲁是谁","沙尔扎鲁的故事"}},{q="沙尔扎鲁在哪里？",a="斥候指出，挖掘地点在恐怖之岛的一处洞穴中，那里与此地隔水相望，位于主要废墟的南面。",al={"沙尔扎鲁在哪","沙尔扎鲁洞穴位置","寻找沙尔扎鲁"}},{q="那件遗物是什么？",a="娜迦挖掘时，沙尔扎鲁亲自挖出的一件奇异遗物。拉托尼库斯希望你把它带给他，以便研究。",al={"神秘遗物 菲拉斯","遗物是什么","沙尔扎鲁遗物"}},{q="我该把遗物交到哪里？",a="交给羽月要塞的拉托尼库斯·月矛。",al={"遗物交给谁","沙尔扎鲁任务交付"}}},fp="21,110,25.150.0,12.277.0,15.198.1,21.93.0,31.108.0,18.141.0,29.66.0"}
P.entries["quest:2871"] = {n="递送遗物",s="拉托尼库斯·月矛请求你将神秘遗物送到羽月要塞，交给他的妻子维斯提亚·月矛。他完全搞不懂这个装置，希望她能看出这是什么东西。",h="拉托尼库斯·月矛请求你将神秘遗物送到羽月要塞，交给他的妻子维斯提亚·月矛。他完全搞不懂这个装置，希望她能看出这是什么东西。",kw={"交付遗物","羽月要塞","菲拉斯","拉托尼库斯·月矛","神秘遗物","维斯提亚·月矛"},sec={{t="学者的眼光",b="即使打赌输了，拉托尼库斯·月矛也没能搞懂这个装置。他说，他的妻子维斯提亚是他们社区里优秀的牧师，也是随处可见的最博学的学者之一。如果有人能弄清楚这个遗物是什么，那一定就是她，而他们必须知道答案。她就在不远处，毫无疑问正在忙于研究。"},{t="维斯提亚的初步观察",b="维斯提亚知道你曾帮助羽月将军和拉托对抗纳迦。当她拿到遗物时，第一眼判断它看起来并不属于它被发现的那些遗迹，也不是纳迦的设计，而是更加外来的东西。研究它需要时间，一旦完成，如果你们还在附近，她可能会再次寻求你的帮助。"}},faq={{q="维斯提亚·月矛是谁？",a="拉托尼库斯·月矛的妻子。拉托尼库斯称她是他们社区里优秀的牧师，也是一位博学的学者。她就在羽月要塞。",al={"维斯提亚·月矛","维斯提亚是谁","拉托的妻子"}},{q="神秘遗物来自哪里？",a="这是沙尔扎鲁领主在恐怖之岛的洞穴里挖掘纳迦时发现的遗物。",al={"遗物来自哪里","遗物起源","神秘遗物来源"}},{q="拉托尼库斯·月矛对这个遗物了解多少？",a="知之甚少。他说他完全搞不懂这个装置，所以才想让他的妻子看一看。",al={"拉托尼库斯了解什么","拉托的装置"}},{q="我该把遗物带到哪里去？",a="带给羽月要塞的维斯提亚·月矛。拉托尼库斯说她就在转角处。",al={"谁来接收遗物","交付遗物的目的地"}}},fp="20,166,15.322.0,19.325.1,24.178.0,42.116.0,52.131.0,26.117.0"}
P.entries["quest:2872"] = {n="斯杜雷的债务",s="“海狼”马克基雷和老朋友斯杜雷打了个赌，比比谁的朗姆酒更烈，斯杜雷在热砂港照看酒吧。斯杜雷似乎在躲着这件事，所以马克基雷请你去和他谈谈。",h="“海狼”马克基雷和老朋友斯杜雷打了个赌，比比谁的朗姆酒更烈，斯杜雷在热砂港照看酒吧。斯杜雷似乎在躲着这件事，所以马克基雷请你去和他谈谈。",kw={"舱底朗姆酒","藏宝海湾","马克基雷","朗姆酒","热砂港","斯杜雷","塔纳利斯","赌约"},sec={{t="朗姆酒与钱的赌约",b="斯杜雷欠“海狼”马克基雷一瓶非常特别的朗姆酒。斯杜雷夸口说，热砂港的朗姆酒比藏宝海湾的任何朗姆酒都烈，还说如果马克基雷尝过后不认同，欠款就翻倍。如今马克基雷觉得斯杜雷没胆子把酒交出来了，但马克基雷从不在赌约面前退缩。你受托前往热砂港的酒吧，与斯杜雷谈谈。"},{t="斯杜雷的答复",b="斯杜雷表示，他并不怕交出热砂劣质朗姆酒。问题是，已经没有朗姆酒可以交给马克基雷了。"}},faq={{q="“海狼”马克基雷是谁？",a="他是斯杜雷的朋友，两人打赌比谁的朗姆酒更烈。他提到，要拿藏宝海湾的朗姆酒来作比较。",al={"马克基雷是谁","“海狼”马克基雷","谁提供斯杜雷的债务任务"}},{q="斯杜雷在哪里？",a="斯杜雷是塔纳利斯热砂港的酒保。",al={"斯杜雷在哪里","斯杜雷位置","寻找斯杜雷"}},{q="斯杜雷和马克基雷打了什么赌？",a="斯杜雷夸口说，热砂港的朗姆酒胜过藏宝海湾的任何朗姆酒。如果马克基雷尝过后不认同，斯杜雷就会把欠他的钱翻倍。",al={"赌约是什么","打什么赌","斯杜雷的赌约"}}},fp="13,133,24.434.0,15.99.1,28.96.0,24.53.0,40.171.0"}
P.entries["quest:2873"] = {n="斯杜雷的货物",s="斯杜雷的朗姆酒喝光了，而且还因为一个赌注欠了朋友一笔债。库尔戈船长偷走了最后一批货物，并把它藏在南边那个有围墙的海盗镇里。所以斯杜雷请求你把它找回来。",h="斯杜雷的朗姆酒喝光了，而且还因为一个赌注欠了朋友一笔债。库尔戈船长偷走了最后一批货物，并把它藏在南边那个有围墙的海盗镇里。所以斯杜雷请求你把它找回来。",kw={"库尔戈","落帆海湾","马克基雷","朗姆酒","货物","热砂港","斯杜雷","塔纳利斯"},sec={{t="被盗的货物",b="斯杜雷答应给藏宝海湾的“海狼”马克基雷的朗姆酒已经没了，而他需要用这些酒来偿还赌债。库尔戈船长偷走了最后一批货，并把它藏在南边那个叫落帆海湾的有围墙的海盗镇里。斯杜雷请求你找回这批朗姆酒，好让他证明卡利姆多的酒比藏宝海湾能提供的任何酒都要好。"},{t="存放在哪里",b="在海盗镇里，朗姆酒被装在西北方那座房子的上层木箱中。"}},faq={{q="斯杜雷是谁？",a="斯杜雷在塔纳利斯的热砂港，他欠了藏宝海湾的“海狼”马克基雷一些朗姆酒来偿还赌注。",al={"斯杜雷","谁发布斯杜雷的货物任务","塔纳利斯的斯杜雷"}},{q="为什么斯杜雷想要拿回他的货物？",a="库尔戈船长偷走了他最后一批朗姆酒。斯杜雷需要用它来偿还与马克基雷的赌约，并证明卡利姆多的酒胜过藏宝海湾的酒。",al={"为什么要朗姆酒","斯杜雷的动机","斯杜雷的货物是什么"}},{q="海盗把朗姆酒藏在哪里了？",a="在南边那个有围墙的海盗镇，即落帆海湾，位于西北方向那座房子的上层木箱里。",al={"斯杜雷的朗姆酒位置","货物在哪里","落帆海湾的朗姆酒"}},{q="库尔戈船长是谁？",a="就是他偷走了斯杜雷最后一批朗姆酒，并将其藏在南边那个有围墙的海盗镇里。",al={"库尔戈","库尔戈船长"}},{q="这一步在任务链中处于什么位置？",a="它是斯杜雷的债务任务之后的后续。",al={"斯杜雷的货物任务链","斯杜雷的债务之后是什么任务"}},{q="“海狼”马克基雷是谁？",a="他在藏宝海湾，和斯杜雷打赌看谁的朗姆酒更好。",al={"海狼马克基雷","藏宝海湾的马克基雷"}}},fp="17,147,17.318.0,16.84.0,14.113.0,39.149.0,35.137.0,22.102.0,38.27.0,28.90.0"}
P.entries["quest:2874"] = {n="给马克基雷的货物",s="斯杜雷递给你一瓶热砂港舱底朗姆酒，让你带给藏宝海湾的“海狼”马克基雷，好让他彻底打消对藏宝海湾酒类的执念。",h="斯杜雷递给你一瓶热砂港舱底朗姆酒，让你带给藏宝海湾的“海狼”马克基雷，好让他彻底打消对藏宝海湾酒类的执念。",kw={"藏宝海湾","马克基雷","“海狼”马克基雷","热砂港舱底朗姆酒","斯杜雷","斯杜雷的债务","斯杜雷的货物","塔纳利斯"},sec={{t="送酒任务",b="在你帮忙运送了货物之后，斯杜雷给了你一瓶热砂港舱底朗姆酒。你得把它送到藏宝海湾的马克基雷手里，这样他终于可以放弃他那关于当地酒水的疯狂想法了。"},{t="马克基雷的定论",b="马克基雷尝了尝朗姆酒，对这种糟糕透顶的味道感到难以置信，这让他很高兴。斯杜雷信守了他关于舱底朗姆酒的诺言，所以他不必再支付欠款。马克基雷称这东西浓得像砂砾，喝起来像岩浆一样灼烧。"}},faq={{q="谁给了你这瓶酒？",a="热砂港的斯杜雷。",al={"谁开启了送酒给马克基雷的任务","送酒给马克基雷的任务发布者"}},{q="谁接收这瓶朗姆酒？",a="藏宝海湾的“海狼”马克基雷。",al={"我该把酒带到哪里","谁收到了朗姆酒","马克基雷的位置"}},{q="运送的是哪种酒？",a="一瓶热砂港舱底朗姆酒。",al={"这是什么朗姆酒","斯杜雷给了什么酒"}},{q="这一步在任务链中处于什么位置？",a="它紧接在“斯杜雷的债务”和“斯杜雷的货物”之后。",al={"送酒给马克基雷之前是什么任务","送酒给马克基雷的任务链"}}},fp="20,160,17.192.0,19.193.1,25.49.0,31.57.0,40.35.0,38.49.0"}
P.entries["quest:2875"] = {n="通缉：安德雷·费尔比德",s="加基森和热砂港的一张悬赏通告点名了海盗安德雷·火须，他被控犯下了针对热砂财团和加基森的罪行。通告声明，将其头颅送至热砂港的安全主管吉罗姆·比格维兹处，即视为一份具有约束力的合同。",h="加基森和热砂港的一张悬赏通告点名了海盗安德雷·火须，他被控犯下了针对热砂财团和加基森的罪行。通告声明，将其头颅送至热砂港的安全主管吉罗姆·比格维兹处，即视为一份具有约束力的合同。",kw={"安德雷·火须","比格维兹","加基森","海盗据点","热砂港","塔纳利斯","悬赏海报"},sec={{t="法令",b="这张通告称安德雷·火须是一个卑劣的海盗，被控犯下了针对热砂财团和加基森的罪行。执政议会已颁布法令，任何阅读此通告的人均可使用致命武力来抓捕安德雷及其同伙。他就在热砂港沿海岸向南走一段路的海盗据点内，站在围墙内的一处篝火旁。"},{t="作为代理的头颅",b="另一条法令指出，如果安德雷死亡或在审讯时无法到场，他的头颅可以作为他的代理。将其送至热砂港的安全主管吉罗姆·比格维兹处，即视为一份具有约束力的合同。"},{t="付款条款",b="比格维兹很高兴安德雷终究还是会出席他的审判。当你签名后就会发放报酬，比格维兹挥挥手说那些小字条款无伤大雅，还补充说它们太小了，用放大镜也看不清。"}},faq={{q="谁是安德雷·火须？",a="一名被控犯下针对热砂财团和加基森罪行的海盗。",al={"安德雷·火须","谁是安德雷","火须 塔纳利斯"}},{q="哪里可以找到悬赏通告？",a="在加基森和热砂港。",al={"任务起始点","悬赏海报位置","悬赏安德雷·火须海报"}},{q="安德雷·火须在哪里？",a="在热砂港沿海岸向南走一段路的海盗据点，围墙内的一处篝火旁。",al={"火须位置","火须在哪里","寻找安德雷·火须"}},{q="处理掉安德雷后，谁负责接收头颅？",a="热砂港的安全主管吉罗姆·比格维兹。",al={"向谁上交火须","比格维兹位置","火须头颅上交处"}},{q="为什么需要他的头颅？",a="根据法令，如果他在审讯时死亡或无法到场，头颅可以作为他的代理。",al={"为什么需要头颅","头颅作为代理","审判代理"}}},fp="23,227,10.338.0,17.205.0,16.193.1,23.81.0,37.66.0,33.117.0,47.67.0,25.100.0"}
P.entries["quest:2876"] = {n="船运时刻表",s="一份卷轴记录了在热砂港和藏宝海湾之间航行的船只，其中一些航程旁边有标记。它应该交到热砂港的一位负责人手中。",h="一份卷轴记录了在热砂港和藏宝海湾之间航行的船只，其中一些航程旁边有标记。它应该交到热砂港的一位负责人手中。",kw={"比格维兹","藏宝海湾","海盗","船只时刻表","热砂港","塔纳利斯"},sec={{t="这卷卷轴",b="卷轴列出了往返于热砂港和藏宝海湾之间的货运船只，包括已完成和将要进行的航次，以及船只的名称。有些航程旁边打了个大大的叉，另一些则写着关于战利品或激烈战斗的笔记。这份卷轴是给热砂港的一位负责人的。"},{t="港口的反应",b="安全主管吉罗姆·比格维兹发现时刻表上的日期和时间十分准确，并担心海盗船长会利用它做出什么事来。在听说你是从海盗手中夺取它之后，比格维兹称这是一个令人不安的消息，他感谢了你，并对海盗已死感到高兴。"}},faq={{q="时刻表上写了什么？",a="往返于热砂港和藏宝海湾之间的船名及航行时间，包括过去和未来的航次，一些航程旁边有大大的叉号，另一些旁边则有关于战利品或激烈战斗的注释。",al={"船只时刻表写了什么","船只时刻表文本","货运备注"}},{q="谁需要看这份文件？",a="热砂港的一位负责人。安全主管吉罗姆·比格维兹就是接收它的人。",al={"我该把时刻表交给谁","船只时刻表上交","时刻表交到哪里"}}},fp="14,111,10.289.0,19.279.1,32.185.0,31.99.0"}
P.entries["quest:2877"] = {n="清理隐匿石",s="来自鹰巢山的弗拉加尔需要一支清理小队去清理隐匿石周围的区域，部落弃守了那里，现在那里已被淤泥怪和软泥怪占领了。蛮锤部族计划在清理干净后利用那片区域。",h="来自鹰巢山的弗拉加尔需要一支清理小队去清理隐匿石周围的区域，部落弃守了那里，现在那里已被淤泥怪和软泥怪占领了。蛮锤部族计划在清理干净后利用那片区域。",kw={"鹰巢山","弗拉加尔","绿色淤泥怪","辛特兰","翡翠软泥怪","隐匿石","蛮锤部族"},sec={{t="领土问题",b="比起铁炉堡的兄弟，蛮锤部族更铭记过去。弗拉加尔说，在这里，通过亲力亲为才能赢得友谊。部落弃守了他们在辛特兰隐匿石周围的据点，如今那里已经被恶心的淤泥怪和软泥怪占领了。蛮锤部族对那块土地另有打算，但首先得先清理掉那些滋生的怪物。"},{t="清理地面",b="击杀十只绿色淤泥怪和十只翡翠软泥怪，然后向在鹰巢山等待的弗拉加尔汇报。"}},faq={{q="弗拉加尔是谁？",a="弗拉加尔是位于辛特兰鹰巢山的一名蛮锤矮人，他希望清理隐匿石。",al={"谁发布隐匿石清理任务","弗拉加尔"}},{q="为什么蛮锤部族想要清理隐匿石？",a="部落弃守了他们在隐匿石周围的阵地，被淤泥怪和软泥怪占领了。蛮锤部族对该区域有计划，但首先需要一支清理小队。",al={"为什么要杀死软泥怪","蛮锤部族隐匿石计划"}},{q="什么生物栖息在隐匿石？",a="绿色淤泥怪和翡翠软泥怪已经占领了那里旧的部落阵地。",al={"隐匿石怪物","隐匿石有什么"}},{q="为什么弗拉加尔要提到铁炉堡？",a="弗拉加尔说，比起铁炉堡的兄弟，蛮锤部族更铭记过去，并且在这里，通过亲力亲为才能赢得友谊。",al={"蛮锤部族与铁炉堡的区别","弗拉加尔与铁炉堡"}}},fp="19,173,21.348.0,19.97.0,29.100.0,47.172.0,35.80.0,36.147.0"}
P.entries["quest:2879"] = {n="艾奎尼克斯法杖",s="特洛亚斯·月风认为他的法杖可能是艾奎尼克斯法杖，那是鸦风废墟中一座纪念碑的钥匙。为了查明真相，你需要收集在那片废墟中仍在燃烧的四团火焰的精华。",h="特洛亚斯·月风认为他的法杖可能是艾奎尼克斯法杖，那是鸦风废墟中一座纪念碑的钥匙。为了查明真相，你需要收集在那片废墟中仍在燃烧的四团火焰的精华。",kw={"拜尔坦","梦境之树","艾奎尼克斯巨石","菲拉斯","伊姆贝尔","拉哈萨","鸦风废墟","萨姆哈","艾奎尼克斯法杖","特洛亚斯·月风"},sec={{t="巨石之匙",b="当你回到特洛亚斯·月风身边时，他说他的法杖可能是艾奎尼克斯法杖，这实际上是艾奎尼克斯巨石的钥匙。那座巨石耸立在鸦风废墟中。在这些废墟里，有四团火焰仍在燃烧，分别是萨姆哈、伊姆贝尔、拜尔坦和拉哈萨。每团火焰都能提供一种精华，你需要站在巨石旁使用这四种精华来为法杖充能。如果它确实是艾奎尼克斯法杖，巨石就会打开，并显露出一件神圣的宝物。"},{t="在巨石旁",b="充能后的法杖几乎令人无法握持，强大的力量在你体内轰鸣。你触碰巨石冰冷的表面，一扇小门随之开启，让你得以取出里面的东西。光束从巨石周围倾泻而出。"}},faq={{q="艾奎尼克斯巨石位于哪里？",a="在大陆上梦境之树的西面，鸦风废墟里。",al={"艾奎尼克斯巨石位置","巨石在哪里","寻找艾奎尼克斯巨石"}},{q="我需要哪四团火焰？",a="萨姆哈、伊姆贝尔、拜尔坦和拉哈萨，这些火焰仍在鸦风废墟中燃烧。你需要收集每团火焰的精华。",al={"四团火焰","菲拉斯的火焰名称","鸦风废墟的火焰"}},{q="艾奎尼克斯法杖有什么用？",a="特洛亚斯·月风说它是开启艾奎尼克斯巨石的钥匙，里面藏有一件神圣的宝物。",al={"法杖有什么用","艾奎尼克斯法杖的用途","为什么要为法杖充能"}},{q="我在哪里为法杖充能？",a="站在艾奎尼克斯巨石旁，使用那四团火焰的精华。",al={"在哪里使用精华","充能法杖的位置"}}},fp="20,169,22.341.0,12.217.1,38.95.0,32.132.0,33.112.0,30.90.0"}
P.entries["quest:288"] = {n="第三舰队",s="在大副菲兹莫斯坐在米奈希尔港深水旅店外，用矮人蜜酒浇愁。他是库尔提拉斯第三舰队唯一的幸存者，这支骄傲的海军舰队在第二次战争期间被兽人奴役的红龙在湿地海岸外焚毁。",h="在大副菲兹莫斯坐在米奈希尔港深水旅店外，用矮人蜜酒浇愁。他是库尔提拉斯第三舰队唯一的幸存者，这支骄傲的海军舰队在第二次战争期间被兽人奴役的红龙在湿地海岸外焚毁。",kw={"深水旅店","末日舰队","龙喉氏族","菲兹莫斯","库尔提拉斯","米奈希尔港","红龙","第三舰队","波浪女王号","湿地"},ang={["faction:Alliance"]="听到菲兹莫斯讲述“波浪女王号”的陨落，让联盟的保卫者们回想起部落的骑龙者在卡兹莫丹留下的持久伤痕。",["race:Dwarf"]="格瑞姆巴托的阴影笼罩着整个卡兹莫丹，在其深处繁育的巨龙对矮人的土地和人类盟友都造成了巨大的破坏。",["race:Human"]="第三舰队的覆灭是一个苦涩的提醒，让人想起库尔提拉斯和联盟对抗龙喉氏族时所进行的一场场灾难性的海战。"},sec={{t="水手的悲伤",b="大副菲兹莫斯整日瘫坐在米奈希尔港深水旅店外，饱受宿醉和挥之不去的记忆折磨。他曾经是隶属于库尔提拉斯海上旗帜的一艘战列舰“波浪女王号”上的军官，如今却用痛苦的记忆换取一瓶瓶矮人蜜酒。任何愿意请他喝酒的人，都能听到他讲述关于第二次战争中最具毁灭性的海军屠杀之一的亲身经历。"},{t="波浪之上的烈火",b="第二次战争期间，第三舰队航行在卡兹莫丹的海岸线上，灾难从天而降。龙喉氏族在格瑞姆巴托奴役了红龙军团，对毫无防备的战舰喷吐龙火。菲兹莫斯回忆起木质船壳在滔天烈焰下无助地燃烧，将整船船员拖入深渊。菲兹莫斯独自幸存并被冲上岸，留下了他那陨落的战友们在那片如今被称为“末日舰队”的水下坟场中。"}},faq={{q="谁是大副菲兹莫斯？",a="他是一位坐在米奈希尔港深水旅店外借酒消愁的老水手。他曾是库尔提拉斯战舰“波浪女王号”的大副，也是第三舰队覆灭后已知的唯一幸存者。",al={"菲兹莫斯","喝醉的水手是谁","菲兹莫斯 旅店"}},{q="第三舰队遭遇了什么？",a="库尔提拉斯的第三舰队在第二次战争期间，于湿地海岸外遭到伏击并被焚毁。来自龙喉氏族的骑龙兽人从天而降喷吐烈火，将舰队的船只和水手送入了海底。",al={"第三舰队的命运","舰队是如何沉没的","库尔提拉斯船只沉没"}},{q="为什么龙会攻击人类船只？",a="第二次战争期间，龙喉氏族在附近的格瑞姆巴托利用恶魔之魂奴役了红龙女王阿莱克丝塔萨。在黑暗魔法的束缚下，红龙被迫成为部落的恐怖坐骑和攻城武器。",al={"龙喉氏族的巨龙","湿地的红龙","为什么兽人骑龙"}},{q="船只到底沉没在哪里？",a="烧焦的残骸沉没在湿地西海岸，米奈希尔港以北的水域，这片悲惨的区域如今被称为“末日舰队”。",al={"末日舰队在哪里","湿地沉船地点","第三舰队残骸"}},{q="菲兹莫斯想要什么饮料？",a="他需要一壶矮人蜜酒来打开话匣子，并缓解他剧烈的宿醉，这可以直接从深水旅店内的旅店老板那里买到。",al={"菲兹莫斯 蜜酒","菲兹莫斯想要什么","一壶蜜酒"}},{q="第三舰队隶属于哪个国家？",a="这支舰队属于库尔提拉斯，这个岛屿海洋王国强大的海军在第二次战争期间是联盟海军力量的支柱。",al={"第三舰队是暴风城的吗","库尔提拉斯舰队","谁拥有波浪女王号"}}},fp="15,166,16.342.0,19.450.0,30.241.0,33.197.0,39.218.0,34.141.0,33.148.0,38.147.0"}
P.entries["quest:2880"] = {n="巨魔部族项链",s="鹰巢山的弗拉加尔坚持认为，蛮锤部族不隶属于任何联盟，并且只以行事来衡量他人。从辛特兰的巨魔身上收集五条部落项链，对你而言会是一个好的开始。",h="鹰巢山的弗拉加尔坚持认为，蛮锤部族不隶属于任何联盟，并且只以行事来衡量他人。从辛特兰的巨魔身上收集五条部落项链，对你而言会是一个好的开始。",kw={"鹰巢山","悬赏","弗拉加尔","辛特兰","巨魔部落项链","巨魔","蛮锤"},sec={{t="赢得蛮锤的尊重",b="弗拉加尔不喜欢空谈，他明确表示蛮锤部族是独立的。任何希望与他们交朋友的人都必须首先证明自己的价值。在辛特兰山坡上游荡的巨魔有时会佩戴部落项链，将其中五条带给鹰巢山的弗拉加尔，便是一个好的开始。"}},faq={{q="弗拉加尔为什么想要巨魔项链？",a="弗拉加尔凭行动而非言语来评判他人，并表示对于任何寻求蛮锤友谊的人来说，五条项链是一个好的开始。",al={"为什么要巨魔项链","巨魔项链悬赏目的","弗拉加尔为什么要项链"}},{q="蛮锤部族是联盟的一部分吗？",a="弗拉加尔坚称他们不是。蛮锤部族是独立的，并且通过行动和作为来评判他人。",al={"蛮锤部族是联盟吗","鹰巢山属于联盟吗","蛮锤部族立场"}},{q="在哪里可以找到巨魔部落项链？",a="据说在辛特兰山坡上游荡的巨魔偶尔会携带这些项链。",al={"哪里获取巨魔部落项链","巨魔项链位置","如何获得巨魔项链"}},{q="我该把项链交给谁？",a="将五条项链交给鹰巢山的弗拉加尔。",al={"谁需要巨魔项链","弗拉加尔交任务","弗拉加尔在哪里"}}},fp="21,105,25.294.0,52.139.0,41.105.0,42.74.0,33.64.0"}
P.entries["quest:2881"] = {n="巨魔部族项链",s="身为蛮锤部族一员的弗拉加尔已经从你这里收过一次巨魔部族项链作为赏金。只要你每次带回五个，这个赏金任务就一直有效。",h="身为蛮锤部族一员的弗拉加尔已经从你这里收过一次巨魔部族项链作为赏金。只要你每次带回五个，这个赏金任务就一直有效。",kw={"弗拉加尔","辛特兰","部族项链","巨魔项链赏金","巨魔","蛮锤部族"},sec={{t="长期有效的赏金",b="弗拉加尔提醒你，虽然第一次上交已经完成，但只要你找到更多的巨魔部族项链，随时欢迎上交。弗拉加尔说，凡是为蛮锤部族而战的人，蛮锤部族也会反过来为他们而战。弗拉加尔只会在凑齐五个项链时才算作一批。"},{t="弗拉加尔的认可",b="交货时，弗拉加尔显得很高兴，他将这些项链视为你愿意干脏活累活的证明。弗拉加尔说，这种意愿在蛮锤部族中是备受推崇的。"}},faq={{q="谁需要巨魔部族项链？",a="弗拉加尔，他以蛮锤部族一员的身份发言。",al={"谁发布了这个赏金","弗拉加尔的角色","谁负责接收项链"}},{q="需要多少条巨魔部族项链？",a="一次五个。弗拉加尔说必须要有五个才算数。",al={"项链数量","多少条项链","赏金要求"}},{q="为什么弗拉加尔要收集这些项链？",a="弗拉加尔将它们视为愿意为蛮锤部族而战的标志，并表示这样做的人会发现蛮锤部族也愿意为他们而战。",al={"为什么要巨魔项链","蛮锤部族的动机","赏金的目的"}},{q="在此赏金任务之前有什么？",a="第一次巨魔项链赏金任务，你已经为弗拉加尔完成了。",al={"前置任务","上一步骤","之前的赏金"}}},fp="21,164,16.213.0,18.159.1,37.49.0,43.73.0,55.130.0,29.80.0"}
P.entries["quest:289"] = {n="被诅咒的船员",s="大副菲兹莫斯是库尔提拉斯第三舰队唯一的幸存者，他恳求人们怜悯他那些迷失的兄弟。这些溺亡的水手和海军陆战队员被困在湿地海岸外沉船上隐藏的一件神秘遗物中，他们作为不得安息的亡灵在残骸中徘徊。",h="大副菲兹莫斯是库尔提拉斯第三舰队唯一的幸存者，他恳求人们怜悯他那些迷失的兄弟。这些溺亡的水手和海军陆战队员被困在湿地海岸外沉船上隐藏的一件神秘遗物中，他们作为不得安息的亡灵在残骸中徘徊。",kw={"被诅咒的船员","被诅咒的海军陆战队员","被诅咒的水手","菲兹莫斯","库尔提拉斯","米奈希尔","斯涅利格","鼻烟盒","第三舰队","湿地"},ang={["class:Paladin"]="第三舰队的水手们是无辜的，他们被一件邪恶的遗物所困；让他们安息可以净化亵渎之举，并为黑暗的水域带来光明。",["faction:Alliance"]="库尔提拉斯长期以来一直为大联盟提供最优秀的水手；让他们受折磨的灵魂安息，是任何联盟冒险者应尽的庄严职责。",["race:Human"]="人类旅行者能感受到与这些落难水手的兄弟情谊，并认可库尔提拉斯王国共享的海军传统。"},sec={{t="不安的舰队",b="当库尔提拉斯第三舰队在米奈希尔港北部的参差海岸触礁沉没时，它们的悲剧并没有随着沉入海底而结束。虽然大副菲兹莫斯设法活着游上了岸，但他其他的船员却遭遇了比死亡更可怕的命运。隐藏在其中一艘船壳深处的一件神秘而可怕的宝藏，向垂死的水手们释放了诡异的魔法，将他们的灵魂束缚在被海水冲刷的船体上，使他们无法得到死亡的安宁。"},{t="刀锋下的慈悲",b="菲兹莫斯徘徊在米奈希尔港的酒馆里，每晚都受到他昔日船友呻吟和哭喊的困扰。他相信终结这些行尸走肉的生命能给他们带来解脱，于是他派遣冒险者深入腐烂、溺水的沉船，去击倒那些被诅咒的水手、经验丰富的海军陆战队员，以及他昔日的同僚大副斯涅利格，并找回斯涅利格的鼻烟盒，作为他的朋友终于获得安息的沉重证明。"}},faq={{q="大副斯涅利格是谁？",a="大副斯涅利格曾与大副菲兹莫斯一同在命运多舛的库尔提拉斯第三舰队服役。在舰队于湿地北海岸失事后，斯涅利格与其他船员一起溺水身亡，随后被藏在船上的邪恶遗物复活。如今，他作为亡灵怪物徘徊在其中一艘沉船被洪水淹没的货舱里。",al={"斯涅利格","大副斯涅利格","斯涅利格是谁"}},{q="为什么水手和海军陆战队员会被诅咒？",a="据菲兹莫斯所说，舰队中的一艘船载有一件隐藏的邪恶宝藏。当船只在海岸边失事时，这件神器的黑暗能量将溺亡船员的灵魂束缚在腐烂的船壳上，阻止了他们的灵魂超度，并将他们强行禁锢在亡灵的折磨中。",al={"为什么他们是亡灵","第三舰队诅咒","被诅咒的水手起因"}},{q="沉船在哪里？",a="第三舰队的沉船残骸位于湿地北部的离岸水域，米奈希尔港的北边。被诅咒的船员在被淹没的甲板和周围的水域中游荡，斯涅利格本人则潜伏在南部沉船破裂的船壳内。",al={"船在哪里","沉船位置","斯涅利格在哪里"}},{q="为什么菲兹莫斯想要斯涅利格的鼻烟盒？",a="鼻烟盒是大副斯涅利格生前的一件私人纪念品。把它带回给菲兹莫斯，可以作为切实的证据，证明他那被诅咒的同伴终于从海浪下腐烂的监狱中得到了解脱。",al={"斯涅利格的鼻烟盒","鼻烟盒","为什么是鼻烟盒"}},{q="大副菲兹莫斯是谁？",a="菲兹莫斯是一名库尔提拉斯水手，也是第三舰队唯一已知的生还者。他被悲伤和内疚所击垮，留在了米奈希尔港，被溺亡兄弟的噩梦所困扰，绝望地寻找愿意结束他们痛苦的旅行者。",al={"菲兹莫斯","大副菲兹莫斯"}},{q="杀死船员真的能打破诅咒吗？",a="击倒水手和海军陆战队员只能让他们不得安息的灵魂获得暂时的喘息，但这并不能完全打破诅咒。诅咒的根源仍然与隐藏在残骸上的那件神秘遗物紧密相连。",al={"诅咒解除了吗","这能结束诅咒吗"}}},fp="15,293,16.325.0,18.439.1,27.291.0,39.259.0,35.231.0,45.180.0,30.236.0,47.205.1"}
P.entries["quest:29"] = {n="湖中试炼",s="月神湖试炼是月光林地举办的一项限时挑战，旨在测试初学者的身体敏捷度和速度。挑战者必须潜入月神湖获取一枚不稳定的神殿灵珠，并在它消散之前将其带到雷姆洛斯神殿。成功完成试炼将获得守望者塔加里的认可，并向塞纳里奥议会对平衡的奉献致敬。",h="月神湖试炼是月光林地举办的一项限时挑战，旨在测试初学者的身体敏捷度和速度。挑战者必须潜入月神湖获取一枚不稳定的神殿灵珠，并在它消散之前将其带到雷姆洛斯神殿。成功完成试炼将获得守望者塔加里的认可，并向塞纳里奥议会对平衡的奉...",kw={"塞纳里奥议会","月神湖","月光林地","雷姆洛斯","神殿灵珠","雷姆洛斯神殿","塔加里","月神湖试炼"},ang={["class:Druid"]="这项试炼测试德鲁伊必备的敏捷与应变能力，是月光林地向守护者雷姆洛斯致敬的成人礼。"},sec={{t="敏捷测试",b="月神湖试炼是由月光林地的守护者们监督的一项入门仪式。挑战者需要潜入月神湖平静的水域，寻回静置在沉入湖底的精致神殿灵珠。由于灵珠在离开存放处后会迅速衰变，这项试炼要求参与者具备敏锐的身体协调性、敏锐的感知力，并能在其魔力消散前将其快速送达目的地。"},{t="向守护者致敬",b="获取灵珠后，奔跑者必须赶往月光林地西北部的雷姆洛斯神殿。这座纪念碑是为守护者雷姆洛斯树立的永恒丰碑，他指引着塞纳里奥议会致力于维护自然与世界的平衡。在神殿激活灵珠是对议会内部重要性的一种仪式性认可。在那里，值得信赖的守望者塔加里会迎接成功克服试炼时间限制与竞争的初学者。"}},faq={{q="什么是月神湖试炼？",a="月神湖试炼是在月光林地进行的一项敏捷与专注力的测试。初学者需要潜入月神湖冰冷的深处取回一枚会衰变的神殿灵珠，并在其能量消散前将其带到避难所的雷姆洛斯神殿。",al={"什么是月神湖试炼","月神湖试炼的目的","这是什么任务"}},{q="雷姆洛斯神殿在哪里？",a="雷姆洛斯神殿位于月光林地西北部。它致力于纪念守护者雷姆洛斯及其对塞纳里奥议会的指引，由守望者塔加里负责守护和维护。",al={"雷姆洛斯神殿在哪里","神殿位置","月光林地雷姆洛斯神殿"}},{q="塔加里是谁？",a="塔加里是月光林地值得信赖的守望者之一，负责照看雷姆洛斯神殿。她监督月神湖试炼的完成情况，并欢迎那些带来灵珠以向神殿致敬的初学者。",al={"塔加里是谁","月光林地塔加里","神殿守望者塔加里"}},{q="什么是神殿灵珠？",a="神殿灵珠是从月神湖湖底取回的圣物。它一旦离开水面就会迅速衰变，需要携带者迅速奔跑，将其送往雷姆洛斯神殿激活，以此作为祭品。",al={"什么是神殿灵珠","为什么灵珠会衰变","神殿灵珠的用途"}},{q="为什么要在该神殿供奉守护者雷姆洛斯？",a="守护者雷姆洛斯是一位受人尊敬的林地守护者，他指引塞纳里奥议会维护自然与世界的平衡。位于月光林地西北部的神殿是他领导力与原则的永恒象征。",al={"守护者雷姆洛斯是谁","雷姆洛斯相关传说","为什么要向雷姆洛斯致敬"}},{q="在神殿供奉灵珠有什么意义？",a="在雷姆洛斯神殿激活灵珠是对塞纳里奥议会所维护的神圣平衡的致敬，也是对该神殿在月光林地内长久精神重要性的认可。",al={"使用灵珠有什么效果","为什么要在大神殿激活灵珠"}}},fp="17,295,19.299.0,21.340.0,30.252.0,39.157.0,15.173.0,24.216.0,45.199.0,52.184.0"}
P.entries["quest:290"] = {n="解除诅咒",s="大副菲兹莫斯认为，他那些落难船员身上所缠绕的无法安息的诅咒，源自他们沉没的船只“无畏号”上所封存的一件黑暗圣物。为了让他的弟兄们得到解脱，冒险者必须面对哈林多尔船长的鬼魂，夺取保险箱钥匙，并从沉没的船体中找回这件遗物。",h="大副菲兹莫斯认为，他那些落难船员身上所缠绕的无法安息的诅咒，源自他们沉没的船只“无畏号”上所封存的一件黑暗圣物。为了让他的弟兄们得到解脱，冒险者必须面对哈林多尔船长的鬼魂，夺取保险箱钥匙，并从沉没的船体中找回这件遗物。",kw={"哈林多尔船长","菲兹莫斯","戈罗林·钢眉","无畏号","解除诅咒","米奈希尔港","保险箱","第三舰队","湿地"},ang={["class:Priest"]="解开精神上的苦难并净化被玷污的遗物需要属灵的权威，这就是为什么菲兹莫斯将保险箱内物品的最终净化工作托付给圣职者的原因。",["faction:Alliance"]="第三舰队的水手们生前效忠于联盟，让他们饱受折磨的灵魂安息是每一位途径米奈希尔港的联盟勇士应尽的荣誉义务。"},sec={{t="船长的重担",b="大副菲兹莫斯在第三舰队那场悲剧性的命运中幸存了下来，但他战友们的记忆时刻困扰着他的清醒时刻和梦境。他始终坚信，缠绕着他船员们的亡灵诅咒与锁在他那艘旧船“无畏号”保险箱里的一件神秘而邪恶的物体有关。哈林多尔船长的幽灵残骸依然在守护着这艘沉船，即使死后，他依然顽固地守护着这艘船最深层秘密的钥匙。"},{t="开启深渊",b="在湿地北部雾气缭绕的海岸外，散落着第三舰队残破的船骸。在“无畏号”被淹没的船体内，这艘船紧锁的保险箱里装着导致船员们痛苦不堪的核心遗物。要取回它，必须在甲板上击败哈林多尔那饱受折磨的鬼魂，拿到生锈的钥匙，并闯入被水淹没的内部，取回这件黑暗圣物，以便让神圣之手将其净化。"}},faq={{q="在这个任务中，你要搜索的是哪艘船？",a="你要搜索的是“无畏号”，也就是第三舰队那艘沉没在湿地西北海岸外的船只。",al={"哪艘船","无畏号沉船","保险箱在哪里"}},{q="哈林多尔船长是谁？",a="哈林多尔船长曾是“无畏号”的指挥官。死后，他那不得安息的灵魂徘徊在废弃船只的甲板上，顽固地紧握着保险箱的钥匙。",al={"哈林多尔是谁","哈林多尔船长背景故事"}},{q="为什么大副菲兹莫斯想要打开保险箱？",a="菲兹莫斯认为保险箱内锁着一件被诅咒的物体，正是它导致他船员们的灵魂陷入无尽的折磨，打开它是找回该圣物并将其净化的唯一途径。",al={"菲兹莫斯的目标","为什么打开保险箱","任务目的"}},{q="“无畏号”的保险箱在哪里？",a="保险箱位于“无畏号”下层船舱内部，已被水淹没，可以通过沉船侧面海浪下的破洞进入。",al={"保险箱位置","箱子在哪里","如何找到保险箱"}},{q="找到被诅咒的物体后，谁能净化它？",a="菲兹莫斯指示冒险者将找回的物体带给米奈希尔港的矮人牧师戈罗林·钢眉，以洗净其污秽。",al={"谁来净化遗物","戈罗林·钢眉是谁","把诅咒之物带给谁"}},{q="当初是什么导致了这艘船沉没？",a="在第二次战争期间，第三舰队遭到了兽人操控的红龙攻击，船只在湿地海岸外被烧毁并沉没；船上载着的被诅咒的财宝让溺亡的船员们无法安息。",al={"第三舰队如何沉没","第三舰队沉没原因"}}},fp="17,204,18.297.0,20.314.1,46.101.0,24.128.0,58.167.0,42.131.0,55.126.0,45.193.0"}
P.entries["quest:2902"] = {n="调查木爪岭",s="哈杜肯·迅蹄确信木爪豺狼人遵循着某种成文的战略。他派遣你去莫沙彻营地南部的豺狼人营地搜寻任何类似作战计划的东西。",h="哈杜肯·迅蹄确信木爪豺狼人遵循着某种成文的战略。他派遣你去莫沙彻营地南部的豺狼人营地搜寻任何类似作战计划的东西。",kw={"作战地图","作战计划","莫沙彻营地","菲拉斯","豺狼人","哈杜肯·迅蹄","木爪部族"},sec={{t="搜寻计划",b="此任务在“阿尔法打击”之后。哈杜肯对豺狼人的智商没什么好感，但他确信他们保留了某种战略记录，因为他们最近的袭击行动协调得太过完美，不像是临时起意。如果他能看到那些计划，就能更好地理解是什么激怒了他们。他派遣你回到木爪部族，去寻找任何看起来像是作战计划的东西并带给他。"},{t="地图显示了什么",b="这张地图确实是哈杜肯想要的。上面的箭头可能显示了部队的动向，但大多数都指向南方，远离北部的莫沙彻营地。地图的其他地方画着一个你认为是巨大昆虫的图案，下面有刻痕，或许是豺狼人遭到未知虫子袭击的损失计数。"}},faq={{q="是谁派遣你去调查木爪豺狼人的？",a="在莫沙彻营地的哈杜肯·迅蹄。",al={"谁给予木爪调查任务","木爪调查任务发布者"}},{q="为什么哈杜肯认为豺狼人有作战计划？",a="他们的袭击协调得太过完美，不像是临时起意，因此哈杜肯推断必然有一份成文的战略，能揭示是什么让他们如此躁动不安。",al={"为什么豺狼人会有计划","木爪部族战略"}},{q="作战计划在哪里？",a="在莫沙彻营地南部的豺狼人营地中。",al={"木爪部族计划在哪里","哪里寻找木爪作战地图"}},{q="“木爪调查”之前的任务是什么？",a="“阿尔法打击”是此任务前的一步。",al={"木爪调查之前的任务","木爪任务链前置条件"}}},fp="21,153,18.373.0,18.259.1,48.81.0,54.151.0,35.64.0,39.44.0"}
P.entries["quest:2903"] = {n="作战计划",s="你拿到了豺狼人的作战计划。接下来要做的就是把它们带回莫沙彻营地的哈杜肯·迅蹄那里，或许他或营地里的其他人能弄明白这些豺狼人到底想干什么。",h="你拿到了豺狼人的作战计划。接下来要做的就是把它们带回莫沙彻营地的哈杜肯·迅蹄那里，或许他或营地里的其他人能弄明白这些豺狼人到底想干什么。",kw={"作战计划","莫沙彻营地","菲拉斯","豺狼人","哈杜肯·迅蹄","木爪"},sec={{t="返回莫沙彻营地",b="在“木爪调查”之后，你拿到了木爪作战计划，现在唯一剩下的步骤就是将其交还给营地里的哈杜肯·迅蹄。哈杜肯一直在寻找豺狼人意图的切实证据。"},{t="哈杜肯的解读",b="哈杜肯说这正是他们所需要的。大部分潦草的字迹他都看不懂，但他见过足够多的作战计划，足以读懂目前的局势：豺狼人在两线作战。营地是其中一条战线，但它们的主力正对准南方的某个敌人。他感觉到这一切背后还有更大的阴谋，并认为现在是时候搞清楚那个第二个敌人是谁了。"}},faq={{q="这些作战计划需要送到哪里？",a="送到莫沙彻营地的哈杜肯·迅蹄那里。",al={"谁来接收计划","作战计划交还地点","作战计划交还"}},{q="这一步之前发生了什么？",a="“木爪调查”，即对豺狼人计划的搜寻。",al={"前置任务","导致作战计划的任务","作战计划的前提条件"}},{q="这些作战计划是从哪里来的？",a="它们是豺狼人自己的计划，是在“木爪调查”期间于莫沙彻营地南部的豺狼人营地中搜出来的。",al={"谁制作了地图","哪些豺狼人制定了计划","木爪计划来源"}}},fp="16,121,20.159.0,17.372.1,39.55.0,27.80.0,37.113.0"}
P.entries["quest:2904"] = {n="一团混乱",s="在诺莫瑞根，你发现克努比遭到黑铁伏击后，遍体鳞伤地倒在穴居人之间。他获救后带来了丹莫罗地下钻探机的消息，这消息将被送往藏宝海湾。",h="在诺莫瑞根，你发现克努比遭到黑铁伏击后，遍体鳞伤地倒在穴居人之间。他获救后带来了丹莫罗地下钻探机的消息，这消息将被送往藏宝海湾。",kw={"藏宝海湾","发条小径","黑铁","诺莫瑞根","克努比","斯库提","超级钻探机","廷克维斯","穴居人"},ang={["faction:Alliance"]="作为联盟的一员，你得知索瑞森大帝的爪牙正在破坏联盟收复诺莫瑞根的行动。",["profession:Engineering"]="作为工程师，得知黑铁机械师正在地下建造一座庞大的超级钻探机，你或许会感到担忧。",["race:Gnome"]="作为侏儒，从诺莫瑞根受到污染的深处救出一名幸存者，是你义不容辞的责任。黑铁渗透者和狂野的穴居人正威胁着他。"},sec={{t="遍体鳞伤的幸存者",b="你在诺莫瑞根的宿舍区找到了克努比，他伤痕累累，神志不清。黑铁矮人伏击了这个地精，把他丢在狂野的穴居人之间。你带着他穿过受到污染的走廊，前往安全地带。"},{t="地下阴谋",b="克努比带来了消息，黑铁氏族正在丹莫罗地下建造一座庞大的超级钻探机。他逃离后渡海前往棘齿城，向地精工程师廷克维斯发出警告。随后，他派你南下藏宝海湾，为地精工程师斯库提送去消息。"}},faq={{q="克努比是谁？",a="克努比是一个地精，你在诺莫瑞根发现他时，他已被打得奄奄一息。在他获救之前，黑铁矮人伏击了他，把他丢在穴居人之间。",al={"克努比","克努比是谁"}},{q="必须把克努比护送到哪里？",a="你带着克努比穿过诺莫瑞根危机四伏的厅堂，前往发条小径出口和上层入口的走廊。",al={"克努比护送到哪里","护送目的地","发条小径出口"}},{q="黑铁矮人为何牵涉其中？",a="黑铁矮人正在协助设计和建造一座庞大的地下超级钻探机。克努比发现了他们的阴谋，随后遭到他们伏击。",al={"黑铁为何参与","黑铁超级钻探机","诺莫瑞根的黑铁"}},{q="克努比逃脱后去了哪里？",a="抵达安全地带后，克努比渡海前往贫瘠之地的棘齿城，警告廷克维斯，黑铁参与了地下钻探机的建造。",al={"克努比去了哪里","克努比棘齿城","廷克维斯警告"}},{q="为什么必须向藏宝海湾的斯库提报告？",a="斯库提是藏宝海湾的一名地精工程师，与廷克维斯合作研制高科技地下设备和传送器网络。",al={"为何找斯库提","藏宝海湾交任务","斯库提的关联"}},{q="这与麦克尼尔·瑟玛普拉格有什么关系？",a="斯库提知道麦克尼尔·瑟玛普拉格在诺莫瑞根内构成的威胁。帮助克努比，能为准备返回那里、对抗这个背信弃义的机械师的冒险者提供援助和补给。",al={"瑟玛普拉格的关联","对抗瑟玛普拉格"}}},fx={["73352f2e"]={q="为什么需要护送克努比出去？",a="克努比遭到黑铁矮人伏击，被打得奄奄一息，随后被丢进一间满是敌对穴居人的宿舍。他伤痕累累，被困在诺莫瑞根深处残破的厅堂里，无法独自活着抵达出口。更关键的是，他还掌握着紧急情报：他发现黑铁氏族直接参与建造一座巨大的钻探装置。只有活着逃出去，他才有机会前往棘齿城，在那台机器造成更多破坏之前警告他的伙伴廷克维斯。",al={"为什么要帮助克努比","克努比的动机","克努比为什么需要帮助"}},["9976ada5"]={q="克努比为什么无法独自逃出诺莫瑞根？",a="你发现克努比时，他已几乎失去意识，俘虏他的黑铁矮人先将他毒打一顿，又把他扔进穴居人的坑里。他遍体鳞伤、手无寸铁，虚弱得只剩一口气，没有一位有能力的冒险者保护，根本无法杀出在发条小径巡逻的辐射变异生物、失控构造体和凶暴穴居人的包围。",al={"克努比为什么需要帮手","克努比为什么无法战斗","克努比为什么选我"}}},fp="11,166,19.204.0,20.250.1,16.147.0,32.119.0,40.149.0,38.164.1,43.127.0,46.191.0"}
P.entries["quest:291"] = {n="森内尔的报告",s="森内尔·白须从卡拉诺斯向铁炉堡的参议员巴林·红石传递消息，报告霜鬃对丹莫罗的威胁。他请你不要透露他那位斥候的身份。",h="森内尔·白须从卡拉诺斯向铁炉堡的参议员巴林·红石传递消息，报告霜鬃对丹莫罗的威胁。他请你不要透露他那位斥候的身份。",kw={"巴林·红石","矮人参议院","霜鬃","王座厅","铁炉堡","卡拉诺斯","麦格尼·铜须","森内尔·白须","报告"},ang={["faction:Alliance"]="身为联盟的一员，你会看到铁炉堡的行政布局，以及影响联盟内政的官僚体系。",["race:Dwarf"]="身为矮人，当你在王座厅递交急报时，会看到麦格尼国王的王权与矮人参议院的议会权力之间的平衡。"},sec={{t="送往王都的急报",b="这份报告带来了霜鬃巨魔要塞深处的消息，那里的巨魔正威胁着丹莫罗。森内尔希望你将报告直接交给巴林·红石，并对那位来自积雪峭壁的斥候的身份保密。"},{t="王座厅中的摩擦",b="森内尔的报告送到铁炉堡王庭后，参议员巴林·红石十分恼火。他对森内尔借麦格尼国王的权威批准自己的行动感到不满。他的怒火显露出参议院对国王的法令，以及以国王名义开展的实地行动的怨怼。"}},faq={{q="森内尔·白须是谁？",a="森内尔·白须是一名矮人巡山人，驻扎在丹莫罗的卡拉诺斯附近。他负责组织侦察和军事侦察，监视侵扰矮人定居点的霜鬃巨魔。",al={"森内尔·白须","谁提供森内尔的观察报告","白须 卡拉诺斯"}},{q="参议员巴林·红石是谁？",a="巴林·红石是一位脾气乖戾、出身贵族的矮人参议员，住在铁炉堡的王座厅内，就在国王麦格尼·铜须附近。平民请愿者很容易惹恼他。",al={"巴林·红石","参议员是谁","红石 铁炉堡"}},{q="红石参议员为什么对报告感到愤怒？",a="森内尔提醒你，红石参议员的脾气很坏。送达报告时，你就会知道这位参议员为何恼火。",al={"红石为何愤怒","参议员为何大吼","参议院与麦格尼"}},{q="森内尔·白须为什么要求隐瞒你提供帮助的事？",a="森内尔·白须请你隐瞒提供帮助的事，好让上级相信是他亲自完成了艰苦的侦察。他不愿承认这些工作是由一位冒险者完成的。",al={"森内尔为何揽功","白须抢功","森内尔的秘密"}},{q="报告要送到哪里？",a="你要将报告交给铁炉堡王座厅中的参议员巴林·红石，那座宏伟的大厅是国王麦格尼·铜须处理朝政的地方。",al={"森内尔的观察报告在哪里交","巴林·红石位置","森内尔的观察报告交任务"}},{q="这个任务揭示了铁炉堡政治的哪些方面？",a="递交报告让你接触到铁炉堡的参议院，以及接收边境报告的官员。红石的反应让你得以一窥铁炉堡的政治。",al={"铁炉堡政府背景","矮人参议院背景","麦格尼与参议院"}}},fx={bde96c47={q="森内尔·白须为什么需要你送报告，而不亲自去送？",a="森内尔·白须仍驻扎在丹莫罗，负责指挥针对霜鬃巨魔等当地威胁的野外行动。更重要的是，他想让参议院和上级相信自己正不知疲倦地奋战在前线，于是把跑腿送信和面对一位脾气暴躁的参议员的苦差事留给了一个无足轻重的旅人。",al={"为什么派我送报告","森内尔为什么不自己送报告","为什么选我送报告"}}},fp="11,163,25.197.0,25.281.1,24.190.0,30.157.0,47.110.1,55.190.0,30.139.0,53.163.1"}
P.entries["quest:292"] = {n="帕雷斯之眼",s="在这个任务中，一位冒险者从被淹没的“无畏号”残骸中找回了一颗名为被诅咒的帕雷斯之眼的黑色脉动宝石。这件邪恶的遗物是应饱受折磨的水手费兹西蒙斯的请求找回的，它必须被带到米奈希尔港，以便矮人牧师戈罗林·钢眉能够预见如何净化它的枯萎诅咒。",h="在这个任务中，一位冒险者从被淹没的“无畏号”残骸中找回了一颗名为被诅咒的帕雷斯之眼的黑色脉动宝石。这件邪恶的遗物是应饱受折磨的水手费兹西蒙斯的请求找回的，它必须被带到米奈希尔港，以便矮人牧师戈罗林·钢眉能够预见如何净化它...",kw={"被诅咒的帕雷斯之眼","帕雷斯之眼","费兹西蒙斯","戈罗林·钢眉","无畏号","米奈希尔港","第三舰队","湿地"},ang={["class:Priest"]="处理像帕雷斯之眼这样的圣物所遭受的玷污，使得这次调查与圣光牧师们直接相关。",["faction:Alliance"]="第三舰队是一支联盟远征军，它的毁灭让米奈希尔港变得脆弱；找回它的遗物有助于让失去的同伴得到安息。",["race:Dwarf"]="发掘卡兹莫丹海岸附近的遗失圣物，触及了矮人致力于收回隐藏圣物的使命，并得到了铁炉堡神职人员如戈罗林·钢眉的协助。"},sec={{t="枯萎的圣物",b="在巴拉丁海湾那危机四伏的海水之下，沉船“无畏号”的锁闭强力保险箱里，静卧着一件不寻常的宝藏。箱子里装着一颗散发着令人不安光芒的黑色宝珠：帕雷斯之眼。这颗特殊的宝石并没有汇聚圣光，而是被扭曲成了一台充满苦难的机器，与第三舰队水手们那些不得安息的灵魂及厄运紧密相连。"},{t="寻求圣职的帮助",b="意识到这种黑暗魔法超出了普通打捞的范畴，这件圣物被直接带到了米奈希尔港的岸上。在那里，圣光的矮人牧师戈罗林·钢眉检查了这件异常物品。虽然他对这种圣洁的装置竟然曾属于第三舰队感到震惊，但戈罗林立刻识别出了它那不自然的腐化，并开始准备必要的仪式来消除其黑暗的影响。"}},faq={{q="什么是帕雷斯之眼？",a="帕雷斯之眼是一颗古老而强大的圣洁宝石。通常它与圣光能量相关联，但这颗特殊的宝石曾随第三舰队的沉船“无畏号”一同沉没，并已被扭曲和诅咒，散发着黑暗魔法。",al={"帕雷斯之眼背景故事","什么是帕雷斯","被诅咒的帕雷斯之眼"}},{q="帕雷斯之眼是在哪里找到的？",a="它是在湿地迷雾笼罩的海岸附近，从沉没的“无畏号”那被水淹没的残骸中的一个锁闭保险箱里找回的。",al={"在哪里可以找到眼睛","帕雷斯之眼位置","无畏号保险箱"}},{q="为什么戈罗林·钢眉关心这件圣物？",a="戈罗林·钢眉是一位驻扎在米奈希尔港的矮人牧师。作为圣光的修行者，他拥有识别古老圣物并开始打破邪恶诅咒所需仪式所需的圣职知识。",al={"谁是戈罗林·钢眉","为什么找钢眉"}},{q="费兹西蒙斯是怎么知道帕雷斯之眼的？",a="费兹西蒙斯是第三舰队的幸存者，至今仍受着那场悲剧的折磨。他因受到创伤而在米奈希尔的酒馆寻求庇护，他知道 残骸 中隐藏着这件折磨他阵亡船员的黑暗遗物。",al={"费兹西蒙斯的关联","费兹西蒙斯为什么派我去"}},{q="为什么这只眼睛会被诅咒？",a="虽然其具体的腐化原因仍与第三舰队沉船上那些超自然的死亡和挥之不去的亡灵有关，但这件圣物是在舰队沉入海底时或之后吸收了黑暗能量。",al={"为什么它被诅咒了","眼睛诅咒起源"}},{q="把这只眼睛交给戈罗林之后会发生什么？",a="戈罗林检查了被诅咒的宝石，认定它不能维持在枯萎的状态，并指导冒险者去净化圣物所受的腐化影响。",al={"后续任务","如何处理这只眼睛"}}},fp="17,199,16.272.0,22.247.1,26.191.0,28.110.0,50.174.0,40.197.0,22.215.0,44.131.1"}
P.entries["quest:2922"] = {n="拯救尖端机器人！",s="大工匠欧沃斯巴克委托联盟冒险者从诺莫瑞根受辐射的废墟中取回尖端机器人的存储器核心。这台曾经乐于助人的机械助手在城市陷落期间遭受了严重的脑部极化，导致它陷入疯狂。欧沃斯巴克希望找回它的核心能让他扭转这种损坏，并修复他心爱的创造物。",h="大工匠欧沃斯巴克委托联盟冒险者从诺莫瑞根受辐射的废墟中取回尖端机器人的存储器核心。这台曾经乐于助人的机械助手在城市陷落期间遭受了严重的脑部极化，导致它陷入疯狂。欧沃斯巴克希望找回它的核心能让他扭转这种损坏，并修复他心爱的...",kw={"诺莫瑞根","存储器核心","负电子","欧沃斯巴克","正电子","尖端机器人","侏儒区"},ang={["faction:Alliance"]="从诺莫瑞根受污染的周边地区回收有价值的失落技术，对于支持在铁炉堡避难的侏儒难民至关重要。",["profession:Engineering"]="尖端机器人的处理器从正电子到负电子的转变，对于致力于高复杂度计算矩阵的技师来说是一个警示故事。",["race:Gnome"]="对于侏儒工程师来说，尖端机器人代表了失去家园城市带来的悲剧性附带损害，证明了即使是他们最出色的智力成就也可能因灾难而扭曲。"},sec={{t="颠倒的思维",b="在诺莫瑞根遭遇灾难之前，尖端机器人是侏儒智慧的结晶。它由大工匠欧沃斯巴克设计，内置了无数小玩意和涵盖海量技术知识的知识库，以此协助研究人员工作。然而，穴居人入侵和有毒辐射泄露造成的混乱并没有放过这台机器。一阵杂散的电流冲击了尖端机器人脆弱的内部结构，使其正电子大脑完全极化，转变成了不稳定的负电子状态。"},{t="打捞行动",b="尖端机器人被困在诺莫瑞根受污染的大厅中，现在陷入了疯狂的狂乱状态，攻击视线内的任何人。尽管它发生了严重的故障，欧沃斯巴克仍拒绝将其视为废铁。他招募有能力的行动人员去追踪这台失控的机器人，从其金属底盘中取出存储器核心，并将其安全送回铁炉堡，以便大工匠能够解除极化并修复尖端机器人的思维。"}},faq={{q="尖端机器人是谁？",a="尖端机器人是大工匠欧沃斯巴克发明的一种机械助手。在诺莫瑞根陷落之前，它凭借庞大的知识数据库和内置的小玩意，协助大工匠及其同事开展工作。",al={"什么是尖端机器人","尖端机器人背景故事","欧沃斯巴克与尖端机器人"}},{q="为什么尖端机器人会变得敌对？",a="在诺莫瑞根陷落期间，一道杂散的电火花震击了尖端机器人的正电子大脑。这次冲击使其神经排列反转为负电子状态，将它乐于助人的性格变成了狂乱的暴走。",al={"为什么尖端机器人会发狂","尖端机器人发生了什么","尖端机器人极化"}},{q="在哪里可以找到尖端机器人？",a="尖端机器人在诺莫瑞根的外围走廊和大厅中徘徊，就在流亡侏儒和矮人远征军活动的防御线之外。",al={"尖端机器人在哪里","尖端机器人位置","找到尖端机器人"}},{q="谁发布了这个任务？",a="大工匠欧沃斯巴克在铁炉堡的侏儒区提供这个任务，他在那里代表大工匠格尔宾·梅卡托克监督打捞和研究工作。",al={"谁发布拯救尖端机器人大脑的任务","欧沃斯巴克位置"}},{q="尖端机器人真的能被修复吗？",a="大工匠欧沃斯巴克相信，取回尖端机器人的存储器核心将使他能够诊断出负电子极化的确切原因，并使这台机器人恢复正常工作状态。",al={"尖端机器人修好了吗","可以修复尖端机器人吗","尖端机器人幸存了吗"}},{q="归还存储器核心后会发生什么？",a="收到核心后，欧沃斯巴克立即着手准备拆解和重新配置那些颠倒的电路，尽管在他那杂乱的工作室里找到合适的工具本身就是一项挑战。",al={"尖端机器人任务结局","上交尖端机器人核心"}}},fx={e9c625cc={q="工匠大师欧沃斯巴克为什么要挽救尖端机器人的大脑？",a="尖端机器人是工匠大师欧沃斯巴克引以为傲的造物，曾凭借庞大的知识储备和实用的小装置为他和其他发明家效力。诺莫瑞根沦陷时，一股异常电流改变了这台自动机械正电子大脑的极性，使其变为负电子状态，导致它陷入疯狂。欧沃斯巴克不愿放弃自己的造物，希望通过研究核心修复损伤，让自己的助手恢复正常。",al={"欧沃斯巴克的动机","为什么要挽救尖端机器人","欧沃斯巴克为什么想要尖端机器人"}},["6f8a4042"]={q="尖端机器人的存储器核心有什么用？",a="存储器核心保存着尖端机器人的数字化思维和积累的知识。由于这台自动机械的正电子大脑在诺莫瑞根沦陷时发生了极性反转，只有取出这个部件，才能检查极性变化，并尝试重新编程或重建这位机械助手。",al={"尖端机器人的存储器核心","存储器核心有什么用"}}},fp="21,341,15.420.0,17.407.0,15.180.0,31.187.0,27.146.0,21.136.0,30.153.0,45.182.1"}
P.entries["quest:2923"] = {n="工匠大师欧沃斯巴克",s="在暴风城，萨尔努修士听说尖端机器人出了故障，而工匠大师欧沃斯巴克正在铁炉堡为此悲伤。他派联盟冒险者前往侏儒区，欧沃斯巴克在那里请求他们帮忙，从诺莫瑞根取回尖端机器人的存储器核心。",h="在暴风城，萨尔努修士听说尖端机器人出了故障，而工匠大师欧沃斯巴克正在铁炉堡为此悲伤。他派联盟冒险者前往侏儒区，欧沃斯巴克在那里请求他们帮忙，从诺莫瑞根取回尖端机器人的存储器核心。",kw={"诺莫瑞根","铁炉堡","欧沃斯巴克","萨尔努","尖端机器人","侏儒区","工匠大师"},ang={["faction:Alliance"]="身为联盟的一员，帮助侏儒区流离失所的侏儒，能加深暴风城与矮人及侏儒王国之间的纽带。",["profession:Engineering"]="身为工程师，你可以通过研究欧沃斯巴克失控的造物，学习侏儒最前沿的精巧技术。",["race:Gnome"]="身为侏儒，你每抢救一件造物、取回一个存储器核心，都能让沦陷故土的一部分免遭辐射和穴居人的侵害。"},sec={{t="大教堂的求助",b="萨尔努修士在暴风城照料旅人，并讲述侏儒难民遇到的麻烦。工匠大师欧沃斯巴克是缔造诺莫瑞根诸多奇迹的智者之一，如今却因尖端机器人的失常而悲伤。这个机械仆从曾忠实地协助工匠们。后来，这座城市沦为废墟。"},{t="前往侏儒区",b="你从暴风城搭乘矿道地铁，前往铁炉堡的侏儒区。在那里，欧沃斯巴克正在寻找愿意前往诺莫瑞根受辐射的厅堂提供帮助的冒险者。他请求他们在这个构造体造成无法挽回的伤害之前，抢救尖端机器人尚存的机能。"}},faq={{q="工匠大师欧沃斯巴克是谁？",a="工匠大师欧沃斯巴克是一位传授侏儒工程学的侏儒工程师。他身在铁炉堡的侏儒区，协调收复诺莫瑞根的行动，并从这座沦为废墟的都城中抢救散落的侏儒科技造物。",al={"欧沃斯巴克","欧沃斯巴克是谁","工匠大师欧沃斯巴克"}},{q="谁提供这个任务？",a="萨尔努修士是暴风城的一位人类牧师，他派你去帮助铁炉堡的侏儒。",al={"任务给予者","哪里接取工匠大师欧沃斯巴克任务"}},{q="尖端机器人是什么？",a="尖端机器人是工匠大师欧沃斯巴克设计的机械造物。它曾是侏儒工程师的得力工具，但在诺莫瑞根陷落后发生故障，在这座受辐射的城市中失去了控制。",al={"尖端机器人","尖端机器人怎么了"}},{q="在哪里能找到工匠大师欧沃斯巴克？",a="工匠大师欧沃斯巴克位于铁炉堡东部的侏儒区侏儒区，身边是同为难民的工匠和实验机械。",al={"欧沃斯巴克位置","欧沃斯巴克在哪里"}},{q="与欧沃斯巴克交谈后要做什么？",a="你与欧沃斯巴克交谈后，他会请求你进入诺莫瑞根，关闭尖端机器人，并取回它的存储器核心，以便将其修复。",al={"后续任务","拯救尖端机器人的大脑"}},{q="联盟为何关心一位发明家损坏的机器？",a="联盟关心流亡的侏儒，而诺莫瑞根失控的自动机械威胁着那些试图收复这座地下都城或守卫丹莫罗边境的远征队。",al={"为何关心尖端机器人","尖端机器人的重要性"}}},fx={["9c70ad2e"]={q="萨尔努修士为什么派你去找工匠大师欧沃斯巴克？",a="在萨尔努修士的记忆中，尖端机器人是一台温和、乐于助人的自动机械，在诺莫瑞根陷入混乱之前一直忠实地为侏儒服务。听说欧沃斯巴克因自己的造物发生故障而心烦意乱，这位神职人员也深感不安。萨尔努希望这台机器仍能获救，免于腐朽或毁灭，于是指引心怀同情的冒险者前往侏儒区，让那位忧心忡忡的工匠大师得到急需的帮助。",al={"萨尔努修士为什么在意","萨尔努修士的动机","为什么派人去找欧沃斯巴克"}}},fp="20,235,25.293.0,14.259.0,28.211.0,22.91.0,16.197.0,40.151.0,41.136.0,63.172.0"}
P.entries["quest:2924"] = {n="基础模组",s="在铁炉堡，科罗莫特·钢尺缺少实验所需的零件。石腭怪入侵、辐射灾难爆发时，流亡的侏儒逃离了诺莫瑞根，将基础模组留在了城内的下层大厅。",h="在铁炉堡，科罗莫特·钢尺缺少实验所需的零件。石腭怪入侵、辐射灾难爆发时，流亡的侏儒逃离了诺莫瑞根，将基础模组留在了城内的下层大厅。",kw={"人工外推器","基础模组","诺莫瑞根","侏儒工程学","铁炉堡","科罗莫特·钢尺","侏儒区"},ang={["faction:Alliance"]="作为联盟的一员，帮助流亡的侏儒找回失落的技术，能增强联盟在铁炉堡的工程实力。",["profession:Engineering"]="作为工程师，你知道缺少一个零件就可能让许多工作停滞。这些零件展现了诺莫瑞根沦陷前侏儒工程师的技艺。",["race:Gnome"]="作为侏儒，找回这些零件有助于让族人在流亡铁炉堡期间保留自己的工艺和发明技术。"},sec={{t="大撤离中的遗忘",b="石腭怪攻陷诺莫瑞根、辐射弥漫走廊时，侏儒们只带着触手可及的物品逃了出来。基础模组被留在了城里。这些特殊的机械零件几乎适用于任何装置，深受工匠和制造者珍视。如今，身在铁炉堡侏儒区的大工匠科罗莫特·钢尺因为缺少这些零件，无法继续新的实验。"},{t="深入探寻 外推器",b="在诺莫瑞根深处，这些零件存放在名为 人工外推器 的沉重蒸汽动力容器中。要找到它们，你必须穿过遭受辐射的大厅，那里游荡着变异的麻风侏儒、失控的自动防御机械和野蛮的石腭怪。克劳莫特 需要十二个零件才能继续工作，让侏儒的发明创造在流亡中延续。"}},faq={{q="什么是基础模组？",a="基础模组是侏儒工程师制造的机械零件，几乎适用于任何装置。工匠和铁匠十分看重这些零件，用它们作为构造复杂装置和实验机械的基础。",al={"什么是基础模组","基础模组","这是什么"}},{q="谁提供基础模组任务？",a="铁炉堡侏儒区的侏儒工程师科罗莫特·钢尺请求收集这些零件。",al={"任务给予者","谁提供任务","哪里获取基础模组"}},{q="诺莫瑞根的基础模组在哪里？",a="基础模组存放在诺莫瑞根深处，位于散布在下层大厅的 人工外推器 内。这些是由蒸汽驱动的高大储物柜。",al={"它们在哪里","外推器 位置","如何找到模组"}},{q="为什么它们被留在了诺莫瑞根？",a="石腭怪入侵诺莫瑞根，辐射笼罩了整座城市。仓促撤离时，侏儒们将储备的基础模组留在了下层工坊。",al={"为何被留下","为何在诺莫瑞根","模组的背景故事"}},{q="科劳莫特 需要它们做什么？",a="科罗莫特·钢尺正在铁炉堡的工坊里筹备复杂的实验，需要用到这些零件。",al={"科劳莫特 为何需要它们","科劳莫特 的计划"}},{q="接受这个任务前必须完成帮助科劳莫特吗？",a="帮助科劳莫特让你结识 科劳莫特，并指引你前往他的工坊。无需完成该任务，你也可以接受这项委托。",al={"前置任务","前置","是否需要 帮助科劳莫特"}}},fx={["41f0ee2b"]={q="为什么科罗莫特需要外来的冒险者进入诺莫瑞根？",a="诺莫瑞根已不再是一座正常运转的城市，而是一个辐射肆虐、危机四伏的战场，到处都是穴居人和神志失常的麻风侏儒。像科罗莫特·钢尺这样的侏儒工匠是研究者，并非前线士兵，而幸存于侏儒区的侏儒是仰赖矮人款待的难民，并非一支进攻大军。要深入这座废城最深、最危险的区域，需要经验丰富的冒险者，杀穿一波波敌对的变异生物，才能抵达储物箱所在之处。",al={"为什么派我去","为什么需要冒险者","为什么科劳莫特不能自己拿"}}},fp="21,215,23.375.0,25.343.0,32.217.0,42.94.0,56.169.0,40.160.0,34.109.0,60.136.0"}
P.entries["quest:2925"] = {n="帮助科劳莫特",s="在达纳苏斯，玛希尔将科罗莫特·钢尺的紧急求助传向大海彼岸。他无法擅离职守，便请联盟旅者前往铁炉堡，寻找他的侏儒朋友。",h="在达纳苏斯，玛希尔将科罗莫特·钢尺的紧急求助传向大海彼岸。他无法擅离职守，便请联盟旅者前往铁炉堡，寻找他的侏儒朋友。",kw={"基础模组","诺莫瑞根","铁炉堡","科罗莫特·钢尺","帮助科劳莫特","麻风侏儒","玛希尔","侏儒区"},ang={["faction:Alliance"]="身为联盟旅者，你将玛希尔的求助从达纳苏斯带到铁炉堡，交给Klockmort。暗夜精灵的领地与矮人的厅堂携手御敌。",["race:Gnome"]="身为侏儒，你知道每一次前往侏儒区响应召唤，都在为夺回失落的家园诺莫瑞根贡献力量。"},sec={{t="跨越大陆的呼唤",b="玛希尔从达纳苏斯的战士区向丹莫罗传去消息。科罗莫特·钢尺需要勇敢的盟友一同深入诺莫瑞根，但玛希尔无法离开岗位前往那里。因此，他请途经达纳苏斯、身手不凡的联盟旅者代他走这一趟。"},{t="通往侏儒区之路",b="科罗莫特·钢尺在侏儒区工作，这片铁炉堡城区收容了被迫离开地下城市的侏儒。他计划从诺莫瑞根遭到污染的走廊中取回关键机械。在玛希尔的引荐下，你来到Klockmort的工坊，他需要有人帮忙取回遗留在那里的东西。"}},faq={{q="谁提供帮助科劳莫特任务？",a="玛希尔发出了召唤。这位暗夜精灵无法离开岗位前往铁炉堡，便请值得信赖的联盟旅者回应老友科罗莫特·钢尺的求助。",al={"任务给予者","谁提供帮助科劳莫特任务","玛希尔任务"}},{q="在哪里能找到科罗莫特·钢尺？",a="在铁炉堡的侏儒区侏儒区可以找到科罗莫特·钢尺。失去家园、流离失所的侏儒在那里建起了工坊，安置了设备。",al={"科劳莫特在哪里","科劳莫特位置","科劳莫特·钢钳铁炉堡"}},{q="科劳莫特为什么需要有人在诺莫瑞根帮忙？",a="科劳莫特需要有人帮忙从诺莫瑞根取回必需的机械零件。有毒的放射性尘埃席卷了这座城市，如今废墟中盘踞着穴居人、神志失常的麻风侏儒和失控的自动机械。",al={"科劳莫特需要什么","为何前往诺莫瑞根执行任务","科劳莫特的目的"}},{q="进入诺莫瑞根必须完成这个任务吗？",a="不必。玛希尔的召唤会引领你找到科罗莫特·钢尺，但即使没有他的引荐，你也可以在铁炉堡与科劳莫特交谈，接受他的任务。",al={"此任务是否必做","诺莫瑞根前置任务","能否跳过帮助科劳莫特"}},{q="帮助科劳莫特的后续任务是什么？",a="与科罗莫特·钢尺交谈后，他会让你接受基础模组任务。这个任务会让你深入诺莫瑞根。",al={"下一个任务","后续任务","基础模组后续任务"}},{q="玛希尔为什么愿意帮助铁炉堡的一名侏儒？",a="玛希尔和科劳莫特是多年的老朋友。虽然驻守远方、无法擅离职守，玛希尔仍在寻找值得信赖的人去帮助朋友。",al={"玛希尔的关系","玛希尔为何关心","玛希尔与科劳莫特"}}},fx={b4ad922f={q="为什么玛希尔请你前去，而不亲自出发？",a="玛希尔职责在身，必须留守达纳苏斯，无法远渡重洋前往丹莫罗。虽然他心中急切地想亲自帮助朋友科罗莫特，却只能托付一位前往铁炉堡的能干冒险者，代他回应求助。",al={"为什么玛希尔不能去","玛希尔为什么派我去","为什么玛希尔不帮助科劳莫特"}}},fp="22,166,24.294.0,22.296.0,43.175.0,38.152.0,43.184.0,43.150.0,42.121.0,58.162.0"}
P.entries["quest:2926"] = {n="诺恩",s="在卡拉诺斯，奥齐·电环派冒险者前往诺莫瑞根，收集放射性尘埃。他希望调制出治疗麻风侏儒的药剂，不过这药剂也可能变成烈酒。",h="在卡拉诺斯，奥齐·电环派冒险者前往诺莫瑞根，收集放射性尘埃。他希望调制出治疗麻风侏儒的药剂，不过这药剂也可能变成烈酒。",kw={"诺恩","诺莫瑞根","绿光","受到辐射的石腭怪","卡拉诺斯","麻风侏儒","奥齐·电环","小瓶","辐射"},ang={["faction:Alliance"]="身为联盟的一员，你知道诺莫瑞根的污染威胁着整个丹莫罗。了解或控制放射性尘埃，关系到这片地区的安全。",["profession:Engineering"]="身为工程师，你看到了侏儒实地开展科学研究的方式：用具有屏蔽作用的铅瓶，收集未经处理的放射性废液。",["race:Gnome"]="身为流亡的侏儒，你知道同胞们多么迫切地想为受到辐射的同族找到解药。即使是奥齐那些异想天开的实验，也值得一试。"},sec={{t="解药还是鸡尾酒",b="自诺莫瑞根陷落以来，诺恩这样的难民一直设法消灭入侵的石腭怪，并治愈那种让同胞发生异变的疾病。奥齐·电环和他的搭档拉兹·滑链则在卡拉诺斯的工坊里另寻出路。奥齐说，他们正试着为麻风侏儒研制解药。不过，他们的配方也可能酿出烈性朗姆酒。"},{t="采集绿光",b="奥齐和拉兹需要灾难中心的有毒残渣。奥齐交给冒险者一个铅制收集瓶，派他们前往诺莫瑞根遭到破坏的隧道。辐射入侵者和辐射抢劫者在那里游荡，这些石腭怪全身浸透了泄漏的废料。瓶子里需要收集的，正是它们身上的绿光。"},{t="头发与厚望",b="有了满满一瓶绿光，奥齐便着手准备活体试验。他希望这副药剂能让一名被俘的麻风侏儒恢复健康与理智。他还希望这份放射性尘埃混合物能治好自己的秃头。"}},faq={{q="谁提供诺恩任务？",a="卡拉诺斯的侏儒工匠奥齐·电环提供这项工作。",al={"谁提供诺恩","诺恩任务给予者","奥齐·电环任务"}},{q="这个任务需要收集什么？",a="对发光的辐射入侵者或辐射抢劫者使用空铅瓶，收集放射性尘埃，直到装满瓶子。",al={"诺恩任务目标","诺恩收集什么","装满的铅瓶"}},{q="在哪里能找到受到辐射的石腭怪？",a="受到辐射的石腭怪出没于通往诺莫瑞根副本传送门的外围入口洞穴和蜿蜒的走廊。无需进入地下城就能找到它们。",al={"受到辐射的石腭怪在哪","诺恩石腭怪位置","辐射入侵者位置"}},{q="接取这个任务前，必须先完成“灾难之后”吗？",a="不必。奥齐提供的这个任务独立于灾难之后，不过后者的故事与卡拉诺斯的局势有关，也是这段故事的铺垫。",al={"是否必须完成灾难之后","诺恩前置任务"}},{q="奥齐想用放射性尘埃做什么？",a="奥齐和拉兹正试着为麻风侏儒研制解药，不过奥齐承认，这副药剂也可能变成高度朗姆酒。",al={"奥齐为何需要辐射","诺恩有什么用"}},{q="诺恩的后续任务是什么？",a="装满瓶子后，便会接到更多的辐射尘！，任务将引导你深入诺莫瑞根。",al={"诺恩后续任务","诺恩之后是什么任务"}}},fx={["28ada800"]={q="装满的铅瓶有什么用？",a="这个瓶子以铅作为屏障，用来安全储存和运送从诺莫瑞根周围穴居人身上提取的危险发光放射性尘埃。奥齐·电环和拉兹·滑链需要这种浓缩的放射性物质，作为实验药剂的关键原料。他们希望这药剂能治好被他们关押的麻风侏儒，或者酿出烈性非凡的朗姆酒，或许还能让奥齐重新长出头发。",al={"装满的铅瓶用途","为什么用铅瓶","铅制收集瓶用途"}},dfd2dab8={q="诺莫瑞根里受到辐射的穴居人是什么来历？",a="穴居人最初从诺莫瑞根的地底深处涌出，攻陷了这座堪称科技奇迹的城市。为了消灭入侵者，大工匠梅卡托克和他的顾问们孤注一掷，让有毒的辐射充斥下层通道。许多穴居人非但没有死去，反而存活下来，变异成凶残的辐射入侵者和掠夺者，如今浑身泛着病态的绿色放射光芒。",al={"辐射入侵者","辐射掠夺者","穴居人为什么受到辐射"}}},fp="8,183,20.360.0,19.298.0,19.200.1,30.65.0,41.146.0,39.164.0,63.128.0,64.118.0,28.95.0"}
P.entries["quest:2927"] = {n="灾难之后",s="在铁炉堡和卡拉诺斯，诺莫瑞根的幸存者正为故城的毁灭寻找出路。诺恩派旅者去找奥齐·电环，他正在研究污染，希望找到解决办法。",h="在铁炉堡和卡拉诺斯，诺莫瑞根的幸存者正为故城的毁灭寻找出路。诺恩派旅者去找奥齐·电环，他正在研究污染，希望找到解决办法。",kw={"诺恩","侏儒爆炸头","诺莫瑞根","卡拉诺斯","奥齐·电环","辐射泄漏","灾难之后","石腭怪"},ang={["faction:Alliance"]="身为联盟的英雄，你帮助丹莫罗的侏儒智者控制这场威胁山地王国的离奇生化灾难。",["profession:Engineering"]="身为工程师，你看到奥齐·电环正在试验各种构想，而侏儒工匠们正面对一场失控的技术灾难。",["race:Gnome"]="身为侏儒，你懂得诺恩的哀叹。其中承载着被逐出首都的难民们的悲剧、古怪的自豪，以及满怀怨恨的复仇之心。"},sec={{t="惨痛的损失",b="在铁炉堡的侏儒区，诺恩为诺莫瑞根和自己失去的侏儒爆炸头而哀伤。入侵的石腭怪占据了这座机械之城，有毒的放射性尘埃则夺走了他引以为傲的浓密头发。对石腭怪的愤怒和收复城市的希望，促使他将心怀同情的旅者派往同僚那里，挽救劫后残存的一切。"},{t="通往卡拉诺斯的道路",b="在卡拉诺斯，富有创造力的侏儒已经开始应对放射性尘埃。诺恩派旅者去找奥齐·电环，他正与搭档拉兹·滑链一同工作。奥奇还记得那场灾难，当时诺恩的头发成把脱落，疯狂与复仇的渴望占据了他的心。如今，奥奇在这座被白雪覆盖的小镇研究污染，运用工程学技艺寻找解毒剂。"}},faq={{q="诺恩是谁？",a="诺恩是铁炉堡侏儒区的一名侏儒难民。石腭怪的入侵和排放放射性废料引发的灾难让他满心怨愤，而那头曾令他自豪的侏儒爆炸头突然脱落，更让他深受打击。",al={"诺恩","秃头侏儒","谁提供灾难之后"}},{q="诺恩为什么派你去找奥齐·电环？",a="诺恩希望诺莫瑞根仍有救。奥齐·电环和他的搭档拉兹·滑链正在卡拉诺斯，研究笼罩那座城市的有毒辐射，并试图用工程学手段研制解药。",al={"为什么去找奥奇","奥齐·电环任务","卡拉诺斯工程师"}},{q="诺莫瑞根发生了什么，才会变成这样？",a="石腭怪大举入侵城市地下时，大工匠格尔宾·梅卡托克受人劝说，将具有放射性的有毒废料排入下层大厅，企图消灭它们。计划失败了。无数侏儒丧生或发生变异，诺莫瑞根变得无法居住，而石腭怪却活了下来。",al={"诺莫瑞根发生了什么","诺莫瑞根为什么受到辐射","石腭怪入侵"}},{q="找到奥齐之后，这条任务线会如何继续？",a="向奥齐报到后，他会让你从诺莫瑞根外受到辐射的石腭怪身上收集放射性尘埃。他将测试旨在中和这些尘埃的实验混合物。",al={"灾难之后后续","灾难之后之后是什么","下一个任务"}}},fx={b3abdd6a={q="为什么诺恩希望完成这件事？",a="驱使诺恩的是个人的愤怒和顽固的希望。毁掉诺莫瑞根的放射性尘埃，也夺走了他引以为傲的心爱之物：整个艾泽拉斯独一无二的侏儒蓬蓬头。他对自己秃顶的遭遇愤恨不已，一心想向入侵的穴居人复仇，却仍不肯放弃家园。他相信，只要引导能干的冒险者去找奥齐·电环，就仍有机会扭转这场灾难，夺回城市。",al={"诺恩的动机","为什么帮助诺恩","诺恩为什么在意"}}},fp="13,196,13.310.0,20.381.0,14.200.0,45.194.0,42.273.0,54.170.0"}
P.entries["quest:2928"] = {n="陀螺式挖掘机",s="在暴风城的矮人区，沉默的舒尼正为丹莫罗筹备掘地机械。由于缺少零件，她派你进入诺莫瑞根，从失控的自动机械身上回收所需部件。",h="在暴风城的矮人区，沉默的舒尼正为丹莫罗筹备掘地机械。由于缺少零件，她派你进入诺莫瑞根，从失控的自动机械身上回收所需部件。",kw={"丹莫罗","矮人区","挖掘机","诺莫瑞根","侏儒工程学","回旋式挖掘机","机械内胆","沉默的舒尼"},ang={["faction:Alliance"]="身为联盟的一员，在暴风城帮助侏儒整备挖掘机械，可以加强收留他们的人类与那些努力夺回祖业的流亡幸存者之间的联系。",["profession:Engineering"]="身为工程师，从诺莫瑞根倒下的机械仆从身上拆取精密的发条内部组件，能让你在实践中了解侏儒设计与重型机械维修。",["race:Gnome"]="身为侏儒，每回收一个部件，都能让舒尼的地下机队离恢复运转更近一步。在暴风城，收复故土、重振工业的梦想仍在延续。"},sec={{t="缺少内胆的机队",b="在暴风城的矮人区，沉默的舒尼正为丹莫罗筹备自动旋钻挖掘机。那里的侏儒工程师正在援助流离失所的同胞。这些机械将通过地下运送人员和物资，但这些庞然大物缺了舒尼手头紧缺的机械零件，就无法运转。"},{t="陷落之城的回收行动",b="诺莫瑞根曾供应侏儒的高科技装备。如今，破败的厅堂和附近的隧道里仍有值得回收的机械，但故障的防御机器人、机械哨兵和发条劳工也在那里肆意游荡。舒尼派你进入这座陷落的城市，收集二十四捆机械内胆，带回人类的领地。"},{t="浩大的工程",b="二十四捆机械内胆提供的废料，只够修好一台挖掘机。舒尼还有近四百台机械需要整备，因此，大规模地下运输的筹备依然进展缓慢。每一台恢复运转的机械，都让夺回诺莫瑞根陷落时失去的土地这一目标更近一步。"}},faq={{q="什么是旋钻式挖掘机？",a="旋钻式挖掘机是一种侏儒重型掘地机械，也称为钻探机，用于挖掘，并在地下运送人员或物资。沉默的舒尼正在筹备一支机队，为丹莫罗效力。",al={"回转式挖掘机","什么是挖掘机","侏儒钻机"}},{q="沉默的舒尼是谁？",a="沉默的舒尼是暴风城矮人区的一名侏儒工程师。她直言不讳，要求严苛，正在整备数百台机械挖掘机。",al={"沉默的舒尼","舒尼","舒尼是谁"}},{q="为什么舒尼偏偏需要诺莫瑞根的零件？",a="诺莫瑞根曾供应侏儒的高科技装备，如今陷落的厅堂里仍有失控的自动机械、发条仆从和防御机甲。城中的制造业供应线已经中断，因此，这些失控的机械成了兼容的侏儒备用零件的来源。",al={"为何需要诺莫瑞根零件","为何需要机械内胆","诺莫瑞根回收"}},{q="在哪里能找到机械内胆？",a="在诺莫瑞根破败的设施及通往其中的上层隧道里，可以从机械哨兵、发条构造体和其他敌对机械身上回收机械内胆。",al={"机械内胆","哪里获取内胆","诺莫瑞根机械内胆"}},{q="修好一台机械，就算完成舒尼的机队了吗？",a="不算。二十四捆机械内胆只能修好一台钻机。舒尼说，她还有三百九十八台挖掘机需要整备。",al={"挖掘机数量","舒尼机队规模","钻机数量"}},{q="为什么要为丹莫罗筹备挖掘机队？",a="丹莫罗是侏儒的祖居之地，也是他们陷落的首都所在地。重型掘地机械可以协助挖掘、清理残骸，并支援白雪覆盖的山区中的作业。",al={"前往丹莫罗的机队","为何选择丹莫罗","挖掘机用途"}}},fx={b2dc5b24={q="机械内胆有什么用？",a="沉默的舒尼需要回收这些内部零件，用来修复她的旋翼钻探挖掘机队。这些地下掘进载具的构造十分复杂，需要精密的齿轮、线路和传动装置，而这些部件很难在暴风城从头制造。只要从游荡于诺莫瑞根的自动发条机械体内拆下还能运作的部件，她就能回收关键备件，让停摆的钻机重新运转。",al={"机械内胆有什么用","机械内胆用途","舒尼要内部零件的用途"}},["1cb24930"]={q="你要在诺莫瑞根里为舒尼对付什么？",a="你受命拆解游荡在诺莫瑞根辐射大厅及周边地区的失控机器人和机械。当这座地下侏儒都城因穴居人入侵和放射性尘埃而沦陷时，无数自动防御系统和工程装置发生故障，开始敌视外来者。在舒尼眼中，这些被遗弃的游荡自动机械不只是危险，也是遍地等待回收的废料。",al={"为舒尼对付谁","诺莫瑞根内部零件目标","哪些机械有内部零件"}},["33a01105"]={q="为什么舒尼需要你收集零件，而不亲自前去？",a="舒尼是驻扎在暴风城矮人区的一名工程师，忙于维护机械，并监督一支庞大挖掘机队的组装。要深入这片辐射肆虐、穴居人盘踞、致命发条哨兵横行的废墟，需要一位全副武装、愿意杀穿危险通道的冒险者。她留在后方，检查送来的回收零件，并用它们修理钻机。",al={"为什么派我收集内部零件","舒尼为什么不亲自去","舒尼的任务为什么找我"}}},fp="30,178,23.289.0,26.332.0,24.290.0,40.208.0,25.146.0,55.250.0,41.172.0,45.115.0,57.182.0"}
P.entries["quest:293"] = {n="净化帕雷斯之眼",s="在湿地，净化帕雷斯之眼让冒险者带着一颗被诅咒的宝珠南下暴风城，寻求援助。找回帕雷斯之眼后，他们前去寻找大主教本尼迪塔斯，祛除其中残留的污秽。",h="在湿地，净化帕雷斯之眼让冒险者带着一颗被诅咒的宝珠南下暴风城，寻求援助。找回帕雷斯之眼后，他们前去寻找大主教本尼迪塔斯，祛除其中残留的污秽。",kw={"大主教本尼迪塔斯","光明大教堂","净化之眼","被诅咒的帕雷斯之眼","帕雷斯之眼","戈罗林·钢眉","暴风城","湿地"},ang={["class:Paladin"]="圣骑士将从黑暗沼泽中寻回圣物视为一项庄严的职责。帕雷斯之眼遭到腐化是一种亵渎，必须在暴风城的神圣殿堂中予以净化。",["class:Priest"]="对信奉圣光的牧师而言，被诅咒的帕雷斯之眼表明，绝望也能腐化神圣造物。唯有大主教本尼迪塔斯施行净化，才能洗去其中的污秽。",["faction:Alliance"]="湿地的矮人前哨与暴风城的精神领袖凭借共同的信仰携手合作，将联盟各王国联结在一起。"},sec={{t="受污染的圣物",b="从沼泽地找回的帕雷斯之眼已不再散发神圣的光芒。暗影缠绕着它，那场令它遗失的悲剧所留下的悲伤与创痛也挥之不去。矮人戈罗林·钢眉认出了宝珠的力量。然而，他并不掌握解除如此沉重诅咒所需的神圣技艺。"},{t="前往大教堂",b="帕雷斯之眼最初由信奉圣光的人类牧师打造，因此只有他们最高阶的教团才知道如何消除其中的污秽。戈罗林让冒险者带着黯淡的宝珠南下暴风城，去见圣光教会的领袖大主教本尼迪塔斯。本尼迪塔斯深知，任由这样的圣物未经净化会带来危险。他接下了恢复其神圣光芒的工作。"}},faq={{q="帕雷斯之眼是什么？",a="帕雷斯之眼是人类牧师打造的神圣宝珠，本应散发圣洁的光辉。未受污染时，它们的力量与圣光相契合。遭到腐化后，它们的能量便会变得不稳定且危险。",al={"帕雷斯之眼背景","这颗宝珠是什么","帕雷斯之眼是什么"}},{q="戈罗林·钢眉为什么不能亲自净化帕雷斯之眼？",a="戈罗林·钢眉无法净化帕雷斯之眼，因为他不掌握驱除其中黑暗诅咒所需的宗教仪式技艺。这件圣物由信奉圣光的人类牧师打造，因此净化其中的腐化需要这一传承的权威。",al={"为什么派我去暴风城","戈罗林净化","为什么找本尼迪塔斯"}},{q="大主教本尼迪塔斯是谁？",a="大主教本尼迪塔斯是圣光教会德高望重的领袖。他居于暴风城的光明大教堂，在信仰事务上指引联盟。",al={"本尼迪塔斯是谁","大主教本尼迪塔斯","暴风城大主教"}},{q="为什么说帕雷斯之眼污秽或悲伤？",a="大主教本尼迪塔斯说，这颗宝珠曾见证湿地的一场重大悲剧。随着时间流逝，它吸收了那份痛苦，而其中挥之不去的悲伤化作诅咒，扭曲了它的力量。",al={"为什么受到诅咒","帕雷斯之眼悲剧","被诅咒的帕雷斯之眼"}},{q="本尼迪塔斯收到宝珠后会怎样？",a="本尼迪塔斯同意净化宝珠。帕雷斯之眼本应光芒四射，而其中的污秽会给附近的人带来精神与肉体上的严重威胁。",al={"本尼迪塔斯会净化它吗","帕雷斯之眼结局"}},{q="光明大教堂位于何处？",a="光明大教堂坐落于暴风城北部城区的教堂广场。大主教本尼迪塔斯站在圣殿中央的主祭坛前。",al={"光明大教堂在哪里","光明大教堂位置","寻找本尼迪塔斯"}}},fx={["6f168d84"]={q="戈罗林·钢眉为什么想净化帕雷斯之眼？",a="戈罗林知道，被诅咒的帕雷斯之眼是一件极其危险的圣物。它由人类圣光牧师创造，原本能够绽放明亮光芒；但一旦遭遇悲剧和黑暗力量的污染，其魔力便会变得危险而具有腐蚀性。矮人工艺和他自己的本领都无法消除这种灵性诅咒，因此他坚持要把它送到暴风城，以免腐化之力继续伤害你或周围的土地。",al={"为何净化帕雷斯之眼","戈罗林·钢眉的动机","为何把帕雷斯之眼送去暴风城"}}},fp="17,203,15.267.0,24.379.0,26.194.0,51.224.0,29.168.0,48.180.0,46.160.0,40.167.0"}
P.entries["quest:2930"] = {n="抢救数据",s="大机械师卡斯派普派你深入诺莫瑞根，找回城中的记录。穴居人和辐射迫使侏儒逃离了这座城市，但穿孔机终端仍将档案封存在层层权限之后。",h="大机械师卡斯派普派你深入诺莫瑞根，找回城中的记录。穴居人和辐射迫使侏儒逃离了这座城市，但穿孔机终端仍将档案封存在层层权限之后。",kw={"卡斯派普","抢救数据","工程实验室","诺莫瑞根","矩阵式打孔计算机","彩色穿孔卡片","穿孔卡片","侏儒区","火车站"},ang={["faction:Alliance"]="作为联盟的一员，你通过帮助卡斯派普，支持流亡铁炉堡的侏儒政府。你的援助增强了Grand Alliance的凝聚力和科技实力。",["profession:Engineering"]="作为工程师，你可以研究矩阵式打孔计算机网络如何储存数据，以及如何运用Tinkers' Court设计的复杂权限机制。",["race:Gnome"]="作为侏儒，你通过找回诺莫瑞根的数据，帮助夺回族人的遗产。每找回一张穿孔卡片，都能让城中的一份智慧结晶免遭穴居人和辐射的毁坏。"},sec={{t="地下失落的档案",b="穴居人和辐射迫使诺莫瑞根的居民逃离城市，留下了数百年来积累的研究成果、设计图和市政记录。矩阵式打孔计算机终端仍排列在城中充满科技气息的走廊里。它们管理安全权限，并储存文件。身在铁炉堡侏儒区的大机械师卡斯派普希望你深入城中，找回这些以穿孔编码保存的档案。"},{t="孔眼中的权限等级",b="侏儒的主机要求逐级提升权限。首先，在内门外的残骸中找到一张白色穿孔卡片。将它插入车站的矩阵式打孔计算机 3005-A，制成一张黄色卡片。然后将它带到宿舍的3005-B终端，换取一张蓝色卡片。3005-C型会将它升级为红色。最后一台终端3005-D位于工程实验室，红色卡片会在那里变成彩色穿孔卡片。"},{t="二进制中的侏儒笑话",b="诺莫瑞根的穿孔卡片上不只有技术记录。卡片的二进制编码中还藏着诙谐的俏皮话、对工作的抱怨，以及关于大工匠Gelbin Mekkatorque穿暗夜精灵内衣的低俗笑话。就连城中的计算机行会也忍不住要搞些恶作剧。"}},faq={{q="彩色穿孔卡片是什么？",a="彩色穿孔卡片代表诺莫瑞根自动化主机认可的最高安全权限。工程实验室的矩阵式打孔计算机 3005-D可以用红色穿孔卡片制作它。",al={"彩色卡片","穿孔卡片是什么","诺莫瑞根穿孔卡片"}},{q="穿孔卡片的升级流程从哪里开始？",a="流程从一张白色穿孔卡片开始，可以在正门外、地铁站附近的穴居人和废弃机械身上找到。",al={"哪里获取白色穿孔卡片","穿孔卡片流程如何开始","第一张穿孔卡片"}},{q="矩阵式打孔计算机终端位于哪里？",a="矩阵式打孔计算机 3005-A位于入口外的地铁站。3005-B型位于清洁区之后的宿舍内，3005-C则在更深处的栈道平台上。3005-D型位于工程实验室的下层。",al={"终端位置","穿孔机在哪里","穿孔卡片机器"}},{q="大机械师卡斯派普是谁？",a="大机械师卡斯派普是铁炉堡侏儒区难民中的一位资深侏儒工程师。他负责协调各项行动，从沦陷的首都找回诺莫瑞根留下的知识遗产。",al={"卡斯派普","谁提供抢救数据","卡斯派普背景故事"}},{q="卡片上究竟存着什么数据？",a="卡片中存有关键的运算数据、侏儒工程师的趣谈、关于萨尔和梅卡托克等各地领袖的轻松笑话，以及一些古怪的笔记。",al={"卡片文字","二进制翻译","二进制写了什么"}},{q="部落玩家能使用这些终端吗？",a="大机械师卡斯派普只在铁炉堡向联盟提供这项工作。任何携带所需卡片的人都可以使用地下城内的穿孔机终端。",al={"部落抢救数据","部落穿孔卡片","部落能否使用终端"}}},fx={["0f0753b5"]={q="为什么大机械师卡斯派普想要找回穿孔卡片？",a="诺莫瑞根沦陷时，侏儒们仓促撤离，大量重要的运行和技术数据在混乱中被遗留了下来。大机械师卡斯派普认为，储存在高度戒备的矩阵式打孔计算机终端中的信息，关乎侏儒的生存与重建，坚称他们承受不起永远失去这些信息的代价。",al={"卡斯派普的动机","卡斯派普为什么需要穿孔卡片","为什么要进行抢救数据"}}},fp="11,210,32.373.0,27.423.0,24.288.1,33.186.0,45.138.0,51.234.0,32.192.0,35.163.0,41.165.0"}
P.entries["quest:2931"] = {n="卡斯派普的任务",s="在铁炉堡，大机械师卡斯派普号召旅行者找回诺莫瑞根的记录。那些残破的大厅中仍保存着至关重要的机械与技术知识。",h="在铁炉堡，大机械师卡斯派普号召旅行者找回诺莫瑞根的记录。那些残破的大厅中仍保存着至关重要的机械与技术知识。",kw={"组装","卡斯派普","抢救数据","加克希姆","诺莫瑞根","铁炉堡","尘链","侏儒区"},ang={["faction:Alliance"]="作为联盟的盟友，你帮助流离失所的侏儒找回遗失的档案。这项工作增强了侏儒区的实力，也巩固了联盟的技术地位。",["profession:Engineering"]="作为工程师，你知道诺莫瑞根的数据核心中保存着计算技术的奇迹与先进图纸，在艾泽拉斯其他地方无可比拟。",["race:Gnome"]="作为侏儒，每一次回收行动都让你从辐射与毁灭中保住一部分沦陷的家园。卡斯派普的工作关乎你族人的生存。"},sec={{t="侏儒区的召唤",b="诺莫瑞根沦陷并因放射性污染而被封锁隔离后，幸存的侏儒在铁炉堡的侏儒区找到了庇护之所。穴居人和受到辐射的构造体仍盘踞在他们昔日的家园。城市深处的计算阵列中保存着运行记录和机械图纸。卡斯派普正在寻找愿意冒险进入剧毒大厅的外来者，找回那些或许能解释灾难缘由，或帮助侏儒重返家园的文件。"},{t="学会的支持",b="来自奥术、炼金术和工程学启蒙协会的加克希姆·尘链正在四处宣传卡斯派普的行动。卡斯派普不属于任何学术团体，但侏儒同胞们敬重他的技艺，也支持他的工作。尘链认为，这次行动具有战略价值的概率为百分之八十四。旅行者可以前往侏儒区报到，听候指示。"}},faq={{q="大机械师卡斯派普是谁？",a="大机械师卡斯派普是铁炉堡侏儒区一位备受尊敬的侏儒工程师。他组织回收队，从诺莫瑞根的地下废墟中找回数据。",al={"卡斯派普","卡斯派普是谁","大机械师卡斯派普"}},{q="卡斯派普为什么需要诺莫瑞根的数据？",a="诺莫瑞根遭到污染、居民撤离时，主机存储器中仍留有关键的技术知识、蓝图和内部系统日志。流离失所的侏儒希望重建家园，因此需要这些资料。",al={"诺莫瑞根数据","为何找回数据","诺莫瑞根记录"}},{q="加克希姆·尘链是谁？",a="加克希姆·尘链是奥术、炼金术和工程学启蒙协会的一位侏儒学者。他支持卡斯派普的回收行动，并指引有能力的旅行者前去参与。",al={"加克希姆","尘链"}},{q="在哪里可以找到卡斯派普？",a="大机械师卡斯派普就在侏儒区，那是铁炉堡东部由侏儒定居的城区。",al={"卡斯派普位置","卡斯派普在哪里"}},{q="向卡斯派普报到后会发生什么？",a="向大机械师卡斯派普报到后，就会接到前往这座沦陷城市执行的抢救数据任务。旅行者将进入诺莫瑞根受到污染的内部区域，找回计算机穿孔卡和存储介质。",al={"后续任务","接下来是什么","卡斯派普之后"}},{q="奥术、炼金术和工程学启蒙协会是什么？",a="奥术、炼金术和工程学启蒙协会是一个备受尊敬的侏儒学会，致力于科学、魔法和机械研究。加克希姆·尘链等成员会运用概率来评估重要工作。",al={"协会","启蒙协会"}}},fx={["0652d792"]={q="为什么加克希姆·尘链派你去找大机械师卡斯派普？",a="加克希姆·尘链十分敬重大机械师卡斯派普的才智，尽管卡斯派普并不是奥术、炼金术和工程学启蒙协会的成员。根据加克希姆的计算，卡斯派普正在诺莫瑞根筹备的数据回收行动，有百分之八十四的可能确实对侏儒至关重要。既然胜算如此可观，加克希姆便热切地引导能干的冒险者前往铁炉堡，支援收复家园的行动。",al={"加克希姆为什么派人去","加克希姆·尘链的动机","为什么找卡斯派普交谈"}}},fp="15,157,20.417.0,20.356.0,32.167.0,44.217.0,24.190.0,28.111.0,41.184.0,81.231.0"}
P.entries["quest:2932"] = {n="可怕的消息",s="尼姆布亚要惩罚背叛萨尔的枯木巨魔，尽管他们曾是部落的盟友。尼姆布亚的长矛要插上枯木巨魔的头颅，立在辛特兰的一座枯木村落里。",h="尼姆布亚要惩罚背叛萨尔的枯木巨魔，尽管他们曾是部落的盟友。尼姆布亚的长矛要插上枯木巨魔的头颅，立在辛特兰的一座枯木村落里。",kw={"可怕的消息","辛特兰","西利瓦萨","尼姆布亚","塔伦米尔","萨尔","枯木","祖瓦沙"},sec={{t="鲜血的警告",b="枯木巨魔曾与部落并肩作战，后来却背叛了萨尔。尼姆布亚交给你一根长矛，派你长途北上，前往辛特兰，那里位于被遗忘者占据的村庄塔伦米尔的东北方。在那里猎杀枯木巨魔，收集他们的头颅，然后将长矛插在西利瓦萨或祖瓦沙的土地上，这两处都是他们较小的村落，好让他们明白自己的所作所为要付出什么代价。事后，尼姆布亚会在荆棘谷等候。"}},faq={{q="尼姆布亚为什么要惩罚枯木巨魔？",a="尼姆布亚说，他们曾是部落的盟友，却背叛了萨尔，这样的背叛不能不受惩罚。",al={"为何攻击枯木","枯木的背叛","可怕的消息原因"}},{q="尼姆布亚派你去哪里插下长矛？",a="西利瓦萨或祖瓦沙都可以，这两处是辛特兰较小的枯木村落。",al={"长矛插在哪里","尼姆布亚长矛位置","可怕的消息地点"}},{q="辛特兰在塔伦米尔的什么方向？",a="辛特兰位于被遗忘者占据的村庄塔伦米尔的东北方，也在尼姆布亚所在的荆棘谷以北很远的地方。",al={"辛特兰位置","辛特兰在哪里"}},{q="谁给予恐怖的消息任务？",a="在荆棘谷的尼姆布亚，他交给你长矛，并在那里等候消息。",al={"可怕的消息任务给予者","尼姆布亚是谁"}}},fp="12,184,18.400.0,54.127.0,46.93.0,43.127.0,23.69.0"}
P.entries["quest:2933"] = {n="毒液瓶",s="在辛特兰的枯木村中，到处都是装着邪恶绿色毒液的瓶子。数量如此之多，说明枯木巨魔非常看重它。附近的塔伦米尔的一位药剂师或许会对样本感兴趣。",h="在辛特兰的枯木村中，到处都是装着邪恶绿色毒液的瓶子。数量如此之多，说明枯木巨魔非常看重它。附近的塔伦米尔的一位药剂师或许会对样本感兴趣。",kw={"药剂师林度恩","蛛形纲生物","辛特兰","塔伦米尔","巨魔毒液","毒液瓶","枯木"},sec={{t="毒性的发现",b="枯木村里的瓶子装着一种邪恶的绿色毒液。数量非常多，枯木巨魔一定认为它很重要。可以将样本带给塔伦米尔的一位药剂师，他可能想看看。"},{t="林度恩的鉴定",b="药剂师林度恩当天所有的实验都失败了，他接过瓶子，断定里面的东西是从某种蛛形纲生物身上提取的毒液。林度恩询问这东西是从哪儿来的。"}},faq={{q="在哪里可以找到毒液瓶？",a="它们就在辛特兰的枯木村里，数量很多。",al={"毒液瓶位置","哪里能找到毒液瓶","枯木毒液"}},{q="谁对这些毒液瓶感兴趣？",a="建议是把样本带给塔伦米尔的一位药剂师，你需要找的是药剂师林度恩。",al={"谁想要毒液","在哪里上交毒液瓶","塔伦米尔药剂师"}},{q="瓶子里装的是什么？",a="一种邪恶的绿色毒液，考虑到枯木巨魔保留了这么多瓶子，他们似乎非常看重它。",al={"毒液是什么","瓶子里有什么"}}},fp="13,191,17.205.0,15.175.1,34.82.0,39.83.0,23.95.0"}
P.entries["quest:2934"] = {n="完好无损的毒囊",s="塔伦米尔的药剂师林度恩需要一份之前送来的那种毒液的新鲜样本，并让你去辛特兰猎杀那些能产生毒液的蜘蛛。时间很紧，因为它必须保持新鲜才能送达。",h="塔伦米尔的药剂师林度恩需要一份之前送来的那种毒液的新鲜样本，并让你去辛特兰猎杀那些能产生毒液的蜘蛛。时间很紧，因为它必须保持新鲜才能送达。",kw={"药剂师林度恩","辛特兰","沙德拉洛","蜘蛛毒液","塔伦米尔","毒液囊"},sec={{t="新鲜样本",b="在收集完“毒液瓶”后，药剂师林度恩想要一些更新鲜的东西。产出这种毒液的蜘蛛一定生活在辛特兰，他需要一个未受损的毒液囊。在巨魔城市沙德拉洛附近游荡着许多这样的蜘蛛。你不能浪费任何时间，因为毒液囊必须在送达时保持新鲜。林度恩急于用它进行实验，并已经订购了几只非常可爱的小动物来做测试。"}},faq={{q="是谁要求获取未受损的毒液囊？",a="塔伦米尔的药剂师林度恩要求获取它，并在那里等待交付。",al={"谁发布未受损的毒液囊任务","谁开启未受损的毒液囊任务","未受损的毒液囊任务发布者"}},{q="在哪里可以找到这些蜘蛛？",a="在辛特兰，在巨魔城市沙德拉洛附近可以找到许多蜘蛛。",al={"蜘蛛位置","蜘蛛在哪里","哪里可以找到未受损的毒液囊"}},{q="为什么药剂师林度恩说不能耽搁？",a="新鲜度至关重要，所以林度恩希望立即送达毒液囊。",al={"为什么有时间限制","为什么毒液囊会变质","未受损的毒液囊计时器"}},{q="这一步之前发生了什么？",a="它接在“毒液瓶”任务之后，在那个任务中，来自枯木村的毒液样本被送交给了林度恩。",al={"前置任务","未受损的毒液囊之前的任务是什么","未受损的毒液囊先决条件"}}},fp="19,155,14.332.0,37.85.0,31.79.0,43.72.0,27.95.0"}
P.entries["quest:2935"] = {n="请教加德林大师",s="药剂师林度恩发现，护巢者的毒液不如你最初带来的样本强效，这说明那份样本来自另一种蜘蛛。林度恩让你去杜隆塔尔的森金村，找可能了解更多情况的加德林大师。",h="药剂师林度恩发现，护巢者的毒液不如你最初带来的样本强效，这说明那份样本来自另一种蜘蛛。林度恩让你去杜隆塔尔的森金村，找可能了解更多情况的加德林大师。",kw={"药剂师林度恩","咨询加德林大师","杜隆塔尔","辛特兰","加德林大师","森金村","毒液","枯木"},sec={{t="寻找强效毒液",b="药剂师林度恩发现，从护巢者身上取得的毒液比你最初带来的样本弱，因此那份样本一定来自另一种蜘蛛。林度恩想要一份毒性更强的新鲜样本。要弄清它的来源，就去杜隆塔尔的森金村，询问一位十分了解枯木的巨魔：加德林大师。运气好的话，加德林能说出那种毒液的来源。"}},faq={{q="药剂师林度恩为什么让你去找加德林大师？",a="护巢者的毒液比最初的样本弱，这说明那份样本来自另一种蜘蛛。加德林是一位十分了解枯木的巨魔，或许能说出那种毒液的来源。",al={"为何咨询加德林","为何去森金村","林度恩 加德林"}},{q="加德林大师在哪里？",a="加德林大师在杜隆塔尔的森金村。",al={"加德林在哪","加德林大师位置","寻找加德林大师"}},{q="这趟旅程之前发生了什么？",a="在此之前，你从辛特兰带回了一个完好无损的毒囊，交给了药剂师林度恩。",al={"前置条件","此前发生了什么","前置任务"}}},fp="21,180,20.335.0,52.163.0,31.48.0,30.94.0"}
P.entries["quest:2937"] = {n="召唤沙德拉",s="加德林大师给你一张羊皮纸，要你在辛特兰的枯木领地深处，于沙德拉洛的祭坛上诵读，以召唤蜘蛛之神沙德拉。随后，你要将她的毒液带给塔伦米尔的药剂师林度恩。",h="加德林大师给你一张羊皮纸，要你在辛特兰的枯木领地深处，于沙德拉洛的祭坛上诵读，以召唤蜘蛛之神沙德拉。随后，你要将她的毒液带给塔伦米尔的药剂师林度恩。",kw={"药剂师林度恩","辛特兰","加德林大师","沙德拉","沙德拉洛","蜘蛛之神","塔伦米尔","枯木"},sec={{t="蜘蛛之神的召唤",b="加德林大师的羊皮纸需要在沙德拉洛的祭坛上诵读，那里位于辛特兰的枯木领地深处。这样就能召唤出蜘蛛之神沙德拉。你必须在那里击败她，并将她的毒液带给塔伦米尔的药剂师林度恩。"}},faq={{q="谁提供召唤沙德拉所需的羊皮纸？",a="加德林大师给你这张羊皮纸。",al={"谁提供召唤沙德拉任务","召唤沙德拉任务给予者"}},{q="在哪里召唤沙德拉？",a="在辛特兰的沙德拉洛祭坛，那里位于枯木领地深处。",al={"在哪里召唤沙德拉","沙德拉洛祭坛位置","沙德拉位置"}},{q="击败沙德拉后，要将毒液交给谁？",a="塔伦米尔的药剂师林度恩。",al={"毒液交给谁","召唤沙德拉任务交付","药剂师林度恩位置"}}},fp="16,93,22.237.0,44.38.0,25.95.0,47.80.0"}
P.entries["quest:2938"] = {n="送往幽暗城的毒药",s="药剂师林度恩对从枯木的蜘蛛之神身上取得的毒液十分满意，想把一份样本送到幽暗城的炼金房，交给他的上级法拉尼尔。你受托带着一个包裹上路。",h="药剂师林度恩对从枯木的蜘蛛之神身上取得的毒液十分满意，想把一份样本送到幽暗城的炼金房，交给他的上级法拉尼尔。你受托带着一个包裹上路。",kw={"炼金房","药剂师林度恩","法拉尼尔的包裹","大药剂师法拉尼尔","沙德拉","送往幽暗城的毒液"},sec={{t="强效毒液",b="林度恩只用一剂毒液就杀死了将近二十四只兔子。其中一些体形很小，抵抗力肯定不强，但这种毒液的威力毋庸置疑。林度恩确信法拉尼尔会想亲自试验，便交给你一个包裹，让你带到幽暗城的炼金房。"}},faq={{q="是谁把包裹寄往幽暗城？",a="药剂师林度恩在试验了从枯木的蜘蛛之神身上取得的毒液后，寄出了这个包裹。",al={"送往幽暗城的毒液任务由谁提供","送往幽暗城的毒液任务给予者","送往幽暗城的毒液任务由谁开启"}},{q="幽暗城里该由谁接收毒液？",a="林度恩的上级，大药剂师法拉尼尔，他在幽暗城的炼金房。",al={"谁接收包裹","毒液送到幽暗城哪里","法拉尼尔是谁"}},{q="毒液在试验中的威力有多强？",a="只用一剂就足以杀死将近二十四只兔子，不过其中一些兔子还很幼小。",al={"沙德拉毒液有多强","林度恩兔子试验"}},{q="这次递送之前是什么任务？",a="前一个任务是召唤沙德拉，毒液就是在那个任务中从蜘蛛之神身上取得的。",al={"送往幽暗城的毒液前一个任务","送往幽暗城的毒液前置任务"}}},fp="22,163,13.286.0,43.93.0,54.107.0,40.79.0,32.84.0"}
P.entries["quest:2939"] = {n="寻找知识",s="特洛亚斯·月风在菲拉斯的废墟瓦砾中发现了一根看似普通的法杖，但他总觉得事情没那么简单。他让你去找他在鲁瑟兰村的同事达蕾恩·轻风。",h="特洛亚斯·月风在菲拉斯的废墟瓦砾中发现了一根看似普通的法杖，但他总觉得事情没那么简单。他让你去找他在鲁瑟兰村的同事达蕾恩·轻风。",kw={"安格拉斯","达纳苏斯","达蕾恩·轻风","菲拉斯","废墟","鲁瑟兰村","法杖","特洛亚斯·月风"},sec={{t="一根普通的法杖",b="特洛亚斯·月风说菲拉斯的废墟虽然危险，但却隐藏着关于过去发生的许多事情的秘密。几天前，他在南边的瓦砾中搜寻时，偶然发现了一根看起来很普通的法杖，但他总觉得这根法杖大有来头。他和安格拉斯查阅了所有的书籍，却找不到关于它的一星半点记载。"},{t="达纳苏斯的同事",b="特洛亚斯在达纳苏斯有一位同事，也许能认出这根法杖。他让你去鲁瑟兰村找她，也就是达蕾恩·轻风。"},{t="达蕾恩的回复",b="达蕾恩抱怨说，特洛亚斯总是用他发现重要东西的荒唐念头来打扰她。在她看来，现在住在那些废墟里的食人魔或鹰身人大概早就把真正有价值的东西搬走了。她补充说，你可以在这儿四处看看，不过她怀疑这里的书能不能帮上忙。"}},faq={{q="是谁让你去找达蕾恩·轻风的？",a="特洛亚斯·月风，他想弄清楚他在菲拉斯废墟中发现的法杖到底是什么。",al={"谁开启了寻求知识的任务","任务发布者"}},{q="特洛亚斯发现了什么？",a="一根看起来很普通的法杖，是在特洛亚斯工作地点的南边瓦砾中发现的。他觉得事情没那么简单。",al={"特洛亚斯发现了什么","菲拉斯法杖"}},{q="达蕾恩·轻风在哪里？",a="在鲁瑟兰村。特洛亚斯说她是他在达纳苏斯的同事。",al={"达蕾恩·轻风的位置","达蕾恩在哪里"}},{q="特洛亚斯为什么要让你去找达蕾恩？",a="他和安格拉斯在书里找不到关于这根法杖的任何记载，或许达蕾恩能告诉他们这到底是什么东西。",al={"为什么要拜访达蕾恩·轻风","为什么去达纳苏斯"}}},fp="22,147,17.307.0,24.132.0,13.307.1,33.118.0,21.119.0,25.91.0,34.107.0"}
P.entries["quest:294"] = {n="奥莫尔的复仇",s="在维尔加挖掘场，奥莫尔·铁衣和两名同伴被困在迅猛龙肆虐的挖掘坑上方。矮人们在湿地地下挖出了巨大的史前骸骨，这番动静引来了成群的斑驳迅猛龙，杀死了大多数挖掘队员。",h="在维尔加挖掘场，奥莫尔·铁衣和两名同伴被困在迅猛龙肆虐的挖掘坑上方。矮人们在湿地地下挖出了巨大的史前骸骨，这番动静引来了成群的斑驳迅猛龙，杀死了大多数挖掘队员。",kw={"杂斑迅猛龙","杂斑尖啸龙","奥莫尔·铁衣","奥莫尔的复仇","勘察员维尔加","湿地","维尔加挖掘场"},ang={["class:Hunter"]="身为猎人，你可以在挖掘场外的山坡上，研究危险的斑驳迅猛龙如何在沼泽地形中追踪猎物。",["race:Dwarf"]="身为矮人，目睹同胞在探险者协会的挖掘行动中遇害，清剿这片迅猛龙盘踞的采石场便能成为捍卫祖先荣耀、伸张正义的复仇之举。"},sec={{t="掘出的恐怖",b="矮人们来到维尔加挖掘场，想要挖出湿地淤泥下巨大的史前遗骸。他们的发现将沼泽中土生土长的迅猛龙引到了挖掘场。成群的斑驳掠食者涌入营地，令挖掘队员猝不及防，在他们之中大肆杀戮。"},{t="悲愤的坚守",b="只有寥寥几个矮人在这场屠杀中幸存。奥莫尔·铁衣、麦琳·石纹和勘察员维尔加仓皇爬上挖掘坑上方的高崖，却仍被凶猛的龙群困在那里。奥莫尔悲痛而愤怒，却依然留下来保护麦琳和勘察员。他请求旅人清剿下方的杂斑迅猛龙和 杂斑尖啸龙，打响复仇的第一战。"}},faq={{q="这里的挖掘队员遭遇了什么？",a="矮人考古学家在盆地里挖出巨大的骸骨后，迅猛龙便占据了挖掘场。挖掘的动静引来了沼泽中的迅猛龙群；它们杀死了大多数队员，将三名幸存者困在高崖上。",al={"迅猛龙为何在这里","维尔加挖掘场惨案","什么杀死了矮人"}},{q="奥莫尔·铁衣是谁？",a="奥莫尔·铁衣是一名困在维尔加挖掘场的矮人挖掘者。他留下来保护惊魂未定的勘察员维尔加和麦琳·石纹，同时也想向杀死同伴的迅猛龙讨还血债。",al={"奥莫尔是谁","奥莫尔·铁衣的背景"}},{q="这些迅猛龙从哪里来？",a="杂斑迅猛龙和 杂斑尖啸龙 是湿地土生土长的掠食者。它们潜伏在挖掘场高崖西侧泥泞的山坡和沼泽中，也出没于通往挖掘场洞穴的小径沿途。",al={"杂斑迅猛龙 在哪里","湿地迅猛龙位置"}},{q="奥莫尔为什么不亲自猎杀迅猛龙？",a="奥莫尔渴望亲手杀死迅猛龙，但他必须保护勘察员维尔加和麦琳·石纹。他守在那里，确保这些惊恐的矮人在高崖上的藏身处不会被攻陷。",al={"奥莫尔为何不战斗","奥莫尔为何被困"}},{q="清剿这些迅猛龙就能了结奥莫尔的仇恨吗？",a="不能。杀死普通的杂斑迅猛龙和 杂斑尖啸龙，只是奥莫尔为死去的朋友复仇的第一步。接下来，他还会对迅猛龙群发动更猛烈的打击。",al={"奥莫尔的复仇就此结束了吗","奥莫尔接下来会怎样"}},{q="为什么挖出骸骨会引来迅猛龙？",a="湿地的迅猛龙是极具领地意识、生性凶猛的食腐动物。挖掘远古巨型遗骸扰动了这片盆地，将好奇而饥饿的掠食者引到了挖掘营地中央。",al={"骸骨为何引来迅猛龙","恐龙骸骨与迅猛龙"}}},fp="15,243,17.279.0,14.398.0,37.221.0,23.229.0,33.196.0,43.176.0,46.176.0,49.197.0"}
P.entries["quest:2940"] = {n="菲拉斯的历史",s="你发现了一本书，它看起来已经很久没人翻动过了，这可能正是特洛亚斯所需要的东西。这本书属于达蕾恩·轻风，所以你需要先询问是否可以借阅。",h="你发现了一本书，它看起来已经很久没人翻动过了，这可能正是特洛亚斯所需要的东西。这本书属于达蕾恩·轻风，所以你需要先询问是否可以借阅。",kw={"书","达蕾恩·轻风","菲拉斯","历史","寻求知识","传说","特洛亚斯"},sec={{t="一本被遗忘的书",b="书的封面磨损严重，纸页也已泛黄。仔细看过之后，你怀疑这正是特洛亚斯正在寻找的东西。你捡起了它，但转念一想，没经过允许就拿走并不妥当。这是达蕾恩·轻风的书，所以应该先问问她。"},{t="达蕾恩的答复",b="达蕾恩·轻风思考了一会儿。她同意让你借阅《菲拉斯：历史》，但前提是你得先帮她一个忙。"}},faq={{q="《菲拉斯：历史》是什么书？",a="一本封面磨损、纸页泛黄的书，看起来好像很久没人翻动过了。这可能正是特洛亚斯正在寻找的东西。",al={"这本书是什么","菲拉斯：历史之书","特洛亚斯的书"}},{q="谁拥有这本书？",a="达蕾恩·轻风。借阅之前你应该先征得她的同意。",al={"谁拥有菲拉斯：历史","谁有这本书","达蕾恩·轻风是谁"}},{q="在这之前的任务是什么？",a="它的前置任务是“寻求知识”，在那项任务中，特洛亚斯·月风让你去找达蕾恩·轻风谈谈关于他法杖的事。",al={"上一个任务","上一个任务是什么","任务前置"}}},fp="18,192,16.252.0,14.142.1,36.148.0,18.59.0,23.117.0"}
P.entries["quest:2941"] = {n="海龟照片",s="达蕾恩·轻风对辛特兰海滩上的钳嘴龟十分着迷，尤其是一只名叫加莫里塔的巨龟。她的研究让她无法脱身，于是她交给你一封信，让你带给塔纳利斯的克格尔·曲藤。",h="达蕾恩·轻风对辛特兰海滩上的钳嘴龟十分着迷，尤其是一只名叫加莫里塔的巨龟。她的研究让她无法脱身，于是她交给你一封信，让你带给塔纳利斯的克格尔·曲藤。",kw={"克格尔·曲藤","达蕾恩·轻风","加莫里塔","钳嘴龟","快照","超级摄影器fx","塔纳利斯","海龟照片"},sec={{t="加莫里塔的照片",b="达蕾恩·轻风说，她研究过许多课题，最近迷上了生活在辛特兰海滩上的钳嘴龟。她尤其想见一只名叫加莫里塔的巨型钳嘴龟。她本想亲自前往，但研究让她无法脱身，所以能有一张加莫里塔的照片也好。"},{t="寄往塔纳利斯的信",b="达蕾恩交给你一封信，让你带给塔纳利斯的克格尔·曲藤。克格尔为达蕾恩做了一件能拍下影像的发明，达蕾恩记得克格尔把这种影像叫作快照。"},{t="克格尔的反应",b="克格尔把你当成了达蕾恩的一名实习生，还称赞达蕾恩是一位学识渊博的历史学家。随后，克格尔便去取超级摄影器FX，认定你一定会喜欢它。"}},faq={{q="谁派你去塔纳利斯？",a="达蕾恩·轻风，她交给你一封信，让你带过去。她的研究让她无法亲自前往。",al={"任务给予者","谁提供海龟照片任务","达蕾恩·轻风"}},{q="克格尔·曲藤是谁？",a="一位身在塔纳利斯的人，为达蕾恩做了一件能拍下影像的发明，达蕾恩记得这种影像叫作快照。",al={"克格尔是谁","克格尔·曲藤的位置","克格尔 塔纳利斯"}},{q="达蕾恩为什么想要加莫里塔的照片？",a="达蕾恩对辛特兰海滩上的钳嘴龟十分着迷，尤其想见见加莫里塔。研究让达蕾恩无法前往，所以能有一张照片也好。",al={"加莫里塔 钳嘴龟","为什么是加莫里塔","巨型钳嘴龟"}},{q="加莫里塔是什么？",a="辛特兰海滩上的一只巨型钳嘴龟。",al={"加莫里塔是谁","加莫里塔"}}},fp="12,176,22.237.0,21.154.0,17.178.1,25.94.0,25.134.0,43.168.0,18.61.0"}
P.entries["quest:2942"] = {n="晨光石",s="当你从艾奎尼克斯巨石上取下神器的那一刻，艾奎尼克斯法杖的力量开始消散。你必须带着烁光之石和法杖回到羽月要塞，交给特洛亚斯·月风。",h="当你从艾奎尼克斯巨石上取下神器的那一刻，艾奎尼克斯法杖的力量开始消散。你必须带着烁光之石和法杖回到羽月要塞，交给特洛亚斯·月风。",kw={"艾奎尼克斯巨石","羽月要塞","菲拉斯","晨光石","烁光之石","艾奎尼克斯法杖","特洛亚斯·月风"},sec={{t="回到羽月要塞",b="当神器离开巨石时，法杖的能量开始消散。羽月要塞的特洛亚斯·月风急于知道你的发现，所以把烁光之石和法杖都带去给他。"},{t="特洛亚斯的发现",b="在你离开期间，特洛亚斯一直在研读，他将这块石头命名为“晨光石”。他还不确定它的用途，但像这样被隐藏在巨石之中的东西一定具有重大意义。他将继续他的研究，并希望你能支持他。"}},faq={{q="这个任务从哪里开始？",a="在艾奎尼克斯巨石处，一旦神器被取下即可开始。",al={"在哪里接这个任务","晨光石任务起始点","艾奎尼克斯巨石起始"}},{q="我该把石头带给谁？",a="带给羽月要塞的特洛亚斯·月风。记得把艾奎尼克斯法杖也带上。",al={"晨光石交予谁","特洛亚斯·月风在哪里","谁接收烁光之石"}},{q="艾奎尼克斯法杖会怎么样？",a="在神器从巨石上被取下的那一刻，它的能量就开始消散了。",al={"艾奎尼克斯法杖能量","法杖会发生什么","为什么法杖失去了力量"}},{q="这个任务之前的内容是什么？",a="它承接任务“艾奎尼克斯法杖”，在该任务中，你在巨石旁为法杖充能。",al={"前置任务","晨光石的前置任务是什么","任务先决条件"}}},fp="16,179,30.208.0,17.259.1,22.70.0,28.96.0,37.85.0,23.83.0"}
P.entries["quest:2943"] = {n="向特洛亚斯回复",s="达蕾恩·轻风交给你一本《菲拉斯：历史》，并嘱托你要妥善保管。这本书要送到羽月要塞的特洛亚斯·月风那里，他肯定已经迫不及待地想看到你回来了。",h="达蕾恩·轻风交给你一本《菲拉斯：历史》，并嘱托你要妥善保管。这本书要送到羽月要塞的特洛亚斯·月风那里，他肯定已经迫不及待地想看到你回来了。",kw={"达纳苏斯","达蕾恩·轻风","羽月要塞","菲拉斯","菲拉斯：历史","特洛亚斯·月风"},sec={{t="借阅的书籍",b="在你身后的是超级摄影器FX，达蕾恩·轻风交给你她的书，并要求你妥善保管。她催促你快点出发，确信特洛亚斯正盼望着你的归来。这本书是给羽月要塞的特洛亚斯·月风准备的。"},{t="特洛亚斯阅读",b="特洛亚斯很高兴你能把这本书带来。他翻看了一遍，快速浏览了书页，然后惊呼他想他已经找到了。"}},faq={{q="我送的是什么？",a="达蕾恩·轻风的书，《菲拉斯：历史》。",al={"这是什么书","我该带给特洛亚斯什么","菲拉斯：历史书籍"}},{q="特洛亚斯·月风在哪里？",a="在羽月要塞。",al={"特洛亚斯的位置","特洛亚斯·月风在哪里","我该去哪里"}},{q="是谁给你的书？",a="达蕾恩·轻风，她要你妥善保管它。",al={"谁发布的任务","任务发布者","达蕾恩·轻风"}},{q="在此之前发生了什么？",a="它是紧随“超级摄影器FX”之后的任务。",al={"上一个任务","我刚才做了什么","之前的任务链"}}},fp="16,130,15.222.0,12.134.1,21.62.0,27.47.0,23.65.0,22.39.0"}
P.entries["quest:2944"] = {n="超级摄影器FX",s="克格尔·曲藤准备好了一款新的拍照装置，名叫超级摄影器FX，并把它交给你试用。拍摄对象是加莫里塔，一只来自辛特兰的生物。拍到她的照片后，你将照片和装置一起带给鲁瑟兰村的达蕾恩·轻风。这项任务接续The Borrower。",h="克格尔·曲藤准备好了一款新的拍照装置，名叫超级摄影器FX，并把它交给你试用。拍摄对象是加莫里塔，一只来自辛特兰的生物。拍到她的照片后，你将照片和装置一起带给鲁瑟兰村的达蕾恩·轻风。这项任务接续The Borrower。",kw={"克格尔·曲藤","达蕾恩·轻风","加莫里塔","鲁瑟兰村","照片","超级摄影器fx","辛特兰"},sec={{t="试用新装置",b="完成The Borrower后，克格尔·曲藤向你展示了自己的新发明，超级摄影器FX。使用方法很简单：对准想拍摄的对象，然后按下按钮。克格尔把它交给你试用。"},{t="拍摄对象",b="拍摄对象是加莫里塔，一只来自辛特兰的生物，你曾向克格尔提起过她。克格尔祝你顺利找到她，并期待达蕾恩·轻风会喜欢这张照片。拍好后，你要将照片和装置一起交给鲁瑟兰村的达蕾恩。"}},faq={{q="谁会给我超级摄影器FX？",a="克格尔·曲藤将这件新发明交给你，让你试用。",al={"谁提供超级摄影器","克格尔任务给予者","哪里获取超级摄影器fx"}},{q="用超级摄影器FX拍摄什么？",a="加莫里塔，一只来自辛特兰的生物。克格尔祝你顺利找到她。",al={"加莫里塔位置","加莫里塔在哪里","加莫里塔照片"}},{q="照片要交给谁？",a="鲁瑟兰村的达蕾恩·轻风。你要将照片和装置一起带给她。",al={"交付超级摄影器fx","照片交到哪里","达蕾恩·轻风是谁"}},{q="这条任务线的下一步是什么？",a="这条任务线接下来是向特洛亚斯回复。",al={"超级摄影器的后续任务","超级摄影器fx之后是什么"}}},fp="20,229,16.183.0,11.261.0,31.56.0,47.90.0,26.80.0,29.42.0"}
P.entries["quest:2945"] = {n="脏兮兮的戒指",s="在诺莫瑞根受辐射的废墟深处，冒险者可以从黑铁矮人入侵者身上获得一件包裹着厚厚有毒污垢和硬泥的珠宝。要发现它的真实身份，需要使用位于宿舍区的工业清洗自动化装置——超级清洁器 5200。一旦清洗干净，戒指就会显露出个人标记，从而开启一段归还或重铸这件传家宝的旅程。",h="在诺莫瑞根受辐射的废墟深处，冒险者可以从黑铁矮人入侵者身上获得一件包裹着厚厚有毒污垢和硬泥的珠宝。要发现它的真实身份，需要使用位于宿舍区的工业清洗自动化装置——超级清洁器...",kw={"清洁区","黑铁矮人","宿舍区","诺莫瑞根","污损的戒指","戒指的回归","超级清洁器 5200"},ang={["profession:Engineering"]="超级清洁器 5200是典型奇特侏儒工程学的典范，将工业溶剂刷洗与自动礼品包装机结合在了一起。",["race:Dwarf"]="这枚戒指出现在潜入的黑铁矮人身上，暗示着这是在诺莫瑞根陷落的混乱中，从铁炉堡或侏儒受害者那里搜刮来的战利品。",["race:Gnome"]="即使在城市陷落的灾难性时刻，侏儒们设计出的卫生装置在完成危险的工业清洗循环后，依然会发出愉快的钟声并系上蝴蝶结。"},sec={{t="污垢下的遗物",b="诺莫瑞根的走廊里满是毒泥、油污和放射性尘埃，因此在战斗中掉落的物品被覆盖上一层坚硬的污泥也就不足为奇了。潜入城市的黑铁矮人经常携带弄得非常脏的饰品，其中最主要的就是这枚污损的戒指。这层污垢太硬了，普通的洗涤根本无法清除，让人完全看不清戒指底下的金属到底是铜、金还是废铁。"},{t="超级清洁器 5200",b="要清洗戒指，必须在Clean Zone宿舍找到Sparklematic 5200。这台机器是侏儒工程学的杰作，其设计极其荒谬有趣：它接受硬币，对严重污损的物品进行剧烈的内部冲刷，最后将其清洗得光亮如新，并用礼品盒精美包装，还系上蝴蝶结。洗掉辐射污泥后，戒指内环显露出城市的印章和刻有的首字母缩写，将一件捡来的饰品变成了一个归还的任务。"}},faq={{q="在哪里可以找到污损的戒指？",a="污损的戒指可以从诺莫瑞根这个被围困的副本里遇到的黑铁矮人尸体中获得。",al={"戒指掉落","污损的戒指在哪里掉落","谁掉落污损的戒指"}},{q="如何清洗戒指？",a="将戒指带到位于诺莫瑞根清洁区宿舍的超级清洁器 5200处。放入戒指并支付所需的硬币费用，即可启动强力自动清洗程序，去除硬化的污垢。",al={"清洗戒指","如何清洗污损的戒指","在哪里清洗戒指"}},{q="戒指清洗后会发生什么？",a="超级清洁器会弹出一个包装整齐的盒子，里面装着一枚带有独特个人刻印的复原戒指。这标志着任务“戒指的回归”的开始，引导你去寻找它的原主人。",al={"污损的戒指后续任务","清洗后的戒指做什么","超级清洁器戒指结果"}},{q="部落玩家能完成这个任务吗？",a="可以。部落冒险者可以使用超级清洁器 5200来清洗戒指。但是，任务链的后续步骤会有所不同，最终会将部落玩家引导至奥格瑞玛的一位工程师处，而不是将其归还给铁炉堡。",al={"污损的戒指是联盟专属吗","部落污损的戒指","部落可以清洗戒指吗"}},{q="为什么清洗后戒指会被包在礼品盒里？",a="超级清洁器 5200的设计带有典型的侏儒奇思妙想。除了强力刷洗污泥和垢物外，该装置还被编程为在处理完成后自动包装物品，并在上面系上装饰性的蝴蝶结。",al={"礼品包装的戒指","为什么超级清洁器有礼品盒"}},{q="有多台超级清洁器机器吗？",a="清洁区宿舍的墙边排列着几台超级清洁器装置，但只有一台能正确处理该戒指：即当你沿着楼梯进入时，靠近友善侏儒的那台。",al={"哪一台超级清洁器","超级清洁器 5200位置"}}},fx={["5abd59ba"]={q="为什么需要清洗脏兮兮的戒指？",a="你从倒下的黑铁矮人身上取下戒指时，它表面覆盖着厚厚一层已经硬化的放射性淤泥和洞穴污垢。透过污垢，依稀能看见贵金属与宝石的微光，但结成硬壳的残渣使它既无法佩戴，也无法仔细查看。只有将它洗净，才能看清它真正的工艺，判断它是否确有价值或用途。",al={"为什么清洗戒指","脏兮兮的戒指用途","为什么清洗脏兮兮的戒指"}},c5a1096d={q="脏兮兮的戒指是什么？",a="它看起来是一件贵重首饰，由一名入侵的黑铁矮人带入诺莫瑞根。它完全被带有辐射的工业污物覆盖，精致的金属工艺和镶嵌的宝石都藏在污垢之下，只有送入诺莫瑞根的自动清洁装置超级清洁器5200，才能重见天日。",al={"脏兮兮的戒指是什么","脏兮兮的戒指背景","这是什么戒指"}}},fp="20,180,24.283.0,21.283.1,43.51.0,26.150.0,39.190.0,38.158.0,53.138.0,41.168.0"}
P.entries["quest:2947"] = {n="戒指归来",s="在诺莫瑞根，一枚金戒指上的工匠印记将你引向铁炉堡。",h="在诺莫瑞根，一枚金戒指上的工匠印记将你引向铁炉堡。",kw={"闪亮的金戒指","黑铁","铁炉堡印章","秘法区","超级清洁器","塔瓦斯德·基瑟尔","特迪克"},ang={["faction:Alliance"]="身为联盟的一员，你可以从黑铁矮人持有的、带着铁炉堡印记的物品中，看出Emperor Thaurissan的爪牙对联盟山中家园日益加剧的威胁。",["race:Gnome"]="身为侏儒，在诺莫瑞根找到失落的手工艺品，让你难得有机会一窥族人在瑟玛普拉格酿成灾难之前从事的和平手艺。"},sec={{t="污泥包裹的珍宝",b="你将一件满是污垢的小饰物放进诺莫瑞根的超级清洁器 5200。机器清除了多年积累的辐射污垢，显露出一枚光洁的闪亮的金戒指，依然因奥术能量而嗡嗡作响。戒圈内侧刻着三个首字母“TdK”，旁边是铁炉堡的品质印章。"},{t="秘法区的工匠",b="塔瓦斯德·基瑟尔是铁炉堡秘法区的一名侏儒珠宝匠，他认出这枚戒指采用了自己在诺莫瑞根陷落前常用的一种设计。他工作时，常常还要应付想象中的讨债人。得知黑铁渗透者带着这枚戒指，他心中不安，也不禁疑惑，那座失落之城的地下究竟有什么在蠢蠢欲动。"}},faq={{q="在诺莫瑞根找到的戒指是谁制作的？",a="首字母“塔瓦斯德·基瑟尔”代表塔瓦斯德·基瑟尔，他是铁炉堡秘法区的一名侏儒珠宝匠。诺莫瑞根陷落前，他曾在那里经营一家珠宝店，并按这种设计制作过几枚简单的魔法戒指。",al={"戒指是谁制作的","戒指首字母塔瓦斯德·基瑟尔","塔瓦斯德·基瑟尔是谁"}},{q="这枚戒指最初来自哪里？",a="这枚戒指来自诺莫瑞根深处，被发现时还是一件裹满污垢的小饰物，由黑铁矮人等敌对入侵者携带。超级清洁器 5200让它重现了金色光泽，也显露出了工匠印记。",al={"戒指发现地点","戒指来自哪里"}},{q="黑铁矮人为什么会带着塔瓦斯德的戒指？",a="塔瓦斯德也不清楚，黑铁渗透者为什么会带着他过去的作品。这枚戒指可能来自他废弃的作坊，也可能是从某个未能逃离诺莫瑞根入侵的人身上夺来的。",al={"黑铁为什么持有戒指","黑铁戒指背景故事"}},{q="塔瓦斯德·基瑟尔为什么以为你是他的房东？",a="塔瓦斯德神经紧张，性情古怪，还经常拖欠铁炉堡的房租。陌生人气势汹汹地走近他的店铺时，他就以为是执达员或房东来追讨欠债了。",al={"塔瓦斯德为什么疑神疑鬼","塔瓦斯德房租"}},{q="塔瓦斯会制作受诅咒的珠宝吗？",a="塔瓦斯坚称，他不会制作受诅咒的物品，试图让有意购买的顾客放心。他紧张的否认往往没能消除疑虑，反而引出了更多疑问。",al={"塔瓦斯德受诅咒了吗","铁炉堡受诅咒的珠宝"}},{q="我可以留下戒指，不归还吗？",a="这枚戒指具有魔法力量，而它的制作者可以检查它，并提出进一步加工，强化它的附魔。",al={"留下戒指","是否应该归还戒指"}}},fx={["8e194cce"]={q="为什么超级清洁器5200想让你归还戒指？",a="它并没有这个想法。超级清洁器 5200是一台自动清洁装置，专门处理从诺莫瑞根深处回收、裹满污垢的物品。放进去什么，它就清洗什么，然后吐出清理干净的物件。机器吐出抛光后的闪亮的金戒指后，你发现戒圈内侧印有制作者的标记和铁炉堡徽记，是否归还它，完全由你决定。",al={"为什么归还戒指","超级清洁器 5200的动机","机器为什么想让人归还戒指"}}},fp="18,80,24.278.0,30.338.1,38.204.0,40.217.0,51.190.0,55.197.0,33.143.0,49.121.0"}
P.entries["quest:2948"] = {n="侏儒的手艺",s="在铁炉堡，塔瓦斯德·基瑟尔愿意改良一枚他在诺莫瑞根打造的戒指。他需要银和苔藓玛瑙，在旧戒环上制作精巧的网状饰纹。",h="在铁炉堡，塔瓦斯德·基瑟尔愿意改良一枚他在诺莫瑞根打造的戒指。他需要银和苔藓玛瑙，在旧戒环上制作精巧的网状饰纹。",kw={"闪亮的金戒指","侏儒的手艺","诺莫瑞根","铁炉堡","苔藓玛瑙","银锭","塔瓦斯德"},ang={["faction:Alliance"]="身为联盟冒险者，你可以借助这座沦陷的都城与铁炉堡之间的联系，帮助来自诺莫瑞根的难民。",["profession:Mining"]="身为矿工，你可以提供Talvash制作珠宝所需的银和苔藓玛瑙。",["race:Gnome"]="身为侏儒，你能看出，即使流亡异乡、失去材料，Talvash仍以自己的手艺为荣。"},sec={{t="流亡的侏儒工匠",b="穴居人入侵和辐射导致诺莫瑞根陷落后，塔瓦斯德·基瑟尔逃离了那里。如今，这位侏儒难民住在铁炉堡的秘法区。这位珠宝匠兼修补匠手头拮据，材料也已耗尽，却决心证明自己的手艺在流亡中依旧精湛。"},{t="改良旧戒环",b="塔瓦斯德很高兴再次见到自己设计的朴素戒指，它已经过超级清洁器 5200清洗。然而，他觉得这枚旧戒环的样式已经过时。他愿意用银和苔藓玛瑙制成的网状饰纹来改良它，展示自己加工金属和宝石的技艺。"}},faq={{q="塔瓦斯德·基瑟尔是谁？",a="塔瓦斯德·基瑟尔是一位流亡铁炉堡的侏儒珠宝匠和工匠。诺莫瑞根陷落前，他在那里经营着一家小珠宝店。冒险者可以找回他打造的一枚戒指，并将它带到秘法区交给他。",al={"塔瓦斯德·基瑟尔","铁炉堡侏儒珠宝匠"}},{q="这枚等待改良的戒指有怎样的来历？",a="塔瓦斯曾在诺莫瑞根的店里打造过几枚朴素的戒指，这枚戒指就是其中之一。一名黑铁矮人将其中一枚带进了废墟，冒险者可以在那里找回它，并用超级清洁器 5200清洗。塔瓦斯愿意添上银和苔藓玛瑙制成的网状饰纹来改良它。",al={"戒指的来历","脏兮兮的戒指的来历"}},{q="塔瓦斯为什么要求玩家提供材料？",a="逃离诺莫瑞根后，塔瓦斯的材料已经用尽，手头也很拮据。他需要银和苔藓玛瑙来制作网状饰纹。",al={"为何需要银和苔藓玛瑙","塔瓦斯德为何没有材料"}},{q="这条任务线从哪里开始？",a="这条线索始于诺莫瑞根，冒险者可以从那里的敌人身上找到脏兮兮的戒指。用超级清洁器 5200将它洗净，再循着姓名首字母缩写“塔德基”，到铁炉堡寻找塔瓦斯。",al={"如何开始侏儒的手艺","戒指任务线起点"}},{q="塔瓦斯对自己在铁炉堡的处境心怀怨愤吗？",a="塔瓦斯感叹自己无端陷入经济困境，却依然保持着乐观和身为工匠的自豪。他相信，只要重新站稳脚跟，自己就会因打造最精美的饰品而名扬艾泽拉斯。",al={"塔瓦斯德的背景","塔瓦斯德的性格"}},{q="部落能接到这个任务吗？",a="不能。在诺莫瑞根清洗沾满污垢的物品后，部落冒险者会被指引去奥格瑞玛寻找诺格，而非前往铁炉堡寻找塔瓦斯。",al={"部落能否做侏儒的手艺","部落戒指改良"}}},fx={["2e3e2066"]={q="银锭有什么用？",a="塔瓦斯德需要这种精炼金属，把你原来的戒指改造成一件更精巧的首饰。他用银锭直接在戒圈上打造出细致的网格纹饰，让原本简单的设计比他早期的作品更加优雅，也更加坚固。",al={"为什么需要银锭","塔瓦斯德银锭","他需要银做什么"}},a02fa77a={q="苔藓玛瑙有什么用？",a="苔藓玛瑙是戒指改良后的核心装饰。塔瓦斯德打算将抛光的绿色宝石嵌入新制的银质网格纹饰，增添光彩，展现自己身为工匠的真正本领，把一件粗陋的小饰品变成远为出色的作品。",al={"为什么需要苔藓玛瑙","塔瓦斯德苔藓玛瑙","他需要玛瑙做什么"}}},fp="17,153,26.270.0,22.232.0,26.213.0,51.266.0,56.136.0,34.176.0,51.197.0,41.132.0"}
P.entries["quest:2949"] = {n="戒指归来",s="一枚来自诺莫瑞根的戒指上刻着奥格瑞玛的印记和字母NOG。它的线索指向地精工程师诺格，他对那片废墟有一个推测。",h="一枚来自诺莫瑞根的戒指上刻着奥格瑞玛的印记和字母NOG。它的线索指向地精工程师诺格，他对那片废墟有一个推测。",kw={"闪亮的金戒指","黑铁","诺莫瑞根","诺格","奥格瑞玛","归还戒指","超级清洁器 5200","荣誉谷"},ang={["faction:Horde"]="身为部落的一员，你很少能在东部王国首屈一指的科技中心深处发现部落的标志。这枚戒指引着你从卡兹莫丹来到荣誉谷。",["profession:Engineering"]="身为工程师，你知道奥格瑞玛的地精发明家总会拿侏儒的发明来衡量自己的本事。对于从侏儒那座已成废墟的科技奇观中找回的任何东西，诺格都急于一探究竟。"},sec={{t="奇特的发现",b="你用Sparklematic 5200清洗了一枚来自诺莫瑞根的戒指。机器清除了污垢，显露出奥格瑞玛的官方印记、一股涌动的魔法力量，以及依稀可辨的字母NOG。诺莫瑞根坐落在卡兹莫丹腹地，是一座远离部落首都的联盟城市。这枚戒指可能是在卡利姆多打造的，也可能是被一支遭遇不幸的远征队带到那里的，但它的印记将线索引回了奥格瑞玛。"},{t="侏儒的竞争与黑铁的阴谋",b="你带着戒指，来到奥格瑞玛的荣誉谷寻找诺格。这位地精工程师说戒指不是他的，不过它的来历引出了疑问。地精向来把侏儒发明家视为古怪的对手。诺格怀疑侏儒窃取并修改了黑铁的魔像设计图。既然这枚戒指曾在诺莫瑞根内由黑铁矮人持有，他认为他们可能正在寻求报复，这条线索值得调查。"}},faq={{q="为什么在诺莫瑞根发现的戒指上会有奥格瑞玛的印记？",a="没人确切知道这枚戒指是如何来到诺莫瑞根的。黑铁矮人把它带进了废墟深处，后来它在那里被寻回。戒指上的奥格瑞玛印记，将它与杜隆塔尔的部落金属工匠和手艺人联系了起来。",al={"为何有奥格瑞玛印记","诺莫瑞根的部落戒指","戒指如何到达那里"}},{q="诺格是谁？",a="诺格是奥格瑞玛荣誉谷的一名地精工程师。他负责管理工程物资和机器，而他的名字恰好与清洗后的戒指上那些磨损的字母相符。",al={"诺格是谁","诺格 奥格瑞玛","诺格字母戒指"}},{q="超级清洁器 5200是什么？",a="超级清洁器 5200是诺莫瑞根清洁区内的一套自动工业清洗系统。它能清除从废墟走廊里带出的物品上厚厚的有毒淤泥和辐射。",al={"超级清洁器是什么","超级清洁器 5200","超级清洁器"}},{q="戒指是诺格的吗？",a="不是。诺格检查了清洗后的戒指，说它不是自己的。他认出了戒指的制作工艺，并运用自己的工程技术为你进一步改造了它。",al={"戒指是诺格的吗","诺格是否丢了戒指","戒指属于谁"}},{q="诺格认为诺莫瑞根发生了什么？",a="诺格怀疑侏儒从黑铁氏族窃取了先进的魔像设计图。他认为黑铁会想要报复，觉得这条线索值得调查。",al={"诺格对诺莫瑞根的推测","诺莫瑞根发生了什么","为何是黑铁矮人"}},{q="可以留下戒指，不把它归还给诺格吗？",a="你可以立即戴上戒指，也可以把它带到奥格瑞玛。将戒指带给诺格，这位地精工程师就能检查它的制作工艺，并为它提供进一步的改良。",al={"留下闪亮的金戒指","是否应该归还戒指","是否必须交给诺格"}}},fx={["9392e9ce"]={q="为什么超级清洁器5200想让你归还戒指？",a="超级清洁器 5200没有自己的意志或动机，它只是诺莫瑞根内的一台自动清洁装置，负责刷去回收物品上的污垢，再将清理后的东西吐出来。它洗净你那枚裹满污垢的戒指，再用包装好的盒子将其送出后，工作就结束了。发现戒圈内侧刻着奥格瑞玛徽记和残缺字母后，决定追查那些姓名首字母的来历，完全是出于你自己的好奇。",al={"超级清洁器的动机","超级清洁器为什么要归还戒指","超级清洁器 5200的目标"}}},fp="18,140,19.394.0,37.391.1,63.203.0,12.163.0,30.193.0,23.151.1,44.169.0,52.157.0"}
P.entries["quest:295"] = {n="奥莫尔的复仇",s="“奥莫尔的复仇”是联盟的一项任务，由湿地维尔加挖掘场的奥莫尔·铁衣发布。随着最初的迅猛龙侦察兵被清理干净，奥莫尔要求屠杀那些将他的探险队赶出挖掘场的更强壮的斑点镰爪龙和剃刀龙。",h="“奥莫尔的复仇”是联盟的一项任务，由湿地维尔加挖掘场的奥莫尔·铁衣发布。随着最初的迅猛龙侦察兵被清理干净，奥莫尔要求屠杀那些将他的探险队赶出挖掘场的更强壮的斑点镰爪龙和剃刀龙。",kw={"矮人","挖掘","探险者协会","斑点剃刀龙","斑点镰爪龙","奥莫尔·铁衣","迅猛龙","湿地","维尔加挖掘场"},ang={["class:Hunter"]="湿地的斑点迅猛龙是领地意识极强的群体猎手，在封闭、泥泞的战壕中带来了致命的追踪挑战。",["faction:Alliance"]="收复维尔加挖掘场可以确保连接湿地到阿拉希高地的东部道路上的作业安全。",["race:Dwarf"]="奥莫尔的愤怒反映了探险者协会强烈的自豪感，他们拒绝让野兽永久阻碍矮人挖掘他们祖先历史的努力。"},sec={{t="升级狩猎",b="奥莫尔·铁衣对那些在维尔加挖掘场横行霸道的迅猛龙怀恨在心，这是他个人的恩怨。在清理了那些占领了上层营地的幼龙后，他让你去对付那些在底层挖掘场潜伏的成年捕食者。这些斑点镰爪龙和剃刀龙对任何重建考古工作的希望构成了核心威胁，它们撕碎了矮人勘察员，在战壕中留下了破碎的板条箱和废弃的十字镐。"},{t="战壕中的鲜血",b="挖掘坑实际上已经变成了迅猛龙的巢穴。当奥莫尔在俯瞰挖掘场的山脊上沉思时，他指引有能力的冒险者进入泥潭，直接打击那些成熟的野兽。虽然勘察员维尔加和他的船员希望抢救古代遗物，但奥莫尔完全被复仇冲昏了头脑，要求在考虑对付该区域的顶级恐怖生物之前，先清点一大批死掉的镰爪龙和剃刀龙。"}},faq={{q="为什么奥莫尔对这些迅猛龙如此愤怒？",a="斑点迅猛龙暴力涌入并占领了维尔加挖掘场，赶走了矮人团队，并屠杀了所有没能及时逃脱的人。奥莫尔·铁衣流离失所且满心苦涩，他拒绝让这些野兽在不付出血的代价的情况下控制挖掘场。",al={"奥莫尔为何愤怒","奥莫尔复仇原因","为什么要在湿地猎杀迅猛龙"}},{q="在哪里可以找到斑点镰爪龙和剃刀龙？",a="这两种迅猛龙都在维尔加挖掘场的下层战壕和周围的土方工程中出没，该挖掘场位于湿地米奈希尔港以东，丹莫德以西。",al={"斑点镰爪龙位置","斑点剃刀龙位置","在哪里找到奥莫尔的目标迅猛龙"}},{q="奥莫尔·铁衣是谁？",a="奥莫尔·铁衣是一位驻扎在维尔加挖掘场的矮人探险者协会成员。在挖掘场遭受灾难性的入侵后，他将消灭困扰他们工作的迅猛龙群作为自己的个人使命。",al={"奥莫尔是谁","奥莫尔·铁衣背景故事"}},{q="清理这些迅猛龙后会发生什么？",a="一旦你清理了镰爪龙和剃刀龙，奥莫尔就会将注意力转向萨尔托斯，他认为这只大型迅猛龙是当地龙群的首领，并指引你去终结迅猛龙入侵的根本源头。",al={"奥莫尔的复仇之后做什么","奥莫尔的复仇后续任务","清理镰爪龙后的下一个任务"}},{q="这个任务与其他挖掘场的任务有关联吗？",a="是的。当冒险者为奥莫尔在整个下层挖掘场猎杀迅猛龙时，他们经常会协助勘察员维尔加和他的团队完成“揭示过去”任务，收集散落在同一战壕中的破碎土灵遗物。",al={"维尔加挖掘场任务","与揭示过去任务的联系"}},{q="矮人们最初为什么要在这里挖掘？",a="铁炉堡的探险者协会建立了维尔加挖掘场，以寻找泰坦遗物并揭示矮人种族的古老历史，但当具有攻击性的野生动物占领了挖掘场后，他们的行动被迫停止了。",al={"为什么在湿地挖掘","维尔加挖掘场目的"}}},fp="15,217,19.338.0,21.341.0,39.256.0,54.188.0,23.214.0,41.196.1,62.208.0,53.217.0"}
P.entries["quest:2950"] = {n="诺格的手艺",s="在奥格瑞玛，诺格正着手改进一枚从诺莫瑞根找回的戒指。他索要稀有材料和有关黑铁矮人的情报，急于证明地精工艺胜过侏儒设计。",h="在奥格瑞玛，诺格正着手改进一枚从诺莫瑞根找回的戒指。他索要稀有材料和有关黑铁矮人的情报，急于证明地精工艺胜过侏儒设计。",kw={"闪亮的金戒指","黑铁","诺莫瑞根","地精工程学","苔藓玛瑙","诺格","奥格瑞玛","银锭"},ang={["faction:Horde"]="身为部落的一员，你可以将诺莫瑞根这类与联盟结盟的殿堂中的技术带给奥格瑞玛的工匠，让部落了解敌人的实力。",["profession:Engineering"]="身为工程师，你能看到地精的巧思与侏儒的奇巧装置之间的较量。地精会大刀阔斧地改造现有装置，以充分发挥它们的潜力。",["profession:Mining"]="身为矿工，你可以通过采矿和宝石切割，帮助提供诺格所需的珍贵材料：一块精炼的银锭和一颗苔藓玛瑙。"},sec={{t="地精的优越技艺",b="你将一枚从诺莫瑞根带回并清洗干净的金戒指送到诺格位于荣誉谷的工坊。这位地精工程师看了一眼戒指上平平无奇的侏儒工艺，便提出了一笔交易。只要带来原材料，再付上一小笔费用，他就会用银和苔藓玛瑙为戒圈加上一层精巧的网格，以增强戒指内的魔力。"},{t="矮人的线索",b="诺格提出这笔交易，背后的用意并不只是做生意。有关黑铁矮人出现在那座遭到围困的侏儒城市中的报告引起了他的注意。在诺格看来，他们的出现或许能解释侏儒的机械技艺为何会突然突飞猛进，毕竟地精一向认为这是自己的专长。你提供的情报为你换来了一枚改进后的戒指，也让诺格勉强认可了你。"}},faq={{q="诺格是谁？",a="诺格是一名地精工程师，在奥格瑞玛的荣誉谷工作。他与暗巷区和荣誉谷的其他工匠一同研究从危险远征中带回的奇特机械造物和结构图。",al={"诺格是谁","诺格 奥格瑞玛","诺格 非玩家角色"}},{q="重铸戒指需要哪些材料？",a="诺格需要原来的闪亮的金戒指、一块银锭、一颗苔藓玛瑙，以及三十枚银币，作为他的工钱和工坊开销。",al={"戒指材料","诺格 材料","诺格需要什么"}},{q="诺格为什么对诺莫瑞根感兴趣？",a="诺莫瑞根拥有极高的技术价值。地精与侏儒在技术领域竞争激烈，而传闻称，黑铁矮人与这座沦陷的科技之城内部的技术异常有关，这引起了诺格的兴趣。",al={"诺格为何关注诺莫瑞根","诺莫瑞根 地精的兴趣"}},{q="诺格究竟对戒指做了什么？",a="诺格用银和苔藓玛瑙在金戒圈外构筑了一层网格。这层框架能够引导并稳定戒指内的魔法，使它比原本的侏儒设计更加强大。",al={"戒指升级背景","戒指有何变化"}},{q="这条任务线从哪里开始？",a="这条任务线始于诺莫瑞根深处。你从一名黑铁矮人身上找到一枚脏兮兮的戒指，然后用超级清洁器 5200机器将它清洗干净。",al={"任务线起点","如何开始诺格的任务","戒指任务线起点"}},{q="诺格为什么怀疑黑铁矮人？",a="地精工程师并不信任侏儒的创新能力。诺格怀疑，侏儒机械技艺的任何突然飞跃都源于外来势力的干预，尤其是诡计多端的黑铁氏族。",al={"为何怀疑黑铁","黑铁矮人的关联"}}},fp="16,182,18.310.0,15.290.1,12.216.0,46.144.0,37.215.0,39.182.0,34.140.0,40.171.0"}
P.entries["quest:2951"] = {n="超级清洁器5200型！",s="在诺莫瑞根的深处，火花机5200是一台在混乱中依然能够正常运转的自动清洁设备。只要往里投入从地下大厅中拾获的脏兮兮的东西，并支付一笔象征性的费用，冒险者就能将回收到的饰品、宝石和废料恢复到崭新的状态。它是侏儒工程学持久的独创性与怪异性的鲜活证明。",h="在诺莫瑞根的深处，火花机5200是一台在混乱中依然能够正常运转的自动清洁设备。只要往里投入从地下大厅中拾获的脏兮兮的东西，并支付一笔象征性的费用，冒险者就能将回收到的饰品、宝石和废料恢复到崭新的状态。它是侏儒工程学持久的...",kw={"清洁器","侏儒","诺莫瑞根","脏兮兮的","机器","回收","火花机","火花机5200","穴居人"},ang={["faction:Alliance"]="对于在诺莫瑞根大厅中冒险的联盟回收小队来说，这台机器提供了一种在将回收的遗物带回铁炉堡之前对其进行清洗的即时方法。",["profession:Engineering"]="工程师们会欣赏这种坚固的电机和分类架构，它能在不卡壳或爆炸的情况下清洁和处理未知的碎片。",["race:Gnome"]="这台机器反映了经典的侏儒韧性：即使在灾难性的家园撤离期间，商业活动和闪耀的清洁工作依然在不间断地进行。"},sec={{t="污垢中的灯塔",b="在诺莫瑞根饱受辐射沉降物和穴居人侵扰的困境中，一小群幸存的侏儒在他们的非凡发明——火花机5200附近维持着一条安全防线。这台坚固的装置旨在清除回收贵重物品上附着的恶劣地下污垢，它承诺要让一切“重焕光彩”。即使地下怪物不断撞击着舱壁，这台机器依然时刻准备着进行商业运作。"},{t="疯狂的运作",b="这种清洁机制绝非温和。一旦冒险者投入了一件沾满污垢的遗物并支付三枚银币，火花机就会陷入猛烈的搅动状态。整个铁制装置会发出呻吟、剧烈震动，并左右摇晃，将有毒的淤泥、受辐射的油脂和岩石粉尘剥离。片刻之后，它便会吐出埋藏在污垢之下的物品，从珍贵的矿物到机械零件应有尽有。"}},faq={{q="什么是火花机5200？",a="火花机5200是一台位于诺莫瑞根安全区域的侏儒自动清洁装置。它的设计初衷是去除从沦陷的城市各处回收的物品上那顽固的放射性油脂、淤泥和污垢。",al={"火花机5200的作用","火花机装置","诺莫瑞根清洁机器"}},{q="这台机器需要什么才能运作？",a="操作火花机需要一件在诺莫瑞根的怪物和碎片中发现的“脏兮兮的东西”，以及直接投入机器投币口的三枚银币作为处理费。",al={"如何使用火花机","火花机费用","火花机投入什么"}},{q="为什么战区中间会有这样一台可以运作的机器？",a="侏儒文明建立在自动化的家庭和工业便利设施之上。当穴居人入侵和有毒气体通风口摧毁了这座城市时，幸存的侏儒退守到了加固的车间里，像火花机这样的机器在那里得以保持完好并持续供电。",al={"为什么火花机会在这里","谁把火花机放进了诺莫瑞根"}},{q="清洁脏兮兮的东西后会得到什么？",a="机器会退还给你完全洗去污垢的回收物品，其中可能包含埋在淤泥下的有用贸易物资、制造石、宝石或备用的工程学零件。",al={"从火花机能得到什么","火花机掉落","脏兮兮的东西奖励"}},{q="我可以使用火花机5200不止一次吗？",a="是的。在最初的演示运行之后，只要你提供更多的脏兮兮的东西和银币，就可以通过持续的清洁任务反复使用该装置。",al={"火花机是否可重复使用","可以清洗多个脏兮兮的物品吗","更多火花机相关信息"}},{q="为什么清洁时机器会剧烈晃动？",a="诺莫瑞根内部附着的污垢密度大、毒性强且已经硬化。这台机器依靠高速搅动和内部刷洗装置来切除污垢，导致整个底盘在运作时发生晃动并发出呻吟。",al={"火花机晃动","火花机坏了吗"}}},fx={["3b5f4e4c"]={q="超级清洁器 5200为什么想完成这件事？",a="超级清洁器 5200并非有意识的生物，而是一台自动化侏儒设备，制造它只有一个商业目的：为付费顾客清洗污垢包裹的贵重物品。正如它的黄铜铭牌所宣传的那样，它能将从诺莫瑞根受污染的厅堂中找回的破损遗物洗刷干净，只收取三枚银币。只要投入合适的燃料和钱币，它就会执行程序，除此之外并无私心。",al={"超级清洁器为什么需要物品","超级清洁器 5200的用途","为什么给超级清洁器投入东西"}},["757f94ef"]={q="脏兮兮的东西有什么用途？",a="脏兮兮的东西可能是回收的侏儒科技零件、矿石或私人饰品，被遍布诺莫瑞根的有毒淤泥和辐射覆盖，已经无法辨认。在这种污秽的状态下，它毫无用处，真实面目也无从知晓。将它投入超级清洁器5200，就能洗去带有辐射的污泥和腐蚀性积垢，显露出藏在下面的贵重装备、珍贵宝石或废金属。",al={"什么是脏兮兮的东西","脏兮兮的东西的用途","为什么保留脏兮兮的东西"}}},fp="22,160,21.270.0,18.308.0,30.198.0,41.141.0,64.236.0,53.167.0,47.125.0,56.162.0"}
P.entries["quest:2952"] = {n="超级清洁器5200型！",s="在诺莫瑞根饱受辐射的大厅深处，坐落着闪光机器5200型。这是一种自动清洁装置，旨在清除回收废料上的有毒污垢。操作这台机器可以洗去污损物品上的厚重积垢，并将回收的物品包装成精美的礼盒。",h="在诺莫瑞根饱受辐射的大厅深处，坐落着闪光机器5200型。这是一种自动清洁装置，旨在清除回收废料上的有毒污垢。操作这台机器可以洗去污损物品上的厚重积垢，并将回收的物品包装成精美的礼盒。",kw={"清洁","装置","净化","诺莫瑞根","污垢","机器","闪光机器"},ang={["profession:Engineering"]="研究闪光机器可以让人一窥自动颗粒清洁和快速包装机制，这些机制经过精心设计，能够经受住强烈的环境辐射。",["race:Gnome"]="闪光机器是沦陷前家园的鲜明写照：即使是一个工业清洗装置，也必须发出欢快的叮当声，并将成品像生日礼物一样包装好交付。"},sec={{t="自动清洁",b="侏儒工程学向来推崇效率与奇思妙想并重。闪光机器5200型被制造出来用以处理有毒和受污染的废弃物，通过自动循环清除污垢和腐蚀性残留物。一旦放入物品并支付费用，该装置就会在发出嘈杂声的过程中完成清洁流程，随后发出愉快的叮当声，将剩下的残余物整齐地包裹进系着蝴蝶结的礼物中。"},{t="污泥中的宝藏",b="自诺莫瑞根沦陷于穴居人手中，随后发生辐射灾难以来，无数个人物品和技术残骸都被工业泥沼所掩埋。将脏兮兮的东西投入机器的冒险者们，可以找回在城市排气时被吞没的遗失宝石、原生矿石以及早已失传的贵重物品。"}},faq={{q="闪光机器5200型有什么用？",a="闪光机器5200型是诺莫瑞根内部的一台自动清洁机器。当提供脏兮兮的东西和一定费用时，它会清除污泥、污垢和放射性废料，并将清洁后的物品装在一个小礼盒中返还。",al={"什么是闪光机器5200型","闪光机器如何工作","闪光机器功能"}},{q="闪光机器5200型位于哪里？",a="该机器位于沦陷城市诺莫瑞根的内部走廊，靠近曾经有幸存者和自动净化系统运作的清洁区。",al={"闪光机器位置","清洁机器在哪里","找到闪光机器"}},{q="为什么机器会把物品包上蝴蝶结？",a="它的程序设计带有典型的侏儒式奇思妙想。即使在洗去了物品上危险的放射尘埃和有毒污垢后，其创造者也将最终循环设计为将修复后的物品包装成令人愉悦、打结整齐的礼物。",al={"为什么是礼盒","闪光机器包装礼物","系着蝴蝶结"}},{q="部落的冒险者可以使用闪光机器5200型吗？",a="可以。闪光机器5200型是一台全自动装置，不在乎阵营偏见。只要有访客投入钱币和污损的物品，机器就会执行其循环。",al={"部落闪光机器","部落可以清洁污垢吗","闪光机器是中立的吗"}},{q="我可以使用多次闪光机器吗？",a="可以。在首次操作后，机器会解锁一个可重复的任务，允许任何在地下城中发现脏兮兮的东西的人反复对其进行处理。",al={"闪光机器可以重复使用吗","闪光机器的更多用途","刷脏兮兮的东西"}},{q="这个任务之后会发生什么？",a="完成这次初始清洁后，会直接开启名为“闪光机器的更多用途”的可重复清洁循环，让你能够清洁随身携带的任何其他脏兮兮的东西。",al={"闪光机器后续任务","闪光机器5200型之后是什么"}}},fx={["1a7da75f"]={q="超级清洁器 5200为什么需要脏兮兮的东西？",a="超级清洁器 5200没有个人野心——它是侏儒工程学创造的自动化奇迹，专门用于清洗和修复回收物品。它建于诺莫瑞根陷落之前，程序设定的功能是洗去厚厚的放射性污泥和碎屑，再将剩下的东西装进整洁的包裹，交给使用者。",al={"超级清洁器为什么需要这个","超级清洁器 5200的用途","为什么清洗脏兮兮的东西"}}},fp="22,164,19.252.0,22.257.0,35.204.0,39.157.0,41.174.0,48.134.0,42.171.0,30.140.0"}
P.entries["quest:2953"] = {n="再次使用超级清洁器",s="在诺莫瑞根的辐射废墟深处，矗立着“闪光机器5200型”，这是一款在城市大撤离时留下的自动化清洁设备。只需支付少量的银币，这台机器就能卖力地把覆满在这座陨落首都内的污垢和放射性淤泥中的可回收物品刷洗干净。",h="在诺莫瑞根的辐射废墟深处，矗立着“闪光机器5200型”，这是一款在城市大撤离时留下的自动化清洁设备。只需支付少量的银币，这台机器就能卖力地把覆满在这座陨落首都内的污垢和放射性淤泥中的可回收物品刷洗干净。",kw={"自动化","清洁机器","清洁","诺莫瑞根","布满污垢的","闪光机器"},ang={["profession:Engineering"]="操作该设备可以让工程师亲眼见证强健的侏儒溶剂循环系统和投币启动的自动化功能。",["race:Gnome"]="闪光机器是侏儒机械耐用性的证明，在你们家园的有毒废墟中依然可靠地运作着。"},sec={{t="自动修复",b="闪光机器5200型代表了侏儒在穴居人入侵和随后的放射性尘埃蔓延之前，在诺莫瑞根各处安装的巧妙自动化设施。尽管走廊里充斥着有毒废料和敌对的自动装置，但只要投下三枚银币并放入一件布满污垢的文物，这台装置依然会一丝不苟地执行它的预设程序。"},{t="淤泥中的奇迹",b="当启动时，闪光机器会剧烈晃动，同时用强效的侏儒清洁溶剂冲洗和刷洗放入其中的圣物。清洗周期结束后，机器会发出一声欢快的提示音，并吐出一个包装整齐的盒子，里面装着从腐蚀性的穴居人黏液和有毒污垢下保存下来的回收品。"}},faq={{q="什么是闪光机器5200型？",a="闪光机器5200型是位于诺莫瑞根内部的侏儒自动化清洁设备。它可以清除回收物品上的腐蚀性淤泥、污垢和放射性残渣，使其恢复为可辨认的回收品。",al={"闪光机器5200型","机器的作用","诺莫瑞根清洁器"}},{q="为什么机器需要支付钱币？",a="闪光机器需要三枚银币才能启动清洗周期。其收费的具体原因并未说明。",al={"为什么要付银币","闪光机器费用"}},{q="可以放入什么样的物品？",a="该机器专门清洁布满污垢的物品，包括从死去的穴居人、腐化的哨兵以及游荡在诺莫瑞根隧道中的辐射怪物身上回收的圣物。",al={"脏兮兮的东西","我可以清洗什么物品"}},{q="闪光机器免受辐射影响吗？",a="虽然外围隧道中充满了放射性废料，但闪光机器5200型依然保持运转，部署专业的侏儒清洁剂来刷掉进入机器内部的物品表面危险的残留物。",al={"闪光机器辐射","闪光机器污染"}},{q="两个阵营都能使用闪光机器5200型吗？",a="是的。闪光机器5200型是一台完全机械化的自动化装置，以中立方式运行，无论访客阵营如何，都会接受支付和布满污垢的物品。",al={"部落闪光机器","谁能使用它"}},{q="谁设计了闪光机器？",a="其制造者没有被提及。闪光机器是一款仍在诺莫瑞根内部工作的侏儒清洁机器。",al={"闪光机器制造者","谁建造了闪光机器"}}},fx={["9d072b2b"]={q="为什么需要启动超级清洁器5200？",a="超级清洁器 5200是一台自动化侏儒设备，唯一的用途就是洗去受污染装备上厚重的地下污泥和工业积垢。身为机器，它没有宏大的野心，也没有隐秘的利害牵扯；它只是静静等待适当的费用和脏兮兮的东西，以便启动清洗程序，送出修复后的物品。",al={"为什么启动超级清洁器","超级清洁器的动机","为什么使用超级清洁器 5200"}}},fp="24,191,21.313.0,21.282.0,30.201.0,34.103.0,40.158.0,40.180.0,44.149.0,30.100.0"}
P.entries["quest:2954"] = {n="石头卫士",s="你带着白金圆盘前往塔纳利斯沙漠，诺甘农的石之守护者已经出现在奥丹姆基座处。它守卫着通往奥丹姆建筑群的入口，只允许那些圆盘组合中包含奥丹姆圆盘的人进入。在继续前进之前，你得先了解它的故事。",h="你带着白金圆盘前往塔纳利斯沙漠，诺甘农的石之守护者已经出现在奥丹姆基座处。它守卫着通往奥丹姆建筑群的入口，只允许那些圆盘组合中包含奥丹姆圆盘的人进入。在继续前进之前，你得先了解它的故事。",kw={"创造者","奥丹姆圆盘","白金圆盘","诺甘农的石之守护者","塔纳利斯","奥达曼","奥丹姆","奥丹姆基座"},sec={{t="基座处的守护者",b="当你带着白金圆盘被派往塔纳利斯沙漠时，守护者的出现正是所期望的反应。它自称为入口的守卫，除非奥丹姆圆盘已经与你的圆盘组合整合，否则它不会让你进入奥丹姆建筑群。在进一步行动之前，你需要找出石之守护者背后的故事，然后使用奥丹姆基座。"},{t="守护者的解释",b="石之守护者在那里代表创造者控制谁可以进入奥丹姆建筑群，只让那些展示了正确序列圆盘的人进入。奥丹姆圆盘是创造者制作的圆盘，存储了他们在奥丹姆的活动数据。它们的大小与你自己的圆盘几乎相同，但它们的标记关注的是奥丹姆而非奥达曼。奥丹姆是一个研究设施，创造者在那里工作以增强艾泽拉斯的生物圈，而他们工作的细节是为那些持有圆盘的人准备的。最后，守护者承诺，一旦你访问基座，你的圆盘就会被归还，而且一旦你的组合中有这些圆盘，你就可以进入建筑群。"},{t="守护者提供的更多信息",b="石之守护者补充说，创造者控制着这个世界所有建筑群的这些圆盘的分配，并且艾泽拉斯已经被重新安排了访问计划。每当来自外部或内部的力量破坏了这些世界的矩阵动态平衡时，创造者就会利用访问来重新建立对已播种世界的控制，这绝非儿戏。"}},faq={{q="诺甘农的石之守护者是谁？",a="一位守卫着塔纳利斯沙漠中奥丹姆基座的入口守护者，负责决定谁可以进入奥丹姆建筑群。",al={"什么是石之守护者","奥丹姆的守护者是谁","石之守护者的身份"}},{q="为什么石之守护者拒绝进入？",a="只有当奥丹姆圆盘已经与你的圆盘组合整合时才允许进入，而你目前还没有这些圆盘。",al={"为什么我无法进入奥丹姆","缺失奥丹姆圆盘","奥丹姆拒绝进入"}}},fp="17,183,26.264.0,25.593.1,21.356.2,38.113.0,38.116.0"}
P.entries["quest:296"] = {n="奥莫尔的复仇",s="在湿地，奥莫尔的复仇始于一个要求：杀死萨尔图斯。奥莫尔·铁衣认为，正是这头迅猛龙带领兽群袭击了维尔加挖掘场，屠杀了那里的矮人挖掘工，并请你带回它的一只利爪作为证明。",h="在湿地，奥莫尔的复仇始于一个要求：杀死萨尔图斯。奥莫尔·铁衣认为，正是这头迅猛龙带领兽群袭击了维尔加挖掘场，屠杀了那里的矮人挖掘工，并请你带回它的一只利爪作为证明。",kw={"探险者协会","奥莫尔·铁衣","迅猛龙","萨尔图斯","利爪","湿地","维尔加挖掘场"},ang={["class:Hunter"]="身为猎人，你将面对湿地最顶尖的掠食者之一。敏锐的追踪技巧将指引你登上山脊，找到兽群首领。",["faction:Alliance"]="身为联盟的一员，你帮助保障矮人探险队在沼泽地中的安全，守住铁炉堡与北方大地之间的联盟据点。",["race:Dwarf"]="身为矮人，为在维尔加挖掘场惨遭屠杀的探险者协会队员复仇，就是向国王麦格尼死去的子民致敬。"},sec={{t="直取兽群首领",b="探险者协会的挖掘工在维尔加挖掘场遭到屠杀后，奥莫尔·铁衣便在山脊上观察那些迅猛龙。其中一头野兽比其他同类都要庞大。萨尔图斯盘踞在挖掘场上方，奥莫尔看见它在那里指挥或带领兽群，将矮人赶了出去。在奥莫尔眼中，萨尔图斯不只是一头野兽。他认为，正是它带头袭击了国王麦格尼·铜须的子民。"},{t="湿地的公道",b="奥莫尔要求以死亡偿还这场屠杀的血债。他派你沿着挖掘场岩壁旁的高处小径上行，杀死萨尔图斯。带回这头迅猛龙的一只骇人利爪，死去的工人便能大仇得报。奥莫尔要让这片沼泽知道，袭击矮人探险队，必将付出代价。"}},faq={{q="萨尔图斯是谁？",a="萨尔图斯是一头体型庞大、凶猛骇人的迅猛龙，统领着湿地维尔加挖掘场的兽群。奥莫尔·铁衣认为，正是萨尔图斯指挥了那场屠杀矮人挖掘工的袭击。",al={"萨尔图斯是什么","迅猛龙首领是谁","萨尔图斯的故事"}},{q="萨尔图斯在哪里？",a="萨尔图斯在维尔加挖掘场西北角、沿西侧岩壁延伸的高处小径上游荡。",al={"寻找萨尔图斯","萨尔图斯在哪里刷新","萨尔图斯的路线"}},{q="奥莫尔为什么要杀死萨尔图斯，而不只是把它赶走？",a="奥莫尔认为，迅猛龙的袭击是对国王麦格尼子民犯下的罪行。矮人工人在劳作时丧命，奥莫尔相信，唯有杀死萨尔图斯，才能告慰死者的在天之灵。",al={"奥莫尔复仇的原因","为什么杀死萨尔图斯"}},{q="奥莫尔需要什么证明？",a="奥莫尔要求带回萨尔图斯的一只利爪，证明这头庞大的掠食者已被杀死。",al={"击杀萨尔图斯的证明","萨尔图斯的利爪"}},{q="挖掘场的遇难者都是些什么人？",a="遇难者是探险者协会派去发掘泰坦神器的矮人考古学家和劳工。迅猛龙群冲入挖掘场，杀了他们一个措手不及，将他们屠戮殆尽。",al={"谁死在维尔加","挖掘场的遇难者"}},{q="杀死萨尔图斯就能确保挖掘场安全吗？",a="杀死萨尔图斯，便能除去兽群中最致命的威胁，为死者复仇。迅猛龙仍在沟壑间四处游荡，挖掘场依然危机四伏，几乎无人问津。",al={"维尔加现在安全吗","奥莫尔获胜了吗"}}},fp="15,195,27.390.0,23.296.0,17.180.0,27.109.0,68.194.0,30.90.0,44.193.0,50.181.0"}
P.entries["quest:2962"] = {n="更多的辐射尘！",s="在卡拉诺斯，奥齐·电环正为麻风侏儒寻找疗法。他需要一份来自诺莫瑞根深处的纯净辐射尘样本。",h="在卡拉诺斯，奥齐·电环正为麻风侏儒寻找疗法。他需要一份来自诺莫瑞根深处的纯净辐射尘样本。",kw={"诺恩","诺莫瑞根","齿轮大厅","卡拉诺斯","麻风侏儒","奥齐·电环","辐射","辐射尘"},ang={["faction:Alliance"]="作为联盟的一员，你可以学习如何应对威胁铁炉堡门户的致命危险，帮助稳定丹莫罗的局势，并夺回诺莫瑞根。",["profession:Engineering"]="作为一名工程师，你知道应对辐射需要坚固的铅制屏障和精密的仪器。诺莫瑞根展现了工程失误的代价。",["race:Gnome"]="作为一名侏儒，你心中承载着失去家园的悲痛。帮助奥齐弄清这些变异能否逆转，也就为拯救受难的同胞带来了一线希望。"},sec={{t="纯净的样本",b="奥齐·电环最初在诺莫瑞根外围进行的试验没能给他答案。丹莫罗的穴居人身上残留的辐射物质太少，而且并不纯净。如今，奥齐正在卡拉诺斯的实验室里，寻求一份来自城内深处的新鲜浓缩样本。他希望这能帮助他找到治疗麻风侏儒的方法。"},{t="直取源头",b="你需要从诺莫瑞根内部收集高强度的辐射尘。Hall of Gears和Clean Zone周围的底层深处，到处都是受到辐射的恐魔、潜伏者和软泥怪。它们体内不稳定的黏液必须装在厚重的铅制小瓶里，这项工作十分危险。辐射尘的效力会迅速减弱，因此你需要及时将它送到奥齐在卡拉诺斯的实验室。"}},faq={{q="奥齐为什么需要辐射尘？",a="奥齐·电环正在为麻风侏儒寻找疗法，诺莫瑞根沦陷时释放的辐射尘摧残了他们的身心。他相信，一份纯净的毒物样本或许能帮助逆转这种影响。",al={"奥齐·电环的疗法","为什么收集绿光","麻风侏儒的疗法"}},{q="玩家在哪里能找到辐射尘？",a="你可以从诺莫瑞根深处活着的受辐射恐魔、潜伏者和软泥怪身上收集辐射尘，尤其是在齿轮大厅周围和清洁区更深处。",al={"高强度辐射尘在哪里","诺莫瑞根辐射尘位置"}},{q="为什么地表穴居人的样本不合要求？",a="诺莫瑞根外围的穴居人受到的污染太少，采集到的样本也不纯净。它们无法为奥齐研究疗法提供可靠的材料。",al={"为什么不用穴居人","诺恩有什么问题"}},{q="为什么辐射尘有时间限制？",a="辐射尘很不稳定，即使装在铅制小瓶里，也会迅速失去效力。必须在它分解之前，将它送到奥齐在卡拉诺斯的实验室。",al={"辐射尘为什么会失效","辐射尘持续时间"}},{q="奥齐希望帮助的麻风侏儒是什么人？",a="麻风侏儒曾是诺莫瑞根的居民，当辐射阀门被打开以对付穴居人时，他们被困在城内。他们活了下来，却变得病弱而疯狂，开始敌视昔日的同胞。",al={"麻风侏儒背景故事","麻风侏儒是什么"}},{q="谁会交付这项任务？",a="奥齐·电环是一位侏儒研究员，常驻丹莫罗的卡拉诺斯。他请你收集辐射尘，希望找到办法医治诺莫瑞根灾难造成的创伤。",al={"谁提供任务","奥齐·电环位置"}}},fx={a4e93100={q="高强度辐射尘有什么用途？",a="奥齐·电环需要这些浓缩的辐射尘，来研究吞没诺莫瑞根的强烈辐射。他的最终目标是找到治愈麻风侏儒的方法，这些发生异变的同胞在灾难中身心都遭到了扭曲。先前从地表游荡的穴居人身上取得的样本强度太低，又受到杂质污染，无法得出有实际价值的科研结果，因此他需要直接从废城内部的生物身上取得强效、未经稀释的辐射样本。",al={"辐射尘有什么用途","高强度辐射尘的用途","奥齐要辐射尘的目的"}},["089f8395"]={q="你要在诺莫瑞根中猎杀哪些生物？",a="你受命从盘踞在诺莫瑞根中的辐射软泥怪、潜伏者和恐兽身上采集样本。这些可悲的软泥怪和变异生物是在城市陷落时释放的有毒辐射尘中直接形成的，吸收了大量高浓度的原始放射性废料。它们体内的辐射尘处于最纯净、最活跃的状态，因此直接从它们身上提取残留物，便能得到奥齐研究所需的未经稀释的高强度样本。",al={"什么是辐射软泥怪","获取辐射尘需要击杀什么","诺莫瑞根辐射尘生物"}}},fp="32,127,13.315.0,21.345.0,40.206.0,39.159.0,44.164.0,35.135.0,45.188.0,22.168.0"}
P.entries["quest:2969"] = {n="精灵龙的自由",s="恐怖图腾氏族正在捕捉精灵龙，而辛达尔·月纹和杰卡伊不知道他们的目的。辛达尔请求你带上强力的盟友，用一把钥匙打开恐怖图腾营地里的笼子，并确保这些精灵龙活着逃出去。辛达尔会随你一同前往，而杰卡伊会留在原地。",h="恐怖图腾氏族正在捕捉精灵龙，而辛达尔·月纹和杰卡伊不知道他们的目的。辛达尔请求你带上强力的盟友，用一把钥匙打开恐怖图腾营地里的笼子，并确保这些精灵龙活着逃出去。辛达尔会随你一同前往，而杰卡伊会留在原地。",kw={"竹笼","艾露恩","精灵龙","菲拉斯","恐怖图腾营地","杰卡伊","辛达尔·月纹","小精龙"},sec={{t="笼中龙",b="辛达尔·月纹称捕捉精灵龙的恐怖图腾氏族卑鄙无耻，并表示无论她还是杰卡伊都无法猜出他们的计划，只知道他们没安好心。他们两人没有足够的实力杀入营地，所以辛达尔向你求助。竹笼钥匙可以打开笼子，辛达尔希望这些精灵龙能活着逃离。欢迎带上强力的盟友。"},{t="辛达尔的瞭望点",b="你可以在恐怖图腾营地后方水面上方的岩架上找到辛达尔。沿着悬崖边的一条小路向上走就能到达那里。辛达尔会随你一同杀入营地，而杰卡伊则留在原地。"},{t="后续",b="一旦精灵龙获得自由，辛达尔会感谢艾露恩。危险尚未结束：被释放的龙并不一定能一直自由，所以辛达尔和杰卡伊打算向恐怖图腾发起反击。辛达尔让你去和杰卡伊谈谈。"}},faq={{q="谁在捕捉精灵龙？",a="根据辛达尔·月纹的说法，是恐怖图腾氏族。至于他们想要这些龙做什么，辛达尔和杰卡伊也说不清楚。",al={"谁捕捉了精灵龙","谁囚禁了精灵龙","恐怖图腾笼子"}},{q="辛达尔·月纹在哪里？",a="在恐怖图腾营地后方水面上方的岩架上。穿过营地左侧，沿着树后的一条小路爬上悬崖即可到达。",al={"辛达尔在哪里","辛达尔·月纹位置","如何找到辛达尔·月纹"}},{q="杰卡伊会一起去吗？",a="不会。杰卡伊留在原地，而辛达尔会随你一同前往。",al={"杰卡伊是否帮忙","杰卡伊的参与"}},{q="我需要什么来释放精灵龙？",a="竹笼钥匙。辛达尔会把这把钥匙交给你，用它就能打开恐怖图腾营地里的笼子。辛达尔希望你带上强力的盟友。",al={"竹笼钥匙","如何释放精灵龙"}},{q="这个任务之后是什么？",a="“伸张正义”是该系列任务的下一步。",al={"“众生平等”后续任务","拯救精灵龙之后的后续"}}},fp="25,205,18.379.0,16.179.0,9.200.1,36.136.0,27.163.0,24.53.0,42.122.0,24.39.0"}
P.entries["quest:297"] = {n="收集石像",s="在一处挖掘场，石腭怪紧攥着麦格玛尔·落斧寻找的雕刻神像。这些遗物让它们陷入了狂暴。",h="在一处挖掘场，石腭怪紧攥着麦格玛尔·落斧寻找的雕刻神像。这些遗物让它们陷入了狂暴。",kw={"狂暴","雕刻的石制神像","挖掘","收集神像","麦格玛尔·落斧","废墟","石腭怪"},ang={["faction:Alliance"]="身为联盟冒险者，你帮助矮人探险队收回危险的遗物，以免凶蛮的石腭怪造成更多破坏。",["race:Dwarf"]="身为矮人，你加入挖掘者的行列，在石腭怪出没的废墟中寻找古代文物及其蕴藏的秘密。"},sec={{t="出土的遗物",b="研究人员发现了一大批雕刻奇异的石制神像，不久后，凶蛮的石腭怪便从地下涌出，占领了挖掘场。袭击迫使探险队撤离废墟，正式研究还没来得及开始。如今，石腭怪攥着遗物，在挖掘场四处游荡，让探险队无法平安返回。"},{t="凶蛮的狂怒",b="石腭怪似乎深受神像影响，远不只是将它们据为己有。神像上的奇异雕刻散发着令人不安的力量，让这些生物陷入无法控制的暴怒。麦格玛尔·落斧希望能安全地研究神像，并平息笼罩这片地区的狂乱，因此想从石腭怪手中夺回它们。"}},faq={{q="麦格玛尔·落斧是谁？",a="麦格玛尔·落斧是一名挖掘者，正设法从一处被石腭怪占领的挖掘场收回雕刻的石制神像。",al={"麦格玛尔·落斧是谁","任务给予者","麦格玛尔"}},{q="这些雕刻的石制神像是什么？",a="这些神像是在一处挖掘场出土的神秘石雕遗物。它们令人不安的力量让附近的石腭怪陷入狂暴。",al={"雕刻的石制神像是什么","奇异的神像","出土的神像"}},{q="神像为什么会让石腭怪发狂？",a="神像对石腭怪有着一种奇异而无法解释的影响。这些生物一旦持有神像，就会被狂怒驱使，陷入疯狂。",al={"石腭怪为何发狂","神像让石腭怪发狂","石腭怪的狂怒"}},{q="麦格玛尔·落斧为什么要收集神像？",a="麦格玛尔·落斧希望安全地收回神像，以便研究它们的起源和特性，并将这些危险的遗物从石腭怪手中夺走。",al={"为何收集神像","收集神像的目的","麦格玛尔的研究"}},{q="挖掘场发生了什么？",a="神像被发现后不久，石腭怪突然从挖掘场的地下涌出。它们将挖掘者赶出了废墟。",al={"谁从挖掘场地下涌出","石腭怪入侵","挖掘场沦陷"}},{q="在哪里能找到神像？",a="在这些遗物最初出土的挖掘场，石腭怪随身带着雕刻的石制神像。",al={"哪里能找到神像","神像在谁手中","雕刻的石制神像位置"}}},fp="15,126,20.301.0,15.306.0,22.108.0,32.144.0,44.124.0,49.142.0,37.132.0,26.97.0"}
P.entries["quest:2970"] = {n="菲拉斯的正义",s="随着小精龙获得自由，耶尔卡·月纹和Kindal打算向恐怖图腾氏族发起反击。耶尔卡请求你消灭恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司，然后回来找他。此任务紧接“众生自由”。",h="随着小精龙获得自由，耶尔卡·月纹和Kindal打算向恐怖图腾氏族发起反击。耶尔卡请求你消灭恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司，然后回来找他。此任务紧接“众生自由”。",kw={"伸张正义","菲拉斯","恐怖图腾","耶尔卡·月纹","辛达尔·月纹","自然学家","劫掠者","萨满祭司"},sec={{t="反击恐怖图腾",b="在“众生自由”任务完成后，耶尔卡·月纹会告诉你，他和Kindal现在要对恐怖图腾发起反击。他们两人联手可以在几乎没有风险的情况下削减这些牛头人的数量，但他们依然欢迎你的帮助。你已经看到了下方营地的情况，在东边还有更多营地。用你自己的战术去对付恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司，然后回到耶尔卡等待的地方。"}},faq={{q="谁给予“伸张正义”？",a="在Kindal告诉你他们在拯救小精龙之后的打算后，位于菲拉斯的耶尔卡·月纹会给予此任务。",al={"谁给予伸张正义","伸张正义任务发布者","耶尔卡·月纹"}},{q="哪些恐怖图腾是目标？",a="恐怖图腾氏族牛头人中的恐怖图腾自然学家、恐怖图腾劫掠者和恐怖图腾萨满祭司。",al={"我需要击杀哪些敌人","伸张正义目标","击杀恐怖图腾"}},{q="恐怖图腾营地在哪里？",a="在耶尔卡下方就能看到一个营地，耶尔卡说在东边还有更多营地。",al={"恐怖图腾在哪里","恐怖图腾营地位置","我该去哪里"}},{q="“伸张正义”之前是什么任务？",a="“众生自由”，在那个任务中你从恐怖图腾营地解救了小精龙。",al={"前置任务","伸张正义先决条件","上一步骤"}}},fp="14,166,33.338.0,25.127.0,29.104.0,30.88.0,33.99.0"}
P.entries["quest:2972"] = {n="菲拉斯的正义",s="在荒野之中，耶尔卡·月纹和辛达尔没有太多东西可以用来表达谢意，所以耶尔卡递给你一枚图章戒指。你需要带着它去达纳苏斯的月神殿寻找泰兰德·语风，这枚戒指会告诉她他们二人一切安好，也能为你的故事增添可信度。此任务紧接在“执行正义”之后。",h="在荒野之中，耶尔卡·月纹和辛达尔没有太多东西可以用来表达谢意，所以耶尔卡递给你一枚图章戒指。你需要带着它去达纳苏斯的月神殿寻找泰兰德·语风，这枚戒指会告诉她他们二人一切安好，也能为你的故事增添可信度。此任务紧接在“执行正...",kw={"达纳苏斯","菲拉斯","耶尔卡·月纹","辛达尔·月纹","图章戒指","泰达希尔","月神殿","泰兰德·语风"},sec={{t="给大祭司的戒指",b="在菲拉斯的荒野中，耶尔卡·月纹和辛达尔能拿出来的东西不多，但他们不希望让你感到不受重视。耶尔卡递给你一枚图章戒指，并指引你前往达纳苏斯，大祭司泰兰德·语风正在那里的月神殿等待。这枚戒指将证明他们二人平安无事，也能印证你所讲述的故事。"},{t="泰兰德的答复",b="泰兰德很高兴你能帮助巨龙和她的一位祭司，并表示耶尔卡让你来找她是正确的。她承诺会将戒指归还给耶尔卡。斥候很快就会前往菲拉斯，到时候他们会顺便处理这枚戒指的事宜。"}},faq={{q="谁给的图章戒指？",a="菲拉斯的耶尔卡·月纹，作为他和辛达尔的谢礼。",al={"谁开启了这个任务","任务发布者"}},{q="图章戒指要送到哪里？",a="送到位于达纳苏斯月神殿的大祭司泰兰德·语风那里。",al={"我该把戒指带去哪里","任务交付地点","谁收到了耶尔卡的图章戒指"}},{q="为什么耶尔卡要给你这枚戒指？",a="耶尔卡和辛达尔在荒野中没有太多东西可以提供。这枚戒指可以向泰兰德证明他们一切安好，并为你的故事提供佐证。",al={"图章戒指的用途","为什么要给耶尔卡的图章戒指"}},{q="任务链的下一步是什么？",a="任务链继续进行，接下来是“寻找家园的孤儿”。",al={"后续任务","接下来要去哪里"}}},fp="14,177,29.298.0,16.283.1,26.89.0,30.91.0,35.121.0,29.54.0"}
P.entries["quest:2973"] = {n="新斗篷的光辉",s="克鲁伊格·碎颅与他的同伴们受奥格瑞玛的主人派遣，来到了菲拉斯。克鲁伊格打算为他的伴侣科琳制作一件披风，并请求你收集十枚虹彩小精龙之翼。",h="克鲁伊格·碎颅与他的同伴们受奥格瑞玛的主人派遣，来到了菲拉斯。克鲁伊格打算为他的伴侣科琳制作一件披风，并请求你收集十枚虹彩小精龙之翼。",kw={"莫沙彻营地","披风","仙女龙","菲拉斯","虹彩之翼","科琳","克鲁伊格·碎颅","小精龙"},sec={{t="科琳的披风",b="克鲁伊格与同伴们受奥格瑞玛的主人派遣，来到了菲拉斯。克鲁伊格的伴侣科琳喜欢新衣服，所以克鲁伊格计划用仙女龙精致的翅膀装饰一件披风。克鲁伊格想要的那种拥有美丽翅膀的小精龙栖息在莫沙彻营地的西边，他请求你收集十枚虹彩小精龙之翼。"},{t="克鲁伊格的警告",b="克鲁伊格提醒说，被激怒的小精龙很危险。他还告诫你要特别小心附近那些也喜欢藏在森林里的暗夜精灵。"}},faq={{q="克鲁伊格·碎颅是谁？",a="克鲁伊格·碎颅就在莫沙彻营地。他是受奥格瑞玛主人的派遣，与同伴一起来到菲拉斯的。",al={"克鲁伊格是谁","克鲁伊格·碎颅背景故事","菲拉斯的克鲁伊格"}},{q="为什么克鲁伊格需要小精龙之翼？",a="克鲁伊格打算为喜欢新衣服的伴侣科琳制作一件装饰有仙女龙翅膀的披风。",al={"为什么需要小精龙翅膀","小精龙之翼用途","克鲁伊格在做什么"}},{q="小精龙在哪里？",a="莫沙彻营地以西。",al={"去哪里找小精龙","小精龙位置","菲拉斯的仙女龙在哪里"}},{q="克鲁伊格警告了哪些危险？",a="克鲁伊格说被激怒的小精龙很危险，而且在森林里出没的暗夜精灵也需要格外留心。",al={"克鲁伊格的警告","菲拉斯森林中的威胁"}}},fp="19,154,18.293.0,15.145.0,27.110.0,40.101.0,37.45.0,35.146.0"}
P.entries["quest:2974"] = {n="可怕的发现",s="莫沙彻营地的克鲁伊格·碎颅听说你在菲拉斯遇到了牛头人，十分惊讶，得知他们属于恐怖图腾后更是如此。克鲁伊格的一位主人贝尔戈洛姆已经悬赏捉拿他们。克鲁伊格要你回去，给他带来二十只恐怖图腾的角。",h="莫沙彻营地的克鲁伊格·碎颅听说你在菲拉斯遇到了牛头人，十分惊讶，得知他们属于恐怖图腾后更是如此。克鲁伊格的一位主人贝尔戈洛姆已经悬赏捉拿他们。克鲁伊格要你回去，给他带来二十只恐怖图腾的角。",kw={"贝尔戈洛姆","莫沙彻营地","菲拉斯","恐怖图腾","犄角","克鲁伊格·碎颅"},sec={{t="恐怖图腾的消息",b="你向克鲁伊格·碎颅讲述了你在附近遇到的牛头人，克鲁伊格立刻指出他们属于恐怖图腾氏族。克鲁伊格的一位主人贝尔戈洛姆对他们颇感兴趣，并已悬赏捉拿他们。克鲁伊格告诉你，恐怖图腾不容小觑，而且他们十分邪恶。你返回那里，杀死他们，将二十只角带回莫沙彻营地，赶在他们夷平村庄或侵占土地之前先发制人。"},{t="交回犄角",b="克鲁伊格认为这些角很不错，并说你已经帮了两次忙。克鲁伊格一回到奥格瑞玛，就会把这件事告诉贝尔戈洛姆。"}},faq={{q="谁提供可怕的发现任务？",a="莫沙彻营地的克鲁伊格·碎颅，在你告诉他你在附近遇到了牛头人之后。",al={"谁提供可怕的发现任务","克鲁伊格·碎颅任务","可怕的发现任务提供者"}},{q="克鲁伊格为什么想要恐怖图腾的角？",a="克鲁伊格称恐怖图腾氏族十分邪恶，希望赶在他们夷平村庄或侵占土地之前发动攻击。奥格瑞玛的一位主人贝尔戈洛姆也已悬赏捉拿他们。",al={"为什么杀死恐怖图腾","恐怖图腾对菲拉斯的威胁","为什么要恐怖图腾的角"}},{q="贝尔戈洛姆是谁？",a="克鲁伊格说贝尔戈洛姆是他的主人之一，对恐怖图腾很感兴趣，并已悬赏捉拿他们。",al={"贝尔戈洛姆 奥格瑞玛","贝尔戈洛姆是谁"}},{q="克鲁伊格想要多少只角？",a="二十只恐怖图腾的角，交给莫沙彻营地的克鲁伊格。如果你办得到，克鲁伊格希望能收到成堆的角。",al={"恐怖图腾的角数量","需要多少只恐怖图腾的角"}},{q="可怕的发现之后是什么任务？",a="任务链接下来是可怕的发现 (2)。",al={"可怕的发现后续任务","可怕的发现任务链"}}},fp="16,170,21.358.0,19.126.1,27.97.0,36.175.0,15.108.0,31.113.0,30.52.0"}
P.entries["quest:2975"] = {n="菲拉斯的食人魔",s="莫沙彻营地的洛卡·奥赫想要在戈杜尼食人魔进一步向菲拉斯扩张之前将其击退。沿着北边的河流走就能找到他们的前哨站，你需要去那里削减食人魔、食人魔法师和蛮兵的数量。",h="莫沙彻营地的洛卡·奥赫想要在戈杜尼食人魔进一步向菲拉斯扩张之前将其击退。沿着北边的河流走就能找到他们的前哨站，你需要去那里削减食人魔、食人魔法师和蛮兵的数量。",kw={"蛮兵","莫沙彻营地","菲拉斯","戈杜尼","食人魔","食人魔法师","洛卡·奥赫"},sec={{t="戈杜尼的印记",b="洛卡·奥赫指出，戈杜尼食人魔部落在这附近非常显眼，他们的存在本身就是对这片土地的创伤。必须在他们深入菲拉斯之前将他们赶回去。他们的前哨站位于北面的河流上方。去那里杀掉十个戈杜尼食人魔、十个戈杜尼食人魔法师和五个戈杜尼蛮兵，让他们知道这里不欢迎他们。"}},faq={{q="谁想要击退戈杜尼食人魔？",a="莫沙彻营地的洛卡·奥赫。",al={"谁发布任务","任务发布者","洛卡·奥赫"}},{q="为什么洛卡·奥赫想要击退戈杜尼？",a="洛卡·奥赫说他们的存在本身就破坏了这片土地，必须在他们进一步扩张到菲拉斯之前阻止他们。",al={"为什么要杀食人魔","戈杜尼的动机","为什么要与戈杜尼战斗"}},{q="戈杜尼前哨站在哪里？",a="洛卡·奥赫说沿着北边的河流走，就能找到前哨站。",al={"食人魔前哨站位置","食人魔在哪里","菲拉斯的戈杜尼位置"}},{q="需要杀死哪些戈杜尼？",a="十个戈杜尼食人魔、十个戈杜尼食人魔法师和五个戈杜尼蛮兵。",al={"要杀多少食人魔","戈杜尼击杀计数"}},{q="这个任务后续是什么？",a="任务链后续是菲拉斯的食人魔（2）。",al={"下一个任务菲拉斯的食人魔","菲拉斯的食人魔任务链"}}},fp="20,114,24.292.0,41.63.0,49.102.0,30.52.0,29.73.0,24.50.0"}
P.entries["quest:2976"] = {n="可怕的发现",s="克鲁伊格·碎颅承认曾经提到过悬赏的事，并表示干活的人理应获得最好的报酬。这些角被装进一个板条箱让你带给贝尔戈洛姆·石槌，他在奥格瑞玛的荣誉谷，他会想听听你的讲述。这是在“残酷的发现”第一部分之后。",h="克鲁伊格·碎颅承认曾经提到过悬赏的事，并表示干活的人理应获得最好的报酬。这些角被装进一个板条箱让你带给贝尔戈洛姆·石槌，他在奥格瑞玛的荣誉谷，他会想听听你的讲述。这是在“残酷的发现”第一部分之后。",kw={"贝尔戈洛姆·石槌","悬赏","菲拉斯","恐怖图腾","角","克鲁伊格·碎颅","奥格瑞玛","荣誉谷"},sec={{t="装角的板条箱",b="在“残酷的发现”第一部分之后，克鲁伊格·碎颅先是吃了一惊，随即承认确实提到了悬赏。既然活是你干的，克鲁伊格觉得让你拿走最好的那份报酬是理所应当的。这些角被装进了一个板条箱交给你。这个板条箱要送去给位于荣誉谷的贝尔戈洛姆·石槌，他想知道你的见闻，并会让你的辛苦付出得到回报。"},{t="贝尔戈洛姆的兴趣",b="贝尔戈洛姆·石槌被关于恐怖图腾的消息所震惊，并询问你是否真的在菲拉斯的狩猎中遇到了他们。贝尔戈洛姆的同僚们也会想听这个故事，所以他让你在清点硬币的时候多讲一些。贝尔戈洛姆最后对你提供的情报表示了感谢。"}},faq={{q="是谁发布了“残酷的发现”的这一部分？",a="克鲁伊格·碎颅，他让人把角装进板条箱交给了你。",al={"谁发布残酷的发现","克鲁伊格·碎颅任务","残酷的发现2任务发布者"}},{q="恐怖图腾之角要送到哪里去？",a="送到贝尔戈洛姆·石槌那里，他在奥格瑞玛的荣誉谷等着。",al={"我该把角带去哪里","贝尔戈洛姆·石槌位置","残酷的发现2任务交还"}},{q="为什么悬赏归你？",a="克鲁伊格说活是你干的，所以最好的报酬理应归你。",al={"为什么是恐怖图腾之角","残酷的发现悬赏"}},{q="贝尔戈洛姆想要从你这里得到什么？",a="克鲁伊格说贝尔戈洛姆会很急切地想听听你的见闻，并会让你的辛苦付出得到回报。",al={"贝尔戈洛姆·石槌恐怖图腾","为什么要关心菲拉斯的恐怖图腾"}},{q="这一步之前是什么？",a="“残酷的发现”第一部分，在那一部分中，你带给了克鲁伊格恐怖图腾的角。",al={"残酷的发现任务链","残酷的发现2前置条件","前置任务"}}},fp="16,205,18.332.0,18.252.1,40.80.0,43.90.0,24.67.0,32.81.0,28.85.0"}
P.entries["quest:2978"] = {n="戈杜尼卷轴",s="一张沾满污渍的卷轴躺在戈杜尼前哨站，拾起后可以看到，上面似乎描绘着一场集会或仪式。莫沙彻营地的洛卡·奥赫会对它感兴趣，也会想知道它对戈杜尼意味着什么。",h="一张沾满污渍的卷轴躺在戈杜尼前哨站，拾起后可以看到，上面似乎描绘着一场集会或仪式。莫沙彻营地的洛卡·奥赫会对它感兴趣，也会想知道它对戈杜尼意味着什么。",kw={"莫沙彻营地","仪式","菲拉斯","戈杜尼前哨站","戈杜尼卷轴","食人魔","洛卡·奥赫"},sec={{t="沾满污渍的卷轴",b="拾起这张沾满污渍的卷轴，你看到上面似乎描绘着某种集会或仪式。你觉得，莫沙彻营地的洛卡·奥赫会想看看它，并弄清它对戈杜尼可能意味着什么。"}},faq={{q="戈杜尼卷轴上描绘了什么？",a="上面似乎描绘着某种集会或仪式。",al={"卷轴上描绘了什么","戈杜尼卷轴内容","卷轴图画"}},{q="谁想要戈杜尼卷轴？",a="莫沙彻营地的洛卡·奥赫。",al={"谁想要卷轴","卷轴交到哪里","交付戈杜尼卷轴"}},{q="在哪里能找到戈杜尼卷轴？",a="在戈杜尼前哨站，可以在那里拾取。",al={"戈杜尼卷轴在哪里","戈杜尼卷轴位置"}},{q="戈杜尼卷轴之后是什么任务？",a="任务链接下来是黑暗仪式。",al={"下一个任务是什么","戈杜尼卷轴之后","戈杜尼卷轴任务链"}}},fp="19,164,17.187.0,35.56.0,30.59.0,35.53.0,33.42.0"}
P.entries["quest:2979"] = {n="黑暗仪式",s="在你带回戈杜尼卷轴后，莫沙彻营地的洛卡·奥赫解读出这是戈杜尼法师领主们所策划的一场黑暗仪式的计划。洛卡·奥赫希望你能从其中一位法师领主手中夺取一颗宝珠，以便进一步了解这场仪式以及戈杜尼所使用的魔法。",h="在你带回戈杜尼卷轴后，莫沙彻营地的洛卡·奥赫解读出这是戈杜尼法师领主们所策划的一场黑暗仪式的计划。洛卡·奥赫希望你能从其中一位法师领主手中夺取一颗宝珠，以便进一步了解这场仪式以及戈杜尼所使用的魔法。",kw={"莫沙彻营地","黑暗仪式","菲拉斯","戈杜尼","戈杜尼宝珠","法师领主","洛卡·奥赫"},sec={{t="黑暗仪式的计划",b="洛卡·奥赫仔细研究了你带回的戈杜尼卷轴，将其解读为一场黑暗仪式的计划。据洛卡所知，是戈杜尼法师领主们在进行这场仪式。必须找到一位法师领主，并从他那里夺取一颗宝珠。法师的宝珠蕴含着巨大的力量，它应该能揭示更多关于这场仪式以及戈杜尼所操纵的魔法的信息。"},{t="当宝珠被送达时",b="一旦拿到宝珠，洛卡·奥赫说它将透露更多关于戈杜尼的信息，而这些知识将被用于策划他们的覆灭。"}},faq={{q="谁给予黑暗仪式任务？",a="莫沙彻营地的洛卡·奥赫，在你带回戈杜尼卷轴之后。",al={"谁给予黑暗仪式","黑暗仪式任务给予者"}},{q="谁在执行这场黑暗仪式？",a="洛卡·奥赫从计划中解读出，是戈杜尼法师领主们在执行仪式。",al={"谁在执行黑暗仪式","戈杜尼仪式领导者"}},{q="洛卡·奥赫想要什么样的宝珠？",a="一颗从戈杜尼法师领主手中夺取的宝珠。法师的宝珠蕴含着强大的力量，洛卡·奥赫希望能借此了解更多关于这场仪式和戈杜尼魔法的信息。",al={"为什么要获取戈杜尼宝珠","戈杜尼宝珠的目的"}},{q="黑暗仪式之后是什么？",a="该任务线接下来是戈杜尼宝珠。",al={"黑暗仪式后的下一个任务","黑暗仪式任务线"}}},fp="13,172,25.270.0,25.114.1,24.81.0,34.87.0,28.178.0,27.42.0"}
P.entries["quest:298"] = {n="挖掘进度报告",s="在铁环挖掘场，勘察员基恩萨·铁环需要你将他的公文和火药订购单送给塞尔萨玛的吉恩·角盔。",h="在铁环挖掘场，勘察员基恩萨·铁环需要你将他的公文和火药订购单送给塞尔萨玛的吉恩·角盔。",kw={"爆破火药","挖掘进度报告","探险者协会","吉恩·角盔","洛克莫丹","勘察员基恩萨·铁环","塞尔萨玛","穴居人"},ang={["faction:Alliance"]="身为联盟的一员，你帮助维持塞尔萨玛与洛克莫丹群山中偏远哨站之间的补给线畅通。",["profession:Mining"]="身为矿工，你知道，要炸开致密的基岩、掘进古老的地层，就需要可靠的爆破火药。",["race:Dwarf"]="身为矮人，你帮助铁环开展探险者协会的历史研究工作，并保护同胞免遭穴居人袭击。"},sec={{t="送往塞尔萨玛的公文",b="铁环的公文汇报了挖掘情况，并再次提出补给请求。挖掘工作需要镐、工人和用来炸开基岩的火药。铁环依靠信使向吉恩·角盔通报情况。"},{t="失踪的弹药",b="公文透露，凶暴的穴居人正在侵扰挖掘场。火药既能炸开岩石，也能炸飞穴居人。然而，铁环再次提出的请求让吉恩·角盔心生疑虑：他几周前就送出了一大批火药，不知这批货物在崎岖的山路上出了什么事。"}},faq={{q="谁将这份报告交给你？",a="勘察员基恩萨·铁环在洛克莫丹东南部丘陵的铁环挖掘场将报告交给你。他负责监督那里的考古挖掘工作。",al={"任务给予者","谁提供挖掘进度报告","铁环位置"}},{q="吉恩·角盔是谁？",a="吉恩·角盔是探险者协会驻塞尔萨玛的矮人联络员。他为遍布洛克莫丹的考古探险队协调补给和当地后勤事务。",al={"吉恩·角盔在哪里","收件人是谁","塞尔萨玛联络员"}},{q="勘察员基恩萨·铁环为什么需要更多爆破火药？",a="铁环需要爆破火药来清除坚硬的岩石，推进挖掘工作。挖掘场还到处都是敌对的穴居人，因此炸药对防御也很重要。",al={"为什么需要爆破火药","铁环要火药做什么"}},{q="上一批火药出了什么事？",a="吉恩·角盔几周前就送出了爆破火药，但这批货物始终没有抵达挖掘场。它的失踪表明，塞尔萨玛与偏远挖掘场之间的运输路线出了问题。",al={"火药去了哪里","失踪的爆破火药"}},{q="交付进度报告后，接下来要做什么？",a="了解铁环的处境和火药失踪的情况后，角盔派你前往铁炉堡，向他的上级汇报探险队的状况。",al={"后续任务","接下来是什么","向铁炉堡汇报"}},{q="穴居人为什么攻击挖掘场？",a="矮人的挖掘工作可能会揭开地下洞室，惊扰穴居人的巢穴。穴居人将矿工视为入侵者，成群袭击那些挖掘大地的人。",al={"穴居人攻击的原因","穴居人为什么憎恨铁环"}}},fx={["0b7d15ff"]={q="勘察员基恩萨·铁环为什么需要你递送报告？",a="勘察员基恩萨·铁环和其他挖掘者被穴居人接连不断的袭击困在了挖掘场。他的队员们忙于保卫考古成果、奋力求生，铁环无法抽出人手沿路返回塞尔萨玛。像你这样的外来旅者，正是能够迅速可靠地穿越危险荒野、替他传递消息的信使。",al={"为什么派我去","为什么不亲自去","为什么递送报告"}}},fp="26,133,23.204.0,17.267.1,29.150.0,21.160.0,51.159.0,49.173.0,50.144.0,45.147.0"}
P.entries["quest:2980"] = {n="菲拉斯的食人魔",s="莫沙彻营地的洛卡·奥赫确信你是一名真正的战士，便派你去营地西南方的高原荒野。在暗夜精灵曾经拥有的遗迹废墟中，戈杜尼食人魔正变得比以前更加强悍，必须将它们击退。此任务紧随“菲拉斯的食人魔”之后。",h="莫沙彻营地的洛卡·奥赫确信你是一名真正的战士，便派你去营地西南方的高原荒野。在暗夜精灵曾经拥有的遗迹废墟中，戈杜尼食人魔正变得比以前更加强悍，必须将它们击退。此任务紧随“菲拉斯的食人魔”之后。",kw={"莫沙彻营地","菲拉斯","戈杜尼","高原荒野","重锤者","洛卡·奥赫","萨满祭司","术士"},sec={{t="前往高原荒野",b="洛卡·奥赫认为你已经证明了自己是一名真正的战士，并委托你执行下一阶段的任务。高原荒野位于营地的西南方，那里有暗夜精灵曾拥有的废弃且破损的建筑。枯萎的树木和亵渎的土地表明了戈杜尼食人魔的所在地。洛卡警告说，这些食人魔比之前的那些要强悍得多。必须击杀十个戈杜尼萨满祭司、十个戈杜尼术士和五个戈杜尼重锤者。"}},faq={{q="谁派你去高原荒野？",a="莫沙彻营地的洛卡·奥赫。",al={"任务发放者","洛卡·奥赫","谁开启任务"}},{q="这些戈杜尼食人魔在哪里？",a="在莫沙彻营地西南方的高原荒野，围绕着暗夜精灵曾拥有过的破损建筑。枯萎的树木和亵渎的土地就是标志。",al={"食人魔在哪里","高原荒野位置","废墟位置"}},{q="必须杀死哪些食人魔？",a="十个戈杜尼萨满祭司、十个戈杜尼术士和五个戈杜尼重锤者。",al={"要杀谁","食人魔目标","戈杜尼类型"}},{q="这一步之前是什么？",a="第一阶段“菲拉斯的食人魔”，洛卡·奥赫在那时派你去对付北边前哨站的食人魔。",al={"前置条件","上一个任务","任务链顺序"}}},fp="20,189,24.423.0,37.38.0,25.183.0,27.80.0,28.85.0"}
P.entries["quest:2982"] = {n="高原荒野",s="安吉拉斯·月风和特洛亚斯一直在考察菲拉斯森林中的古老遗迹，但最近特洛亚斯开始独自前往高原荒野，这让安吉拉斯感到担忧。戈杜尼食人魔占据了那片土地。安吉拉斯希望你能通过铲除那些食人魔，让东南方的遗迹变得稍微安全一些。",h="安吉拉斯·月风和特洛亚斯一直在考察菲拉斯森林中的古老遗迹，但最近特洛亚斯开始独自前往高原荒野，这让安吉拉斯感到担忧。戈杜尼食人魔占据了那片土地。安吉拉斯希望你能通过铲除那些食人魔，让东南方的遗迹变得稍微安全一些。",kw={"安吉拉斯·月风","菲拉斯","戈杜尼","戈杜尼蛮兵","戈杜尼萨满祭司","戈杜尼术士","高原荒野","食人魔","特洛亚斯"},sec={{t="对特洛亚斯的担忧",b="安吉拉斯·月风承认这项工作很危险，但她和特洛亚斯一直都在考察散布在菲拉斯森林中的遗迹。最近，特洛亚斯独自前往高原荒野，这让安吉拉斯很担心。戈杜尼食人魔已经占领了那里，并且对进入其领地的任何人都不友善。安吉拉斯希望你能前往东南方的遗迹，铲除其中的一些食人魔，好让特洛亚斯的处境更安全些：击败八个戈杜尼术士、八个戈杜尼萨满祭司和八个戈杜尼蛮兵。"},{t="事成之后",b="一旦任务完成，安吉拉斯会非常感激，并请你不要向特洛亚斯透露半个字。"}},faq={{q="是谁让你去清理高原荒野的？",a="安吉拉斯·月风，她和特洛亚斯一起调查菲拉斯的遗迹。",al={"谁是安吉拉斯","安吉拉斯·月风","谁发布了高原荒野的任务"}},{q="为什么安吉拉斯想要消减戈杜尼食人魔的数量？",a="特洛亚斯一直独自前往高原荒野，这让安吉拉斯很担心。戈杜尼食人魔已经占据了该地区，并且不欢迎任何访客进入他们的领地。",al={"为什么要杀戈杜尼","为什么要杀高原荒野的食人魔","安吉拉斯的理由"}},{q="高原荒野的遗迹在哪里？",a="安吉拉斯指引你前往东南方的遗迹。",al={"高原荒野在哪里","高原荒野的位置","东南方的遗迹"}},{q="必须消灭哪些戈杜尼？",a="八个戈杜尼术士、八个戈杜尼萨满祭司和八个戈杜尼蛮兵。",al={"我在高原荒野要杀谁","高原荒野的戈杜尼目标"}},{q="关于戈杜尼的魔法有什么说法？",a="安吉拉斯警告说，戈杜尼的魔法似乎在摧残他们脚下的土地，并叮嘱你在他们附近时要保持警惕。",al={"戈杜尼的魔法","食人魔的法术","什么魔法造成了破坏"}}},fp="19,193,16.408.0,9.90.1,46.99.0,53.134.0,34.50.0,29.96.0,40.119.0"}
P.entries["quest:2985"] = {n="水之召唤",s="斯瓦特派遣一位萨满祭司从剃刀岭出发，前往贫瘠之地海岸寻找水之先知伊斯伦。大地与火焰已经考验过这位初学者；如今，水要求的是另一种领悟。",h="斯瓦特派遣一位萨满祭司从剃刀岭出发，前往贫瘠之地海岸寻找水之先知伊斯伦。大地与火焰已经考验过这位初学者；如今，水要求的是另一种领悟。",kw={"水之召唤","水之先知伊斯伦","棘齿城","剃刀岭","萨满祭司","怒水河","斯瓦特","贫瘠之地","水之图腾"},ang={["class:Shaman"]="身为萨满祭司，你从大地与火焰转向水的复苏之力，踏上通往治疗图腾的灵性之路。",["faction:Horde"]="身为部落的萨满祭司，你受指引前往贫瘠之地海岸寻找水之先知伊斯伦，与水沟通。"},sec={{t="元素的转变",b="剃刀岭的萨满祭司训练师斯瓦特，引导初学者认识各种元素。大地教会他们坚韧，火焰则考验他们的驾驭之力。当一位萨满祭司证明自己能够驾驭火焰而不被吞噬时，斯瓦特便认为他们已经准备好寻求水的教诲。"},{t="商旅海岸的隐士",b="水之先知伊斯伦住在贫瘠之地海岸，棘齿城更远处。要找到她，沿怒水河南下进入贫瘠之地，再向东前往一具巨大鲨鱼尸体附近的海岸。伊斯伦住在海浪与陆地交汇之处，远离杜隆塔尔城镇中的训练师。她引导部落与水沟通。"}},faq={{q="谁会给予这个任务？",a="当你证明自己能够驾驭大地与火焰后，剃刀岭的兽人萨满祭司训练师斯瓦特便会指引你继续前行。",al={"任务给予者","谁开启 水之召唤","斯瓦特"}},{q="在哪里能找到水之先知伊斯伦？",a="水之先知伊斯伦住在贫瘠之地东部海岸，就在棘齿城以南。从杜隆塔尔沿怒水河南下，再前往海岸，寻找一条搁浅的大鲨鱼，她的营地就在旁边。",al={"伊斯伦 在哪里","伊斯伦 位置","如何找到水之先知伊斯伦"}},{q="为什么萨满祭司必须按特定顺序学习元素之道？",a="萨满祭司的传统要求初学者逐步建立灵魂的平衡。大地使灵魂稳固，火焰则锤炼灵魂，使其能够适应水的变幻无常。",al={"元素顺序","为何火之后是水","萨满祭司成长"}},{q="其他职业可以接受这个任务吗？",a="不可以。唯有萨满祭司才会寻求水之灵的眷顾，并尝试召唤自己的水之图腾。",al={"非萨满祭司能否完成","水之召唤 是否仅限萨满祭司"}},{q="寻找伊斯伦时应该留意什么地标？",a="寻找棘齿城以南海岸上一条搁浅的巨大鲨鱼。伊斯伦就住在它旁边。",al={"鲨鱼地标","如何找到 伊斯伦 的营地","伊斯伦 海岸"}},{q="找到水之先知伊斯伦后会发生什么？",a="与伊斯伦交谈便会开启水的试炼。萨满祭司必须穿越卡利姆多和洛丹伦，收集纯净的水滴，并与精魂对抗，才能获得图腾。",al={"下一步","伊斯伦 做什么","水之召唤 之后"}}},fp="13,169,23.247.0,33.304.0,21.109.0,33.204.0,57.149.0,41.93.0,57.86.0,44.176.1"}
P.entries["quest:2987"] = {n="戈杜尼钴矿石",s="奥尔文·吉兹米克刚到菲拉斯，听说戈杜尼食人魔埋藏了一些有趣的矿石。奥尔文提供了一把铲子，并让你前往莫沙彻营地以北的戈杜尼前哨站，循着蓝色的光芒挖掘十二份戈杜尼钴矿。",h="奥尔文·吉兹米克刚到菲拉斯，听说戈杜尼食人魔埋藏了一些有趣的矿石。奥尔文提供了一把铲子，并让你前往莫沙彻营地以北的戈杜尼前哨站，循着蓝色的光芒挖掘十二份戈杜尼钴矿。",kw={"莫沙彻营地","钴矿","菲拉斯","吉兹米克","戈杜尼","戈杜尼前哨站","食人魔","奥尔文","铲子"},sec={{t="埋藏的矿石",b="奥尔文·吉兹米克才刚刚抵达菲拉斯，就听说戈杜尼食人魔拥有一些有趣的矿石。奥尔文不知道食人魔想干什么，但他们守护得非常严密，从不随手乱放。他们把矿石埋了起来，以防像奥尔文这样的人染指。奥尔文给了你一把铲子。戈杜尼前哨站位于营地以北；蓝色的光芒指明了挖掘的位置。需要收集十二份戈杜尼钴矿。"},{t="当交付钴矿时",b="奥尔文打算在接下来的旅途中带着这些钴矿，他确信会有人出高价购买，并会给你一些报酬作为辛苦费。"}},faq={{q="谁需要戈杜尼钴矿？",a="位于莫沙彻营地的奥尔文·吉兹米克，他刚到菲拉斯。",al={"戈杜尼钴矿任务起始人","奥尔文·吉兹米克任务","谁需要钴矿"}},{q="戈杜尼钴矿在哪里？",a="埋藏在莫沙彻营地以北的戈杜尼前哨站。",al={"戈杜尼钴矿位置","菲拉斯哪里能找到钴矿","戈杜尼前哨站在哪里"}},{q="如何发现埋藏的钴矿？",a="蓝色的光芒会显示位置，然后你就可以进行挖掘。",al={"如何发现钴矿","在菲拉斯寻找钴矿","食人魔埋藏地的蓝光"}},{q="为什么食人魔要埋藏他们的钴矿？",a="奥尔文说食人魔对这些矿石保护有加，将它们埋起来是为了防止像奥尔文这样的人染指。至于他们想要这些矿石做什么，奥尔文也说不清楚。",al={"为什么钴矿被埋起来","为什么戈杜尼食人魔要埋藏钴矿","埋藏的食人魔钴矿"}},{q="奥尔文需要多少钴矿？",a="十二份，需要用奥尔文的铲子挖掘。",al={"钴矿数量","需要多少戈杜尼钴矿"}}},fp="15,166,15.357.0,28.150.1,26.92.0,29.79.0,34.67.0,35.147.0,32.51.0"}
P.entries["quest:2988"] = {n="枯木巨魔的牢笼",s="鹰巢山狮鹫管理员塔隆艾克斯告诉你，最强大的狮鹫迅翼的后代——利喙失踪了。据推测，这只幼狮鹫是被巨魔抓走的。他请求你去枯木巨魔的两个村庄，搜查所有的笼子，寻找利喙的踪迹。",h="鹰巢山狮鹫管理员塔隆艾克斯告诉你，最强大的狮鹫迅翼的后代——利喙失踪了。据推测，这只幼狮鹫是被巨魔抓走的。他请求你去枯木巨魔的两个村庄，搜查所有的笼子，寻找利喙的踪迹。",kw={"笼子","狮鹫","辛特兰","利喙","迅翼","塔隆艾克斯","巨魔","枯木"},sec={{t="失踪的后代",b="利喙几天前与他的父母外出狩猎时失踪了。塔隆艾克斯和其他人认为巨魔抓走了他，因此请求你的帮助。你需要去枯木巨魔的两个村庄查看三个笼子，并将你的发现告诉塔隆艾克斯。"},{t="来自村庄的消息",b="利喙不在枯木村庄里。塔隆艾克斯听到这个消息后神情严峻。这只幼狮鹫注定要带领下一代狮鹫，如果他丢了，狮鹫群的力量和精神将会遭受重创。"}},faq={{q="利喙是谁？",a="利喙是迅翼的后代，塔隆艾克斯称迅翼为最强大的狮鹫。利喙在几天前与父母狩猎时失踪了。",al={"利喙","这只狮鹫是谁","迅翼的后代"}},{q="为什么怀疑是枯木巨魔干的？",a="塔隆艾克斯和其他人认为巨魔抓走了利喙，所以枯木村庄的笼子是首要搜查目标。",al={"为什么是巨魔","枯木部族的牵连","谁抓走了利喙"}},{q="我该去哪里寻找利喙？",a="去枯木巨魔的两个村庄查看笼子，然后回来告诉狮鹫管理员塔隆艾克斯你的发现。",al={"笼子在哪里","枯木笼子位置","去哪里寻找利喙"}}},fp="16,176,14.270.0,22.200.1,17.152.0,40.133.0,32.122.0"}
P.entries["quest:2989"] = {n="祖尔祭坛",s="枯木巨魔那里没有尖喙，因此狮鹫管理员塔隆艾克斯怀疑是不是邪枝巨魔把这只幼年狮鹫抓走了。你被派往邪枝巨魔领地西侧边缘的祖尔祭坛去寻找它。",h="枯木巨魔那里没有尖喙，因此狮鹫管理员塔隆艾克斯怀疑是不是邪枝巨魔把这只幼年狮鹫抓走了。你被派往邪枝巨魔领地西侧边缘的祖尔祭坛去寻找它。",kw={"祖尔祭坛","狮鹫管理员塔隆艾克斯","辛特兰","尖喙","邪枝巨魔","枯木巨魔"},sec={{t="另一个部落，另一番搜寻",b="枯木巨魔的笼子里没有尖喙的踪迹。塔隆艾克斯现在怀疑是邪枝巨魔干的，并派你去他们领地西侧边缘的祖尔祭坛，去祭坛顶部寻找那只幼年狮鹫。塔隆艾克斯不敢去想，如果落入邪枝巨魔手中，那只俘虏会遭遇什么。"},{t="来自祭坛的消息",b="尖喙不在祭坛上。塔隆艾克斯认为这既是坏消息也是好消息：众所周知，邪枝巨魔会进行献祭仪式，所以没在那里找到这只狮鹫也算是一种解脱。塔隆艾克斯感谢你的帮助，并表示前方还有更艰巨的任务在等着。"}},faq={{q="为什么狮鹫管理员塔隆艾克斯要派你去祖尔祭坛？",a="枯木巨魔那里没有尖喙，所以塔隆艾克斯认为可能是邪枝巨魔把它抓走了。",al={"为什么去祖尔祭坛","去祖尔祭坛的原因","为何前往祖尔祭坛"}},{q="祖尔祭坛在哪里？",a="祖尔祭坛位于辛特兰邪枝巨魔领地的西侧边缘。你需要去检查一下祭坛顶部。",al={"祖尔祭坛位置","祖尔祭坛在哪里"}},{q="尖喙是谁？",a="尖喙是迅翼的后代，也是塔隆艾克斯自其失踪后一直在寻找的幼年狮鹫。",al={"尖喙是谁","尖喙背景故事"}},{q="为什么塔隆艾克斯担心邪枝巨魔？",a="塔隆艾克斯担心，如果邪枝巨魔抓到了尖喙，没人知道他们会怎么对待它。",al={"为什么邪枝巨魔很危险","邪枝巨魔的行为"}}},fp="16,175,29.284.0,19.250.1,62.100.0,34.108.0,17.97.0,52.85.0"}
P.entries["quest:299"] = {n="发现历史",s="勘察员维尔加需要找回戈阿兹之石缺失的四块碎片，它们散落在湿地那处已被侵占的挖掘场中。石上的铭文仍待翻译。",h="勘察员维尔加需要找回戈阿兹之石缺失的四块碎片，它们散落在湿地那处已被侵占的挖掘场中。石上的铭文仍待翻译。",kw={"阿度斯","戈阿兹之石","高尔姆","莫德","奈尔鲁","上古之神","勘察员维尔加","泰坦","发现历史","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="身为联盟的一员，你支持League在湿地各处开展挖掘工作。这些工作巩固了联盟在当地的势力，也保护了珍贵的知识，使其免遭野蛮之徒或敌人染指。",["race:Dwarf"]="身为矮人，你知道探险者协会珍视每一件遗物，因为它们可能揭示矮人的起源。戈阿兹之石上的Titan铭文便涉及这份古老的传承。"},sec={{t="破碎的石板",b="在迅猛龙侵占湿地的挖掘场之前，勘察员维尔加挖出了戈阿兹之石。他最初尝试解读上面的古老文字时，发现了一些残缺的记载，提及神圣的计划与预示厄运的预言。石板上有四块碎片脱落，部分铭文也随之散落在挖掘场各处。"},{t="勇闯挖掘场",b="为了复原石板，你在迅猛龙盘踞的挖掘场中寻找四块碎片：阿度斯、莫德、高尔姆和奈尔鲁。这些碎片散落在松土和挖掘到一半的遗物之间，凶猛的锯齿龙和镰爪龙在周围虎视眈眈。想要拿到碎片，就得面对沼泽中最凶猛的掠食者。"},{t="囚于大地之下",b="重新拼合的戈阿兹之石上刻着泰坦的语言。维尔加翻译这些符文时，读到了一句令人不寒而栗的话：“上古之神……被锁链囚禁于大地之下。”石板讲述了世界初生时的争斗，以及埋藏在艾泽拉斯地下的邪恶。"}},faq={{q="戈阿兹之石是什么？",a="戈阿兹之石是勘察员维尔加在湿地挖掘场发现的一件古老泰坦圣物。石上晦涩的铭文提及一项神圣的计划，以及被束缚在地下深处的古老存在。",al={"戈阿兹之石背景","戈阿兹之石石板是什么","湿地石板碎片"}},{q="谁提供发现历史任务？",a="勘察员维尔加在一处可以俯瞰维尔加挖掘场的高地上提供这个任务，那里位于湿地的米奈希尔港以东。凶猛的迅猛龙将他赶出了挖掘场。",al={"谁提供发现历史","哪里接发现历史"}},{q="补全石板需要哪些碎片？",a="四块碎片分别是阿度斯、莫德、高尔姆和奈尔鲁。它们散落在迅猛龙盘踞的采掘场底部，混杂于松散的土堆和古老的瓮罐之间。",al={"需要哪些碎片","石板碎片名称","阿度斯 莫德 高尔姆 奈尔鲁"}},{q="勘察员维尔加为什么不能亲自找回碎片？",a="勘察员维尔加是一位年迈的矮人学者。凶恶的迅猛龙入侵并占据采掘场后，他只能撤退，无法独自杀出重重龙群。",al={"维尔加为什么不去取石头","维尔加为什么请人帮忙"}},{q="翻译后的泰坦符文揭示了什么？",a="四块碎片拼合后，维尔加将泰坦文字译为：“上古之神……被锁链囚禁于大地之下。”这些文字暗示，在艾泽拉斯塑形期间，有古老的宇宙存在被囚禁了起来。",al={"戈阿兹之石上写了什么","湿地泰坦文字翻译","上古之神被锁链囚禁于大地之下"}},{q="这个任务与附近的其他探险活动有关吗？",a="有。奥莫尔·铁衣的奥莫尔的复仇任务会派冒险者前往同一处采掘场，削减迅猛龙的数量。",al={"挖掘场附近的任务","奥莫尔·铁衣的关联","奥莫尔的复仇的关联"}}},fx={["2fe7ef8c"]={q="为什么勘察员维尔加想要找回石板碎片？",a="勘察员维尔加在迅猛龙攻占挖掘现场前，发现了一件名为戈阿兹之石的巨大遗物。石碑上已翻译的泰坦文字提到了“神圣计划”和“注定毁灭的预言”，但铭文在四处缺失的部分处戛然而止。维尔加担心时日无多，急切地想要重新拼好整块石板，以便解读剩下的文字，揭开埋藏在挖掘现场地下的秘密。",al={"维尔加的动机","为什么要找碎片","维尔加为什么需要碎片"}},f38df7d0={q="阿多斯、莫德、戈尔姆和涅鲁碎片是什么？",a="阿多斯、莫德、戈尔姆和涅鲁碎片是从戈阿兹之石上断裂缺失的四块碎片。每块碎片都刻有一段古老的泰坦文字，是补全铭文所必需的。将它们重新嵌回主石板后，勘察员维尔加就能完成文本翻译，揭示有关被囚禁在地下的古老存在的不祥篇章。",al={"碎片是什么","阿多斯 莫德 戈尔姆 涅鲁","石板碎片的含义"}}},fp="19,135,16.274.0,20.277.0,24.249.1,23.184.1,40.167.0,49.150.0,59.169.0,43.188.1,54.107.0"}
P.entries["quest:2990"] = {n="萨迪斯·格希德",s="狮鹫管理员鹰斧交给你一根从幼年狮鹫沙普比克的巢中取来的羽毛。你要将它带给占卜师萨迪斯·格希德，他住在诅咒之地守望堡的法师塔中。",h="狮鹫管理员鹰斧交给你一根从幼年狮鹫沙普比克的巢中取来的羽毛。你要将它带给占卜师萨迪斯·格希德，他住在诅咒之地守望堡的法师塔中。",kw={"鹰巢山","诅咒之地","占卜","狮鹫","守望堡","沙普比克","鹰斧","萨迪斯·格希德"},sec={{t="向占卜师求助",b="多年前，萨迪斯·格希德离开鹰巢山，去追寻更黑暗的知识，但鹰斧说，他内心依然是一名蛮锤。运气好的话，凭借占卜魔法和沙普比克巢中的羽毛，萨迪斯就能找到这只幼年狮鹫。鹰斧说，可以在诅咒之地守望堡的法师塔中找到萨迪斯。"},{t="占卜师的迎接",b="萨迪斯向你打招呼，仿佛你是来送礼的。他一眼就认出，这根羽毛属于一只出色的狮鹫，只要它能平安长大，日后必将大有作为。随后，他让你仔细听。"}},faq={{q="萨迪斯·格希德是谁？",a="萨迪斯·格希德是一名占卜师。多年前，他离开鹰巢山，去追寻更黑暗的知识，但鹰斧说，他内心依然是一名蛮锤。",al={"萨迪斯·格希德的故事","萨迪斯是谁"}},{q="为什么需要沙普比克的羽毛？",a="这根羽毛取自沙普比克栖息的巢穴。鹰斧希望萨迪斯能对它施展占卜魔法，找到那只年幼的狮鹫。",al={"为什么需要沙普比克的羽毛","羽毛的用途"}},{q="萨迪斯·格希德在哪里？",a="萨迪斯·格希德住在诅咒之地守望堡的法师塔中。",al={"萨迪斯·格希德的位置","萨迪斯在哪里"}}},fp="17,98,19.288.0,21.208.1,25.117.0,36.134.0,35.84.0"}
P.entries["quest:2992"] = {n="占卜",s="萨迪斯·格希德要你让开些，好让他进行占卜仪式。他打算循着你带来的羽毛与其主人之间的联系，找到沙普比克。",h="萨迪斯·格希德要你让开些，好让他进行占卜仪式。他打算循着你带来的羽毛与其主人之间的联系，找到沙普比克。",kw={"羽毛","狮鹫","仪式","沙普比克","萨迪斯·格希德","占卜"},sec={{t="占卜仪式",b="萨迪斯循着沙普比克的羽毛与它的狮鹫主人之间的联系，希望找到沙普比克本人。他要你保持安静，给他留出施法的空间。他承认仪式可能不会按计划进行，并警告你，要是那样，你最好闭上眼睛。"},{t="仪式结束之时",b="仪式成功了。萨迪斯看到了沙普比克，能够告诉你该去哪里寻找。"}},faq={{q="萨迪斯·格希德在这个仪式中做什么？",a="萨迪斯正在进行占卜仪式。他要寻找你带来的羽毛与沙普比克之间的联系，并打算循着这条联系找到沙普比克本人。",al={"占卜是什么","格希德的仪式","格希德如何找到沙普比克"}},{q="沙普比克是谁？",a="沙普比克是一只年幼的狮鹫，你带给萨迪斯的羽毛就是它的，狮鹫管理员沙拉克·鹰斧一直在设法寻找它。",al={"沙普比克","沙普比克是谁"}},{q="仪式有危险吗？",a="萨迪斯警告说，如果仪式没有按计划进行，你最好闭上眼睛。他要你在他施法时让开些。",al={"占卜有危险吗","为什么要闭眼","占卜风险"}}},fp="14,154,22.265.0,20.111.1,47.140.0,17.131.0,24.131.0"}
P.entries["quest:2993"] = {n="返回辛特兰",s="萨迪斯·格希德告诉了你锐喙被关押的地方：在辛特兰辛萨罗山顶的一座悬崖边上的笼子里。邪枝巨魔的高阶女祭司——邪恶女祭司海克斯拥有钥匙。你需要把这个消息带给鹰巢山狮鹫管理员塔隆艾克斯。",h="萨迪斯·格希德告诉了你锐喙被关押的地方：在辛特兰辛萨罗山顶的一座悬崖边上的笼子里。邪枝巨魔的高阶女祭司——邪恶女祭司海克斯拥有钥匙。你需要把这个消息带给鹰巢山狮鹫管理员塔隆艾克斯。",kw={"狮鹫管理员塔隆艾克斯","辛特兰","辛萨罗","锐喙","萨迪斯·格希德","邪恶女祭司海克斯","邪枝"},sec={{t="锐喙的下落",b="萨迪斯完成了他的任务，他祝你好运并告诉你他所打探到的消息。锐喙被关在辛特兰辛萨罗山顶一座高悬崖上的笼子里。邪枝巨魔的高阶女祭司，邪恶女祭司海克斯，拥有那个笼子的钥匙。把这个消息带给狮鹫管理员塔隆艾克斯。"},{t="塔隆艾克斯的答复",b="塔隆艾克斯询问萨迪斯说了些什么。在得知邪枝巨魔抓住了锐喙后，塔隆艾克斯感到无法忍受，并宣称必须组织一支力量去救回这只狮鹫。"}},faq={{q="是谁透露了锐喙的下落？",a="萨迪斯·格希德，他在执行了占卜仪式后告诉你锐喙被关押在什么地方。",al={"谁告诉你锐喙的位置","锐喙位置来源","谁找到了锐喙"}},{q="锐喙被关在哪里？",a="锐喙被关在辛特兰辛萨罗山顶的一座高悬崖上的笼子里。",al={"锐喙在哪里","锐喙的关押地点","锐喙的悬崖"}},{q="谁拥有锐喙笼子的钥匙？",a="邪枝巨魔的高阶女祭司，邪恶女祭司海克斯，持有钥匙。",al={"锐喙的钥匙","谁有笼子钥匙","邪恶女祭司海克斯的钥匙"}},{q="你应该把这个消息交给谁？",a="把它带给辛特兰的狮鹫管理员塔隆艾克斯。",al={"我应该找谁汇报","重返辛特兰的任务交接地点","狮鹫管理员塔隆艾克斯的位置"}},{q="在此次任务之前发生了什么？",a="萨迪斯·格希德刚刚执行了占卜仪式以寻找锐喙。",al={"上一个任务","是什么导致了重返辛特兰","前置步骤"}}},fp="25,75,23.252.0,17.157.1,38.90.0,30.71.0,38.96.0,31.67.0,30.80.0"}
P.entries["quest:2994"] = {n="拯救沙普比克",s="狮鹫管理员塔隆艾克斯派你去往辛萨罗的顶峰，那座山峰正位于邪枝巨魔领地的中心。邪恶女祭司海克斯拥有开启尖喙牢笼的钥匙，你必须从她手中夺取钥匙并救出那只狮鹫。",h="狮鹫管理员塔隆艾克斯派你去往辛萨罗的顶峰，那座山峰正位于邪枝巨魔领地的中心。邪恶女祭司海克斯拥有开启尖喙牢笼的钥匙，你必须从她手中夺取钥匙并救出那只狮鹫。",kw={"鹰巢山","狮鹫管理员塔隆艾克斯","辛特兰","辛萨罗","拯救尖喙","尖喙","邪恶女祭司海克斯","邪枝巨魔"},sec={{t="前往辛萨罗",b="根据萨迪斯·格希德的预言以及你向塔隆艾克斯的汇报，营救尖喙的方法已经很明确了。辛萨罗位于邪枝巨魔领地的中心，你必须一路杀到它的顶峰。邪恶女祭司海克斯持有尖喙牢笼的钥匙。从她身上把它拿走，然后找到牢笼，救出那只狮鹫。"},{t="塔隆艾克斯的谢意",b="迅风和利爪已经把他们的孩子接回家了，现在还在对他疼爱有加。这一幕让塔隆艾克斯热泪盈眶。塔隆艾克斯说这份恩情无以为报，鹰巢山的狮鹫和骑士们将永远传唱你的名字。"}},faq={{q="是谁派你去营救尖喙的？",a="在预言揭示了狮鹫被关押的位置后，狮鹫管理员塔隆艾克斯请求你去营救尖喙。",al={"谁发布了拯救尖喙的任务","尖喙任务发布者","我在哪里开始拯救尖喙的任务"}},{q="尖喙被关在哪里？",a="尖喙被关在辛萨罗的顶峰，那里位于辛特兰的邪枝巨魔领地内。",al={"尖喙在哪里","尖喙位置","尖喙的牢笼在哪里"}},{q="谁持有尖喙牢笼的钥匙？",a="邪恶女祭司海克斯拥有打开尖喙牢笼所需的钥匙。",al={"谁掉落尖喙的钥匙","海克斯的钥匙在哪里","邪恶女祭司海克斯的钥匙"}}},fp="16,157,14.304.0,17.235.1,34.125.0,30.92.0,38.27.0"}
P.entries["quest:2996"] = {n="寻找斯坦哈德",s="在奥格瑞玛，甘鲁尔·血眼派术士南下棘齿城，接受更深入的训练。在那里，一位人类召唤师传授超越基础召唤术的技艺。",h="在奥格瑞玛，甘鲁尔·血眼派术士南下棘齿城，接受更深入的训练。在那里，一位人类召唤师传授超越基础召唤术的技艺。",kw={"贫瘠之地","暗影裂口","地狱猎犬任务","甘鲁尔·血眼","棘齿城","寻找斯坦哈德","斯坦哈德·法尔杉","阴谋之书"},ang={["class:Warlock"]="作为术士，你正在逐步掌握驾驭中阶恶魔的本领，并接受考验，证明自己已准备好奴役吞噬魔法的地狱猎犬。",["faction:Horde"]="作为部落的一员，你看到了术士集会如何在大酋长的正式外交之外行事：他们的大师将学徒送往一位独居的人类那里。"},sec={{t="走出奥格瑞玛的阴影",b="甘鲁尔·血眼在暗影裂口训练年轻的术士，让他们学习驾驭虚空的力量。当学徒的能力超出这些教导的范围时，甘鲁尔便指引他们走出城墙。要驾驭更不稳定的生物，就需要精通黑暗秘术的大师指点。"},{t="不同寻常的合作",b="甘鲁尔将学徒送往斯坦哈德·法尔杉那里，这位人类巫师住在棘齿城地精港口上方的一座高塔中。部落与人类或许互为敌人，但术士的眼光超越了寻常的阵营忠诚。力量、自律和仪式知识比血统更重要。斯坦哈德评判学徒，看的是内心的仇恨和奴役的能力，而非肤色。"}},faq={{q="为什么兽人术士要派我去向人类求教？",a="术士看重黑暗知识，胜过对种族的忠诚。甘鲁尔·血眼知道，斯坦哈德·法尔杉在高深的恶魔学识上造诣非凡。若想召唤危险的生物，导师的知识比阵营界限更重要。",al={"为何向人类学习","斯坦哈德人类术士","为何找斯坦哈德"}},{q="在哪里能找到斯坦哈德·法尔杉？",a="斯坦哈德·法尔杉住在贫瘠之地棘齿城上方的高崖上，就在他俯瞰地精港口的高塔外。",al={"斯坦哈德位置","斯坦哈德在哪里","斯坦哈德高塔棘齿城"}},{q="斯坦哈德传授什么力量？",a="斯坦哈德传授束缚地狱猎犬的仪式，这是一种来自扭曲虚空、吞噬魔法的恶魔。他与术士一同研读秘典，然后考验他们奴役这头恶魔的能力。",al={"斯坦哈德解锁什么","从斯坦哈德处获得什么","寻找斯坦哈德奖励"}},{q="甘鲁尔·血眼是谁？",a="甘鲁尔·血眼是奥格瑞玛地下暗影裂口中一位声名显赫的兽人术士导师。他向初出茅庐的部落术士传授邪能魔法的基础知识，以及召唤低阶仆从的方法。",al={"甘鲁尔是谁","甘鲁尔·血眼","奥格瑞玛术士训练师"}},{q="还有其他方式开始这个任务吗？",a="有。被遗忘者术士会在幽暗城的魔法区收到类似的召唤，指引他们前往棘齿城上方，拜访同一位人类导师。",al={"寻找斯坦哈德幽暗城","被遗忘者 寻找斯坦哈德","幽暗城版本"}},{q="棘齿城对部落术士有危险吗？",a="棘齿城由热砂港管理，始终是一座中立港口。只要维持和平，不在城内攻击旅人，地精卫兵就不会找你的麻烦。",al={"棘齿城安全吗","棘齿城卫兵敌对","中立港口"}}},fp="15,142,32.257.0,22.346.0,44.221.0,32.106.0,30.188.1,24.181.0,41.140.0,47.166.0"}
P.entries["quest:2997"] = {n="圣洁之书",s="阿扎尔·战锤将丹莫罗有潜力的矮人圣骑士送往铁炉堡，接受更深入的教导。蒂萨·热炉在那里的Hall of Mysteries等候，侍奉圣光的试炼将在此开始。",h="阿扎尔·战锤将丹莫罗有潜力的矮人圣骑士送往铁炉堡，接受更深入的教导。蒂萨·热炉在那里的Hall of Mysteries等候，侍奉圣光的试炼将在此开始。",kw={"阿扎尔·战锤","丹莫罗","秘法大厅","圣光","铁炉堡","秘法区","圣骑士","救赎","蒂萨·热炉","圣洁之书"},ang={["class:Paladin"]="作为圣骑士，你将雪地中的实际军务与神圣战士应有的深厚精神修行融为一体。",["faction:Alliance"]="作为联盟的一员，你与卡兹莫丹的矮人守卫者，以及洛丹伦和暴风城的人类盟友一样，都敬奉圣光。",["race:Dwarf"]="作为矮人，你在铁炉堡的Hall of Mysteries中，将族人的坚韧与圣光的教诲融为一体。"},sec={{t="来自王座厅的召唤",b="矮人新兵守卫着丹莫罗白雪覆盖的村庄与道路。当阿扎尔认为一名守卫者已准备好接受更深入的精神教导时，他便让这名候选人离开野外岗位，前往铁炉堡。在那里，城中侍奉圣光的长者可以给予指引。"},{t="Hall of Mysteries",b="这道召令指引你穿过秘法区，来到Hall of Mysteries。殿堂中陈列着神圣的遗物，弥漫着庄严的求知氛围。蒂萨·热炉会考验你是否已准备好自我牺牲、心怀仁慈，并承担这份使命所要求的道德责任。"}},faq={{q="这项任务的目的是什么？",a="阿扎尔·战锤召回在丹莫罗执行野外任务的有潜力的矮人圣骑士，派你前往铁炉堡寻找蒂萨·热炉。这些试炼让你了解圣光，也是获得复活之力的必经之路。",al={"为何需要这项任务","圣洁之书有什么用","圣洁之书的目的"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位经验丰富的矮人圣骑士，也是铁炉堡神秘大厅中备受尊敬的导师。她引导年轻的圣骑士接受精神教导，完成圣洁之书的神圣试炼。",al={"蒂萨是谁","蒂萨·热炉的背景","热炉是谁"}},{q="神秘大厅在哪里？",a="神秘大厅位于铁炉堡西部的秘法区。牧师、圣骑士和法师汇聚于此，这里是矮人首都的信仰与奥术中心。",al={"秘法大厅在哪里","寻找秘法大厅","铁炉堡秘法大厅"}},{q="是谁派圣骑士执行这项差事？",a="阿扎尔·战锤是丹莫罗的圣骑士训练师。当有潜力的新兵证明自己愿为保卫当地矮人聚落尽心尽力后，他便派他们前往铁炉堡。",al={"谁开启圣洁之书","圣洁之书任务给予者","阿扎尔·战锤"}},{q="矮人圣骑士为何必须到铁炉堡学习？",a="阿扎尔在野外传授基础战斗技巧，而秘法大厅拥有圣光的正式教义、神圣典籍，以及侍奉它的长者。蒂萨·热炉等资深导师会指导学员研习高深的仪式与精神教义。",al={"为何前往铁炉堡","为何在铁炉堡训练"}},{q="与蒂萨·热炉交谈后会发生什么？",a="与蒂萨交谈后，矮人的圣洁之书试炼便会开始。这些试炼要求你在侍奉圣光时展现虔诚、怜悯与牺牲精神。",al={"接下来是什么","圣洁之书的后续任务","蒂萨会给予什么"}}},fx={d775d5e6={q="阿扎尔·战锤为什么想让你前往铁炉堡？",a="阿扎尔·战锤意识到，你作为学徒援助丹莫罗的日子即将结束。要真正成为圣光的勇士，你需要更深入地学习圣光的奥秘、教义与责任。他指引你前往铁炉堡，因为蒂萨·热炉受托考验那些前途光明的年轻圣骑士，引导他们找到自己真正的使命。",al={"阿扎尔为什么派人去","阿扎尔·战锤的动机","为什么去见蒂萨·热炉"}},a7a63213={q="阿扎尔·战锤为什么偏偏派你去？",a="这段旅程并非城中卫兵或久经沙场的老兵能替你完成的差事。它标志着你作为圣骑士的个人成长。阿扎尔派你去找蒂萨·热炉，因为唯有你自己才能回应圣光的召唤，证明你对其美德的忠诚，并承担神圣战士应尽的责任。",al={"为什么派我去","阿扎尔派人去的原因","为什么选择圣骑士玩家"}}},fp="16,213,23.242.0,21.221.0,34.225.0,24.203.0,39.169.0,37.164.0,45.238.0,50.157.0"}
P.entries["quest:2998"] = {n="圣洁之书",s="如今，一纸召令正召唤艾尔文前途可期的圣骑士前往暴风城。威尔海姆修士召他们前去，而圣洁之书则开启了一系列神圣试炼，教导他们掌握借助圣光复活他人的力量。",h="如今，一纸召令正召唤艾尔文前途可期的圣骑士前往暴风城。威尔海姆修士召他们前去，而圣洁之书则开启了一系列神圣试炼，教导他们掌握借助圣光复活他人的力量。",kw={"威尔海姆修士","光明大教堂","达索瑞恩·拉尔","闪金镇","圣骑士","救赎","暴风城","圣洁之书"},ang={["class:Paladin"]="身为圣骑士，你的事迹得到导师们的认可，他们派你前去拜见白银之手的高阶指挥官。这标志着圣骑士成长道路上的一道重要仪式。",["faction:Alliance"]="暴风城招募并考验神圣勇士，帮助联盟在动荡时期维持一支忠诚的前线治疗者与战斗人员队伍。",["race:Human"]="身为人类，你从乡间的艾尔文森林前往宏伟的光明大教堂，这段旅程将你与王国根基深厚的信仰及军事机构联系在一起。"},sec={{t="前往王都的召令",b="在艾尔文森林，初入行伍的圣骑士起初会帮助当地居民，并与狼、迪菲亚匪徒和狗头人交战，磨炼自己的实力。当一名新兵在战斗中展现出自律与对圣光的虔诚时，威尔海姆修士这样的导师便会亲自发出召令。圣骑士领袖会选出前途可期的学徒，指引他们离开当地的小教堂。他们必须前往王国的信仰中心报到。"},{t="光明大教堂",b="暴风城的光明大教堂坐落于教堂广场，是王国神职人员与白银之手骑士团最重要的圣所。达索瑞恩·拉尔居住于此，负责督导那些宣誓加入骑士团的人。在高耸的穹顶下，资深圣骑士为每位新兵安排圣洁之书的正式试炼。这些试炼考验他们的怜悯之心、坚韧意志与牺牲精神。"}},faq={{q="谁会派我前往暴风城执行这个任务？",a="威尔海姆修士是闪金镇狮王之傲旅店附近的圣骑士训练师。当你在外历练、展现出潜力与实力后，他便会派你前往暴风城。",al={"任务给予者","谁给予任务","威尔海姆修士"}},{q="在哪里可以找到达索瑞恩·拉尔？",a="达索瑞恩·拉尔住在暴风城西北部教堂广场的光明大教堂内。他大多数日子都在宏伟的厅堂中训练圣骑士。",al={"达索瑞恩·拉尔位置","达索瑞恩·拉尔在哪里","圣骑士大师位置"}},{q="为什么这道召令对圣骑士如此重要？",a="向达索瑞恩·拉尔报到，标志着你从基础武艺训练迈向与圣光的深层交融。圣洁之书的试炼由此开始，最终将赋予你借助圣光让阵亡盟友死而复生的神圣力量。",al={"为什么做这个任务","任务重要性","圣骑士试炼"}},{q="非人类圣骑士也会接到完全相同的任务吗？",a="威尔海姆修士从艾尔文森林发出的召令面向人类圣骑士。矮人圣骑士则会收到丹莫罗训练师发出的类似召令，前往铁炉堡。",al={"矮人圣骑士","矮人能否完成","任务是否仅限人类"}},{q="向达索瑞恩·拉尔报到后会发生什么？",a="当你向达索瑞恩·拉尔致意时，他会欢迎你来到暴风城，并向你介绍圣洁之书的试炼。这些试炼将考验你的怜悯之心，以及你守护弱者的决心。",al={"下一个任务","接下来会发生什么","圣洁之书 下一步"}},{q="达索瑞恩·拉尔是谁？",a="达索瑞恩·拉尔是暴风城与白银之手骑士团中最有影响力的圣骑士之一。他在王都教导新一代的神圣勇士。",al={"达索瑞恩 是谁","达索瑞恩·拉尔背景"}}},fx={["69ec335a"]={q="威尔海姆修士为什么派你去找达索瑞恩·拉尔？",a="威尔海姆修士十分敬重达索瑞恩·拉尔，他是骑士团中最有影响力的圣骑士之一。威尔海姆无意间听到达索瑞恩称赞你的功绩，并提到你已准备好接受考验，因此只想确保你能抓住这个机会。作为闪金镇的导师，引导有潜力的新成员接受更高深的教导，既是他的职责，也是他的骄傲。",al={"威尔海姆为什么派我去","威尔海姆修士的动机","为什么与达索瑞恩·拉尔交谈"}}},fp="16,205,24.425.0,22.397.0,41.155.0,32.168.0,46.251.0,47.171.0,47.177.0,22.164.0"}
P.entries["quest:2999"] = {n="圣洁之书",s="“神圣之书”是为在丹莫罗服役的年轻矮人圣骑士提供的成人礼任务。在铁炉堡神秘大厅的圣骑士训练师布兰度尔·铁锤的指引下，初学者将被派往楼上与受人尊敬的圣骑士训练师蒂萨·热炉交谈。这标志着从基础武力训练向圣光之道更深层的精神职责与神圣誓言的转变。",h="“神圣之书”是为在丹莫罗服役的年轻矮人圣骑士提供的成人礼任务。在铁炉堡神秘大厅的圣骑士训练师布兰度尔·铁锤的指引下，初学者将被派往楼上与受人尊敬的圣骑士训练师蒂萨·热炉交谈。这标志着从基础武力训练向圣光之道更深层的精神职...",kw={"布兰度尔·铁锤","神秘大厅","铁炉堡","圣骑士","救赎","蒂萨·热炉","神圣之书"},ang={["class:Paladin"]="这个任务标志着初学者从粗糙的武力操练转向圣光深层精神重负的时刻，并为获得救赎力量的试炼做好准备。",["race:Dwarf"]="矮人圣骑士将圣光的奉献与卡兹莫丹深厚的职责与兄弟会传统相结合，响应着铁炉堡山脉大厅内的召唤。"},sec={{t="高阶宝座的召唤",b="当新手圣骑士还在安威玛尔和卡拉诺斯抵御穴居人和霜鬃巨魔时，他们的职责终将要求他们有更深层的奉献。布兰度尔·铁锤在认可了一名初学者的武技修养后，会建议他们暂时放下在雪地山口的任务，前往铁炉堡他所在的神秘大厅寻找指导。在那里，资深圣骑士会监督该职业的精神成长。"},{t="蒂萨·热炉的指引",b="蒂萨·热炉是铁炉堡矮人中最受尊敬的圣骑士之一。她的职责是指导初学者理解圣光的真正重负，不仅是简单的剑术与锤击，更要传授同情、正义与自我牺牲。寻找到她便开启了对“神圣之书”的正式研究，这一神圣过程旨在赋予圣骑士复活倒下者的能力。"}},faq={{q="这个任务的目的是什么？",a="这个任务将年轻的矮人圣骑士从他们的训练师布兰度尔·铁锤处引向铁炉堡的资深圣骑士蒂萨·热炉。它是研究“神圣之书”并获得精神复活力量所需试炼的开端。",al={"这个任务有什么用","神圣之书起始","为什么要做这个任务"}},{q="布兰度尔·铁锤是谁？",a="布兰度尔·铁锤是一位驻扎在铁炉堡神秘大厅的矮人圣骑士训练师。他在那里监督年轻的圣骑士，当他们准备好承担更重大的神圣职责时，将有前途的初学者送往楼上寻找蒂萨·热炉。",al={"谁发布这个任务","布兰度尔的作用","布兰度尔·铁锤背景故事"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是一位受人尊敬的资深圣骑士，位于铁炉堡神秘大厅的楼上。她指导年轻的圣骑士，教导他们除了武力之外，圣光对他们有着怎样的真正要求。",al={"蒂萨在哪里","蒂萨·热炉的作用","谁是蒂萨"}},{q="这个任务接下来指向哪里？",a="与蒂萨·热炉交谈将启动“神圣之书”的具体试炼。这些任务旨在考验圣骑士的奉献精神、仁慈之心以及为了圣光而保护和恢复生命意志。",al={"后续任务","接下来是什么","神圣之书任务链"}},{q="为什么矮人圣骑士必须寻求“神圣之书”？",a="为了掌握将倒下的盟友起死回生的奇迹，圣骑士必须理解真正的无私与精神职责。“神圣之书”通过正式课程和信仰考验引导初学者，而这些是引导如此强大神圣力量所必需的。",al={"为什么是神圣之书","圣骑士复活任务背景","矮人救赎"}},{q="人类会在铁炉堡接受同样的指导吗？",a="人类圣骑士会通过暴风城的光明大教堂进行平行的旅程，而不是在铁炉堡。这个从布兰度尔·铁锤到蒂萨·热炉的具体召唤是专为在铁炉堡训练的矮人量身定做的。",al={"人类能做这个吗","这是矮人专属吗","人类神圣之书"}}},fx={["1a85ab42"]={q="布兰度尔·铁锤为什么派你去找蒂萨·热炉？",a="布兰度尔·铁锤意识到，你在丹莫罗的训练已经让你准备好在骑士团中承担更重的责任。他希望你在自己的使命上更进一步，而非一直被当地的麻烦牵绊。蒂萨·热炉是矮人圣骑士敬重的导师，当年轻的新成员准备好了解圣光真正要求他们承担什么时，她便会给予指引。",al={"布兰度尔为什么派人去","布兰度尔·铁锤的动机","为什么与蒂萨·热炉交谈"}},["264c72ef"]={q="为什么必须由你亲自与蒂萨交谈，而不能让布兰度尔代办？",a="圣骑士之路关乎自身，无法由他人代行。布兰度尔·铁锤可以指导你早期的武艺训练，但灵性上的成长要求你亲自来到长者面前。蒂萨·热炉必须亲自评估你的虔诚与决心，才能将圣洁之书这样的神圣教诲托付给你。",al={"圣洁之书为什么选我","为什么必须亲自去找蒂萨","布兰度尔为什么不去"}}},fp="16,184,25.261.0,30.253.0,34.221.0,26.233.0,24.169.0,32.174.0,56.207.0,53.169.0"}
P.entries["quest:3000"] = {n="圣洁之书",s="这个任务指引在远方游历的矮人圣骑士回到家乡铁炉堡，以进一步完成他们的神圣使命。该任务由暴风城的格雷森·沙东布瑞克公爵发布，旨在引导初出茅庐的勇士前往蒂萨·热炉处，她是神秘大厅最受尊敬的导师之一。回到家乡标志着他们正式开始接受《神圣法典》的试炼。",h="这个任务指引在远方游历的矮人圣骑士回到家乡铁炉堡，以进一步完成他们的神圣使命。该任务由暴风城的格雷森·沙东布瑞克公爵发布，旨在引导初出茅庐的勇士前往蒂萨·热炉处，她是神秘大厅最受尊敬的导师之一。回到家乡标志着他们正式开始...",kw={"矮人圣骑士","秘法大厅","铁炉堡","格雷森·沙东布瑞克公爵","秘法区","救赎","蒂萨·热炉","神圣法典"},ang={["class:Paladin"]="这标志着矮人圣骑士的一个重要成年仪式，让他们走上研读《神圣法典》并掌握复活之赐的道路。",["faction:Alliance"]="暴风城的圣骑士与铁炉堡的导师之间共同的训练和相互尊重，彰显了矮人与人类之间紧密的精神联盟。",["race:Dwarf"]="这个任务架起了你在人类领地的冒险与你对卡兹莫丹职责之间的桥梁，召唤你回到铁炉堡的祖居地，在你的族中长者指导下接受训练。"},sec={{t="召唤回家",b="虽然矮人圣骑士经常援助暴风城王国并在人类领地内四处冒险，但他们的精神和武力根基仍扎根于卡兹莫丹。格雷森·沙东布瑞克公爵在认定一名矮人的实战训练已足够成熟时，会建议他们回到铁炉堡的核心。在那里，他们的族人会监督他们履行作为一名白银之手骑士所应尽的深刻精神义务。"},{t="神秘大厅",b="在回到这座山中之城后，圣骑士将被指引前往神秘区。蒂萨·热炉就居住在神秘大厅深处的上层。作为矮人圣骑士新生代的受人尊敬的导师，她负责帮助他们做好准备，通过《神圣法典》中记载的神圣试炼来肩负起圣光的重担。"}},faq={{q="为什么格雷森·沙东布瑞克公爵要让我回铁炉堡？",a="格雷森公爵认为，虽然你已经在战场上证明了自己的实力，但年轻的矮人圣骑士理应在蒂萨·热炉的指导下，直接向自己的族人学习圣光更深奥的教义和试炼。",al={"为什么要回铁炉堡","为什么格雷森让我离开","为什么要拜访蒂萨"}},{q="蒂萨·热炉是谁？",a="蒂萨·热炉是铁炉堡最受尊敬的矮人圣骑士之一。她驻守在神秘大厅的楼上，负责指导成长中的圣骑士，并监督那些考验他们对圣光奉献精神的试炼。",al={"蒂萨·热炉","蒂萨是谁","圣骑士训练师蒂萨"}},{q="我在哪里可以找到蒂萨·热炉？",a="她位于铁炉堡神秘区的神秘大厅内。前往圣所的楼上就能找到她。",al={"蒂萨在哪里","蒂萨·热炉位置","如何找到蒂萨"}},{q="什么是《神圣法典》？",a="《神圣法典》包含了圣骑士为了掌握圣光力量——特别是复活的力量和对阵亡盟友的无私奉献——所必须经历的神圣教义和严苛试炼。",al={"神圣法典的含义","什么是神圣法典","圣骑士之书"}},{q="人类圣骑士能做这个版本的任务吗？",a="不能。这个特定的召唤任务专门指引矮人圣骑士回到他们家乡的导师处，而人类圣骑士则直接在暴风城的格雷森·沙东布瑞克公爵和达索瑞恩·拉尔的指导下进行试炼。",al={"人类能做这个吗","这是矮人专属任务吗"}},{q="向蒂萨·热炉报到后会发生什么？",a="一旦你向蒂萨做了自我介绍，她就会通过《神圣法典》为你布置正式的矮人试炼，考验你是否准备好掌握圣光的救赎力量。",al={"接下来是什么","神圣法典之后的下一个任务","与蒂萨交谈后"}}},fx={c5356bb5={q="格雷森·沙东布瑞克公爵为什么选择我来做这件事？",a="格雷森公爵看到了你作为圣骑士日益增长的潜力，但他也尊重你族人独有的传统。他知道，年轻的矮人圣骑士必须以本族长者的教诲为根基，不能只在暴风城的光明大教堂中接受教导。他让你返回故乡，是因为你该接受下一场神圣仪式了，而蒂萨·热炉正是引导矮人跨过这道灵性关口的受敬重的导师。",al={"圣洁之书为什么选我","格雷森为什么派我去","为什么选择矮人圣骑士"}}},fp="16,201,14.310.0,21.262.0,62.178.0,24.159.0,34.92.0,29.156.0,48.174.0,49.176.0"}
P.entries["quest:3001"] = {n="寻找斯坦哈德",s="凯伦丁·哈加尔派部落术士横渡无尽之海，寻找斯坦哈德·法尔杉。在棘齿城上方，一位人类术士指引他们超越基础暗影法术，研习召唤地狱猎犬的艰深技艺。",h="凯伦丁·哈加尔派部落术士横渡无尽之海，寻找斯坦哈德·法尔杉。在棘齿城上方，一位人类术士指引他们超越基础暗影法术，研习召唤地狱猎犬的艰深技艺。",kw={"贫瘠之地","凯伦丁·哈加尔","地狱猎犬","棘齿城","寻找斯坦哈德","斯坦哈德·法尔杉","阴谋之书","幽暗城","术士"},ang={["class:Warlock"]="作为术士，这标志着你在达到第三十级左右时迎来的一场进阶试炼。你将告别束缚小鬼和虚空行者的初级法术，转而学习驾驭凶猛的地狱猎犬。",["faction:Horde"]="作为部落术士，你暂时放下平日对人类的敌意，前往中立的棘齿城，向一位活着的术士求教。",["race:Undead"]="作为Undead，你也是凯伦丁·哈加尔从幽暗城派出的被遗忘者弟子之一。他的选择表明，即使是Sylvanas的忠诚追随者，也会向活着的大师求教，扩充自己的手段。"},sec={{t="海那边的大师",b="凯伦丁·哈加尔是幽暗城魔法区的一位被遗忘者术士训练师，他知道何时基础教导已不足以满足学徒。他派弟子们走出洛丹伦的废墟，寻找斯坦哈德·法尔杉。哈加尔提醒他们，斯坦哈德虽然是个活着的人类，却绝非弱者，不要把他当作敌人。对术士而言，追求驾驭恶魔的力量，往往会跨越种族和阵营的界限。"},{t="棘齿城的眺望台",b="斯坦哈德在棘齿城上方的峭壁上钻研法术，这座地精港口坐落于贫瘠之地。他在一座石砌瞭望塔旁俯视下方的水手、雇佣兵和商人，这些人对扭曲虚空一无所知，却过得无忧无虑，令他觉得有趣。前来找他的部落术士，眼中或许带着猜忌与压抑的仇恨。斯坦哈德接纳这份原始的恶意，将其作为塑造黑暗力量的燃料。"}},faq={{q="为什么幽暗城的术士要派我去找一个人类？",a="为了追求稀有而强大的黑暗知识，术士常常会暂时放下阵营分歧。凯伦丁·哈加尔说，斯坦哈德·法尔杉精通高等恶魔召唤术，那是哈加尔无法传授的专门技艺。在追求恶魔力量时，导师的学识比血统更重要。",al={"为何找人类训练师","为何派去找人类","凯伦丁派去找斯坦哈德"}},{q="斯坦哈德·法尔杉究竟在哪里？",a="斯坦哈德·法尔杉位于贫瘠之地，在地精港口棘齿城上方的高耸悬崖上。他站在一座石塔旁，俯瞰海湾与繁忙的港口码头。",al={"斯坦哈德位置","斯坦哈德在哪","如何找到斯坦哈德"}},{q="斯坦哈德传授什么样的力量？",a="斯坦哈德指导经验丰富的术士，学习束缚扭曲虚空高等恶魔的复杂仪式。他的教导将引领他们接受危险的试炼，学习召唤并驾驭地狱猎犬。",al={"斯坦哈德教什么","这个任务有何用途","地狱猎犬任务"}},{q="斯坦哈德与联盟结盟了吗？",a="斯坦哈德虽然是人类，却在棘齿城的中立地精领地活动，并不隶属于大联盟。他是一位独立的施法者，与能够承受他教导的部落和联盟术士自由往来。",al={"斯坦哈德属于联盟吗","斯坦哈德阵营","斯坦哈德友善吗"}},{q="找到斯坦哈德之后会发生什么？",a="你抵达后，斯坦哈德会考验你的决心，并让你找回阴谋之书散落的残页和相关材料。为了寻找召唤地狱猎犬的仪式，你将奔走于遥远的各地。",al={"找到斯坦哈德之后","阴谋之书","后续任务"}},{q="斯坦哈德为什么欢迎学生心怀仇恨？",a="恶魔魔法以强烈的情感、支配欲和意志力为养分。仇恨可以被凝聚并加以约束，帮助召唤者束缚来自虚空的混乱生物，否则这些生物便会吞噬缺乏自制的人。",al={"斯坦哈德为何喜欢仇恨","眼中的仇恨"}}},fp="15,212,23.343.0,23.373.0,50.293.0,40.154.0,38.203.0,36.229.0,36.207.0,48.209.0"}
P.entries["quest:3002"] = {n="戈杜尼宝珠",s="洛卡·奥赫很了解敌人，但他是个战士，无法说出戈杜尼宝珠到底有什么能力。洛卡知道奥格瑞玛有一位法师能说出更多信息。这枚宝珠需要你带给奥格瑞玛暗棘小屋的尤塞尔奈。这是在“黑暗仪式”之后的任务。",h="洛卡·奥赫很了解敌人，但他是个战士，无法说出戈杜尼宝珠到底有什么能力。洛卡知道奥格瑞玛有一位法师能说出更多信息。这枚宝珠需要你带给奥格瑞玛暗棘小屋的尤塞尔奈。这是在“黑暗仪式”之后的任务。",kw={"暗棘小屋","菲拉斯","戈杜尼","戈杜尼宝珠","奥格瑞玛","洛卡·奥赫","尤塞尔奈"},sec={{t="战士的知识之外",b="在“黑暗仪式”之后，洛卡·奥赫拿着宝珠，但他承认自己只是个战士，根本不知道这东西有什么用。洛卡知道奥格瑞玛有一位法师能说出更多情况，于是让你带着宝珠去寻找在暗棘小屋的尤塞尔奈。"},{t="尤塞尔奈的结论",b="尤塞尔奈觉得这枚宝珠很迷人。尤塞尔奈说，它非常强大，但也非常危险。"}},faq={{q="是谁让你去找尤塞尔奈的？",a="洛卡·奥赫，在你拿到了“黑暗仪式”中要求你夺取的宝珠之后。",al={"戈杜尼宝珠系列任务","黑暗仪式后续","戈杜尼宝珠的前置任务"}},{q="为什么洛卡·奥赫不检查一下这枚宝珠？",a="洛卡·奥赫是个战士，根本说不出这枚宝珠有什么用，但他知道奥格瑞玛有一位法师能给出更多信息。",al={"为什么要将宝珠送到奥格瑞玛","为什么洛卡·奥赫要把宝珠送走","为什么是尤塞尔奈"}},{q="尤塞尔奈在哪里？",a="在奥格瑞玛的暗棘小屋里。",al={"尤塞尔奈位置","尤塞尔奈在哪里","暗棘小屋位置"}},{q="在“戈杜尼宝珠”之前的任务是什么？",a="“黑暗仪式”，在那项任务中洛卡·奥赫派你去从一名戈杜尼法师领主手中夺取宝珠。",al={"戈杜尼宝珠前置条件","戈杜尼宝珠前序任务"}}},fp="16,126,28.219.0,19.99.1,27.82.0,39.136.0,19.45.0,35.87.0"}
P.entries["quest:301"] = {n="向铁炉堡报告",s="这项任务将一位冒险者从洛克莫丹的塞尔萨玛送往铁炉堡的中心地带，带去来自铁环挖掘场的重要更新。将挖掘进度报告送交至探险者大厅的勘察员塔伯斯·雷矛，将引发对缺失的爆破火药和山脚下停滞的考古工作的调查。",h="这项任务将一位冒险者从洛克莫丹的塞尔萨玛送往铁炉堡的中心地带，带去来自铁环挖掘场的重要更新。将挖掘进度报告送交至探险者大厅的勘察员塔伯斯·雷矛，将引发对缺失的爆破火药和山脚下停滞的考古工作的调查。",kw={"爆破火药","探险者协会","铁环营地","吉恩·角盔","洛克莫丹","勘察员塔伯斯·雷矛","报告铁炉堡","塞尔萨玛"},ang={["faction:Alliance"]="这项任务展示了联盟的后勤能力，将山谷中遥远的研究营地与铁炉堡的军事和学术领导层连接起来。",["race:Dwarf"]="对矮人来说，应对探险者协会的官僚作风以及处理雷矛氏族传说中的脾气，是他们在首都大厅中熟悉的一种通过仪式。"},sec={{t="探险者协会的信使",b="卡兹莫丹各地的考古探险队在很大程度上依赖于探险者协会的资金、补给和监督。当洛克莫丹南部的勘察员基恩萨·铁环的挖掘场缺乏爆破补给时，他的监管人无法简单地在当地征用更多物资。塞尔萨玛旅店的吉恩·角盔委托一位冒险者将勘察员基恩萨·铁环的书面报告翻越山口直接送交至协会总部的勘察员塔伯斯·雷矛手中。"},{t="雷矛的脾气",b="勘察员塔伯斯·雷矛代表了他所在氏族那种雷厉风行、火爆坚决的性格特征。他驻扎在铁炉堡宏伟的图书馆和探险者大厅中，期待着协会挖掘工作能迅速取得切实成果。在收到这封信后，雷矛愤怒地发现勘察员基恩萨·铁环未能说明数周前寄出的一大批爆破火药的去向，这表明洛克莫丹的补给线已经出现了危险的中断。"}},faq={{q="为什么这份报告需要被送到铁炉堡？",a="探险者协会严格管理着像爆破火药这类宝贵资源的分配。野外挖掘点如果没有驻扎在探险者大厅总部的资深勘察员的正式授权，就无法订购危险的爆炸物。",al={"为什么要去铁炉堡","为什么要将报告交给雷矛","铁炉堡报告原因"}},{q="谁是勘察员塔伯斯·雷矛？",a="他是驻扎在铁炉堡的探险者协会的一位高级官员。作为引以为傲的雷矛氏族的一员，他因脾气暴躁以及对停滞的挖掘点和丢失的库存缺乏耐心而臭名昭著。",al={"谁是雷矛","勘察员雷矛背景故事"}},{q="勘察员基恩萨·铁环最初的爆破火药去哪了？",a="一批爆破火药在数周前就已发出，但勘察员基恩萨·铁环只字未提是否收到。这引发了人们的担忧，担心石腭怪或强盗在洛克莫丹的道路上伏击了运输车。",al={"爆破火药发生了什么","丢失的爆破火药","火药在哪里"}},{q="在铁炉堡哪里可以找到勘察员塔伯斯·雷矛？",a="勘察员塔伯斯·雷矛位于探险者大厅（也被称为图书馆或探险者大厅），坐落在铁炉堡的东北翼。",al={"雷矛的位置","雷矛在哪里","探险者大厅位置"}},{q="是谁在塞尔萨玛交给你报告的？",a="吉恩·角盔居住在塞尔萨玛的烈酒旅店，担任联络人，负责协调勘察员基恩萨·铁环的偏远营地与城市领导层之间的报告和通讯。",al={"谁发布了报告铁炉堡任务","吉恩·角盔的角色"}},{q="雷矛读完报告后会发生什么？",a="对不知去向的弹药和停滞的进度感到愤怒，雷矛命令玩家组织一批新的爆破火药，并直接送回给勘察员基恩萨·铁环。",al={"接下来是什么","报告铁炉堡之后的后续任务"}}},fx={["499fe615"]={q="吉恩·角盔为什么派你去，而不亲自前往？",a="吉恩·角盔忙着管理塞尔萨玛的后勤事务，并为当地的挖掘工作提供支援，早已分身乏术。此外，勘察员塔伯斯·雷矛出了名的脾气火暴，遇到延误和挫折就会大发雷霆。让一个无足轻重的信使去承受雷矛的怒火，吉恩既能避开上司的直接责难，又能专心处理当地事务。",al={"为何派我","为何不亲自去","角盔为何需要我"}},["601d3943"]={q="吉恩·角盔为什么想把这份报告送往铁炉堡？",a="勘察员基恩萨·铁环在洛克莫丹的挖掘工作已经停滞，因为队伍耗尽了爆破火药。吉恩·角盔无权自行申领更多补给；他需要得到铁炉堡探险者协会总部的正式批准。把进度报告交给勘察员塔伯斯·雷矛，是取得新一批火药、让挖掘继续进行的唯一行政途径。",al={"为什么送报告","吉恩·角盔的动机","吉恩为什么需要爆破火药"}}},fp="19,191,24.427.0,20.376.1,57.193.0,28.209.0,45.173.0,52.154.0,38.164.0,46.201.1"}
P.entries["quest:302"] = {n="铁环的火药",s="在铁炉堡，探险者协会将爆破火药运往南方，送到勘察员基恩萨·铁环位于洛克莫丹的挖掘场。勘察员塔伯斯·雷矛批准了这项申请，货物先运到塞尔萨玛，再继续运往铁环挖掘场。",h="在铁炉堡，探险者协会将爆破火药运往南方，送到勘察员基恩萨·铁环位于洛克莫丹的挖掘场。勘察员塔伯斯·雷矛批准了这项申请，货物先运到塞尔萨玛，再继续运往铁环挖掘场。",kw={"探险者协会","胡达尔","铁炉堡","吉恩·角盔","洛克莫丹","给铁环送火药","勘察员塔伯斯·雷矛","塞尔萨玛"},ang={["faction:Alliance"]="身为联盟旅人，协助维护洛克莫丹道路的安全，有助于维系铁炉堡与东部边疆之间的联系。",["profession:Mining"]="身为矿工，你知道爆破火药能帮助矿工和挖掘者凿穿深处的基岩。",["race:Dwarf"]="身为矮人，协助为挖掘工作筹措火药，就是在支持揭开族人神秘起源的神圣事业。"},sec={{t="官僚手续与爆破火药",b="探险者协会从铁炉堡向勘察员基恩萨·铁环在洛克莫丹南部的探险队运送爆破火药。挖掘场的火药不足时，消息便传到了协会的领导者那里。勘察员塔伯斯·雷矛批准了这项申请，并派信使前往塞尔萨玛寻找吉恩·角盔，那里是谷地的主要补给中心。"},{t="错过启程",b="此前穿越洛克莫丹的货车，有的失踪，有的遭到当地穴居人的骚扰。雷矛命令你亲自护送运送火药的货车。但当你抵达塞尔萨玛的烈酒旅店时，吉恩·角盔已经让胡达尔和两名矮人搬运工带着货车南下了。你急忙沿路追赶他们。"}},faq={{q="为什么要向铁环运送爆破火药？",a="勘察员基恩萨·铁环在洛克莫丹南部带领一支矮人考古队进行挖掘。他的队伍在开凿坚硬岩层时耗尽了爆破火药，而穴居人的攻势也愈发猛烈。",al={"为何需要火药","铁环爆破火药","火药的用途"}},{q="勘察员塔伯斯·雷矛是谁？",a="勘察员塔伯斯·雷矛是矮人探险者协会的一名高级官员，驻于铁炉堡的探险者大厅。他审核野外送来的申请，批准关键设备的调拨，并管理卡兹莫丹各大挖掘场的补给。",al={"雷矛的职责","任务给予者"}},{q="吉恩·角盔是谁？",a="吉恩·角盔是探险者协会在洛克莫丹塞尔萨玛的联络人。他筹备物资，并组织运输队，前往谷地更危险的边远地区。",al={"吉恩·角盔的位置","吉恩·角盔在哪"}},{q="为什么这批货物需要你亲自护送？",a="此前运往铁环挖掘场的货物未能抵达。从山间和挖掘场涌出的穴居人，让洛克莫丹的主干道变得越来越危险。",al={"为何护送火药","穴居人袭击货车"}},{q="你抵达塞尔萨玛时发生了什么？",a="吉恩·角盔已经派胡达尔和搬运工米兰、赛恩带着货车出发了。你沿着南下的道路追赶，争取在麻烦发生前赶上他们。",al={"是否错过货车","货物在哪"}},{q="这个任务如何融入探险者协会的故事线？",a="这次运送将挖掘场的申请送交铁炉堡的协会管理者，再经由塞尔萨玛将物资送回野外。这样，探险队就能继续挖掘。",al={"铁环任务链","挖掘任务线"}}},fx={["8773e6dd"]={q="勘察员塔伯斯·雷矛为什么派冒险者去，而不派正式卫兵？",a="勘察员塔伯斯·雷矛在铁炉堡的探险者大厅办公，主要处理行政事务和申请许可，并不负责调遣部队。此前运送的爆破火药已在洛克莫丹的道路上遭遇危险，因此他将希望寄托在一位正要前往野外、又有能力的旅人身上，请其亲自确保吉恩·角盔的补给车队安全抵达挖掘场。",al={"为何派我","为何不派卫兵去铁环那里","为何找冒险者"}}},fp="18,229,31.302.0,18.311.1,46.177.0,28.223.0,21.171.0,52.164.0,42.152.1,61.174.0"}
P.entries["quest:3022"] = {n="小心运送",s="克格尔·曲藤交给你一箱蛋，请你把它送给德鲁伊艾瑞拉斯·琥珀，他就在泰达希尔的一个小村庄鲁瑟兰。",h="克格尔·曲藤交给你一箱蛋，请你把它送给德鲁伊艾瑞拉斯·琥珀，他就在泰达希尔的一个小村庄鲁瑟兰。",kw={"克格尔·曲藤","艾瑞拉斯·琥珀","角鹰兽的蛋","鲁瑟兰村","塔纳利斯","泰达希尔"},sec={{t="一箱蛋",b="克格尔·曲藤交给你一箱仔细包装好的蛋。这些是角鹰兽的蛋，要送给一位名叫艾瑞拉斯·琥珀的德鲁伊。"},{t="鲁瑟兰的德鲁伊",b="艾瑞拉斯·琥珀是一位照料这些蛋的德鲁伊。他帮助这些蛋孵化，然后训练年幼的角鹰兽。鲁瑟兰村是泰达希尔南部的一个小村庄。"}},faq={{q="克格尔·曲藤交给你的箱子里装着什么？",a="仔细包装好的箱子里装着角鹰兽的蛋。",al={"箱子里有什么","仔细包装的箱子里装着什么","携带的是什么"}},{q="箱子需要送到哪里？",a="箱子要送给德鲁伊艾瑞拉斯·琥珀，他在泰达希尔的小村庄鲁瑟兰。",al={"箱子送到哪里","艾瑞拉斯·琥珀的位置","鲁瑟兰村在哪里"}},{q="艾瑞拉斯·琥珀是谁？",a="艾瑞拉斯·琥珀是鲁瑟兰村的一位德鲁伊。他照料角鹰兽的蛋，并在幼兽孵化后训练它们。",al={"艾瑞拉斯是谁","琥珀的故事","谁接收这些蛋"}}},fp="16,97,15.130.0,23.172.0,48.65.0,32.89.0,23.129.0"}
P.entries["quest:303"] = {n="黑铁战争",s="在湿地北缘的丹莫德，莫特雷·加玛森正率领守军拼死抵抗。破坏者炸毁萨多尔大桥后，黑铁氏族占据了城镇，铁炉堡巡山人只能勉强维持防线，等待或许永远不会到来的援军。",h="在湿地北缘的丹莫德，莫特雷·加玛森正率领守军拼死抵抗。破坏者炸毁萨多尔大桥后，黑铁氏族占据了城镇，铁炉堡巡山人只能勉强维持防线，等待或许永远不会到来的援军。",kw={"铜须","黑铁","爆破兵","丹莫德","铁炉堡","莫特雷·加玛森","破坏者","萨多尔大桥","湿地"},ang={["faction:Alliance"]="身为联盟的一员，你知道萨多尔大桥被毁、丹莫德陷落，切断了暴风城北方盟友与南方诸王国之间的陆路通道。",["profession:Engineering"]="身为工程师，你看得出黑铁破坏者使用的特制炸药，显露出他们对结构爆破令人胆寒的精通。",["race:Dwarf"]="身为铜须矮人，你知道丹莫德的失守是奇耻大辱，也直接威胁着卡兹莫丹的主权。是时候向世代仇敌复仇了。"},sec={{t="北方门户的战线",b="丹莫德曾守卫着宏伟的萨多尔大桥南端，这座大桥连接着卡兹莫丹与洛丹伦。黑铁的破坏者和爆破兵炸毁了桥拱，切断联盟的交通，随后攻占了这座要塞。莫特雷·加玛森与少数幸存的守军撤退到城外的一处观察营地。如果不发起反攻，这道北方门户恐将永远落入黑铁之手。"},{t="为预备军争取时间",b="矮人军团被派往遥远的联盟战场，莫特雷的小队只能大体依靠自己苦撑。他的斥候试图向铁炉堡传讯求援，但联络时断时续，承诺派来的预备军始终不见踪影。为了争取时间并扰乱敌人的防御部署，莫特雷下令深入丹莫德的废墟，展开精准突袭。目的是在黑铁的工程师、挖掘工和前线士兵继续向南推进、深入湿地之前，削减他们的兵力。"}},faq={{q="莫特雷·加玛森是谁？",a="莫特雷·加玛森是一名铁炉堡巡山人军官，指挥着丹莫德幸存的驻军。他以被占城镇外的一处营地为据点，协调侦察行动，并对黑铁部队发动游击袭击。",al={"莫特雷·加玛森","莫特雷是谁","丹莫德指挥官"}},{q="丹莫德为何对铁炉堡如此重要？",a="丹莫德扼守着萨多尔大桥的南端。这座大桥是连接卡兹莫丹、阿拉希高地与北方洛丹伦的唯一陆路干道，因此控制丹莫德，就意味着控制这些地区之间的陆路交通与物资运输。",al={"丹莫德为何重要","丹莫德的重要性","丹莫德背景故事"}},{q="黑铁矮人为何在湿地作战？",a="黑铁氏族长期以来一直试图破坏同族铜须的势力，削弱联盟。他们入侵湿地并摧毁萨多尔大桥，切断了铁炉堡通往北方的补给线，还在联盟疆域内部开辟了第二条敌对战线。",al={"黑铁为何在此","黑铁湿地","黑铁战争原因"}},{q="萨多尔大桥出了什么事？",a="黑铁的挖掘工和爆破兵在萨多尔大桥的承重拱基中集中埋设炸药，严重破坏了大桥。他们意图在攻占丹莫德之前，切断铁炉堡来自洛丹伦的援军。",al={"萨多尔大桥被毁","谁炸毁了大桥","萨多尔大桥爆炸"}},{q="铁炉堡的预备军在哪里？",a="铁炉堡的军力分散在远征与本土防御之中，已捉襟见肘。加玛森的斥候罗戈难以与最高指挥部保持可靠的联络，丹莫德的前哨只能依靠能找到的当地盟友坚守防线。",al={"铁炉堡预备军","援军在哪里","罗戈预备军"}},{q="击退丹莫德的黑铁之后会发生什么？",a="清除步兵和工兵能争取到宝贵的时间。罗戈的情报揭示，被关押在暴风城监狱的卡姆·深怒曾参与策划对萨多尔大桥的袭击，莫特雷请你把深怒的头颅带给他。",al={"黑铁战争后续任务","深深的愤怒任务","黑铁战争之后"}}},fp="17,264,28.416.0,28.480.0,23.209.0,42.249.0,51.260.0,34.234.0,39.232.0,59.227.1"}
P.entries["quest:304"] = {n="艰巨的任务",s="在黑铁矮人对丹莫德和萨多尔大桥发动毁灭性突袭之后，布莱德·长须誓要为阵亡的亲族和失去的士兵复仇。他委托勇敢的旅者去追踪并杀掉神出鬼没的黑铁术士巴尔加拉斯，并割下他的耳朵作为完成任务的证明。",h="在黑铁矮人对丹莫德和萨多尔大桥发动毁灭性突袭之后，布莱德·长须誓要为阵亡的亲族和失去的士兵复仇。他委托勇敢的旅者去追踪并杀掉神出鬼没的黑铁术士巴尔加拉斯，并割下他的耳朵作为完成任务的证明。",kw={"严酷的任务","“脏鬼”巴尔加拉斯","黑铁矮人","丹莫德","布莱德·长须","罗戈","萨多尔大桥","湿地"},ang={["class:Warlock"]="“脏鬼”巴尔加拉斯利用邪恶的魔能来策划对丹莫德守军的大屠杀，这展示了黑铁矮人利用其技艺所达到的危险目的。",["faction:Alliance"]="萨多尔大桥是连接卡兹莫丹和洛丹伦的主要陆路通道，这使得清除黑铁矮人破坏者成为整个联盟的战略重中之重。",["race:Dwarf"]="对于铁炉堡的矮人来说，黑铁矮人在丹莫德的背叛和暴力行为是一种人身侮辱，也是氏族间长期内战中一道新伤口。"},sec={{t="丹莫德废墟",b="湿地的北部地区目睹了铁炉堡登山者与黑铁矮人潜入者之间激烈的战斗。在围攻期间，丹莫德镇被占领，萨多尔大桥的西侧桥梁被摧毁。布莱德·长须不仅在袭击中失去了许多忠诚的士兵，还失去了自己的兄弟，这让他决心要让敌人血债血偿。"},{t="懦弱的指挥官",b="诸如罗戈之类的斥候侦察表明，占领丹莫德的黑铁矮人部队是由一名被称为“脏鬼”巴尔加拉斯的术士指挥的。巴尔加拉斯并不与敌人正面交锋，而是躲藏起来，指使他的士兵执行他那邪恶的计划。布莱德希望干掉巴尔加拉斯能打垮黑铁矮人部队的脊梁，让铁炉堡的幸存者能够收复这条通往北方的关键通道。"}},faq={{q="“脏鬼”巴尔加拉斯是谁？",a="“脏鬼”巴尔加拉斯是一名黑铁术士，指挥着占领湿地北部丹莫德的部队。布莱德·长须形容他是个胆小鬼，他回避直接战斗，转而派遣成群的黑铁矮人军队来守住该地区。",al={"巴尔加拉斯","巴尔加拉斯是谁","丹莫德的黑铁领袖"}},{q="布莱德·长须是谁？",a="布莱德·长须是一位驻扎在丹莫德废墟外的矮人指挥官。当黑铁矮人部队夺取该定居点并摧毁萨多尔大桥的西侧通道时，他失去了他的兄弟和许多士兵。",al={"布莱德","布莱德·长须","丹莫德任务发布者"}},{q="为什么布莱德想要巴尔加拉斯的耳朵？",a="因为巴尔加拉斯是一个难以捉摸的目标，经常躲避公开战斗，布莱德需要这位术士死亡的实物证明，以确保这种威胁确实已被消除。",al={"为什么需要耳朵","巴尔加拉斯的耳朵"}},{q="萨多尔大桥发生了什么事？",a="萨多尔大桥的西侧桥梁在黑铁矮人对丹莫德的突袭中被摧毁，切断了连接湿地和阿拉希高地之间的一条重要道路。",al={"萨多尔大桥被毁","为什么萨多尔大桥断了"}},{q="巴尔加拉斯躲在哪里？",a="巴尔加拉斯潜伏在丹莫德周围被占领的防御工事和废墟中，他躲在士兵身后，而不是冒险进入开阔的沼泽地。",al={"巴尔加拉斯在哪里","寻找巴尔加拉斯"}},{q="巴尔加拉斯被杀后会发生什么？",a="随着巴尔加拉斯的死亡，布莱德相信，在另一位指挥官赶来增援之前，剩下的那些群龙无首的黑铁矮人部队将更容易被清除。",al={"严酷的任务之后","丹莫德下一步"}}},fp="11,227,21.320.0,20.284.0,25.216.0,26.215.0,39.119.0,34.174.0,25.130.0,37.145.0"}
P.entries["quest:305"] = {n="寻找挖掘队",s="塔雷尔·石纹在湿地等待妻子麦琳从维尔加挖掘场传来消息。她已有两周没有来信，他担心东边的挖掘场遭遇了灾难。",h="塔雷尔·石纹在湿地等待妻子麦琳从维尔加挖掘场传来消息。她已有两周没有来信，他担心东边的挖掘场遭遇了灾难。",kw={"探险者协会","寻找挖掘队","长须","麦琳·石纹","塔雷尔·石纹","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="身为联盟的一员，你知道遍布沼泽地的矮人哨站和研究工作，有助于守护湿地，抵御荒野中的危险。",["race:Dwarf"]="身为矮人，你知道探险者协会以发掘古老历史为荣。你在 Whelgar Excavation 的同胞陷入困境，需要你的关注。"},sec={{t="丈夫的忧惧",b="塔雷尔·石纹已经两周没有收到妻子麦琳的消息了。过去，她在维尔加挖掘场工作时，每周都会给他写信，讲述工作的情况。如今，塔雷尔担心营地遭遇了灾难。矮人当局人手紧缺，他只得向路过的斥候求助，打听挖掘队员是否还活着。"},{t="维尔加挖掘场",b="维尔加挖掘场位于湿地东部，矮人在那里挖掘古老的 泰坦 遗物，探寻历史。在荒野中工作的队伍可能遭遇野兽，以及来自地下的威胁。挖掘场远离大路，而导致书信中断的变故，也让人难以与挖掘队员取得联系。"}},faq={{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是湿地的一名矮人，他的妻子麦琳在东边的挖掘场工作，却不再来信，这让他忧心忡忡。他把路过的冒险者当成了受派前来调查失联情况的斥候。",al={"塔雷尔·石纹","任务发布者","谁发布 寻找挖掘队"}},{q="麦琳·石纹是谁？",a="麦琳·石纹是一名矮人考古学家，在湿地米奈希尔港以东，随 维尔加挖掘场 队伍一起工作。她原本定期给丈夫写信，直到某件事让她的书信中断。",al={"麦琳·石纹","塔雷尔的妻子","麦琳是谁"}},{q="维尔加挖掘场在哪里？",a="维尔加挖掘场位于湿地，米奈希尔港以东、丹莫德西南方，在远离大路的岩石山脊之间。",al={"挖掘场位置","在哪里找麦琳","维尔加挖掘场 在哪里"}},{q="麦琳为什么不再来信？",a="麦琳不再来信，是因为挖掘场的一股威胁切断了研究人员与正常信使路线的联系，也打乱了营地生活。",al={"为什么来信中断","挖掘队出了什么事","为什么没有来信"}},{q="塔雷尔提到的“长须”是谁？",a="长须是一名矮人官员，曾答应在失去联系时派斥候去查看 维尔加挖掘场 队伍的情况。塔雷尔认为，任何前来帮忙的能干冒险者都是长须派来的。",al={"长须 是谁","长须 斥候"}},{q="靠近挖掘场安全吗？",a="不安全。维尔加挖掘场位于湿地危险的荒野之中，导致队伍每周来信中断的威胁，也危及所有抵达挖掘场的人。",al={"挖掘场安全吗","维尔加 危险"}}},fp="32,164,17.305.0,15.286.0,25.200.0,25.196.0,37.149.0,36.112.0,43.198.0,40.155.0"}
P.entries["quest:306"] = {n="寻找挖掘队",s="杂斑迅猛龙冲进维尔加挖掘场后，麦琳·石纹从那里捎来了消息。她在信中告诉塔雷尔·石纹，自己活了下来，但探险队的大多数成员都已遇难。",h="杂斑迅猛龙冲进维尔加挖掘场后，麦琳·石纹从那里捎来了消息。她在信中告诉塔雷尔·石纹，自己活了下来，但探险队的大多数成员都已遇难。",kw={"挖掘","米奈希尔港","麦琳·石纹","杂斑迅猛龙","奥莫尔","塔雷尔·石纹","湿地","维尔加"},ang={["faction:Alliance"]="身为联盟的旅行者，你知道湿地各处的野兽都威胁着定居点和人们的劳作。",["race:Dwarf"]="身为矮人，你知道麦格尼国王麾下的探险者远离铁炉堡时，会面临怎样的危险。这场灾难打击了矮人探索往昔的希望。"},sec={{t="废墟中的消息",b="麦琳·石纹在维尔加挖掘场上方的山脊上，有消息要向你报告。队员们正在发掘稀有文物和巨大的史前化石时，成群的杂斑迅猛龙冲进了挖掘场。大多数队员在袭击中丧生。麦琳和其他幸存者仍被困在那里，无法前往米奈希尔港。"},{t="悲喜交加",b="在米奈希尔港，塔雷尔·石纹得知妻子和至少两名同伴活了下来。奥莫尔英勇奋战，帮助他们逃出生天，让塔雷尔稍稍安心。然而，众多同僚的死讯仍让镇上的人们悲痛不已，也打击了他们开拓边疆的热忱。"}},faq={{q="湿地的挖掘队遭遇了什么？",a="这支矮人探险队正在发掘稀有文物和巨大的远古骸骨时，遭到了成群杂斑迅猛龙的袭击。大多数挖掘者惨遭杀害，只有少数人逃到挖掘场上方的高地，幸存下来。",al={"挖掘场发生了什么","湿地挖掘灾难","挖掘为何失败"}},{q="谁救了麦琳·石纹？",a="麦琳·石纹说，是奥莫尔击退了迅猛龙，护送她和勘察员到山脊上的安全地带。",al={"谁救了麦琳","奥莫尔·织石者","奥莫尔是谁"}},{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是麦琳的丈夫，正在米奈希尔港等候。挖掘场迟迟没有消息，让他忧心忡忡，于是他请旅行者去打听妻子的遭遇。",al={"塔雷尔是谁","塔雷尔·石纹位置"}},{q="挖掘场在哪里？",a="挖掘场位于湿地内陆，在米奈希尔港以东、丹莫德西南方。",al={"挖掘场在哪","维尔加挖掘场位置"}},{q="探险队在挖掘什么？",a="队员们在矮人勘察员的指挥下，挖掘埋藏在沼泽地下的稀有文物和大型史前化石。",al={"他们在挖什么","挖掘文物"}},{q="除了麦琳，还有其他幸存者吗？",a="有。麦琳说，奥莫尔和首席勘察员与她一同逃了出来，因此已知的幸存者共有三人。",al={"还有谁活了下来","挖掘场幸存者"}}},fp="32,185,24.311.0,15.239.0,53.200.0,28.122.0,25.163.0,30.99.0,36.141.0,40.95.0"}
P.entries["quest:3062"] = {n="黑暗之心",s="位于莫沙彻营地的塔罗·刺蹄想要埃达娜·恨爪的黑暗之心。她是居住在西边废墟中的北泉鹰身人女王。塔罗称她纯粹是邪恶的化身。",h="位于莫沙彻营地的塔罗·刺蹄想要埃达娜·恨爪的黑暗之心。她是居住在西边废墟中的北泉鹰身人女王。塔罗称她纯粹是邪恶的化身。",kw={"莫沙彻营地","黑暗之心","埃达娜·恨爪","菲拉斯","鹰身人","恨爪之石","北泉","塔罗·刺蹄"},sec={{t="鹰身人女王",b="埃达娜·恨爪是鹰身人的女王，统治着西边废墟中的北泉族群。塔罗称她纯粹是邪恶的化身，除了对他人的仇恨外，心中没有任何感情，并听说她的心脏是由水晶构成的。塔罗要你去面对她，并带回她的黑暗之心，因为她所散播的仇恨必须被终结。"},{t="召唤",b="塔罗听说鹰身人携带有一只号角。据传在废墟北部的恨爪之石附近吹响它，就能把女王引出来。塔罗很高兴想到，回应号角的将不会是她的族人，而是她的死亡。"},{t="当你归来时",b="塔罗现在确信埃达娜已经彻底消亡，并表示这颗心脏将被妥善保管，以纪念你的功绩。"}},faq={{q="埃达娜·恨爪是谁？",a="她统治着西部废墟中的北泉鹰身人。塔罗称她纯粹是邪恶的化身，说她只感受到仇恨，还听说她的心脏是水晶做的。",al={"埃达娜·恨爪","菲拉斯鹰身人女王","谁是鹰身人女王"}},{q="如何召唤埃达娜·恨爪？",a="塔罗听说鹰身人随身携带着一只号角，在废墟北端的恨爪之石附近吹响它，就能召唤出女王。",al={"如何召唤埃达娜","吹响号角 菲拉斯","恨爪之石"}},{q="是谁发布了狩猎埃达娜·恨爪的任务？",a="位于莫沙彻营地的塔罗·刺蹄。",al={"谁发布黑暗之心任务","塔罗·刺蹄","在哪里获得黑暗之心"}},{q="为什么塔罗·刺蹄想要埃达娜的心脏？",a="塔罗想要终结埃达娜在土地上散播的仇恨，因此索要她的黑暗之心。",al={"为什么需要黑暗之心","塔罗·刺蹄的动机"}}},fp="10,94,15.270.0,9.226.0,14.109.1,23.159.0,36.145.0,39.66.0,43.100.0"}
P.entries["quest:3063"] = {n="对鹰身人的复仇",s="塔罗·刺蹄曾经是一位经验丰富的猎人，无惧任何野兽，直到他被森林里的鸟妖伏击。从那以后，仇恨就在他心中沸腾，塔罗请求你去向西边的北泉鸟妖复仇。",h="塔罗·刺蹄曾经是一位经验丰富的猎人，无惧任何野兽，直到他被森林里的鸟妖伏击。从那以后，仇恨就在他心中沸腾，塔罗请求你去向西边的北泉鸟妖复仇。",kw={"菲拉斯","鸟妖","北泉","复仇","游羽","杀戮者","塔罗·刺蹄","唤风者"},sec={{t="老猎人的积怨",b="塔罗记得自己曾是一位经验丰富的猎人，无惧世间万物。直到在森林里的某一天，一场苦战过后，他正磨砺着武器，一群鸟妖包围了他。塔罗好不容易才逃出生天，但至今仍能听到她们的尖叫声在耳边回荡，从此他便不再是以前的自己了。事隔多年，那股仇恨依然在沸腾，塔罗渴望复仇。"},{t="北泉鸟妖",b="北泉鸟妖居住在西面。塔罗想要四只北泉鸟妖、四只北泉游羽、四只北泉唤风者和四只北泉杀戮者偿命。塔罗警告说，她们的翅膀如同黑夜一般，并且能潜入黑暗中消失不见。"},{t="狩猎之后",b="塔罗以老牛头人的口吻向你致谢，说你平复了他那颗备受煎熬的心。"}},faq={{q="塔罗·刺蹄是谁？",a="过去的一位老练猎人，无惧任何野兽，直到被森林里的鸟妖伏击。从此以后，塔罗就变了个人。",al={"塔罗·刺蹄的背景故事","谁发布了向北泉鸟妖复仇的任务","塔罗 菲拉斯"}},{q="北泉鸟妖在哪里？",a="在塔罗·刺蹄的西面。",al={"北泉鸟妖的位置","北泉鸟妖在哪里","菲拉斯鸟妖位置"}},{q="为什么塔罗想要向鸟妖复仇？",a="鸟妖在森林里伏击了塔罗，在他一场战斗后磨砺武器时包围了他，塔罗好不容易才逃脱。从此他便不再是以前的自己，而那股仇恨至今仍在心头翻涌。",al={"为什么要杀北泉鸟妖","塔罗·刺蹄的背景","塔罗为什么痛恨鸟妖"}},{q="塔罗想要杀掉哪些鸟妖？",a="四只北泉鸟妖、四只北泉游羽、四只北泉唤风者和四只北泉杀戮者。",al={"向北泉鸟妖复仇的目标","需要杀掉哪些鸟妖","北泉鸟妖的种类"}},{q="北泉鸟妖长什么样？",a="塔罗说她们的翅膀如同黑夜般漆黑，并警告说她们能遁入黑暗之中。",al={"鸟妖的外貌","北泉鸟妖的翅膀"}}},fp="28,168,22.297.0,23.259.0,14.103.1,22.125.0,42.59.0,47.177.0,36.131.0,42.93.0"}
P.entries["quest:3065"] = {n="普通石板",s="普通石板是初出茅庐的战士进入试炼谷的一种入门仪式。在证明了你对付当地野兽的勇气后，它会被交到你手中，指引你去找弗朗恩，这位当地的老兵负责将原始的蛮力转化为武技。",h="普通石板是初出茅庐的战士进入试炼谷的一种入门仪式。在证明了你对付当地野兽的勇气后，它会被交到你手中，指引你去找弗朗恩，这位当地的老兵负责将原始的蛮力转化为武技。",kw={"杜隆塔尔","弗朗恩","高内克","普通石板","大兽穴","试炼谷","战士"},ang={["class:Warrior"]="这份召唤标志着你踏上杜隆塔尔 The Warrior's Path 的第一步，直接指引你向弗朗恩学习基础姿态和打击技巧。",["faction:Horde"]="部落依靠源源不断的久经沙场的前线战士来保护杜隆塔尔那岌岌可危的边界，抵御半人马、野猪人和人类入侵者的威胁。",["race:Troll"]="在谷中训练的暗矛巨魔可能会听到弗朗恩对他（们）偏爱长矛胜过兽人斧头这一点的粗鲁评价，尽管他尊重任何能杀敌的手段。"},sec={{t="战斗的召唤",b="在证明了你能应付谷中的杂斑野猪后，高内克会把一张专门留给你的羊皮纸交给你。在杜隆塔尔恶劣的环境下，部落不会让他们的战士长时间缺乏指引。这块石板是一封邀请函，让你去找大兽穴外驻扎的战士训练师弗朗恩。"},{t="在大兽穴的阴凉处",b="弗朗恩在大兽穴外的阴凉处避暑，注视着从红色灌木丛中走来的新兵。他以老练的眼光评估着这些新兵，准备传授基础知识——无论是挥舞重斧还是使用长矛——以确保每一名新战士都能保卫年轻部落那脆弱的定居点。"}},faq={{q="什么是普通石板？",a="这是一份交给试炼谷年轻战士的入门指引。高内克将它传递下去，指引这些武技新兵去寻找驻地战士训练师弗朗恩。",al={"普通石板","这块石板是什么","战士笔记"}},{q="谁发送了这块石板？",a="这条信息来自大兽穴外休息的老兵、战士训练师弗朗恩，他一直在留意着新晋的战士。",al={"谁写的石板","谁发送了普通石板"}},{q="我在哪里可以找到弗朗恩？",a="弗朗恩驻扎在试炼谷内的大兽穴外，在岩石的遮蔽下躲避沙漠的烈日。",al={"弗朗恩位置","弗朗恩在哪里","寻找战士训练师"}},{q="弗朗恩为什么要提到长矛和斧头？",a="弗朗恩注意到了部落新兵中多样的战斗风格。虽然兽人偏爱双手斧这样沉重的砍刀，但巨魔和其他战士通常更喜欢长矛和轻便的长柄武器，这两者在战斗中都很有用。",al={"弗朗恩的长矛语录","为什么用长矛"}},{q="其他职业会接到这个任务吗？",a="不会。普通石板是专门给战士的。其他职业会收到属于他们自己的羊皮纸、符文或卷轴，指引他们去寻找各自的导师。",al={"普通石板是战士专属吗","试炼谷职业任务"}},{q="大兽穴的用途是什么？",a="大兽穴是试炼谷中一个有遮蔽的洞穴群，训练师、补给品和休息的新兵们会聚在这里，远离灼热的酷暑和游荡的野兽。",al={"什么是大兽穴","杜隆塔尔大兽穴"}}},fp="13,152,17.249.0,26.270.0,26.103.0,21.97.0,23.106.0,39.207.0,32.154.0,31.166.0"}
P.entries["quest:307"] = {n="肮脏的爪子",s="“肮脏的爪子”是巡山人卡尔·雷矛发布的一项任务，要求从被侵占的银泉矿洞中回收有价值的装备。尽管矿藏早已枯竭，但矿工联盟在狗头人侵入矿道之前，已将其改作仓库。矮人当局希望在巡山人对该地点发动毁灭性清洗之前，能够找回那些结实的工具。",h="“肮脏的爪子”是巡山人卡尔·雷矛发布的一项任务，要求从被侵占的银泉矿洞中回收有价值的装备。尽管矿藏早已枯竭，但矿工联盟在狗头人侵入矿道之前，已将其改作仓库。矮人当局希望在巡山人对该地点发动毁灭性清洗之前，能够找回那些结实...",kw={"肮脏的爪子","狗头人","洛克莫丹","矿工装备","矿工联盟","巡山人卡尔·雷矛","银泉矿洞","塞尔萨玛"},ang={["faction:Alliance"]="随着矮人的防御力量在卡兹莫丹各处分散，清理补给仓库可以确保重要的基础设施继续为联盟所用。",["profession:Mining"]="矿工们能够理解高品质矮人装备的价值，也明白让功能完好的工具在洞穴害虫的爪子里生锈是一件多么令人悲痛的事。",["race:Dwarf"]="对于矮人来说，看到粗鄙的狗头人玷污矿工联盟的手工艺品是一种侮辱，必须用迅捷的回收行动和锋利的钢铁来回应。"},sec={{t="枯竭的仓库",b="银泉矿洞坐落在奥加兹岗哨以东、洛克莫丹北部的山丘之中，很久以前就开采完了最后一点银矿脉。矮人矿工联盟并没有废弃这个地下建筑，而是将干燥的矿井重新改造为一个安全的仓库，用于存放备用的挖掘设备、十字镐和施工材料。在卡兹莫丹，只要有驻军守卫并抵御荒野的侵袭，坚固的地下隧道就是天然的仓库。"},{t="仓库里的爪子",b="矮人在洛克莫丹各地的警备力量有所削弱，狗头人趁机潜入了矿井。被黑暗的隧道和留下的闪亮铁制工具所吸引，这些害虫迅速将此地占为己有，当作巢穴。巡山人卡尔·雷矛急于带领一队战士进入隧道将它们消灭，但沉重的靴子和横扫的劈砍会震碎那些板条箱。冒险者必须潜入或一路杀进去，在全面进攻开始前把联盟的补给品取出来。"}},faq={{q="如果矿洞已经枯竭，为什么还要把装备留在里面？",a="在矿藏枯竭后，矿工联盟将银泉矿洞改建成了一个集中的存储仓库。矮人的地下隧道提供了坚固、干燥的庇护所，可以储存笨重的工具和物资，直到其他地方需要时再取出。",al={"为什么银泉矿洞里有装备","为什么矿洞里有工具","矿工联盟仓库"}},{q="为什么巡山人卡尔·雷矛不亲自清理矿洞？",a="卡尔·雷矛接到的命令是等待。此外，矿工联盟希望先将他们的装备取出来；如果卫兵冲进狭窄、黑暗的矿井，很可能会在激战中损坏那些装在板条箱里的精细工具。",al={"为什么雷矛不去","为什么巡山人要等待","雷矛任务原因"}},{q="银泉矿洞位于哪里？",a="矿洞位于洛克莫丹北部，奥加兹岗哨以东，巨石水坝以西南方向。",al={"银泉矿洞位置","银泉矿洞在哪里","“肮脏的爪子”发生地点"}},{q="为什么狗头人对矮人的工具如此感兴趣？",a="狗头人是强迫性的地下拾荒者。它们觊觎金属十字镐、铁铲、蜡烛和成品铁器，这些东西能让它们永无止境的挖掘工作变得更容易，因此满是矮人工具的仓库对它们来说是无法抗拒的战利品。",al={"为什么狗头人想要装备","狗头人偷窃工具","银泉矿洞的狗头人"}},{q="独自探索银泉矿洞危险吗？",a="矿洞内狭窄的通道和密集的狗头人使其变得十分危险。巡山人卡尔·雷矛明确警告说，独自前往的冒险者最好带上同伴。",al={"“肮脏的爪子”难吗","银泉矿洞难度","我能独自完成“肮脏的爪子”吗"}},{q="存放在矿洞里的物资属于谁？",a="这些物资属于铁炉堡矿工联盟，这是一个负责矮人王国境内的采石、采矿和管理地下资源的贸易协会。",al={"装备的主人是谁","矿工联盟的板条箱","谁经营矿工联盟"}}},fx={c638d192={q="巡山人卡尔·雷矛为什么想要找回矿工装备？",a="矿工联盟将矿藏枯竭的银泉矿洞改成了仓库，但狗头人侵入坑道，占据了里面的装备。虽然巡山人计划很快清剿这些害物，矿工联盟却坚持先把贵重的工具取出来。雷矛派你在部队清剿之前进去，以免动作粗鲁的矮人战士在即将到来的进攻中砸坏那些精密装备。",al={"雷矛为何想要装备","雷矛的肮脏的爪子动机","为何找回矿工装备"}},e40e35ce={q="矿工装备用来做什么？",a="这些装备是属于矿工联盟的优质矮人工具和物资。银泉矿洞的矿石开采殆尽后，矿工联盟将洞室改造成安全的仓库，用来储存作业装备。矿工联盟需要在战斗毁坏这些贵重器具之前，将它们完好无损地取回。",al={"矿工装备是什么","矿工装备的用途","矮人工具有何用"}},["31be8455"]={q="谁占据了银泉矿洞？",a="一群狗头人占据了旧矿洞的坑道。这些害物天生就喜欢地下洞穴和闪亮的金属，它们搬进矿藏枯竭的矿井，开始翻找储存的装备，用爪子玷污矮人的工具。",al={"谁在银泉矿洞里","肮脏的爪子的敌人","什么占据了矿洞"}}},fp="11,238,16.342.0,17.421.0,56.174.0,57.184.0,40.108.0,50.183.0,53.137.0,41.153.0"}
P.entries["quest:308"] = {n="加文的爱好",s="在卡拉诺斯的雷酒酿制厂，加文·雷酒看守着地窖里的存酒。家人禁止他在值守时饮用酒桶里的酒，于是他请你从楼上带些雷霆麦酒给他。他希望一杯酒能让自己头脑更敏锐。",h="在卡拉诺斯的雷酒酿制厂，加文·雷酒看守着地窖里的存酒。家人禁止他在值守时饮用酒桶里的酒，于是他请你从楼上带些雷霆麦酒给他。他希望一杯酒能让自己头脑更敏锐。",kw={"地窖","酿制厂","分散加文的注意力","丹莫罗","加文·雷酒","卡拉诺斯","雷霆麦酒"},ang={["class:Rogue"]="身为潜行者，你知道烈酒能分散守卫的注意力。而加文自己就提出了这样的要求。",["race:Dwarf"]="身为矮人，你知道守着一桶桶名酒却一口也喝不上的滋味有多煎熬。"},sec={{t="值守的口渴守卫",b="加文看守着深处的酒窖，四周都是丹莫罗最上等的烈性黑啤酒。家人禁止他在值守时饮用库存的酒。然而，他终究抵挡不住诱惑，请你从楼上的酒龙头接一品脱劲道十足的雷霆麦酒。"},{t="提神之说存疑",b="加文说，好酒能让他的感官更敏锐，值守时也更警觉。守卫是否该在当值时喝酒，那就是另一回事了。不过，想尝一口自家亲人酿的麦酒，少有身强体健的矮人会为此责怪一个雷酒家族的人。"}},faq={{q="加文·雷酒是谁？",a="加文·雷酒出身于声名远扬的雷酒家族。他在卡拉诺斯的雷酒酿制厂地窖里看守存放的酒桶。",al={"加文是谁","加文的故事","地窖里的守卫"}},{q="加文为什么需要别人给他送麦酒？",a="加文的家人禁止他在值守时饮用地窖里的存酒。于是，他请一个外人从楼上带一杯新接的麦酒给他，那些密封的酒桶便可以原封不动。",al={"加文为什么不能喝酒","加文的麦酒任务","为什么要取酒"}},{q="哪里能找到雷霆麦酒？",a="卡拉诺斯的雷酒酿制厂楼上有一间酒馆大厅，旅店老板和酒保在那里供应雷霆麦酒。",al={"获取雷霆麦酒","雷霆麦酒在哪里","购买雷霆麦酒"}},{q="雷酒酿制厂在哪里？",a="雷酒酿制厂是卡拉诺斯的中心旅店，坐落在丹莫罗白雪皑皑的腹地。从铁炉堡沿山路往下走不远就能到。",al={"卡拉诺斯酿制厂","雷酒地窖位置","加文在哪里"}},{q="雷酒家族的麦酒为什么如此有名？",a="雷酒家族的烈性黑啤酒和麦酒闻名于卡兹莫丹乃至更远的地方。它们浓烈的酒劲、风味和矮人酿酒特有的后劲广为人知。",al={"雷酒的名声","雷霆麦酒是什么"}},{q="把加文灌醉会惹出什么麻烦吗？",a="加文说，麦酒会让他头脑更敏锐，而不是更迟钝。不过，麦酒会分散他的注意力，让他顾不上那些在下层库房四处探查的人。",al={"加文喝醉的后果","分散加文注意力后会发生什么"}}},fx={a200e5d8={q="加文·雷酒为什么想要一桶雷霆麦酒？",a="加文奉命看守地窖，周围堆满了矮人烈酒，但严令禁止他动用自己看管的任何存货。他渴望喝上一口，提提神，也打发漫长的值守时光，因此需要一个行事谨慎的人，悄悄给他送来一点雷酒最好的佳酿，让他不必公然违纪也能过过酒瘾。",al={"加文为何想要麦酒","加文的动机","加文为何喝酒"}},["8c39bfa0"]={q="雷霆麦酒有什么用？",a="这桶雷霆麦酒是一份劲道十足的饮品，用来满足加文·雷酒的酒瘾。他在酿酒厂地窖深处站岗，指望你从上面的酒龙头给他接些酒来，好让他不必擅离职守，也不必动用储存的酒。",al={"雷霆麦酒有何用","雷霆麦酒的用途","为何取雷霆麦酒"}}},fp="18,241,23.266.0,19.230.0,26.143.0,46.179.0,27.114.0,44.135.0,33.147.0,44.134.0"}
P.entries["quest:3082"] = {n="风蚀石板",s="高内克给试炼谷的猎人送来一块雕刻石板。石板上有基沙的印记，召唤他们开始在荒野中接受训练。",h="高内克给试炼谷的猎人送来一块雕刻石板。石板上有基沙的印记，召唤他们开始在荒野中接受训练。",kw={"黑暗之矛","杜隆塔尔","风蚀石板","高内克","猎人","基沙","试炼谷"},ang={["class:Hunter"]="身为猎人，你初步跻身部落猎人的行列，开始在荒野中向当地的训练师学习。",["faction:Horde"]="身为部落的一员，你会看到兽人和巨魔分享各自的长处，帮助两个种族生存下去。",["race:Orc"]="身为兽人，你向黑暗之矛盟友学习精湛的潜行与追踪技艺，为族人的战士传统增添新的本领。",["race:Troll"]="身为巨魔，你能看到黑暗之矛的狩猎知识如何帮助部落在卡利姆多生存，并支援盟友。"},sec={{t="狩猎的召唤",b="新手猎人在大兽穴附近与野猪交战、证明自己后，高内克会给他们带来一块雕刻石板。石板上有基沙的印记。她是一位技艺娴熟的巨魔女猎手，就驻守在附近，这则口信表明，经验丰富的猎人已经注意到了这位新人的坚毅。接下来的课程不再只是应对当地的危险，而是要在荒野中接受有章法的训练。"},{t="生存之道的传承",b="基沙教导说，兽人和巨魔在部落中有着悠久的共同历史。兽人带来了享有盛名的战士与萨满祭司传统，黑暗之矛巨魔则带来了古老的潜行、追踪和生存技艺。这些技艺帮助兽人在艾泽拉斯生存下来。基沙训练新猎人的同时，两个种族也继续交流各自的知识，对狩猎的敬重将他们联系在一起。"}},faq={{q="是谁送来了风蚀石板？",a="这块刻有铭文的石板由基沙寄出，等你在试炼谷证明自己后，再由高内克转交。",al={"谁写了风蚀石板","石板寄送者","谁给了我这块石板"}},{q="在哪里能找到基沙？",a="基沙位于杜隆塔尔的试炼谷北部，与其他职业训练师一起待在大兽穴附近。",al={"基沙位置","基沙在哪里","寻找基沙"}},{q="为什么这里的巨魔训练师会教导兽人猎人？",a="基沙说，部落在艾泽拉斯艰难求生时，曾向巨魔求教狩猎知识。兽人早已熟悉战士和萨满祭司之道，而这两个种族至今仍在交流各自的技艺。",al={"为什么是巨魔猎人训练师","巨魔教导兽人","黑暗之矛猎人"}},{q="交还这块石板后会发生什么？",a="基沙会收你为徒，并随着你经验的增长，传授部落猎人的基础技巧、射击技能和生存之道。",al={"交还石板后做什么","风蚀石板奖励背景","基沙后续"}},{q="获得这块石板前，必须完成什么前置任务？",a="你必须先完成高内克的初始任务小试身手，杀死杂斑野猪，证明自己的耐力。",al={"石板前置任务","如何解锁风蚀石板","风蚀石板前置条件"}},{q="任何职业都能完成这个任务吗？",a="只有新手猎人才能在试炼谷收到这份训练召唤。其他职业会从高内克那里收到不同的召唤。",al={"谁能获得风蚀石板","风蚀石板职业要求","是否仅限猎人"}}},fp="13,120,21.359.0,23.357.0,28.108.0,28.99.0,45.195.0,42.152.0,62.109.0,34.124.0"}
P.entries["quest:3083"] = {n="密文石板",s="在试炼谷，高内克将一份加密的召令交给立志成为潜行者的新兵。召令指引他们前往大兽穴寻找鲁瓦格，在那里，潜行者的训练与碎手氏族联系在一起。",h="在试炼谷，高内克将一份加密的召令交给立志成为潜行者的新兵。召令指引他们前往大兽穴寻找鲁瓦格，在那里，潜行者的训练与碎手氏族联系在一起。",kw={"杜隆塔尔","密文石板","高内克","潜行者训练师","鲁瓦格","碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="身为潜行者，你通过这块石板结识自己的第一位导师鲁瓦格，并接触到碎手氏族在杜隆塔尔的势力。",["race:Orc"]="身为兽人，你的文化崇尚在战场上正面交锋，而兽人潜行者则担任斥候和渗透者，为如今的部落效力。",["race:Troll"]="身为巨魔，你将丛林追踪的本能融入大兽穴导师传授的刀刃技艺，在兽人盟友之中确立自己悄然行事的价值。"},sec={{t="加密的召令",b="高内克会将一块密文石板交给每个在对抗当地野兽时证明了自身实力的新兵。石板上的信息用密码写成，对于学习潜行、用毒和诡计的人而言，这既是恰当的考验，也是一道防范措施。召令指引新兵进入大兽穴，拜见鲁瓦格，他负责训练部落的潜行者、盗贼和扒手。"},{t="手的阴影",b="在大兽穴内，新兵会找到鲁瓦格，一名隶属于碎手氏族的密探。他告诉新来的潜行者，公会不会干涉他们的一举一动，但如果学徒表现不佳，手就会向他问责。初建的部落强敌环伺，十分依赖悄无声息的斥候和身手敏捷的扒手收集情报，并从暗处消除威胁。"}},faq={{q="密文石板有什么用途？",a="密文石板召集试炼谷的新手潜行者，让他们前往大兽穴内拜见自己的训练师鲁瓦格。",al={"石板有什么用","密文石板用途","为什么需要密文石板"}},{q="谁将石板交给玩家？",a="高内克负责监督谷中的试炼，在你击杀杂斑野猪、完成首次战斗试炼后，他会将石板交给你。",al={"谁给密文石板","石板任务给予者","高内克石板"}},{q="在哪里可以找到鲁瓦格？",a="鲁瓦格位于大兽穴深处，这片洞穴群坐落在试炼谷北侧的崖壁边。",al={"鲁瓦格位置","鲁瓦格在哪","寻找鲁瓦格"}},{q="鲁瓦格提到的“手”是什么？",a="鲁瓦格指的是碎手氏族，这是一个由刺客、间谍和潜行者组成的秘密网络与公会，为大酋长萨尔领导的部落效力。",al={"手是什么","碎手氏族 鲁瓦格","手是谁"}},{q="为什么石板上的文字要用密码书写？",a="密码能掩盖潜行者的机密事务及其联络人的身份，避开窥探的目光。它也能考验新兵是否有能力处理秘密信息。",al={"为什么加密","为什么使用密码","潜行者石板密码"}},{q="任何职业都能接取这个任务吗？",a="不能。只有在试炼谷开始冒险的巨魔潜行者才能获得密文石板。",al={"密文石板是否仅限潜行者","战士能做密文石板任务吗","石板职业限制"}}},fp="16,168,15.321.0,22.347.0,44.113.0,38.141.0,24.107.0,37.124.0,49.150.0,35.99.0"}
P.entries["quest:3084"] = {n="符文石板",s="在试炼谷，初出茅庐的萨满祭司会收到史克里克的召唤。这份召唤邀请有潜力的学徒，正式学习与先祖之灵及大地、火焰、水和空气四种元素沟通。",h="在试炼谷，初出茅庐的萨满祭司会收到史克里克的召唤。这份召唤邀请有潜力的学徒，正式学习与先祖之灵及大地、火焰、水和空气四种元素沟通。",kw={"杜隆塔尔","元素","高内克","萨满祭司","史克里克","石板","萨尔","试炼谷"},ang={["class:Shaman"]="身为萨满祭司，你收到这块石板，便意味着正式踏上了萨满之道。它赋予你职责，要你平衡元素之力，并以先祖的智慧引导他人。",["faction:Horde"]="身为部落的一员，你也传承着萨满之道，为严酷的边疆带来荣耀与平衡。",["race:Orc"]="身为兽人，你从这块石板中看到了萨尔所倡导的回归先祖萨满之道，告别受恶魔影响的过往所遗留的术士传统。",["race:Troll"]="身为巨魔，你在萨满之道中找到了与史克里克这样的兽人导师的共同之处。你将自己与先祖沟通的传统，同部落共有的元素传统结合起来。"},sec={{t="先祖之灵的召唤",b="初出茅庐的萨满祭司在试炼谷尘土飞扬的训练场上证明自己初步掌握了修行之道后，高内克便会交给他们一块雕刻的石板。石板上的符文承载着当地萨满祭司训练师史克里克的邀请。这份召唤告诉每一位学徒，他们已经准备好将目光投向肉搏之外，聆听自然世界深处的涌动。"},{t="新部落的精神领袖",b="在重获新生的部落中，萨满之道拥有神圣的地位。史克里克教导萨满祭司从四种元素中汲取力量，从先祖之灵那里获得支持。他们以大酋长萨尔为榜样，担任族人的精神向导，为族人提供智慧。在杜隆塔尔各地，他们守护着那些正在扎根的定居点。"}},faq={{q="符文石板是什么？",a="高内克会将一块刻有符文的石板交给试炼谷的萨满祭司新手，上面载有史克里克的召唤。它召唤年轻的冒险者，正式开始学习与先祖之灵和元素沟通的技艺。",al={"符文石板","石板物品","萨满祭司石板"}},{q="史克里克是谁？",a="史克里克是试炼谷大兽穴入口附近的萨满祭司训练师。她引导兽人和巨魔萨满祭司新手掌握元素之力，并了解自己作为部落精神领袖的职责。",al={"史克里克","史克里克是谁","试炼谷萨满祭司训练师"}},{q="史克里克为何在教导萨满祭司新手时提起萨尔？",a="恶魔的腐化吞噬了旧部落之后，大酋长萨尔带领先祖传下的萨满之道重获新生。史克里克以他为榜样，说明萨满祭司有责任维系元素的和谐，同时引导并保护自己的族人。",al={"为何提起萨尔","史克里克提起萨尔"}},{q="史克里克在哪里？",a="史克里克就在试炼谷东侧的大兽穴入口外，随时准备向萨满祭司新手传授入门技艺。",al={"史克里克在哪里","寻找史克里克"}},{q="谁会发放石板？",a="高内克负责监督初到试炼谷的新人的最初试炼。他会将石板交给已经初步证明自身胆识的学徒。",al={"谁发放石板","高内克石板"}},{q="史克里克传授的核心理念是什么？",a="史克里克教导萨满祭司从火焰、大地、水和空气中汲取力量，从先祖之灵那里获得毅力与决心。萨满祭司应当为自己加入的城镇或战团提供智慧与庇护。",al={"史克里克的理念","萨满祭司的教诲"}}},fp="21,190,21.323.0,37.317.0,34.197.0,15.206.0,60.227.0,25.141.0,25.149.0,40.210.0"}
P.entries["quest:3085"] = {n="神圣石板",s="在试炼谷，年轻的牧师完成首次试炼后，会收到肯杰的消息。这块石板召唤他们前去学习黑暗之矛牧师与灵魂沟通的方式。",h="在试炼谷，年轻的牧师完成首次试炼后，会收到肯杰的消息。这块石板召唤他们前去学习黑暗之矛牧师与灵魂沟通的方式。",kw={"黑暗之矛","杜隆塔尔","高内克","神圣石板","肯杰","牧师","灵魂","大兽穴","试炼谷"},ang={["class:Priest"]="身为牧师，你告别谷中的普通试炼，开始在大兽穴外接受肯杰正式的灵魂教导。",["faction:Horde"]="身为部落的一员，当你的族人在杜隆塔尔定居时，你帮助他们始终将灵魂仪式与灵魂的意志置于核心地位。",["race:Troll"]="身为巨魔，你遵循尊崇先祖灵魂和loa的黑暗之矛传统，而非异族牧师拘泥教条的方式。"},sec={{t="肯杰的消息",b="你在高内克的监督下击败野猪、证明自己后，他会交给你一块刻有文字的石头，名为神圣石板。上面的消息带有肯杰的印记。这位黑暗之矛秘术师在大兽穴外等候，照看那些受到信仰与灵魂魔法感召的新来者。"},{t="与灵魂沟通",b="部落中的黑暗之矛牧师寻求与灵魂和洛阿沟通，与大海彼岸信奉圣光的人类和矮人牧师不同。肯杰欢迎你来到杜隆塔尔，并教导你通过灵魂修行增强力量。随着你与灵魂的联系日益深厚，他会传授你更高深的仪式。"}},faq={{q="神圣石板是什么？",a="神圣石板上刻着巨魔牧师训练师肯杰写给试炼谷年轻牧师的消息。在你证明自己具备基本能力之前，石板由高内克保管。",al={"神圣石板是什么","神圣石板物品","石板背景故事"}},{q="肯杰是谁？",a="肯杰是一位黑暗之矛巨魔牧师训练师，位于试炼谷的大兽穴外。他教导年轻的入门者与灵魂沟通，学习治疗和暗影灵魂法术。",al={"肯杰","肯杰是谁","肯杰训练师"}},{q="为什么牧师一开始要与杂斑野猪战斗？",a="在专门的训练师花时间指导你之前，你需要证明自己具备基本的自立和生存能力。试炼谷的每一位入门者都要面对这项考验，无论他们选择何种职业。",al={"为什么杀野猪","与小试身手的关联"}},{q="肯杰的牧师之道与圣光有何不同？",a="黑暗之矛牧师呼唤灵魂和洛阿神灵，而人类和矮人的教会则崇拜圣光。肯杰教导牧师，他们必须维系这些无形力量的眷顾，并与之和谐共处。",al={"巨魔牧师背景故事","部落牧师","灵魂与圣光的区别"}},{q="大兽穴在哪里？",a="大兽穴是杜隆塔尔南部试炼谷中一处开凿于洞穴内的聚居地。训练师和试炼导师以这里为据点，指导部落的新兵。",al={"杜隆塔尔大兽穴","大兽穴在哪里","肯杰位置"}},{q="兽人能通过这个任务成为牧师吗？",a="不能。在试炼谷，只有黑暗之矛巨魔拥有在肯杰门下修习牧师之道所需的灵魂传统。兽人文化则遵循萨满之道与术士魔法。",al={"兽人牧师","兽人能成为牧师吗","兽人神圣石板"}}},fp="15,175,22.264.0,26.302.0,28.188.0,15.181.0,51.186.0,57.189.0,17.149.0,43.174.0"}
P.entries["quest:3086"] = {n="雕文石板",s="在试炼谷，一块雕文石板指引年轻的部落法师前去拜见迈安。高内克会在他们证明实力后将石板交给他们，而这位巨魔训练师就在大兽穴外等候。",h="在试炼谷，一块雕文石板指引年轻的部落法师前去拜见迈安。高内克会在他们证明实力后将石板交给他们，而这位巨魔训练师就在大兽穴外等候。",kw={"奥术","杜隆塔尔","雕文石板","高内克","法师","迈安","大兽穴","试炼谷"},ang={["class:Mage"]="身为法师，你会得到谷中训练师的正式欢迎，加入部落施法者的行列。迈安会教你掌控原始魔力所需的自律。",["race:Orc"]="身为兽人，你在迈安的指导下踏上一条少有人走的道路。兽人文化长期受到萨满祭司和战士的影响，你的族人中很少有人尝试研习奥术。",["race:Troll"]="身为黑暗之矛巨魔，你跟随迈安学习，反映出你的部族在保留传统灵魂仪式的同时，也日益广泛地运用系统的施法技艺。"},sec={{t="刻在石板上的讯息",b="你已在与试炼谷野兽的较量中证明了自己的实力，高内克交给你一块刻有文字的石板。这是谷中的法师训练师迈安送来的。她请你在准备好开始研习奥术时，到大兽穴入口处找她。"},{t="无形的危险",b="迈安直言不讳地讲述法师掌握的力量，以及随之而来的危险。她警告说，法师最大的威胁是魔法引人堕落的无形力量，而非与他们为敌的战士或种族。她说，谦逊和耐心至关重要，因为不加约束的魔法会让法师高估自己对力量的掌控。"}},faq={{q="谁将雕文石板交给玩家？",a="你清除试炼谷的杂斑野猪后，高内克会将石板交给你。",al={"谁给雕文石板","哪里领取雕文石板","雕文石板起始人"}},{q="迈安是谁？",a="迈安是一位黑暗之矛巨魔法师训练师，就在试炼谷的大兽穴外。她向部落的新手法师传授基础法术，并告诫他们提防奥术的腐化。",al={"迈安是谁","迈安背景故事","巨魔法师训练师"}},{q="迈安在哪里？",a="迈安就在试炼谷北部的大兽穴入口外等候，位于洞口右侧。",al={"迈安在哪里","迈安位置","寻找迈安"}},{q="迈安对魔法提出了什么警告？",a="迈安警告说，魔法会腐化使用它的人。她说，比起兽人、精灵或矮人这类有形的敌人，法师更应畏惧魔法无形的诱惑和对力量的妄想。",al={"迈安的警告","魔法腐化背景故事","迈安说了什么"}},{q="其他职业也会收到雕文石板吗？",a="不会。雕文石板是给新手法师的。其他职业会收到各自训练师发来的不同入门召唤信物，例如符文、卷轴或符印。",al={"其他职业能领取雕文石板吗","雕文石板是否仅限法师"}},{q="收到这块石板需要满足什么前提条件？",a="你必须先完成高内克交给你的初始任务，杀死试炼谷红土平地上的杂斑野猪。",al={"雕文石板领取条件","雕文石板前置条件"}}},fp="14,178,28.246.0,25.290.0,46.86.0,14.168.0,24.112.0,42.188.0,44.158.0,53.121.0"}
P.entries["quest:3087"] = {n="风蚀羊皮纸",s="在试炼谷，风蚀羊皮纸召唤一名年轻猎人前去拜见基沙。新兵初次浴血后，高内克便将它交到新兵手中，开启了在杜隆塔尔接受荒野训练的道路。",h="在试炼谷，风蚀羊皮纸召唤一名年轻猎人前去拜见基沙。新兵初次浴血后，高内克便将它交到新兵手中，开启了在杜隆塔尔接受荒野训练的道路。",kw={"黑暗之矛","杜隆塔尔","风蚀羊皮纸","高内克","猎人训练师","基沙","试炼谷"},ang={["class:Hunter"]="作为猎人，这封召集信指引你前去拜见基沙，磨炼射术，了解荒野。",["faction:Horde"]="作为部落猎人，你负责侦察边境，为营地提供食物。早期训练有助于保障杜隆塔尔的补给与防卫。",["race:Orc"]="作为兽人，你依靠基沙这样的导师，将氏族的狩猎方法用于应对杜隆塔尔干旱的峭壁和致命的野兽。",["race:Troll"]="作为黑暗之矛新兵，向基沙学习，能让从回音群岛传承而来的古老丛林追踪传统延续下去。"},sec={{t="荒野的召唤",b="在试炼谷，猎人击杀杂斑野猪、证明自己后，会从高内克那里收到风蚀羊皮纸。基沙是一位技艺精湛的黑暗之矛猎人，她在营地边缘观察新来者后，送来了这封信。信中欢迎新兵接受正式训练，也肯定了他们具备驾驭杜隆塔尔的野兽、征服这片严酷土地所需的本能。"},{t="猎人之道",b="向基沙报到，意味着从新兵成长为专注狩猎的追踪者。她告诫学徒，狩猎并不比奥术或传承自先祖的萨满之道更容易。驾驭杜隆塔尔的掠食者、保养远程武器，以及在严酷的土地上生存，都需要严明的自律。基沙派学徒去帮助谷中的其他居民，磨炼自己的能力，然后再回来学习更高深的生存技巧。"}},faq={{q="风蚀羊皮纸是什么？",a="风蚀羊皮纸是高内克代猎人训练师基沙转交的一封召集信。它召唤有潜力的新兵前去拜见她，在试炼谷接受专门的战斗与荒野生存训练。",al={"这张羊皮纸是什么","风蚀羊皮纸信件","猎人羊皮纸"}},{q="谁将这封召集信交给玩家？",a="你在试炼谷击杀杂斑野猪、完成首次试炼后，高内克便会将羊皮纸交给你。",al={"谁给风蚀羊皮纸","任务在哪里接"}},{q="基沙是谁？",a="基沙是一名驻守试炼谷的黑暗之矛巨魔猎人。她评估新来的兽人和巨魔猎人，传授远程作战、追踪和驭兽之术。",al={"基沙背景故事","基沙是谁"}},{q="基沙为什么将猎人与法师和萨满祭司相比？",a="基沙告诫学徒，许多人误以为狩猎比与先祖之灵沟通或研习奥术魔法更容易。练就致命的射术、掌握驾驭野兽的本领，同样需要全心投入，也同样伴随着危险。",al={"猎人为何不容易","基沙对话含义"}},{q="向基沙报到后会发生什么？",a="基沙会向你传授进阶的猎人技巧，并派你帮助试炼谷的其他居民。你将在实际的生存历练中练习新学到的技能。",al={"风蚀羊皮纸之后做什么","猎人任务后续"}},{q="谁能接到这个任务？",a="只有在试炼谷受训的新建兽人猎人角色才能接到这个任务。",al={"谁能接风蚀羊皮纸","是否仅限猎人"}}},fp="16,176,23.357.0,16.431.0,29.200.0,40.107.0,16.165.0,55.194.0,41.183.0,27.79.0"}
P.entries["quest:3088"] = {n="密文羊皮纸",s="在试炼谷，密文羊皮纸指引通过考验的兽人潜行者新兵前往大兽穴。纸上的密文指引他们去找鲁瓦格，一名碎手氏族的密探。",h="在试炼谷，密文羊皮纸指引通过考验的兽人潜行者新兵前往大兽穴。纸上的密文指引他们去找鲁瓦格，一名碎手氏族的密探。",kw={"杜隆塔尔","密文羊皮纸","高内克","兽人潜行者","鲁瓦格","碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="身为潜行者，这张羊皮纸标志着你加入了部落的秘密队伍。它引领你结识鲁瓦格，开始最初的专业训练。",["faction:Horde"]="身为部落的一员，你知道，即便是萨尔这样崇尚荣誉的大酋长，也需要间谍和斥候来保护杜隆塔尔这片新生的土地，抵御暗藏的威胁。",["race:Orc"]="身为兽人，你既要恪守祖先的纪律，也要掌握碎手氏族所要求的不动声色的狡黠，与那些在正面厮杀中追求嗜血荣耀的战士不同。"},sec={{t="密文召令",b="高内克将密文羊皮纸交给那些已在对抗当地野兽时证明自己的兽人新兵。其他训练师在空地上公开招收学徒，潜行者训练师鲁瓦格却用密文传达召令。这封信指引你离开阳光下的营地，深入名为大兽穴的洞窟。"},{t="暗影中的眼睛",b="进入大兽穴，你会发现鲁瓦格正在岩石间监视四周。术士潜伏在洞穴更深处，而他告诉你，他正在为碎手氏族物色新兵。兽人社会崇尚光明磊落的荣誉与战场上的荣耀，碎手氏族却是部落隐秘的情报网络，成员包括间谍、杀手和情报搜集者。"}},faq={{q="谁寄出了密文羊皮纸？",a="羊皮纸由试炼谷的潜行者训练师鲁瓦格写就。他让高内克在前途可期的年轻兽人完成最初的试炼后，将这封密信交给他们。",al={"谁写的羊皮纸","谁给的密文羊皮纸","谁寄的信"}},{q="这个任务的目的是什么？",a="羊皮纸指引兽人潜行者前往大兽穴寻找鲁瓦格，在那里开始正式训练。他传授潜行、开锁和战斗中的诡诈之术。",al={"为什么需要密文羊皮纸","这个任务有什么用"}},{q="鲁瓦格在哪里？",a="鲁瓦格藏身于大兽穴，那是试炼谷北侧的一处幽暗洞窟。他待在入口附近，提防着洞穴深处的术士。",al={"鲁瓦格在哪","寻找鲁瓦格","鲁瓦格位置"}},{q="羊皮纸为什么要加密？",a="密文能防止四处游荡的莽汉和好奇的外人读懂召令。这也能考验新兵是否有能力破解秘密讯息。",al={"为什么用密文","信为什么要加密"}},{q="碎手氏族是什么？",a="碎手氏族最初是一个以自残闻名、声名狼藉的兽人氏族。在萨尔的部落中，它是由斥候、刺客和秘密特工组成的组织，在暗影中行动，维护部落的利益。",al={"碎手氏族 部落","碎手氏族是什么"}},{q="鲁瓦格为什么不信任纳托克？",a="纳托克是大兽穴深处的一名术士训练师。鲁瓦格不信任那些在洞穴最深处的角落里公然举行邪能仪式的黑暗施法者。",al={"鲁瓦格 纳托克","鲁瓦格为什么讨厌术士"}}},fp="19,154,15.295.0,19.316.0,34.160.0,34.144.0,22.150.0,31.144.0,27.212.0,30.145.0"}
P.entries["quest:3089"] = {n="符文羊皮纸",s="在试炼谷，一封刻有符文的召集信指引初入萨满之道的人去见史克里克。高内克交出的这张羊皮纸，开启了他们与灵魂和元素沟通的正式修行。",h="在试炼谷，一封刻有符文的召集信指引初入萨满之道的人去见史克里克。高内克交出的这张羊皮纸，开启了他们与灵魂和元素沟通的正式修行。",kw={"先祖","杜隆塔尔","元素","高内克","符文羊皮纸","萨满","史克里克","试炼谷"},ang={["class:Shaman"]="作为萨满祭司，这张羊皮纸标志着你踏上灵魂修行之路的第一步，将你与灵魂和杜隆塔尔的原始元素紧紧相连。",["race:Orc"]="作为兽人，你重归萨满之道，是对德拉诺先祖传统的尊崇，这些传统曾因Old Horde遭受恶魔腐化而几近消亡。",["race:Troll"]="作为黑暗之矛巨魔，你将与生俱来的灵魂沟通能力和对先祖的敬意，融入部落共同的萨满传统。"},sec={{t="灵魂的召唤",b="兽人萨满新手在与当地野兽的较量中证明自己的生存本领后，会从试炼谷的管理者高内克那里收到一张符文羊皮纸。上面的神秘文字出自谷中的萨满祭司训练师史克里克之手，她希望见见这位初来乍到的学徒。"},{t="萨满之道",b="与史克里克会面，意味着萨满祭司开始肩负起为部落效力的神圣职责。她教导学徒，萨满祭司既是先祖之魂的媒介，也是元素之怒的驾驭者。在她的指引下，萨满新手学会引导灵魂能量、治愈伤口，并召唤卡利姆多的自然之力。"}},faq={{q="符文羊皮纸是什么？",a="高内克会交给试炼谷的萨满新手一封召集信，让他们前往训练师史克里克处接受正式教导。",al={"这是什么任务","羊皮纸任务","萨满新手信件"}},{q="是谁送来的羊皮纸？",a="史克里克是试炼谷洞穴附近的萨满祭司训练师，这封信就是她写的。她正等待那些被选中在精神上指引族人的人。",al={"谁写的羊皮纸","史克里克的信","史克里克是谁"}},{q="我该把羊皮纸送到哪里？",a="你只需带着羊皮纸在试炼谷内走上一小段路，史克里克就在赤红的峭壁下等候，教导兽人和巨魔萨满祭司。",al={"该去哪里","史克里克在哪里","交任务地点"}},{q="为什么我的角色会被选中收到它？",a="史克里克说，受萨满之道感召的人被选中作为先祖的媒介，与世间的元素之力交谈。",al={"为什么是萨满","为何被选中","萨满召唤的背景故事"}},{q="交出羊皮纸后会发生什么？",a="史克里克会收你为徒，教你认识元素魔法、与先祖沟通，以及治疗和战斗的基础。",al={"下一步","史克里克做什么","交出羊皮纸之后"}},{q="任何职业都能完成这个任务吗？",a="不能。符文羊皮纸是给萨满新手的。其他职业会收到各自训练师发来的不同召集信。",al={"是否仅限萨满","谁会收到这张羊皮纸","战士的羊皮纸"}}},fp="24,168,26.258.0,22.282.0,37.122.0,24.142.0,30.132.0,42.132.0,44.138.0,34.116.0"}
P.entries["quest:309"] = {n="护送货物",s="在洛克莫丹南部，米兰正将爆破火药运往铁环挖掘场。勘察员基恩萨·铁环需要这些火药来开展挖掘，但补给线中断，运货马车又受到威胁，米兰因此被困在途中。",h="在洛克莫丹南部，米兰正将爆破火药运往铁环挖掘场。勘察员基恩萨·铁环需要这些火药来开展挖掘，但补给线中断，运货马车又受到威胁，米兰因此被困在途中。",kw={"爆破火药","黑铁伏击","铁环挖掘场","洛克莫丹护送","米兰","勘察员基恩萨·铁环"},ang={["faction:Alliance"]="身为联盟的一员，你帮助洛克莫丹的信使抵御来自地下的劫掠者，维系铁炉堡与东部边疆之间的联系。",["profession:Mining"]="身为矿工，你深知在开凿卡兹莫丹坚硬的基岩时，爆破火药既有价值，也有危险。",["race:Dwarf"]="身为铁炉堡的矮人，你守护铁环的补给，保护先祖遗迹的发掘成果，免遭与你们仇深似海的黑铁同族破坏。"},sec={{t="危机四伏的火药运输",b="勘察员基恩萨·铁环需要爆破火药来炸开挖掘场的岩石。米兰带着沉重的货物，被困在危机四伏的道路上。你护送他沿着崎岖的道路前往挖掘场，让火药顺利送达。"},{t="黑铁的同情者",b="黑铁渗透者埋伏在挖掘场附近，企图夺取这批爆炸物。他们的伏击表明，黑铁势力正在获取非法物资，并在洛克莫丹制造纷争。这批货物让挖掘工作得以继续，但铁环如今知道，敌人的破坏活动已经深入联盟领土。"}},faq={{q="米兰是谁？",a="米兰是一名联盟信使，负责沿着洛克莫丹危险的偏僻小路，将包括爆破火药在内的重要补给运往铁环挖掘场。",al={"米兰是谁","米兰 洛克莫丹","信使米兰"}},{q="勘察员基恩萨·铁环为什么需要火药？",a="勘察员基恩萨·铁环在洛克莫丹南部主持考古挖掘。他的队伍需要爆破火药来清除岩石，发掘埋藏的遗物，让工作继续进行。",al={"铁环为什么需要火药","火药用途","铁环 爆破火药"}},{q="护送途中是谁发动了袭击？",a="黑铁矮人破坏者在挖掘场附近伏击米兰，企图夺取爆炸物，并阻挠铁炉堡在这一地区的行动。",al={"谁伏击米兰","伏击者","护送途中的袭击者"}},{q="护送的终点在哪里？",a="护送路线沿洛克莫丹南部的一条道路前行，终点是湖泊东南方丘陵中的铁环挖掘场。",al={"护送终点","米兰去哪里","铁环在哪里"}},{q="黑铁矮人为什么会出现在洛克莫丹？",a="黑铁氏族在卡兹莫丹各地设有秘密据点，并安插了间谍。他们袭击补给线，破坏探险者协会的挖掘场，企图削弱铁炉堡的防御。",al={"黑铁 洛克莫丹","黑铁矮人为何在此","黑铁的踪迹"}},{q="货物送达后会发生什么？",a="勘察员基恩萨·铁环收到了火药，并为货物顺利送达而感谢圣光，尽管附近仍有黑铁的同情者在活动。",al={"任务后续","护送货物之后","下一个任务"}}},fx={a48eefd2={q="米兰为什么想要完成这件事？",a="米兰奉命将至关重要的爆破火药运过敌人出没的地区，送到勘察员基恩萨·铁环的挖掘场。货物沉重，道路凶险，潜伏的黑铁伏兵更让这趟行程危机四伏。他无法在这条险路上一边搬运不稳定的货物，一边保护自己。",al={"米兰的动机","为何护送米兰","为何运送火药"}},bdc08a2b={q="米兰为什么需要你帮忙，而不找当地卫兵？",a="洛克莫丹的巡山人既要抵御穴居人的入侵，又要保卫各处主要聚落，早已兵力不足。没有正规巡逻队能护送补给，米兰只能依靠像你这样有能力的冒险者，击退潜伏在山间的黑铁矮人。",al={"米兰为何找我","米兰为何需要帮助","米兰为何没有巡山人护送"}}},fp="23,214,21.234.0,22.293.1,13.155.0,45.165.0,30.146.0,27.123.0,33.171.0,40.129.0"}
P.entries["quest:3090"] = {n="被污染的羊皮纸",s="你离开后，一张被污染的羊皮纸正等着你，你的导师纳托克想与你谈谈。纸上的文字质疑萨尔的统治，并警告术士们面临的危险。",h="你离开后，一张被污染的羊皮纸正等着你，你的导师纳托克想与你谈谈。纸上的文字质疑萨尔的统治，并警告术士们面临的危险。",kw={"大兽穴","纳托克","奥格瑞玛","施法","被污染的羊皮纸","萨尔","试炼谷","术士"},ang={["class:Warlock"]="身为术士，你面临着纳托克所警告的危险：鲁莽地运用力量可能致命。"},sec={{t="一封待阅的信",b="这张被污染的羊皮纸据信出自你的新导师纳托克之手。读完后，去试炼谷的大兽穴与他交谈。他称兽人是一个骄傲的民族，并说萨尔拒绝接受一种足以让兽人拥有这片土地的力量。"},{t="跻身其中",b="纳托克说你已经加入了他们的行列，但术士的力量并不会让你受到欢迎。萨尔允许术士进入奥格瑞玛，因为他们仍然是兽人。纳托克警告你，鲁莽行事可能致命。如果你需要指导，他随时愿意教你施法。"}},faq={{q="是谁送来了羊皮纸？",a="这张羊皮纸据信来自你的新导师纳托克。",al={"谁送来的","羊皮纸来自谁"}},{q="我可以在哪里与纳托克交谈？",a="纳托克就在试炼谷的大兽穴。",al={"纳托克在哪里","纳托克的位置"}},{q="纳托克如何看待萨尔？",a="纳托克说，萨尔拒绝接受那股足以让这片土地归他们所有的力量。",al={"对萨尔的看法","为何批评萨尔"}},{q="萨尔为什么允许术士进入奥格瑞玛？",a="纳托克说，萨尔允许术士进入奥格瑞玛，因为他们仍然是兽人。",al={"奥格瑞玛的术士","萨尔为何容许术士"}},{q="纳托克给出了什么警告？",a="纳托克警告你，拥有术士的力量并不意味着会被接纳，而鲁莽行事可能致命。",al={"纳托克的警告","术士的危险"}},{q="纳托克能教我法术吗？",a="如果你需要施法方面的指导，纳托克随时愿意教你。",al={"法术教学","术士训练"}}},fp="17,176,15.241.0,18.262.1,23.64.0,30.45.0,33.73.0,46.78.0,30.90.0,27.65.0"}
P.entries["quest:3091"] = {n="简易便笺",s="在纳拉其营地，哈鲁特·雷角召唤年轻的牛头人战士保卫族人。他的召令提醒他们，战士与德鲁伊和萨满祭司并肩守卫部族边界，抵御半人马。",h="在纳拉其营地，哈鲁特·雷角召唤年轻的牛头人战士保卫族人。他的召令提醒他们，战士与德鲁伊和萨满祭司并肩守卫部族边界，抵御半人马。",kw={"纳拉其营地","半人马","哈鲁特·雷角","莫高雷","红云台地","简易便笺","牛头人","战士"},ang={["class:Warrior"]="哈鲁特·雷角教导初出茅庐的牛头人战士收敛傲气，保卫纳拉其营地，抵御半人马。",["race:Tauren"]="对于在红云台地踏上旅程的年轻牛头人来说，这张便笺表明，保卫部族与追随萨满之道和德鲁伊之道等精神追求同样重要。"},sec={{t="战斗的召唤",b="在纳拉其营地，一名信使为年轻的战士们带来了哈鲁特·雷角的召令。这位经验丰富的训练师召集每一位战士前来报到，开始接受保卫部族的训练。"},{t="守护者的重担",b="舒哈鲁 敬重他们的精神领袖，但 哈鲁特 教导战士们，他们肩负着同样的重担。他们巡逻部族边界，猎杀四处劫掠的半人马群，保护爱好和平的族人免遭袭击。战斗或许会带来荣耀，但战士仍须保持谦逊，完成与萨满祭司和德鲁伊相同的传统仪式。"}},faq={{q="简易便笺是谁写的？",a="哈鲁特·雷角写下了这份召令，并派信使将它送给准备接受战斗训练的年轻牛头人。",al={"谁送来了 简易便笺","便笺是谁写的","简易便笺 送信人"}},{q="哈鲁特·雷角是谁？",a="哈鲁特·雷角是莫高雷纳拉其营地的一位牛头人战士训练师。他教导新晋战士战斗技巧，以及祖辈传承下来的部族作战之道。",al={"哈鲁特 是谁","哈鲁特·雷角","哈鲁特 在哪里"}},{q="简易便笺有什么用途？",a="这张便笺召唤刚刚觉醒的战士前去拜见训练师。它提醒他们，守护者和猎人与德鲁伊和萨满祭司一样，对部族至关重要。",al={"便笺为何重要","便笺写了什么"}},{q="为什么要召集战士猎杀半人马？",a="敌对的半人马群威胁着莫高雷的边界。哈鲁特 训练战士猎杀他们，保护营地。",al={"为何与半人马作战","牛头人与半人马的冲突"}},{q="纳拉其营地位于何处？",a="纳拉其营地坐落在莫高雷的红云台地边缘。这里是鹰风部族世代相传的训练营，也是部族年轻牛头人踏上旅程的起点。",al={"纳拉其营地位置","纳拉其营地在哪里"}},{q="哈鲁特 提到的部族仪式是什么？",a="文中没有说明这些仪式的名称。文中说，每一位部族成员，从战士和猎人到萨满祭司和德鲁伊，都必须经历这些仪式，以证明自己的力量、谦逊和对族人的奉献。",al={"牛头人成年仪式","牛头人要经历什么仪式"}}},fp="11,203,19.174.0,21.316.0,26.112.0,26.149.0,39.153.0,45.107.0,30.160.0,42.190.0"}
P.entries["quest:3092"] = {n="风化便笺",s="在纳拉其营地，风化便笺召唤一名年轻的牛头人猎人，前去跟随兰卡·远箭接受训练。这封信开启了这名猎人研习荒野之道的旅程。",h="在纳拉其营地，风化便笺召唤一名年轻的牛头人猎人，前去跟随兰卡·远箭接受训练。这封信开启了这名猎人研习荒野之道的旅程。",kw={"纳拉其营地","风化便笺","兰卡·远箭","莫高雷","红云台地","牛头人猎人"},ang={["class:Hunter"]="作为猎人，你开始学习射击、野外生存，以及如何与野兽伙伴共同生活。",["race:Tauren"]="作为Shu'halo，你尊重那些在莫高雷平原上供养部族的野兽，以此向Earth Mother致敬。"},sec={{t="狩猎的召唤",b="格鲁尔·鹰风将这封刻写的信交给一名擅长射击与追踪的年轻牛头人。这名新手曾在红云台地的峭壁之间受训。兰卡·远箭留意到了这名年轻人的血统和天赋，召其前来，在自己的指导下学习。"},{t="平原的传统",b="在舒哈鲁之中，猎人负责侦察和战斗，也以其他方式为部族效力。他们用猎物供养族人，守卫游牧营地，并与卡利姆多的野兽保持密切联系。兰卡·远箭的教导从武器和莫高雷的生物开始。随着训练深入，这名新手或许会学到驯服荒野伙伴的古老技艺。"}},faq={{q="风化便笺有什么用途？",a="风化便笺召唤一名牛头人猎人新手，前往纳拉其营地，跟随兰卡·远箭接受训练。",al={"风化便笺的作用","风化便笺用途","获得风化便笺的原因"}},{q="是谁转交了便笺？",a="格鲁尔·鹰风转交了便笺。他说，猎人训练师派来的信使刚刚还在寻找这名年轻猎人。",al={"谁给予风化便笺","风化便笺任务给予者","罗哈库便笺"}},{q="兰卡·远箭在哪里？",a="兰卡·远箭位于红云台地的纳拉其营地，就在猎人训练场附近，随时准备指导新猎人。",al={"兰卡·远箭在哪里","寻找兰卡·远箭","兰卡·远箭位置"}},{q="为什么猎人在牛头人中如此受人敬重？",a="猎人为牛头人提供食物，解读荒野的迹象，并与平原之灵保持和谐。",al={"牛头人猎人背景故事","牛头人猎人的重要性"}},{q="这项训练会传授哪些技能？",a="兰卡·远箭教授狩猎基础、远程武器的使用以及野兽知识。随着训练深入，他或许会传授驯服动物伙伴的仪式。",al={"兰卡·远箭教授什么","牛头人猎人基础"}},{q="读完便笺后，下一步该做什么？",a="你可以前往纳拉其营地，向兰卡·远箭报到，开始训练。随着你的成长，他会教你使用步枪、驯服宠物，以及更多本领。",al={"风化便笺之后的任务","风化便笺后续"}}},fp="11,129,21.260.0,23.308.0,39.85.0,22.126.0,31.116.0,44.94.0,41.136.0,45.135.0"}
P.entries["quest:3094"] = {n="绿色便笺",s="在纳拉其营地，绿色便笺召唤年轻的牛头人前去寻找加尔特·迷雾行者。格鲁尔·鹰风代加尔特·迷雾行者传达这份召唤。",h="在纳拉其营地，绿色便笺召唤年轻的牛头人前去寻找加尔特·迷雾行者。格鲁尔·鹰风代加尔特·迷雾行者传达这份召唤。",kw={"纳拉其营地","德鲁伊","大地母亲","加尔特·迷雾行者","格鲁尔·鹰风","莫高雷","红云台地","绿色便笺"},ang={["class:Druid"]="身为德鲁伊，你开始学习引导艾泽拉斯的荒野能量与躁动不安的灵魂。",["faction:Horde"]="身为部落的一员，你加入了牛头人德鲁伊的行列。他们将部落与卡利姆多的自然奥秘联系起来，同时平衡部落的尚武之力。",["race:Tauren"]="身为牛头人，你传承的德鲁伊之道是一份神圣的盟约，根植于对Earthmother的虔诚。"},sec={{t="踏上此道的召唤",b="在红云台地，格鲁尔·鹰风将加尔特·迷雾行者派来的信使带来的消息交给年轻的牛头人。这份召唤要求那些天赋自然之力的人承担起自己的责任。它邀请他们研习牛头人古老的德鲁伊之道，并要求他们放下村中的琐碎差事，为平原的平衡尽力。"},{t="大地母亲的声音",b="加尔特·迷雾行者警告说，莫高雷各处的先祖之灵与自然之灵已变得躁动不安。牛头人德鲁伊是自然的化身，即使远方纷争不断，他们仍遵循大地母亲的意志，维系和谐。暗夜精灵也研习德鲁伊之术，但加尔特·迷雾行者说，他们的傲慢蒙蔽了双眼，使他们看不到牛头人与自然界之间的深厚联系。"}},faq={{q="什么是绿色便笺？",a="绿色便笺召唤年轻的牛头人德鲁伊前往纳拉其营地寻找加尔特·迷雾行者，开始学习德鲁伊之术。",al={"绿色便笺","德鲁伊信件","莫高雷德鲁伊任务便笺"}},{q="谁将便笺交给玩家？",a="格鲁尔·鹰风将便笺交给年轻的德鲁伊，并说加尔特·迷雾行者派来的一位信使正在寻找他们。",al={"谁给予绿色便笺","绿色便笺任务起始"}},{q="在哪里可以找到加尔特·迷雾行者？",a="加尔特·迷雾行者就在纳拉其营地的天然崖壁下，他在那里训练初入此道的牛头人德鲁伊。",al={"加尔特·迷雾行者位置","加尔特在哪里"}},{q="加尔特·迷雾行者为何告诫学生提防暗夜精灵？",a="加尔特·迷雾行者说，暗夜精灵的傲慢蒙蔽了他们的双眼，使他们看不到牛头人与自然之间的深厚联系。他敦促学生聆听大地母亲的智慧。",al={"牛头人与暗夜精灵德鲁伊","暗夜精灵傲慢德鲁伊"}},{q="莫高雷的灵魂为何躁动不安？",a="加尔特·迷雾行者感知到，莫高雷各处的先祖之灵与自然之灵正在躁动。这份不安昭示着初入此道的德鲁伊毕生的职责：维持荒野的平衡。",al={"莫高雷灵魂躁动不安","自然之灵为何愤怒"}},{q="完成这个任务后，加尔特·迷雾行者接下来会传授什么技能？",a="年轻的德鲁伊向加尔特·迷雾行者报到后，他便成为他们的训练师，并承诺随着他们智慧的增长，教导他们运用大地母亲的恩赐。",al={"绿色便笺之后是什么","德鲁伊后续任务"}}},fp="12,132,21.330.0,25.343.0,25.119.0,36.115.0,35.116.0,54.146.0,40.157.0,62.150.0"}
P.entries["quest:3095"] = {n="简易卷轴",s="你对付天灾军团时，收到一卷盖有丹纳尔·斯特恩印记的密封卷轴。卷轴召你前往丧钟镇，丹纳尔在那里谈起你的自由，并表示愿意教导你。",h="你对付天灾军团时，收到一卷盖有丹纳尔·斯特恩印记的密封卷轴。卷轴召你前往丧钟镇，丹纳尔在那里谈起你的自由，并表示愿意教导你。",kw={"丹纳尔·斯特恩","丧钟镇","简单的角色","被遗忘者","天灾军团","简单的卷轴","希尔瓦娜斯","训练"},sec={{t="密封的信件",b="你外出对付那些毫无理智的天灾军团时，有人送来一卷卷轴。封印看起来属于丹纳尔·斯特恩，他是丧钟镇的战士训练师。信中请你读完后去找他谈谈，再次启程。"},{t="自由与训练",b="丹纳尔说，其他人逃过一死，逃到了镇上；他看到了他们坚韧不拔的潜质。他认为是希尔瓦娜斯解放了你的身躯与灵魂，尽管瘟疫依然折磨着你。他表示，随着你积累经验，愿意教导你；希尔瓦娜斯也需要你这样的职业人才，帮助拯救被遗忘者。"}},faq={{q="谁给我寄了卷轴？",a="卷轴上有丹纳尔·斯特恩的封印，他是丧钟镇的战士训练师。",al={"卷轴寄件人","谁寄来的","丹纳尔的卷轴"}},{q="为什么会收到这卷轴？",a="信中请你读完后去丧钟镇找丹纳尔·斯特恩谈谈。",al={"为何寄卷轴","这卷轴有什么用","简单的卷轴"}},{q="丹纳尔怎么评价希尔瓦娜斯？",a="丹纳尔认为是希尔瓦娜斯解放了你的身躯与灵魂，尽管瘟疫依然影响着你。",al={"希尔瓦娜斯的解放","希尔瓦娜斯做了什么","希尔瓦娜斯与我"}},{q="丹纳尔愿意提供什么？",a="丹纳尔愿意在你积累经验时教导你，并请你去找他。",al={"丹纳尔的教导","丹纳尔能训练我吗","战士训练师"}},{q="希尔瓦娜斯需要我做什么？",a="丹纳尔说，希尔瓦娜斯需要你这样的职业人才，帮助拯救被遗忘者。",al={"希尔瓦娜斯的需求","我的职业职责","被遗忘者的未来"}}},fp="13,177,16.240.0,20.296.0,23.80.0,26.73.0,36.98.0,23.82.0,32.78.0"}
P.entries["quest:3096"] = {n="密文卷轴",s="在丧钟镇，一封密封的信件送到了一名刚刚苏醒的被遗忘者潜行者手中。暗影牧师萨维斯在这名新兵证明自己已准备就绪后，派其去见大卫·提亚斯。",h="在丧钟镇，一封密封的信件送到了一名刚刚苏醒的被遗忘者潜行者手中。暗影牧师萨维斯在这名新兵证明自己已准备就绪后，派其去见大卫·提亚斯。",kw={"大卫·提亚斯","丧钟镇","密文卷轴","被遗忘者潜行者","暗影牧师萨维斯","巡影者","提瑞斯法林地"},ang={["class:Rogue"]="身为潜行者，你收到了一份秘密召见，获邀加入被遗忘者的秘密网络。你在新近复生者之中迈出的第一步，或许会将你引向秘密任务。",["race:Undead"]="身为一名新近复生的被遗忘者，你协助保卫提瑞斯法林地，抵御Scourge和残存的生者势力。斥候和秘密特工对黑暗女王的生存战略至关重要。"},sec={{t="悄然召见",b="新近复生的被遗忘者在墓地中与无意识的僵尸战斗，丧钟镇的领袖们则留意着那些倾向于潜行和诡计的人。一旦你证明自己已准备就绪，暗影牧师萨维斯就会交给你一张密封的羊皮纸。大卫·提亚斯那枚不起眼的封印，标志着你与被遗忘者领导层麾下的秘密网络建立了最初的联系。"},{t="暗影中的耳目",b="大卫·提亚斯留意着丧钟镇的路口和旅店，为今后的秘密行动物色人选。被遗忘者需要训练有素的特工为他们初建的王国效力，而非寻常窃贼或鲁莽的扒手。提亚斯说，出色的潜行者可能会引起巡影者的注意，这是一个重视狡诈、精准以及对黑暗女王绝对忠诚的被遗忘者组织。"}},faq={{q="密文卷轴有什么用途？",a="这份卷轴秘密邀请一名刚刚苏醒的被遗忘者潜行者去见大卫·提亚斯，接受专门训练。暗影牧师萨维斯会在你证明自己的能力后，将它交给你。",al={"密文卷轴是什么","卷轴有什么用","为什么要用密文卷轴"}},{q="大卫·提亚斯是谁？",a="大卫·提亚斯是丧钟镇旅店中的潜行者导师。他评估新兵，并为规模更大的被遗忘者情报行动物色人选。",al={"大卫·提亚斯","提亚斯是谁","丧钟镇潜行者训练师"}},{q="提亚斯提到的巡影者是谁？",a="巡影者是被遗忘者的秘密特工和刺客。他们寻找的是才干出众、纪律严明的特工，而非笨手笨脚的扒手。",al={"巡影者是谁","巡影者 被遗忘者","巡影者"}},{q="这封信为什么要加密？",a="丧钟镇防备薄弱，加密可以防止机密信息被随意窥见。对被遗忘者潜行者而言，加密能保护他们的通信，并保障行动安全。",al={"为什么加密","为什么使用密码"}},{q="在哪里能找到暗影牧师萨维斯？",a="暗影牧师萨维斯在提瑞斯法林地丧钟镇中央的墓穴与礼拜堂建筑群中，负责接收刚刚苏醒的被遗忘者。",al={"萨维斯在哪里","萨维斯位置","寻找暗影牧师萨维斯"}},{q="大卫·提亚斯在哪里？",a="大卫·提亚斯就在丧钟镇那座破损的旅店里，从中央礼拜堂沿小路走一小段便能到达。",al={"提亚斯在哪里","大卫·提亚斯位置","丧钟镇旅店训练师"}}},fp="16,150,15.308.0,19.359.0,44.167.0,19.145.0,46.136.0,29.171.0,39.136.0,29.91.0"}
P.entries["quest:3097"] = {n="神圣卷轴",s="《神圣卷轴》是针对丧钟镇新觉醒的被遗忘者牧师的入门召唤。这份公文由暗影牧师萨维斯移交，召集新手前往破败的村庄礼拜堂寻找黑暗牧师杜斯滕，以了解亡灵在死后如何运用信仰。",h="《神圣卷轴》是针对丧钟镇新觉醒的被遗忘者牧师的入门召唤。这份公文由暗影牧师萨维斯移交，召集新手前往破败的村庄礼拜堂寻找黑暗牧师杜斯滕，以了解亡灵在死后如何运用信仰。",kw={"黑暗牧师杜斯滕","丧钟镇","被遗忘者牧师","神圣卷轴","牧师任务","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Priest"]="这个任务标志着你在哲学上对被遗忘者神职的洗礼，拒绝传统的虔诚奉献，转而拥抱自立、苦难和暗影魔法。",["race:Undead"]="该卷轴体现了被遗忘者的世界观：脱离了旧有的人类信仰，他们纯粹依靠钢铁般的意志和相互间的需求而生存。"},sec={{t="丧钟镇的召唤",b="当新觉醒的亡灵从丧钟镇的坟墓中蹒跚走出时，他们的头脑往往因为瘟疫、死亡以及突然从巫妖王掌控中解脱而产生的创伤而感到眩晕。对于那些生前曾是圣光虔诚信徒的人来说，困惑尤为深刻。当新生的亡灵与徘徊在定居点外围的无脑天灾军团战斗时，暗影牧师萨维斯会拦截收到的信息。这封带有黑暗牧师杜斯滕印记的《神圣卷轴》要求新晋的牧师放弃游荡，前往受损的城镇礼拜堂报到。"},{t="信仰的重塑",b="在递交卷轴后，新手会接触到被遗忘者牧师严苛的神学。黑暗牧师杜斯滕毫不留情：圣光在死亡中抛弃了他们，祖先之灵只是空洞的传说，而虚空恶魔对他们的苦难毫无兴趣。相反，被遗忘者的神职人员教导说，纯粹的意志力和彻底的自立才是救赎的唯一真正源泉。在杜斯滕的教导下，新生的修行者学会了引导神圣戒律和暗影，运用力量不是出于对遥远神灵的虔诚，而是出于对自己生存的绝对信念。"}},faq={{q="什么是神圣卷轴？",a="这是一份由暗影牧师萨维斯交给丧钟镇新晋被遗忘者牧师的封印文件。它指示他们前往城镇礼拜堂寻找黑暗牧师杜斯滕，以开始正式的牧师训练。",al={"神圣卷轴","卷轴物品","牧师卷轴"}},{q="谁给玩家发送了卷轴？",a="该卷轴带有黑暗牧师杜斯滕的个人印记，他是居住在丧钟镇礼拜堂的被遗忘者牧师导师，尽管它是由暗影牧师萨维斯交给你的。",al={"谁发送了卷轴","杜斯滕卷轴","萨维斯信件"}},{q="被遗忘者还能运用圣光吗？",a="黑暗牧师杜斯滕告诉新牧师，圣光不再与他们有关。正如他所解释的，传统的圣光崇拜被放弃，取而代之的是对自己信仰以及对暗影的掌控。",al={"亡灵使用圣光","被遗忘者圣光","亡灵可以施放圣光吗"}},{q="黑暗牧师杜斯滕在哪里？",a="他位于提瑞斯法林地西部丧钟镇中心的废墟教堂内，站在其他被遗忘者训练师附近。",al={"寻找杜斯滕","杜斯滕位置","黑暗牧师杜斯滕在哪里"}},{q="为什么杜斯滕不理会祖先和恶魔？",a="杜斯滕试图剥离新复活的亡灵所持有的所有幻想。他告诉他们，圣光不再与他们有关，祖先的灵魂只是童话故事，而虚空生物也不需要他们，并以此宣扬被遗忘者仅凭意志生存了下来。",al={"杜斯滕的演讲","童话故事","虚空不想要你"}},{q="阅读卷轴后会发生什么？",a="你阅读了羊皮纸，并向丧钟镇礼拜堂的黑暗牧师杜斯滕报到，从而解锁你最初的牧师技能，并确立他为你在此新手区域的训练师。",al={"神圣卷轴任务目标","提交卷轴"}}},fp="15,180,23.439.0,15.434.0,28.167.0,35.107.0,40.183.0,37.133.0,46.241.0,38.163.0"}
P.entries["quest:3098"] = {n="雕文卷轴",s="雕文卷轴是发给丧钟镇新觉醒的被遗忘者法师的正式传唤。这张羊皮纸上盖着法师训练师伊莎贝拉的印章，指引着那些有前途的奥术修行者前往村庄里破败的教堂找到她，以磨练他们不稳定的力量。",h="雕文卷轴是发给丧钟镇新觉醒的被遗忘者法师的正式传唤。这张羊皮纸上盖着法师训练师伊莎贝拉的印章，指引着那些有前途的奥术修行者前往村庄里破败的教堂找到她，以磨练他们不稳定的力量。",kw={"奥术","丧钟镇","被遗忘者法师","雕文卷轴","伊莎贝拉","法师训练师","提瑞斯法林地"},ang={["class:Mage"]="这张卷轴标志着你正式加入被遗忘者法师的行列，将你的魔法技艺直接与你刚获得自由的族群的生存与复兴联系在了一起。",["race:Undead"]="被遗忘者法师带着黑暗的目的挥舞奥术，他们不把魔法视为达拉然那样的学术游戏，而是将其视为夺回他们被窃家园不可或缺的武器。"},sec={{t="奥术传唤",b="当一名刚被复活的被遗忘者在丧钟镇周围清理无脑的天灾军团时展现出对奥术魔法的亲和力，他们很快就会引起长辈们的注意。雕文卷轴由专人送达，上面印有当地法师导师伊莎贝拉的奥术印记。它要求这位新晋的修行者前往她在破败教堂内的岗位报到，因为如果不加管制，这种魔法天赋对被遗忘者造成的危险和对他们的敌人一样大。"},{t="亡灵的魔法运用",b="在丧钟镇破败的礼拜堂内，伊莎贝拉教导初学者们，死亡并没有使他们免受奥术危险的影响。虽然死亡剥夺了他们身体上的虚弱，但魔法那不稳定的拉扯和腐蚀本质依然如故。对于被遗忘者来说，追求奥术支配地位不仅仅是一项学术追求，更是一种生存和复仇的工具——这是夺回命运、消灭任何挑战他们对洛丹伦脆弱统治权的敌人的手段。"}},faq={{q="什么是雕文卷轴？",a="雕文卷轴是一份带有丧钟镇被遗忘者法师训练师伊莎贝拉个人印章的指导文书。它指示新觉醒的法师前往破败的教堂报告，以推进他们的奥术研究。",al={"雕文卷轴任务","这是什么卷轴","丧钟镇卷轴"}},{q="谁给你发送了雕文卷轴？",a="这张卷轴由丧钟镇的驻地法师训练师伊莎贝拉发出，在你证明了自己的价值、清理了附近无脑的天灾军团后递交给你。",al={"谁发送了卷轴","谁写了雕文卷轴","雕文卷轴发送者"}},{q="伊莎贝拉在哪里？",a="伊莎贝拉驻扎在丧钟镇中心那座破败的村庄教堂内，与其他为新复活的被遗忘者提供指导的职业导师待在一起。",al={"伊莎贝拉在哪里","找到伊莎贝拉","丧钟镇法师训练师位置"}},{q="为什么伊莎贝拉要警告你魔法腐蚀？",a="伊莎贝拉警告说，尽管被遗忘者是亡灵，但奥术力量不稳定的本质依然没有改变。魔法仍然带有持续的腐蚀和成瘾风险，需要纪律和意志来掌控，否则就会被其吞噬。",al={"亡灵魔法腐蚀","奥术腐蚀背景知识","为什么魔法对亡灵危险"}},{q="为什么奥术魔法对丧钟镇的被遗忘者很重要？",a="被遗忘者法师将奥术力量视为夺回洛丹伦、确保他们在无脑天灾军团、敌对活着的凡人以及血色十字军面前获得自治权的至关重要的工具。",al={"为什么被遗忘者使用魔法","亡灵法师背景知识"}},{q="任何被遗忘者职业都能收到这张卷轴吗？",a="不能。雕文卷轴专门发放给被遗忘者法师，作为前往丧钟镇主要职业训练师处的入门传唤。",al={"雕文卷轴是法师专属吗","术士能得到雕文卷轴吗","谁能获得雕文卷轴"}}},fp="14,147,23.335.0,25.393.0,27.186.0,36.114.0,26.130.0,52.134.0,60.153.0,43.102.0"}
P.entries["quest:3099"] = {n="被污染的卷轴",s="“被污染的卷轴”是丧钟镇的一项早期任务，指引刚苏醒的被遗忘者术士前往他们的训练师马克西米利安处。通过这封信件，马克西米利安邀请初学者拥抱力量与黑暗的奴役，以此作为确保获得真正自由的手段。",h="“被污染的卷轴”是丧钟镇的一项早期任务，指引刚苏醒的被遗忘者术士前往他们的训练师马克西米利安处。通过这封信件，马克西米利安邀请初学者拥抱力量与黑暗的奴役，以此作为确保获得真正自由的手段。",kw={"丧钟镇","被遗忘者","马克西米利安","天灾军团","希尔瓦娜斯","被污染的卷轴","提瑞斯法林地","术士"},ang={["class:Warlock"]="马克西米利安在丧钟镇引导刚苏醒的被遗忘者术士，将恶魔学识和奴役视为掌控与自由的终极主张。",["race:Undead"]="被遗忘者术士在打破天灾军团的枷锁与寻求可供驱使以求生存的恶魔仆从之间建立了一种黑暗的联系。"},sec={{t="黑暗召唤",b="在刚复生的被遗忘者开始清理丧钟镇周围漫无目的的天灾军团残党后不久，一封带有丧钟镇当地术士训练师马克西米利安印章的不祥信件随之送达。卷轴召唤收信人深思奴役与自主的本质，然后再回到这座废弃的定居点亲自与他交谈。"},{t="控制哲学",b="在回应召唤后，马克西米利安揭示了他关于力量与征服的哲学。他认为既然已经从巫妖王盲目的掌控中挣脱，那么只要没有夺取真正的权威，奴隶就永远是奴隶。在他眼中，驾驭恶魔仆从并非背叛希尔瓦娜斯，而是被遗忘者争取自我决定权与尊重的自然结果。"}},faq={{q="是谁寄出了“被污染的卷轴”？",a="这封卷轴上盖有马克西米利安的个人印章，他是驻扎在丧钟镇的术士训练师，负责寻找刚苏醒的黑暗艺术从业者。",al={"谁寄出了被污染的卷轴","谁给了我被污染的卷轴","被污染的卷轴寄件人"}},{q="马克西米利安是谁？",a="马克西米利安是丧钟镇的术士训练师，负责指导刚复生的被遗忘者学习召唤和控制恶魔实体的黑暗艺术。",al={"马克西米利安是谁","马克西米利安 丧钟镇","术士训练师 丧钟镇"}},{q="“被污染的卷轴”上写了什么？",a="这是一封寄给刚苏醒术士的信件，其中反思了自由、力量和奴役的本质，敦促读者拜访马克西米利安以获取更深入的指导。",al={"什么是被污染的卷轴","卷轴说了什么","卷轴信息"}},{q="马克西米利安是希尔瓦娜斯女士的叛徒吗？",a="马克西米利安明确表示他并非希尔瓦娜斯女士的叛徒。他声称女妖之王会欣赏他的观点，并指出她本人对自我决定权的追求正是打破他们天灾枷锁的关键。",al={"马克西米利安是叛徒吗","马克西米利安是否背叛希尔瓦娜斯","马克西米利安的忠诚"}},{q="我在哪里可以找到马克西米利安？",a="马克西米利安住在丧钟镇，那是提瑞斯法林地里的一座废弃定居点，刚复生的被遗忘者最初就是从那里的坟墓中苏醒的。",al={"在哪里找到马克西米利安","马克西米利安位置"}},{q="这个任务的目的是什么？",a="该任务是为刚复生的被遗忘者术士提供的引导性召唤，旨在让他们开始职业训练，并将他们引向丧钟镇的导师处。",al={"为什么术士任务是被污染的卷轴","被污染的卷轴目的"}}},fp="14,177,14.291.0,25.337.1,28.142.0,19.111.0,38.142.0,42.156.0,29.139.0,34.105.0"}
P.entries["quest:31"] = {n="水栖形态",s="在雷霆崖，一位年轻的部落德鲁伊归来，即将获得自然守护者的认可。这位德鲁伊已在月光林地证明了自己的资格，并化身为海狮；如今，正式的认可将使其习得水栖形态。",h="在雷霆崖，一位年轻的部落德鲁伊归来，即将获得自然守护者的认可。这位德鲁伊已在月光林地证明了自己的资格，并化身为海狮；如今，正式的认可将使其习得水栖形态。",kw={"水栖形态","德迪利特·星焰","德鲁伊","月光林地","海狮坠饰","海狮","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="身为德鲁伊，水栖形态能帮助你轻松穿越水域，逃离深水中的捕食者。",["faction:Horde"]="身为部落的一员，你与牛头人德鲁伊共享着同塞纳里奥议会的精神纽带，往来于中立庇护所与部族主城之间。",["race:Tauren"]="身为牛头人，掌握海中野兽的形态既是对先祖的敬意，也让你的族人更加坚定地回归德鲁伊之道。"},sec={{t="海狮归来",b="你在月光林地完成试炼后，德迪利特·星焰便派你返回莫高雷。海狮坠饰见证了你在卡利姆多各处水域展现的平衡与奉献。将它带回家乡，便证明你遵循了化身水生生物所必需的古老传统。"},{t="与水域交融",b="在雷霆崖的高地上，你将坠饰交给导师图拉克·符文图腾。他很欣慰，因为你敬重先祖，也维持了自然的平衡。随后，图拉克向你传授水栖形态的奥秘。你可以潜游于江河与海洋之中，自由呼吸，并像海中生灵一样在深水中穿行。"}},faq={{q="这个任务的目的是什么？",a="这场仪式完成了年轻部落德鲁伊的成长历程。在雷霆崖，你献上海狮坠饰，并习得水栖形态。",al={"为什么做这个任务","水栖形态用途","这个任务有什么用"}},{q="我该把海狮坠饰交给谁？",a="将海狮坠饰交给图拉克·符文图腾，他是位于莫高雷雷霆崖上层高地的德鲁伊训练师。",al={"找谁交任务","水栖形态在哪里交任务","图拉克·符文图腾位置"}},{q="是谁派你返回雷霆崖？",a="你在月光林地完成水中试炼后，德迪利特·星焰便派你返回。",al={"谁提供水栖形态任务","德迪利特·星焰任务"}},{q="非德鲁伊职业能完成这个任务吗？",a="不能。只有德鲁伊才能完成这场仪式，在通往动物形态的精神与魔法之路上继续前行。",al={"是否仅限德鲁伊","其他职业能否做水栖形态"}},{q="月光林地的暗夜精灵为什么会帮助部落德鲁伊？",a="月光林地是由塞纳里奥议会管理的中立庇护所。暗夜精灵导师引导牛头人德鲁伊研习古老的塞纳里奥技艺，追寻自然的平衡，不受政治敌意的影响。",al={"为什么德迪利特帮助部落","月光林地部落联盟","德鲁伊中立"}},{q="完成这个任务会获得什么能力？",a="图拉克·符文图腾会教你水栖形态。在这个形态下，你游得更快，还能在水下呼吸。",al={"获得什么形态","水栖形态法术","水栖形态"}}},fp="12,210,22.282.0,25.324.0,34.132.0,46.114.0,36.86.0,35.110.0,53.188.0,46.96.0"}
P.entries["quest:310"] = {n="针锋相对",s="马莱斯·麦酒请你前往卡拉诺斯的雷酒酿制厂，用她家族酿的酒换掉一桶雷霆麦酒。",h="马莱斯·麦酒请你前往卡拉诺斯的雷酒酿制厂，用她家族酿的酒换掉一桶雷霆麦酒。",kw={"热麦酒","针锋相对","丹莫罗","卡拉诺斯","马莱斯·麦酒","雷霆麦酒","雷酒酿制厂"},ang={["class:Rogue"]="身为潜行者，你知道如何潜入戒备森严的地窖、引开哨兵，再调换违禁品。这一次，要争夺的是啤酒，而非黄金。",["faction:Alliance"]="身为联盟的旅人，你会途经卡拉诺斯，这里是丹莫罗的文化与后勤枢纽。旅店里的地方纷争常常将新兵卷入其中。",["race:Dwarf"]="身为矮人，你知道酿酒带来的声望足以媲美锻造。为了麦酒孰优孰劣而起的争执，与丹莫罗的雪景十分相称。"},sec={{t="竞争的滋味",b="麦酒家族对雷酒家族家族酒厂的盛名早已心怀不满。马莱斯认可那里的麦酒，却无法容忍丹莫罗的人们只知道雷酒。她打算用自家烈性十足的热麦酒改变当地人的口味。"},{t="地窖里的暗计",b="卡拉诺斯的雷酒酿制厂下方，地下储藏室里堆满了陈酿酒桶。一名守卫看守着雷酒家族家族珍藏的佳酿。引开他，再悄悄调换酒桶。"}},faq={{q="谁会给予针锋相对任务？",a="马莱斯·麦酒将这项差事交给你。她希望自家的酿酒手艺能与雷酒酿制厂闻名遐迩的麦酒一较高下。",al={"谁给予针锋相对","马莱斯任务给予者"}},{q="雷酒的地窖在哪里？",a="地窖位于卡拉诺斯的雷酒酿制厂下方。通往地窖的楼梯就在厨房的一张桌子后面。",al={"雷酒地下室在哪","怎么去酿制厂地窖"}},{q="热麦酒是什么？",a="热麦酒是马莱斯·麦酒自家酿制的烈性麦酒。她希望卡拉诺斯的酒客喝到替换了雷霆麦酒的这款酒时，能认可她的手艺。",al={"热麦酒","要调换什么酒"}},{q="如何绕过看守酒桶的守卫？",a="地下室里的雷酒守卫会暗示什么东西能吸引他的注意。分散他的注意力，再趁机调换酒桶。",al={"引开地窖守卫","无人看守的雷霆麦酒桶","守卫酒桶"}},{q="麦酒家族和雷酒家族家族为何结怨？",a="这场争执源于矮人对自身手艺的自豪。雷酒家族家族的酒在卡拉诺斯的酒馆里占尽风头，麦酒家族则想证明自家的配方同样出色，甚至更胜一筹。",al={"酿酒师争端","麦酒为何憎恨雷酒"}},{q="针锋相对之后是什么任务？",a="放好那桶热麦酒后，你便返回马莱斯那里，向她报告成功的消息。",al={"针锋相对后续任务","针锋相对之后是什么"}}},fx={["6a423fcc"]={q="马莱斯·麦酒为什么想要调换酒桶？",a="马莱斯·麦酒与雷酒氏族长期激烈竞争，都想酿出丹莫罗最好的麦酒。虽然她不情愿地承认雷酒酿的酒还不错，却受不了他们的吹嘘，一心想证明自己的热麦酒更胜一筹。她希望把自己的酒桶悄悄放进雷酒酿制厂的地窖，让对方的忠实酒客喝到，发现这酒的好处，挫一挫雷酒的锐气。",al={"为何调换酒桶","马莱斯的动机","为何调换酒"}},["41e8c9ba"]={q="马莱斯·麦酒为什么需要你帮忙，而不亲自动手？",a="马莱斯在卡拉诺斯太有名了，根本无法悄无声息地走进竞争对手的地下室。雷酒酿制厂严密看守着地窖，任何一位为人熟知的麦酒成员出现，都会立刻引起警觉。你是个陌生的旅人，可以溜进酿酒厂，设法绕过地窖守卫，调换酒桶，不至于立刻让整个计划败露。",al={"马莱斯为何不能亲自动手","针锋相对为何找我","为何雇用外人"}}},fp="13,126,22.243.0,17.190.0,34.129.0,40.109.0,27.156.0,49.134.0,49.172.0,33.94.0"}
P.entries["quest:3100"] = {n="简要的信件",s="简要的信件是一封入门指示信，引导新手战士前往北郡修道院，拜访训练师莱尼·拜舍尔。它标志着他们正式开始武艺训练，并敦促他们帮助山谷中身陷困境的居民。",h="简要的信件是一封入门指示信，引导新手战士前往北郡修道院，拜访训练师莱尼·拜舍尔。它标志着他们正式开始武艺训练，并敦促他们帮助山谷中身陷困境的居民。",kw={"艾尔文森林","白银之手骑士团","莱尼·拜舍尔","北郡修道院","北郡山谷","简要的信件","战士训练师"},ang={["class:Warrior"]="莱尼·拜舍尔是北郡修道院的常驻战士训练师，这封简短的信便是初来乍到的战士接受武艺训练的最初召唤。",["faction:Alliance"]="即使身处白银之手庇护下这片相对安全的土地，新兵们也会立刻接到召唤，去帮助身陷困境的联盟居民。",["race:Human"]="北郡修道院是人类冒险者踏入艾尔文森林前的摇篮，当地新兵在这里接受最初的指引。"},sec={{t="战斗的召唤",b="简要的信件为来到北郡山谷、立志成为战士的人提供最初的指引。这封信指引初来乍到的战士去拜访北郡修道院的常驻战士训练师莱尼·拜舍尔，熟悉周围环境，并为战士生涯的种种考验做好准备。"},{t="保卫山谷",b="虽然北郡修道院有白银之手骑士团警戒守护，山谷平静的表象下却隐藏着更深的隐患。正如 拜舍尔 收到信时所说，周边居民面临重重困境，需要身强体健的守护者，因此他敦促新兵熟练掌握武器，挺身保卫王国。"}},faq={{q="简要的信件是什么？",a="简要的信件是战士从狗头人营地返回后，在北郡山谷收到的一封引荐信。信中指引他们去向当地的战士训练师莱尼·拜舍尔报到，开始正式的武艺训练。",al={"简要的信件 是什么","简要的信件 任务","人类战士入门信件"}},{q="莱尼·拜舍尔是谁？",a="莱尼·拜舍尔是驻守北郡修道院的战士训练师。他向新手战士传授战斗技巧，欢迎奉命或受人推荐、来到山谷寻找他的新兵。",al={"莱尼·拜舍尔 是谁","拜舍尔 位置","北郡 战士训练师在哪"}},{q="简要的信件应该交到哪里？",a="这封信要直接交给莱尼·拜舍尔，他就在北郡山谷的北郡修道院里，周围是受神圣骑士团庇护的土地。",al={"简要的信件 在哪交","简要的信件 交任务","莱尼·拜舍尔 位置"}},{q="白银之手骑士团在北郡扮演什么角色？",a="白银之手骑士团协助守卫北郡山谷，让修道院及其周边保持相对安全，使新兵、农民和神职人员在当地局势日益紧张的情况下仍能各司其职。",al={"圣骑士在 北郡 做什么","白银之手 北郡修道院","圣骑士 艾尔文"}},{q="当地居民为什么需要帮助？",a="虽然修道院本身的防卫仍然较为稳固，当地居民却不断受到侵扰，还面临物资短缺。拜舍尔 建议新来的人探索周边地区，用自己的武艺帮助有需要的人。",al={"拜舍尔 为什么要人帮助居民","北郡 的困境","北郡 谁需要帮助"}},{q="交出信件后，应该什么时候再去找莱尼·拜舍尔？",a="莱尼·拜舍尔日夜都在修道院，随时准备教导那些积累了战斗经验、需要学习更高深武艺的战士。",al={"何时再找 莱尼·拜舍尔","北郡 进阶战士训练","拜舍尔 训练"}}},fp="13,137,14.248.0,19.252.0,26.169.0,21.142.0,37.118.0,63.206.0,49.199.0,66.132.0"}
P.entries["quest:3101"] = {n="圣洁信件",s="圣洁信件是初到北郡山谷的圣光新兵随身携带的一封入门召集信。信中指示持信者前往北郡修道院，向自己的职业训练师报到，开始训练，并肩负起作为信仰象征的职责。",h="圣洁信件是初到北郡山谷的圣光新兵随身携带的一封入门召集信。信中指示持信者前往北郡修道院，向自己的职业训练师报到，开始训练，并肩负起作为信仰象征的职责。",kw={"萨缪尔修士","圣洁信件","艾尔文森林","圣光","北郡","北郡修道院","圣骑士","训练师"},ang={["class:Paladin"]="身为圣光的使用者，圣骑士肩负着彰显其美德的职责，要为北郡及其他地方的盟友点亮希望。",["faction:Alliance"]="圣光的代表应当以荣耀为准则行事，维护联盟的道德准则，保卫联盟。",["race:Human"]="对于在北郡修道院开始服役的人类而言，这封信强调了他们的责任：在一个近来饱受考验的王国中，成为荣耀的象征。"},sec={{t="神圣的召唤",b="圣洁信件标志着新兵在北郡山谷的旅程正式开始。这封信写给初来乍到的圣光使用者，召他们前往北郡修道院寻找训练师，正式接受教导，并承担自己在暴风城王国的职责。"},{t="承载光明",b="新兵呈上信件时，会被提醒自己肩负的使命有多么沉重。圣光在引导它的人体内闪耀，让他们立刻成为盟友眼中的希望象征，也成为敌人明确的目标。训练师强调，拥有这样的力量，就必须严守纪律，并时刻留意自身言行所树立的榜样。"},{t="指引与自律",b="除了精神上的义务，这封信也确立了学生与导师之间长久的师承关系。新兵在对抗北郡当地威胁、磨炼自身的同时，也应定期返回修道院，进一步领悟战斗之道与神圣恩典。"}},faq={{q="圣洁信件是什么？",a="圣洁信件是写给北郡山谷一名圣光新兵的入门召集信。信中指示持信者前往北郡修道院寻找自己的职业训练师，开始接受训练，并提醒他们牢记神圣的职责。",al={"圣洁信件 是什么","圣洁信件 任务"}},{q="圣洁信件从何而来？",a="一名新晋圣骑士从狗头人的营地返回后，北郡修道院里便会有人交给他这封信，信上盖着萨缪尔修士的印记，叫这名圣骑士前去见他。",al={"谁给予 圣洁信件","谁寄出 圣洁信件"}},{q="圣洁信件要交给谁？",a="这封信要交给萨缪尔修士，他是驻守在艾尔文森林北郡修道院入口附近的圣骑士训练师。",al={"谁交还 圣洁信件","谁阅读 圣洁信件"}},{q="读完信后，训练师会发挥什么作用？",a="训练师是指引新兵修习圣光之道的导师，在新兵于山谷中积累实战经验的过程中，传授武艺、用于防御的祝福和神圣法术。",al={"训练师传授什么","为何跟随训练师学习"}},{q="信中为何提到成为象征？",a="引导圣光的人被视为信仰与美德的鲜明典范。无论敌友，都能认出这份光明的力量，因此它的使用者格外引人注目，他们的言行也影响着信仰本身的形象。",al={"为何成为象征","圣光 象征"}},{q="训练在哪里进行？",a="北郡修道院坐落于艾尔文森林北部宁静的山谷中，既是信仰的庇护所，也是暴风城王国招募卫士的主要场所。",al={"北郡修道院在哪里","信要送到哪里"}}},fp="18,192,16.264.0,18.279.0,23.275.0,31.192.0,44.181.0,36.113.0,57.198.0,43.167.0,36.171.0"}
P.entries["quest:3102"] = {n="密文信件",s="在北郡修道院，乔里克·克里丹召集有潜力的潜行者与他秘密会面。他的信指引他们前往一处安静的马厩，听取应对前路危险的忠告。",h="在北郡修道院，乔里克·克里丹召集有潜力的潜行者与他秘密会面。他的信指引他们前往一处安静的马厩，听取应对前路危险的忠告。",kw={"迪菲亚潜行者","密文信件","乔里克·克里丹","北郡修道院","北郡山谷","潜行者训练师","si:7"},ang={["class:Rogue"]="身为潜行者，你会与乔里克·克里丹会面，听取他关于如何与 SI:7 和迪菲亚潜行者打交道，同时保持独立的忠告。",["faction:Alliance"]="即使在北郡修道院内，暴风城的暗影特工也在招募和训练有潜力的探员，为即将到来的冲突做准备。"},sec={{t="隐秘的召唤",b="北郡修道院看似平静，院墙之内却在招募擅长隐秘行动的人才。对付过狗头人之后，有潜力的新手会收到一封盖有乔里克·克里丹印章的信。这封信悄悄送达，避开了牧师和圣骑士的耳目。持信人被指引到修道院后方的马厩，参加一场隐秘的会面。"},{t="北郡的暗影",b="乔里克·克里丹待在马厩，因为那里安静，也不引人注意。新人悄然抵达后，他便直言相告，讲述外面更广阔的世界。暴风城的 SI:7 和迪菲亚潜行者都在寻找擅长潜行的特工。乔里克劝告每个新手保有自由，抵制那些想要摆布他们的强大组织。聪明的潜行者手握王牌。"}},faq={{q="密文信件是谁寄来的？",a="这封信由乔里克·克里丹寄出，上面带有他的个人徽记。有潜力的新手侦察过附近的狗头人营地后，就会收到这封信。",al={"谁寄来了 密文信件","谁给了我 密文信件","谁写了 密文信件"}},{q="乔里克·克里丹在哪里？",a="乔里克·克里丹待在北郡修道院后方安静的马厩里。他避开旁人的视线，从事自己的秘密工作。",al={"乔里克 在哪里","哪里能找到 乔里克·克里丹","乔里克 的位置"}},{q="密文信件有什么用途？",a="这封信秘密邀请崭露头角的潜行者与当地的训练师会面。信中经过加密的文字让训练事宜避开了修道院周围窥探的目光。",al={"为什么收到 密文信件","密文信件 有什么用","信为什么要加密"}},{q="哪些组织想要招募潜行者？",a="乔里克·克里丹说，许多势力都在寻找技艺娴熟的潜行者，包括暴风城的秘密机构 SI:7 和迪菲亚潜行者。迪菲亚潜行者想要在暴风城内安插间谍。",al={"谁想招募潜行者","对潜行者感兴趣的势力","谁觊觎潜行者的本领"}},{q="乔里克·克里丹有什么忠告？",a="乔里克劝你坚持自己的意志，拒绝受人胁迫去做违背心愿的事。在这场较量结束之前，潜行者手中始终握着王牌。",al={"乔里克 的忠告","乔里克 说了什么","乔里克 给潜行者的忠告"}},{q="乔里克·克里丹为什么待在马厩里？",a="乔里克·克里丹待在北郡修道院后方安静的马厩里，因为那里不引人注意。在那里，训练师和特工可以避开修道院神职人员与守卫的耳目，秘密会面。",al={"为什么藏在马厩里","乔里克 为什么在修道院后面","马厩为什么安静"}}},fp="16,163,18.319.0,21.362.0,30.131.0,32.121.0,44.149.0,50.163.0,37.142.0,43.191.0"}
P.entries["quest:3103"] = {n="神圣信件",s="在北郡，治安官玛克布莱德会将女牧师安妮塔的信交给前途可期的年轻牧师。信中召他们前往北郡修道院，开始接受圣光的正式训练，而王国仍笼罩在动乱的阴影之下。",h="在北郡，治安官玛克布莱德会将女牧师安妮塔的信交给前途可期的年轻牧师。信中召他们前往北郡修道院，开始接受圣光的正式训练，而王国仍笼罩在动乱的阴影之下。",kw={"艾尔文","神圣信件","圣光","治安官玛克布莱德","北郡修道院","牧师","女牧师安妮塔"},ang={["class:Priest"]="身为牧师，你将在女牧师安妮塔的指导下，开始正式研习圣光。你的魔法也承载着治愈这个破碎世界的责任。",["race:Human"]="身为人类，你来到北郡修道院，这里是暴风城王国供人坚守信仰、休养康复的庇护所。尽管艾尔文周围动荡不安，修道院仍坚守着自己的传统。"},sec={{t="牧师之路的召唤",b="在北郡周围的狗头人营地证明自己的实力后，见习牧师会收到一封由女牧师安妮塔封缄的信。治安官玛克布莱德将信交给他们，邀请他们在修道院宁静的厅堂中研习圣光。"},{t="亟待救助的世界",b="当你带着信前来，女牧师安妮塔会告诉你，王国依然动荡不安。燃烧军团遗留的威胁仍笼罩着艾泽拉斯，各片大陆也伤痕未愈，纷争不息。对安妮塔而言，成为牧师意味着的不只是学习。牧师还肩负着为受苦的世界带来治愈与慰藉的责任。"}},faq={{q="神圣信件是什么？",a="这是一封带有女牧师安妮塔徽记的密封信件，由治安官玛克布莱德交给初到北郡山谷的人类牧师。信中指引见习牧师前往北郡修道院，继续接受正式训练。",al={"神圣信件","北郡牧师入门任务","安妮塔的信"}},{q="神圣信件是谁寄出的？",a="女牧师安妮塔是北郡修道院的牧师训练师，由她写下这封信并封缄。她请治安官玛克布莱德在新入门的牧师侦察狗头人侵扰的情况归来后，将信交给对方。",al={"神圣信件是谁写的","信是谁寄的"}},{q="女牧师安妮塔为何召见新来的牧师？",a="安妮塔看出你受到了圣光的感召，希望指导你的修行。她说，燃烧军团残余势力等威胁依然存在于世间，因此迫切需要训练有素的治疗者和引路人。",al={"安妮塔为何找我","信的用途"}},{q="在哪里可以找到女牧师安妮塔？",a="女牧师安妮塔住在北郡修道院的主厅。她在那里教导人类牧师最初的祷告与仪式。",al={"安妮塔在哪里","女牧师安妮塔的位置"}},{q="将信交给女牧师安妮塔后会发生什么？",a="读过信并向安妮塔问候后，她会收你为学生。她会传授基础的智慧，并邀请你在积累经验后回来接受更多训练。",al={"神圣信件的后续任务","神圣信件之后是什么"}},{q="为什么在北郡会提到燃烧军团？",a="虽然第三次大战已经结束，燃烧军团残余的恶魔仍在艾泽拉斯肆虐。安妮塔提起这个威胁更广的敌人，是为了说明任何离开山谷的人都将面临怎样的危险。",al={"燃烧军团与北郡","安妮塔为何提到恶魔"}}},fp="15,209,22.225.0,15.307.0,28.212.0,30.191.0,45.214.0,36.128.0,61.169.0,50.184.0"}
P.entries["quest:3104"] = {n="雕文信件",s="治安官玛克布莱德的召唤传到了北郡山谷的人类新晋法师手中。凯尔登·布雷门召集有潜力的施法者前往北郡修道院，开始接受奥术教导。",h="治安官玛克布莱德的召唤传到了北郡山谷的人类新晋法师手中。凯尔登·布雷门召集有潜力的施法者前往北郡修道院，开始接受奥术教导。",kw={"奥术","艾尔文森林","雕文信件","凯尔登·布雷门","法师","治安官玛克布莱德","北郡修道院"},ang={["class:Mage"]="作为一名法师，你将在凯尔登·布雷门的指导下，正式开始学习暴风城的奥术技艺。",["race:Human"]="作为一名人类，你承载着北郡的奥术传承。这一传承可以追溯到达拉然最早的人类奥术师和肯瑞托，如今仍在暴风城王国延续。"},sec={{t="奥术的召唤",b="治安官玛克布莱德将这封带有符文印记的信交给了一位有志学习魔法的学徒，此人曾协助他对付当地的害兽，证明了自己的能力。信是由北郡的法师训练师凯尔登·布雷门写的。他留意着来到修道院的新兵，寻找具备魔法素养与天赋的人。"},{t="魔法的重担",b="北郡修道院长久以来一直是圣光的庇护之所。然而，暴风城面临的危险需要各有所长的人来应对。这封信指引你上楼去找凯尔登·布雷门，而他并不轻易赞许他人。他告诫你，掌握奥术之力意味着挑战自然的极限。这种力量会让普通民众深深敬重，也让他们深感恐惧。"}},faq={{q="谁会交付雕文信件？",a="新来的法师帮助清除附近的狗头人祸患后，治安官玛克布莱德会在北郡修道院外将信交给他们。",al={"谁给予雕文信件","雕文信件任务给予者"}},{q="雕文信件是谁写的？",a="这封信由北郡修道院楼上房间里的法师训练师凯尔登·布雷门撰写并封好。",al={"雕文信件作者","谁寄出雕文信件"}},{q="在哪里能找到凯尔登·布雷门？",a="进入治安官玛克布莱德身后的北郡修道院。沿左侧走廊前行，然后上楼。凯尔登在后面的房间里等候，准备传授魔法。",al={"凯尔登·布雷门位置","凯尔登在哪里"}},{q="为什么法师训练师会在修道院里？",a="北郡修道院是一处神圣的庇护所，但暴风城也利用这片山谷训练各有所长的守卫者。奥术导师在这里与牧师和治安官一同任职。",al={"法师为何在北郡修道院","神圣修道院中的法师训练师"}},{q="交付信件后会发生什么？",a="凯尔登·布雷门会收你为学生。他欢迎你怀着决心，不惧危险地研习奥术，并让你直接接受基础法术训练。",al={"雕文信件后续","雕文信件的下一个任务"}},{q="为什么凯尔登警告说法师会受到畏惧？",a="奥术魔法能够扭曲现实，而且难以控制。凯尔登警告说，追求至高知识会跨越某些界限，让普通民众深感不安。",al={"法师为何令人畏惧","凯尔登·布雷门对话"}}},fp="14,175,23.276.0,22.332.0,32.124.0,29.99.0,31.137.0,44.164.0,41.157.0,48.155.0"}
P.entries["quest:3105"] = {n="被污染的信件",s="在北郡，被污染的信件引导初出茅庐的人类术士避开修道院的卫兵，学习邪能之术。杜希拉·拉萨雷将信交给治安官玛克布莱德，由他转交给她的新学徒。",h="在北郡，被污染的信件引导初出茅庐的人类术士避开修道院的卫兵，学习邪能之术。杜希拉·拉萨雷将信交给治安官玛克布莱德，由他转交给她的新学徒。",kw={"腐化","杜希拉·拉萨雷","艾尔文森林","治安官玛克布莱德","北郡修道院","被污染的信件","扭曲虚空","术士"},ang={["class:Warlock"]="作为术士，你在北郡接受正式教导，同时避开卫兵的评判。在那里，你学习驾驭危险的虚空魔法。",["race:Human"]="作为人类，你生活在一个崇敬圣光和肯瑞托严谨奥术传统的社会中。术士则在北郡这类聚居地的边缘，悄然练习召唤之术。"},sec={{t="隐秘的召唤",b="初出茅庐的术士在对抗狗头人的战斗中证明自己后，会从治安官玛克布莱德手中收到一封信。牧师和圣骑士在北郡修道院公开研习，术士却必须行事隐秘。信上印着杜希拉·拉萨雷的徽记。信中指引每位初学法术的学徒，先到修道院主围墙外她的僻静驻地报到，再承担其他职责。"},{t="诱惑与野心",b="杜希拉警告说，暴风城的卫兵正密切监视着术士。她称他们为“可悲的凡夫俗子”。从扭曲虚空汲取力量和与恶魔交流，都有遭受腐化的风险。因此，她敦促学徒在操控这些黑暗能量时，要耐心、审慎，并保持坚定的自制力。她说，谨慎不应熄灭术士的野心。"}},faq={{q="谁寄出了被污染的信件？",a="杜希拉·拉萨雷在北郡修道院外的驻地写下这封信，并将它封好。她请治安官玛克布莱德在你清剿附近的狗头人营地归来时，将信交给你。",al={"谁写了被污染的信件","被污染的信件作者","谁交付被污染的信件"}},{q="治安官玛克布莱德为什么会转交术士的信？",a="治安官玛克布莱德负责向山谷中有潜力的新兵传递消息。他认得杜希拉的印章，并表示她的信应当优先处理。他主要关心的仍是北郡的防务和行政事务，而非监管守卫者研习何种魔法。",al={"玛克布莱德为什么有这封信","玛克布莱德知道信的内容吗","玛克布莱德术士信件"}},{q="在哪里能找到杜希拉·拉萨雷？",a="杜希拉·拉萨雷在北郡修道院正门外等候，就在外墙和帐篷附近。她与院内的教士保持着距离。",al={"杜希拉位置","杜希拉·拉萨雷在哪里","寻找杜希拉"}},{q="为什么北郡修道院允许术士活动？",a="联盟领地内的术士备受猜疑，因此行事低调。杜希拉在北郡的户外训练学徒，远离圣所，以避免与北郡圣教会的教士和圣骑士发生正面冲突。",al={"北郡的术士","邪能魔法在北郡合法吗","为什么允许术士活动"}},{q="收到信后，杜希拉会传授什么教诲？",a="杜希拉警告说，若缺乏自律，从扭曲虚空汲取力量便有遭受腐化的风险。她敦促学徒保持自制和审慎，但也说，对腐化的恐惧不应压垮术士的野心。",al={"杜希拉的忠告","杜希拉说了什么","被污染的信件的教诲"}},{q="送达被污染的信件后，接下来要做什么？",a="与杜希拉交谈便完成了这次召唤，她也会成为你的训练师。她邀请你在力量增长后再来，进一步学习术士之道。",al={"被污染的信件之后的任务","被污染的信件后续"}}},fp="14,186,18.364.0,23.336.0,29.182.0,50.249.0,35.137.0,45.240.0,58.189.0,47.162.0"}
P.entries["quest:3106"] = {n="简易符文",s="在安威玛尔，斯登·粗臂为新晋矮人战士带来斯兰·库尔曼的召唤。符文召他们离开寒脊山谷的雪路，开始接受训练。",h="在安威玛尔，斯登·粗臂为新晋矮人战士带来斯兰·库尔曼的召唤。符文召他们离开寒脊山谷的雪路，开始接受训练。",kw={"安威玛尔","寒脊山谷","丹莫罗","铁炉堡","简易符文","斯登·粗臂","斯兰·库尔曼","土腭怪","战士"},ang={["class:Warrior"]="身为战士，这枚符文标志着你正式开始接受军事训练，并指引你前往安威玛尔寻找斯兰·库尔曼。",["faction:Alliance"]="身为联盟的一员，你在寒脊山谷接受训练，那里的山地部队守卫着通往卡兹莫丹的南部要道。",["race:Dwarf"]="身为矮人，你可以向斯兰·库尔曼学习矮人历代相传的坚毅。他教导新兵在世界变迁之际，坚守自己的钢铁文化。",["race:Gnome"]="身为被土腭怪和辐射逐出诺莫瑞根的侏儒，你在寒脊山谷跟随矮人导师学习前线作战，以求在流亡中生存。"},sec={{t="铁砧的召唤",b="老练的斥候观察新兵清除寒脊山谷周围的害兽，从中寻找有潜力的战士。斯登·粗臂带来了一块刻有斯兰·库尔曼留言的石头。石头上的简易符文召他们离开雪路，走进安威玛尔温暖的熔炉大厅，在那里立志踏上战士之路。"},{t="变迁中的丹莫罗",b="斯兰·库尔曼直言丹莫罗面临的困境。摧毁诺莫瑞根的爆炸让侏儒流离失所，前来寻求庇护，而一些矮人开始研习外来的奥术，或追随人类对圣光的信仰。土腭怪在地下深处受到惊扰后，开始侵扰群山边界。斯兰·库尔曼认为，只有严明的军事纪律才能抵御这些威胁。"}},faq={{q="简易符文是什么？",a="斯登·粗臂代斯兰·库尔曼带来一块刻有文字的石板。石板邀请新晋战士到室内报到，接受训练。",al={"简易符文物品","符文有什么用","简易符文背景故事"}},{q="斯兰·库尔曼是谁？",a="斯兰·库尔曼在寒脊山谷的安威玛尔内训练战士。他教导年轻的矮人和侏儒战士近战技巧、纪律，以及矮人的坚韧精神。",al={"斯兰·库尔曼是谁","斯兰·库尔曼背景故事","寒脊山谷战士训练师"}},{q="为什么侏儒住在丹莫罗和铁炉堡？",a="为了击退土腭怪的入侵，侏儒孤注一掷，引爆了造成灾难性后果的辐射炸药，随后逃离了诺莫瑞根。幸存者前往铁炉堡，向矮人盟友寻求庇护。",al={"侏儒为什么在这里","铁炉堡的侏儒","诺莫瑞根难民"}},{q="斯兰·库尔曼为什么提到土腭怪？",a="土腭怪是原始而凶残的生物，在地下深处受到了惊扰。近来，它们已闯入寒脊山谷和丹莫罗的地表洞穴，威胁着定居点和商路。安威玛尔的守卫必须时刻保持武装与警惕。",al={"土腭怪的威胁","附近为什么有土腭怪","寒脊山谷土腭怪"}},{q="斯兰·库尔曼提到矮人信奉圣光，是什么意思？",a="一些矮人与洛丹伦和暴风城等人类王国来往密切，因此接受了圣光信仰。如今，他们开始培养自己的圣骑士和牧师。",al={"矮人与圣光","矮人圣骑士背景故事","矮人牧师"}},{q="简易符文要交到哪里？",a="沿着寒脊山谷的小路往上走，将符文交给安威玛尔大型地堡大厅内训练场上的斯兰·库尔曼。",al={"简易符文在哪里交","斯兰·库尔曼在哪里","寻找斯兰·库尔曼"}}},fp="11,159,22.283.0,21.368.0,24.123.0,21.160.0,50.192.0,30.242.0,62.154.0,32.129.0"}
P.entries["quest:3107"] = {n="神圣符文",s="在安威玛尔，布罗莫斯·格鲁诺尔号召初出茅庐的矮人圣骑士加入白银之手骑士团。斯登·粗臂召他们前往那里。",h="在安威玛尔，布罗莫斯·格鲁诺尔号召初出茅庐的矮人圣骑士加入白银之手骑士团。斯登·粗臂召他们前往那里。",kw={"安威玛尔","布罗莫斯·格鲁诺尔","寒脊山谷","神圣符文","圣光","圣骑士训练师","白银之手","斯登·粗臂"},ang={["class:Paladin"]="作为圣骑士，这枚符文标志着你正式迈出了加入白银之手骑士团的第一步。你的职责是引导Light的力量，保卫铁炉堡。",["race:Dwarf"]="作为矮人，你将矮人传统的坚韧与人类传授的神学融为一体。矮人圣骑士以坚定不移的决心践行圣光的教义。"},sec={{t="安威玛尔的召唤",b="你的符文标志着正式入会的开始，未经磨炼的潜能必须接受纪律的约束。在寒脊山谷一带，当地领袖留意着那些在神圣武技方面天赋出众的人。布罗莫斯·格鲁诺尔在安威玛尔内等候，指引新入会的成员。"},{t="矮人与圣光",b="白银之手骑士团起源于洛丹伦的人类，但铁炉堡的矮人也以炽烈的虔诚接受了圣光。布罗莫斯欢迎你加入兄弟会，并提醒你，矮人圣骑士同样肩负着保卫艾泽拉斯的庄严职责。骑士团以牺牲、传统和武德为根基，要求新成员同样重视战锤与信仰。"}},faq={{q="什么是神圣符文？",a="神圣符文是斯登·粗臂在寒脊山谷交给矮人圣骑士新手的一枚刻有铭文的信物。它指引你前往安威玛尔，向布罗莫斯·格鲁诺尔接受正式训练。",al={"神圣符文物品","符文有什么用","寒脊山谷圣骑士符文"}},{q="布罗莫斯·格鲁诺尔是谁？",a="布罗莫斯·格鲁诺尔是安威玛尔内的圣骑士训练师。他教导新加入白银之手骑士团的矮人成员，让他们做好准备，应对威胁丹莫罗的危险。",al={"布罗莫斯是谁","安威玛尔圣骑士训练师","布罗莫斯·格鲁诺尔背景故事"}},{q="矮人为什么会加入白银之手骑士团？",a="第二次战争期间及战后，人类牧师和圣骑士将圣光的教义带给了铁炉堡的矮人。矮人敬重骑士团的军事纪律，以及为保卫艾泽拉斯甘愿牺牲的精神。",al={"矮人圣骑士背景故事","矮人为什么有圣骑士","白银之手矮人"}},{q="谁会给你神圣符文？",a="你帮助斯登·粗臂处理当地的事务后，他会在安威玛尔外将符文交给你。他说，是布罗莫斯·格鲁诺尔托他转交的。",al={"符文在哪里获得","谁交付符文"}},{q="布罗莫斯·格鲁诺尔在哪里？",a="布罗莫斯·格鲁诺尔位于寒脊山谷的安威玛尔大厅内，与其他职业导师在一起。",al={"布罗莫斯位置","布罗莫斯在哪里","寻找布罗莫斯·格鲁诺尔"}},{q="将符文交给布罗莫斯后会发生什么？",a="你交出符文后，布罗莫斯会确认你已获准加入白银之手，并为你提供首次正式的战斗与神圣之力训练。随后，他会派你返回丹莫罗。",al={"接下来是什么","神圣符文后续"}}},fp="16,135,21.242.0,26.390.0,29.178.0,23.176.0,55.228.0,35.135.0,33.103.0,49.179.0"}
P.entries["quest:3108"] = {n="风蚀符文",s="在寒脊山谷，矮人新手猎人会从斯登·粗臂手中收到一份刻在石上的召令。它指引他们前往安威玛尔，向里面的索加斯·格瑞姆森学习狩猎之道。",h="在寒脊山谷，矮人新手猎人会从斯登·粗臂手中收到一份刻在石上的召令。它指引他们前往安威玛尔，向里面的索加斯·格瑞姆森学习狩猎之道。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人","风蚀符文","猎人","斯登·粗臂","索加斯·格瑞姆森"},ang={["class:Hunter"]="作为猎人，风蚀符文开启了你在丹莫罗的旅程，让你结识索加斯·格瑞姆森，并了解矮人在追踪、武器保养和野外生存方面的传统。",["race:Dwarf"]="作为矮人，你能从用于传递正式消息的雕刻符文中，看出族人对石工、传统和经久耐用工艺的重视。"},sec={{t="刻在石上的召令",b="当你帮助斯登·粗臂应对寒脊山谷周围的威胁时，他会将风蚀符文交给你。矮人导师偏爱用雕刻的符文传递正式消息，而非口头命令或普通的羊皮纸。这块石板请你回顾初步历练中的收获，然后前往安威玛尔内部报到，接受更深入的狩猎指导。"},{t="丹莫罗猎人的传统",b="在安威玛尔，风蚀符文标志着猎人开始接受正式训练。索加斯·格瑞姆森教导你，在卡兹莫丹登山和求生，必须敬畏这片严酷的土地。你会学习辨认严寒积雪中的足迹，保养武器和弹药，并了解游荡在峭壁间的野兽。这枚符文标志着你迈出第一步，从独自持枪漫游的旅人，成为安威玛尔资深探路者麾下的学徒。"}},faq={{q="风蚀符文是什么？",a="风蚀符文是一块刻有文字的石板，邀请寒脊山谷的新手猎人前往安威玛尔，向里面的索加斯·格瑞姆森寻求正式训练。",al={"风蚀符文是什么","风蚀符文物品","符文含义"}},{q="风蚀符文是谁寄来的？",a="风蚀符文是索加斯·格瑞姆森寄来的。当你在安威玛尔外证明自己具备基本本领后，巡山人斯登·粗臂会将它交给你。",al={"谁给了我风蚀符文","风蚀符文寄件人"}},{q="该把风蚀符文带到哪里？",a="将风蚀符文带给索加斯·格瑞姆森，他在寒脊山谷的安威玛尔大厅内。",al={"该去哪里","该交给谁","索加斯位置"}},{q="矮人为什么用符文代替书信？",a="矮人文化重视石工、传统和经久耐用的工艺。与脆弱的羊皮纸相比，雕刻的符文能让消息和神圣的训诫更好地抵御丹莫罗的凛冽寒风与恶劣天气。",al={"为什么用风蚀符文","矮人符文背景"}},{q="将符文交给索加斯·格瑞姆森后会发生什么？",a="索加斯会欢迎你加入矮人追踪者的行列。他会讲解如何在冰封的峭壁间生存、保养装备并尊重野兽，然后提供基础猎人技艺的训练。",al={"索加斯教什么","交付风蚀符文"}},{q="任何职业都能收到风蚀符文吗？",a="只有在寒脊山谷踏上旅程的矮人猎人才能收到风蚀符文。其他职业会收到各自不同的信物，指引他们去安威玛尔寻找自己的导师。",al={"风蚀符文是否仅限猎人","战士能否获得风蚀符文"}}},fp="11,154,18.308.0,35.434.0,24.154.0,26.140.0,32.96.0,44.197.0,58.201.0,38.174.0"}
P.entries["quest:3109"] = {n="密文符文",s="在寒脊山谷，斯登·粗臂将一块刻有密文的符文交给年轻的潜行者，召他们进入安威玛尔，与索姆·哈格林见面。",h="在寒脊山谷，斯登·粗臂将一块刻有密文的符文交给年轻的潜行者，召他们进入安威玛尔，与索姆·哈格林见面。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文符文","诺莫瑞根","潜行者训练师","索姆·哈格林","斯登·粗臂"},ang={["class:Rogue"]="身为潜行者，这块符文将你引到索姆·哈格林面前。他愿意教你潜行、战斗诀窍，以及在丹莫罗求生的本领。",["race:Dwarf"]="作为铁炉堡氏族的一名矮人，索姆欢迎你踏入暗影。在丹莫罗，冰冷的刀刃与黑暗能助你保住性命。",["race:Gnome"]="身为侏儒，你听见索姆敦促学生们支持那些在寒脊山谷避难的侏儒，他们在诺莫瑞根的悲剧中失去了家园。"},sec={{t="密文中的消息",b="斯登说，有人悄悄把这块刻字的石头交给他，请他转交。他怀疑是索姆·哈格林送来的。这块符文考验新手能否保守秘密，召他们到里面去，免得索姆在庭院里高声宣布自己需要斥候和恶棍。"},{t="安威玛尔的屋梁下",b="在安威玛尔内，索姆·哈格林欢迎新来的潜行者入行。他愿意传授身法、攻击招式和隐秘技艺，让他们保住性命，赚取钱财。他还提醒矮人潜行者照顾流离失所的侏儒盟友，他们仍未从诺莫瑞根沦陷的浩劫中恢复过来。"}},faq={{q="密文符文是谁送来的？",a="安威玛尔大厅中的潜行者训练师索姆·哈格林写下了符文，并请斯登·粗臂在雪地里悄悄将它交给有潜力的新兵。",al={"谁写了符文","密文符文寄送者","谁把符文交给斯登"}},{q="在哪里能找到索姆·哈格林？",a="索姆·哈格林就在安威玛尔的主厅内，这座石堡坐落在丹莫罗的寒脊山谷中央。",al={"索姆在哪里","索姆·哈格林位置","寻找索姆"}},{q="这块符文有什么用途？",a="这块符文召潜行者新手解读其中的消息，并向训练师报到。他愿意教他们战斗技巧和求生身法。",al={"符文有什么用","密文符文用途","为什么使用密文符文"}},{q="索姆为什么提起侏儒？",a="诺莫瑞根不久前遭遇灾难而沦陷，侏儒难民与矮人一同住在寒脊山谷和安威玛尔。索姆提醒学生们，在侏儒逐渐适应这个临时家园时给予他们支持。",al={"为什么帮助侏儒","索姆谈诺莫瑞根"}},{q="谁将符文交给玩家？",a="潜行者冒险者帮助斯登·粗臂处理山谷中的事务后，他便会在寒脊山谷将这块石头交给他们。",al={"谁开启密文符文任务","密文符文任务给予者"}},{q="其他职业能收到这块符文吗？",a="不能。这块符文是交给那些在寒脊山谷踏上旅途的潜行者新人的。",al={"这个任务仅限潜行者吗","战士能获得密文符文吗"}}},fp="14,117,17.248.0,24.298.0,29.149.0,29.111.0,33.147.0,33.202.0,33.117.0,36.81.0"}
P.entries["quest:311"] = {n="向马莱斯回报",s="马莱斯在烈酒村等着你从卡拉诺斯带来雷霆麦酒。这桶酒将证明她的热麦酒已被送进雷酒的酒窖。",h="马莱斯在烈酒村等着你从卡拉诺斯带来雷霆麦酒。这桶酒将证明她的热麦酒已被送进雷酒的酒窖。",kw={"烈酒村","丹莫罗","卡拉诺斯","马莱斯·麦酒","热麦酒","雷霆麦酒","雷酒"},ang={["class:Rogue"]="身为潜行者，你可以潜入积雪山丘中有人看守的酒窖，调换酒桶，考验自己的潜行技巧和手上功夫。",["race:Dwarf"]="身为矮人，你知道酿酒既是一门技艺，也可以是一场关乎荣誉的较量。就连酒窖里的谍报活动，也能激起当地人的自豪感。"},sec={{t="破坏行动的战利品",b="这桶酒来自雷酒的酒窖，就在酿酒师们的眼皮底下被取走。它证明调包成功，也让马莱斯得到了来自对手的战利品。"},{t="苦酒之争落定",b="你扛着沉重的酒桶，翻过积雪的山脊，来到烈酒村。马莱斯为巧妙骗过卡拉诺斯的守卫和酒窖管事而欣喜不已。她这番大胆的行动表明，矮人家族极其珍视各自的独门配方。"}},faq={{q="这个任务的目的是什么？",a="你将偷来的那桶雷霆麦酒带给烈酒村的马莱斯·麦酒。它证明你已将她的热麦酒放进卡拉诺斯的酒窖。",al={"任务做什么","返回马莱斯任务目标","交还酒桶"}},{q="马莱斯·麦酒是谁？",a="马莱斯是烈酒村的一名矮人酿酒师。她以家族的烈性啤酒配方为傲，与卡拉诺斯的雷酒酿酒师们相互竞争。",al={"马莱斯是谁","马莱斯的故事","麦酒"}},{q="这桶酒是从哪里带来的？",a="你将马莱斯的热麦酒换进卡拉诺斯雷酒酿制厂的存酒后，从酒窖里取走了这桶酒。",al={"酒桶来自哪里","卡拉诺斯酒窖","雷霆麦酒位置"}},{q="烈酒村在哪里？",a="烈酒村坐落在丹莫罗西部涌冰湖冰封的湖畔，位于卡拉诺斯的西北方。",al={"烈酒位置","烈酒在哪里","如何找到马莱斯"}},{q="马莱斯为什么与卡拉诺斯结怨？",a="马莱斯想证明，她的热麦酒能胜过雷酒家族酿造的知名雷霆麦酒，或让这种酒颜面尽失。矮人酿酒大师们围绕各自的配方展开激烈竞争。",al={"为何成为对手","马莱斯与雷酒","酿酒之争"}},{q="马莱斯会怎么处理这桶酒？",a="这桶酒证明，调包就在卡拉诺斯守卫的眼皮底下成功了。马莱斯很乐意将对手的存酒据为己有。",al={"为何偷雷霆麦酒","麦酒的去向"}}},fp="17,144,22.153.0,21.211.0,34.143.0,26.145.0,33.122.0,26.103.0,37.166.0,37.125.0"}
P.entries["quest:3110"] = {n="神圣符文",s="在寒脊山谷，一位年轻的矮人牧师受到斯登·粗臂的召唤，前往安威玛尔。他将布兰斯托克·卡德尔刻下的祷文与指引交给这位新手，并召其进入大厅，加深与圣光的联系。",h="在寒脊山谷，一位年轻的矮人牧师受到斯登·粗臂的召唤，前往安威玛尔。他将布兰斯托克·卡德尔刻下的祷文与指引交给这位新手，并召其进入大厅，加深与圣光的联系。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","矮人牧师","神圣符文","斯登·粗臂"},ang={["class:Priest"]="身为牧师，这枚符文标志着你在丹莫罗正式获认可为圣光的侍奉者，并指引你前往布兰斯托克·卡德尔处，初次研习法术。",["race:Dwarf"]="身为矮人，你将对圣光的虔诚与山民的坚韧融为一体，协助寒脊山谷抵御入侵的穴居人。"},sec={{t="圣职的召唤",b="一位年轻的牧师在协助清除安威玛尔外的威胁时，引起了斯登·粗臂的注意。布兰斯托克·卡德尔是这座聚居地的精神导师，他将一枚刻有祷文与指引的符文交给斯登，托他转交给这位新手。随后，这位年轻的牧师被召入安威玛尔坚固的厅堂，开始研习神圣之道。"},{t="寒脊山谷的守卫者",b="矮人崇尚武力与厚重的板甲，但圣光在铁炉堡社会中仍占据着重要地位。在寒脊山谷，神圣法术的施法者与战士、猎人并肩作战，抵御穴居人的入侵和穿行于雪地的危险野兽，保卫这片聚居地。"}},faq={{q="什么是神圣符文？",a="斯登·粗臂代表布兰斯托克·卡德尔，将这枚刻有文字的牧师符文交给新手。符文上的祷文引领年轻的牧师认识信仰，并指引他们接受正式训练。",al={"什么是神圣符文","符文用途"}},{q="布兰斯托克·卡德尔是谁？",a="布兰斯托克·卡德尔在安威玛尔内训练矮人牧师。他以冷幽默和坚定的信仰引导新入门的侍僧，传授用于保卫寒脊山谷的基础神圣法术。",al={"布兰斯托克","寒脊山谷牧师训练师"}},{q="在哪里能找到布兰斯托克·卡德尔？",a="布兰斯托克·卡德尔就在安威玛尔的石砌主厅内，这座建筑坐落于丹莫罗寒脊山谷中央的空地上。",al={"布兰斯托克位置","布兰斯托克在哪里"}},{q="为什么寒脊山谷的矮人需要牧师？",a="穴居人已经占据了山谷的部分地区。卫兵坚守防线时，需要依靠牧师治疗伤者，并运用圣光对抗敌人。",al={"为什么需要矮人牧师","安威玛尔的牧师"}},{q="任何职业都能接受这个任务吗？",a="不能。只有在寒脊山谷踏上旅程的年轻矮人牧师才能收到神圣符文。",al={"谁能获得神圣符文","这个任务是否仅限牧师"}},{q="谁将符文交给玩家？",a="斯登·粗臂负责交付符文。他是安威玛尔的一名巡山人，负责监督大厅外的试炼，会在你初到山谷、协助守卫这里之后，将符文交给你。",al={"谁提供神圣符文任务","斯登·粗臂的职责"}}},fp="13,225,22.306.0,22.269.0,26.168.0,25.186.0,34.117.0,48.148.0,30.99.0,36.160.0"}
P.entries["quest:3112"] = {n="简易备忘录",s="在寒脊山谷，侏儒战士收到召唤，前往安威玛尔。斯登·粗臂将斯兰·库尔曼的召唤带给受过训练的战士，邀请他们学习作战技艺，为夺回诺莫瑞根做好准备。",h="在寒脊山谷，侏儒战士收到召唤，前往安威玛尔。斯登·粗臂将斯兰·库尔曼的召唤带给受过训练的战士，邀请他们学习作战技艺，为夺回诺莫瑞根做好准备。",kw={"安威玛尔","寒脊山谷","丹莫罗","诺莫瑞根","简易备忘录","斯登·粗臂","斯兰·库尔曼","战士训练师"},ang={["class:Warrior"]="身为侏儒战士，你在铁炉堡资深武器大师的指导下，开始学习战斗技艺。",["race:Dwarf"]="身为矮人，你看到斯兰·库尔曼对待侏儒的困境如同对待矮人间的世仇一样认真，与流离失所的盟友同舟共济。",["race:Gnome"]="身为侏儒，你铭记着被迫离开诺莫瑞根的流亡岁月，决心训练士兵，夺回那座遭到辐射污染的城市。"},sec={{t="安威玛尔的召唤",b="你帮助斯登·粗臂驱赶寒脊山谷的穴居人和野猪。安威玛尔的资深训练师斯兰·库尔曼看到了这名难民新兵的潜力。他召唤这名新兵前往中央大厅，接受战斗训练。"},{t="团结互助的誓言",b="矮人训练师或许会拿侏儒战士的个头打趣，但斯兰·库尔曼十分重视他们失去家园的遭遇。他请他们想象，如果铁炉堡落入黑铁矮人之手，矮人会有何感受。斯兰已立誓帮助流亡的侏儒。他传授他们作战技艺，直到他们准备好夺回家园。"}},faq={{q="简易备忘录是什么？",a="在寒脊山谷，斯登·粗臂交给侏儒战士一张便条，指引他们去找安威玛尔大厅里的战士训练师斯兰·库尔曼。",al={"简易备忘录","这张便条是什么","备忘录任务"}},{q="是谁送来这份备忘录的？",a="斯兰·库尔曼通过斯登·粗臂，将备忘录交给那些协助巡山人、颇具潜力的战士。",al={"备忘录是谁写的","简易备忘录是谁送的"}},{q="斯兰·库尔曼为什么训练侏儒战士？",a="斯兰·库尔曼曾立誓帮助流亡的侏儒。他敬重他们的决心，也理解他们失去家园的痛苦。他将诺莫瑞根的陷落比作铁炉堡被黑铁矮人攻占。",al={"斯兰为什么训练侏儒","侏儒战士背景故事"}},{q="在哪里能找到斯兰·库尔曼？",a="你可以在丹莫罗寒脊山谷的安威玛尔主厅内找到斯兰·库尔曼。",al={"斯兰·库尔曼在哪里","斯兰·库尔曼位置"}},{q="斯登·粗臂是谁？",a="斯登·粗臂是一名矮人巡山人，驻守在寒脊山谷的安威玛尔外。他负责协调防御，抵御凶猛的野猪和入侵的穴居人。",al={"斯登·粗臂","斯登是谁"}},{q="侏儒为什么从寒脊山谷开始冒险？",a="诺莫瑞根陷落并遭到辐射污染后，幸存的侏儒作为难民逃入矮人的领地。安威玛尔和铁炉堡向他们敞开大门，在他们重建力量期间提供庇护。",al={"侏儒为什么在这里","寒脊山谷的侏儒"}}},fp="17,208,21.219.0,22.310.0,30.143.0,25.104.0,44.182.0,30.90.0,21.149.0,44.191.0"}
P.entries["quest:3113"] = {n="密文备忘录",s="在寒脊山谷，斯登·粗臂将一张折好的便笺交给初出茅庐的侏儒潜行者，让他们转交给安威玛尔内的索姆·哈格林。",h="在寒脊山谷，斯登·粗臂将一张折好的便笺交给初出茅庐的侏儒潜行者，让他们转交给安威玛尔内的索姆·哈格林。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文备忘录","诺莫瑞根","潜行者训练师","索姆·哈格林","斯登·粗臂"},ang={["class:Rogue"]="身为潜行者，你首次收到前去拜会索姆·哈格林的召唤。他在信中告诉你，在矮人的土地上从事隐秘的行当，需要同道之间的相互庇护。",["race:Dwarf"]="身为矮人，你看到斯登·粗臂这样的巡山人，在铁炉堡与寒脊山谷流离失所的侏儒之间传递消息。",["race:Gnome"]="身为侏儒，你看到诺莫瑞根沦陷后难民所面临的困境。幸存者寄居在矮人之中，彼此团结。"},sec={{t="隐秘的引荐",b="当你帮助巡山人应对穴居人的威胁时，斯登将一张受托保管的羊皮纸交给你。它看起来像是一份正式的备忘录。便笺邀请你去见驻扎在安威玛尔内的潜行者训练师索姆·哈格林。"},{t="雪中共患难",b="诺莫瑞根突然沦陷，侏儒幸存者被迫离开地下家园，与收留他们的矮人挤在狭小的住处。索姆·哈格林知道，每当有物品失踪，潜行者总会遭人怀疑。因此，他敦促他们暗中团结起来，互相帮助，共渡难关。"}},faq={{q="密文备忘录是谁写的？",a="这张便笺出自安威玛尔内的潜行者训练师索姆·哈格林之手。他将它伪装成上级下达的正式指令，好让斯登·粗臂毫不起疑地转交出去。",al={"谁寄出备忘录","谁写的便笺","索姆的便笺"}},{q="为什么要伪装备忘录？",a="索姆·哈格林将便笺加以伪装，是为了在矮人的要塞安威玛尔内悄悄与你接触。他行事低调，以免装备失踪时招来流言或指控，并用暗语向同道中人传递消息。",al={"为何伪装","为何加密"}},{q="这张便笺透露了丹莫罗的什么状况？",a="便笺描述了诺莫瑞根沦陷后，侏儒与矮人之间的紧张与团结。在铁炉堡和丹莫罗共用居所，让资源变得紧张，因此索姆敦促从事暗影行当的人彼此照应。",al={"侏儒与矮人的关系","诺莫瑞根难民 丹莫罗"}},{q="是谁将备忘录交给玩家的？",a="你在寒脊山谷帮助斯登·粗臂后，他便将备忘录交给你。他以为索姆·哈格林送来这份备忘录是为了安排你的训练。",al={"斯登·粗臂递送","谁递交便笺"}},{q="索姆·哈格林担任什么职务？",a="索姆·哈格林在安威玛尔的山中大厅内训练潜行者。他向新入行的潜行者传授战斗技巧与暗影技艺。",al={"索姆·哈格林的职务","索姆做什么"}},{q="这个任务与诺莫瑞根的沦陷有关吗？",a="有关。索姆提到诺莫瑞根已被攻陷，并表示流离失所的侏儒潜行者尽管失去了机械家园，仍能凭借彼此的兄弟情谊坚持下去。",al={"诺莫瑞根沦陷的背景故事","侏儒难民的处境"}}},fp="20,105,23.219.0,28.268.0,35.174.0,32.218.0,61.226.0,42.129.0,34.120.0,44.165.0"}
P.entries["quest:3114"] = {n="雕文备忘录",s="在安威玛尔，巡山人斯登·粗臂交给你一份来自法师训练师玛瑞克·斯托纳尔的备忘录，邀请你去见他。",h="在安威玛尔，巡山人斯登·粗臂交给你一份来自法师训练师玛瑞克·斯托纳尔的备忘录，邀请你去见他。",kw={"安威玛尔","寒脊山谷","丹莫罗","雕文备忘录","法师训练师","玛瑞克·斯托纳尔","斯登·粗臂"},ang={["class:Mage"]="作为法师，你会通过这份备忘录，在丹莫罗见到自己的第一位奥术训练师。",["faction:Alliance"]="作为联盟的一员，你会通过寒脊山谷的斯登·粗臂和玛瑞克·斯托纳尔，看到矮人与侏儒如何携手合作。",["race:Gnome"]="作为侏儒，你可以向玛瑞克·斯托纳尔学习。他是在诺莫瑞根沦陷后前往矮人领地避难的侏儒专家之一。"},sec={{t="致新手法师的信",b="这份召唤是给你的，你是斯登在寒脊山谷帮助的一名新手法师。读完后，进入安威玛尔，去见写下它的侏儒。你的法术研习将从那里开始。"},{t="向玛瑞克·斯托纳尔学习",b="在安威玛尔内，侏儒法师训练师玛瑞克·斯托纳尔会在授课前给你几句朴实的忠告。别惹上大麻烦，攒些钱用来训练和去酒馆喝酒。远离沦陷的诺莫瑞根，那里有危险的辐射。玛瑞克已经准备好传授你奥术技艺。"}},faq={{q="谁会交给我这份备忘录？",a="在寒脊山谷帮助巡山人斯登·粗臂完成最初的事务后，他就会把备忘录交给你。",al={"谁发放雕文备忘录","斯登·粗臂任务"}},{q="玛瑞克·斯托纳尔是谁？",a="玛瑞克·斯托纳尔是寒脊山谷安威玛尔内的一名侏儒法师训练师。他教导新手法师入门法术，以及如何安全地研习奥术。",al={"玛瑞克是谁","安威玛尔法师训练师"}},{q="在哪里可以找到玛瑞克·斯托纳尔？",a="你可以在丹莫罗寒脊山谷最上端的安威玛尔大厅内找到玛瑞克·斯托纳尔。",al={"玛瑞克·斯托纳尔位置","寒脊山谷的法师训练师在哪"}},{q="玛瑞克为什么告诫我不要前往诺莫瑞根？",a="穴居人占领了诺莫瑞根，一场灾难性的放射性气体泄漏污染了整座城市。对于在丹莫罗四处游历的新手来说，那里十分危险。",al={"玛瑞克关于诺莫瑞根的警告","为什么要远离诺莫瑞根"}},{q="哪些职业会接到这项任务？",a="在寒脊山谷开始研习的新手法师会收到备忘录，前去拜见自己的职业训练师。",al={"谁能接到雕文备忘录","这个任务是否仅限法师"}},{q="玛瑞克对学生有什么要求？",a="玛瑞克劝学生们别惹麻烦，攒些银币学习法术，再给他买杯麦酒，还要远离诺莫瑞根。",al={"玛瑞克的要求","训练师想要什么"}}},fp="18,125,26.173.0,29.272.0,29.112.0,23.160.0,33.103.0,49.145.0,31.105.0,42.133.0"}
P.entries["quest:3115"] = {n="被污染的备忘录",s="在寒脊山谷，斯登·粗臂悄悄派你去安威玛尔找阿拉玛尔·格里姆。格里姆劝你相信黑暗力量，而非收留你的矮人。",h="在寒脊山谷，斯登·粗臂悄悄派你去安威玛尔找阿拉玛尔·格里姆。格里姆劝你相信黑暗力量，而非收留你的矮人。",kw={"阿拉玛尔·格里姆","安威玛尔","寒脊山谷","丹莫罗","侏儒术士","诺莫瑞根流亡者","斯登·粗臂","被污染的备忘录"},ang={["class:Warlock"]="身为术士，你会收到一封信，标志着你正式踏上术士之道。信中将恶魔契约视为求生所迫的务实选择，而非疯狂之举。",["race:Dwarf"]="身为矮人，你看到族人容忍这些黑暗施法者在自己的屋檐下活动，却明显流露出厌恶与强烈的戒心。",["race:Gnome"]="身为侏儒，你或许也和一些流亡者一样，对失去家园、依赖铁炉堡的处境心怀怨愤。"},sec={{t="秘密的召唤",b="术士在寒脊山谷备受猜忌。你帮助斯登·粗臂应对当地的威胁时，他不情愿地偷偷递给你一张便笺。他的警告清楚地表明，这里的人对你这样的术士有多不信任，即使那份勉强维系的休战约定允许术士在联盟领地内修习法术。"},{t="流亡侏儒的怨愤",b="在安威玛尔，阿拉玛尔·格里姆谈起了侏儒的困境。他认为，寻常的魔法和机械技艺未能拯救诺莫瑞根，使他们的族人濒临灭绝，沦为仰赖矮人善意、低人一等的难民。他劝你既不要相信圣光，也不要相信矮人的政治手段。相反，你应当召唤恶魔并驾驭它们，因为它们的服从不附带任何条件。"}},faq={{q="被污染的备忘录是什么？",a="被污染的备忘录是斯登·粗臂在寒脊山谷交给侏儒术士新手的一封书信。信中指引他们去寻找安威玛尔的术士训练师阿拉玛尔·格里姆。",al={"被污染的备忘录","术士便笺 丹莫罗","备忘录是什么"}},{q="为什么寒脊山谷的人不信任术士？",a="矮人及其联盟盟友崇尚武勇与荣誉，并信奉圣光。他们认为恶魔学识和暗影魔法既堕落又危险，因此对侏儒术士深怀疑虑。",al={"矮人为什么不喜欢术士","术士偏见 安威玛尔"}},{q="阿拉玛尔·格里姆是谁？",a="阿拉玛尔·格里姆是安威玛尔的一位侏儒术士训练师。他对诺莫瑞根的陷落以及侏儒仰赖矮人施舍的处境愤懑不已，因而教导年轻侏儒束缚恶魔仆从，为自己夺取力量。",al={"阿拉玛尔·格里姆的故事","阿拉玛尔是谁"}},{q="为什么格里姆批评普通魔法和技术？",a="格里姆认为，在诺莫瑞根的灾难中，传统工程学和公认的魔法学派都未能拯救侏儒。他说，这使侏儒不得不依赖矮人的资助，而这些资助者将与人类的关系置于收复侏儒家园之上。",al={"格里姆对诺莫瑞根的看法","为什么选择黑暗魔法而非工程学"}},{q="矮人术士能接到这个任务吗？",a="不能。在丹莫罗，只有侏儒能修习术士之道，因此这份召唤是发给初来乍到的侏儒术士的。",al={"矮人术士 被污染的备忘录","矮人能成为术士吗"}},{q="这个任务在哪里进行？",a="你从寒脊山谷的斯登·粗臂附近出发，最终在安威玛尔内部完成任务。这座位于丹莫罗西南部的中央堡垒俯瞰着山谷。",al={"阿拉玛尔·格里姆在哪里","被污染的备忘录交任务"}}},fp="18,142,18.270.0,27.373.0,31.177.0,48.178.0,20.213.0,53.233.0,38.118.0,33.147.0"}
P.entries["quest:3116"] = {n="简易符记",s="简易符记是发给幽影谷中有抱负的暗夜精灵战士的入门征召令。它由管理员伊尔萨莱恩代表训练师奥莉希亚传达，正式标志着新兵开始接受战斗训练，以保护尚显稚嫩的泰达希尔枝叶。",h="简易符记是发给幽影谷中有抱负的暗夜精灵战士的入门征召令。它由管理员伊尔萨莱恩代表训练师奥莉希亚传达，正式标志着新兵开始接受战斗训练，以保护尚显稚嫩的泰达希尔枝叶。",kw={"奥达希尔","奥莉希亚","菲拉斯","伊尔萨莱恩","幽影谷","简易符记","泰达希尔","战士"},ang={["class:Warrior"]="这个任务标志着你作为卡多雷战士的正式开始，将你作为你的第一位武器导师介绍给奥莉希亚。",["faction:Alliance"]="奥莉希亚的建议反映了暗夜精灵尽管历经数世纪的孤立，却依然努力欢迎其他联盟种族来到他们枝叶下的早期举措。",["race:NightElf"]="这枚符记直接反映了卡多雷周围发生的快速变化——从种植泰达希尔，到向外国盟友开放他们与世隔绝的家园。"},sec={{t="幽影谷的战斗号角",b="在证明了自己能够应对幽影谷中躁动的野生动物并掌握基本生存技能后，年轻的暗夜精灵战士会收到一枚经由管理员伊尔萨莱恩转交的刻印符记。这枚代币是奥莉希亚发出的正式请求，她是驻扎在奥达希尔的当地战士训练师，旨在邀请新兵站出来，为保卫族人贡献他们的武力。"},{t="动荡的新纪元",b="当向奥莉希亚报到时，她会将战士的训练置于快速且令人不安的变革背景下。在短短几年内，暗夜精灵种下了世界之树泰达希尔，目睹了一种阴险的腐蚀在远近的森林野兽中蔓延，并重新与曾经被认为已经失落的古老祖先领地（如菲拉斯）取得了联系。面对这些威胁，急需能干的守卫者。"},{t="开启枝叶",b="除了武艺训练外，奥莉希亚还为年轻的卡多雷准备好面对他们这片庇护谷地之外的世界。她建议新兵不要对那些来到泰达希尔的其他种族外来者抱有偏见。虽然她告诫说并非每一位旅者都是出于纯粹的利他主义，但她强调盟友对保卫卡多雷至关重要，并敦促她的学生在担任守护者角色时，给予适度的信任。"}},faq={{q="什么是简易符记？",a="这是一枚由幽影谷的战士训练师奥莉希亚发出的刻印代币，发给初出茅庐的暗夜精灵战士，以召唤他们进行正式的战斗指导。",al={"简易符记物品","这个符记是什么","战士符记"}},{q="谁派你去找奥莉希亚的？",a="在你完成在幽影谷维持平衡的初步任务后，管理员伊尔萨莱恩会将符记交给你，并指引你去找奥莉希亚。",al={"谁发放简易符记","简易符记任务发布者"}},{q="奥莉希亚在哪里？",a="奥莉希亚位于幽影谷的安全避风港内，站在奥达希尔的巨树干旁，在那里训练有抱负的暗夜精灵战士。",al={"奥莉希亚位置","奥莉希亚在哪里","幽影谷战士训练师"}},{q="为什么奥莉希亚说现在需要战士？",a="近年来带来了巨大的挑战：泰达希尔的建立、感染当地野生动物的广泛腐蚀，以及对菲拉斯等久已失落之地的重新发现。需要熟练的战斗人员来保护卡多雷免受这些迫在眉睫的威胁。",al={"为什么暗夜精灵需要战士","幽影谷战士背景"}},{q="奥莉希亚对访问泰达希尔的其他种族有什么评价？",a="她劝诫不要抱有偏见，解释说其他种族的外来者很快就会造访泰达希尔的枝叶。虽然她承认并非所有到访者都是纯粹出于利他主义，但她建议给予一定程度的信任，以便他们能协助保卫这棵大树。",al={"奥莉希亚关于其他种族的看法","暗夜精灵与外来者","泰达希尔的联盟"}},{q="提到菲拉斯有什么意义？",a="菲拉斯代表了暗夜精灵古老的土地，这些土地在天崩地裂后长期与世隔绝或被认为已经失落。它的被重新发现凸显了卡多雷在经历了数千年的孤立后，正以多快的速度与广阔的世界重新建立联系。",al={"为什么要提到菲拉斯","菲拉斯的联系"}}},fp="12,177,28.294.0,20.336.0,18.305.0,25.137.0,31.143.0,28.110.0,52.222.0,61.197.0,47.200.0"}
P.entries["quest:3117"] = {n="风化符记",s="在幽影谷，风化符记召唤年轻的暗夜精灵猎人前往奥达希尔。阿亚娜·远途通过管理员伊尔萨莱恩传来召唤，让他们拜见训练师，开始学习箭术与驯兽技艺。",h="在幽影谷，风化符记召唤年轻的暗夜精灵猎人前往奥达希尔。阿亚娜·远途通过管理员伊尔萨莱恩传来召唤，让他们拜见训练师，开始学习箭术与驯兽技艺。",kw={"奥达希尔","阿亚娜·远途","风化符记","猎人","伊尔萨莱恩","幽影谷","泰达希尔"},ang={["class:Hunter"]="作为猎人，你将在泰达希尔开始训练，学习箭术、追踪和野兽掌控。",["race:NightElf"]="作为kaldorei，你继承的狩猎传统源于与自然和谐共处以及对Elune的崇敬，而非单纯的消遣。"},sec={{t="枝头的召唤",b="年轻的卡多雷猎人协助保卫幽影谷后，管理员伊尔萨莱恩会交给他们一枚刻有文字的信物。这是信使从他们的导师阿亚娜·远途那里带来的。符记指引每位新手登上奥达希尔的高枝，训练师们在那里守望着树冠。"},{t="猎人之路",b="拜见阿亚娜，便开启了猎人在泰达希尔的训练。她教导新手射击技巧，以及如何了解卡利姆多的野生生物。猎人必须尊重自己的野兽伙伴，以警觉和谦逊面对世间潜藏的危险。"}},faq={{q="风化符记是什么？",a="风化符记是阿亚娜·远途刻下的口信，指引有潜力的暗夜精灵新手前往她在奥达希尔顶端的驻地。",al={"风化符记","这个符记是什么","符记物品"}},{q="阿亚娜·远途在哪里？",a="阿亚娜·远途位于奥达希尔上层的平台，就在幽影谷中央那棵巨大世界之树的树洞中。",al={"阿亚娜在哪里","寻找阿亚娜·远途","阿亚娜·远途的位置"}},{q="谁会发放风化符记？",a="暗夜精灵猎人开始通过保卫当地林地证明自己时，管理员伊尔萨莱恩会将风化符记交给他们。",al={"谁发放任务","任务给予者","在哪里获得风化符记"}},{q="阿亚娜·远途传授什么？",a="阿亚娜传授射击技巧、照料野兽的方法和野外生存之道。她告诫猎人，不要低估外界的危险。",al={"猎人训练","阿亚娜教什么","为何与阿亚娜交谈"}},{q="阿亚娜为何告诫猎人要慎重对待宠物？",a="阿亚娜告诫猎人，要尊重自己的动物伙伴。荒野中潜藏的威胁远超新手的想象，因此他们绝不能轻视伙伴的能力。",al={"野兽的危险","为何尊重野兽","宠物相关告诫"}},{q="其他职业也能接到这个任务吗？",a="不能。风化符记是专门面向暗夜精灵猎人的入门召唤。",al={"德鲁伊能做这个任务吗","是否仅限猎人","其他职业"}}},fp="12,201,23.271.0,22.254.0,25.126.0,35.113.0,31.132.0,34.129.0,49.189.0,41.76.0"}
P.entries["quest:3118"] = {n="密文符记",s="在幽影谷，一份加密的召令召唤初出茅庐的暗夜精灵潜行者开始训练。管理员伊尔萨莱恩替弗拉胡恩·影语者保管着这份召令，而后者也警告说，卡利姆多各地的和平十分脆弱。",h="在幽影谷，一份加密的召令召唤初出茅庐的暗夜精灵潜行者开始训练。管理员伊尔萨莱恩替弗拉胡恩·影语者保管着这份召令，而后者也警告说，卡利姆多各地的和平十分脆弱。",kw={"奥达希尔","管理员伊尔萨莱恩","密文符记","弗拉胡恩·影语者","潜行者训练师","幽影谷","泰达希尔"},ang={["class:Rogue"]="身为潜行者，你加入了由斥候、刺客和密探组成的kaldorei情报网，保护泰达希尔免受隐秘敌人的侵害。",["faction:Alliance"]="身为联盟的一员，你听到幽影谷的训练师警告说，各阵营间的条约十分脆弱，而情报工作有助于阻止部落入侵。",["race:NightElf"]="身为暗夜精灵，你与奥达希尔一同守望卡利姆多不断变动的边界，保卫新近栽下的枝桠。"},sec={{t="暗影中的消息",b="年轻的暗夜精灵在管理员伊尔萨莱恩的指导下学习自然的平衡，而那些向往潜行之道的人则会收到一份更隐秘的召令。一名信使带来了幽影谷潜行者导师弗拉胡恩·影语者送出的密文符记。上面的密文是写给初入此道的学徒的。持有者需要破译消息，然后前往奥达希尔的根部附近寻找弗拉胡恩，开始接受指导。"},{t="遥望天际",b="弗拉胡恩的消息也警告说，卡利姆多的和平尚不稳固。第三次大战已经结束，但联盟与新兴的部落之间的休战仍然脆弱。幽影谷的潜行者斥候与密探被敦促尽早磨炼耳目。他们留意着各种威胁与暗中的挑衅，以防战火再度跨越边界蔓延。"}},faq={{q="密文符记是什么？",a="密文符记是潜行者导师弗拉胡恩·影语者发出的加密信物，指引幽影谷的新晋潜行者到奥达希尔下方寻找他，接受训练。",al={"这枚符记是什么","密文符记任务","符记物品"}},{q="谁将符记交给年轻的暗夜精灵？",a="当学徒在应对幽影谷枝桠周围的野生动物时展现出基本本领，管理员伊尔萨莱恩便会代弗拉胡恩交付符记。",al={"谁提供任务","任务给予者","管理员伊尔萨莱恩"}},{q="在哪里可以找到弗拉胡恩·影语者？",a="在幽影谷的大树奥达希尔庇护之下，可以找到弗拉胡恩·影语者，他随时准备指导新来的暗夜精灵潜行者。",al={"弗拉胡恩在哪里","寻找弗拉胡恩·影语者","弗拉胡恩位置"}},{q="宁静的泰达希尔为何需要潜行者？",a="潜行者不可或缺，因为与外界势力的休战十分脆弱。斥候与密探监视着暗中的阴谋，包括部落的动向和枝桠间潜藏的威胁。",al={"暗夜精灵为何需要潜行者","幽影谷的潜行者","潜行者的作用"}},{q="将符记交给弗拉胡恩后会怎样？",a="你交出符记后，弗拉胡恩会收下密文，并认可你已做好准备。他请你在积累经验后再来，以便传授你战斗技巧、武器运用和潜行之术。",al={"接下来是什么","密文符记之后","符记奖励背景"}},{q="部落是否正直接威胁着幽影谷？",a="部落并未公开进攻与世隔绝的泰达希尔，但有传言称，部落特工正在卡利姆多各地散播猜疑，这让卡多雷的哨兵与密探始终保持警惕。",al={"部落是否在泰达希尔","部落对幽影谷的威胁","部落散播猜疑"}}},fp="15,198,24.364.0,20.343.0,28.137.0,41.144.0,39.136.0,45.169.0,50.190.0,53.166.0"}
P.entries["quest:3119"] = {n="神圣符记",s="神圣符记是给在幽影谷开始训练的年轻暗夜精灵牧师的入门召唤信物。管理员伊尔萨莱恩传达了来自牧师训练师珊达的消息，指导新手修行者前往奥达希尔寻求指引，学习如何运用艾露恩的恩典。",h="神圣符记是给在幽影谷开始训练的年轻暗夜精灵牧师的入门召唤信物。管理员伊尔萨莱恩传达了来自牧师训练师珊达的消息，指导新手修行者前往奥达希尔寻求指引，学习如何运用艾露恩的恩典。",kw={"奥达希尔","管理员伊尔萨莱恩","艾露恩","神圣符记","牧师","幽影谷","珊达","泰达希尔"},ang={["class:Priest"]="这一通过仪式将年轻的卡多雷牧师与珊达联系起来，开启了他们在艾露恩的光辉与智慧中的正式训练。",["faction:Alliance"]="珊达的言论突显了新建立的联盟关系是如何将不熟悉的种族和旅者直接带到泰达希尔的枝干上的。",["race:NightElf"]="牧师体系是卡多雷文化的核心，由指引其族人几千年的古老月神信仰传统所管理。"},sec={{t="侍奉的召唤",b="在暗夜精灵文化中，牧师作为月神艾露恩的侍女和仆人，占据着神圣的地位。当幽影谷的一位年轻卡多雷表现出对圣光和信仰的亲和力时，管理员伊尔萨莱恩便会将一枚神圣符记交托给他们。这枚由牧师训练师珊达派信使送来的信物，是一份正式的邀请，请他们前往奥达希尔之树，开始专业的灵性教导。"},{t="变革的世界",b="在见到珊达后，年轻的侍僧发现受庇护的泰达希尔圣地正在经历不同寻常的动荡。珊达指出，世界之树的枝干上开始出现旅者，其中包括获准与卡多雷会面的联盟成员。虽然广阔的世界在呼唤，但珊达建议新手在涉足更遥远的纷争之前，先立足于幽影谷目前面临的问题。"}},faq={{q="什么是神圣符记？",a="这是一枚由牧师训练师珊达通过信使发送给管理员伊尔萨莱恩的刻印信物，旨在召唤新手牧师前往奥达希尔接受指导。",al={"神圣符记物品","这个符记是什么","珊达的符记"}},{q="珊达是谁？",a="珊达是驻扎在幽影谷奥达希尔的牧师训练师。她指导初出茅庐的暗夜精灵牧师进行艾露恩姐妹会的基本仪式、纪律和祈祷。",al={"奥达希尔牧师训练师","珊达是谁"}},{q="珊达在哪里？",a="珊达居住在幽影谷中心地带的巨大树木——奥达希尔的空心树根内部，这里位于泰达希尔。",al={"找到珊达","神圣符记交任务地点","珊达位置"}},{q="为什么联盟成员会访问泰达希尔？",a="在第三次战争后，暗夜精灵与联盟建立了联系。外族人开始抵达泰达希尔的枝干上，与卡多雷进行协调和商议，因为双方都在为艾泽拉斯面临的挑战做准备。",al={"泰达希尔的联盟","为什么外来者在世界之树"}},{q="牧师完成这个任务后应该做什么？",a="珊达建议牧师协助幽影谷各地的当地守卫者和看守者，并在需要学习新的祈祷和技巧时随时回到她身边。",al={"拿到符记后做什么","神圣符记之后"}},{q="为什么伊尔萨莱恩要发布这个任务？",a="管理员伊尔萨莱恩负责监督幽影谷中新手的最初试炼。当珊达的信使带着符记到达时，伊尔萨莱恩将其保管，直到这位有抱负的牧师证明自己有能力迈出下一步。",al={"管理员伊尔萨莱恩牧师","为什么和伊尔萨莱恩对话"}}},fp="14,206,20.343.0,16.346.0,27.148.0,14.134.0,24.111.0,45.266.0,51.144.0,36.204.0"}
P.entries["quest:312"] = {n="马克格拉恩的干肉",s="图德拉·马克格拉恩需要从冰须那里取回过冬的储粮。那只雪人搬走了用瑟银加固的储肉箱，而马克格拉恩腿上有伤，无法前往洞穴。",h="图德拉·马克格拉恩需要从冰须那里取回过冬的储粮。那只雪人搬走了用瑟银加固的储肉箱，而马克格拉恩腿上有伤，无法前往洞穴。",kw={"肉干","丹莫罗","储肉箱","冰须","失窃的储粮","瑟银","图德拉·马克格拉恩","雪人"},ang={["class:Hunter"]="身为猎人，你知道保存肉食要花多少工夫。马克格拉恩外出追踪鹿群时，一头野兽偷走了他的储粮。",["class:Rogue"]="身为潜行者，你可以趁冰须不在时潜入它的洞穴，不动刀刃就能取走储肉箱。",["race:Dwarf"]="身为矮人，你知道山中的寒冬有多么严酷。没有腌肉或栖身之所，即使是经验丰富的登山者，也未必能抵御严寒。"},sec={{t="冬粮与失窃的储肉箱",b="为了过冬，马克格拉恩腌制了足够吃一个月的肉干。他将肉干封在用瑟银加固的箱子里，以防饥饿的熊偷吃。冰须没有试着打开箱子，而是把整个箱子搬走了。"},{t="冰须的巢穴",b="趁马克格拉恩外出猎鹿时，冰须把箱子拖进了崎岖山丘中的一处洞穴。马克格拉恩相信雪人无法破开坚固的瑟银，但他腿上有伤，无法取回储粮。你可以迎战这头野兽，也可以趁它在雪堆间游荡时潜入洞穴。"}},faq={{q="图德拉·马克格拉恩是谁？",a="图德拉·马克格拉恩是一名矮人猎人，住在丹莫罗的冰雪地带。他腿上有伤，只能依靠储存的食物过冬。",al={"图德拉·马克格拉恩","马克格拉恩","马克格拉恩是谁"}},{q="谁偷走了马克格拉恩的储肉箱？",a="当地的雪人冰须趁马克格拉恩外出猎鹿时，偷走了他的储肉箱。那头野兽把箱子拖进了山中的洞穴。",al={"谁偷走了储粮","谁拿走了肉","偷走储粮的窃贼"}},{q="马克格拉恩为什么不能自己取回肉？",a="马克格拉恩腿上有伤，行动不够敏捷，也不够隐蔽，无法进入冰须的洞穴后安全脱身。",al={"马克格拉恩为什么无法取回储粮","马克格拉恩的腿","伤腿"}},{q="雪人把食物吃了吗？",a="没有。肉干仍锁在坚固的瑟银箱中。冰须把箱子搬走了，却无法破开这层金属。",al={"食物被吃了吗","冰须能打开箱子吗"}},{q="必须打败冰须才能取回储肉箱吗？",a="你可以趁冰须外出游荡时潜入洞穴，无须与它交战就能取回储肉箱。",al={"能潜行绕过冰须吗","必须杀死冰须吗"}},{q="被偷走的储粮在哪里？",a="被偷走的储肉箱就在冰须的山洞深处，位于丹莫罗马克格拉恩营地附近的山丘中。",al={"洞穴在哪里","冰须洞穴位置"}}},fx={ceb049bb={q="图德拉·马克格拉恩为什么需要找回他的储肉箱？",a="马克格拉恩花了许多天狩猎，腌制了足足一个月的口粮，好熬过丹莫罗严酷的寒季。一旦冬日的风雪袭来，失去这些腌肉的他就会在偏远的山间营地面临饥荒，因为腿伤让他无法及时猎获足够的野兽，补齐过冬的储备。",al={"为什么帮助图德拉·马克格拉恩","马克格拉恩的动机","为什么找回储肉箱"}},["9ce729b1"]={q="马克格拉恩的干肉是什么？",a="那是图德拉·马克格拉恩专门为熬过山中寒冬而腌制的大量鹿肉和其他野味。他把肉锁在一个加固的瑟银箱里，免得觅食的熊闻到气味找来，幸好这箱子也足够结实，连冰须都没能撕开。",al={"马克格拉恩的干肉","马克格拉恩的干肉是什么","马克格拉恩储肉箱里的东西"}}},fp="30,181,32.217.0,18.290.0,23.153.0,33.141.0,46.118.0,26.128.0,57.107.0,34.116.0"}
P.entries["quest:3120"] = {n="绿色符记",s="绿色符记是一份送达幽影谷新觉醒的暗夜精灵德鲁伊手中的书面传唤。管理员伊尔萨莱恩会将其转交给他们，指引这些初出茅庐的变形者前往奥达希尔的树枝间寻找玛丹特·硬木。它标志着德鲁伊正式开始学习自然与翡翠梦境的奥秘。",h="绿色符记是一份送达幽影谷新觉醒的暗夜精灵德鲁伊手中的书面传唤。管理员伊尔萨莱恩会将其转交给他们，指引这些初出茅庐的变形者前往奥达希尔的树枝间寻找玛丹特·硬木。它标志着德鲁伊正式开始学习自然与翡翠梦境的奥秘。",kw={"奥达希尔","德鲁伊训练师","翡翠梦境","ilthalaine","玛丹特·硬木","幽影谷","绿色符记"},ang={["class:Druid"]="这个任务代表了你正式加入塞纳里奥议会，在玛丹特·硬木的教导下，开启了通往理解翡翠梦境的漫长道路。",["race:NightElf"]="德鲁伊教义深深植根于暗夜精灵文化之中；在奥达希尔出示这枚符记，标志着新手踏入这一古老传统的第一步。"},sec={{t="树枝的召唤",b="一旦一位年轻的暗夜精灵在维持幽影谷的当地平衡方面展现出潜力，就需要接受正式的入会仪式。管理员伊尔萨莱恩通过一名信使收到绿色符记，并将其委托给这位新手。这枚小小的信物象征着奥达希尔的塞纳里奥议会已经注意到了他们，并邀请这位年轻的德鲁伊正式开始他们的训练。"},{t="共融与梦境",b="在奥达希尔内向玛丹特·硬木出示符记后，新手便会被接纳进入组织。尽管与翡翠梦境进行更深层次的共融以及掌握动物形态尚需时日，但玛丹特确立了他作为他们第一位导师的地位，负责教导他们如何解读自然的灵魂并引导原始的林地之力。"}},faq={{q="什么是绿色符记？",a="这是一份由管理员伊尔萨莱恩代玛丹特·硬木传递的铭文传唤，召集德鲁伊新手前往奥达希尔开始他们的正式训练。",al={"绿色符记物品","这是什么符记","德鲁伊符记"}},{q="我该把绿色符记带给谁？",a="把它交给玛丹特·硬木，他是驻扎在幽影谷中心、奥达希尔巨型瘤树内的德鲁伊训练师。",al={"玛丹特在哪里","上交绿色符记","我该去哪里"}},{q="为什么玛丹特会提到翡翠梦境？",a="德鲁伊通过漫长的沉睡恍惚，从翡翠梦境中汲取了他们大部分的力量与智慧。虽然新手还未准备好自由漫游翡翠梦境，但玛丹特将其作为他们最终将要学习的基础奥秘引入。",al={"为什么是翡翠梦境","玛丹特的梦境对话","德鲁伊恍惚"}},{q="是谁把符记送给伊尔萨莱恩的？",a="玛丹特·硬木派出的信使将符记送达给了管理员伊尔萨莱恩，以便直接交到这位有前途的年轻德鲁伊手中。",al={"谁发送了符记","符记信使"}},{q="出示符记后会发生什么？",a="玛丹特·硬木将成为你在幽影谷的主要导师，让你能在力量增长的同时学习最早期的德鲁伊法术和魔法技巧。",al={"接下来我学什么","绿色符记之后"}},{q="非德鲁伊玩家可以接到这个任务吗？",a="不能。绿色符记专供在幽影谷开启旅程的暗夜精灵德鲁伊使用。其他职业会收到各自职业训练师发出的独特传唤。",al={"这是德鲁伊专属吗","谁会获得绿色符记"}}},fp="13,239,20.315.0,23.302.0,26.176.0,34.138.0,43.198.0,34.144.0,40.144.0,34.154.0"}
P.entries["quest:3121"] = {n="奇怪的要求",s="巫医尤克里需要一份奥格瑞玛的尼鲁·火刃调制好的药剂。尤克里交给你一颗干缩的头颅，作为换取草药报酬许诺给尼鲁的，并让你前往奥格瑞玛的大断崖把它交给尼鲁。",h="巫医尤克里需要一份奥格瑞玛的尼鲁·火刃调制好的药剂。尤克里交给你一颗干缩的头颅，作为换取草药报酬许诺给尼鲁的，并让你前往奥格瑞玛的大断崖把它交给尼鲁。",kw={"一个奇怪的要求","暗影裂口","菲拉斯","尼鲁·火刃","奥格瑞玛","干缩的头颅","巫医尤克里"},sec={{t="许诺的报酬",b="巫医尤克里说，奥格瑞玛的尼鲁·火刃手头上有他在菲拉斯开始行动所需的东西：一种他还不愿解释其用途的药剂。尤克里给了你一颗干缩的头颅，以此作为换取草药报酬许诺给尼鲁的物品。这原本是尤克里在森林里偶遇的某个可怜矮人的头颅。你可以在大断崖找到尼鲁。"},{t="尼鲁的草药",b="尼鲁·火刃一直在等尤克里派人送来这件东西，他将为尤克里的实验准备的草药混合物交给了你。"}},faq={{q="谁给予了“奇怪的要求”任务？",a="巫医尤克里，他让你带一颗干缩的头颅去奥格瑞玛。",al={"谁给予了奇怪的要求","谁开启了这个任务","奇怪的要求任务给予者"}},{q="尼鲁·火刃在哪里？",a="在奥格瑞玛的大断崖。",al={"尼鲁·火刃在哪里","我该去哪里","干缩的头颅交付地点"}},{q="那颗干缩的头颅是谁的？",a="尤克里称那是他在森林里偶遇的某个可怜矮人的头颅。",al={"这颗头颅是谁的","干缩的头颅身份","那个矮人是谁"}},{q="为什么尤克里要给尼鲁一颗干缩的头颅？",a="尤克里承诺过用它换取草药，并且他需要尼鲁调制好的药剂。",al={"为什么尼鲁想要这颗头颅","尼鲁·火刃交易"}},{q="“奇怪的要求”之后是什么？",a="这个任务线接下来是“回到巫医尤克里身边”。",al={"接下来是什么","奇怪的要求之后的下一个任务"}}},fp="17,72,18.320.0,13.134.1,28.64.0,25.56.0,32.69.0,46.105.0,31.55.0"}
P.entries["quest:3122"] = {n="向巫医尤克里回复",s="随着在“一个奇怪的请求”中交付了缩小的头颅，尼鲁·火刃将草药交给你，并要求你将其带给位于菲拉斯的巫医尤克里，同时转告他，尼鲁对这个头颅很满意。",h="随着在“一个奇怪的请求”中交付了缩小的头颅，尼鲁·火刃将草药交给你，并要求你将其带给位于菲拉斯的巫医尤克里，同时转告他，尼鲁对这个头颅很满意。",kw={"菲拉斯","草药袋","穆塞克容器","缩小的头颅","巫医尤克里"},sec={{t="草药的去向",b="在“一个奇怪的请求”之后，尼鲁·火刃给了你一袋给巫医尤克里的草药。他还要求你告诉尤克里，尼鲁对那个缩小的头颅很满意。这袋草药是要带给菲拉斯的尤克里的。"},{t="仪式开始",b="尤克里说这些草药正是准备穆塞克容器所需要的，并希望他最新的咒语能像他预期的那样强大。他让你等一会儿，他要进行仪式并使用这些草药。"}},faq={{q="谁把草药给了巫医尤克里？",a="尼鲁·火刃，就是你把缩小头颅带给他的那个人。",al={"任务起始点","谁给了草药"}},{q="这些草药要送到哪里？",a="送到位于菲拉斯的巫医尤克里那里。",al={"这是什么草药","我应该把草药袋带到哪里"}},{q="尼鲁对那个缩小的头颅满意吗？",a="是的。尼鲁对这个头颅很满意，并让你转告尤克里。",al={"尼鲁喜欢那个头颅吗","尼鲁缩小头颅交易"}}},fp="29,124,17.168.0,17.226.1,43.74.0,22.47.0,41.75.0"}
P.entries["quest:3123"] = {n="测试容器",s="在回到巫医尤克里处后，巫医尤克里称这是对刚刚进行的仪式以及你自身能力的考验。你被给予了一个可以缩小并捕获生物的容器，并被派往辛特兰用它捕获十只枭兽，然后将它们带回菲拉斯交给尤克里。",h="在回到巫医尤克里处后，巫医尤克里称这是对刚刚进行的仪式以及你自身能力的考验。你被给予了一个可以缩小并捕获生物的容器，并被派往辛特兰用它捕获十只枭兽，然后将它们带回菲拉斯交给尤克里。",kw={"艾露恩","菲拉斯","辛特兰","穆塞克","枭兽","尤克里","容器"},sec={{t="辛特兰的容器",b="巫医尤克里称这是一场考验，既是对刚刚完成的仪式的考验，也是对你自身能力的考验。你收到的容器可以将生物缩小并将其困在其中。你前往辛特兰寻找枭兽，这种生物曾是暗夜精灵女神艾露恩的宠物。尤克里指明这些凶猛、原始且野蛮的枭兽就是你的猎物。你必须击败十只，并在它们的灵魂消散前将其缩小放入容器中。十只枭兽连同容器，一起带回菲拉斯交给尤克里。"},{t="后续",b="尤克里解释说，当一个生物暴力死去时，它的穆塞克可能会逃脱并寻求复仇。像你刚才那样将倒下的生物缩小，可以防止穆塞克逃走，尤克里现在说它可以随意使用了。"}},faq={{q="谁发布了“测试容器”任务？",a="巫医尤克里，他将容器交给你。",al={"测试容器任务发布者","谁发布测试容器"}},{q="枭兽在哪里？",a="尤克里派你去辛特兰寻找它们。",al={"哪里找到枭兽","枭兽位置"}},{q="目标生物是什么？",a="被称为枭兽的凶猛、原始或野蛮的鸟兽。需要十只。",al={"要杀哪种枭兽","测试容器目标"}},{q="枭兽和艾露恩之间有什么联系？",a="尤克里说，枭兽曾经是暗夜精灵女神艾露恩的宠物。",al={"枭兽与艾露恩传说","为什么是枭兽"}},{q="这个容器有什么作用？",a="它能让你将倒下的生物缩小并困住，这样它的灵魂就无法逃脱。",al={"穆塞克容器如何工作","容器力量"}},{q="“测试容器”之后是什么？",a="任务线接下来是“角鹰兽穆塞克”。",al={"测试容器后续任务","测试容器之后做什么"}}},fp="18,171,28.432.0,9.242.1,29.61.0,22.52.0,32.82.0,47.75.0,23.95.0,32.43.0"}
P.entries["quest:3124"] = {n="角鹰兽灵魂精华",s="在你通过了缪塞克容器的试炼后，巫医尤克里要你去处理另一种生物。你需要立刻杀掉高原荒野的碎羽角鹰兽，并将它们缩小装入容器中，以便保存它们的缪塞克。",h="在你通过了缪塞克容器的试炼后，巫医尤克里要你去处理另一种生物。你需要立刻杀掉高原荒野的碎羽角鹰兽，并将它们缩小装入容器中，以便保存它们的缪塞克。",kw={"菲拉斯","碎羽","高原荒野","角鹰兽缪塞克","缪塞克容器","巫医尤克里"},sec={{t="忠诚的伙伴",b="巫医尤克里认为你值得信赖，并将容器交给了你，现在他想要另一种生物的灵魂。角鹰兽是暗夜精灵的老伙伴，它们的灵魂忠诚而坚定。你需要杀掉十只任意种类的碎羽角鹰兽，并用容器迅速将它们缩小捕获，以保存它们的缪塞克。尤克里说它们就在营地南边的高原荒野中。"},{t="尤克里的警告",b="尤克里说，如果被杀死的动物的缪塞克逃逸了，它可能会化身为更强大的生物，到那时它的复仇将让你永无宁日。尤克里称这项工作很危险，并称赞你完成得很好。"}},faq={{q="是谁派你去捕获角鹰兽的？",a="巫医尤克里。在完成“测试容器”后，你才会接到这个任务。",al={"角鹰兽缪塞克任务发布者","谁提供角鹰兽缪塞克任务","哪里接角鹰兽缪塞克任务"}},{q="碎羽角鹰兽在哪里？",a="它们位于高原荒野，尤克里说就在营地的南边。",al={"碎羽角鹰兽在哪里","菲拉斯角鹰兽位置","在菲拉斯哪里找角鹰兽"}},{q="为什么巫医尤克里想要角鹰兽的灵魂？",a="尤克里提到角鹰兽是暗夜精灵的老伙伴，它们的灵魂忠诚且坚定。他的目的是为了保存它们的缪塞克。",al={"为什么要找角鹰兽","为什么要捕获角鹰兽缪塞克","尤克里对于角鹰兽的理由"}},{q="如何捕获缪塞克？",a="杀掉一只碎羽角鹰兽，然后迅速用缪塞克容器将它缩小并捕获。任务需要十只，任意类型皆可。",al={"如何使用缪塞克容器","如何获得角鹰兽缪塞克","捕获碎羽缪塞克"}},{q="这个任务链的前一步是什么？",a="测试容器，在那里你证明了自己值得信赖，并掌握了使用缪塞克容器的方法。",al={"角鹰兽缪塞克前置条件","角鹰兽缪塞克的前一个任务","角鹰兽缪塞克的前置任务"}}},fp="17,138,16.400.0,16.214.1,37.78.0,44.84.0,53.138.0,27.118.0,41.102.0"}
P.entries["quest:3125"] = {n="精灵龙灵魂精华",s="在收集了角鹰兽之灵后，巫医尤克里又盯上了小精龙的灵魂。你被派往西方去猎杀小精龙和精灵龙，并夺取它们力量的源泉。",h="在收集了角鹰兽之灵后，巫医尤克里又盯上了小精龙的灵魂。你被派往西方去猎杀小精龙和精灵龙，并夺取它们力量的源泉。",kw={"小精龙穆希克","菲拉斯","角鹰兽穆希克","部落","穆希克容器","小精龙","精灵龙","树人穆希克","巫医尤克里"},sec={{t="脆弱的外表，强大的灵魂",b="尤克里指出，小精龙看起来很脆弱，但它们的灵魂才是真正的珍宝。它们一直是暗夜精灵的盟友，尤克里希望部落也能分享那份力量。尤克里给了你一个穆希克容器，并派你向西走，去击杀八只小精龙或精灵龙，然后用容器缩小并捕获每一只倒下的小精龙。"},{t="回到尤克里身边",b="当你带着捕获的灵魂回来时，尤克里向你表示感谢，并说现在部落可以汲取小精龙的精神力量了。尤克里还希望你能再帮他完成一项工作。"}},faq={{q="为什么巫医尤克里想要小精龙的灵魂？",a="尤克里说，小精龙虽然看起来脆弱，但却拥有强大的灵魂，而且它们一直是暗夜精灵的盟友。尤克里希望部落也能从这种力量中受益。",al={"为什么需要小精龙","小精龙穆希克的作用","为什么要杀小精龙"}},{q="在哪里可以找到小精龙？",a="尤克里说它们就在他所处位置的西方。",al={"小精龙在哪里","小精龙的位置","菲拉斯小精龙位置"}},{q="什么生物能提供这种穆希克？",a="小精龙和精灵龙。需要击杀并捕获其中的八只。",al={"哪些怪物会掉落穆希克","小精龙穆希克杀什么怪物","小精龙穆希克目标"}},{q="必须对倒下的生物做什么？",a="在每一只倒下的小精龙身上使用穆希克容器，将其缩小并捕获其中的穆希克。",al={"如何获得小精龙穆希克","穆希克容器如何使用","捕获穆希克"}},{q="这一步在尤克里的任务中排在什么位置？",a="它在角鹰兽穆希克之后，后面紧跟着树人穆希克任务。",al={"这个任务前置是什么","穆希克任务链顺序","小精龙穆希克之后是什么"}}},fp="20,152,28.356.0,21.182.1,56.177.0,38.51.0,35.97.0,42.87.0,49.62.0"}
P.entries["quest:3126"] = {n="树人灵魂精华",s="巫医尤克里的下一个目标是 游荡的森林漫游者，这些树人在森林中缓缓游荡。精龙之后，你受命去寻找其中的三个。",h="巫医尤克里的下一个目标是 游荡的森林漫游者，这些树人在森林中缓缓游荡。精龙之后，你受命去寻找其中的三个。",kw={"菲拉斯","灵魂精华容器","树人灵魂精华","树人","尤克里","游荡的森林漫步者"},sec={{t="缓慢的保护者",b="尤克里说，暗夜精灵招募了树人作为盟友，共同对抗部落。它们行动缓慢，但尤克里认为它们作为保护者的作用毋庸置疑，并计划利用这股力量为部落谋利。"},{t="三个 森林漫游者",b="尤克里要你找到并杀死三个 游荡的森林漫游者，然后用 灵魂容器 将每个倒下的树人缩小并捕获。"},{t="尤克里的评判",b="你回来后，尤克里向你道谢，并表示 灵魂 的收集工作已接近完成。"}},faq={{q="是谁派冒险者去对付树人的？",a="巫医尤克里，他在精龙的任务之后紧接着提出了这个要求。",al={"谁提供 树人灵魂精华","树人灵魂精华 任务给予者","尤克里树人任务"}},{q="巫医尤克里为什么想要树人的灵魂精华？",a="尤克里说，暗夜精灵招募了树人作为盟友，共同对抗部落，他想利用它们的守护力量为部落谋利。",al={"为什么杀死 森林漫游者","为什么收集树人 灵魂精华","尤克里对付树人的动机"}},{q="树人灵魂精华要求寻找什么生物？",a="在森林中游荡的 游荡的森林漫游者。需要找到三个。",al={"要杀哪些树人","游荡的森林漫游者","树人灵魂精华 目标"}},{q="如何捕获树人？",a="在一个 游荡的森林漫游者 倒下后，使用 灵魂精华容器 将它缩小并捕获。",al={"如何使用 灵魂精华容器","捕获 森林漫游者","缩小树人"}},{q="树人灵魂精华在尤克里的任务中排在什么位置？",a="它在精灵龙灵魂精华之后，山岭巨人灵魂精华则在它之后。",al={"树人灵魂精华 任务链","精灵龙灵魂精华 之后是什么","树人灵魂精华 的后续任务"}}},fp="13,144,15.196.0,20.136.0,16.101.1,40.78.0,48.128.0,47.67.0,29.85.0,53.77.0"}
P.entries["quest:3127"] = {n="山岭巨人灵魂精华",s="巫医尤克里称这是最后一项任务，并派你前往西北方寻找最后的敌人：山岭巨人。尤克里渴望利用它们巨大的体型和力量。",h="巫医尤克里称这是最后一项任务，并派你前往西北方寻找最后的敌人：山岭巨人。尤克里渴望利用它们巨大的体型和力量。",kw={"燃烧军团","峭壁巨人","菲拉斯","踏地者","山岭巨人穆瑟克","穆瑟克容器","树妖的穆瑟克","巫医尤克里"},sec={{t="岩石地面的巨人",b="据巫医尤克里所说，当燃烧军团降临艾泽拉斯时，山岭巨人从群山中走下来协助暗夜精灵。它们那庞大的身躯和踏在岩石地面上引起的震颤非常容易辨认。尤克里渴望利用那种规模的力量。尤克里要你击倒七个踏地者或峭壁巨人，并用穆瑟克容器将它们缩小并捕获。"},{t="尤克里的吹嘘",b="当你返回时，尤克里谈到了现在所收集之物的可能性。尤克里声称，利用你一路上收集的材料，它能够将这些生物的灵魂永久地禁锢在它想要的任何东西中。"}},faq={{q="谁要求获得山岭巨人的穆瑟克？",a="巫医尤克里，它称这是对你的最后要求。",al={"任务发布者","谁发布山岭巨人穆瑟克任务","尤克里任务"}},{q="山岭巨人在哪里？",a="尤克里派你向西北方向行进，在岩石地形中寻找它们。",al={"山岭巨人位置","踏地者在哪里","峭壁巨人位置"}},{q="为什么山岭巨人会在这里？",a="根据尤克里的说法，当燃烧军团降临到这个世界上时，它们从群山中走下来协助暗夜精灵。",al={"巨人为什么在这里","菲拉斯山岭巨人背景"}},{q="哪些生物提供所需的穆瑟克？",a="踏地者和峭壁巨人。需要七个，穆瑟克容器会将每一个倒下的巨人缩小并捕获。",al={"为了穆瑟克我需要杀什么","哪些巨人算数"}},{q="这个任务在序列中排在什么前面？",a="它紧随“树妖的穆瑟克”之后，而“灵魂武器”列在它之后。",al={"前置任务","穆瑟克任务链顺序"}}},fp="21,108,26.366.0,14.175.1,41.92.0,38.88.0,29.144.0,44.129.0,39.74.0"}
P.entries["quest:3128"] = {n="天然材料",s="位于莫沙彻营地的巫医尤克里需要收集材料来完成一项尝试，这些材料需要与其他试炼一起收集：破碎的圆木、结痂的矿石、坚韧的筋腱和金属碎片，它们分别来自树人、山岭巨人、精龙、枭兽和角鹰兽。",h="位于莫沙彻营地的巫医尤克里需要收集材料来完成一项尝试，这些材料需要与其他试炼一起收集：破碎的圆木、结痂的矿石、坚韧的筋腱和金属碎片，它们分别来自树人、山岭巨人、精龙、枭兽和角鹰兽。",kw={"莫沙彻营地","结痂的矿石","菲拉斯","金属碎片","穆伊斯克","自然材料","坚韧的筋腱","破碎的圆木","辛特兰","巫医尤克里"},sec={{t="为巫医收集材料",b="在你回到巫医尤克里身边后，还有一份后续的材料清单等着你，需要与其他试炼一起收集。需要从菲拉斯的树人身上获取两根破碎的圆木。六块结痂的矿石可以在西部的山岭巨人与精龙身上找到。二十块坚韧的筋腱来自于辛特兰的枭兽或菲拉斯的角鹰兽。大量的金属碎片（总共四十个）可以从上述任意生物身上获得。"},{t="尤克里的裁决",b="当带回材料后，尤克里感到很高兴。将它们与穆伊斯克结合，应该能得到预期的结果。"}},faq={{q="谁在请求这些自然材料？",a="莫沙彻营地的巫医尤克里。",al={"自然材料任务发布者","自然材料任务起始地点"}},{q="哪些生物拥有破碎的圆木？",a="菲拉斯的树人；需要两根破碎的圆木。",al={"破碎的圆木获取地点","谁掉落破碎的圆木","破碎的圆木来源"}},{q="哪里可以收集到结痂的矿石？",a="西部的山岭巨人和精龙携带着它们；需要六块。",al={"如何获得结痂的矿石","结痂的矿石来源","谁掉落结痂的矿石"}},{q="哪些野兽提供坚韧的筋腱？",a="辛特兰的枭兽或菲拉斯的角鹰兽；需要二十块。",al={"坚韧的筋腱掉落","在哪里寻找坚韧的筋腱","谁拥有坚韧的筋腱"}},{q="金属碎片来自哪里？",a="四十个碎片来自上述列出的任何生物：树人、山岭巨人、精龙、枭兽和角鹰兽。",al={"金属碎片来源","如何获得金属碎片","谁掉落金属碎片"}},{q="在此任务之前有什么要求？",a="该任务紧接“回到巫医尤克里”之后。",al={"自然材料前置任务","自然材料前续任务","什么任务指引向自然材料"}}},fp="17,206,30.401.0,16.134.1,37.50.0,40.59.0,41.86.0,41.109.0,38.110.0,30.51.0"}
P.entries["quest:3129"] = {n="灵魂武器",s="巫医尤克里如今已备齐所需的一切，还有你捕获的灵魂。将它们束缚在武器中是一项艰难的工作，因此尤克里请你稍等片刻，待准备工作完成。",h="巫医尤克里如今已备齐所需的一切，还有你捕获的灵魂。将它们束缚在武器中是一项艰难的工作，因此尤克里请你稍等片刻，待准备工作完成。",kw={"菲拉斯","灵魂精华","灵魂武器","巫医尤克里"},sec={{t="片刻耐心",b="尤克里坦言，将灵魂注入武器十分费力。如今，所需的材料和你捕获的灵魂都已备齐，尤克里可以动手了，并请你等候武器制备完成。"},{t="等候结束之时",b="尤克里回来让你挑选武器，并告诉你，捕获的生物灵魂已被永久封入其中。如今，你可以将它们的能量化为己用。"}},faq={{q="灵魂武器由谁交付？",a="巫医尤克里，也就是派你去收集灵魂精华的那位巫医，这项任务接在山岭巨人灵魂精华之后。",al={"谁交付灵魂武器","灵魂武器任务交付者","尤克里任务"}},{q="巫医尤克里在这一步中做些什么？",a="尤克里着手将捕获的灵魂精华注入武器，据说这个过程十分艰难，因此请你稍候，等待准备工作完成。",al={"灵魂武器中发生什么","尤克里做什么"}},{q="尤克里开始之前需要什么？",a="尤克里说，所需材料已经备齐，你捕获的灵魂也已到手，可以开始了。",al={"灵魂武器所需条件","灵魂武器前置条件"}}},fp="17,122,19.171.0,18.168.1,32.82.0,50.136.0,39.84.0"}
P.entries["quest:313"] = {n="灰色洞穴",s="在卡拉诺斯附近的钢架补给站，驾驶员迪恩·石轮派你向西前往灰色洞穴猎杀雪怪。它们厚实的毛皮将为他的攻城坦克Trollplow保暖。",h="在卡拉诺斯附近的钢架补给站，驾驶员迪恩·石轮派你向西前往灰色洞穴猎杀雪怪。它们厚实的毛皮将为他的攻城坦克Trollplow保暖。",kw={"丹莫罗","灰色洞穴","卡拉诺斯","驾驶员迪恩·石轮","特罗普","雪怪","雪怪的鬃毛"},ang={["profession:Engineering"]="如果你欣赏矮人的攻城器械工艺，就会知道重型机械需要巧妙的办法，才能在零度以下的天气里保暖。",["race:Dwarf"]="对于年轻的巡山人或铁炉堡冒险者来说，迎战灰色洞穴的雪怪是当地的一项成人考验。",["race:Gnome"]="与卡拉诺斯周围的矮人比邻而居，意味着你可以帮助装备铁炉堡的重型装甲战车。"},sec={{t="胆识的考验",b="石轮会先考验初来乍到的人，才放心把工作交给他们。在寒冷的山间驾驶庞大的攻城坦克并非易事。这需要钢铁般的意志和强健的体魄。去面对冰封山丘上的野兽，证明你两者兼备。"},{t="Trollplow内的暖意",b="丹莫罗的严寒侵入Trollplow狭窄的铁甲驾驶舱。石轮想用厚实的雪怪鬃毛，为坦克的甲板铺上一张温暖耐用的地毯。这场狩猎也能遏制当地野兽的数量。"}},faq={{q="驾驶员迪恩·石轮是谁？",a="驾驶员迪恩·石轮是一名矮人攻城坦克驾驶员，驻扎在丹莫罗的卡拉诺斯镇外。他驾驶着装甲战争机器巨魔碾压者，并以自己钢铁般的意志和机械技艺为傲。",al={"驾驶员迪恩·石轮","谁提供任务","石轮是谁"}},{q="灰色洞穴在哪里？",a="灰色洞穴位于卡拉诺斯正西方白雪覆盖的群山之中。丹莫罗凶猛的雪怪栖息在这些洞穴里。",al={"灰色洞穴位置","雪怪洞穴在哪","如何找到灰色洞穴"}},{q="石轮为什么需要雪怪鬃毛？",a="石轮想用雪怪毛皮，为巨魔碾压者内部的甲板铺上一张温暖的地毯。收集毛皮也能考验冒险者的勇气。",al={"为何需要雪怪鬃毛","鬃毛用途","鬃毛有什么用"}},{q="巨魔碾压者是什么？",a="巨魔碾压者是驾驶员迪恩·石轮的私人矮人攻城坦克。它的名字反映了铁炉堡矮人与周围峭壁间敌对的霜鬃巨魔之间的冲突。",al={"巨魔碾压者","石轮的坦克","巨魔碾压者是什么"}},{q="灰色洞穴里栖息着什么生物？",a="凶残的雪怪栖息在灰色洞穴中。这些形似猿猴的野兽生性狂暴，原生于丹莫罗的积雪高地，会凶猛地捍卫自己的领地。",al={"灰色洞穴里的怪物","灰色洞穴里有什么生物"}},{q="雪怪会危及卡拉诺斯吗？",a="雪怪很少像霜鬃巨魔那样组织进攻。然而，它们生性凶暴，又出没于主干道附近，给旅人和当地商贩带来了危险。",al={"雪怪是否构成威胁","雪怪的危险"}}},fx={["9edb896b"]={q="雪怪的鬃毛有什么用？",a="驾驶员迪恩·石轮想要灰色洞穴里雪怪的浓密长鬃，用来享受一种很实在的矮人奢侈生活：布置内饰。在丹莫罗刺骨的寒风中驾驶巨魔碾压者这样庞大的攻城坦克，脚下的金属甲板总是冰冷彻骨。石轮打算把收集来的鬃毛缝成一张厚实温暖的地毯，让巨魔碾压者的驾驶舱在漫长的巡逻途中舒适许多。",al={"雪怪的鬃毛用途","雪怪的鬃毛有什么用","为什么要雪怪的鬃毛"}},["72b90979"]={q="驾驶员迪恩·石轮为什么派你去，而不自己收集鬃毛？",a="石轮是一名攻城坦克驾驶员，要让巨魔碾压者这样的钢铁机器保养妥当，随时准备保卫卡拉诺斯，就得投入全部精力。在狭窄冰冷的洞穴通道里猎杀敏捷凶猛的雪怪，并不是庞大战争机器擅长的事。石轮也把这项任务当作一次公开的挑战，看看你是否具备丹莫罗守卫者所需的毅力、胆识与勇气。",al={"石轮为什么选我","石轮为什么需要帮助","为什么不亲自收集鬃毛"}}},fp="16,162,14.246.0,30.212.0,23.192.0,34.127.0,38.128.0,18.177.0,48.148.0,39.161.0"}
P.entries["quest:3130"] = {n="憎世纳迦之战",s="你汇报完毕后，珊蒂斯·羽月将军派你去见羽月要塞中的副官拉托尼库斯·月矛。珊蒂斯希望全力出兵对付纳迦，但不愿让要塞暴露在部落或更可怕的威胁面前。",h="你汇报完毕后，珊蒂斯·羽月将军派你去见羽月要塞中的副官拉托尼库斯·月矛。珊蒂斯希望全力出兵对付纳迦，但不愿让要塞暴露在部落或更可怕的威胁面前。",kw={"对抗憎世","羽月要塞","菲拉斯","憎世","部落","拉托尼库斯·月矛","纳迦","珊蒂斯·羽月"},sec={{t="珊蒂斯权衡风险",b="珊蒂斯·羽月将军派你去见副官拉托尼库斯·月矛，他一直在密切监视纳迦的兵力动向。珊蒂斯将评估此地与纳迦有关的整体局势。虽然她很想全力出兵对付它们，但让要塞面临部落或更可怕的敌人的直接进攻，似乎并不妥当。拉托尼库斯在羽月要塞等你。"},{t="拉托尼库斯的打算",b="拉托尼库斯·月矛说，将军已命他正面应对纳迦。计划分为两部分：削减它们的数量，削弱它们的指挥力量，并查明它们在废墟中的活动。有了你的帮助，就能在确保要塞安全的同时，遏制它们的势力。"}},faq={{q="珊蒂斯·羽月为什么派你去见拉托尼库斯？",a="如果全力出兵对付纳迦会让羽月要塞暴露在部落或更可怕的威胁面前，珊蒂斯就不会这样做。因此，将军指引你去见一直监视纳迦的副官拉托尼库斯。",al={"为什么与拉托尼库斯交谈","为什么找拉托尼库斯·月矛","羽月要塞引荐"}},{q="拉托尼库斯·月矛在哪里？",a="在羽月要塞，珊蒂斯派你去那里向他报到。",al={"拉托尼库斯位置","拉托尼库斯在哪里","寻找拉托尼库斯·月矛"}},{q="这项任务之前是什么？",a="返回羽月要塞，之后珊蒂斯会派你去见拉托尼库斯。",al={"憎世纳迦前置任务","上一个任务","憎世任务链起点"}}},fp="21,90,24.362.0,23.285.1,53.202.0,38.93.0,33.78.0"}
P.entries["quest:314"] = {n="保护牲畜",s="在冻石农场，鲁德拉·冻石担心瓦加什会夺走更多珍贵的山羊。他请求路过的战士保护羊群，并带回这头猛兽已死的证据。",h="在冻石农场，鲁德拉·冻石担心瓦加什会夺走更多珍贵的山羊。他请求路过的战士保护羊群，并带回这头猛兽已死的证据。",kw={"冻石农场","丹莫罗","铁炉堡","山羊","保护羊群","鲁德拉·冻石","瓦加什","维隆·冻石"},ang={["class:Hunter"]="身为猎人，在丹莫罗的积雪中追踪瓦加什，找到他在山间的巢穴，是对你技艺的考验。",["faction:Alliance"]="身为联盟战士，你可以帮助乡间农户，而王座厅的军团则在东部王国各地支援联盟的行动。",["race:Dwarf"]="身为矮人，你可以帮助保护这些山羊，它们驮着你的同胞奔赴卡兹莫丹各地的战场。"},sec={{t="农场的威胁",b="瓦加什已经从冻石农场夺走了两只珍贵的山羊。这座农场为铜须矮人提供坐骑和役畜，羊群也支撑着丹莫罗的乡村经济。瓦加什在农场上方的峭壁间猎食当地的牲畜。"},{t="捉襟见肘的防御",b="铁炉堡的兵力分散在王国各地，在遥远的边境支援联盟。山脊上没有军队巡逻，鲁德拉·冻石便请求独立行动的战士猎杀瓦加什。他想要这头猛兽的一颗致命獠牙作为证据。"}},faq={{q="瓦加什是谁？",a="瓦加什是一头危险的猛兽，潜伏在冻石农场上方积雪的山脊间。他力大凶残，贪食无度，威胁着农场珍贵的山羊和丹莫罗东部的旅人。",al={"瓦加什是什么","瓦加什怪物","瓦加什背景故事"}},{q="在哪里能找到瓦加什？",a="瓦加什的巢穴位于冻石农场上方的高处峭壁间，是一个覆满积雪的洞穴。爬上农舍后方松树外的雪坡，就能到达洞口。",al={"瓦加什位置","瓦加什在哪里","寻找瓦加什"}},{q="铁炉堡的卫兵为什么不来处理？",a="铁炉堡的兵力分散在遥远的驻地和联盟的各处战场。冻石农场附近没有军队可以援助，因此那里的饲养者必须自行保卫农舍，或寻求有能力的战士相助。",al={"为什么没有卫兵","铁炉堡军队在哪里","为什么帮助冻石"}},{q="鲁德拉提到的维隆是谁？",a="维隆·冻石在农场为铜须部族繁育、训练和照料山羊坐骑。鲁德拉说，等到那头一直猎食他们珍贵牲畜的猛兽被除掉，维隆就能松一口气了。",al={"维隆是谁","维隆·冻石","维隆"}},{q="为什么需要击杀证据？",a="鲁德拉想要瓦加什的獠牙，以此证明死去的是那头威胁羊群的怪物，而非山坡上某头普通的游荡野兽。",al={"为什么要瓦加什的獠牙","瓦加什的牙齿","证据是什么"}},{q="山羊对丹莫罗有什么重要意义？",a="山羊体格强健，在卡兹莫丹冰冷崎岖的土地上也能稳步行走。它们为矮人提供畜力、羊毛和骑兵坐骑。",al={"山羊为什么重要","冻石山羊用途","矮人山羊背景故事"}}},fx={["81b569d0"]={q="鲁德拉·冻石为什么想办成这件事？",a="鲁德拉·冻石正在保卫一家人的生计。冻石农场繁育并照料着强壮的山羊，它们在丹莫罗和铁炉堡备受珍视。瓦加什开始在农场附近游荡，趁着夜色潜入，屠杀牲畜。一夜之间就有两只珍贵的山羊被拖走，农场经不起这头凶猛掠食者的持续袭击。",al={"鲁德拉为什么想杀死瓦加什","鲁德拉·冻石的动机","为什么杀死瓦加什"}},["34abe682"]={q="瓦加什的牙齿有什么用？",a="这颗牙齿是无可辩驳的实物证据，能证明那头令人畏惧的野兽确实已被杀死。瓦加什在农场一带以体型庞大、性情凶猛而恶名远扬，鲁德拉·冻石必须彻底确认这头在上方峭壁间徘徊的掠食者已经死去，她和家人才能放心照料剩下的羊群。",al={"为什么需要瓦加什的牙齿","瓦加什的牙齿用途","瓦加什的牙齿"}}},fp="19,175,21.251.0,17.255.0,14.189.0,26.169.0,47.199.0,32.179.0,34.133.0,47.154.0"}
P.entries["quest:315"] = {n="完美烈酒",s="烈酒村的雷杰德·麦酒决心酿造出终极的矮人烈酒，他将家族的酿酒传统与异域风味的当地原料相结合。为了完善他的实验性配方，他正在寻找闪光草，这是一种极其辛辣的植物，只由敌对的霜鬃巨魔在闪光岭的顶部种植。胆大的旅行者被派遣进入巨魔营地，直接从他们的部落篮筐中偷取这种草药。",h="烈酒村的雷杰德·麦酒决心酿造出终极的矮人烈酒，他将家族的酿酒传统与异域风味的当地原料相结合。为了完善他的实验性配方，他正在寻找闪光草，这是一种极其辛辣的植物，只由敌对的霜鬃巨魔在闪光岭的顶部种植。胆大的旅行者被派遣进入巨...",kw={"烈酒村","丹莫罗","矮人酿酒","霜鬃巨魔","完美烈酒","雷杰德·麦酒","闪光岭","闪光草"},ang={["profession:Herbalism"]="虽然不是标准的制作草药，但这种抗寒的闪光草因其独特的植物学特性，成为了丹莫罗冰冷岩壁上一种引人入胜的新奇事物。",["race:Dwarf"]="对于铜须氏族来说，酿酒几乎是神圣的，而寻找一种异域野生草药来超越竞争对手的酒馆被认为是一项高尚的追求。"},sec={{t="酿酒师的野心",b="在烈酒村，酿酒不仅仅是一门手艺，更是一种生活方式，对麦酒家族来说尤其如此。雷杰德·麦酒坚信酿造出伟大的酒是他的天职，但要酿造出传说中的“完美烈酒”需要非传统的创新。雷杰德没有仅仅依靠标准的啤酒花、麦芽和山泉水，而是将目光投向了丹莫罗未受驯化的植物，试图赋予他的麦酒一种独特的刺激感。"},{t="闪光岭的巨魔草药",b="雷杰德觊觎的秘密配方是闪光草，这是一种耐寒植物，由东边闪光岭上的霜鬃巨魔种植。虽然霜鬃巨魔采集它主要是为了部落和神秘仪式，但矮人们除了知道它辛辣、独特的味道外，几乎没什么实际用途。这种草药直接从巨魔村庄的储存篮中抢来，成为了雷杰德最新、最大胆的发酵实验的核心原料。"}},faq={{q="什么是闪光草？",a="闪光草是一种独特的植物，由闪光岭上的霜鬃巨魔种植和收获。虽然巨魔主要在部落仪式中使用它，但雷杰德·麦酒试图测试其辛辣、独特的味道，将其作为矮人酿酒过程中一种非传统的调味剂。",al={"闪光草背景知识","闪光草有什么用","霜鬃巨魔植物"}},{q="闪光岭在哪里？",a="闪光岭位于丹莫罗北部积雪覆盖的高地上，烈酒村的东侧。它是当地霜鬃巨魔的加固营地，因此去那里进行任何草药采集活动都是进入敌方领地的危险之举。",al={"闪光岭位置","闪光岭在哪里","如何找到闪光岭"}},{q="雷杰德为什么要从霜鬃巨魔那里偷东西？",a="霜鬃巨魔垄断了丹莫罗的闪光草种植，矮人和巨魔之间的紧张关系使得和平贸易成为不可能。由于这些植物已经被收获并捆扎在他们营地的部落篮筐中，溜进去或杀进去抢夺是雷杰德唯一的选择。",al={"为什么要偷巨魔的东西","为什么要偷巨魔的篮子","雷杰德的巨魔计划"}},{q="雷杰德·麦酒是谁？",a="雷杰德·麦酒是一位居住在烈酒村的雄心勃勃的矮人酿酒师。正如他的家族姓氏所示，他致力于发现完美烈酒的配方，不断尝试新的口味和强效的野生原料。",al={"雷杰德是谁","雷杰德·麦酒","麦酒家族"}},{q="闪光草算是炼金药草吗？",a="不算。闪光草不是从野外采集点获得的炼金试剂。它是一种任务物品，储存在闪光岭上霜鬃巨魔营地的柳条篮和储物箱里。",al={"草药师可以采摘闪光草吗","闪光草是草药学吗","闪光草采集"}},{q="闪光草上交后会有什么用？",a="雷杰德将新采集来的闪光草直接投入烈酒村正在发酵的一批酒中，希望它独特的属性最终能让他酿造出他梦寐以求的完美配方。",al={"这种烈酒有效吗","雷杰德的酿造结果","闪光草啤酒"}}},fx={["3780a202"]={q="霜鬃巨魔是什么人？",a="霜鬃是冰霜巨魔的一个土著部族，世代居住在丹莫罗的雪山峭壁间。随着铁炉堡矮人不断扩张，他们被赶出了祖辈的猎场，因此对邻近的矮人怀有深深的敌意。他们在闪光岭等聚居地种植闪光草，用于部族仪式，并会竭力抵御任何闯入营地的人。",al={"霜鬃巨魔","闪光岭上的巨魔是谁","霜鬃部族"}}},fp="17,335,19.319.0,31.300.0,20.238.0,31.188.0,56.267.0,25.170.0,42.191.0,47.182.0"}
P.entries["quest:3161"] = {n="加兹瑞迪安",s="玛尔冯·瑞文斯克是一位科学家，骨子里也是位寻宝者。他需要三十件曾经生活在塔纳利斯的巨魔留下的饰品。玛尔冯给了你一个他自己发明的探测器来帮助你寻找它们。",h="玛尔冯·瑞文斯克是一位科学家，骨子里也是位寻宝者。他需要三十件曾经生活在塔纳利斯的巨魔留下的饰品。玛尔冯给了你一个他自己发明的探测器来帮助你寻找它们。",kw={"破碎石柱","探测器","东月废墟","加兹瑞迪安","加兹瑞拉","玛尔冯·瑞文斯克","南月废墟","塔纳利斯","巨魔"},sec={{t="多头蛇神的遗物",b="很久以前，巨魔占据了这片土地，他们制作了大量以加兹瑞拉——他们当作神来崇拜的多头蛇——为原型的饰品。玛尔冯·瑞文斯克将雕刻这些饰品的元素称为“加兹瑞迪安”，这个名字取自那位多头蛇神。玛尔冯已经找到了一些，他希望能有更多的来进行研究。"},{t="探测器",b="玛尔冯发明了一种能让寻找加兹瑞迪安变得简单的探测器，并将它交给了你。佩戴它即可开始搜寻。饰品在塔纳利斯的几乎任何地方都能找到，不过在破碎石柱、东月废墟和南月废墟附近最为密集。"}},faq={{q="玛尔冯·瑞文斯克是谁？",a="玛尔冯·瑞文斯克是塔纳利斯的一位科学家，骨子里也是位寻宝者。他研究古代巨魔制作的饰品。",al={"玛尔冯·瑞文斯克","谁给予加兹瑞迪安","任务发布者"}},{q="什么是加兹瑞迪安？",a="这是玛尔冯·瑞文斯克对巨魔的多头蛇饰品所用雕刻元素的命名，取自那位多头蛇神的名字。",al={"什么是加兹瑞迪安","加兹瑞迪安矿石","加兹瑞迪安材料"}},{q="加兹瑞拉是谁？",a="加兹瑞拉是古代巨魔当作神来崇拜的一头多头蛇。他们制作饰品时便是以它为原型的。",al={"加兹瑞拉神灵","多头蛇崇拜","谁是加兹瑞拉"}},{q="在哪里可以找到加兹瑞迪安饰品？",a="在塔纳利斯几乎任何地方，不过最集中的地方是在破碎石柱以及东月废墟和南月废墟周围。",al={"在哪里寻找加兹瑞迪安","加兹瑞迪安的最佳地点","加兹瑞迪安位置"}},{q="如何找到这些饰品？",a="玛尔冯专门发明了一种探测器。佩戴它即可开始搜寻。",al={"如何发现饰品","加兹瑞迪安探测器","寻找加兹瑞迪安"}}},fp="11,145,23.255.0,12.251.0,26.127.0,20.111.0,18.93.0,38.148.0,30.95.0"}
P.entries["quest:317"] = {n="贝尔丁的补给",s="在钢架补给站，驾驶员贝隆·风箱正为贝尔丁随铁炉堡的攻城坦克旅长期出征做准备。车组需要为旅途储备野猪肉和熊皮。",h="在钢架补给站，驾驶员贝隆·风箱正为贝尔丁随铁炉堡的攻城坦克旅长期出征做准备。车组需要为旅途储备野猪肉和熊皮。",kw={"熊皮","野猪肉","丹莫罗","灰色洞穴","贝尔丁","驾驶员贝隆·风箱","攻城坦克旅","钢架补给站"},ang={["faction:Alliance"]="身为联盟的一员，你帮助矮人的维修场与攻城坦克旅的装甲车组建立联系，让联盟的攻城机械保持运转。",["profession:Cooking"]="身为厨师，你可以利用野猪肉，丹莫罗的山地驻军也靠这种肉食维持补给。",["race:Dwarf"]="身为矮人，你帮助在卡兹莫丹机械场执行任务的攻城坦克旅车组获得食物与休息。",["race:Gnome"]="身为侏儒，你的帮助让矮人的攻城坦克旅在长期征战中保持补给充足。这支部队是流亡侏儒的盟友。"},sec={{t="为战车储备物资",b="工程大师贝尔丁·钢架正在卡拉诺斯郊外的钢架补给站调试攻城坦克。贝尔丁正为代表攻城坦克旅执行一次行动做准备。车组需要储备一个月的物资，以抵御丹莫罗零度以下的严寒。"},{t="雪原狩猎",b="贝尔丁·钢架正在贝尔丁的引擎盖下忙碌，因此贝隆·风箱无法离开战车去收集食物和保暖材料。灰色洞穴以南的雪原上有可供取肉的野猪，还有熊，熊皮可以铺在坦克的卧铺上保暖。"}},faq={{q="贝尔丁是什么？",a="贝尔丁是一辆攻城坦克，由矮人驾驶员贝隆·风箱操纵。它正在钢架补给站接受调试并补充物资，准备随铁炉堡的攻城坦克旅长期出征。",al={"贝尔丁","贝尔丁是谁","贝尔丁是什么","贝隆·风箱的坦克"}},{q="驾驶员贝隆·风箱是谁？",a="驾驶员贝隆·风箱绰号菲兹，是铁炉堡攻城坦克旅的一名矮人攻城坦克驾驶员。他的战车在钢架补给站接受调试期间，他负责为即将到来的任务筹备补给。",al={"驾驶员贝隆·风箱","贝隆·风箱","驾驶员贝隆·风箱是谁"}},{q="所需的补给可以在哪里收集？",a="灰色洞穴以南的雪原上栖息着野猪和熊，它们的肉可作食物，皮毛可作铺盖。",al={"野猪在哪里","熊在哪里","狩猎地点","丹莫罗野猪肉"}},{q="攻城坦克旅是什么？",a="攻城坦克旅是铁炉堡的攻城坦克驾驶员部队。该部队的重装甲战车，包括贝尔丁和巨魔碾压者，为矮人的防御和联盟的战役提供支援。",al={"攻城坦克旅"}},{q="这个任务接下来要去哪里？",a="为贝尔丁补足肉和皮毛后，驾驶员贝隆·风箱会派旅人向西前往烈酒村，获取艾沃沙酒。他用这种烈酒御寒，也将其用作坦克熔炉的应急燃料。",al={"下一个任务","贝尔丁的补给之后是什么","贝尔丁的补给后续任务"}},{q="攻城坦克为什么需要动物皮毛？",a="矮人和侏儒的蒸汽坦克在雪山中长期作战时，车内会变得冰冷透风。厚实的熊皮能让车组在长期远离营地时，依然拥有温暖的铺盖。",al={"为什么需要皮毛","厚熊皮的用途","铺盖"}}},fx={bd6a237a={q="驾驶员贝隆·风箱为什么想办成这件事？",a="驾驶员贝隆·风箱正为随攻城坦克旅长期出征做准备。接下来的任务会让他在野外停留至少一个月，而要深入丹莫罗冰冷的荒野作战，就必须做好周密准备。在出发执行任务之前，他需要在贝尔丁上储备充足的补给。",al={"驾驶员贝隆·风箱的动机","为什么给贝尔丁储备物资","风箱为什么需要补给"}},f0e85f28={q="大块野猪肉有什么用？",a="这些野猪肉是驾驶员贝隆·风箱即将开始的一个月驻外任务所需的重要口粮。在严寒中驾驶重型攻城坦克会消耗大量体力，而当地峭壁野猪提供的耐储肉食，能在他远离己方哨站时维持所需的体力。",al={"大块野猪肉用途","为什么要野猪肉","野猪肉贝尔丁"}},["779906a6"]={q="驾驶员贝隆·风箱为什么需要你去狩猎？",a="风箱正在监督贝尔丁的维护工作，抽不出时间狩猎。机械大师贝尔丁·钢架正在钢架补给站调校和修理这辆坦克，驾驶员必须留在附近，确保机器做好出发准备。",al={"风箱为什么不能狩猎","风箱为什么选我","为什么要替风箱狩猎"}}},fp="17,169,23.257.0,23.248.0,17.177.0,23.202.0,44.114.0,26.174.0,34.201.1,44.185.0"}
P.entries["quest:318"] = {n="艾沃沙酒",s="在卡拉诺斯附近的钢架补给站，驾驶员贝隆·风箱需要烈酒村的雷杰德·麦酒酿造的艾沃沙酒。这种烈酒既能让他暖身，也能为他的攻城坦克贝尔丁提供燃料。",h="在卡拉诺斯附近的钢架补给站，驾驶员贝隆·风箱需要烈酒村的雷杰德·麦酒酿造的艾沃沙酒。这种烈酒既能让他暖身，也能为他的攻城坦克贝尔丁提供燃料。",kw={"烈酒村","丹莫罗","艾沃沙酒","贝尔丁","卡拉诺斯","驾驶员贝隆·风箱","雷杰德·麦酒"},ang={["profession:Engineering"]="身为工程师，你能看出，易燃的烈酒让贝隆·风箱这样的驾驶员多了一种办法，在恶劣环境中维持攻城坦克运转。",["race:Dwarf"]="身为矮人，你深知矮人酿酒能有多烈，而雷杰德·麦酒的烈酒将这份烈性带到了丹莫罗寒冷的山峰。",["race:Gnome"]="身为侏儒，你或许会欣赏驾驶员贝隆·风箱的巧思，他能把寻常之物，甚至矮人酿的酒，临时用作燃料。"},sec={{t="烈性佳酿",b="雷杰德·麦酒的酿酒试验远不止普通的矮人麦酒。除了最能喝的矮人，艾沃沙酒足以让任何矮人醉倒，但它带来的暖意在丹莫罗的严寒中备受珍视。"},{t="驾驶员贝隆·风箱的燃料",b="在卡拉诺斯郊外的钢架补给站，驾驶员贝隆·风箱喝上一口艾沃沙酒，暖身抵御凛冽寒风。这种易燃的烈酒也能为贝尔丁的熔炉提供燃料。当贝隆·风箱陷入困境时，它能让他的攻城坦克爆发出一股应急动力。"}},faq={{q="艾沃沙酒是什么？",a="艾沃沙酒是烈酒村的矮人酿酒师雷杰德·麦酒酿造的一种烈性试验酒。它的酒劲如火，就连酒量很好的矮人也会被它放倒。",al={"艾沃沙酒是什么","艾沃沙酒","艾沃沙酒是什么酒"}},{q="驾驶员贝隆·风箱为什么想要艾沃沙酒？",a="驾驶员贝隆·风箱饮用艾沃沙酒，暖身抵御丹莫罗的寒冷，也将它用作应急燃料。在贝尔丁的熔炉中，这种易燃的烈酒能让攻城坦克瞬间爆发出一股动力。",al={"贝隆·风箱为什么想要酒","驾驶员贝隆·风箱 艾沃沙酒","贝隆·风箱为什么需要它"}},{q="烈酒村在哪里？",a="烈酒村位于丹莫罗西部，就在卡拉诺斯以西的道路沿线。雷杰德·麦酒等酿酒师住在那里，附近是白雪覆盖的山丘。",al={"烈酒在哪里","烈酒村位置","寻找烈酒"}},{q="雷杰德·麦酒是谁？",a="雷杰德·麦酒是烈酒村一位热衷试验的矮人酿酒师。他酿造各种酒，从可口的麦酒，到足以点燃机器熔炉的烈酒。",al={"雷杰德是谁","雷杰德·麦酒资料","麦酒酿酒师"}},{q="找到雷杰德·麦酒后，接下来要做什么？",a="雷杰德需要你先帮个忙，才肯交出他的酒。在烈酒村，你会接到“艾沃沙酒”，先帮助这位酿酒师，他才会给你一桶酒，让你带给驾驶员贝隆·风箱。",al={"艾沃沙酒之后的任务","艾沃沙酒之后做什么","雷杰德后续任务"}},{q="艾沃沙酒真的能安全饮用吗？",a="驾驶员贝隆·风箱说，几乎任何矮人喝了艾沃沙酒都会醉倒。最强健的山地居民能喝下它，但它也极易燃烧，因此还能用在引擎熔炉里。",al={"艾沃沙酒能喝吗","艾沃沙酒有毒吗","艾沃沙酒危险吗"}}},fp="9,179,19.179.0,24.268.0,18.177.0,40.201.0,26.144.0,25.171.0,49.181.1,33.188.0"}
P.entries["quest:3181"] = {n="玛尔戈的巨角",s="这只来自灼热峡谷的狂暴的玛尔戈的巨角布满划痕和裂纹，粗糙的表面嵌着一块断裂的斧头。斧头上刻着巡山人贝波蒂的名字，表明这是她的物品，而当你试着将它取出时，它却碎成了无数碎片。这只角需要交给贝波蒂。",h="这只来自灼热峡谷的狂暴的玛尔戈的巨角布满划痕和裂纹，粗糙的表面嵌着一块断裂的斧头。斧头上刻着巡山人贝波蒂的名字，表明这是她的物品，而当你试着将它取出时，它却碎成了无数碎片。这只角需要交给贝波蒂。",kw={"巨角","洛克莫丹","狂暴的玛尔戈","贝波蒂","灼热峡谷","石坝小径"},sec={{t="破碎的线索",b="这只来自狂暴的玛尔戈的角布满了划痕和裂纹。角里嵌着一件不寻常的金属物体，那是一块断裂的斧头，上面的刻字表明它属于巡山人贝波蒂。当你试着将它取出时，它却碎成了无数碎片。"},{t="大门",b="这只角开启了一系列任务，完成后便能打开连接洛克莫丹与灼热峡谷的石坝小径。它需要交给巡山人贝波蒂，而她并不愿意打开大门。"},{t="大门前",b="贝波蒂说，这只角显然是假的。贝波蒂曾与 玛尔戈 正面相遇，她说 玛尔戈 的角要大得多，至少是你这只的八倍，而你这只多半是从贫瘠之地的一头 雷角蜥蜴 身上取下来的。"}},faq={{q="这只角来自哪里？",a="它来自灼热峡谷的狂暴的玛尔戈。",al={"哪里能找到这只角","狂暴的玛尔戈 在哪里","谁掉落这只角"}},{q="巡山人贝波蒂是谁？",a="贝波蒂就是你需要将这只角交给的巡山人，也是那个不愿打开大门的人。",al={"贝波蒂","贝波蒂是谁","巡山人贝波蒂"}},{q="嵌在角里的斧头会怎样？",a="斧头上刻着巡山人贝波蒂的名字，表明这是她的物品，而当你试着将它取出时，它却碎成了无数碎片。",al={"贝波蒂的斧头为何嵌在角里","斧头上的刻字"}},{q="这只角会引出什么？",a="它开启了一系列任务，完成后便能打通石坝小径，连接洛克莫丹与灼热峡谷。",al={"石坝小径","通往灼热峡谷的大门钥匙是什么"}}},fp="21,66,16.221.0,8.203.0,11.230.1,31.49.0,31.114.0,41.110.0,27.92.1"}
P.entries["quest:319"] = {n="艾沃沙酒",s="为了帮钢架补给站的驾驶员贝隆·风箱弄到一桶永光酒，冒险者必须先帮帮烈酒村。酿酒师雷杰德·麦酒拒绝交出他的酒，除非先清理掉在附近雪堆中游荡的危险掠食者。",h="为了帮钢架补给站的驾驶员贝隆·风箱弄到一桶永光酒，冒险者必须先帮帮烈酒村。酿酒师雷杰德·麦酒拒绝交出他的酒，除非先清理掉在附近雪堆中游荡的危险掠食者。",kw={"贝隆·风箱","烈酒村","丹莫罗","成年峭壁野猪","永光酒","冰爪熊","雷杰德·麦酒","雪豹"},ang={["class:Hunter"]="清理丹莫罗西部的凶猛掠食者是对射击技术的考验，对手是峭壁上最强壮的冬季野兽。",["race:Dwarf"]="每一个矮人都明白让野生掠食者远离酿酒坊的重要性，这样才能确保烈酒村传奇的酒桶不被干扰。",["race:Gnome"]="钢架补给站的攻城机器驾驶员和技工们急切地等待着这桶酒，他们指望着冒险者能安抚那位固执的酿酒师，好让“喷气蒸汽号”的准备工作能够继续。"},sec={{t="酿酒师的交易",b="雷杰德·麦酒确实有驾驶员贝隆·风箱需要的永光酒，但他并不急着免费交出这珍贵的佳酿。雷杰德想要的不是钱，而是保护。丹莫罗西部的野生猛兽——贪婪的冰爪熊、皮糙肉厚的成年峭壁野猪，还有徘徊的雪豹——在烈酒村附近游荡，令当地居民感到不安，也造成了持续不断的干扰和危险。"},{t="工匠的安宁",b="虽然雷杰德坚持说没有一个自尊的矮人会畏惧野兽，但全天候应付这些掠食者会浪费宝贵的生产时间。清理掉当地的野生动物能让村民们获得安宁，从而专注于酿造和锻造工作，不必总是提心吊胆地盯着树林边缘。"}},faq={{q="雷杰德为什么要杀掉这些动物？",a="徘徊的熊、野猪和雪豹在烈酒村附近游荡。虽然矮人们并不怕它们，但驱赶它们会浪费本可以用于酿造和锻造的宝贵工作时间。",al={"为什么要杀熊","为什么要清理烈酒村的动物","雷杰德的任务原因"}},{q="永光酒是什么？",a="永光酒是一种烈性、著名的酒，由雷杰德·麦酒在烈酒村独家酿造。像驾驶员贝隆·风箱这样的攻城机器驾驶员觉得它非常有价值，既可以作为饮品，也可以作为一种易燃的燃料添加剂。",al={"什么是永光酒","永光酒酿造","雷杰德的酒"}},{q="谁最初想要永光酒？",a="钢架补给站的驾驶员贝隆·风箱派你去获取它，好让他在这路上保持温暖，并将其投入他自己的攻城机器“喷气蒸汽号”的熔炉中，以获得爆发性的动力。",al={"谁派我去取永光酒","谁想要永光酒","任务链开始"}},{q="去哪里可以找到这些动物？",a="它们在丹莫罗西部的烈酒村和涌冰湖周围的冰冻原野和峭壁上游荡。",al={"冰爪熊在哪里","雪豹位置","成年峭壁野猪位置"}},{q="完成这个委托后会发生什么？",a="一旦清理完野兽，雷杰德就会交出那桶永光酒，让你直接把它带回钢架补给站交给驾驶员贝隆·风箱。",al={"后续任务","完成永光酒的委托后"}},{q="村民们真的受到掠食者的威胁吗？",a="雷杰德坚持认为没有一个自尊的矮人会怕雪地里的野兽，但在家门口就有危险的掠食者咆哮着，会对日常工作造成持续的干扰和危险。",al={"烈酒村有危险吗","矮人害怕吗"}}},fx={["02738ac5"]={q="雷杰德·麦酒派你去猎杀哪些动物？",a="雷杰德派你去清剿烈酒村周围雪地里游荡的野兽和掠食者：冰爪熊、老峭壁野猪和雪豹。这些本地野兽四处游荡，危险地逼近村落边缘，村民们照料酿酒桶和作坊时，外面总能听到它们的低吼和喷鼻声。",al={"雷杰德的狩猎目标","哪些野兽","艾沃沙酒要杀哪些动物","烈酒村有哪些动物"}},fe0fe64f={q="雷杰德为什么找你，而不让烈酒村的村民处理这些野兽？",a="烈酒村的矮人根本不怕本地的野兽，任何有自尊的矮人都不会在野猪或雪豹面前退缩。不过，追猎成群游荡的掠食者会占用宝贵的时间，让他们无暇投入真正热爱的事情：酿造麦酒、制作物品、照料酿酒桶。既然你是个身强力壮的旅人，又正好在找一桶艾沃沙酒，雷杰德便与你做了笔交易，好让乡亲们安心干活。",al={"村民为什么不能杀死它们","雷杰德为什么选我","雷杰德为什么需要帮助","烈酒村的猎人"}}},fp="21,187,18.238.0,23.265.0,42.176.0,18.185.0,39.168.0,31.108.0,40.120.0,54.133.0"}
P.entries["quest:32"] = {n="异种蝎的威胁",s="高级勘探员菲兹杜瑟将关于虫群威胁的报告交给你，并催促你把它送到奥格瑞玛，交给一位名叫基尔兹宾·鼓眼的巨魔学者。",h="高级勘探员菲兹杜瑟将关于虫群威胁的报告交给你，并催促你把它送到奥格瑞玛，交给一位名叫基尔兹宾·鼓眼的巨魔学者。",kw={"暗影裂口","鼓眼","菲兹杜瑟","昆虫","奥格瑞玛","其拉虫人","塔纳利斯","基尔兹宾"},sec={{t="知情者",b="菲兹杜瑟希望这份报告能交到一位对此类事务有深入了解的人手中。基尔兹宾·鼓眼是一位巨魔学者，他花了很多时间研究艾泽拉斯生态中独特的生命形式，此外他还是一位历史学家。菲兹杜瑟希望基尔兹宾能弄清楚真正的危险究竟是什么，以及该如何阻止它，并表示需要一切能够提供的帮助。基尔兹宾住在奥格瑞玛暗影裂口的第二层。"},{t="基尔兹宾的回答",b="基尔兹宾以前处理过这些生物，并认为菲兹杜瑟把报告交给你是一个明智的选择。它们会迅速吞噬塔纳利斯沙漠，是任何人所面临的最大威胁之一。它们就是其拉虫人，是部落和联盟所面临的最严峻威胁之一的工具。基尔兹宾感叹没有人有足够的远见能早点发现这一点。"}},faq={{q="基尔兹宾·鼓眼是谁？",a="一位巨魔学者和历史学家，他花费了大量时间研究艾泽拉斯生态系统中独特的生命形式。",al={"谁是鼓眼","基尔兹宾·鼓眼背景故事","奥格瑞玛的巨魔学者"}},{q="是谁派你去找基尔兹宾的？",a="高级勘探员菲兹杜瑟，他给了你这份报告，并让你把它带到奥格瑞玛。",al={"其拉虫人的崛起起始","谁给予其拉虫人的崛起任务"}},{q="基尔兹宾·鼓眼在奥格瑞玛的什么位置？",a="在奥格瑞玛暗影裂口，第二层的一间屋子里。",al={"基尔兹宾在哪里","鼓眼的房子在哪里"}},{q="这一步之前是什么？",a="它紧接在“昆虫分析”之后。",al={"其拉虫人的崛起前置任务","什么导致了其拉虫人的崛起"}}},fp="20,104,17.407.0,17.364.1,25.127.0,26.88.0,48.75.0,37.34.0"}
P.entries["quest:320"] = {n="艾沃沙酒",s="“回到驾驶员贝隆·风箱处”是丹莫罗的一个短途配送任务，冒险者需要将一桶当地酿造的永恒之光送给位于钢架补给站的驾驶员贝隆·风箱。这个任务结束了一次当地的委托，为口渴的驾驶员送去了一杯令人愉悦的佳酿。",h="“回到驾驶员贝隆·风箱处”是丹莫罗的一个短途配送任务，冒险者需要将一桶当地酿造的永恒之光送给位于钢架补给站的驾驶员贝隆·风箱。这个任务结束了一次当地的委托，为口渴的驾驶员送去了一杯令人愉悦的佳酿。",kw={"永恒之光酒桶","丹莫罗","永恒之光","卡拉诺斯","驾驶员贝隆·风箱","回到贝隆·风箱处","钢架补给站"},ang={["faction:Alliance"]="在矮人猎人和矮人驾驶员之间奔走传信有助于维持驻扎在丹莫罗的联盟部队的士气和同志情谊。",["race:Dwarf"]="像永恒之光这样醇厚的矮人佳酿在整个丹莫罗总是供不应求，将其安全送到口渴的战友手中简直是理所当然的事。",["race:Gnome"]="驾驶员贝隆·风箱是一位驻扎在钢架补给站的矮人攻城机驾驶员，让辛勤工作的工程师们保持精力充沛有助于维持机械的平稳运转。"},sec={{t="给补给站的一桶酒",b="“回到驾驶员贝隆·风箱处”是丹莫罗雪原上的一个差事。在协助当地的狩猎活动后，冒险者会收到一桶刚酿好的永恒之光，并被指派将其直接送到钢架补给站的驾驶员贝隆·风箱手中。这是一件简单的顺手之劳，彰显了在这片寒冷的边境地区，人们之间那种非正式的同志情谊和相互支持的精神。"},{t="口渴的驾驶员",b="钢架补给站是卡拉诺斯外的一个繁忙中心，主要负责机械测试、车辆维护和侏儒工艺。对于驻扎在寒风中的飞行员来说，没有什么比喝上一口烈性的当地佳酿更让人满足的了。驾驶员贝隆·风箱在收到酒后毫不耽搁，急切地当场启瓶，享受着当地酿酒师的劳动成果。"}},faq={{q="任务“回到驾驶员贝隆·风箱处”是什么？",a="“回到驾驶员贝隆·风箱处”是丹莫罗的一个运送任务，冒险者需要将一桶刚得到的永恒之光直接送给位于钢架补给站的驾驶员贝隆·风箱。",al={"回到贝隆·风箱处任务","贝隆·风箱任务"}},{q="驾驶员贝隆·风箱是谁？",a="驾驶员贝隆·风箱是一位矮人攻城机驾驶员，驻扎在丹莫罗卡拉诺斯外的钢架补给站。他正热切地等待着新鲜的永恒之光送来品尝。",al={"谁想要永恒之光","贝隆·风箱是谁"}},{q="永恒之光是什么？",a="永恒之光是一种在丹莫罗酿造的强劲当地佳酿，装在结实的木桶里，深受口渴的飞行员和当地人的喜爱。",al={"什么是永恒之光","永恒之光酒桶"}},{q="应该把酒桶送到哪里？",a="驾驶员贝隆·风箱位于钢架补给站，那是一个位于丹莫罗卡拉诺斯以东的工程中心和工作坊。",al={"贝隆·风箱在哪里","贝隆·风箱位置"}},{q="为什么要给贝隆·风箱送去永恒之光？",a="在协助该地区的狩猎任务后，冒险者受托将一桶永恒之光送给一直热切期盼着能尝上一口的驾驶员贝隆·风箱。",al={"为什么要运送永恒之光","运送永恒之光的原因"}},{q="当贝隆·风箱收到永恒之光时会发生什么？",a="在收到木桶后，驾驶员贝隆·风箱感到非常满意，他说这酒很不错，并立即动手启瓶品尝。",al={"贝隆·风箱怎么处理酒","贝隆·风箱的反应"}}},fp="19,141,20.218.0,16.291.0,38.91.0,23.168.0,30.114.0,30.124.0,40.122.0,51.116.0"}
P.entries["quest:321"] = {n="光铸铁",s="“圣铸铁”是戈罗林·钢眉在米奈希尔港发布的一项联盟打捞任务。冒险者被派往搜索“飞鱼号”的残骸，这是一艘精灵驱逐舰，在第二次战争期间，它随库尔提拉斯第三舰队一同失踪，船上载有珍贵的圣洁金属。",h="“圣铸铁”是戈罗林·钢眉在米奈希尔港发布的一项联盟打捞任务。冒险者被派往搜索“飞鱼号”的残骸，这是一艘精灵驱逐舰，在第二次战争期间，它随库尔提拉斯第三舰队一同失踪，船上载有珍贵的圣洁金属。",kw={"飞鱼号","戈罗林·钢眉","金属锭","库尔提拉斯","圣铸铁","米奈希尔港","鱼人","第三舰队","浸水的箱子","湿地"},ang={["class:Paladin"]="用圣铸铁锻造的武器与圣光有着深刻的共鸣，即使找回一枚丢失的金属锭也具有重要的精神意义。",["faction:Alliance"]="米奈希尔港外的沉船是第二次战争中令人悲痛的纪念碑，库尔提拉斯和洛丹伦的勇敢水手们在那里倒在了龙火之下。",["profession:Blacksmithing"]="各门派的铁匠都将圣铸铁视为材料界的圣杯，它以蕴含强大的祝福和无与伦比的结构稳定性而闻名。"},sec={{t="圣洁货物",b="虽然散落在湿地海岸线上的大多数沉船残骸都属于著名的库尔提拉斯第三舰队，但有一艘船与众不同：一艘名为“飞鱼号”的精灵驱逐舰。该船从洛丹伦出发，试图跟随海军舰队以寻求庇护，船上运载着珍贵的圣铸铁货物。不幸的是，当龙喉氏族的兽人驾驭着被奴役的红龙从天而降时，与战舰同行的保护作用微乎其微。他们焚毁了舰队，将士兵和圣洁的金属一同沉入了海底。"},{t="潮汐掠夺者",b="到达米奈希尔港以南“飞鱼号”的破碎残骸处，会发现时间与大海并不是唯一的破坏者。装载着货物的被水浸透的箱子已被撬开并遭到翻找。海岸鱼人作为沉船的常客，早已洗劫了船舱并将金属锭四处散落，几乎没给戈罗林·钢眉留下任何珍贵矿石的踪迹。"}},faq={{q="什么是“飞鱼号”？",a="“飞鱼号”是一艘在第二次战争期间从洛丹伦驶出的精灵驱逐舰。它运载着一批稀有的圣铸铁，并随库尔提拉斯第三舰队同行以寻求保护，但最终与舰队其余船只一起被受兽人奴役的红龙焚毁并沉没。",al={"飞鱼号背景故事","湿地精灵驱逐舰","哪艘船载有圣铸铁"}},{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位驻扎在湿地米奈希尔港的矮人。他致力于从海岸线的沉船中回收历史遗物和贵重材料，尤其是像圣铸铁这样的传奇金属。",al={"戈罗林·钢眉","米奈希尔港的矮人","谁发布圣铸铁任务"}},{q="什么是圣铸铁？",a="圣铸铁是一种极其罕见的圣洁金属，用于锻造神圣的武器和盔甲。因其纯净和强大的精神属性，它受到圣光追随者和铁匠们的高度珍视。",al={"圣铸铁金属","什么是圣铸铁","圣铸铁锭"}},{q="为什么这些船只在湿地沉没？",a="在第二次战争期间，部落的龙喉氏族利用恶魔之魂奴役了红龙军团。巨龙骑士在湿地海岸外袭击了库尔提拉斯第三舰队，烧毁了船只并将它们送入海底。",al={"谁击沉了第三舰队","为什么湿地有沉船","湿地红龙舰队"}},{q="为什么箱子几乎是空的？",a="“飞鱼号”上那个被水浸透的箱子上有明显的鱼人利爪抓痕。这些生物撬开了箱子并掠走了货物，带走了大部分金属锭，并将它们散落在泥泞的岸边。",al={"金属锭在哪里","为什么箱子有抓痕","谁偷了圣铸铁"}},{q="“飞鱼号”的残骸位于何处？",a="残骸位于米奈希尔港以南的海岸浅滩，沿着湿地的西岸散布在当地鱼人聚居地附近的浅水区。",al={"飞鱼号位置","箱子在哪里","湿地沉船位置"}}},fp="15,195,14.335.0,22.251.1,26.226.0,24.209.0,24.167.0,40.227.0,30.162.0,51.192.0"}
P.entries["quest:322"] = {n="格瑞曼德·艾尔默",s="在暴风城，戈罗林·钢眉将光铸铁送去，用于打造对抗摩本特·费尔的武器。你把从湿地的飞翔鱼鹰号号残骸中找回的稀有金属交给武器锻造大师格瑞曼德·艾尔默，他能将其锻造成战斗所需的武器。",h="在暴风城，戈罗林·钢眉将光铸铁送去，用于打造对抗摩本特·费尔的武器。你把从湿地的飞翔鱼鹰号号残骸中找回的稀有金属交给武器锻造大师格瑞曼德·艾尔默，他能将其锻造成战斗所需的武器。",kw={"神圣武器","矮人区","戈罗林·钢眉","格瑞曼德·艾尔默","光铸铁","洛克莫丹","摩本特·费尔","暴风城"},ang={["class:Paladin"]="身为圣骑士，你运送经过祝圣的铁，用来打造对抗暮色森林一名死灵法师的武器。这践行了白银之手的使命：以神圣的警觉应对黑暗巫术。",["faction:Alliance"]="身为联盟的一员，你在诸王国之间传递援助，从米奈希尔港的一位矮人牧师那里，一路送到暴风城的矮人区。暮色森林的人民正饱受困扰。",["profession:Blacksmithing"]="光铸铁稀有且难以锻造。看着经验丰富的矮人铁匠格瑞曼德·艾尔默接下这项工作，便能明白锻造神圣武器需要怎样的技艺。"},sec={{t="稀有金属归来",b="戈罗林·钢眉将找回的光铸铁装箱，准备运往暴风城。这种金属十分稀有，对邪恶与不洁的生物有强大的威力，需要懂得如何锻造它的铁匠。这批货物来自湿地海岸外的飞翔鱼鹰号号残骸。在南方诸王国中，戈罗林只知道一位适合承担这项工作的工匠：武器锻造大师格瑞曼德·艾尔默。"},{t="矮人区的熔炉",b="在暴风城的矮人区，格瑞曼德·艾尔默拥有城中最好的铁砧之一。当你将找回的货物交给他时，他说，自己上一次锻打光铸铁已是多年前的事了。这位经验丰富的工匠很高兴能有机会打击死灵法师摩本特·费尔。他答应挥锤开工。"}},faq={{q="运送这批货物的目的是什么？",a="箱子里装着从湿地的飞翔鱼鹰号号残骸中打捞出的光铸铁。戈罗林·钢眉将它送给格瑞曼德·艾尔默，他能把这种经过祝圣的金属锻造成对抗摩本特·费尔的武器。",al={"为何把铁锭送往暴风城","祝福之臂的目的","一箱光铸铁锭有什么用"}},{q="格瑞曼德·艾尔默是谁？",a="格瑞曼德·艾尔默是暴风城矮人区一位备受尊敬的矮人武器锻造师。很少有工匠受过锻造光铸铁这类特殊金属的训练。",al={"格瑞曼德·艾尔默的故事","矮人区的铁匠是谁"}},{q="为什么光铸铁对抗摩本特·费尔如此重要？",a="光铸铁对邪恶与不洁的生物有强大的威力。格瑞曼德·艾尔默能将这种经过祝圣的金属锻造成对抗死灵法师摩本特·费尔的武器。",al={"为何使用光铸铁","光铸铁如何伤害摩本特·费尔"}},{q="戈罗林·钢眉派你去哪里？",a="戈罗林·钢眉派你从湿地的米奈希尔港出发，前往暴风城矮人区的格瑞曼德·艾尔默的铁匠铺。",al={"祝福之臂要去哪里","格瑞曼德·艾尔默在哪里"}},{q="格瑞曼德·艾尔默以前锻造过光铸铁吗？",a="是的。格瑞曼德说，自己上一次锻造光铸铁已是多年前的事了。他很高兴有机会再次锻造这种久负盛名的金属。",al={"格瑞曼德以前锻造过光铸铁吗","艾尔默的锻造经验"}},{q="武器完成之前，还需要做什么？",a="格瑞曼德答应将找回的光铸铁锻造成摩本特的克星。等他完成后，你就把武器带给暮色森林的斯温·约根。",al={"祝福之臂之后是什么","武器会立即锻造好吗"}}},fx={["983cc211"]={q="戈罗林·钢眉为什么要安排这次运送？",a="戈罗林知道，普通钢铁无法击破暮色森林中守护摩本特·费尔的黑暗防护。拿到你从湿地的飞翔鱼鹰号残骸中找回的光铸铁后，他得知你正与这名死灵法师作战，便指引你去找一位技艺精湛的铁匠，打造一件真正能伤到他的武器。",al={"戈罗林·钢眉的动机","戈罗林为什么帮忙","为什么把铁锭送给格瑞曼德"}}},fp="11,236,20.355.0,28.315.0,37.202.0,22.167.0,56.155.0,37.127.0,54.135.0,51.143.0"}
P.entries["quest:3221"] = {n="与伦弗利尔会面",s="在瑟伯切尔，药剂师伦弗利尔正等着你带来关于受污染狼心的调查结果。高级执行官哈德瑞克派你去与这位皇家药剂师学会的研究员交谈。",h="在瑟伯切尔，药剂师伦弗利尔正等着你带来关于受污染狼心的调查结果。高级执行官哈德瑞克派你去与这位皇家药剂师学会的研究员交谈。",kw={"哈德瑞克","伦弗利尔","皇家药剂师学会","瑟伯切尔","银松森林","狼心"},ang={["faction:Horde"]="作为部落的一员，你可以了解污染正在如何改变银松森林的野兽。",["race:Undead"]="作为Undead，你或许会听到皇家药剂师学会的研究员如何在瑟伯切尔与军事指挥人员协作。他们研究银松森林的异常生物。"},sec={{t="协会的召见",b="你在银松森林各处帮助亡灵哨兵之后，高级执行官哈德瑞克交给你一封药剂师伦弗利尔的紧急信件。伦弗利尔研究了从当地野生动物身上收集的变色狼心，需要你立刻前去。"},{t="炼金奇物",b="药剂师伦弗利尔为皇家药剂师学会效力，在瑟伯切尔墓穴内的一间实验室里工作。他研究黑暗魔法和疾病如何改变银松森林的野兽。他的炼金研究以战线传来的军事报告为依据。"}},faq={{q="药剂师伦弗利尔在哪里？",a="药剂师伦弗利尔在银松森林中部的瑟伯切尔墓穴里工作，就在他的炼金设备旁边。从高级执行官哈德瑞克所在的地方走一小段路就能找到他。",al={"伦弗利尔位置","伦弗利尔在哪里","寻找伦弗利尔"}},{q="药剂师伦弗利尔为什么要与我交谈？",a="伦弗利尔研究了银松森林狼的变色心脏，并在其腐化迹象中发现了异常。他需要进一步调查，并向幽暗城汇报。",al={"伦弗利尔为什么找我","伦弗利尔狼心"}},{q="谁派你去找伦弗利尔？",a="高级执行官哈德瑞克是瑟伯切尔的被遗忘者指挥官，你帮助亡灵哨兵归来后，他会向你转达伦弗利尔的召见。",al={"谁提供与伦弗利尔会面","任务给予者"}},{q="这次交谈之后会发生什么？",a="与伦弗利尔交谈后，你将继续开展工作，将瑟伯切尔的炼金研究与幽暗城的高层人物联系起来，其中包括药剂师金格。",al={"与伦弗利尔交谈的下一个任务","伦弗利尔后续"}}},fp="20,179,24.231.0,22.241.0,38.155.0,52.168.0,27.141.0,31.164.0"}
P.entries["quest:323"] = {n="证明你的实力",s="“证明你的价值”是斯温·约根在暮色森林西部复仇行动中的关键一步。在允许冒险者直接对抗死灵法师摩尔本·菲尔之前，这位悲痛的隐士要求证明他们有能力击败盘踞在乌鸦岭墓地的亡灵军团。",h="“证明你的价值”是斯温·约根在暮色森林西部复仇行动中的关键一步。在允许冒险者直接对抗死灵法师摩尔本·菲尔之前，这位悲痛的隐士要求证明他们有能力击败盘踞在乌鸦岭墓地的亡灵军团。",kw={"黑暗骑士","暮色森林","荒弃鬼屋","摩尔本·菲尔","证明你的价值","乌鸦岭墓地","骷髅治疗者","骷髅掠夺者","骷髅守卫","斯温·约根"},ang={["class:Paladin"]="净化乌鸦岭墓地中摩尔本·菲尔的躁动死者是神圣的工作，用圣光的正义回应暮色森林逝者未被掩埋的哀嚎。",["class:Priest"]="黑暗仪式对乌鸦岭墓地的亵渎呼唤着精神上的净化，终结那些扭曲生死、祸害世间的守卫和治疗者。",["faction:Alliance"]="由于缺乏常规的暴风城巡逻队，暮色森林西部已经陷入无政府状态，这使得像斯温这样饱受摧残的边境居民只能完全依赖流浪的勇士来击退亡灵天灾。"},sec={{t="苦涩隐士的考验",b="斯温·约根躲藏在喧嚣森林以北的一处偏僻营地中，因家人的惨死而饱受悲痛与愤怒的折磨。他已经拼凑出线索，摧毁他家园的暗影黑暗骑士与一名名叫摩尔本·菲尔的邪恶死灵法师结盟。尽管斯温渴望复仇，但他并非鲁莽之徒，不会将未经考验的新兵直接推向菲尔的魔爪。他要求冒险者展示出高超的战斗技巧，以击败占据乌鸦岭墓地的骷髅大军。"},{t="乌鸦岭墓穴",b="为了满足斯温的要求，冒险者必须深入位于荒弃鬼屋以南的乌鸦岭墓地。在菲尔邪恶魔法的束缚下，陵墓及其周边地区到处都是躁动的尸体：挥舞长剑的骷髅掠夺者在墓碑间游荡，而骷髅守卫和治疗者则照看著地下深处的黑暗密室。清理这支先锋部队是一场血腥的苦差事，尤其是当复仇幻影摩拉迪姆这样的恐怖存在在墓地小径上游荡时。"},{t="通往死灵法师之路",b="在布满白骨的地下墓穴中幸存下来，这让斯温确信他的盟友不仅仅只有匹夫之勇。然而，击败菲尔的爪牙只是序幕。摩尔本·菲尔掌握着黑暗的保护附魔，使他在普通武器面前几乎毫发无伤，这迫使斯温必须在最终决战开始前寻求更伟大的智慧和上古遗物。"}},faq={{q="为什么在面对摩尔本·菲尔之前，斯温要让我去对付骷髅？",a="斯温知道摩尔本·菲尔是一位与神秘黑暗骑士结盟的致命死灵法师。在他们证明自己拥有切开整支亡灵先锋部队所需的耐力和战术技巧之前，他拒绝让盟友去送死。",al={"为什么要证明你的价值","为什么斯温要我杀骷髅","斯温的考验"}},{q="哪里可以找到骷髅守卫和治疗者？",a="虽然骷髅掠夺者在荒弃鬼屋以南的开阔墓地游荡，但骷髅治疗者和守卫主要集中在墓地中心以西的大型陵墓和地下墓穴隧道内及其周围。",al={"守卫在哪里","骷髅治疗者在哪里","寻找骷髅守卫"}},{q="摩拉迪姆是谁，我为什么要在这里提防他？",a="摩拉迪姆是一位强大而悲惨的亡灵骑士，他会在乌鸦岭墓地的小径上游荡。他比墓穴周围的普通骷髅强大得多，会迅速斩杀粗心大意的冒险者。",al={"摩拉迪姆的危险","摩拉迪姆是谁","乌鸦岭游荡的精英"}},{q="摩尔本·菲尔与黑暗骑士有什么关联？",a="斯温发现摩尔本·菲尔与屠杀他妻儿的披风黑暗骑士结盟。虽然骑士们消失在阴影中，但菲尔仍驻扎在暮色森林，继续他的邪恶死灵法术。",al={"摩尔本·菲尔与黑暗骑士的联系","为什么黑暗骑士和菲尔结盟","斯温家人的凶手"}},{q="完成这个任务后会发生什么？",a="一旦证明了你的战斗实力，斯温会认可你的力量，但也会解释说摩尔本·菲尔不能仅靠蛮力杀死。他会指引你去暴风城的光明大教堂寻求主教法席恩的建议，以找到剥除死灵法师邪恶保护的方法。",al={"证明你的价值后的下一个任务","消灭骷髅后做什么"}},{q="斯温·约根的营地在哪里？",a="斯温在暮色森林最西北边缘的山丘上维持着一处隐蔽的营地，安全地隐藏在乌鸦岭以北、通往西部荒野的道路以西。",al={"斯温在哪里","斯温的营地位置"}}},fp="18,179,22.397.0,21.370.0,27.276.1,64.179.0,49.187.0,57.152.0,48.200.0,41.216.1,36.136.0"}
P.entries["quest:324"] = {n="丢失的铁锭",s="“丢失的铸块”是联盟在湿地执行的一项任务，旨在从沉船中回收圣化金属。在沉没的宝箱中只找到一根铸块后，旅行者们必须去搜寻掠夺了剩余货物的当地蓝腮鱼人。",h="“丢失的铸块”是联盟在湿地执行的一项任务，旨在从沉船中回收圣化金属。在沉没的宝箱中只找到一根铸块后，旅行者们必须去搜寻掠夺了剩余货物的当地蓝腮鱼人。",kw={"蓝腮","飞鱼号","戈罗林·钢眉","铸块","光铸铁","鱼人","浸水的宝箱","湿地"},ang={["class:Paladin"]="从原始鱼人手中回收光铸铁，能确保圣洁的材料被保存下来，用于制造适合作为圣光勇士使用的圣化武器。",["profession:Blacksmithing"]="每一位金属工匠都知道，看到像光铸铁这样优质的原材料最终变成沿海鱼人巢穴里的珍品，而不是出现在铁砧上，是一件多么令人痛心的事情。",["race:Dwarf"]="回收丢失的杰作级矿石，并将其交到像戈罗林·钢眉这样的矮人牧师手中，是对矮人锻造传统和回收者传统的致敬。"},sec={{t="被劫掠的沉船",b="在湿地多雾的海岸外，躺着飞鱼号的残骸。为了给矮人牧师戈罗林·钢眉取回珍贵的光铸铁，寻宝者们发现货舱里的浸水宝箱几乎是空的。贪婪的当地蓝腮鱼人已经抢掠了船只的其余部分，将闪闪发光的铸块据为己有。"},{t="收回圣洁金属",b="光铸铁并非普通的矿石；它是一种稀有、特殊的金属，能够用于圣洁的锻造工艺。对于一位圣光矮人来说，任由这些金属在鱼人营地中腐烂是无法想象的。通过狩猎那些在破碎船体附近的浅滩上蜂拥而至的蓝腮劫掠者，冒险者们夺回了散落的铸块，以便戈罗林·钢眉能将这些铁锭锻造成武器。"}},faq={{q="哪艘船运载了光铸铁？",a="货物是搭乘飞鱼号抵达的，这艘不幸的船只在湿地海岸外遭遇了劫难。它破碎的木材残骸现在部分淹没在浅滩中。",al={"哪艘船","飞鱼号","沉船名称"}},{q="为什么宝箱里没有铸块？",a="浸水的宝箱里只剩下一根铸块。沿海的蓝腮鱼人已经撬开了沉没的残骸，掠走了剩余的货物，并将其散布在它们的沿海劫掠者之间。",al={"铸块在哪里","为什么鱼人持有铁锭","宝箱是空的"}},{q="戈罗林·钢眉是谁？",a="戈罗林·钢眉是一位圣光教会的矮人牧师，位于米奈希尔港的深水旅店中。他是主教法席恩的同事，他寻找光铸铁是为了打造一把对抗死灵法师摩本特·费尔的武器。",al={"戈罗林","戈罗林·钢眉是谁","任务发布者"}},{q="光铸铁有什么特别之处？",a="光铸铁是一种稀有的圣洁金属，对神圣附魔和锻造有着独特的感应。它受到那些制作与圣光相符的武器装备的工匠们的推崇。",al={"光铸铁背景","什么是光铸铁","为什么铁锭很重要"}},{q="是哪些鱼人拿走了铁锭？",a="蓝腮部落，特别是那些在飞鱼号残骸周围的浅滩和海滩上徘徊的鱼人劫掠者，夺走了丢失的铸块。",al={"谁偷了铸块","哪个部落","蓝腮劫掠者"}},{q="交还铸块后接下来要做什么？",a="一旦戈罗林·钢眉收齐了所有的铸块，他会将这些圣洁的金属装进一个板条箱，并派你去暴风城找武器匠格里曼德·艾尔莫尔进行锻造，任务将继续进入“受福武器”。",al={"下一个任务","戈罗林做什么","受福武器任务"}}},fp="15,147,21.264.0,27.242.0,38.141.0,37.117.0,24.219.0,38.140.0,28.114.0,43.191.1"}
P.entries["quest:325"] = {n="整装待发",s="“武装待命”标志着铸造一把专为剥离死灵法师摩本特·费尔的邪恶防御而设计的武器的圆满完成。在获得了格里曼德·埃尔默的精湛手艺后，这位冒险者带着“摩本特的克星”渡河回到暮色森林，交给了复仇心切的斯温·约根。",h="“武装待命”标志着铸造一把专为剥离死灵法师摩本特·费尔的邪恶防御而设计的武器的圆满完成。在获得了格里曼德·埃尔默的精湛手艺后，这位冒险者带着“摩本特的克星”渡河回到暮色森林，交给了复仇心切的斯温·约根。",kw={"武装待命","暮色森林","格里曼德·埃尔默","摩本特·费尔","摩本特的克星","乌鸦岭","暴风城","斯温·约根"},ang={["class:Paladin"]="优质矮人钢铁与神圣祝圣的结合，呼应了圣骑士将神圣光芒注入武术装备以粉碎亡灵结界的传统。",["faction:Alliance"]="暴风城的工匠与暮色森林的前线幸存者之间的协作，突显了联盟必须利用其首都的专业知识来清除蔓延的枯萎病。",["profession:Blacksmithing"]="格里曼德·埃尔默的手艺展示了精湛的锻造技术如何与神圣仪式相结合，从而打造出对抗超自然威胁的特制武器。"},sec={{t="锻造武器",b="摩本特·费尔对乌鸦岭墓地的掌控似乎坚不可摧。常规的钢铁在笼罩着这位死灵法师的黑暗结界面前要么粉碎，要么被毫无伤痕地弹开。要克服这种邪恶的魔法，需要一件专门的圣物：“摩本特的克星”。随着金属在暴风城的矮人区由格里曼德·埃尔默塑形，并经由神圣力量的祝圣，这件破除结界的圣物终于完成了，随时准备切断费尔与亡灵的联系。"},{t="回到隐士身边",b="将“摩本特的克星”带回暮色森林为斯温·约根带来了希望，他目睹了自己的家人和农场成为不断蔓延的黑暗的牺牲品。驻扎在森林西部边界附近那个孤寂营地的斯温，一眼就看出了这位旅者眼中的火光，以及这把武器所蕴含的神圣工艺。随着这件破除结界的圣物交付，向乌鸦岭的主人发起直接攻击的舞台已经搭好。"}},faq={{q="什么是“摩本特的克星”？",a="“摩本特的克星”是一把经过专门锻造和祝圣的武器，旨在刺穿乌鸦岭死灵法师摩本特·费尔周围那不可摧毁的魔法结界。",al={"摩本特的克星","什么是该武器","摩本特的克星之剑"}},{q="是谁打造了这把武器？",a="居住在暴风城的矮人区的熟练铁匠格里曼德·埃尔默，用祝圣过的圣光锻铁打造了这把破除结界的武器。",al={"谁制作了摩本特的克星","格里曼德·埃尔默的角色"}},{q="我该把“摩本特的克星”交给谁？",a="你必须将武器交给斯温·约根，他正躲在暮色森林西部的一个营地里，距离西部荒野的边界不远。",al={"斯温在哪里","斯温·约根的位置","交付地点"}},{q="为什么斯温·约根不能亲自对付摩本特·费尔？",a="斯温·约根被迫离开了家园，他的家人和同伴都在森林肆虐的黑暗势力中丧生。在孤立无援且遭到追猎的情况下，他只能依靠联盟中能力出众的勇士来为逝者复仇。",al={"为什么斯温不战斗","斯温·约根的背景故事"}},{q="完成“武装待命”后会发生什么？",a="在收到这把被祝福的武器后，斯温·约根会指派你直接深入乌鸦岭墓地，去面对并击败摩本特·费尔。",al={"接下来是什么","武装待命后的下一个任务"}},{q="回到斯温营地的最快路线是什么？",a="从西部荒野的哨兵岭向东穿过河流，通常比向西穿越充满恐怖的夜色镇要短得多，也安全得多。",al={"去斯温那里的最快方式","如何快速到达斯温处"}}},fx={["4a0f4d98"]={q="格瑞曼德·艾尔默为什么想把摩本特的克星送给斯温？",a="格瑞曼德·艾尔默是暴风城的一位锻造大师，承担了打造一件能够穿透黑暗魔法的武器的任务。完成摩本特的克星后，他迫切地派你返回暮色森林，好让这件武器发挥应有的作用，并祝愿你战胜那名死灵法师，期待听到你凯旋的故事。",al={"格瑞曼德·艾尔默的动机","格瑞曼德为什么帮忙","格瑞曼德为什么帮助斯温"}},["2182c2f5"]={q="格瑞曼德·艾尔默为什么需要你带走武器，而不亲自送去？",a="格瑞曼德是一名在暴风城矮人区工作的铁匠，并非四处游历的冒险者或信使。你为他带来了材料和暮色森林的噩耗，而你正准备与斯温·约根一起面对那个恶魔，因此将这件受过祝福的武器带回战场的责任就落在了你身上。",al={"整装待发为什么选我","格瑞曼德为什么不去暮色森林","为什么派玩家去找斯温"}}},fp="15,99,15.277.0,20.301.1,23.110.0,23.121.0,34.100.0,48.170.0,46.116.1,47.153.0"}
P.entries["quest:3261"] = {n="乔恩·星眼",s="在贫瘠之地南部，经验丰富的部落猎人向乔恩·星眼寻求指引。你为瑟格拉·黑棘猎杀当地的迅猛龙后，她会派你南下前往陶拉祖营地，那里的一位年长追踪者将传授更深入的技艺。",h="在贫瘠之地南部，经验丰富的部落猎人向乔恩·星眼寻求指引。你为瑟格拉·黑棘猎杀当地的迅猛龙后，她会派你南下前往陶拉祖营地，那里的一位年长追踪者将传授更深入的技艺。",kw={"陶拉祖营地","猎人之路","乔恩·星眼","镰爪龙","瑟格拉·黑棘","贫瘠之地","十字路口"},ang={["class:Hunter"]="身为猎人，你会遇见乔恩·星眼，他将考验你能否凭借智慧和力量，战胜中部与南部平原上的传奇顶级掠食者。",["faction:Horde"]="身为部落的一员，你从十字路口前往陶拉祖营地，深入争夺不断的贫瘠之地南部。",["race:Tauren"]="身为一名南下返回陶拉祖营地的牛头人，你将重新把部族的狩猎技艺与守护贫瘠之地荒野的精神传承联系起来。"},sec={{t="传承衣钵",b="你猎杀了潜行于北方草原的狡猾的 太阳鳞 和 镰爪 迅猛龙，赢得了十字路口的瑟格拉·黑棘的尊重。她深知，除了战斗技巧，还必须了解这片土地上的强大野兽。她的教导已经结束，于是派你南下。"},{t="通往陶拉祖之路",b="沿黄金之路向南，穿过愈发崎岖的平原，便能抵达陶拉祖营地，这是一处靠近南部荒野的重要牛头人聚居地。年长的追踪者乔恩·星眼在那里等候，准备教导猎人如何在贫瘠之地追寻那些行踪难觅的传奇猎物。"}},faq={{q="谁会派我去找乔恩·星眼？",a="你猎杀当地的 镰爪 迅猛龙后，十字路口的迅猛龙猎手瑟格拉·黑棘会派你南下。这些狩猎证明了你的追踪本领和狩猎技艺。",al={"谁提供 乔恩·星眼 任务","谁开启 乔恩·星眼 任务","瑟格拉·黑棘 任务"}},{q="乔恩·星眼在哪里？",a="乔恩·星眼位于陶拉祖营地，沿着贯穿贫瘠之地的大路向南走很远才能抵达。",al={"乔恩·星眼 在哪里","乔恩·星眼 位置","寻找 乔恩·星眼"}},{q="找到乔恩·星眼后会发生什么？",a="向乔恩报到后，他会欢迎你踏上猎人之路，并开始指引你在贫瘠之地南部追踪和猎杀行踪难觅的野兽。第一个目标就是传奇迅猛龙伊沙姆哈尔。",al={"乔恩 教什么","乔恩·星眼 后续","乔恩·星眼 之后的任务"}},{q="完成这个任务必须是猎人职业吗？",a="不必。任何完成瑟格拉·黑棘的迅猛龙狩猎任务的部落冒险者，无论是什么职业，都可以踏上这条学习在平原上追踪猎物的道路。",al={"是否仅限猎人","乔恩·星眼 职业要求"}},{q="为什么瑟格拉不再亲自教导你？",a="瑟格拉·黑棘在十字路口附近的北部迅猛龙巢穴一带活动。等你掌握了那些狩猎技巧，她就会派你南下去找乔恩·星眼，由他带领你深入南方，追猎那里的野兽。",al={"瑟格拉 为什么派人离开","瑟格拉 指导结束"}},{q="陶拉祖营地是什么地方？",a="陶拉祖营地是贫瘠之地南部的一处牛头人营地。它既是狩猎哨站和贸易枢纽，也是往返于北部平原与莫高雷或千针石林之间的旅人交流文化的歇脚处。",al={"关于陶拉祖营地","陶拉祖 是什么"}}},fp="12,214,18.283.0,19.235.0,29.161.0,30.83.0,41.186.0,48.127.0,42.191.0,21.205.0"}
P.entries["quest:328"] = {n="隐藏的钥匙",s="在博彩商赫洛德的账本装订处藏着一把小铜钥匙，旁边还有关于一个保险箱的笔记。在库尔森的营地后方的洞穴群深处找到这个容器，也许能揭开列兵索尔森是如何被出卖的真相。",h="在博彩商赫洛德的账本装订处藏着一把小铜钥匙，旁边还有关于一个保险箱的笔记。在库尔森的营地后方的洞穴群深处找到这个容器，也许能揭开列兵索尔森是如何被出卖的真相。",kw={"博彩商赫洛德","铜钥匙","库尔森的营地","列兵索尔森","储藏区","荆棘谷","保险箱"},sec={{t="装订里的秘密",b="搜查博彩商赫洛德的账本并没有直接提到列兵索尔森，但却有了其他发现：一本装订好的书里藏着一把小铜钥匙。文书中的碎片提到在库尔森的营地后方的洞穴群——也就是储藏区——里藏着一个保险箱。打开那个容器或许能揭开索尔森的身份是如何暴露的。"},{t="深入储藏区",b="想要找到这个保险箱，必须深入营地后的洞穴系统。这口箱子又重又厚，上面包着铜边，结构坚固，就放在洞穴里堆叠的板条箱中间。"}},faq={{q="这把铜钥匙是从哪里来的？",a="这把小铜钥匙藏在博彩商赫洛德的一本账簿的装订处，是在检查他的文书时发现的。",al={"钥匙在哪里","我怎么拿到的钥匙","小铜钥匙来源"}},{q="博彩商赫洛德的保险箱在哪里？",a="这个保险箱位于储藏区内，也就是库尔森的营地最深处的那个洞穴群。",al={"保险箱位置","保险箱在哪里","箱子在哪里"}},{q="为什么要寻找赫洛德的保险箱？",a="赫洛德的散乱文件没能解释列兵索尔森的行踪是如何泄露的，但它们提到了一个可能藏有答案的保险箱。",al={"为什么要找保险箱","盒子里有什么","保险箱的目的"}},{q="这一步之前发生了什么？",a="这发生在对博彩商赫洛德的调查之后，当时正在搜寻并查阅他的账簿记录。",al={"上一个任务","哪个任务在前"}}},fp="14,126,24.264.0,23.138.0,35.111.0,42.98.0,33.149.0,27.94.0"}
P.entries["quest:3281"] = {n="被偷走的银币",s="十字路口的加兹罗格派你追回被迅猛龙偷走的军饷银币。关于它们狡猾天性的传闻，将你引向棘齿城南面的迅猛龙巢穴。驻军需要追回军饷。",h="十字路口的加兹罗格派你追回被迅猛龙偷走的军饷银币。关于它们狡猾天性的传闻，将你引向棘齿城南面的迅猛龙巢穴。驻军需要追回军饷。",kw={"贫瘠之地","十字路口","加兹罗格","军饷","迅猛龙巢穴","偷钱的迅猛龙","棘齿城","被偷走的银币"},ang={["class:Hunter"]="身为猎人，你看到贫瘠之地的迅猛龙以复杂的社会群体筑巢生活，还会被闪闪发亮的人造货物吸引。",["faction:Horde"]="身为部落的一员，你知道十字路口会让卫兵领到军饷、吃饱肚子，以守住卡利姆多的边疆。"},sec={{t="野兽劫案",b="加兹罗格需要给十字路口的卫兵发放军饷，可迅猛龙却把钱抢走了。你受命追回被盗的钱币，而不只是惩罚这些野兽。迅猛龙伏击运送军饷的队伍后，加兹罗格最初一心想要复仇。但杀死这群迅猛龙，也无法找回失踪的钱。部落必须查清迅猛龙是如何搬走沉重的钱箱，又把它们带到了哪里。"},{t="迅猛龙巢穴",b="斥候在两座嶙峋的山峰之间发现了一处迅猛龙巢穴，位于棘齿城以南、北方城堡西北。这些生物将完好无损的锁箱拖进了自己的领地，与龙蛋和刚捕杀的猎物一同看守。如今，加兹罗格觉得那些关于迅猛龙狡猾、喜欢囤积物品的传闻似乎是真的。寻常野兽很少会藏起贵重的金属物品。"}},faq={{q="迅猛龙究竟为什么要偷银币？",a="贫瘠之地的迅猛龙有着惊人的狡猾天性，搜集杂物的习性也十分奇特。它们将完好无损的保险箱拖到了迅猛龙巢穴中的群居巢穴里，也许是被箱子的光泽、箱上经过处理的皮革，或是囤积的本能所吸引。",al={"迅猛龙为什么想要银币","迅猛龙为何偷银币","迅猛龙偷钱动机"}},{q="加兹罗格是谁？",a="加兹罗格是一名兽人军官，驻扎在十字路口的主地堡内。他负责治安与后勤，包括应对当地野兽的威胁、半人马的入侵，以及军饷运输受阻等问题。",al={"加兹罗格","被偷走的银币由谁发布","十字路口任务给予者加兹罗格"}},{q="迅猛龙巢穴位于哪里？",a="迅猛龙巢穴位于贫瘠之地东部，棘齿城以南、北方城堡西北。它们的巢穴遍布两座山之间的崎岖通道。",al={"迅猛龙巢穴位置","哪里能找到被偷走的银币","被偷走的银币箱子位置"}},{q="如果无法追回银币，会发生什么？",a="被盗的银币是十字路口卫兵一个月的军饷。没有这笔钱，哨站的守军就得在领不到军饷的情况下继续执勤，而这座饱受野猪人、半人马和联盟袭击者侵扰的堡垒，士气也可能因此受挫。",al={"被偷走的银币为何重要","十字路口卫兵军饷"}},{q="这是一个较长任务链的一部分吗？",a="在寻找藏匿的钱币之前，你必须先为加兹罗格完成迅猛龙的偷袭。在那个任务中，你会清剿袭击第一支运输队的迅猛龙，并查明钱币的藏匿地点。",al={"被偷走的银币前置任务","偷钱的迅猛龙后续任务"}},{q="联盟参与了这次盗窃吗？",a="没有。北方城堡位于迅猛龙巢穴东南方，但实施盗窃的是当地的迅猛龙。它们偷窃和囤积物品的行为，连身经百战的部落指挥官都感到惊讶。",al={"北方城堡偷了银币吗","联盟迅猛龙贫瘠之地"}}},fp="13,198,15.370.0,18.323.0,48.236.0,14.185.0,37.150.0,44.214.0,37.176.0,38.168.0"}
P.entries["quest:329"] = {n="找出内鬼！",s="在赫洛德的保险箱里放着一张潮湿的羊皮纸，上面详细记录了列兵索尔森的日常生活。这封信只留下了一个字母“M”作为署名，暗示着在荆棘谷北部的反抗军营地中混入了一个内奸。这张沾满泥土的字条是写给多伦上尉的。",h="在赫洛德的保险箱里放着一张潮湿的羊皮纸，上面详细记录了列兵索尔森的日常生活。这封信只留下了一个字母“M”作为署名，暗示着在荆棘谷北部的反抗军营地中混入了一个内奸。这张沾满泥土的字条是写给多伦上尉的。",kw={"多伦","赫洛德","沾满泥土的字条","反抗军营地","间谍","荆棘谷","保险箱","索尔森","叛徒"},ang={["faction:Alliance"]="揪出荆棘谷的告密者，可以保护联盟反抗军在当地威胁下维持的岌岌可危的据点。"},sec={{t="队伍中的叛徒",b="打开保险箱，不仅发现了值钱的东西，还有一张追踪列兵索尔森行踪的日程表。上面那难以辨认的字迹记录了他的巡逻路线、同伴，以及他在反抗军营地周围的日常活动，最后只签了一个“-M”。如此详尽的观察记录只能来自与索尔森朝夕相处的人，这表明反抗军营地内部出现了叛徒。"},{t="向多伦报告",b="带着这张潮湿的羊皮纸回到反抗军营地，真相就会大白于多伦上尉面前。凭借这张带有签名的字条，指挥官便掌握了搜查潜伏在营地内部的告密者所需的证据。"}},faq={{q="那张沾满泥土的字条上写了什么？",a="字条上包含了一份列兵索尔森的日常作息表。它勾勒出了他的巡逻地点、他交谈的对象，以及他在营地里如何打发时间，最后以字母“-M”结尾。",al={"沾满泥土的字条内容","字条上写了什么","间谍字条细节"}},{q="这张字条是从哪里来的？",a="这张字条是在解锁赫洛德的保险箱后，在箱子里发现的。",al={"去哪里找沾满泥土的字条","揭露间谍任务起始","如何开启揭露间谍任务"}},{q="谁会收到这张字条？",a="这张字条必须交给荆棘谷北部反抗军营地的多伦上尉。",al={"把沾满泥土的字条交给谁","去哪里上交字条","多伦上尉交任务"}},{q="上报字条后接下来该做什么？",a="在报告此事之后，多伦上尉的调查将继续进行，接下来的任务是“巡逻时刻表”。",al={"下一个任务是什么","揭露间谍之后的下一步","揭露间谍之后"}}},fp="17,214,22.220.0,18.188.1,34.172.0,30.84.0,22.84.0,41.94.0"}
P.entries["quest:33"] = {n="林中的群狼",s="在北郡山谷，伊根·派特斯金纳请你猎杀狼，并把狼肉带给他。他在北郡修道院外等候，尽管卫兵正忙于对付迪菲亚匪徒，日常生计仍得维持。",h="在北郡山谷，伊根·派特斯金纳请你猎杀狼，并把狼肉带给他。他在北郡修道院外等候，尽管卫兵正忙于对付迪菲亚匪徒，日常生计仍得维持。",kw={"修道院","伊根","艾尔文","肉","北郡","皮尔斯金纳","森林狼","狼"},ang={["profession:Cooking"]="身为厨师，你从伊根对狼排的渴望中学到了一条边地常识：猎来的东西，往往也能烹饪食用。",["race:Human"]="作为北郡的一名人类新兵，你会发现，这是你最早能以实际行动帮助巩固暴风城附近边境的方式之一。"},sec={{t="务实的请求",b="伊根·派特斯金纳在北郡修道院的围墙旁等候，对当地的森林狼满怀怒气。治安官玛克布莱德和暴风城卫兵已无多少余力抵御迪菲亚匪徒，保卫修道院。商贩们仍有日常所需，因此伊根请你减少狼的数量，并带回坚韧的狼肉供他烹饪。"},{t="北郡的荒野",b="随着巡逻力量减弱，狼群越来越靠近北郡修道院。暴风城王国兵力不足，也缺乏领导。幼狼和森林狼在修道院的小径与果园间游荡。猎杀它们既能充实伊根的食物储备，也能让附近的道路对见习修士、劳工和新来的守卫更加安全。"}},faq={{q="伊根·派特斯金纳是谁？",a="伊根·派特斯金纳是北郡修道院入口附近的一名猎人兼商贩。他厌恶当地的森林狼，很乐意把它们的肉做成食物吃掉。",al={"伊根 是谁","派特斯金纳","伊根·派特斯金纳"}},{q="伊根为什么想要狼肉？",a="伊根喜欢吃狼排。他会给带来新鲜狼肉的新兵一些实用的入门装备和钱币。",al={"为什么要狼肉","伊根 饿了","伊根 用狼肉做什么"}},{q="狼在哪里？",a="森林狼和幼狼在北郡山谷的田野、山丘与河岸间游荡，尤其常见于修道院的南面和东面。",al={"狼在哪里","狼的位置","寻找狼"}},{q="为什么狼群成了北郡的祸患？",a="巡逻减少，加上迪菲亚匪徒作乱，使北郡的道路和农场失去了抵御野兽的保护。对神职人员和工人而言，没有护送的出行十分危险。",al={"狼为什么攻击","北郡 狼患"}},{q="接取这个任务前，需要先和谁交谈吗？",a="不需要。维里副队长可能会通过一个引荐差事，让新来者去找伊根，但任何来到修道院外与伊根交谈的人，都能直接接到他的狩猎任务。",al={"任务前置条件","前置条件","谁提供这个任务"}},{q="硬狼肉能用于烹饪配方吗？",a="伊根打算亲自烹饪这些肉。初学烹饪的人常会学到，在艾尔文森林采集的狼肉是野外烹饪的基本食材。",al={"硬狼肉烹饪","玩家能否烹饪狼肉"}}},fx={["12d6ae41"]={q="硬狼肉有什么用？",a="伊根·派特斯金纳打算把它做成狼肉排，供自己享用。尽管他厌恶那些在山谷里游荡的野兽，却十分喜爱它们的肉，乐意用实用的装备换取任何人送来的食材。",al={"硬狼肉有什么用","为什么需要硬狼肉","硬狼肉用途"}},acd05579={q="为什么有狼在北郡游荡？",a="幼狼和森林狼本就会在北郡山谷林木茂盛的边缘地带与开阔草地上游荡。然而，当地的暴风城卫兵正忙于应对迪菲亚潜行者日益加剧的威胁，这些食肉野兽便无人遏制，逐渐逼近了修道院。",al={"这里为什么有狼","北郡森林狼","北郡的狼"}}},fp="24,189,19.323.0,19.318.0,25.158.0,30.109.0,29.128.0,39.151.0,53.160.0,44.149.0"}
P.entries["quest:330"] = {n="巡逻时间表",s="在发现了一封只留有首字母缩写的罪证信息后，多伦上尉试图找出反抗军营地内的叛徒。通过对比值勤名册，值勤记录可以揭示上周是谁与列兵索尔森一起执行巡逻任务。",h="在发现了一封只留有首字母缩写的罪证信息后，多伦上尉试图找出反抗军营地内的叛徒。通过对比值勤名册，值勤记录可以揭示上周是谁与列兵索尔森一起执行巡逻任务。",kw={"塞斯曼下士","库尔森","多伦上尉","巡逻时间表","列兵索尔森","反抗军营地","荆棘谷"},sec={{t="名册中的线索",b="找回的字条上只写着字母M，仅凭这一点很难揭露那个协助库尔森部队的同谋。然而，作者提到在上周一直与列兵索尔森一起执行定期的巡逻任务。多伦上尉让你穿过反抗军营地去和负责维护值勤记录的士兵塞斯曼下士谈谈，以查明是谁和索尔森一起执行任务。"},{t="记录显示的内容",b="查看官方记录证实，在过去的一整周里，列兵默尔被分配了与索尔森完全相同的值勤时间和路线。这一发现揭露了默尔就是向库尔森的人提供情报的告密者。身份一旦暴露，叛徒便逃离营地，向着暮色森林的北部边界逃去。"}},faq={{q="为什么多伦上尉要派你去找塞斯曼下士？",a="塞斯曼下士负责反抗军营地的值勤记录和时间表。因为那封找回的字条提到曾与列兵索尔森一起走过固定的路线，所以塞斯曼的记录可以查明是谁被指派与他一同值勤。",al={"为什么要找塞斯曼谈话","塞斯曼下士的职责","塞斯曼的巡逻时间表"}},{q="在找回的字条中发现了什么线索？",a="信息上只签了字母M，并明确提到其作者在上周与列兵索尔森走过相同的巡逻路线。",al={"字条线索","信件线索","谁在字条上签名"}},{q="这项调查在哪里进行？",a="这项调查完全在荆棘谷北部的反抗军营地内进行，需要在多伦上尉和塞斯曼下士之间往返。",al={"巡逻时间表在哪里","巡逻时间表位置"}},{q="是什么事件引发了这次调查？",a="在“间谍现形！”任务中，你给多伦上尉带去了从赫洛德的贵重物品中发现的泥泞字条，上面只签了一个首字母。",al={"前置任务","巡逻时间表任务的起因"}}},fp="16,228,21.317.0,21.225.1,55.186.0,41.131.0,35.124.0,33.147.0"}
P.entries["quest:3301"] = {n="茉拉·符文图腾",s="你带着一枚来自贫瘠之地的钳嘴龟壳，跨海前往银松森林，将它交给茉拉·符文图腾。壳中奇异的生命力或许能帮助这位牛头人治疗者援助被遗忘者。",h="你带着一枚来自贫瘠之地的钳嘴龟壳，跨海前往银松森林，将它交给茉拉·符文图腾。壳中奇异的生命力或许能帮助这位牛头人治疗者援助被遗忘者。",kw={"贫瘠之地","茉拉·符文图腾","绿洲","瑟伯切尔","银松森林","钳嘴龟壳","图加·符文图腾"},ang={["class:Druid"]="作为德鲁伊，你研究自然界中不寻常的复苏现象，即便它们源于奇异的变异，也希望借此让受创的土地恢复平衡。",["faction:Horde"]="作为部落的一员，你从卡利姆多的守护者与洛丹伦的被遗忘者之间的合作中，看到了部落日益紧密的纽带。",["race:Tauren"]="作为牛头人，你看到符文图腾氏族滋养自然的奉献精神跨越海洋，延伸到了银松森林枯萎的林间。",["race:Undead"]="作为亡灵，你或许认为瑟伯切尔周围的森林早已被腐朽与枯萎吞噬，但茉拉·符文图腾这样的牛头人德鲁伊仍在寻求让它重获新生。"},sec={{t="跨海之桥",b="图加·符文图腾在调查贫瘠之地绿洲周围受魔法影响的野生动物时，发现变异的钳嘴龟有些异样。尽管受到腐化，它们的壳仍涌动着顽强的能量。他请你带上一枚壳，穿过无尽之海，送给驻扎在东部王国的同族茉拉·符文图腾。"},{t="援助被遗忘者",b="茉拉·符文图腾身在瑟伯切尔，那是被遗忘者位于银松森林的一处前哨站。她历经艰辛来到这里，帮助部落的新盟友净化并复苏他们那片衰败、遭受枯萎侵蚀的林地。茉拉希望，壳内的微光与经久不灭的生命火花能揭示让北方大陆重焕生机的方法。"}},faq={{q="茉拉·符文图腾是谁？",a="茉拉·符文图腾是一位牛头人德鲁伊，也是图加·符文图腾的同族。她远渡重洋，在瑟伯切尔落脚，研究拯救垂死森林的方法，以此援助被遗忘者。",al={"茉拉","茉拉是谁","符文图腾 银松森林"}},{q="茉拉·符文图腾在哪里？",a="茉拉·符文图腾位于东部王国的瑟伯切尔，那是银松森林中部道路旁的一座被遗忘者城镇。",al={"茉拉位置","茉拉在哪里","寻找茉拉·符文图腾"}},{q="图加为什么要把一枚钳嘴龟壳送到银松森林？",a="贫瘠之地绿洲附近的变异钳嘴龟，其壳中显露出不自然的生命力，还散发着内在的微光。图加相信，研究这股顽强的生命力，或许能让茉拉找到治愈银松森林那遭受枯萎侵蚀、濒临死亡的生态的方法。",al={"为何送壳","钳嘴龟壳用途","茉拉为何需要壳"}},{q="牛头人为什么要治愈被遗忘者的土地？",a="牛头人将滋养和修复自然视为神圣的职责。茉拉看到银松森林正在腐朽、枯萎，希望运用大地的疗愈传统，帮助部落的新盟友，让土壤恢复平衡。",al={"牛头人帮助亡灵","为何治愈银松森林","银松森林的德鲁伊"}},{q="这个任务如何将贫瘠之地与银松森林联系起来？",a="这枚壳的旅程串联起部落早期的领地，带你从卡利姆多的平原来到东部王国的森林。",al={"贫瘠之地到银松森林的任务","跨大陆任务"}},{q="把壳交给茉拉后会发生什么？",a="茉拉被壳内久久不散的微光深深吸引，决心仔细研究它，为银松森林遭受枯萎侵蚀的林地寻找疗愈之法。",al={"茉拉后续","接下来是什么"}}},fp="14,107,20.296.0,19.320.0,22.172.0,32.121.0,55.204.0,49.218.0,54.132.0,41.147.0"}
